Object.assign(window.TEM8_DICTIONARY, {"unnerving":{"media":{"uk":"media/uk/unnerving__gb_1.mp3","us":"media/us/unnerving__us_1.mp3"},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"令人担心的；令人不舒服的","en":"If you describe something as unnerving, you mean that it makes you feel worried or uncomfortable.","ex":{"en":"It is very unnerving to find out that someone you see every day is carrying a potentially deadly virus.","cn":"发现朝夕相处的人竟携带着一种可能致命的病毒是一件令人很不安的事情。"}}]},"examples":[{"en":"He was unnerved by the way Sylvia kept staring at him.","cn":""}],"oxford":{"phon":"ˌʌnˈnɜːvɪŋ","pos":"adjective","senses":[{"en":"making somebody feel nervous or frightened","cn":"使紧张；使恐惧；使丧失信心","ex":{"en":"an unnerving experience","cn":"可怕的经历"}}]}},"use":{"media":{"uk":"media/uk/use__gb_1.mp3","us":"media/us/use__us_1.mp3"},"oxford":{"phon":"juːz","pos":"verb","senses":[{"en":"to do something with a machine, a method, an object, etc. for a particular purpose","cn":"使用；利用；运用","g":"[transitive]","ex":{"en":"Can I use the photocopier?","cn":"我能用一下复印机吗？"}},{"en":"to take a particular amount of a liquid, substance, etc. in order to achieve or make something","cn":"消耗","g":"[transitive]","ex":{"en":"This type of heater uses a lot of electricity.","cn":"这种加热器耗电量很大。"}},{"en":"to say or write particular words or a particular type of language","cn":"说，写，使用（词语或语言）","g":"[transitive]","ex":{"en":"The poem uses simple language.","cn":"这首诗用语简单。"}},{"en":"to be kind, friendly, etc. to somebody with the intention of getting an advantage for yourself from them","cn":"（施展手段）利用（别人）","g":"[transitive]","lab":"disapproving","ex":{"en":"Can't you see he's just using you for his own ends?","cn":"你难道看不出他在利用你谋求私利吗？"}},{"en":"to take illegal drugs","cn":"吸（毒）；服用（毒品）","g":"[transitive, intransitive]","lab":"slang","ex":{"en":"Most of the inmates have used drugs at some point in their lives.","cn":"这些囚犯大多数在人生的某个阶段服用过毒品。"}},{"en":"the act of using something; the state of being used","cn":"用；使用；得到利用","g":"[uncountable, singular]","lab":"formal","ex":{"en":"A ban was imposed on the use of chemical weapons.","cn":"化学武器已被禁止使用。"},"pos":"noun"},{"en":"a purpose for which something is used; a way in which something is or can be used","cn":"用途；功能；用法","g":"[countable, uncountable]","ex":{"en":"The plant has various medical uses.","cn":"这种植物有多种药用价值。"},"pos":"noun"},{"en":"the right or opportunity to use something, for example something that belongs to somebody else","cn":"使用权；使用的机会","g":"[uncountable]","ex":{"en":"I have the use of the car this week.","cn":"这辆汽车本周归我使用。"},"pos":"noun"},{"en":"the ability to use your mind or body","cn":"运用头脑（或身体）的能力；功能","g":"[uncountable]","ex":{"en":"He lost the use of his legs (= became unable to walk) in an accident.","cn":"他在一次事故中失去了双腿的功能。"},"pos":"noun"},{"en":"a particular word or phrase, used with a particular meaning","cn":"（单词或短语的）用法","g":"[countable]","ex":{"en":"The phrase ‘all told’ comes from an old use of the verb ‘tell’, meaning ‘to count’.","cn":"短语 all told（合计）来自动词 tell 的一个古老用法，意思是“计算”。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"用；使用；应用；运用","en":"If you use something, you do something with it in order to do a job or to achieve a particular result or effect.","ex":{"en":"Trim off the excess pastry using a sharp knife","cn":"用一把快刀切去多余的饼皮。"}},{"pos":"VERB 动词","cn":"耗尽；耗掉","en":"If you use a supply of something, you finish it so that none of it is left.","ex":{"en":"You used all the ice cubes and didn't put the ice trays back","cn":"你把所有的冰块都用完了，又不把冰格放回去。"}},{"pos":"VERB 动词","cn":"服（药，尤指毒品）","en":"If someone uses drugs, they take drugs regularly, especially illegal ones.","ex":{"en":"He denied he had used drugs","cn":"他否认自己吸过毒。"}},{"pos":"VERB 动词","cn":"用（洗手间或卫生间）（礼貌说法）","en":"You can say that someone uses the toilet or bathroom as a polite way of saying that they go to the toilet.","ex":{"en":"Wash your hands after using the toilet","cn":"便后要洗手。"}},{"pos":"VERB 动词","cn":"使用（单词或表达方式）","en":"If you use a particular word or expression, you say or write it, because it has the meaning that you want to express.","ex":{"en":"The judge liked using the word 'wicked' of people he had sent to jail","cn":"这个法官喜欢使用“邪恶”一词来形容被他判罪入狱的人。"}},{"pos":"VERB 动词","cn":"用（名字）；自称","en":"If you use a particular name, you call yourself by that name, especially when it is not the name that you usually call yourself.","ex":{"en":"Now I use a false name if I'm meeting people for the first time","cn":"现在和初次见面的人交往时我会用假名。"}},{"pos":"VERB 动词","cn":"(为自身利益)利用(别人)","en":"If you say that someone uses people, you disapprove of them because they make others do things for them in order to benefit or gain some advantage from it, and not because they care about the other people.","ex":{"en":"Be careful she's not just using you","cn":"当心她不只是在利用你。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"用；使用；应用；运用","en":"Your use of something is the action or fact of your using it.","ex":{"en":"The treatment does not involve the use of any artificial drugs.","cn":"这种治疗不会使用任何人工合成药物。"}},{"pos":"N-SING 单数名词","cn":"需要；功能；使用价值","en":"If you have a use for something, you need it or can find something to do with it.","ex":{"en":"You will no longer have a use for the magazines","cn":"你再也用不着这些杂志了。"}},{"pos":"N-VAR 可变名词","cn":"用途；用处","en":"If something has a particular use, it is intended for a particular purpose.","ex":{"en":"Infrared detectors have many uses","cn":"红外探测器有多种用途。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"使用权；运用能力","en":"If you have the use of something, you have the permission or ability to use it.","ex":{"en":"She will have the use of the car one night a week.","cn":"她每周有一个晚上会用车。"}},{"pos":"N-COUNT 可数名词","cn":"（单词的）意义，用法","en":"A use of a word is a particular meaning that it has or a particular way in which it can be used.","ex":{"en":"There are new uses of words coming in and old uses dying out.","cn":"单词总有新用法出现，也有旧用法慢慢被淘汰。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（名字的）使用","en":"Your use of a particular name is the fact of your calling yourself by it.","ex":{"en":"Police have been hampered by Mr Urquhart's use of bogus names.","cn":"厄克特先生使用了假名，警方的调查因此受阻。"}},{"pos":"PHRASE 短语","cn":"供…使用","en":"If something is for the use of a particular person or group of people, it is for that person or group to use.","ex":{"en":"The leisure facilities are there for the use of guests","cn":"这些休闲设施是供客人使用的。"}},{"pos":"PHRASE 短语","cn":"有好处","en":"If you say that being something or knowing someone has its uses, you mean that it makes it possible for you to do what you otherwise would not be able to do.","ex":{"en":"Being a hospital Sister had its uses.","cn":"在医院当护士有它的好处。"}},{"pos":"PHRASE 短语","cn":"在使用/不再使用","en":"If something such as a technique, building, or machine is in use, it is used regularly by people. If it has gone out of use, it is no longer used regularly by people.","ex":{"en":"...the methods of making Champagne which are still in use today","cn":"至今仍在用的香槟酿制法"}},{"pos":"PHRASE 短语","cn":"使用；利用","en":"If you make use of something, you do something with it in order to do a job or achieve a particular result or effect.","ex":{"en":"Not all nursery schools make use of the opportunities open to them.","cn":"并不是所有的托儿所都能抓住他们面临的机会。"}},{"pos":"PHRASE 短语","cn":"没有用处；无益","en":"You use expressions such as it's no use ,there's no use, and what's the use to indicate that a particular action will not achieve anything.","ex":{"en":"It's no use arguing with a drunk","cn":"跟一个醉汉争论是没有用处的。"}},{"pos":"PHRASE 短语","cn":"没用；行不通","en":"If you say it's no use, you mean that you have failed to do something and realize that it is useless to continue trying because it is impossible.","ex":{"en":"It's no use. Let's hang up and try for a better line.","cn":"打不通。挂掉吧，找一条更好的线打吧。"}},{"pos":"PHRASE 短语","cn":"有用/没用","en":"If something or someone is of use, they are useful. If they are no use, they are not at all useful.","ex":{"en":"The contents of this booklet should be of use to all students","cn":"这本小册子的内容应该会对所有的学生都有用处。"}}]},"examples":[{"en":"‘Why don't you want to see him again?’ ‘Oh, use your head!’ “","cn":"你为什么不愿再见到他？” “唔，你好好想想吧！”"},{"en":"She'll be able to put her languages to good use in her new job.","cn":"她在新工作中应该可以好好运用她会的各种语言。"}]},"under":{"media":{"uk":"media/uk/under__gb_1.mp3","us":"media/us/under__us_1.mp3"},"oxford":{"phon":"ˈʌndə(r)","pos":"preposition","senses":[{"en":"in, to or through a position that is below something","cn":"在（或到、通过）…下面","ex":{"en":"Have you looked under the bed?","cn":"你看了床底下没有？"}},{"en":"below the surface of something; covered by something","cn":"在…表面下；由…覆盖着","ex":{"en":"The boat lay under several feet of water.","cn":"那条船沉在水下好几英尺处。"}},{"en":"less than; younger than","cn":"少于；小于；不足；比…年轻","ex":{"en":"an annual income of under £10 000","cn":"不到 1 万英镑的年收入"}},{"en":"affected by something","cn":"由…造成；受…影响","ex":{"en":"The wall collapsed under the strain.","cn":"墙壁因承受不了重压而坍塌了。"}},{"en":"used to say who or what controls, governs or manages somebody/something","cn":"由…控制（或管理、经营）","ex":{"en":"The country is now under martial law.","cn":"这个国家目前在戒严中。"}},{"en":"according to an agreement, a law or a system","cn":"根据，按照（协议、法律或制度）","ex":{"en":"A man was detained under the Mental Health Act.","cn":"根据《精神卫生法》，一名男子被拘留。"}},{"en":"experiencing a particular process","cn":"在…过程中","ex":{"en":"The hotel is still under construction.","cn":"旅馆还在兴建中。"}},{"en":"using a particular name","cn":"用，以（某一名字）","ex":{"en":"She also wrote under the pseudonym of Barbara Vine.","cn":"她还用芭芭拉·瓦因的化名从事写作。"}},{"en":"found in a particular part of a book, list, etc.","cn":"在…项下；在（书等中的）某部分","ex":{"en":"If it's not under ‘sports’, try looking under ‘games’.","cn":"如果在“体育运动”项下查不到，就试试“游戏”项吧。"}},{"en":"below something","cn":"在下面","ex":{"en":"He pulled up the covers and crawled under.","cn":"他掀开被子钻到里面。"},"pos":"adverb"},{"en":"below the surface of water","cn":"在水下","ex":{"en":"She took a deep breath and stayed under for more than a minute.","cn":"她深吸了一口气，然后潜水一分多钟。"},"pos":"adverb"},{"en":"less; younger","cn":"少于；小于；较年轻","ex":{"en":"prices of ten dollars and under","cn":"不高于十美元的价格"},"pos":"adverb"},{"en":"in or into an unconscious state","cn":"在昏迷中；陷入昏迷状态","ex":{"en":"He felt himself going under.","cn":"他觉得自己将要昏厥。"},"pos":"adverb"},{"en":"below","cn":"在下面；在…之下","ex":{"en":"undergrowth","cn":"下木层"},"pos":"prefix"},{"en":"lower in age or rank","cn":"（年龄）较小；（级别）较低","ex":{"en":"the under-fives","cn":"五岁以下的儿童"},"pos":"prefix"},{"en":"not enough","cn":"不足；未","ex":{"en":"underripe","cn":"未成熟的"},"pos":"prefix"},{"en":"lower","cn":"较低的；下方的","ex":{"en":"the under layer","cn":"下面的一层"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"PREP 介词","cn":"在…下面；在…下方；在…底下","en":"If a person or thing is under something, they are at a lower level than that thing, and may be covered or hidden by it.","ex":{"en":"They found a labyrinth of tunnels under the ground.","cn":"他们发现了一处迷宫似的地道。"}},{"pos":"PREP 介词","cn":"在（水面）之下；在（水）里","en":"In a place such as a sea, river, or swimming pool, if someone or something is under the water, they are fully in the water and covered by it.","ex":{"en":"They said he'd been held under the water and drowned","cn":"他们说他被按到水里淹死了。"}},{"pos":"PREP 介词","cn":"经由…的底下","en":"If you go under something, you move from one side to the other of something that is at a higher level than you.","ex":{"en":"He went under a brick arch","cn":"他穿过一个砖砌的拱门。"}},{"pos":"PREP 介词","cn":"在（尤指一层衣服）的里面（或底下)","en":"Something that is under a layer of something, especially clothing, is covered by that layer.","ex":{"en":"I was wearing two sweaters under the green army jacket","cn":"我在绿军装里套了两件毛线衫。"}},{"pos":"PREP 介词","cn":"受…影响；经历","en":"You can use under before a noun to indicate that a person or thing is being affected by something or is going through a particular process.","ex":{"en":"...fishermen whose livelihoods are under threat","cn":"生计受到威胁的渔夫"}},{"pos":"PREP 介词","cn":"在（…情况或条件）下","en":"If something happens under particular circumstances or conditions, it happens when those circumstances or conditions exist.","ex":{"en":"His best friend was killed by police under extremely questionable circumstances","cn":"他最好的朋友在极其可疑的情况下被警察打死了。"}},{"pos":"PREP 介词","cn":"根据，按照，依照（法律、协定、制度等）","en":"If something happens under a law, agreement, or system, it happens because that law, agreement, or system says that it should happen.","ex":{"en":"Under law, your employer has the right to hire a temporary worker to replace you","cn":"根据法律规定，你的雇主有权雇用一名临时工来代替你。"}},{"pos":"PREP 介词","cn":"在（…领导）下；在（…当政）期间；在（…统治）之下","en":"If something happens under a particular person or government, it happens when that person or government is in power.","ex":{"en":"There would be no new taxes under his leadership.","cn":"在他主政期间不会增加新税种。"}},{"pos":"PREP 介词","cn":"在…指导下(学习)；在…手下(工作)","en":"If you study or work under a particular person, that person teaches you or tells you what to do.","ex":{"en":"Kiefer was just one of the artists who had studied under Beuys in the early Sixties","cn":"基弗只是60年代早期师从博伊斯的艺术家之一。"}},{"pos":"PREP 介词","cn":"用（…之名）；以（…的名义）；假借（…之名）","en":"If you do something under a particular name, you use that name instead of your real name.","ex":{"en":"Were any of your books published under the name Amanda Fairchild?","cn":"你们所出版的书里有署名为阿曼达·费尔柴尔德的吗？"}},{"pos":"PREP 介词","cn":"在…之下；在…部分里","en":"You use under to say which section of a list, book, or system something is in.","ex":{"en":"This study is described under 'General Diseases of the Eye'","cn":"“普通眼科疾病”这一部分里对该项研究作了描述。"}},{"pos":"PREP 介词","cn":"（年龄或数量）不足，低于，在…以下","en":"If something or someone is under a particular age or amount, they are less than that age or amount. →see: ; under wraps→see: ;","ex":{"en":"...jobs for those under 65","cn":"适合65岁以下人群从事的工作"}}]},"examples":[{"en":"If it's not under ‘sports’, try looking under ‘games’.","cn":"如果在“体育运动”项下查不到，就试试“游戏”项吧。"},{"en":"Under its new conductor, the orchestra has established an international reputation.","cn":"在新指挥的领导下，这个乐团建立了国际声誉。"}]},"uphill":{"media":{"uk":"media/uk/uphill__gb_1.mp3","us":"media/us/uphill__us_1.mp3"},"oxford":{"phon":"ˌʌpˈhɪl","pos":"adjective","senses":[{"en":"sloping upwards","cn":"上坡的","ex":{"en":"an uphill climb/slope","cn":"向上的攀爬；上坡"}},{"en":"an argument or a struggle that is difficult to win and takes a lot of effort over a long period of time","cn":"漫长而艰难的，费力的（战斗、斗争、任务等）","ex":{"en":"He faces an uphill struggle to be fit in time for the championships.","cn":"为了及时适应锦标赛，他面临着一场艰苦的斗争。"}},{"en":"towards the top of a hill or slope","cn":"向山上；朝上坡方向","ex":{"en":"We cycled uphill for over an hour.","cn":"我们骑自行车爬了一个多小时的坡。"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"靠山顶；上坡","en":"If something or someone is uphill or is moving uphill, they are near the top of a hill or are going up a slope.","ex":{"en":"He had been running uphill a long way","cn":"他已经跑了一段很长的上坡路。"}},{"pos":"ADJ 形容词","cn":"荆棘满途的；艰苦卓绝的；崎岖曲折的","en":"If you refer to something as an uphill struggle or an uphill battle, you mean that it requires a great deal of effort and determination, but it should be possible to achieve it.","ex":{"en":"It had been an uphill struggle to achieve what she had wanted","cn":"她历尽坎坷才达到目的。"}}]},"examples":[{"en":"We cycled uphill for over an hour.","cn":"我们骑自行车爬了一个多小时的坡。"},{"en":"The last part of the race is all uphill.","cn":"赛跑的最后一段全是上坡路。"}]},"unaffiliated":{"media":{"uk":"media/uk/unaffiliated__gb_1.mp3","us":"media/us/unaffiliated__us_1.mp3"},"oxford":{"phon":"ˌʌnəˈfɪlieɪtɪd","pos":"adjective","senses":[{"en":"not belonging to or connected with a political party or a large organization","cn":"独立的；无党派（或组织）的","ex":{"en":"unaffiliated voters","cn":"无党派选民"}}]}},"unsurpassed":{"media":{"uk":"media/uk/unsurpassed__gb_1.mp3","us":"media/us/unsurpassed__us_1.mp3"},"oxford":{"phon":"ˌʌnsəˈpɑːst","pos":"adjective","senses":[{"en":"better or greater than any other","cn":"无法超越的；无与伦比的"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"无与伦比的；无可匹敌的；超凡绝伦的","en":"If you describe something as unsurpassed, you are emphasizing that it is better or greater than anything else of its kind.","ex":{"en":"The quality of Smallbone furniture is unsurpassed.","cn":"斯莫尔本恩家具品质超凡。"}}]},"examples":[{"en":"an unsurpassed knowledge of Greek history","cn":"对希腊历史的了解无出其右"}]},"unchanging":{"oxford":{"phon":"ʌnˈtʃeɪndʒɪŋ","pos":"adjective","senses":[{"en":"that always stays the same and does not change","cn":"永恒的；不变的","ex":{"en":"unchanging truths","cn":"永恒的真理"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"永不改变的；恒定的","en":"Something that is unchanging always stays the same.","ex":{"en":"...eternal and unchanging truths","cn":"永恒不变的真理"}}]},"media":{"uk":"media/uk/unchanging__gb_1.mp3","us":"media/us/unchanging__us_1.mp3"},"examples":[{"en":"unchanging truths","cn":"永恒的真理"}]},"union":{"media":{"uk":"media/uk/union__gb_1.mp3","us":"media/us/union__us_1.mp3"},"oxford":{"phon":"ˈjuːniən","pos":"noun","senses":[{"en":"an organization of workers, usually in a particular industry, that exists to protect their interests, improve conditions of work, etc.","cn":"工会","g":"[countable]","lab":"British English also","ex":{"en":"I've joined the union.","cn":"我已经加入工会。"}},{"en":"an association or a club for people or organizations with the same interest","cn":"协会；联合会；会社；俱乐部","g":"[countable]","ex":{"en":"the Scottish Rugby Union","cn":"苏格兰橄榄球协会"}},{"en":"a group of states or countries that have the same central government or that agree to work together","cn":"同盟；联盟；联邦","g":"[countable]","ex":{"en":"the former Soviet Union","cn":"苏维埃联盟"}},{"en":"the US (used especially at the time of the Civil War)","cn":"（尤指内战时期的）美利坚合众国，美国","g":"[singular]","ex":{"en":"the Union and the Confederacy","cn":"合众国与南部邦联"}},{"en":"the act of joining two or more things together; the state of being joined together","cn":"联合；结合；合并","g":"[uncountable, singular]","ex":{"en":"a meeting to discuss economic and currency union","cn":"商讨经济和货币联盟的会议"}},{"en":"a marriage","cn":"结为夫妻；婚姻","g":"[countable]","lab":"old-fashioned or formal","ex":{"en":"Their union was blessed with six children.","cn":"他们婚后幸得六个儿女。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"工会","en":"A union is a workers' organization which represents its members and which aims to improve things such as their working conditions and pay.","ex":{"en":"I feel that women in all types of employment can benefit from joining a union.","cn":"我认为女性无论从事什么工作，加入工会都是有好处的。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"联合；合并","en":"When the union of two or more things occurs, they are joined together and become one thing.","ex":{"en":"In 1918 the Romanian majority in this former tsarist province voted for union with Romania.","cn":"1918年，这个前沙皇统治的省份中占了多数的罗马尼亚人投票赞成与罗马尼亚合并。"}},{"pos":"N-SING 单数名词","cn":"联盟；联合体","en":"When two or more things, for example countries or organizations, have been joined together to form one thing, you can refer to them as a union .","ex":{"en":"Tanzania is a union of the states of Tanganyika and Zanzibar.","cn":"坦桑尼亚是坦噶尼喀和桑给巴尔两个政体组成的联合国家。"}},{"pos":"N-COUNT 可数名词","cn":"婚姻","en":"The marriage of two people is sometimes referred to as a union .","ex":{"en":"Even Louis began to think their union was not blessed in the eyes of God.","cn":"就连路易斯都开始认为他们的婚姻并没有受到上帝的祝福。"}},{"pos":"N-IN-NAMES 名称名词","cn":"（用于名称中）俱乐部，协会，联合会","en":"Union is used in the name of some clubs, societies, and organizations.","ex":{"en":"The naming of stars is at the discretion of the International Astronomical Union.","cn":"给星体命名是由国际天文学联合会决定的。"}}]},"examples":[{"en":"the State of the Union address by the President","cn":"美国总统向国会发表的国情咨文"},{"en":"a summit to discuss economic and monetary union","cn":"商讨经济和金融合作的高峰会议"}]},"uncontrolled":{"oxford":{"phon":"ˌʌnkənˈtrəʊld","pos":"adjective","senses":[{"en":"that somebody cannot control or stop","cn":"抑制不住的；无法制止的","ex":{"en":"uncontrolled anger","cn":"克制不住的愤怒"}},{"en":"that is not limited or managed by law or rules","cn":"不受法律（或规则）制约的；无序的","ex":{"en":"the uncontrolled growth of cities","cn":"城市的无规划发展"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"控制不住的；未受控制的；不加约束的","en":"If you describe someone's behaviour as uncontrolled, you mean they appear unable to stop it or to make it less extreme.","ex":{"en":"His uncontrolled behavior disturbed the entire class","cn":"他放肆的举动扰乱了全班的秩序。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（形势或活动）不受控制的，未加制止的","en":"If a situation or activity is uncontrolled, no-one is controlling it or preventing it from continuing or growing.","ex":{"en":"The capital, Nairobi, is choking on uncontrolled immigration.","cn":"移民纷纷涌入首都内罗毕，人满为患。"}}]},"media":{"uk":"media/uk/uncontrolled__gb_1.mp3","us":"media/us/uncontrolled__us_1.mp3"},"examples":[{"en":"The thoughts rushed into my mind uncontrolled.","cn":"各种想法如潮水般涌上我的心头。"},{"en":"uncontrolled dumping of toxic wastes","cn":"有毒废弃物的胡乱弃置"}]},"undergrowth":{"media":{"uk":"media/uk/undergrowth__gb_1.mp3","us":"media/us/undergrowth__us_1.mp3"},"oxford":{"phon":"ˈʌndəɡrəʊθ","pos":"noun","senses":[{"en":"a mass of bushes and plants that grow close together under trees in woods and forests","cn":"下木层","ex":{"en":"They used their knives to clear a path through the dense undergrowth.","cn":"他们用刀在浓密的灌木丛中劈开一条小路。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"下层灌丛；矮树丛；林下植物","en":"Undergrowth consists of bushes and plants growing together under the trees in a forest.","ex":{"en":"...plunging through the undergrowth.","cn":"一头钻过矮树丛"}}]},"examples":[{"en":"They used their knives to clear a path through the dense undergrowth.","cn":"他们用刀在浓密的灌木丛中劈开一条小路。"},{"en":"The murder weapon was found concealed in undergrowth.","cn":"杀人凶器被发现藏在灌木丛中。"}]},"urban":{"media":{"uk":"media/uk/urban__gb_1.mp3","us":"media/us/urban__us_1.mp3"},"oxford":{"phon":"ˈɜːbən","pos":"adjective","senses":[{"en":"connected with a town or city","cn":"城市的；都市的；城镇的","g":"[usually before noun]","ex":{"en":"urban and rural communities","cn":"城市及农村社区"}},{"en":"connected with types of music such as rhythm and blues, reggae, soul, etc. that are played by black musicians","cn":"都市音乐的，城市音乐的（如节奏布鲁斯、雷鬼乐、灵乐等）","g":"[only before noun]","ex":{"en":"today’s urban music scene","cn":"当今的城市音乐圈"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"城市的；城镇的；都市的","en":"Urban means belonging to, or relating to, a town or city.","ex":{"en":"Most of the population is an urban population","cn":"绝大多数人口都是城镇居民。"}}]},"examples":[{"en":"efforts to control urban sprawl (= the spread of city buildings into the countryside)","cn":"控制城市向乡村延伸的努力"},{"en":"damage to both urban and rural environments","cn":"对城乡环境的破坏"}]},"undermines":{"oxford":{"phon":"ˌʌndəˈmaɪn","pos":"verb","senses":[{"en":"to make sth, especially sb's confidence or authority, gradually weaker or less effective","cn":"逐渐削弱（信心、权威等）；使逐步减少效力"},{"en":"to make sth weaker at the base, for example by digging under it","cn":"从根基处破坏；挖 … 的墙脚"}]},"media":{"uk":"media/uk/undermine__gb_1.mp3","us":"media/us/undermine__us_1.mp3"}},"urge":{"media":{"uk":"media/uk/urge__gb_1.mp3","us":"media/us/urge__us_1.mp3"},"oxford":{"phon":"ɜːdʒ","pos":"verb","senses":[{"en":"to advise or try hard to persuade somebody to do something","cn":"敦促；催促；力劝","ex":{"en":"If you ever get the chance to visit this place, I strongly urge you to do so.","cn":"你如果有机会来这里，我强烈建议你一定要来。"}},{"en":"to recommend something strongly","cn":"大力推荐；竭力主张","ex":{"en":"The situation is dangerous and the UN is urging caution.","cn":"局势岌岌可危，联合国力主谨慎行事。"}},{"en":"to make a person or an animal move more quickly and/or in a particular direction, especially by pushing or forcing them","cn":"驱赶；鞭策","lab":"formal","ex":{"en":"He urged his horse forward.","cn":"他策马前行。"}},{"en":"a strong desire to do something","cn":"强烈的欲望；冲动","ex":{"en":"Freud claimed that this behaviour was caused by the repression of sexual urges.","cn":"弗洛伊德声称这种行为是性压抑造成的。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"敦促；力劝","en":"If you urge someone to do something, you try hard to persuade them to do it.","ex":{"en":"They urged parliament to approve plans for their reform programme","cn":"他们敦促议会批准他们的改革方案。"}},{"pos":"VERB 动词","cn":"推；拉；催促","en":"If you urge someone somewhere, you make them go there by touching them or talking to them.","ex":{"en":"He slipped his arm around her waist and urged her away from the window","cn":"他揽住她的腰，拉着她离开了窗边。"}},{"pos":"VERB 动词","cn":"竭力主张；强烈要求","en":"If you urge a course of action, you strongly advise that it should be taken.","ex":{"en":"He urged restraint on the security forces","cn":"他力主对安全部队设限。"}},{"pos":"N-COUNT 可数名词","cn":"强烈的欲望；冲动；迫切的要求","en":"If you have an urge to do or have something, you have a strong wish to do or have it.","ex":{"en":"He had an urge to open a shop of his own","cn":"他很想自己开一家店。"}},{"pos":"","cn":"","en":"相关词组：urge on"}]},"examples":[{"en":"‘Why not give it a try?’ she urged (him). “","cn":"为什么不试一试呢？”她敦促（他）道。"},{"en":"The report urged that all children be taught to swim.","cn":"这份报告呼吁给所有的儿童教授游泳。"}]},"unqualified":{"media":{"uk":"media/uk/unqualified__gb_1.mp3","us":"media/us/unqualified__us_1.mp3"},"oxford":{"phon":"ˌʌnˈkwɒlɪfaɪd","pos":"adjective","senses":[{"en":"not having the right knowledge, experience or qualifications to do something","cn":"不合格的；没资格的","ex":{"en":"an unqualified instructor","cn":"不合格的教员"}},{"en":"complete; not limited by any negative qualities","cn":"完全的；绝对的；无保留的；无限制条件的","g":"[usually before noun]","ex":{"en":"The event was not an unqualified success.","cn":"这件事并非百分之百的成功。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"没资格的；资格不够的；不合格的","en":"If you are unqualified, you do not have any qualifications, or you do not have the right qualifications for a particular job.","ex":{"en":"She was unqualified for the job","cn":"她没资格做这份工作。"}},{"pos":"ADJ 形容词","cn":"完全的；绝对的；无保留的；不受限制的","en":"Unqualified means total or unlimited.","ex":{"en":"The event was an unqualified success","cn":"这一活动取得了极大成功。"}}]},"examples":[{"en":"I feel unqualified to comment on the subject.","cn":"我觉得没有资格对此事发表意见。"},{"en":"He was totally unqualified for his job as a senior manager.","cn":"他担任高级经理职务完全不够格。"}]},"unit":{"oxford":{"phon":"ˈjuːnɪt","pos":"noun","senses":[{"en":"a single thing, person or group that is complete by itself but can also form part of something larger","cn":"单独的事物（或人、群体）；单位；单元","sc":"single thing","ex":{"en":"After 1946 the British Government treated the four territorial divisions as a single unit.","cn":"1946 年以后，英国政府将这四个行政区域视为一个整体。"}},{"en":"a single item of the type of product that a company sells","cn":"一件（商品）；单位","lab":"business","sc":"single thing","ex":{"en":"The game's selling price was $15 per unit.","cn":"这游戏的售价为每套 15 美元。"}},{"en":"one of the parts into which a textbook or a series of lessons is divided","cn":"单元；课","sc":"in textbook","ex":{"en":"Each unit of the course that we completed felt like a real achievement.","cn":"我们每完成一单元课程，都觉得很了不起。"}},{"en":"a group of people who work or live together, especially for a particular purpose","cn":"班组；小队","sc":"group of people","ex":{"en":"army/military/combat/police units","cn":"陆军／军事／战斗／警察小队"}},{"en":"a department, especially in a hospital, that provides a particular type of care or treatment","cn":"科；病区","sc":"in hospital","ex":{"en":"the intensive care unit","cn":"重症监护室"}},{"en":"a piece of furniture, especially a cupboard, that fits with and matches others of the same type","cn":"配套家具组件；（尤指）成套家具中的柜子","sc":"furniture","ex":{"en":"a fitted kitchen with white units","cn":"使用白色组件的整体厨房"}},{"en":"a fixed quantity, etc. that is used as a standard measurement","cn":"单位；单元","sc":"measurement","ex":{"en":"a unit of measurement","cn":"计量单位"}},{"en":"a small machine that has a particular purpose or is part of a larger machine","cn":"装置；机件；部件；元件","sc":"small machine","ex":{"en":"a waste disposal unit","cn":"垃圾处理器"}},{"en":"a single flat, house or section in a building or group of buildings","cn":"（一）套房；单元房","lab":"formal","sc":"flat/part of building","ex":{"en":"a housing/residential unit","cn":"一套住宅"}},{"en":"any whole number from 0 to 9","cn":"个位数","sc":"number","ex":{"en":"a column for the tens and a column for the units","cn":"十位数栏和个位数栏"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"单位；整体","en":"If you consider something as a unit, you consider it as a single, complete thing.","ex":{"en":"Agriculture was based in the past on the family as a unit.","cn":"过去的农业是以家庭为单位的。"}},{"pos":"N-COUNT 可数名词","cn":"（工作）班组，部门","en":"A unit is a group of people who work together at a specific job, often in a particular place.","ex":{"en":"...the health services research unit","cn":"医疗卫生服务研究部门"}},{"pos":"N-COUNT 可数名词","cn":"（武装部队或警察机关的）小队，分队","en":"A unit is a group within an armed force or police force, whose members fight or work together or carry out a particular task.","ex":{"en":"One secret military unit tried to contaminate the drinking water of the refugees","cn":"一个秘密军事分队企图污染难民的饮用水。"}},{"pos":"N-COUNT 可数名词","cn":"（常为更大机器一部分的）装置，设备，部件","en":"A unit is a small machine which has a particular function, often part of a larger machine.","ex":{"en":"The unit plugs into any TV set.","cn":"这个部件能插进任何电视机。"}},{"pos":"N-COUNT 可数名词","cn":"（计量）单位","en":"A unit of measurement is a fixed standard quantity, length, or weight that is used for measuring things. The litre, the centimetre, and the ounce are all units."},{"pos":"N-COUNT 可数名词","cn":"（课本）单元","en":"A unit is one of the parts that a textbook is divided into."}]},"media":{"uk":"media/uk/unit__gb_1.mp3","us":"media/us/unit__us_1.mp3"},"examples":[{"en":"Women are advised not to drink more than fourteen units of alcohol per week.","cn":"建议妇女每周饮酒不超过十四个酒精单位。"},{"en":"The game's selling price was $15 per unit.","cn":"这游戏的售价为每套 15 元。"}]},"undemonstrative":{"media":{"uk":"media/uk/undemonstrative__gb_1.mp3","us":"media/us/undemonstrative__us_1.mp3"},"oxford":{"phon":"ˌʌndɪˈmɒnstrətɪv","pos":"adjective","senses":[{"en":"not showing feelings openly, especially feelings of love","cn":"喜怒不形于色的；不流露感情的"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"含蓄的；情感不外露的","en":"Someone who is undemonstrative does not often show affection.","ex":{"en":"Lady Ainslie is an undemonstrative woman who rarely touches even her own son.","cn":"安斯利夫人是一个连自己儿子都很少抚摸一下的矜持女子。"}}]}},"urgency":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the need to deal with something immediately because it is very important","cn":"紧急，急迫"},{"en":"the feeling of wanting something immediately","cn":"急切，急迫"}]},"examples":[{"en":"The issue should be discussed as a matter of urgency .","cn":"这一事件应被当作紧急情况讨论。","src":"ld"},{"en":"Despite the crisis, there appeared to be no sense of urgency .","cn":"危机当前却没有出现紧迫的氛围。","src":"ld"}],"media":{"uk":"media/uk/urgency__gb_1.mp3","us":"media/us/urgency__us_1.mp3"},"oxford":{"phon":"ˈɜːdʒənsi","pos":"noun","senses":[{"en":"the quality of needing to be dealt with or happen immediately","cn":"紧急的；紧迫的；迫切的","ex":{"en":"This is a matter of some urgency.","cn":"这件事相当紧迫。"}},{"en":"the feeling or belief that something needs to be dealt with immediately","cn":"催促的；急切的","ex":{"en":"There was a note of urgency in his voice.","cn":"他的语气有些急切。"}}]}},"until":{"media":{"uk":"media/uk/until__gb_1.mp3","us":"media/us/until__us_1.mp3"},"oxford":{"phon":"ənˈtɪl","pos":"conjunction, preposition","senses":[{"en":"up to the point in time or the event mentioned","cn":"到…时；直到…为止","ex":{"en":"Let's wait until the rain stops.","cn":"咱们等雨停了吧。"}}]},"collins":{"senses":[{"pos":"PREP 介词","cn":"直至；直到；在…之前","en":"If something happens until a particular time, it happens during the period before that time and stops at that time.","ex":{"en":"Until 1982 he was senior lecturer in botany at Durham University.","cn":"1982年以前他一直是达勒姆大学生物系的高级讲师。"}},{"pos":"PREP 介词","cn":"（与否定词连用）直到…之前，直到…为止，除非","en":"You use until with a negative to emphasize the moment in time after which the rest of your statement becomes true, or the condition which would make it true.","ex":{"en":"The traffic laws don't take effect until the end of the year","cn":"交通法要到年底才生效。"}},{"pos":"","cn":"","en":"up until→see: ;"}]},"examples":[{"en":"They moved here in 2009. Until then they'd always been in the London area.","cn":"他们 2009 年搬到这里，之前一直住在伦敦地区。"},{"en":"You can stay on the bus until London (= until you reach London).","cn":"你可以不用下车，直到公车到达伦敦为止。"}]},"unaccustomed":{"media":{"uk":"media/uk/unaccustomed__gb_1.mp3","us":"media/us/unaccustomed__us_1.mp3"},"oxford":{"phon":"ˌʌnəˈkʌstəmd","pos":"adjective","senses":[{"en":"not in the habit of doing something; not used to something","cn":"不习惯；不适应","ex":{"en":"He was unaccustomed to hard work.","cn":"他不习惯艰苦工作。"}},{"en":"not usual, normal or familiar","cn":"反常的；不一般的；不熟悉的","g":"[usually before noun]","ex":{"en":"The unaccustomed heat made him weary.","cn":"反常的炎热令他虚弱无力。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不习惯的；不熟悉的；不适应的","en":"If you are unaccustomed to something, you do not know it very well or have not experienced it very often.","ex":{"en":"They were unaccustomed to such military setbacks","cn":"他们还不习惯这样的军事挫败。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不寻常的；奇怪的","en":"If you describe someone's behaviour or experiences as unaccustomed, you mean that they do not usually behave like this or have experiences of this kind.","ex":{"en":"He began to comfort me with such unaccustomed gentleness","cn":"他开始以那种少有的温柔安慰我。"}}]},"examples":[{"en":"The unaccustomed heat made him weary.","cn":"反常的炎热令他虚弱无力。"},{"en":"I am unaccustomed to being told what to do.","cn":"我没有听人使唤的习惯。"}]},"utterly":{"media":{"uk":"media/uk/utterly__gb_1.mp3","us":"media/us/utterly__us_1.mp3"},"collins":{"senses":[{"pos":"ADV 副词","cn":"全然；完全地；彻底地","en":"You use utterly to emphasize that something is very great in extent, degree, or amount.","ex":{"en":"Everything about the country seemed utterly different from what I'd experienced before","cn":"这个国家的一切似乎与我以前的经历完全不同。"}}]},"examples":[{"en":"We're so utterly different from each other.","cn":"我们之间有着天壤之别。"},{"en":"She utterly failed to convince them.","cn":"她根本没有说服他们。"}],"oxford":{"phon":"ˈʌtəli","pos":"adverb","senses":[{"en":"completely","cn":"完全；十足；彻底","ex":{"en":"We're so utterly different from each other.","cn":"我们之间有着天壤之别。"}}]}},"unstable":{"media":{"uk":"media/uk/unstable__gb_1.mp3","us":"media/us/unstable__us_1.mp3"},"oxford":{"phon":"ʌnˈsteɪbl","pos":"adjective","senses":[{"en":"likely to change suddenly","cn":"不稳定的；易变的；变化莫测的","ex":{"en":"The political situation remains highly unstable.","cn":"政局仍然十分动荡。"}},{"en":"if people are unstable, their behaviour and emotions change often and suddenly because their minds are upset","cn":"（行为、情绪）反复无常的，不稳定的","ex":{"en":"He's highly unstable, and liable to sudden fits of rage.","cn":"他情绪极其反复无常，动辄暴跳如雷。"}},{"en":"likely to move or fall","cn":"易动（或倒下）的；不稳固的","ex":{"en":"Icebergs are notoriously unstable and are likely to turn over.","cn":"众所周知，冰山非常不稳定，很可能会翻转。"}},{"en":"not staying in the same chemical or atomic state","cn":"不稳定的","lab":"specialist","ex":{"en":"chemically unstable","cn":"化学上不稳定的"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不稳定的；不可靠的；动荡的","en":"You can describe something as unstable if it is likely to change suddenly, especially if this creates difficulty or danger.","ex":{"en":"After the fall of Pitt in 1801 there was a decade of unstable government","cn":"1801年皮特倒台后，政府经历了10年的动荡。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不牢固的；松脱的","en":"Unstable objects are likely to move or fall.","ex":{"en":"Both clay and sandstone are unstable rock formations.","cn":"黏土和砂岩都是不牢固的岩石构造。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（情绪）不稳定的，波动的","en":"If people are unstable, their emotions and behaviour keep changing because their minds are disturbed or upset.","ex":{"en":"He was emotionally unstable","cn":"他情绪不稳定。"}}]},"examples":[{"en":"The political situation remains highly unstable.","cn":"政局仍然十分动荡。"},{"en":"chemically unstable","cn":"化学上不稳定的"}]},"unknown":{"media":{"uk":"media/uk/unknown__gb_1.mp3","us":"media/us/unknown__us_1.mp3"},"oxford":{"phon":"ˌʌnˈnəʊn","pos":"adjective","senses":[{"en":"not known or identified","cn":"未知的；不详的；未被确认的","ex":{"en":"A previously unknown group claimed responsibility for the bombing.","cn":"一个此前不为人知的组织声称对爆炸负责。"}},{"en":"not famous or well known","cn":"不出名的；无名的","ex":{"en":"She was then still relatively unknown.","cn":"她当时还不怎么有名。"}},{"en":"never happening or existing","cn":"从未发生的；从不存在的","ex":{"en":"The disease is as yet unknown in Europe (= there have been no cases there).","cn":"这种疾病至今尚未在欧洲出现过。"}},{"en":"places or things that are not known about","cn":"未知的地方（或事物）","g":"[singular]","ex":{"en":"a journey into the unknown","cn":"探险之旅"},"pos":"noun"},{"en":"a person who is not well known","cn":"无名者；不出名的人","g":"[countable]","ex":{"en":"A young unknown played the leading role.","cn":"演主角的是一个名不见经传的年轻人。"},"pos":"noun"},{"en":"a fact or an influence that is not known","cn":"不明的情况；未知的因素","g":"[countable]","ex":{"en":"There are so many unknowns in the proposal.","cn":"这项提案中的未知数太多了。"},"pos":"noun"},{"en":"a quantity that does not have a known value","cn":"未知数；未知量","g":"[countable]","lab":"mathematics","ex":{"en":"X and Y in the equation are both unknowns.","cn":"等式中的 X 和 Y 都是未知数。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"不知道的；不了解的；未知的","en":"If something is unknown to you, you have no knowledge of it.","ex":{"en":"An unknown number of demonstrators were arrested","cn":"有数目不详的示威者遭到了逮捕。"}},{"pos":"ADJ 形容词","cn":"不认识的；不熟悉的；陌生的","en":"An unknown person is someone whose name you do not know or whose character you do not know anything about.","ex":{"en":"Unknown thieves had forced their way into the apartment","cn":"不知名的窃贼破门闯入了公寓。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不出名的；无人知晓的；未获公众认可的","en":"An unknown person is not famous or publicly recognized.","ex":{"en":"He was an unknown writer.","cn":"他是个名不见经传的作家。"}},{"pos":"ADJ 形容词","cn":"从未发生的；从未存在的","en":"If you say that a particular problem or situation is unknown, you mean that it never occurs.","ex":{"en":"A hundred years ago coronary heart disease was virtually unknown in Europe and America.","cn":"在100年前冠心病几乎不存在于欧洲和美洲。"}},{"pos":"N-SING 单数名词","cn":"（总称）未知事物，不为人知的地方","en":"The unknown refers generally to things or places that people do not know about or understand.","ex":{"en":"Ignorance of people brings fear, fear of the unknown.","cn":"人们的无知会带来恐惧，对未知事物的恐惧。"}}]},"examples":[{"en":"The author is virtually unknown outside Poland.","cn":"在波兰以外，这位作者实际上鲜为人知。"},{"en":"A young unknown played the leading role.","cn":"演主角的是一个名不见经传的年轻人。"}]},"unread":{"media":{"uk":"media/uk/unread__gb_1.mp3","us":"media/us/unread__us_1.mp3"},"oxford":{"phon":"ˌʌnˈred","pos":"adjective","senses":[{"en":"that has not been read","cn":"未读的；未阅的","ex":{"en":"a pile of unread newspapers","cn":"一摞未看的报纸"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未被阅读的；无人翻阅的","en":"If a book or other piece of writing is unread, you or other people have not read it, for example because it is boring or because you have no time.","ex":{"en":"All his unpublished writing should be destroyed unread","cn":"他所有未发表的作品必须在被人看到之前销毁。"}}]},"examples":[{"en":"a pile of unread newspapers","cn":"一摞未看的报纸"}]},"urine":{"oxford":{"phon":"ˈjʊərɪn","pos":"noun","senses":[{"en":"the waste liquid that collects in the bladder and that you pass from your body","cn":"尿；小便","ex":{"en":"I gagged at the stench of stale urine.","cn":"尿臊味让我想吐。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"尿；小便","en":"Urine is the liquid that you get rid of from your body when you go to the toilet."}]},"media":{"uk":"media/uk/urine__gb_1.mp3","us":"media/us/urine__us_1.mp3"}},"undo":{"media":{"uk":"media/uk/undo__gb_1.mp3","us":"media/us/undo__us_1.mp3"},"oxford":{"phon":"ʌnˈduː","pos":"verb","senses":[{"en":"to open something that is fastened, tied or wrapped","cn":"打开；解开；拆开","ex":{"en":"to undo a button/knot/zip","cn":"解开纽扣／绳结；拉开拉锁"}},{"en":"to cancel the effect of something","cn":"消除，取消，废止（某事的影响）","ex":{"en":"He undid most of the good work of the previous manager.","cn":"他把前任经理的大部分功绩都毁掉了。"}},{"en":"to make somebody/something fail","cn":"打败；挫败","g":"[usually passive]","lab":"formal","ex":{"en":"The team was undone by the speed and strength of their opponents.","cn":"这个队伍被对手的速度和力量打败了。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"解开；松开；打开","en":"If you undo something that is closed, tied, or held together, or if you undo the thing holding it, you loosen or remove the thing holding it.","ex":{"en":"I managed secretly to undo a corner of the parcel","cn":"我悄悄地设法解开了包裹的一角。"}},{"pos":"VERB 动词","cn":"撤销；抵消；消除","en":"To undo something that has been done means to reverse its effect.","ex":{"en":"A heavy-handed approach from the police could undo that good impression","cn":"警方采取高压手段可能会毁掉之前留下的好印象。"}},{"pos":"VERB 动词","cn":"破坏；毁掉","en":"If a person, organization, or plan is undone by something, that thing causes their failure.","ex":{"en":"They were undone by a goal from John Barnes","cn":"约翰·巴恩斯的一粒进球使他们落败。"}}]},"examples":[{"en":"He undid most of the good work of the previous manager.","cn":"他把前任经理的大部分功绩都毁掉了。"},{"en":"The team was undone by the speed and strength of their opponents.","cn":"这个队伍被对手的速度和体力打败了。"}]},"unlimited":{"oxford":{"phon":"ʌnˈlɪmɪtɪd","pos":"adjective","senses":[{"en":"as much or as many as is possible; not limited in any way","cn":"尽量多的；任意多的；无限制的","ex":{"en":"The ticket gives you unlimited travel for seven days.","cn":"凭本车票在七日内可自由乘车不受限制。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"无限的；（数量）极大的","en":"If there is an unlimited quantity of something, you can have as much or as many of that thing as you want.","ex":{"en":"An unlimited number of copies can still be made from the original","cn":"仍可以由原件复印出无数份副本来。"}}]},"media":{"uk":"media/uk/unlimited__gb_1.mp3","us":"media/us/unlimited__us_1.mp3"},"examples":[{"en":"The court has the power to impose an unlimited fine for this offence.","cn":"法庭有权对这一违法行为罚款，额度不受限制。"},{"en":"The ticket gives you unlimited travel for seven days.","cn":"凭本车票在七日内可自由乘车不受限制。"}]},"untimely":{"oxford":{"phon":"ʌnˈtaɪmli","pos":"adjective","senses":[{"en":"happening too soon or sooner than is normal or expected","cn":"过早的；不到时间的；突然的","g":"[usually before noun]","ex":{"en":"She met a tragic and untimely death at 25.","cn":"她于 25 岁时不幸猝然辞世。"}},{"en":"happening at a time or in a situation that is not suitable","cn":"不合时宜的；不适时的","ex":{"en":"His interruption was untimely.","cn":"他的插话不是时候。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"过早的；提早的；未到期的","en":"If you describe an event as untimely, you mean that it happened earlier than it should, or sooner than you expected.","ex":{"en":"His mother's untimely death had a catastrophic effect on him","cn":"他母亲的早逝给了他沉重的打击。"}},{"pos":"ADJ 形容词","cn":"不适时的；不合时宜的","en":"You can describe something as untimely if it happens at an unsuitable time.","ex":{"en":"...an untimely visit from the milkman","cn":"送牛奶的来得不是时候"}}]},"media":{"uk":"media/uk/untimely__gb_1.mp3","us":"media/us/untimely__us_1.mp3"},"examples":[{"en":"She met a tragic and untimely death at 25.","cn":"她于 25 岁时不幸猝然辞世。"},{"en":"His interruption was untimely.","cn":"他的插话不是时候。"}]},"unexpected":{"media":{"uk":"media/uk/unexpected__gb_1.mp3","us":"media/us/unexpected__us_1.mp3"},"oxford":{"phon":"ˌʌnɪkˈspektɪd","pos":"adjective","senses":[{"en":"if something is unexpected, it surprises you because you were not expecting it","cn":"出乎意料的；始料不及的","ex":{"en":"Things took an unexpected turn.","cn":"事情出现了意料之外的变化。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"想不到的；未预料到的；意外的","en":"If an event or someone's behaviour is unexpected, it surprises you because you did not think that it was likely to happen.","ex":{"en":"His death was totally unexpected","cn":"他的死亡完全出乎意料。"}}]},"examples":[{"en":"Not unexpectedly, most local business depends on tourism.","cn":"并非出人意料的是，当地的大部分生意依靠旅游业。"},{"en":"Police officers must be prepared for the unexpected.","cn":"警察必须随时准备应付意外事件。"}]},"upright":{"media":{"uk":"media/uk/upright__gb_1.mp3","us":"media/us/upright__us_1.mp3"},"oxford":{"phon":"ˈʌpraɪt","pos":"adjective","senses":[{"en":"not lying down, and with the back straight rather than bent","cn":"直立的；挺直的","ex":{"en":"Try to maintain an upright posture while doing this exercise.","cn":"进行此练习时尽量保持直立姿势。"}},{"en":"placed in a vertical position","cn":"竖直的；直立的；垂直的","ex":{"en":"Keep the bottle upright.","cn":"保持瓶子直立。"}},{"en":"behaving in a moral and honest way","cn":"正直的；正派的；诚实的","ex":{"en":"an upright citizen","cn":"正直的公民"}},{"en":"in or into a straight, vertical position","cn":"竖立着；垂直着","ex":{"en":"She sat upright in bed.","cn":"她挺直地坐在床上。"},"pos":"adverb"},{"en":"a long piece of wood, metal or plastic that is placed in a vertical position, especially in order to support something","cn":"（尤指支撑用的）直柱，立柱，立放构件","pos":"noun"},{"en":"a piano in which the strings are vertical (= go straight up and down)","cn":"立式钢琴","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"垂直的；挺直的；直挺挺的","en":"If you are sitting or standing upright, you are sitting or standing with your back straight, rather than bending or lying down.","ex":{"en":"Helen sat upright in her chair","cn":"海伦笔直地坐在椅子上。"}},{"pos":"ADJ 形容词","cn":"（吸尘器、冰箱等）竖式的，立式的","en":"An upright vacuum cleaner or freezer is tall rather than wide.","ex":{"en":"...the latest state-of-the-art upright vacuum cleaners.","cn":"最新款、最先进的立式吸尘器"}},{"pos":"ADJ 形容词","cn":"（椅子）直靠背的，没有扶手的","en":"An upright chair has a straight back and no arms.","ex":{"en":"He was sitting on an upright chair beside his bed, reading.","cn":"他正坐在床前一张直背椅上看书。"}},{"pos":"N-COUNT 可数名词","cn":"立柱；立放构件","en":"You can refer to vertical posts or the vertical parts of an object as uprights .","ex":{"en":"...the uprights of a four-poster bed.","cn":"四柱床的立柱"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"诚实的，正直的；规矩的","en":"You can describe people as upright when they are careful to follow acceptable rules of behaviour and behave in a moral way.","ex":{"en":"...a very upright, trustworthy man.","cn":"一个非常正直可靠的人"}}]},"examples":[{"en":"Gradually raise your body into an upright position.","cn":"慢慢起身，成直立状态。"},{"en":"She sat upright in bed.","cn":"她挺直地坐在床上。"}]},"u":{"media":{"uk":"media/uk/u__gb_1.mp3","us":"media/us/u__us_1.mp3"},"oxford":{"phon":"juː","pos":"noun","senses":[{"en":"the 21st letter of the English alphabet","cn":"英语字母表的第 21 个字母","ex":{"en":"‘Under’ begins with (a) U/‘U’.","cn":"under 一词以字母 u 开头。"}},{"en":"universal (the label of a film that is suitable for anyone including children)","cn":"U 类影片（适合所有观众）","ex":{"en":"Aladdin, certificate U","cn":"U 类电影《阿拉丁》"},"pos":"abbreviation"},{"en":"the symbol for the chemical element Uranium","cn":"铀化学元素的符号","pos":"symbol"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"英语字母表的第21个字母","en":"U is the twenty-first letter of the English alphabet."},{"pos":"","cn":"（用作首字母为 u 的一些单词的缩写，如 unit, united 或 University）","en":"U or u is used as an abbreviation for words beginning with 'u', such as 'unit', 'united', or 'University'."}]},"examples":[{"en":"‘Under’ begins with (a) U/‘U’. * under","cn":"一词以字母 u 开头。"},{"en":"‘Under’ begins with (a) U/‘U’.","cn":""}]},"unquestionably":{"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"use this to emphasize that something is definitely true. Definitely is more common in spoken English than certainly","cn":""},{"en":"use this to say that, in your opinion, something is definitely true about someone or something","cn":""}]},"examples":[{"en":"The Eiffel Tower is unquestionably one of Paris’s most familiar landmarks.","cn":"埃菲尔铁塔无疑是巴黎最为人熟知的地标之一。","src":"ld"}],"media":{"uk":"media/uk/unquestionably__gb_1.mp3","us":"media/us/unquestionably__us_1.mp3"},"oxford":{"phon":"ʌnˈkwestʃənəbli","pos":"adverb","senses":[{"en":"without any doubt","cn":"无疑的；无可非议的；确实的","ex":{"en":"It was unquestionably a step in the right direction.","cn":"这无疑是朝正确方向迈出的一步。"}}]}},"uncontrollable":{"media":{"uk":"media/uk/uncontrollable__gb_1.mp3","us":"media/us/uncontrollable__us_1.mp3"},"oxford":{"phon":"ˌʌnkənˈtrəʊləbl","pos":"adjective","senses":[{"en":"that you cannot control or prevent","cn":"无法控制的；难以防止的；禁不住的","ex":{"en":"an uncontrollable temper","cn":"控制不住的脾气"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"无法控制的；控制不住的","en":"If you describe a feeling or physical action as uncontrollable, you mean that you cannot control it or prevent yourself from feeling or doing it.","ex":{"en":"It had been a time of almost uncontrollable excitement","cn":"那是一个几乎难以抑制亢奋的时期。"}},{"pos":"ADJ 形容词","cn":"难以管束的；放肆的","en":"If you describe a person as uncontrollable, you mean that their behaviour is bad and that nobody can make them behave more sensibly.","ex":{"en":"Mark was withdrawn and uncontrollable","cn":"马克沉默寡言，难以管束。"}},{"pos":"ADJ 形容词","cn":"（局势等）无法掌控的","en":"If you describe a situation or series of events as uncontrollable, you believe that nothing can be done to control them or to prevent things from getting worse.","ex":{"en":"If political and ethnic problems are not resolved the situation could become uncontrollable.","cn":"如果政治和民族问题得不到解决，局面可能会失控。"}}]},"examples":[{"en":"He's an uncontrollable child (= he behaves very badly and cannot be controlled).","cn":"他是个难以管教的孩子。"},{"en":"She began shaking uncontrollably.","cn":"她不由自主地哆嗦起来。"}]},"united":{"media":{"uk":"media/uk/united__gb_1.mp3","us":"media/us/united__us_1.mp3"},"oxford":{"phon":"juˈnaɪtɪd","pos":"adjective","senses":[{"en":"joined together as a political unit or by shared aims","cn":"联合的；统一的","ex":{"en":"the United States of America","cn":"美利坚合众国"}},{"en":"in agreement and working together","cn":"和谐的；一致的；团结的","ex":{"en":"We need to become a more united team.","cn":"我们要成为一支更加团结的队伍。"}},{"en":"used in the names of some teams and companies","cn":"（用于团队和公司名称）","ex":{"en":"Manchester United","cn":"曼彻斯特联队"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"团结的；联合的；一致的","en":"When people are united about something, they agree about it and act together.","ex":{"en":"Every party is united on the need for parliamentary democracy","cn":"各党派一致认为有必要实行议会民主。"}},{"pos":"ADJ 形容词","cn":"（国家）统一的，合并的","en":"United is used to describe a country which has been formed from two or more states or countries.","ex":{"en":"...the first elections to be held in a united Germany for fifty eight years.","cn":"58年来第一次在一个统一的德国举行的选举"}},{"pos":"ADJ 形容词","cn":"（用于国名中）联合的，合众的","en":"United is used in the names of countries which are made up from several states or smaller countries.","ex":{"en":"...the United States of America.","cn":"美利坚合众国"}}]},"examples":[{"en":"We need to become a more united team.","cn":"我们要成为一支更加团结的队伍。"},{"en":"They are united in their opposition to the plan.","cn":"他们一致反对这个计划。"}]},"unlikely":{"media":{"uk":"media/uk/unlikely__gb_1.mp3","us":"media/us/unlikely__us_1.mp3"},"oxford":{"phon":"ʌnˈlaɪkli","pos":"adjective","senses":[{"en":"not likely to happen; not probable","cn":"不大可能发生的","ex":{"en":"The project seemed unlikely to succeed.","cn":"这个项目似乎难以成功。"}},{"en":"not the person, thing or place that you would normally think of or expect","cn":"非心目中的；意料之外的","g":"[only before noun]","ex":{"en":"He seems a most unlikely candidate for the job.","cn":"他似乎是最不适合担任这项工作的人选。"}},{"en":"difficult to believe","cn":"难以相信的；不能信服的","g":"[only before noun]","ex":{"en":"She gave me an unlikely explanation for her behaviour.","cn":"她对自己行为的解释很难令我信服。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不太可能的；未必会发生的","en":"If you say that something is unlikely to happen or unlikely to be true, you believe that it will not happen or that it is not true, although you are not completely sure.","ex":{"en":"A military coup seems unlikely","cn":"看起来不太可能会发生军事政变。"}}]},"examples":[{"en":"He seems a most unlikely candidate for the job.","cn":"他似乎是最不适合担任这项工作的人选。"},{"en":"She gave me an unlikely explanation for her behaviour.","cn":"她对自己行为的解释很难令我信服。"}]},"urgent":{"media":{"uk":"media/uk/urgent__gb_1.mp3","us":"media/us/urgent__us_1.mp3"},"oxford":{"phon":"ˈɜːdʒənt","pos":"adjective","senses":[{"en":"that needs to be dealt with or happen immediately","cn":"紧急的；紧迫的；迫切的","lab":"formal","ex":{"en":"The police have issued an urgent appeal for information.","cn":"警方已发出紧急呼吁，要求提供信息。"}},{"en":"showing that you think that something needs to be dealt with immediately","cn":"催促的；急切的","ex":{"en":"an urgent whisper","cn":"急切的耳语"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"紧迫的；紧急的；紧要的","en":"If something is urgent, it needs to be dealt with as soon as possible.","ex":{"en":"There is an urgent need for food and water","cn":"现在亟需食物和水。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"急切的；极力主张的","en":"If you speak in an urgent way, you show that you are anxious for people to notice something or to do something.","ex":{"en":"His voice was low and urgent","cn":"他的嗓音低沉而急切。"}}]},"examples":[{"en":"‘Can I see you for a moment?’ ‘Is it urgent?’ “","cn":"我能见你一下吗？” “有急事吗？”"},{"en":"The attack added a new urgency to the peace talks.","cn":"这次攻击事件使和平谈判愈加紧迫。"}]},"underclass":{"media":{"uk":"media/uk/underclass__gb_1.mp3","us":"media/us/underclass__us_1.mp3"},"oxford":{"phon":"ˈʌndəklɑːs","pos":"noun","senses":[{"en":"a social class that is very poor and has no status","cn":"社会底层；贫困阶层","ex":{"en":"The long-term unemployed are becoming a new underclass.","cn":"长期失业的人正形成新的贫困阶层。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"下层社会；社会底层","en":"A country's underclass consists of those members of its population who are poor, and who have little chance of improving their situation.","ex":{"en":"The basic problems of the inner-city underclass are inadequate housing and lack of jobs","cn":"老城区底层人群面临的基本问题是住房紧张和就业不足。"}}]},"examples":[{"en":"The long-term unemployed are becoming a new underclass.","cn":"长期失业的人正形成新的贫困阶层。"},{"en":"an urban underclass, who have limited access to health care","cn":"不能充分享受医疗服务的城市贫困阶层"}]},"unceasing":{"media":{"uk":"media/uk/unceasing__gb_1.mp3","us":"media/us/unceasing__us_1.mp3"},"oxford":{"phon":"ʌnˈsiːsɪŋ","pos":"adjective","senses":[{"en":"continuing all the time","cn":"持续不断的；连绵不绝的","ex":{"en":"unceasing efforts","cn":"不懈的努力"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"不停的；持续的；连续不断的","en":"If you describe something as unceasing, you are emphasizing that it continues without stopping.","ex":{"en":"...the unceasing quest for more speed.","cn":"不断追求更高的速度"}}]},"examples":[{"en":"Planes passed overhead with unceasing regularity.","cn":"每隔一段时间总有飞机从头顶飞过。"},{"en":"Snow fell unceasingly.","cn":"飞雪连绵。"}]},"undeveloped":{"media":{"uk":"media/uk/undeveloped__gb_1.mp3","us":"media/us/undeveloped__us_1.mp3"},"oxford":{"phon":"ˌʌndɪˈveləpt","pos":"adjective","senses":[{"en":"not used for farming, industry, building, etc.","cn":"未开垦的；未利用的；未开发的","ex":{"en":"undeveloped countryside","cn":"未开发的乡村"}},{"en":"not having modern industries, and with a low standard of living","cn":"不发达的；落后的"},{"en":"not grown to full size","cn":"发育不良的；未充分发育的","ex":{"en":"undeveloped limbs","cn":"发育不全的四肢"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（国家或地区）不发达的，落后的","en":"An undeveloped country or region does not have modern industries and usually has a low standard of living.","ex":{"en":"The big losers will be the undeveloped countries, especially sub-Saharan Africa.","cn":"受害最深的将是不发达国家，尤其是非洲撒哈拉沙漠以南地区。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（土地）未开发的，未开垦的","en":"Undeveloped land has not been built on or used for activities such as mining and farming.","ex":{"en":"Vast tracts of the country are wild and undeveloped","cn":"乡间大片大片的荒地尚未开发。"}}]},"examples":[{"en":"undeveloped limbs","cn":"发育不全的四肢"},{"en":"the undeveloped regions of the world","cn":"世界上的欠发达地区"}]},"upstairs":{"media":{"uk":"media/uk/upstairs__gb_1.mp3","us":"media/us/upstairs__us_1.mp3"},"oxford":{"phon":"ˌʌpˈsteəz","pos":"adverb","senses":[{"en":"up the stairs; on or to a floor of a house or other building higher than the one that you are on","cn":"在（或向）楼上；在（或向）上一层","ex":{"en":"to run/walk/head upstairs","cn":"跑／走上楼；往楼上走"}},{"en":"on a floor of a house or other building that is higher than the one that you are on","cn":"在楼上的；在上一楼层的","ex":{"en":"an upstairs room/window/bathroom","cn":"楼上的房间/窗户/浴室"},"pos":"adjective"},{"en":"the floor or floors in a building that are above the ground floor","cn":"二楼；二楼以上各层；楼上","ex":{"en":"We've converted the upstairs into an office.","cn":"我们把楼上改成了办公室。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"上楼；往楼上","en":"If you go upstairs in a building, you go up a staircase towards a higher floor.","ex":{"en":"He went upstairs and changed into fresh clothes","cn":"他上楼换上干净衣服。"}},{"pos":"ADV 副词","cn":"在楼上","en":"If something or someone is upstairs in a building, they are on a floor that is higher than the ground floor.","ex":{"en":"The restaurant is upstairs and consists of a large, open room","cn":"饭店在楼上，有一个宽敞的开间。"}},{"pos":"ADJ 形容词","cn":"楼上的","en":"An upstairs room or object is situated on a floor of a building that is higher than the ground floor.","ex":{"en":"Marsani moved into the upstairs apartment.","cn":"马萨尼搬进了楼上的公寓里。"}},{"pos":"N-SING 单数名词","cn":"楼层","en":"The upstairs of a building is the floor or floors that are higher than the ground floor.","ex":{"en":"Together we went through the upstairs","cn":"我们一起走过各层楼。"}}]},"examples":[{"en":"We've converted the upstairs into an office.","cn":"我们把楼上改成了办公室。"},{"en":"I carried her bags upstairs.","cn":"我把她的包拿到楼上。"}]},"untidiness":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not tidy – used especially when things have not been put back in their correct place","cn":""},{"en":"untidy or dirty. American people use this word instead of untidy . British people use this word, but it sounds less formal than untidy","cn":""}]},"examples":[{"en":"Her clothes were in an untidy heap on the floor.","cn":"","src":"ld"},{"en":"His room is always so messy .","cn":"","src":"ld"}],"media":{"uk":"media/uk/untidiness__gb_1.mp3","us":"media/us/untidiness__us_1.mp3"},"oxford":{"phon":"ʌnˈtaɪdinəs","pos":"noun","senses":[{"en":"the state of not being neat or well arranged; a lack of order","cn":"凌乱","ex":{"en":"He hated untidiness and dirt.","cn":"他讨厌不整洁和肮脏。"}},{"en":"the fact of tending not to keep things neat or well organized","cn":"无条理的；不修边幅的","ex":{"en":"He teased her for her untidiness.","cn":"他嘲笑她不整洁。"}}]}},"upward":{"media":{"uk":"media/uk/upward__gb_1.mp3","us":"media/us/upward__us_1.mp3"},"oxford":{"phon":"ˈʌpwəd","pos":"adjective","senses":[{"en":"pointing towards or facing a higher place","cn":"向上的；朝上的；向高处的","ex":{"en":"an upward gaze","cn":"举目凝望"}},{"en":"increasing in amount or price","cn":"（数量、价格）上升的，上涨的，增长的","ex":{"en":"an upward movement in property prices","cn":"房地产价格的上升"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"向上的","en":"An upward movement or look is directed towards a higher place or a higher level.","ex":{"en":"She started once again on the steep upward climb","cn":"她又开始沿着陡峭的山路往上爬。"}},{"pos":"ADJ 形容词","cn":"上升的；升高的","en":"If you refer to an upward trend or an upward spiral, you mean that something is increasing in quantity or price.","ex":{"en":"...the Army's concern that the upward trend in the numbers avoiding military service may continue","cn":"部队对逃避服兵役人数可能持续增多的担忧"}}]},"examples":[{"en":"an upward movement in property prices","cn":"房地产价格的上升"},{"en":"an upward gaze","cn":"举目凝望"}]},"unmanageable":{"media":{"uk":"media/uk/unmanageable__gb_1.mp3","us":"media/us/unmanageable__us_1.mp3"},"oxford":{"phon":"ʌnˈmænɪdʒəbl","pos":"adjective","senses":[{"en":"difficult or impossible to control or deal with","cn":"难以控制（或处理）的；无法对付的","ex":{"en":"The costs involved had become unmanageable.","cn":"所产生的费用已无法应付了。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"难管理的；难操纵的","en":"If you describe something as unmanageable, you mean that it is difficult to use, deal with, or control.","ex":{"en":"People were visiting the house every day, sometimes in unmanageable numbers.","cn":"每天都有人来参观那栋房子，有时人多得都无法控制。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"难以管教的","en":"If you describe someone, especially a young person, as unmanageable, you mean that they behave in an unacceptable way and are difficult to control.","ex":{"en":"The signs are that indulged children tend to become unmanageable when they reach their teens.","cn":"这些迹象表明被宠坏的孩子在十几岁的时候往往会变得难以管教。"}}]}},"useless":{"media":{"uk":"media/uk/useless__gb_1.mp3","us":"media/us/useless__us_1.mp3"},"oxford":{"phon":"ˈjuːsləs","pos":"adjective","senses":[{"en":"not useful; not doing or achieving what is needed or wanted","cn":"无用的；无效的；无价值的","ex":{"en":"This pen is useless.","cn":"这支笔没用了。"}},{"en":"not very good at something; not able to do things well","cn":"差劲的；不行的；不擅长的","lab":"informal","ex":{"en":"I'm useless at French.","cn":"我的法语不太行。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无用的；无价值的","en":"If something is useless, you cannot use it.","ex":{"en":"He realised that their money was useless in this country","cn":"他意识到他们国家的货币在这个国家一文不值。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无益的；无效的；不能收到效果的","en":"If something is useless, it does not achieve anything helpful or good.","ex":{"en":"She knew it was useless to protest.","cn":"她知道抗议是没有意义的。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"差劲的；不行的","en":"If you say that someone or something is useless, you mean that they are no good at all.","ex":{"en":"Their education system is useless","cn":"他们的教育体制真差劲。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无能的；无用的","en":"If someone feels useless, they feel bad because they are unable to help someone or achieve anything.","ex":{"en":"She sits at home all day, watching TV and feeling useless.","cn":"她整天坐在家里，看着电视，觉得自己一无是处。"}}]},"examples":[{"en":"Don't ask her to help. She's useless.","cn":"别求她帮忙。她没那个能耐。"},{"en":"She tried to work, but it was useless (= she wasn't able to).","cn":"她很想做事，但力不从心。"}]},"unsatisfied":{"media":{"uk":"media/uk/unsatisfied__gb_1.mp3","us":"media/us/unsatisfied__us_1.mp3"},"oxford":{"phon":"ʌnˈsætɪsfaɪd","pos":"adjective","senses":[{"en":"not dealt with","cn":"未处理的；未解决的；未满足的"},{"en":"not having got what you hoped; not having had enough of something","cn":"不如意的；失望的；未得到满足的","ex":{"en":"The novel had interested him, but left him unsatisfied.","cn":"这本小说引起了他的兴趣，但又让他不满意。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"失望的；不满意的","en":"If you are unsatisfied with something, you are disappointed because you have not got what you hoped to get.","ex":{"en":"The game ended a few hours too early, leaving players and spectators unsatisfied","cn":"那场比赛提早几个小时结束了，球员和观众都很失望。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"未被满足的","en":"If a need or demand is unsatisfied, it is not dealt with.","ex":{"en":"The poll suggests that the strongest unsatisfied appetite for home computers isn't among the richest consumers.","cn":"民意调查显示，家用电脑的最大需求者不是那些最有钱的人。"}}]},"examples":[{"en":"an unsatisfied demand for graduates","cn":"毕业生的供不应求"},{"en":"unsatisfied consumers","cn":"不满意的消费者"}]},"unkempt":{"media":{"uk":"media/uk/unkempt__gb_1.mp3","us":"media/us/unkempt__us_1.mp3"},"oxford":{"phon":"ˌʌnˈkempt","pos":"adjective","senses":[{"en":"not well cared for; not neat or tidy","cn":"不整洁的；凌乱的；不修边幅的","ex":{"en":"greasy, unkempt hair","cn":"油乎乎乱蓬蓬的头发"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不整洁的；未被照顾妥当的；未被收拾整齐的","en":"If you describe something or someone as unkempt, you mean that they are untidy, and not looked after carefully or kept neat.","ex":{"en":"His hair was unkempt and filthy.","cn":"他的头发蓬乱污秽。"}}]},"examples":[{"en":"greasy, unkempt hair","cn":"油乎乎乱蓬蓬的头发"}]},"unhappily":{"media":{"uk":"media/uk/unhappily__gb_1.mp3","us":"media/us/unhappily__us_1.mp3"},"oxford":{"phon":"ʌnˈhæpɪli","pos":"adverb","senses":[{"en":"in an unhappy way","cn":"难过地；怏怏不乐地","ex":{"en":"He sighed unhappily.","cn":"他难过地叹息了一声。"}},{"en":"used to say that a particular situation or fact makes you sad or disappointed","cn":"遗憾地；不幸地；可惜地","ex":{"en":"Unhappily, such good luck is rare.","cn":"遗憾的是，这样的好运太少了。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"令人伤心地；令人遗憾地","en":"You use unhappily to introduce or refer to a statement when you consider it is sad and wish that it was different.","ex":{"en":"On May 23rd, unhappily, the little boy died","cn":"令人伤心的是，5月23号，那个小男孩死了。"}}]},"examples":[{"en":"Unhappily, such good luck is rare.","cn":"遗憾的是，这样的好运太少了。"},{"en":"His wife, unhappily, died five years ago.","cn":"他的妻子不幸于五年前去世了。"}]},"unfair":{"media":{"uk":"media/uk/unfair__gb_1.mp3","us":"media/us/unfair__us_1.mp3"},"oxford":{"phon":"ˌʌnˈfeə(r)","pos":"adjective","senses":[{"en":"not right or fair according to a set of rules or principles; not treating people equally","cn":"不公正的；不公平的；待人不平等的","ex":{"en":"They had been given an unfair advantage.","cn":"他们得到了不公正的好处。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（行动或情形）不公正的，不公平的","en":"An unfair action or situation is not right or fair.","ex":{"en":"She was awarded £5,000 in compensation for unfair dismissal","cn":"她获判5,000英镑，作为遭到无理解雇的补偿。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（制度或情形）不公平的，不平等的","en":"An unfair system or situation does not give equal treatment or equal opportunities to everyone involved.","ex":{"en":"The American plane makers continue to accuse Airbus of unfair competition","cn":"美国飞机制造商继续指控空中客车公司不正当竞争。"}}]},"examples":[{"en":"It seems unfair on him to make him pay for everything.","cn":"让他承担一切费用似乎对他不公平。"},{"en":"The tests discriminate unfairly against older people.","cn":"这些测验使年纪较大的人受到歧视。"}]},"unimportant":{"media":{"uk":"media/uk/unimportant__gb_1.mp3","us":"media/us/unimportant__us_1.mp3"},"oxford":{"phon":"ˌʌnɪmˈpɔːtnt","pos":"adjective","senses":[{"en":"not important","cn":"不重要的；次要的；无足轻重的","ex":{"en":"unimportant details","cn":"细枝末节"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不重要的；无意义的；微不足道的","en":"If you describe something or someone as unimportant, you mean that they do not have much influence, effect, or value, and are therefore not worth serious consideration.","ex":{"en":"It was an unimportant job, and paid very little","cn":"这份工作无足轻重，而且薪水还很低。"}}]},"examples":[{"en":"I was just a young girl from a small town and I felt very unimportant.","cn":"当时我只是个从小镇出来的小女孩，自觉十分渺小。"},{"en":"They dismissed the problem as unimportant.","cn":"他们认为这个问题无关紧要而不予理会。"}]},"unregulated":{"oxford":{"phon":"ˌʌnˈreɡjuleɪtɪd","pos":"adjective","senses":[{"en":"not controlled by laws or regulations","cn":"不受法规约束的；不受管制的"}]},"media":{"uk":"media/uk/unregulated__gb_1.mp3","us":"media/us/unregulated__us_2.mp3"},"examples":[{"en":"an unregulated banking system","cn":"无监管的银行系统"}]},"unimpressed":{"media":{"uk":"media/uk/unimpressed__gb_1.mp3","us":"media/us/unimpressed__us_1.mp3"},"oxford":{"phon":"ˌʌnɪmˈprest","pos":"adjective","senses":[{"en":"not thinking that somebody/something is particularly good, interesting, etc.; not impressed by somebody/something","cn":"印象平平的；无深刻印象的","ex":{"en":"Voters are unimpressed with his performance so far.","cn":"迄今为止选民对他的表现印象平平。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"没有留下深刻印象的；不以为然的","en":"If you are unimpressed by something or someone, you do not think they are very good, clever, or useful.","ex":{"en":"He was also very unimpressed by his teachers","cn":"他对他的老师也很不以为然。"}}]},"examples":[{"en":"Board members were unimpressed with the plan.","cn":"董事会成员对这个计划没有兴趣。"}]},"undressed":{"media":{"uk":"media/uk/undressed__gb_1.mp3","us":"media/us/undressed__us_1.mp3"},"oxford":{"phon":"ʌnˈdrest","pos":"adjective","senses":[{"en":"not wearing any clothes","cn":"赤裸；一丝不挂","ex":{"en":"She began to get undressed (= remove her clothes).","cn":"她开始脱去衣服。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未穿衣服的；裸体的；只穿睡衣的","en":"If you are undressed, you are wearing no clothes or your night clothes. If you get undressed, you take off your clothes.","ex":{"en":"Fifteen minutes later he was undressed and in bed","cn":"15分钟后他便穿了睡衣躺在床上了。"}}]},"examples":[{"en":"She began to get undressed (= remove her clothes).","cn":"她开始脱去衣服。"},{"en":"He started to get undressed (= to take his clothes off ) .","cn":"他开始脱光衣服。"}]},"unanswered":{"oxford":{"phon":"ʌnˈɑːnsəd","pos":"adjective","senses":[{"en":"that has not been answered","cn":"未回答的；未解答的；悬而未决的","ex":{"en":"Many questions about the crime remain unanswered.","cn":"这桩罪行涉及的许多问题仍然没有答案。"}},{"en":"that has not been replied to","cn":"未回复（或答复）的","ex":{"en":"unanswered letters","cn":"未答复的信件"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未予回答的；未得到回复的","en":"Something such as a question or letter that is unanswered has not been answered.","ex":{"en":"Some of the most important questions remain unanswered","cn":"最重要的一些问题依然没有答案。"}}]},"media":{"uk":"media/uk/unanswered__gb_1.mp3","us":"media/us/unanswered__us_1.mp3"},"examples":[{"en":"Many questions about the crime remain unanswered.","cn":"这桩罪行涉及的许多问题仍然没有答案。"},{"en":"unanswered letters","cn":"未答复的信件"}]},"unmade":{"media":{"uk":"media/uk/unmade__gb_1.mp3","us":"media/us/unmade__us_1.mp3"},"oxford":{"phon":"ˌʌnˈmeɪd","pos":"adjective","senses":[{"en":"an unmade bed is not ready for sleeping in because the sheets, etc. have not been arranged neatly","cn":"（床）未铺好的"},{"en":"an unmade road does not have a hard, smooth surface","cn":"（道路）未铺路面的","lab":"British English"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（床铺）没整理好的","en":"An unmade bed has not had the sheets and covers neatly arranged after it was last slept in."}]}},"unavailable":{"oxford":{"phon":"ˌʌnəˈveɪləbl","pos":"adjective","senses":[{"en":"that cannot be obtained","cn":"得不到；无法得到","ex":{"en":"Such luxuries are unavailable to ordinary people.","cn":"此等奢侈品普通百姓是难以获得的。"}},{"en":"not able or not willing to see, meet or talk to somebody","cn":"不能（或不愿）见面；不能（或不愿）交谈","ex":{"en":"The minister was unavailable for comment.","cn":"部长无法接受访问作出评论。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"弄不到的；得不到的；不方便的","en":"When things or people are unavailable, you cannot obtain them, meet them, or talk to them.","ex":{"en":"Mr Hicks is out of the country and so unavailable for comment","cn":"希克斯先生目前不在国内，所以无法发表评论。"}}]},"media":{"uk":"media/uk/unavailable__gb_1.mp3","us":"media/us/unavailable__us_1.mp3"},"examples":[{"en":"Such luxuries are unavailable to ordinary people.","cn":"此等奢侈品普通百姓是难以获得的。"},{"en":"The minister was unavailable for comment.","cn":"部长无暇接受访问作出评论。"}]},"user":{"oxford":{"phon":"ˈjuːzə(r)","pos":"noun","senses":[{"en":"a person or thing that uses something","cn":"使用者；用户","ex":{"en":"road users","cn":"道路的使用者"}},{"en":"a person who uses illegal drugs","cn":"瘾君子；吸毒者","lab":"slang"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"使用者；用户","en":"A user is a person or thing that uses something such as a place, facility, product, or machine.","ex":{"en":"Beach users have complained about people walking their dogs on the sand.","cn":"海滩上的游客投诉有人在沙滩上遛狗。"}}]},"media":{"uk":"media/uk/user__gb_1.mp3","us":"media/us/user__us_1.mp3"},"examples":[{"en":"road users","cn":"道路的使用者"},{"en":"computer software users","cn":"电脑软件用户"}]},"ussr":{"oxford":{"phon":"ˌjuː es es ˈɑː(r)","pos":"abbreviation","senses":[{"en":"(the former) Union of Soviet Socialist Republics","cn":"苏联；苏维埃社会主义共和国联盟"}]},"media":{"uk":"media/uk/ussr__gb_1.mp3","us":"media/us/ussr__us_1.mp3"}},"unhealthy":{"oxford":{"phon":"ʌnˈhelθi","pos":"adjective","senses":[{"en":"not having good health; showing a lack of good health","cn":"不健康的；虚弱的","ex":{"en":"They looked poor and unhealthy.","cn":"他们看起来贫病交加。"}},{"en":"harmful to your health; likely to make you ill","cn":"损害健康的；对身体有害的；会致病的","ex":{"en":"unhealthy living conditions","cn":"有碍健康的生活条件"}},{"en":"not normal and likely to be harmful","cn":"反常的；不良的；有害的","ex":{"en":"He had an unhealthy interest in disease and death.","cn":"他对疾病与死亡有一种病态的兴趣。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"可能致病的；不健康的","en":"Something that is unhealthy is likely to cause illness or poor health.","ex":{"en":"Avoid unhealthy foods such as hamburger and chips","cn":"不要吃不健康食品，如汉堡和薯条。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不舒服的；身体不适的","en":"If you are unhealthy, you are not very fit or well.","ex":{"en":"I'm quite unhealthy really.","cn":"我真的很不舒服。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（经济体或公司）状况不佳的，面临财务危机的","en":"An unhealthy economy or company is financially weak and unsuccessful.","ex":{"en":"The redundancy of skilled and experienced workers is a terrible waste and a clear sign of an unhealthy economy.","cn":"技术熟练、经验丰富的工人过剩是可怕的浪费，也是经济运行不良的明显征兆。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（行为或爱好）不正常的，病态的","en":"If you describe someone's behaviour or interests as unhealthy, you do not consider them to be normal and think they may involve mental problems.","ex":{"en":"Frank has developed what I would term an unhealthy relationship with these people","cn":"弗兰克与这些人的关系在我看来不正常。"}}]},"media":{"uk":"media/uk/unhealthy__gb_1.mp3","us":"media/us/unhealthy__us_1.mp3"},"examples":[{"en":"He had an unhealthy interest in disease and death.","cn":"他对疾病与死亡有一种病态的兴趣。"},{"en":"His eyeballs were an unhealthy yellow.","cn":"他的眼球是不健康的蜡黄色。"}]},"uniqueness":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if something or someone is different, they are not like something or someone else, or they are not like they were before","cn":""},{"en":"very different, special, or unusual and the only one of its kind. Don’t use words such as very before unique","cn":""}]},"examples":[{"en":"This is a unique opportunity to study these rare creatures.","cn":"","src":"ld"},{"en":"Each person’s fingerprints are unique.","cn":"","src":"ld"}],"media":{"uk":"media/uk/uniqueness__gb_1.mp3","us":"media/us/uniqueness__us_1.mp3"},"oxford":{"phon":"juˈniːknəs","pos":"noun","senses":[{"en":"the fact of being the only one of its kind","cn":"成为同类中唯一","ex":{"en":"The author stresses the uniqueness of the individual.","cn":"作者强调每个人都是独一无二的。"}},{"en":"the quality of being very special or unusual","cn":"非常特殊或不寻常的性质","ex":{"en":"the uniqueness of his style of writing","cn":"他的写作风格的独特性"}}]}},"unconsciously":{"media":{"uk":"media/uk/unconsciously__gb_1.mp3","us":"media/us/unconsciously__us_1.mp3"},"oxford":{"phon":"ʌnˈkɒnʃəsli","pos":"adverb","senses":[{"en":"without being aware","cn":"无意地；不知不觉地","ex":{"en":"Perhaps, unconsciously, I've done something to offend her.","cn":"我也许无意中做了什么得罪她的事。"}}]},"examples":[{"en":"Perhaps, unconsciously, I've done something to offend her.","cn":"我也许无意中做了什么得罪她的事。"},{"en":"She was found alive but unconscious.","cn":""}]},"unfailing":{"media":{"uk":"media/uk/unfailing__gb_1.mp3","us":"media/us/unfailing__us_1.mp3"},"oxford":{"phon":"ʌnˈfeɪlɪŋ","pos":"adjective","senses":[{"en":"that you can rely on to always be there and always be the same","cn":"可靠的；一贯的；永久的","ex":{"en":"unfailing support","cn":"一贯的支持"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"一贯的；永恒的","en":"If you describe someone's good qualities or behaviour as unfailing, you mean that they never change.","ex":{"en":"He had the unfailing care and support of Erica, his wife","cn":"他的妻子埃丽卡始终如一地关心和支持着他。"}}]},"examples":[{"en":"She fought the disease with unfailing good humour.","cn":"她始终抱乐观态度同疾病斗争。"},{"en":"unfailingly loyal/polite","cn":"一贯地忠心耿耿/彬彬有礼"}]},"unrolls":{"oxford":{"phon":"ʌnˈrəʊl","pos":"verb","senses":[{"en":"if you unroll paper, cloth, etc. that was in a roll or if it unrolls , it opens and becomes flat （","cn":"使纸张、织物等）展开，摊开，铺开"},{"en":"to happen one after another in a series","cn":"相继出现；连续发生"}]},"media":{"uk":"media/uk/unroll__gb_1.mp3","us":"media/us/unroll__us_1.mp3"}},"unintended":{"media":{"uk":"media/uk/unintended__gb_1.mp3","us":"media/us/unintended__us_1.mp3"},"oxford":{"phon":"ˌʌnɪnˈtendɪd","pos":"adjective","senses":[{"en":"an unintended effect, result or meaning is one that you did not plan or intend to happen","cn":"非计划的；无意的；无心的","ex":{"en":"In law you are considered responsible for the unintended consequences of your actions.","cn":"法律认为人应对自己行为的意外后果负责。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"无意的；不是存心的","en":"Unintended results were not planned to happen, although they happened.","ex":{"en":"...the unintended consequences of human action.","cn":"人的行为无意中造成的后果"}}]}},"utterance":{"oxford":{"phon":"ˈʌtərəns","pos":"noun","senses":[{"en":"the act of expressing something in words","cn":"用言语的表达；说话","g":"[uncountable]","ex":{"en":"You may feel moved to give utterance to your thoughts.","cn":"您可能会因为说出自己的想法而感到感动。"}},{"en":"something that you say","cn":"话语；言论","g":"[countable]","ex":{"en":"This was one of her few recorded public utterances.","cn":"这是她为数不多的公开言论录音之一。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"言辞；言语；言论","en":"Someone's utterances are the things that they say.","ex":{"en":"...the Queen's public utterances.","cn":"女王的公开讲话"}},{"pos":"N-UNCOUNT 不可数名词","cn":"吐露；表达","en":"Utterance is the expression in words of ideas, thoughts, and feelings.","ex":{"en":"She could choose her own partner in matrimony, as long as she gave no utterance to her passions and emotions.","cn":"只要她不表露她的激情和情感，她就可以选择自己的婚姻伴侣。"}}]},"media":{"uk":"media/uk/utterance__gb_1.mp3","us":"media/us/utterance__us_1.mp3"},"examples":[{"en":"one of her few recorded public utterances","cn":"她仅有的几次公开讲话录音之一"},{"en":"to give utterance to your thoughts","cn":"把你的想法说出来"}]},"underwater":{"media":{"uk":"media/uk/underwater__gb_1.mp3","us":"media/us/underwater__us_1.mp3"},"oxford":{"phon":"ˌʌndəˈwɔːtə(r)","pos":"adverb","senses":[{"en":"below the surface of water","cn":"在水下","ex":{"en":"They escaped by swimming underwater.","cn":"他们通过游泳逃脱。"}},{"en":"found, used or happening below the surface of water","cn":"水下的；用于水下的；水下发生的","ex":{"en":"an underwater camera/photographer","cn":"水下摄影机／摄影师"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"在水下；在水中","en":"Something that exists or happens underwater exists or happens below the surface of the sea, a river, or a lake.","ex":{"en":"...giant submarines able to travel at high speeds underwater","cn":"能够在水下高速行进的巨型潜艇"}},{"pos":"ADJ 形容词","cn":"供水下用的","en":"Underwater devices are specially made so that they can work in water.","ex":{"en":"...underwater camera equipment.","cn":"水下摄影器材"}}]},"examples":[{"en":"Take a deep breath and see how long you can stay underwater.","cn":"深吸一口气，看你能在水里待多久。"},{"en":"an underwater camera","cn":"水下摄影机"}]},"unique":{"media":{"uk":"media/uk/unique__gb_1.mp3","us":"media/us/unique__us_1.mp3"},"oxford":{"phon":"juˈniːk","pos":"adjective","senses":[{"en":"being the only one of its kind","cn":"唯一的；独一无二的","ex":{"en":"Everyone's fingerprints are unique.","cn":"每个人的指纹都是独一无二的。"}},{"en":"very special or unusual","cn":"独特的；罕见的","ex":{"en":"The preview offers a unique opportunity to see the show without the crowds.","cn":"预展提供了看展览但不挨挤的难得机会。"}},{"en":"belonging to or connected with one particular person, place or thing","cn":"（某人、地或事物）独具的，特有的","ex":{"en":"an atmosphere that is unique to New York","cn":"纽约所独具的气氛"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"唯一的；独一无二的","en":"Something that is unique is the only one of its kind.","ex":{"en":"Each person's signature is unique","cn":"每个人的签名都是独一无二的。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"独特的；无与伦比的","en":"You can use unique to describe things that you admire because they are very unusual and special.","ex":{"en":"Brett's vocals are just unique","cn":"布雷特的歌声无与伦比。"}},{"pos":"ADJ 形容词","cn":"独有的；特有的","en":"If something is unique to one thing, person, group, or place, it concerns or belongs only to that thing, person, group, or place.","ex":{"en":"No one knows for sure why adolescence is unique to humans","cn":"没有人确切地知道为什么只有人类才会经历青春期。"}}]},"examples":[{"en":"The deal will put the company in a unique position to export goods to Eastern Europe.","cn":"这项协议给予这家公司向东欧输出商品的特殊地位。"},{"en":"Her past experience made her uniquely suited to lead the campaign.","cn":"她以往的经历使她格外适合领导这场运动。"}]},"unrelated":{"media":{"uk":"media/uk/unrelated__gb_1.mp3","us":"media/us/unrelated__us_1.mp3"},"oxford":{"phon":"ˌʌnrɪˈleɪtɪd","pos":"adjective","senses":[{"en":"not connected; not related to something else","cn":"无关联的；不相关的","ex":{"en":"The two events were totally unrelated.","cn":"这两件事毫不相干。"}},{"en":"not belonging to the same family","cn":"不属于同一家族（或同一科等）的；无亲缘关系的","ex":{"en":"They have the same name but are, in fact, unrelated.","cn":"它们具有相同的名称，但实际上无关。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"没关联的；没联系的","en":"If one thing is unrelated to another, there is no connection between them. You can also say that two things are unrelated .","ex":{"en":"My line of work is entirely unrelated to politics","cn":"我的职业与政治完全无关。"}},{"pos":"ADJ 形容词","cn":"不属于同一家族的；没有亲属关系的","en":"If one person is unrelated to another, they are not members of the same family. You can also say that two people are unrelated .","ex":{"en":"Jimmy is adopted and thus unrelated to Beth by blood.","cn":"吉米是被收养的，因此和贝丝没有血缘关系。"}}]},"examples":[{"en":"The two events were totally unrelated.","cn":"这两件事互不相干。"},{"en":"The police think that the two incidents are unrelated.","cn":"警方认为这两个事件互不相关。"}]},"useful":{"media":{"uk":"media/uk/useful__gb_1.mp3","us":"media/us/useful__us_1.mp3"},"oxford":{"phon":"ˈjuːsfl","pos":"adjective","senses":[{"en":"that can help you to do or achieve what you want","cn":"有用的；有益的；实用的；有帮助的","ex":{"en":"a useful tool","cn":"有用的工具"}},{"en":"good; of the right standard","cn":"好的；合格的","lab":"British English, informal，，","ex":{"en":"He's a very useful player.","cn":"他是个很棒的运动员。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有用的；可用的；有助益的","en":"If something is useful, you can use it to do something or to help you in some way.","ex":{"en":"The slow cooker is very useful for people who go out all day","cn":"慢炖锅对于整天都不在家的人来说很有用。"}},{"pos":"PHRASE 短语","cn":"有用；派得上用场","en":"If an object or skill comes in useful, it can help you achieve something in a particular situation.","ex":{"en":"The accommodation is some distance from the clubhouse, so a hire car comes in useful.","cn":"住处离会所有一段距离，所以租一辆车会很有用。"}}]},"examples":[{"en":"Some products can be recycled at the end of their useful life.","cn":"有些产品过了有效使用年限后是可以回收再利用的。"},{"en":"These plants are particularly useful for brightening up shady areas.","cn":"这些植物特别有助于让背阴的地方明亮起来。"}]},"umbrella":{"oxford":{"phon":"ʌmˈbrelə","pos":"noun","senses":[{"en":"an object with a round folding frame of long, straight pieces of metal covered with material, that you use to protect yourself from the rain or from hot sun","cn":"伞；雨伞；阳伞","lab":"also British English, informal，，","ex":{"en":"to carry/hold an umbrella","cn":"拿着／撑着雨伞"}},{"en":"a thing that contains or includes many different parts or elements","cn":"综合体；总体；整体","ex":{"en":"Many previously separate groups are now operating under the umbrella of a single authority.","cn":"许多原本分散的团体现归一个单一的机构领导。"}},{"en":"a country or system that protects people","cn":"保护国（或体系）；保护伞；庇护","ex":{"en":"the American nuclear umbrella over Europe","cn":"美国向欧洲提供的核保护伞"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"伞；雨伞；阳伞","en":"An umbrella is an object which you use to protect yourself from the rain or hot sun. It consists of a long stick with a folding frame covered in cloth.","ex":{"en":"Harry held an umbrella over Dawn.","cn":"哈里为唐打着伞。"}},{"pos":"N-SING 单数名词","cn":"综合团体；总称；统称","en":"Umbrella is used to refer to a single group or description that includes a lot of different organizations or ideas.","ex":{"en":"Does coincidence come under the umbrella of the paranormal?","cn":"巧合属于超自然现象吗？"}},{"pos":"N-SING 单数名词","cn":"保护伞（指保护某个国家或群体的体制或协议）","en":"Umbrella is used to refer to a system or agreement which protects a country or group of people.","ex":{"en":"The major powers have chosen to act under the moral umbrella of the United Nations","cn":"世界主要大国都选择在联合国的道义框架下行事。"}}]},"media":{"uk":"media/uk/umbrella__gb_1.mp3","us":"media/us/umbrella__us_1.mp3","img":["media/ldoce/img/umbrella.jpg"]},"examples":[{"en":"Many previously separate groups are now operating under the umbrella of a single authority.","cn":"许多原本分散的团体现归一个单一的机构领导。"},{"en":"‘Contact sports’ is an umbrella term for a variety of different sports. “","cn":"接触式运动”是多种不同体育运动的总称。"}]},"unnoticed":{"media":{"uk":"media/uk/unnoticed__gb_1.mp3","us":"media/us/unnoticed__us_1.mp3"},"oxford":{"phon":"ˌʌnˈnəʊtɪst","pos":"adjective","senses":[{"en":"not seen or noticed","cn":"未被看见；未受到注意；被忽视","ex":{"en":"His kindness did not go unnoticed by his staff.","cn":"他的厚道员工了然于心。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未被看见的；未引起注意的；被忽视的","en":"If something happens or passes unnoticed, it is not seen or noticed by anyone.","ex":{"en":"I tried to slip up the stairs unnoticed","cn":"我试图趁没人注意溜上楼去。"}}]},"examples":[{"en":"His kindness did not go unnoticed by his staff.","cn":"他的厚道员工了然于心。"},{"en":"Elsa stood unnoticed at the edge of the crowd.","cn":"埃尔莎悄悄地站在人群边上。"}]},"unchanged":{"oxford":{"phon":"ʌnˈtʃeɪndʒd","pos":"adjective","senses":[{"en":"that has stayed the same and not changed","cn":"不变；没有变化","ex":{"en":"My opinion remains unchanged.","cn":"我的看法一如既往。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（一段时间内）未改变的，不变的","en":"If something is unchanged, it has stayed the same for a particular period of time.","ex":{"en":"For many years prices have remained virtually unchanged","cn":"价格多年来几乎没变。"}}]},"media":{"uk":"media/uk/unchanged__gb_1.mp3","us":"media/us/unchanged__us_1.mp3"},"examples":[{"en":"My opinion remains unchanged.","cn":"我的看法一如既往。"}]},"usa":{"collins":{"senses":[{"pos":"N-PROPER 专有名词","cn":"美国","en":"The USA is an abbreviation for (缩略=) the United States of America .","ex":{"en":"In the USA you can ring Social Security or the Department of Welfare and ask what help is available.","cn":"在美国，你可以致电社会保障部或福利部询问能得到何种帮助。"}},{"pos":"N-PROPER 专有名词","cn":"美国陆军","en":"USA is an abbreviation for (缩略=) United States Army ."}]},"media":{"uk":"media/uk/usa__gb_1.mp3","us":"media/us/usa__us_1.mp3"},"examples":[{"en":"Do you need a visa for the USA?","cn":"你需要美国签证吗？"}],"oxford":{"phon":"ˌjuː es ˈeɪ","pos":"abbreviation","senses":[{"en":"United States of America","cn":"美国；美利坚合众国","ex":{"en":"Do you need a visa for the USA?","cn":"你需要美国签证吗？"}}]}},"uninterested":{"oxford":{"phon":"ʌnˈɪntrəstɪd","pos":"adjective","senses":[{"en":"not interested; not wanting to know about somebody/something","cn":"不感兴趣的；冷淡的；漠不关心的","ex":{"en":"He was totally uninterested in sport.","cn":"他对体育运动毫无兴趣。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不感兴趣的；不关心的","en":"If you are uninterested in something or someone, you do not want to know any more about them, because you think they have no special or exciting qualities.","ex":{"en":"I was so uninterested in the result that I didn't even bother to look at it.","cn":"我对结果完全没兴趣，甚至都懒得看一眼。"}}]},"media":{"uk":"media/uk/uninterested__gb_1.mp3","us":"media/us/uninterested__us_1.mp3"},"examples":[{"en":"She seemed cold and uninterested.","cn":"她似乎很冷漠且不感兴趣。"},{"en":"He was totally uninterested in sport.","cn":"他对体育运动毫无兴趣。"}]},"unfriendly":{"oxford":{"phon":"ʌnˈfrendli","pos":"adjective","senses":[{"en":"not kind or pleasant to somebody","cn":"不友好的；冷漠的；有敌意的","ex":{"en":"an unfriendly atmosphere","cn":"不友好的气氛"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不友好的；不友善的；有敌意的","en":"If you describe a person, organization, or their behaviour as unfriendly, you mean that they behave towards you in an unkind or rather hostile way.","ex":{"en":"It is not fair for him to be permanently unfriendly to someone who has hurt him","cn":"他对伤害过自己的人永远存有敌意，这样是不对的。"}}]},"media":{"uk":"media/uk/unfriendly__gb_1.mp3","us":"media/us/unfriendly__us_1.mp3"},"examples":[{"en":"There's no need to be so unfriendly towards them.","cn":"没必要对他们这么不客气。"},{"en":"the use of environmentally unfriendly products (= that harm the environment)","cn":"危害环境的产品的使用"}]},"unauthorized":{"media":{"uk":"media/uk/unauthorized__gb_1.mp3","us":"media/us/unauthorized__us_1.mp3"},"oxford":{"phon":"ʌnˈɔːθəraɪzd","pos":"adjective","senses":[{"en":"without official permission","cn":"未经许可（或批准）的","ex":{"en":"No access for unauthorized personnel.","cn":"未经允许不得入内。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未经授权的；未经许可的","en":"If something is unauthorized, it has been produced or is happening without official permission.","ex":{"en":"...a new unauthorized biography of the Russian President.","cn":"一本新的未经授权的俄罗斯总统传记"}}]},"examples":[{"en":"No access for unauthorized personnel.","cn":"未经允许不得入内。"},{"en":"the unauthorized use of government funds","cn":"对政府资金的擅自动用"}]},"unacceptable":{"media":{"uk":"media/uk/unacceptable__gb_1.mp3","us":"media/us/unacceptable__us_1.mp3"},"oxford":{"phon":"ˌʌnəkˈseptəbl","pos":"adjective","senses":[{"en":"so bad that you think it should not be allowed","cn":"不能接受的；不被允许的","ex":{"en":"Such behaviour is totally unacceptable in a civilized society.","cn":"这种行为在文明社会是完全不能接受的。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"难以接受的；不能容忍的","en":"If you describe something as unacceptable, you strongly disapprove of it or object to it and feel that it should not be allowed to continue.","ex":{"en":"It is totally unacceptable for children to swear","cn":"孩子说脏话是完全不能容忍的。"}}]},"examples":[{"en":"Such behaviour is totally unacceptable in a civilized society.","cn":"这种行为在文明社会是完全不能接受的。"},{"en":"Noise from the factory has reached an unacceptable level.","cn":"工厂的噪声达到了难以容忍的地步。"}]},"undershirt":{"media":{"uk":"media/uk/undershirt__gb_1.mp3","us":"media/us/undershirt__us_1.mp3"},"oxford":{"phon":"ˈʌndəʃɜːt","pos":"noun","senses":[{"en":"a piece of underwear worn under a shirt, etc. next to the skin","cn":"（衬衣等里面贴身穿的）背心，汗衫","ex":{"en":"He was standing there in his undershirt and shorts.","cn":"他穿着背心和短裤站在那儿。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"贴身内衣；汗衫；背心","en":"An undershirt is a piece of clothing that you wear on the top half of your body next to your skin in order to keep warm.","ex":{"en":"He put on a pair of short pants and an undershirt.","cn":"他穿上了一条短裤和一件汗衫。"}}]}},"unemployed":{"media":{"uk":"media/uk/unemployed__gb_1.mp3","us":"media/us/unemployed__us_1.mp3"},"oxford":{"phon":"ˌʌnɪmˈplɔɪd","pos":"adjective","senses":[{"en":"without a job although able to work","cn":"失业的；待业的；下岗的","lab":"British English","ex":{"en":"How long have you been unemployed?","cn":"你失业多久了？"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未受雇用的；失业的","en":"Someone who is unemployed does not have a job.","ex":{"en":"The problem is millions of people are unemployed","cn":"问题是，大批的人都失业了。"}}]},"examples":[{"en":"a programme to get the long-term unemployed back to work","cn":"协助长期失业者恢复工作的计划"},{"en":"I've joined the ranks of the unemployed (= I've lost my job).","cn":"我加入了失业者的行列。"}]},"users":{"oxford":{"phon":"ˈjuːzə(r)","pos":"noun","senses":[{"en":"a person or thing that uses sth","cn":"使用者；用户"},{"en":"( slang ) a person who uses illegal drugs","cn":"瘾君子；吸毒者"}]}},"unnecessary":{"oxford":{"phon":"ʌnˈnesəsəri","pos":"adjective","senses":[{"en":"not needed; more than is needed","cn":"不需要的；不必要的；多余的","ex":{"en":"They were found guilty of causing unnecessary suffering to animals.","cn":"他们因虐待动物而被判有罪。"}},{"en":"not needed in the situation and likely to be offensive","cn":"不必要（且容易开罪于人）的","ex":{"en":"That last comment was a little unnecessary, wasn't it?","cn":"那最后一点评论有点多余，是吧？"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不需要的；没必要的；多余的","en":"If you describe something as unnecessary, you mean that it is not needed or does not have to be done, and is undesirable.","ex":{"en":"The slaughter of whales is unnecessary and inhuman","cn":"屠杀鲸鱼是没有必要的也是不人道的。"}}]},"media":{"uk":"media/uk/unnecessary__gb_1.mp3","us":"media/us/unnecessary__us_1.mp3"},"examples":[{"en":"That last comment was a little unnecessary, wasn't it?","cn":"那最后一点评论有点多余，是吧？"},{"en":"They were found guilty of causing unnecessary suffering to animals.","cn":"他们因虐待动物而被判有罪。"}]},"understand":{"media":{"uk":"media/uk/understand__gb_1.mp3","us":"media/us/understand__us_1.mp3"},"oxford":{"phon":"ˌʌndəˈstænd","pos":"verb","senses":[{"en":"to know or realize the meaning of words, a language, what somebody says, etc.","cn":"懂；理解；领会","g":"[transitive, intransitive]","sc":"meaning","ex":{"en":"Can you understand French?","cn":"你懂法语吗？"}},{"en":"to know or realize how or why something happens, how it works or why it is important","cn":"了解；认识到；明了","g":"[transitive]","lab":"formal","sc":"how something works/happens","ex":{"en":"Doctors still don't understand much about the disease.","cn":"医生对这种疾病仍了解不多。"}},{"en":"to know somebody’s character, how they feel and why they behave in the way they do","cn":"了解；谅解；体谅","g":"[transitive, intransitive]","lab":"formal","sc":"know somebody","ex":{"en":"Nobody understands me.","cn":"没有人了解我。"}},{"en":"to think or believe that something is true because you have been told that it is","cn":"得知；据信；认为","g":"[transitive]","lab":"formal","sc":"think/believe","ex":{"en":"I understand (that) you wish to see the manager.","cn":"我听说您想见经理。"}},{"en":"to agree something with somebody without it needing to be said","cn":"默认；默许；不言而喻","g":"[transitive]","sc":"be agreed","ex":{"en":"I thought it was understood that my expenses would be paid.","cn":"我原以为对方已同意支付我的费用。"}},{"en":"to realize that a word in a phrase or sentence is not expressed and to supply it in your mind","cn":"领会；清楚；推断出","g":"[transitive, usually passive]","sc":"missing word","ex":{"en":"In the sentence ‘I can't drive’, the object ‘a car’ is understood.","cn":"在 I can’t drive 一句中，宾语 a car 是不言自明的。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"理解；明白；听懂","en":"If you understand someone or understand what they are saying, you know what they mean.","ex":{"en":"I think you heard and also understand me","cn":"我想你听到了我的话，也明白我的意思。"}},{"pos":"VERB 动词","cn":"懂（某种语言）","en":"If you understand a language, you know what someone is saying when they are speaking that language.","ex":{"en":"I couldn't read or understand a word of Yiddish, so I asked him to translate.","cn":"我根本不懂意第绪语，所以请他来翻译。"}},{"pos":"VERB 动词","cn":"理解（某人）","en":"To understand someone means to know how they feel and why they behave in the way that they do.","ex":{"en":"It would be nice to have someone who really understood me, a friend","cn":"要是有个真正理解我的人、有个朋友就好了。"}},{"pos":"VERB 动词","cn":"知道，明白，了解（所发生的事及其原因）","en":"You say that you understand something when you know why or how it happens.","ex":{"en":"They are too young to understand what is going on","cn":"他们还太小，不明白发生了什么事。"}},{"pos":"VERB 动词","cn":"听说；获悉；了解","en":"If you understand that something is the case, you think it is true because you have heard or read that it is. You can say that something is understood to be the case to mean that people generally think it is true.","ex":{"en":"We understand that she's in the studio recording her second album","cn":"我们听说她正在录音棚录制她的第二张专辑。"}},{"pos":"PHRASE 短语","cn":"获悉，间接得知","en":"If someone is given to understand that something is the case, it is communicated to them that it is the case, usually without them being told directly.","ex":{"en":"I am given to understand that he was swearing throughout the game at our fans.","cn":"我得知整场比赛中他一直冲着我方球迷骂个不停。"}},{"pos":"CONVENTION 惯用语","cn":"明白吗？懂了没有？","en":"You can use understand in expressions like do you understand? or is that understood? after you have told someone what you want, to make sure that they have understood you and will obey you.","ex":{"en":"You do not hit my grandchildren, do you understand?","cn":"你不准打我的孙子孙女，明白吗？"}}]},"examples":[{"en":"In the sentence ‘I can't drive’, the object ‘a car’ is understood.","cn":"在 I can't drive 一句中，可推测出宾语 a car 被省略了。"},{"en":"He was the first to understand that we live in a knowledge economy.","cn":"他最早认识到我们正处于知识经济的时代。"}]},"understanding":{"media":{"uk":"media/uk/understanding__gb_1.mp3","us":"media/us/understanding__us_1.mp3"},"oxford":{"phon":"ˌʌndəˈstændɪŋ","pos":"noun","senses":[{"en":"the knowledge that somebody has about a particular subject or situation","cn":"理解；领悟；了解","g":"[uncountable, singular]","ex":{"en":"Students will gain a broad understanding of the workings of Parliament.","cn":"学生将对议会的运作有个大致的了解。"}},{"en":"the ability to understand why people behave in a particular way and to forgive them when they do something wrong","cn":"理解；谅解；体谅","g":"[uncountable, singular]","ex":{"en":"Organizers of the rally say they want to promote understanding, tolerance and open-mindedness.","cn":"集会的组织者说他们希望促进谅解、宽容和开明。"}},{"en":"an informal agreement","cn":"（非正式的）协议","g":"[countable, usually singular]","ex":{"en":"We finally came to an understanding about what hours we would work.","cn":"我们最终就工作时间问题取得了一致意见。"}},{"en":"the particular way in which somebody understands something","cn":"理解；看法；解释；意见","g":"[uncountable, countable]","ex":{"en":"My understanding of the situation is different.","cn":"我对形势的看法不同。"}},{"en":"showing sympathy for other people’s problems and being willing to forgive them when they do something wrong","cn":"善解人意的；富有同情心的；体谅人的","ex":{"en":"She has very understanding parents.","cn":"她的父母非常宽容。"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"了解；掌握；知识","en":"If you have an understanding of something, you know how it works or know what it means.","ex":{"en":"They have to have a basic understanding of computers in order to use the advanced technology.","cn":"要想利用先进技术，他们必须先对计算机有个基本的了解。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"能谅解的；宽容的；通情达理的","en":"If you are understanding towards someone, you are kind and forgiving.","ex":{"en":"Her boss, who was very understanding, gave her time off","cn":"她的老板很通情达理，准了她的假。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"理解；谅解","en":"If you show understanding, you show that you realize how someone feels or why they did something, and are not hostile towards them.","ex":{"en":"We would like to thank them for their patience and understanding.","cn":"我们要感谢他们的耐心和理解。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"相互理解；友好互信","en":"If there is understanding between people, they are friendly towards each other and trust each other.","ex":{"en":"There was complete understanding between Wilson and myself.","cn":"我和威尔逊之间完全能够彼此理解，相互信任。"}},{"pos":"N-COUNT 可数名词","cn":"（非正式的）协议","en":"An understanding is an informal agreement about something.","ex":{"en":"We had not set a date for marriage but there was an understanding between us.","cn":"我们还没有确定结婚的日子，不过我们对此有一致的想法。"}},{"pos":"N-SING 单数名词","cn":"了解；领会；理解","en":"If you say that it is your understanding that something is the case, you mean that you believe it to be the case because you have heard or read that it is.","ex":{"en":"It is my understanding that this torture has been going on for many years","cn":"据我了解，这种折磨已经持续很多年了。"}},{"pos":"PHR-CONJ-SUBORD","cn":"以…为条件；假如","en":"If you agree to do something on the understanding that something else will be done, you do it because you have been told that the other thing will definitely be done.","ex":{"en":"Kevin had treatment on the understanding that he would attempt to overcome his drinking problem.","cn":"凯文接受了治疗，但条件是他要努力克服自身的酗酒问题。"}}]},"examples":[{"en":"We must tackle the problem with sympathy and understanding.","cn":"我们必须以同情和谅解的态度来处理这个问题。"},{"en":"The committee has little or no understanding of the problem.","cn":"委员会对这个问题了解不多或根本不了解。"}]},"upgrade":{"media":{"uk":"media/uk/upgrade__gb_1.mp3","us":"media/us/upgrade__us_1.mp3"},"oxford":{"phon":"ˌʌpˈɡreɪd","pos":"verb","senses":[{"en":"to make a machine, computer system, etc. more powerful and efficient; to start using a new and better version of a machine, system, etc.","cn":"升级，改进（机器、计算机系统等）；开始使用（升级版）","g":"[transitive, intransitive]","ex":{"en":"We are constantly upgrading our software to meet customers' needs.","cn":"我们不断升级软件以满足用户的需要。"}},{"en":"to improve the condition of a building, etc. in order to provide a better service","cn":"提高（设施、服务等的）档次；改善；使升格","g":"[transitive]","ex":{"en":"to upgrade the town’s leisure facilities","cn":"改善镇里的休闲设施"}},{"en":"to give somebody a better seat on a plane, room in a hotel, etc. than the one that they have paid for","cn":"升级（机票舱位、旅馆客房等）","g":"[transitive, often passive]","ex":{"en":"On the flight back, we were upgraded to business class.","cn":"返程时，我们升级到了公务舱。"}},{"en":"to give somebody a more important job","cn":"提升；提拔","g":"[transitive]"},{"en":"the act of making a machine, computer system, etc. more powerful and efficient; the more powerful and efficient machine, computer system, etc.","cn":"（机器、计算机系统等的）升级，升级版","ex":{"en":"instructions for installing an upgrade to the existing system","cn":"现有系统升级安装说明"},"pos":"noun"},{"en":"the act of improving the condition of a building, etc. in order to provide a better service","cn":"（设施、服务等的）提高档次，改善，升格","ex":{"en":"The building urgently needs an upgrade.","cn":"该建筑迫切需要升级。"},"pos":"noun"},{"en":"the act of giving somebody a better seat on a plane, room in a hotel, etc. than the one that they paid for; the seat, room, etc. itself","cn":"（舱位、旅馆房间等的）升级；升级的舱位（或房间等）","ex":{"en":"Frequent flyers qualify for a free upgrade.","cn":"常旅客有资格享受免费升舱。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"改良；更新；升级","en":"If equipment or services are upgraded, they are improved or made more efficient.","ex":{"en":"Helicopters have been upgraded and modernized","cn":"直升机已经更新换代，装配了现代化设备。"}},{"pos":"VERB 动词","cn":"擢升；晋升；提升；提拔","en":"If someone is upgraded, their job or status is changed so that they become more important or receive more money.","ex":{"en":"He was upgraded to security guard.","cn":"他被擢升为保安。"}},{"pos":"VERB 动词","cn":"(使)升级到更高待遇;(使)升舱","en":"If you upgrade or are upgraded, you change something such as your air ticket or your hotel room to one that is more expensive.","ex":{"en":"You can upgrade from self-catering accommodation to a hotel.","cn":"您可以将自理膳食旅店升级为酒店。"}}]},"examples":[{"en":"to upgrade the town's leisure facilities","cn":"改善镇里的休闲设施"},{"en":"You’ll need to upgrade your hard drive to 120Mb before running this software.","cn":"运行这个软件之前你需要把硬盘升级到120兆。"}]},"unlike":{"media":{"uk":"media/uk/unlike__gb_1.mp3","us":"media/us/unlike__us_1.mp3"},"oxford":{"phon":"ˌʌnˈlaɪk","pos":"preposition","senses":[{"en":"different from a particular person or thing","cn":"不像；与…不同","ex":{"en":"Music is quite unlike any other art form.","cn":"音乐与其他艺术形式迥然不同。"}},{"en":"used to contrast somebody/something with another person or thing","cn":"（用于对比）与…不同","ex":{"en":"Unlike most systems, this one is very easy to install.","cn":"本系统与多数系统不同，极易安装。"}},{"en":"not typical of somebody/something","cn":"非…的特征","ex":{"en":"It's very unlike him to be so late.","cn":"迟到这么久可实在不像他平时的作风。"}},{"en":"different from each other","cn":"不同；不像；相异","ex":{"en":"They are both teachers. Otherwise they are quite unlike.","cn":"他们两位都是教师；除此之外他们迥然不同。"},"pos":"adjective"},{"en":"to show, by clicking a special button, that you disagree with something on social media, a news website, a blog, etc.","cn":"（在社交媒体、新闻网站、博客等）踩，拍砖","pos":"verb"},{"en":"to not be liked by people; to be unpopular","cn":"不像：不被人们喜欢；不受欢迎","ex":{"en":"The article suggests his character was unliked by many.","cn":"这篇文章表明，许多人不喜欢他的性格。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"PREP 介词","cn":"不像；与…不同","en":"If one thing is unlike another thing, the two things have different qualities or characteristics from each other.","ex":{"en":"This was a foreign country, so unlike San Jose","cn":"这是外国，与圣何塞很不一样。"}},{"pos":"PREP 介词","cn":"与…相反","en":"You can use unlike to contrast two people, things, or situations, and show how they are different.","ex":{"en":"Unlike aerobics, walking entails no expensive fees for classes or clubs.","cn":"散步不像有氧健身操那样需要交纳昂贵的费用来参加健身班或俱乐部。"}},{"pos":"PREP 介词","cn":"与…平时不同；不像…平常那样","en":"If you describe something that a particular person has done as being unlike them, you mean that you are surprised by it because it is not typical of their character or normal behaviour.","ex":{"en":"It was so unlike him to say something like that, with such intensity, that I was astonished","cn":"他一反常态用如此强烈的语气说出那番话，着实让我吃惊。"}}]},"examples":[{"en":"They are both teachers. Otherwise they are quite unlike.","cn":"他们两位都是教师；除此之外他们迥然不同。"},{"en":"It's very unlike him to be so late.","cn":"迟到这么久可实在不像他平时的作风。"}]},"unconventional":{"oxford":{"phon":"ˌʌnkənˈvenʃənl","pos":"adjective","senses":[{"en":"not following what is done or considered normal or acceptable by most people; different and interesting","cn":"不因循守旧的；不因袭的；新奇的","ex":{"en":"an unconventional approach to the problem","cn":"解决这个问题的非常规方法"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（人、态度、行为）不遵循传统的，异于常人的，标新立异的","en":"If you describe a person or their attitude or behaviour as unconventional, you mean that they do not behave in the same way as most other people in their society.","ex":{"en":"Linus Pauling is an unconventional genius","cn":"莱纳斯·鲍林是个标新立异的天才人物。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（做事方式）非传统的，不寻常的，非一般的","en":"An unconventional way of doing something is not the usual way of doing it, and may be rather surprising.","ex":{"en":"The vaccine had been produced by an unconventional technique","cn":"该疫苗是用非传统工艺生产的。"}}]},"media":{"uk":"media/uk/unconventional__gb_1.mp3","us":"media/us/unconventional__us_1.mp3"},"examples":[{"en":"an unconventional approach to the problem","cn":"解决这个问题的非常规方法"},{"en":"unconventional views","cn":"新奇的观点"}]},"update":{"media":{"uk":"media/uk/update__gb_1.mp3","us":"media/us/update__us_1.mp3"},"oxford":{"phon":"ˌʌpˈdeɪt","pos":"verb","senses":[{"en":"to make something more modern by adding new parts, etc.","cn":"使现代化；更新","ex":{"en":"an updated version of the app","cn":"该应用的更新版"}},{"en":"to give somebody the most recent information about something; to add the most recent information to something","cn":"向…提供最新信息；给…增加最新信息","ex":{"en":"I'll be updating you shortly.","cn":"我很快就会向您通报最新情况。"}},{"en":"a report or broadcast that gives the most recent information about something; a new version of something containing the most recent information","cn":"最新报道；最新消息；最新进展","ex":{"en":"They will send you regular updates by email.","cn":"他们会发电邮定期告知你最新消息。"},"pos":"noun"},{"en":"the most recent improvements to a computer program that are sent to users of the program","cn":"（计算机程序的）更新，最新校正数据","lab":"computing","ex":{"en":"software updates","cn":"软件更新"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"更新；使现代化","en":"If you update something, you make it more modern, usually by adding new parts to it or giving new information.","ex":{"en":"He was back in the office, updating the work schedule on the computer","cn":"他已回到办公室，正在电脑上更新工作日程。"}},{"pos":"N-COUNT 可数名词","cn":"最新消息；快讯；速递","en":"An update is a news item containing the latest information about a particular situation.","ex":{"en":"She had heard the news-flash on a TV channel's news update.","cn":"她在一家电视台的新闻快讯中听到了这则简明新闻。"}},{"pos":"VERB 动词","cn":"为…提供最新消息；把最新进展告诉（某人）","en":"If you update someone on a situation, you tell them the latest developments in that situation.","ex":{"en":"We'll update you on the day's top news stories","cn":"我们将为您提供当天的重要新闻。"}}]},"examples":[{"en":"I called the office to update them on the day's developments.","cn":"我给办公室打电话告诉他们当天最新的发展。"},{"en":"It's about time we updated our software.","cn":"我们的软件应该更新了。"}]},"universe":{"media":{"uk":"media/uk/universe__gb_1.mp3","us":"media/us/universe__us_1.mp3"},"oxford":{"phon":"ˈjuːnɪvɜːs","pos":"noun","senses":[{"en":"the whole of space and everything in it, including the earth, the planets and the stars","cn":"宇宙；天地万物；万象","g":"[singular]","ex":{"en":"Could there be intelligent life elsewhere in the universe?","cn":"宇宙其他地方会有智慧生物吗？"}},{"en":"a system of stars, planets, etc. in space outside our own","cn":"（已知宇宙以外的）宇宙","g":"[countable]","lab":"figurative","ex":{"en":"The idea of a parallel universe is hard to grasp.","cn":"平行宇宙的概念是很难理解的。"}},{"en":"a particular area of experience or activity","cn":"（某种）经验（或活动）领域；体系","g":"[singular]","ex":{"en":"the moral universe","cn":"道德体系"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"宇宙","en":"The universe is the whole of space and all the stars, planets, and other forms of matter and energy in it.","ex":{"en":"Einstein's equations showed the Universe to be expanding","cn":"爱因斯坦的方程式表明宇宙正在膨胀。"}},{"pos":"N-COUNT 可数名词","cn":"经验领域","en":"If you talk about someone's universe, you are referring to the whole of their experience or an important part of it.","ex":{"en":"Good writers suck in what they see of the world, recreating their own universe on the page","cn":"优秀的作家从他们眼中的世界汲取体验，然后在纸上重塑自己的天地。"}},{"pos":"PHRASE 短语","cn":"全天下，宇宙万物中（最）","en":"If you say that something is, for example, the best or biggest thing of its kind in the universe, you are emphasizing that you think it is bigger or better than anything else of its kind.","ex":{"en":"According to my friends I am the coolest, thinnest, cleverest, funniest journalist in the universe.","cn":"我的朋友说我是全天下最酷、最瘦、最聪明、最幽默的记者。"}}]},"examples":[{"en":"The idea of a parallel universe is hard to grasp.","cn":"认为另有一个平行宇宙的概念是很难理解的。"},{"en":"He lives in a little universe of his own.","cn":"他生活在自己的小天地里。"}]},"unhelpful":{"oxford":{"phon":"ʌnˈhelpfl","pos":"adjective","senses":[{"en":"not helpful or useful; not willing to help somebody","cn":"无益的；无用的；不愿帮助的","ex":{"en":"an unhelpful response","cn":"于事无补的反应"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"没有帮助的；无益的","en":"If you say that someone or something is unhelpful, you mean that they do not help you or improve a situation, and may even make things worse.","ex":{"en":"The criticism is both unfair and unhelpful.","cn":"批评既不公正又无济于事。"}}]},"media":{"uk":"media/uk/unhelpful__gb_1.mp3","us":"media/us/unhelpful__us_1.mp3"},"examples":[{"en":"The taxi driver was being very unhelpful.","cn":"那个出租车司机不肯帮忙。"},{"en":"an unhelpful response","cn":"于事无补的反应"}]},"unrest":{"media":{"uk":"media/uk/unrest__gb_1.mp3","us":"media/us/unrest__us_1.mp3"},"oxford":{"phon":"ʌnˈrest","pos":"noun","senses":[{"en":"a political situation in which people are angry and likely to protest or fight","cn":"动荡；动乱；骚动","ex":{"en":"industrial/civil/social/political/popular unrest","cn":"工业／平民／社会／政治／民众动乱"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"动乱；骚乱；动荡","en":"If there is unrest in a particular place or society, people are expressing anger and dissatisfaction about something, often by demonstrating or rioting.","ex":{"en":"The real danger is civil unrest in the east of the country","cn":"真正的危险是该国东部地区的民众动乱。"}}]},"examples":[{"en":"There is growing unrest in the south of the country.","cn":"这个国家的南方日益动荡不安。"},{"en":"industrial/civil/social/political/popular unrest","cn":"工业/平民/社会/政治/民众动乱"}]},"unless":{"media":{"uk":"media/uk/unless__gb_1.mp3","us":"media/us/unless__us_1.mp3"},"oxford":{"phon":"ənˈles","pos":"conjunction","senses":[{"en":"used to say that something can only happen or be true in a particular situation","cn":"除非；除非在…情况下","ex":{"en":"You won't get paid for time off unless you have a doctor's note.","cn":"除非你有医生证明，否则你不上班便拿不到工资。"}},{"en":"used to give the only situation in which something will not happen or be true","cn":"若非；如果不","ex":{"en":"I sleep with the window open unless it's really cold.","cn":"天气若不很冷，我总开着窗户睡觉。"}}]},"collins":{"senses":[{"pos":"CONJ-SUBORD 连词","cn":"除非；若不；除非在…的时候","en":"You use unless to introduce the only circumstances in which an event you are mentioning will not take place or in which a statement you are making is not true.","ex":{"en":"Unless you are trying to lose weight to please yourself, it's going to be tough to keep your motivation level high","cn":"除非减肥是为了悦已，否则很难保持积极性。"}}]},"examples":[{"en":"You won't get paid for time off unless you have a doctor's note.","cn":"除非你有医生证明，否则你不上班便拿不到工资。"},{"en":"He hasn't got any hobbies — unless you call watching TV a hobby.","cn":"他没有什么爱好，除非你把看电视也称作爱好。"}]},"uniform":{"media":{"uk":"media/uk/uniform__gb_1.mp3","us":"media/us/uniform__us_1.mp3"},"oxford":{"phon":"ˈjuːnɪfɔːm","pos":"noun","senses":[{"en":"the special set of clothes worn by all members of an organization or a group at work, or by children at school","cn":"制服；校服","g":"[countable, uncountable]","ex":{"en":"The hat is part of the school uniform.","cn":"这帽子是校服的一部分。"}},{"en":"the clothes worn by the members of a sports team when they are playing","cn":"（运动队）队服","g":"[countable, usually singular, uncountable]","lab":"North American English","ex":{"en":"a striped baseball uniform","cn":"条纹棒球服"}},{"en":"the type of clothes that a person or group usually wears","cn":"清一色服装；统一服装","g":"[singular, uncountable]","ex":{"en":"my standard teenage uniform of sweatshirt and jeans","cn":"我少年时代标准的衣着：运动衫和牛仔裤"}},{"en":"not varying; the same in all parts and at all times","cn":"一致的；统一的；一律的","ex":{"en":"uniform rates of pay","cn":"统一的薪资标准"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"制服","en":"A uniform is a special set of clothes which some people, for example soldiers or the police, wear to work in and which some children wear at school.","ex":{"en":"The town police wear dark blue uniforms and flat caps","cn":"镇上的警察穿着深蓝色制服，戴着鸭舌帽。"}},{"pos":"N-COUNT 可数名词","cn":"（某一群体的）特种服式","en":"You can refer to the particular style of clothing which a group of people wear to show they belong to a group or a movement as their uniform.","ex":{"en":"Mark's is the uniform of the young male traveller — green Army trousers, T-shirt and shirt.","cn":"马克一身年轻男性旅行者的典型行头——绿军裤、T恤外加衬衫。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（同一物）始终如一的，均匀的，划一的","en":"If something is uniform, it does not vary, but is even and regular throughout.","ex":{"en":"Chips should be cut into uniform size and thickness","cn":"土豆条要切得大小厚薄均匀。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（不同物）全都相同的，一律的，清一色的","en":"If you describe a number of things as uniform, you mean that they are all the same.","ex":{"en":"Along each wall stretched uniform green metal filing cabinets","cn":"每面墙边都一溜摆着相同的绿色金属档案柜。"}}]},"examples":[{"en":"my standard teenage uniform of sweatshirt and jeans","cn":"我少年时代标准的衣着：运动衫和牛仔裤"},{"en":"They tried to ensure uniformity across the different departments.","cn":"他们努力保证各部门之间的统一。"}]},"used":{"media":{"uk":"media/uk/used__gb_2.mp3","us":"media/us/used__us_2.mp3"},"oxford":{"phon":"juːst","pos":"adjective","senses":[{"en":"familiar with something because you do it or experience it often","cn":"习惯于；适应","ex":{"en":"I'm not used to eating so much at lunchtime.","cn":"我不习惯午饭吃那么多。"}},{"en":"that has belonged to or been used by somebody else before","cn":"用过的；旧的；二手的","ex":{"en":"used cars","cn":"二手汽车"}},{"en":"that has already been used","cn":"用过的；旧的","ex":{"en":"a used teabag","cn":"泡过的茶包"}}]},"collins":{"senses":[{"pos":"PHR-MODAL 情态动词短语","cn":"过去常常；过去曾","en":"If something used to be done or used to be the case, it was done regularly in the past or was the case in the past.","ex":{"en":"People used to come and visit him every day","cn":"人们过去每天都来拜访他。"}},{"pos":"PHR-MODAL 情态动词短语","cn":"过去不曾（亦作did not use to 或 did not used to，尤用于口语）","en":"If something used not to be done or used not to be the case, it was not done in the past or was not the case in the past. The forms did not use to and did not used to are also found, especially in spoken English.","ex":{"en":"Borrowing used not to be recommended","cn":"过去是不建议借贷的。"}},{"pos":"PHRASE 短语","cn":"习惯于","en":"If you are used to something, you are familiar with it because you have done it or experienced it many times before.","ex":{"en":"I'm used to having my sleep interrupted","cn":"我习惯了睡觉时被吵醒。"}},{"pos":"PHRASE 短语","cn":"开始习惯于","en":"If you get used to something or someone, you become familiar with it or get to know them, so that you no longer feel that the thing or person is unusual or surprising.","ex":{"en":"This is how we do things here. You'll soon get used to it","cn":"我们这里就是这么做事的。你很快就会习惯的。"}},{"pos":"ADJ 形容词","cn":"用过的;不干净的；损坏的","en":"A used object is dirty or spoiled because it has been used, and usually needs to be thrown away or washed.","ex":{"en":"...a used cotton ball stained with makeup","cn":"沾满化妆品的脏棉球"}},{"pos":"ADJ 形容词","cn":"（车）二手的，旧的","en":"A used car has already had one or more owners.","ex":{"en":"Would you buy a used car from this man?","cn":"你会从这个人手里买一辆旧车吗？"}}]},"examples":[{"en":"I found the job tiring at first but I soon got used to it.","cn":"起初我觉得这份工作很累人，但很快就习惯了。"},{"en":"I'm not used to eating so much at lunchtime.","cn":"我不习惯午饭吃那么多。"}]},"unroll":{"media":{"uk":"media/uk/unroll__gb_1.mp3","us":"media/us/unroll__us_1.mp3"},"oxford":{"phon":"ʌnˈrəʊl","pos":"verb","senses":[{"en":"if you unroll paper, cloth, etc. that was in a roll or if it unrolls, it opens and becomes flat","cn":"（使纸张、织物等）展开，摊开，铺开","g":"[transitive, intransitive]","ex":{"en":"We unrolled our sleeping bags.","cn":"我们打开了睡袋。"}},{"en":"to happen one after another in a series","cn":"相继出现；连续发生","g":"[intransitive]","ex":{"en":"We watched the events unroll before the cameras.","cn":"我们眼看着事态的发展一一呈现在镜头前。"}}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"铺开；展开","en":"If you unroll something such as a sheet of paper or cloth, or if it unrolls, it opens up and becomes flat when it was previously rolled in a cylindrical shape.","ex":{"en":"I unrolled my sleeping bag as usual","cn":"我像往常一样铺开我的睡袋。"}}]},"examples":[{"en":"We watched the events unroll before the cameras.","cn":"我们眼看着事态的发展一一呈现在镜头前。"},{"en":"We unrolled our sleeping bags.","cn":"我们打开了睡袋。"}]},"unusually":{"media":{"uk":"media/uk/unusually__gb_1.mp3","us":"media/us/unusually__us_1.mp3"},"oxford":{"phon":"ʌnˈjuːʒuəli","pos":"adverb","senses":[{"en":"used before adjectives to emphasize that a particular quality is greater than normal","cn":"（置于形容词前，用以强调）特别地，极，非常","ex":{"en":"unusually high levels of radiation","cn":"超高的辐射强度"}},{"en":"used to say that a particular situation is not normal or expected","cn":"不寻常地；意想不到地","ex":{"en":"Unusually for him, he wore a tie.","cn":"他破例打了一条领带。"}}]},"collins":{"senses":[{"pos":"ADV-GRADED 副词","cn":"出奇地；不寻常地","en":"You use unusually to emphasize that someone or something has more of a particular quality than is usual.","ex":{"en":"He was an unusually complex man.","cn":"他是个极其复杂的人。"}},{"pos":"ADV-GRADED 副词","cn":"异常地；不常见地","en":"You can use unusually to suggest that something is not what normally happens.","ex":{"en":"Unusually among British prime ministers, he was not a man of natural authority.","cn":"他不是那种天生一副官派的人，这在英国首相中并不常见。"}}]},"examples":[{"en":"Unusually for him, he wore a tie.","cn":"他破例打了一条领带。"},{"en":"unusually high levels of radiation","cn":"超高的辐射强度"}]},"uneven":{"media":{"uk":"media/uk/uneven__gb_1.mp3","us":"media/us/uneven__us_1.mp3"},"oxford":{"phon":"ʌnˈiːvn","pos":"adjective","senses":[{"en":"not level, smooth or flat","cn":"凹凸不平的；不平坦的","ex":{"en":"The floor felt uneven under his feet.","cn":"他觉得脚下的地板高低不平。"}},{"en":"not following a regular pattern; not having a regular size and shape","cn":"无定型的；不规则的；无规律的","ex":{"en":"Her breathing was quick and uneven.","cn":"她的呼吸急促不匀。"}},{"en":"not having the same quality in all parts","cn":"质量不稳定的","ex":{"en":"an uneven performance (= with some good parts and some bad parts)","cn":"时好时坏的表现"}},{"en":"in which one group, team or player is much better than the other","cn":"实力悬殊的；一边倒的；不在同一水平的"},{"en":"organized in a way that is not regular and/or fair","cn":"不均衡的；不公平的；不规则的","ex":{"en":"an uneven distribution of resources","cn":"资源的不均衡分配"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不平坦的;不平滑的;凹凸不平的;参差不齐的","en":"An uneven surface or edge is not smooth, flat, or straight.","ex":{"en":"He staggered on the uneven surface of the car park","cn":"他摇摇晃晃地行走在停车场凹凸不平的地面上。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不规则的；不一致的","en":"Something that is uneven is not regular or consistent.","ex":{"en":"He could hear that her breathing was uneven","cn":"他能听到她的呼吸不均匀。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（质量）不稳定的，时好时坏的","en":"If you describe something as uneven, you think it is not very good because it is not consistent in quality.","ex":{"en":"This was, for him, an oddly uneven performance","cn":"对他而言，这场演出时好时坏，很是奇怪。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不公平的；不均衡的","en":"An uneven system or situation is unfairly arranged or organized.","ex":{"en":"Some of the victims are complaining loudly about the uneven distribution of emergency aid","cn":"其中一些灾民大声地抱怨紧急援助物资分配不公。"}}]},"examples":[{"en":"The floor felt uneven under his feet.","cn":"他觉得脚下的地板高低不平。"},{"en":"Her breathing was quick and uneven.","cn":"她的呼吸急促不匀。"}]},"un":{"oxford":{"phon":"ˌjuː ˈen","pos":"abbreviation","senses":[{"en":"United Nations (an association of many countries that aims to help economic and social conditions improve and to solve political problems in the world in a peaceful way)","cn":"联合国","ex":{"en":"the UN Security Council","cn":"联合国安理会"}},{"en":"not; the opposite of","cn":"不；非；相反的","ex":{"en":"unable","cn":"不能"},"pos":"prefix"},{"en":"a way of saying or writing ‘one’","cn":"（等于 one）","ex":{"en":"That was a good ’un.","cn":"那个东西不错。"},"pos":"pronoun"}]},"collins":{"senses":[{"pos":"N-PROPER 专有名词","cn":"同 United Nations","en":"The UN is the same as the United Nations .","ex":{"en":"...a UN peace-keeping mission.","cn":"联合国维和行动"}}]},"media":{"uk":"media/uk/un__gb_1.mp3","us":"media/us/un__us_1.mp3"},"examples":[{"en":"a UN peacekeeping plan","cn":"联合国维和计划"},{"en":"the UN Security Council","cn":"联合国安理会"}]},"undisturbed":{"media":{"uk":"media/uk/undisturbed__gb_1.mp3","us":"media/us/undisturbed__us_1.mp3"},"oxford":{"phon":"ˌʌndɪˈstɜːbd","pos":"adjective","senses":[{"en":"not moved or touched by anyone or anything","cn":"未被移动（或触及）","g":"[not usually before noun]","ex":{"en":"The treasure had lain undisturbed for centuries.","cn":"那份珍宝安然无恙地存放了几个世纪。"}},{"en":"not interrupted by anyone","cn":"未受惊扰的；未被打搅的","ex":{"en":"She succeeded in working undisturbed for a few hours.","cn":"她终于得以安安静静地工作了几个小时。"}},{"en":"not affected or upset by something","cn":"平静；镇定；泰然自若","g":"[not usually before noun]","ex":{"en":"He seemed undisturbed by the news of her death.","cn":"他对她的死讯似乎无动于衷。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未被动过的；未被移动的；未用过的","en":"Something that remains undisturbed is not touched, moved, or used by anyone.","ex":{"en":"The desk looked undisturbed","cn":"那张桌子看上去没人动过。"}},{"pos":"ADJ 形容词","cn":"（地方）平静的，未受扰乱的","en":"A place that is undisturbed is peaceful and has not been affected by changes that have happened in other places.","ex":{"en":"In the Balearics pockets of rural life and inland villages are undisturbed","cn":"在巴利阿里群岛上，零星散布在岛内的村庄和那里的生活平静而祥和。"}},{"pos":"ADJ 形容词","cn":"（人）未被打扰的，未受干扰的","en":"If you are undisturbed in something that you are doing, you are able to continue doing it and are not affected by something that is happening.","ex":{"en":"I can spend the whole day undisturbed at the warehouse","cn":"我可以一整天都呆在仓库里而不受打扰。"}},{"pos":"ADJ 形容词","cn":"不烦恼的；不着急的；不担忧的","en":"If someone is undisturbed by something, it does not affect, bother, or upset them.","ex":{"en":"Victoria was strangely undisturbed by this symptom, even though her husband and family were frightened.","cn":"尽管丈夫和家人都吓坏了，维多利亚却对这一症状出奇地淡定。"}}]},"examples":[{"en":"She succeeded in working undisturbed for a few hours.","cn":"她终于得以安安静静地工作了几个小时。"},{"en":"The treasure had lain undisturbed for centuries.","cn":"那份珍宝安然无恙地存放了几个世纪。"}]},"unfamiliar":{"media":{"uk":"media/uk/unfamiliar__gb_1.mp3","us":"media/us/unfamiliar__us_1.mp3"},"oxford":{"phon":"ˌʌnfəˈmɪliə(r)","pos":"adjective","senses":[{"en":"that you do not know or recognize","cn":"陌生的；不熟悉的；不认识的","ex":{"en":"She felt uneasy in the unfamiliar surroundings.","cn":"她在陌生的环境中感到局促不安。"}},{"en":"not having any knowledge or experience of something","cn":"无…的知识（或经验）","ex":{"en":"an introductory course for students who are unfamiliar with computers","cn":"为不了解计算机的学生开设的入门课程"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不熟悉的；陌生的","en":"If something is unfamiliar to you, you know nothing or very little about it, because you have not seen or experienced it before.","ex":{"en":"She grew many wonderful plants that were unfamiliar to me","cn":"她种了很多我不熟悉的奇妙植物。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不熟知的；不了解的","en":"If you are unfamiliar with something, it is unfamiliar to you.","ex":{"en":"She speaks no Japanese and is unfamiliar with Japanese culture.","cn":"她不会说日语，也不了解日本文化。"}}]},"examples":[{"en":"an introductory course for students who are unfamiliar with computers","cn":"为不了解计算机的学生开设的入门课程"},{"en":"Please highlight any terms that are unfamiliar to you.","cn":"请把你们不熟悉的用语都标示出来。"}]},"urbanization":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"城市化；都市化","en":"Urbanization is the process of creating towns in country areas."}]},"media":{"uk":"media/uk/urbanization__gb_1.mp3","us":"media/us/urbanization__us_1.mp3"},"examples":[{"en":"During the 19th century, Britain became the world’s first modern urbanized society.","cn":""},{"en":"the most heavily urbanized regions","cn":""}],"oxford":{"phon":"ˌɜːbənaɪˈzeɪʃn","pos":"noun","senses":[{"en":"the process in which towns, streets, factories, etc. are built where there was once countryside","cn":"城市化的","ex":{"en":"a time of rapid urbanization and industrialization","cn":"快速城市化和工业化的时代"}},{"en":"the process in which more and more people start to live and work in towns and cities rather than in the country","cn":"向城市转移","ex":{"en":"the increasing urbanization of Africans","cn":"非洲人日益城市化"}}]}},"upbringing":{"oxford":{"phon":"ˈʌpbrɪŋɪŋ","pos":"noun","senses":[{"en":"the way in which a child is cared for and taught how to behave while it is growing up","cn":"抚育；养育；教养；培养","ex":{"en":"She had had a very sheltered upbringing.","cn":"她在备受呵护中长大。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"抚育；培育；养育；教养","en":"Your upbringing is the way that your parents treat you and the things that they teach you when you are growing up.","ex":{"en":"Martin's upbringing shaped his whole life","cn":"马丁的家庭教养影响了他的一生。"}}]},"media":{"uk":"media/uk/upbringing__gb_1.mp3","us":"media/us/upbringing__us_1.mp3"},"examples":[{"en":"He was a Catholic by upbringing.","cn":"他因受家庭薰陶，从小就是个天主教徒。"},{"en":"to have had a sheltered upbringing","cn":"受到呵护的养育"}]},"undid":{"collins":{"senses":[{"pos":"","cn":"","en":"Undid is the past tense of undo."}]},"media":{"uk":"media/uk/undid__gb_1.mp3","us":"media/us/undid__us_1.mp3"}},"unnecessarily":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if you do not have to do something, you can do it if you want, but you are not forced to do it, either by a rule or by another person, or by the situation you are in","cn":""},{"en":"say this to tell someone that it is not necessary for them to do something","cn":""}]},"media":{"uk":"media/uk/unnecessarily__gb_1.mp3","us":"media/us/unnecessarily__us_1.mp3"},"oxford":{"phon":"ʌnˈnesəsərəli","pos":"adverb","senses":[{"en":"without any need; in a way that is not needed or is more than is needed","cn":"不必要地","ex":{"en":"There's no point worrying him unnecessarily.","cn":"没有必要让他过于担心。"}}]}},"unsurprising":{"media":{"uk":"media/uk/unsurprising__gb_1.mp3","us":"media/us/unsurprising__us_1.mp3"},"oxford":{"phon":"ˌʌnsəˈpraɪzɪŋ","pos":"adjective","senses":[{"en":"not causing surprise","cn":"不令人惊讶的；不足为奇的","ex":{"en":"It’s unsurprising that people with dogs walk more than others.","cn":"养狗的人比其他人走路更多，这并不奇怪。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不出所料的；不出奇的；意料中的","en":"If something is unsurprising, you are not surprised by it because you would expect it to happen or be like it is.","ex":{"en":"It is unsurprising that he remains so hated","cn":"他还是那么乞人憎这一事实并不令人觉得奇怪。"}}]},"examples":[{"en":"Unsurprisingly, the plan failed.","cn":"果然不出所料，计划失败了。"},{"en":"It’s unsurprising that the project failed.","cn":"这个项目失败了没什么好奇怪的。"}]},"unity":{"media":{"uk":"media/uk/unity__gb_1.mp3","us":"media/us/unity__us_1.mp3"},"oxford":{"phon":"ˈjuːnəti","pos":"noun","senses":[{"en":"the state of being in agreement and working together; the state of being joined together to form one unit","cn":"团结一致；联合；统一","g":"[uncountable, singular]","ex":{"en":"European unity","cn":"欧洲的统一"}},{"en":"the quality of looking or being complete in a natural and attractive way","cn":"完整；完美；和谐；协调","g":"[uncountable]","ex":{"en":"The design lacks unity.","cn":"这项设计整体不够协调。"}},{"en":"any of the principles of classical or neoclassical theatre that limit the action of a play to a single story, day and place","cn":"（情节、时间和地点的）统一性，一致性；三一律","g":"[countable]","lab":"specialist","ex":{"en":"the unities of action, time and place","cn":"要求情节、时间和地点一致的三一律"}},{"en":"a single thing that may consist of a number of different parts","cn":"统一体；联合体；整体","g":"[singular]","lab":"formal","ex":{"en":"If society is to exist as a unity, its members must have shared values.","cn":"社会若要成为一个统一的群体，它的成员就必须有共同的价值观。"}},{"en":"the number one","cn":"（数目或数字）一","g":"[uncountable]","lab":"mathematics"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"联合（状态）；统一（状态）","en":"Unity is the state of different areas or groups being joined together to form a single country or organization.","ex":{"en":"Senior politicians met today to discuss the future of European economic unity.","cn":"高级政要今天会晤，探讨欧洲经济一体化的未来。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"团结；一致","en":"When there is unity, people are in agreement and act together for a particular purpose.","ex":{"en":"...a renewed unity of purpose","cn":"目标的重新确认一致"}}]},"examples":[{"en":"If society is to exist as a unity, its members must have shared values.","cn":"社会若要成为一个统一的群体，它的成员就必须有共同的价值观。"},{"en":"the unities of action, time and place","cn":"要求情节、时间和地点一致的三一律"}]},"underground":{"oxford":{"phon":"ˌʌndəˈɡraʊnd","pos":"adjective","senses":[{"en":"under the surface of the ground","cn":"地下的；地面以下的","ex":{"en":"an underground bunker/tunnel","cn":"地下掩体／隧道"}},{"en":"operating secretly and often illegally, especially against a government","cn":"秘密的，非法的，暗中的，地下的（尤指反政府的）","ex":{"en":"an underground resistance movement","cn":"地下抵抗运动"}},{"en":"under the surface of the ground","cn":"地下的；地面以下的","ex":{"en":"Rescuers found victims trapped several feet underground.","cn":"营救人员发现有受难者被困在地下几英尺处。"},"pos":"adverb"},{"en":"in or into a secret place in order to hide from the police, the government, etc.","cn":"隐蔽地；隐匿地","ex":{"en":"He went underground to avoid arrest.","cn":"他隐藏起来以防被捕。"},"pos":"adverb"},{"en":"an underground railway system in a city","cn":"地铁；地下铁路系统","g":"[singular]","lab":"British English","ex":{"en":"underground stations","cn":"地铁车站"},"pos":"noun"},{"en":"a secret political organization, usually working against the government of a country","cn":"秘密政治组织；（反政府）地下组织","g":"[singular + singular or plural verb]","pos":"noun"},{"en":"a person who works against the government as a member of a secret political organization","cn":"反政府地下组织成员","lab":"Indian English","pos":"noun"}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"地下；地面下","en":"Something that is underground is below the surface of the ground.","ex":{"en":"Solid low-level waste will be disposed of deep underground","cn":"放射性水平低的固体废料将做地下深埋处理。"}},{"pos":"N-SING 单数名词","cn":"地铁","en":"The underground in a city is the railway system in which electric trains travel below the ground in tunnels.","ex":{"en":"...a woman alone in the underground waiting for a train","cn":"独自在地铁里等车的女子"}},{"pos":"N-SING 单数名词","cn":"（反抗敌人或暴政的）地下组织，秘密组织","en":"In a country which is controlled by an enemy or has a harsh government, the underground is an organized group of people who are involved in illegal activities against the people in power.","ex":{"en":"These US dollars were smuggled into the country during the war, to aid the underground.","cn":"战争期间，这些美元被偷运到该国，用以资助那里的地下组织。"}},{"pos":"ADJ 形容词","cn":"地下的；秘密的；非法的","en":"Underground groups and activities are secret because their purpose is to oppose the government and they are illegal.","ex":{"en":"...the underground Kashmir Liberation Front","cn":"秘密的克什米尔解放阵线"}},{"pos":"ADV 副词","cn":"秘密地；隐蔽地；暗中","en":"If you go underground, you hide from the authorities or the police because your political ideas or activities are illegal.","ex":{"en":"After the violent clashes of 1981 they either went underground or left the country.","cn":"经历了1981年的激烈冲突之后，他们或转入地下，或离开了该国。"}}]},"media":{"img":["media/pic/trains_comp.jpg","media/thumb/underground.jpg"],"uk":"media/uk/underground__gb_1.mp3","us":"media/us/underground__us_1.mp3"},"examples":[{"en":"Rescuers found victims trapped several feet underground.","cn":"营救人员发现有受难者被困在地下几英尺处。"},{"en":"He went underground to avoid arrest.","cn":"他隐藏起来以防被捕。"}]},"uncommon":{"media":{"uk":"media/uk/uncommon__gb_1.mp3","us":"media/us/uncommon__us_1.mp3"},"oxford":{"phon":"ʌnˈkɒmən","pos":"adjective","senses":[{"en":"not existing in large numbers or in many places","cn":"不常有的；罕见的；稀罕的","ex":{"en":"an uncommon occurrence","cn":"不寻常的事情"}},{"en":"unusually large in degree or amount; great","cn":"程度深的；特别大的","lab":"formal or literary","ex":{"en":"She showed uncommon pleasure at his arrival.","cn":"他的到来令她异常欢喜。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不平常的；罕见的","en":"If you describe something as uncommon, you mean that it does not happen often or is not often seen.","ex":{"en":"Cancer of the breast in young women is uncommon","cn":"乳腺癌在年轻女子当中并不常见。"}},{"pos":"ADJ 形容词","cn":"非凡的；杰出的；罕有的","en":"If you describe a quality, usually a good quality, as uncommon, you mean that it is unusually great in degree or amount.","ex":{"en":"Both are blessed with uncommon ability to fix things","cn":"两人在修理东西方面都身手不凡。"}}]},"examples":[{"en":"It is not uncommon for college students to live at home.","cn":"大学生住在家里并不少见。"},{"en":"Red squirrels are uncommon in England.","cn":"红松鼠在英格兰很少见。"}]},"utility":{"media":{"uk":"media/uk/utility__gb_1.mp3","us":"media/us/utility__us_1.mp3"},"oxford":{"phon":"juːˈtɪləti","pos":"noun","senses":[{"en":"a service provided for the public, for example an electricity, water or gas supply","cn":"公用事业","g":"[countable]","lab":"especially North American English","ex":{"en":"a privatized electricity utility","cn":"私有化的电力服务"}},{"en":"the quality of being useful","cn":"实用；效用；有用","g":"[uncountable]","lab":"formal","ex":{"en":"This information is of the highest utility to a historian.","cn":"这些信息对于历史学家来说具有最高的实用性。"}},{"en":"a piece of computer software that performs a particular task","cn":"实用程序；公用程序；工具","g":"[countable]","lab":"computing"},{"en":"that can be used for several different purposes","cn":"多用途的；多效用的；多功能的","ex":{"en":"an all-round utility player (= one who can play equally well in several different positions in a sport)","cn":"全面型选手"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"功用;效用;实用","en":"The utility of something is its usefulness.","ex":{"en":"Belief in the utility of higher education is shared by students nationwide","cn":"全国的学生都相信高等教育是有用的。"}},{"pos":"N-COUNT 可数名词","cn":"公用事业","en":"A utility is an important service such as water, electricity, or gas that is provided for everyone, and that everyone pays for.","ex":{"en":"...public utilities such as gas, electricity and phones.","cn":"煤气、电和电话等公用事业"}}]},"examples":[{"en":"an all-round utility player (= one who can play equally well in several different positions in a sport)","cn":"全面型选手"},{"en":"the administration of public utilities","cn":"公共事业的管理"}]},"unfold":{"oxford":{"phon":"ʌnˈfəʊld","pos":"verb","senses":[{"en":"to spread open or flat something that has previously been folded; to become open and flat","cn":"（使）展开；打开","g":"[transitive, intransitive]","ex":{"en":"to unfold a map","cn":"展开地图"}},{"en":"to be gradually made known; to gradually make something known to other people","cn":"（使）逐渐展现；展示；透露","g":"[intransitive, transitive]","ex":{"en":"The audience watched as the story unfolded before their eyes.","cn":"观众看着剧情逐渐地展开。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"展现；呈现；逐渐明朗","en":"If a situation unfolds, it develops and becomes known or understood.","ex":{"en":"The outcome depends on conditions as well as how events unfold","cn":"结果取决于条件，还取决于事件的进展。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（故事）展开；讲述","en":"If a story unfolds or if someone unfolds it, it is told to someone else.","ex":{"en":"Don's story unfolded as the cruise got under way","cn":"随着航行的开始，唐的故事也随之展开。"}},{"pos":"V-ERG 及物/不及物动词","cn":"展开；打开；伸展","en":"If someone unfolds something which has been folded or if it unfolds, it is opened out and becomes flat.","ex":{"en":"He quickly unfolded the blankets and spread them on the mattress","cn":"他迅速展开毯子，铺在床垫上。"}}]},"media":{"uk":"media/uk/unfold__gb_1.mp3","us":"media/us/unfold__us_1.mp3"},"examples":[{"en":"The audience watched as the story unfolded before their eyes.","cn":"观众注视着剧情逐渐地展开。"},{"en":"She unfolded her tale to us.","cn":"她向我们倾吐了她的故事。"}]},"uptake":{"media":{"uk":"media/uk/uptake__gb_1.mp3","us":"media/us/uptake__us_1.mp3"},"oxford":{"phon":"ˈʌpteɪk","pos":"noun","senses":[{"en":"the use that is made of something that has become available","cn":"（对现有东西的）使用，利用，应用","ex":{"en":"There has been a high uptake of the free training.","cn":"免费培训有很多人参加。"}},{"en":"the process by which something is taken into a body or system; the rate at which this happens","cn":"吸收；吸收速度","lab":"specialist","ex":{"en":"the uptake of oxygen by muscles","cn":"肌肉对氧气的吸收"}}]},"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"摄入；摄取","en":"A person's uptake of something is the amount of it that they use.","ex":{"en":"The drug increases the number of red cells in the blood, enhancing oxygen uptake by 10 percent.","cn":"这种药增加了血液里的红细胞数量，从而将摄氧量提高了10%。"}},{"pos":"PHRASE 短语","cn":"理解力强/理解力弱","en":"You say that someone is quick on the uptake when they understand things quickly. You say that someone is slow on the uptake when they have difficulty understanding simple or obvious things.","ex":{"en":"She is not an intellectual, but is quick on the uptake","cn":"她并不是个才智非凡的人，但理解力很强。"}}]},"examples":[{"en":"There has been a high uptake of the free training.","cn":"免费培训有很多人参加。"},{"en":"Is he always this slow on the uptake?","cn":"他总是理解得这么慢吗？"}]},"unforgiving":{"media":{"uk":"media/uk/unforgiving__gb_1.mp3","us":"media/us/unforgiving__us_1.mp3"},"oxford":{"phon":"ˌʌnfəˈɡɪvɪŋ","pos":"adjective","senses":[{"en":"unwilling to forgive other people when they have done something wrong","cn":"不饶人的；不宽容的；不肯原谅的","ex":{"en":"a proud and unforgiving man","cn":"一个骄傲且无情的人"}},{"en":"unpleasant and causing difficulties for people","cn":"让人为难的；难应付的；棘手的","ex":{"en":"The island is an unforgiving place in winter.","cn":"冬天的岛上是一个无情的地方。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"不宽容的；不原谅人的","en":"If you describe someone as unforgiving, you mean that they are unwilling to forgive other people.","ex":{"en":"He was an unforgiving man who never forgot a slight","cn":"他斤斤计较，很不大度。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（形势或活动）无情的，难以应付的，不利的","en":"If you describe a situation or activity as unforgiving, you mean that it causes a lot of people to experience great difficulty or failure, even people who deserve to succeed.","ex":{"en":"Business is a competitive activity. It is very fierce and very unforgiving.","cn":"商场如战场，竞争激烈，不近人情。"}}]}},"unheard":{"oxford":{"phon":"ʌnˈhɜːd","pos":"adjective","senses":[{"en":"that nobody pays attention to","cn":"无人理会的；未被注意的","ex":{"en":"Their protests went unheard.","cn":"他们的抗议无人理会。"}},{"en":"not listened to or heard","cn":"未被听的；未听到的","ex":{"en":"a previously unheard tape of their conversations","cn":"以前未听过的他们谈话的录音带"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"没听到的；不被理睬的；被忽略的","en":"If you say that a person or their words go unheard, you are expressing criticism because someone refuses to pay attention to what is said or take it into consideration.","ex":{"en":"His impassioned pleas went unheard","cn":"他充满激情的请求未被理睬。"}},{"pos":"ADJ 形容词","cn":"不为人知的；前所未闻的","en":"If you describe spoken comments or pieces of music as unheard, you mean that most people are not familiar with them because they have not been expressed or performed in public.","ex":{"en":"A vast treasure-trove of virtually unheard melody awaits discovery by this new audience.","cn":"大量不为人知的优美旋律正等着这批新听众来发掘。"}},{"pos":"ADJ 形容词","cn":"听不到的","en":"If someone's words or cries go unheard, nobody can hear them, or a particular person cannot hear them.","ex":{"en":"Martin's weak cries for help went unheard until 6.40pm yesterday.","cn":"直到昨天傍晚6点40分，马丁微弱的呼救声才被人听到。"}}]},"media":{"uk":"media/uk/unheard__gb_1.mp3","us":"media/us/unheard__us_1.mp3"},"examples":[{"en":"a previously unheard tape of their conversations","cn":"以前未听过的他们谈话的录音带"},{"en":"Their protests went unheard.","cn":"他们的抗议无人理会。"}]},"unkind":{"oxford":{"phon":"ˌʌnˈkaɪnd","pos":"adjective","senses":[{"en":"not pleasant or friendly; slightly cruel","cn":"不友善的；不亲切的；不客气的；刻薄的","ex":{"en":"an unkind remark","cn":"不友善的话"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不仁慈的；不友善的；不厚道的；刻薄的","en":"If someone is unkind, they behave in an unpleasant, unfriendly, or slightly cruel way. You can also describe someone's words or actions as unkind .","ex":{"en":"All last summer he'd been unkind to her","cn":"去年整个夏天他都对她很恶劣。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（遭遇）残忍的，无情的","en":"If you describe something bad that happens to someone as unkind, you mean that they do not deserve it.","ex":{"en":"The weather was unkind to those pipers who played in the morning.","cn":"坏天气对上午那些风笛吹奏者毫不容情。"}}]},"media":{"uk":"media/uk/unkind__gb_1.mp3","us":"media/us/unkind__us_1.mp3"},"examples":[{"en":"‘That's your problem,’ she remarked unkindly. “","cn":"那是你的问题。”她刻薄地说。"},{"en":"He was never actually unkind to them.","cn":"其实他从没有对他们不好。"}]},"underlie":{"oxford":{"phon":"ˌʌndəˈlaɪ","pos":"verb","senses":[{"en":"to be the basis or cause of something","cn":"构成…的基础；作为…的原因","ex":{"en":"These ideas underlie much of his work.","cn":"他的作品大部分都是以这些主题思想为基础。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"为…的起因；构成…的基础","en":"If something underlies a feeling or situation, it is the cause or basis of it.","ex":{"en":"Try to figure out what feeling underlies your anger.","cn":"努力找出你的愤怒之下潜藏的情感。"}}]},"media":{"uk":"media/uk/underlie__gb_1.mp3","us":"media/us/underlie__us_1.mp3"},"examples":[{"en":"These ideas underlie much of his work.","cn":"他的作品大部分都是以这些主题思想为基础。"},{"en":"It is a principle that underlies all the party's policies.","cn":"这是贯穿该党各项政策的一条准则。"}]},"unsettling":{"media":{"uk":"media/uk/unsettling__gb_1.mp3","us":"media/us/unsettling__us_1.mp3"},"oxford":{"phon":"ʌnˈsetlɪŋ","pos":"adjective","senses":[{"en":"making you feel upset, nervous or worried","cn":"令人不安（或紧张、担忧）的","ex":{"en":"Seeing Nicky again after so long was an unsettling experience.","cn":"时隔这么久再次见到尼基是一次令人不安的经历。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"令人担忧的；令人不安的","en":"If you describe something as unsettling, you mean that it makes you feel rather worried or uncertain.","ex":{"en":"The prospect of change of this kind has an unsettling effect on any organisation","cn":"这种变化的前景对任何组织都有不确定的影响。"}}]},"examples":[{"en":"an unsettling experience","cn":"令人不安的经历"}]},"undoubtedly":{"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"used when saying that you are sure about something","cn":""},{"en":"used when saying that you are completely sure about something. Undoubtedly sounds more certain and a little more formal than certainly","cn":""}]},"examples":[{"en":"That is undoubtedly true.","cn":"那是千真万确的。","src":"ld"},{"en":"Undoubtedly, public interest in folk music has declined.","cn":"无疑﹐大众对民谣的兴趣减退了。","src":"ld"}],"media":{"uk":"media/uk/undoubtedly__gb_1.mp3","us":"media/us/undoubtedly__us_1.mp3"},"oxford":{"phon":"ʌnˈdaʊtɪdli","pos":"adverb","senses":[{"en":"used to emphasize that something exists or is definitely true","cn":"无疑地；确实地；千真万确地","ex":{"en":"There is undoubtedly a great deal of truth in what he says.","cn":"他所说的无疑有不少是实情。"}}]}},"upwards":{"media":{"uk":"media/uk/upwards__gb_1.mp3","us":"media/us/upwards__us_1.mp3"},"oxford":{"phon":"ˈʌpwədz","pos":"adverb","senses":[{"en":"towards a higher place or position","cn":"向上；向高处","ex":{"en":"Place your hands on the table with the palms facing upwards.","cn":"把手放在桌子上，手心朝上。"}},{"en":"towards a higher amount or price","cn":"（数量、价格）上升，上涨，提高","ex":{"en":"Bad weather forced the price of fruit upwards.","cn":"恶劣的天气迫使水果价格上涨。"}},{"en":"more than the amount or number mentioned","cn":"在…以上；大于；超过","ex":{"en":"You should expect to pay upwards of £50 for a hotel room.","cn":"酒店每个房间预计至少要 50 英镑。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"向上","en":"If someone moves or looks upwards, they move or look up towards a higher place.","ex":{"en":"'There,' said Jack, pointing upwards","cn":"“在那里，”杰克向上指着说。"}},{"pos":"ADV 副词","cn":"上升；上涨","en":"If an amount or rate moves upwards, it increases.","ex":{"en":"...with prices soon heading upwards in high street stores","cn":"商业大街上商店里的价格迅速上涨"}},{"pos":"PREP-PHRASE 短语介词","cn":"…以上；多于…","en":"A quantity that is upwards of a particular number is more than that number.","ex":{"en":"...projects worth upwards of 200 million pounds","cn":"价值2亿多英镑的项目"}}]},"examples":[{"en":"You should expect to pay upwards of £50 for a hotel room.","cn":"住宿饭店，每个房间预计至少要 50 英镑。"},{"en":"Bad weather forced the price of fruit upwards.","cn":"恶劣的天气迫使水果价格上涨。"}]},"undergo":{"media":{"uk":"media/uk/undergo__gb_1.mp3","us":"media/us/undergo__us_1.mp3"},"oxford":{"phon":"ˌʌndəˈɡəʊ","pos":"verb","senses":[{"en":"to experience something, especially a change or something unpleasant","cn":"经历，经受（变化、不快的事等）","ex":{"en":"to undergo tests/trials/repairs","cn":"经受考验；接受检修"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"经历；接受；遭受；忍受","en":"If you undergo something necessary or unpleasant, it happens to you.","ex":{"en":"New recruits have been undergoing training in recent weeks","cn":"最近几周，新兵正在接受训练。"}}]},"examples":[{"en":"Some children undergo a complete transformation when they become teenagers.","cn":"一些儿童进入少年期会完全变了另一个人。"},{"en":"My mother underwent major surgery last year.","cn":"我母亲去年动过大手术。"}]},"unprecedented":{"media":{"uk":"media/uk/unprecedented__gb_1.mp3","us":"media/us/unprecedented__us_1.mp3"},"oxford":{"phon":"ʌnˈpresɪdentɪd","pos":"adjective","senses":[{"en":"that has never happened, been done or been known before","cn":"前所未有的；空前的；没有先例的","ex":{"en":"The situation is unprecedented in modern times.","cn":"这种情况在现代还没有出现过。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"前所未有的；空前的；没有先例的","en":"If something is unprecedented, it has never happened before.","ex":{"en":"Such a move is rare, but not unprecedented","cn":"这种做法很罕见，但也不是没有先例的。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（质量、数量、规模）很高的，很大的","en":"If you describe something as unprecedented, you are emphasizing that it is very great in quality, amount, or scale.","ex":{"en":"Each home boasts an unprecedented level of quality throughout","cn":"每家的质量都堪称一流。"}}]},"examples":[{"en":"The situation is unprecedented in modern times.","cn":"这种情况在现代还没有出现过。"},{"en":"a period of unprecedentedly high food prices","cn":"食物空前昂贵的时期"}]},"uncountable":{"oxford":{"phon":"ʌnˈkaʊntəbl","pos":"adjective","senses":[{"en":"a noun that is uncountable cannot be made plural or used with a or an, for example water, bread and information","cn":"（名词）不可数的"}]},"media":{"uk":"media/uk/uncountable__gb_1.mp3","us":"media/us/uncountable__us_1.mp3"}},"unpopular":{"oxford":{"phon":"ʌnˈpɒpjələ(r)","pos":"adjective","senses":[{"en":"not liked or enjoyed by a person, a group or people in general","cn":"没人缘的；不受欢迎的；不得人心的","ex":{"en":"an unpopular choice","cn":"不普遍的选择"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"没有人缘的；不受欢迎的；不得人心的","en":"If something or someone is unpopular, most people do not like them.","ex":{"en":"It was a painful and unpopular decision","cn":"那是一个痛苦又不得人心的决定。"}}]},"media":{"uk":"media/uk/unpopular__gb_1.mp3","us":"media/us/unpopular__us_1.mp3"},"examples":[{"en":"The proposed increase in income tax proved deeply unpopular with the electorate.","cn":"增加所得税的建议令选民十分不满。"},{"en":"the growing unpopularity of the military regime","cn":"军政府日益不得人心"}]},"upset":{"oxford":{"phon":"ˌʌpˈset","pos":"adjective","senses":[{"en":"unhappy or disappointed because of something unpleasant that has happened","cn":"难过；不高兴；失望；沮丧","g":"[not before noun]","ex":{"en":"I understand how upset you must be feeling.","cn":"我理解你一定感到多么沮丧。"}},{"en":"an illness in the stomach that makes you feel sick (= want to vomit) or have diarrhoea","cn":"（肠胃）不适的；腹泻的","ex":{"en":"I've been off work with an upset stomach.","cn":"我因胃部不适而下班了。"}},{"en":"to make somebody/yourself feel unhappy, anxious or annoyed","cn":"使烦恼；使心烦意乱；使生气","ex":{"en":"This decision is likely to upset a lot of people.","cn":"这项决定很可能会使许多人不快。"},"pos":"verb"},{"en":"to make a plan, situation, etc. go wrong","cn":"打乱；搅乱","ex":{"en":"He arrived an hour late and upset all our arrangements.","cn":"他迟到了一个小时，把我们的一切安排都打乱了。"},"pos":"verb"},{"en":"to make somebody feel sick (= want to vomit) after they have eaten or drunk something","cn":"使（肠胃）不适","pos":"verb"},{"en":"to make something fall over by hitting it by accident","cn":"打翻；碰倒；使倾覆","ex":{"en":"She stood up suddenly, upsetting a glass of water.","cn":"她突然站了起来，打翻了一杯水。"},"pos":"verb"},{"en":"a situation in which there are problems or difficulties, especially when these are unexpected","cn":"（意外的）混乱，困扰，麻烦","g":"[uncountable]","ex":{"en":"The company has survived the recent upset in share prices.","cn":"这家公司撑过了最近股价的动荡。"},"pos":"noun"},{"en":"a situation in which a person or team beats the person or team that was expected to win","cn":"意外的结果；爆冷门","g":"[countable]","ex":{"en":"The biggest upset of the tournament came when the top seed was beaten in the second round.","cn":"本届赛事最大的冷门是头号种子在第二轮被击败。"},"pos":"noun"},{"en":"an illness in the stomach that makes you feel sick (= want to vomit) or have diarrhoea","cn":"（肠胃）不适的；腹泻的","g":"[countable]","ex":{"en":"a stomach upset","cn":"拉肚子"},"pos":"noun"},{"en":"the state of being unhappy, disappointed or worried because of something unpleasant that has happened","cn":"难过；不高兴；失望；沮丧","g":"[uncountable, countable]","ex":{"en":"It had been the cause of much emotional upset.","cn":"那便是使人情绪一落千丈的原因。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"心烦的；苦恼的；沮丧的","en":"If you are upset, you are unhappy or disappointed because something unpleasant has happened to you.","ex":{"en":"After she died I felt very, very upset","cn":"她去世之后，我非常非常难过。"}},{"pos":"VERB 动词","cn":"使心烦意乱；使生气；使心情不好","en":"If something upsets you, it makes you feel worried or unhappy.","ex":{"en":"The whole incident had upset me and my fiancee terribly","cn":"整个事件搞得我和未婚妻都心烦意乱。"}},{"pos":"VERB 动词","cn":"打乱；搅乱","en":"If events upset something such as a procedure or a state of affairs, they cause it to go wrong.","ex":{"en":"...a deal that would upset the balance of power in the world's gold markets","cn":"一桩将会打破全球黄金市场均势的交易"}},{"pos":"VERB 动词","cn":"弄翻；打翻；弄乱","en":"If you upset an object, you accidentally knock or push it over so that it scatters over a large area.","ex":{"en":"Don't upset the piles of sheets under the box.","cn":"不要把箱子下面那几叠床单弄乱了。"}},{"pos":"N-COUNT 可数名词","cn":"（肠胃的）不适","en":"A stomach upset is a slight illness in your stomach caused by an infection or by something that you have eaten.","ex":{"en":"Paul was unwell last night with a stomach upset","cn":"保罗昨晚肚子不舒服。"}},{"pos":"","cn":"","en":"to upset the applecart→see: ;"}]},"media":{"uk":"media/uk/upset__gb_1.mp3","us":"media/us/upset__us_1.mp3"},"examples":[{"en":"It upsets me to think of her all alone in that big house.","cn":"想到她孤身一人守着那所大房子，我就感到不舒服。"},{"en":"He arrived an hour late and upset all our arrangements.","cn":"他迟到了一个小时，把我们的一切安排都打乱了。"}]},"utterances":{"oxford":{"phon":"ˈʌtərəns","pos":"noun","senses":[{"en":"the act of expressing sth in words","cn":"用言语的表达；说话"},{"en":"something that you say","cn":"话语；言论"}]}},"unaccountable":{"media":{"uk":"media/uk/unaccountable__gb_1.mp3","us":"media/us/unaccountable__us_1.mp3"},"oxford":{"phon":"ˌʌnəˈkaʊntəbl","pos":"adjective","senses":[{"en":"impossible to understand or explain","cn":"无法理解的；难以解释的","ex":{"en":"There has been an unaccountable increase in cases of the disease.","cn":"这种疾病的病例出现了无法解释的增加。"}},{"en":"not having to explain or give reasons for your actions to anyone","cn":"无须解释（或说明）的；不负责的","ex":{"en":"Too many government departments are unaccountable to the general public.","cn":"有太多的政府部门不对社会大众负责。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无法解释的；不可理解的；莫名其妙的","en":"Something that is unaccountable does not seem to have any sensible explanation.","ex":{"en":"For some unaccountable reason, it struck me as extremely funny","cn":"不知道为什么，我觉得这极其滑稽。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不负责任的；无须解释的","en":"If you describe a person or organization as unaccountable, you are critical of them because they are not responsible to anyone for their actions, or do not feel they have to explain their actions to anyone.","ex":{"en":"Economic policy in Europe should not be run by an unaccountable committee of governors of central banks.","cn":"欧洲经济政策不应由不负责任的央行行长委员会来执行。"}}]},"examples":[{"en":"Too many government departments are unaccountable to the general public.","cn":"有太多的政府部门不对社会大众负责。"},{"en":"For some unaccountable reason, the letter never arrived.","cn":"不知何故，那封信始终未寄到。"}]},"upper":{"media":{"uk":"media/uk/upper__gb_1.mp3","us":"media/us/upper__us_1.mp3","img":["media/ldoce/img/shoes.jpg"]},"oxford":{"phon":"ˈʌpə(r)","pos":"adjective","senses":[{"en":"located above something else, especially something of the same type or the other of a pair","cn":"上边的，上面的，上层的（尤指同类或一对中的一个）","ex":{"en":"her upper lip","cn":"她的上嘴唇"}},{"en":"at or near the top of something","cn":"上部的；靠上部的","ex":{"en":"There is an upper limit of £20 000 spent on any one project.","cn":"任何项目都有一个 2 万英镑的经费上限。"}},{"en":"located away from the coast, on high ground or towards the north of an area","cn":"内陆的；高地的；向北部的","ex":{"en":"the upper reaches of the river","cn":"河流的上游"}},{"en":"the top part of a shoe that is attached to the sole","cn":"鞋帮；靴面","ex":{"en":"shoes with leather uppers","cn":"皮鞋"},"pos":"noun"},{"en":"a drug that makes you feel excited and full of energy","cn":"兴奋剂","lab":"informal","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-COMPAR 形容词比较级形式","cn":"较高的；上面的","en":"You use upper to describe something that is above something else.","ex":{"en":"There is a smart restaurant on the upper floor","cn":"楼上有一家时尚的餐馆。"}},{"pos":"ADJ-COMPAR 形容词比较级形式","cn":"较上面的；较高的","en":"You use upper to describe the higher part of something.","ex":{"en":"...the upper part of the foot.","cn":"脚面部分"}},{"pos":"PHRASE 短语","cn":"上风；优势；有利地位","en":"If you have the upper hand in a situation, you have more power than the other people involved and can make decisions about what happens.","ex":{"en":"The government was beginning to gain the upper hand","cn":"政府开始占上风。"}},{"pos":"N-COUNT 可数名词","cn":"鞋帮","en":"The upper of a shoe is the top part of it, which is attached to the sole and the heel.","ex":{"en":"Wear well-fitting, lace-up shoes with soft uppers","cn":"穿合脚的、系带的软帮鞋。"}},{"pos":"N-COUNT 可数名词","cn":"兴奋剂","en":"Uppers are drugs that make you feel very happy, excited, and full of energy.","ex":{"en":"...people crazy on alcohol and cocaine and uppers and downers","cn":"酗酒、吸食可卡因、兴奋剂及镇静剂的人"}},{"pos":"","cn":"","en":"a stiff upper lip→see: ;"}]},"examples":[{"en":"There is an upper limit of £20 000 spent on any one project.","cn":"任何项目都有一个 2 万英镑的经费上限。"},{"en":"salaries at the upper end of the pay scale","cn":"工资级别最高的薪金"}]},"unusual":{"media":{"uk":"media/uk/unusual__gb_1.mp3","us":"media/us/unusual__us_1.mp3"},"oxford":{"phon":"ʌnˈjuːʒuəl","pos":"adjective","senses":[{"en":"different from what is usual or normal","cn":"特别的；不寻常的；罕见的","ex":{"en":"The case is highly unusual.","cn":"这个案子极不寻常。"}},{"en":"different from other similar things and therefore interesting and attractive","cn":"独特的；与众不同的；别致的","ex":{"en":"an unusual colour","cn":"特别的颜色"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不寻常的；不常见的；罕见的","en":"If something is unusual, it does not happen very often or you do not see it or hear it very often.","ex":{"en":"They have replanted many areas with rare and unusual plants","cn":"他们在许多地方重新种上了珍稀植物。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"异于常人的；与众不同的；不同凡响的","en":"If you describe someone as unusual, you think that they are interesting and different from other people.","ex":{"en":"He was an unusual man with great business talents.","cn":"此人不同凡响，具有异常敏锐的商业头脑。"}}]},"examples":[{"en":"It's not unusual for young doctors to work a 70-hour week (= it happens often).","cn":"年轻的医生每周工作 70 小时并不罕见。"},{"en":"It's unusual for the trees to flower so early.","cn":"这种树这么早开花很少见。"}]},"unparalleled":{"media":{"uk":"media/uk/unparalleled__gb_1.mp3","us":"media/us/unparalleled__us_1.mp3"},"oxford":{"phon":"ʌnˈpærəleld","pos":"adjective","senses":[{"en":"used to emphasize that something is bigger, better or worse than anything else like it","cn":"无比的；无双的；空前的；绝无仅有的","ex":{"en":"It was an unparalleled opportunity to develop her career.","cn":"这是她发展自己的事业的绝好机会。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"无比的；空前的；无双的；绝无仅有的","en":"If you describe something as unparalleled, you are emphasizing that it is, for example, bigger, better, or worse than anything else of its kind, or anything that has happened before.","ex":{"en":"Germany's unparalleled prosperity is based on wise investments","cn":"德国空前的繁荣是建立在明智的投资基础之上的。"}}]},"examples":[{"en":"The book has enjoyed a success unparalleled in recent publishing history.","cn":"这本书在近期出版史上是空前的成功。"},{"en":"It was an unparalleled opportunity to develop her career.","cn":"这是她发展自己的事业的绝好机会。"}]},"understandably":{"media":{"uk":"media/uk/understandably__gb_1.mp3","us":"media/us/understandably__us_1.mp3"},"oxford":{"phon":"ˌʌndəˈstændəbli","pos":"adverb","senses":[{"en":"in a way that seems normal and reasonable in a particular situation","cn":"可以理解地；正常地；合乎情理地","ex":{"en":"They were understandably disappointed with the result.","cn":"他们对结果感到失望是可以理解的。"}}]},"examples":[{"en":"They were understandably disappointed with the result.","cn":"他们对结果感到失望是可以理解的。"},{"en":"It is understandable that parents are angry, and looking for someone to blame.","cn":""}]},"undergraduate":{"media":{"uk":"media/uk/undergraduate__gb_1.mp3","us":"media/us/undergraduate__us_1.mp3"},"oxford":{"phon":"ˌʌndəˈɡrædʒuət","pos":"noun","senses":[{"en":"a university or college student who is studying for their first degree","cn":"本科生","lab":"British English","ex":{"en":"a first-year undergraduate","cn":"大学一年级学生"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"在校本科生;大学生","en":"An undergraduate is a student at a university or college who is studying for his or her first degree.","ex":{"en":"Economics undergraduates are probably the brightest in the university.","cn":"经济学专业的本科生可能是大学里最聪明的学生。"}}]},"examples":[{"en":"an undergraduate course/student/degree","cn":"大学本科课程/学生/学位"},{"en":"a first-year undergraduate","cn":"大学一年级学生"}]},"unsympathetic":{"media":{"uk":"media/uk/unsympathetic__gb_1.mp3","us":"media/us/unsympathetic__us_1.mp3"},"oxford":{"phon":"ˌʌnˌsɪmpəˈθetɪk","pos":"adjective","senses":[{"en":"not feeling or showing any sympathy","cn":"无同情心的；不表示同情的；冷漠的","ex":{"en":"I told him about the problem but he was totally unsympathetic.","cn":"我把麻烦事告诉了他，但他完全无动于衷。"}},{"en":"not in agreement with something; not supporting an idea, aim, etc.","cn":"（与…）不一致的；有分歧的；（与某意见、目的等）相违的","ex":{"en":"The government was unsympathetic to the needs of the poor.","cn":"政府对穷人的需求无动于衷。"}},{"en":"not easy to like; unpleasant","cn":"不招人喜欢的"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"冷漠的；不体恤人的；无同情心的","en":"If someone is unsympathetic, they are not kind or helpful to a person in difficulties.","ex":{"en":"Her husband was unsympathetic and she felt she had no one to turn to.","cn":"她丈夫并不懂得体恤人，她觉得无人可依靠。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"讨厌的；难缠的","en":"An unsympathetic person is unpleasant and difficult to like.","ex":{"en":"...a very unsympathetic main character","cn":"讨人厌的主角"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（对主张或目标）不支持的，不赞成的","en":"If you are unsympathetic to a particular idea or aim, you are not willing to support it.","ex":{"en":"I'm highly unsympathetic to what you are trying to achieve.","cn":"我极不赞成你试图达成的目标。"}}]},"examples":[{"en":"I told him about the problem but he was totally unsympathetic.","cn":"我把麻烦事告诉了他，但他完全无动于衷。"},{"en":"‘You've only got yourself to blame,’ she said unsympathetically. “","cn":"你只能怪你自己。”她冷漠地说。"}]},"upsets":{"oxford":{"phon":"ʌpˈset","pos":"verb","senses":[{"en":"to make sb/yourself feel unhappy, anxious or annoyed","cn":"使烦恼；使心烦意乱；使生气"},{"en":"to make a plan, situation, etc. go wrong","cn":"打乱；搅乱"}]}},"universal":{"media":{"uk":"media/uk/universal__gb_1.mp3","us":"media/us/universal__us_1.mp3"},"oxford":{"phon":"ˌjuːnɪˈvɜːsl","pos":"adjective","senses":[{"en":"done by or involving all the people in the world or in a particular group","cn":"普遍的；全体的；全世界的；共同的","ex":{"en":"Such problems are a universal feature of old age.","cn":"这类问题是老年人的通病。"}},{"en":"true or right at all times and in all places","cn":"普遍存在的；广泛适用的","ex":{"en":"universal facts about human nature","cn":"人性的普遍现象"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"普遍的；全体的","en":"Something that is universal relates to everyone in the world or everyone in a particular group or society.","ex":{"en":"The insurance industry has produced its own proposals for universal health care","cn":"保险业提出了自己的全民医疗保健方案。"}},{"pos":"ADJ 形容词","cn":"宇宙的;全世界的","en":"Something that is universal affects or relates to every part of the world or the universe.","ex":{"en":"...universal diseases.","cn":"全球性的疾病"}},{"pos":"N-COUNT 可数名词","cn":"普遍原则；通用原理","en":"A universal is a principle that applies in all cases or a characteristic that is present in all members of a particular class.","ex":{"en":"There are no economic universals.","cn":"没有普遍适用的经济学原理。"}}]},"examples":[{"en":"Agreement on this issue is almost universal.","cn":"这个问题几乎取得全体一致的意见。"},{"en":"Such problems are a universal feature of old age.","cn":"这类问题是老年人的通病。"}]},"unrealized":{"media":{"uk":"media/uk/unrealized__gb_1.mp3","us":"media/us/unrealized__us_1.mp3"},"oxford":{"phon":"ˌʌnˈriːəlaɪzd","pos":"adjective","senses":[{"en":"not achieved or created","cn":"未实现的；未完成的；未成为现实的","ex":{"en":"an unrealized ambition","cn":"没有实现的抱负"}},{"en":"not sold or changed into the form of money","cn":"未变现的","lab":"finance","ex":{"en":"unrealized assets","cn":"未变现资产"}}]},"examples":[{"en":"Their potential is unrealized.","cn":"他们没有发挥出潜力。"},{"en":"an unrealized ambition","cn":"没有实现的抱负"}]},"untidy":{"oxford":{"phon":"ʌnˈtaɪdi","pos":"adjective","senses":[{"en":"not neat or well arranged; not in order","cn":"不整洁的；不整齐的；凌乱的","ex":{"en":"an untidy desk","cn":"凌乱的办公桌"}},{"en":"not keeping things neat or well organized","cn":"无条理的；不修边幅的","ex":{"en":"Why do you have to be so untidy?","cn":"你为什么非得这么邋遢？"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不整齐的；凌乱的","en":"If you describe something as untidy, you mean that it is not neat or well arranged.","ex":{"en":"The place quickly became untidy.","cn":"这地方很快变得凌乱不堪。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不修边幅的；不整洁的","en":"If you describe a person as untidy, you mean that they do not care about whether things are neat and well arranged, for example in their house.","ex":{"en":"I'm untidy in most ways.","cn":"我在很多方面都没有条理。"}}]},"media":{"uk":"media/uk/untidy__gb_1.mp3","us":"media/us/untidy__us_1.mp3"},"examples":[{"en":"Why do you have to be so untidy?","cn":"你为什么非得这么邋遢？"},{"en":"an untidy desk","cn":"凌乱的办公桌"}]},"ungrammatical":{"oxford":{"phon":"ˌʌnɡrəˈmætɪkl","pos":"adjective","senses":[{"en":"not following the rules of grammar","cn":"违反语法规则的；不合语法的"}]},"media":{"uk":"media/uk/ungrammatical__gb_1.mp3","us":"media/us/ungrammatical__us_1.mp3"}},"unjust":{"media":{"uk":"media/uk/unjust__gb_1.mp3","us":"media/us/unjust__us_1.mp3"},"oxford":{"phon":"ˌʌnˈdʒʌst","pos":"adjective","senses":[{"en":"not deserved or fair","cn":"不公平的；不公正的；非正义的","ex":{"en":"an unjust law","cn":"不公正的法律"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"非正义的；不公正的；不公平的","en":"If you describe an action, system, or law as unjust, you think that it treats a person or group badly in a way that they do not deserve.","ex":{"en":"The attack on Charles was deeply unjust","cn":"对查尔斯的攻击甚为不公。"}}]},"examples":[{"en":"She felt that she had been unjustly treated.","cn":"她觉得自己受到了不公平的待遇。"},{"en":"an unjust law","cn":"不公正的法律"}]},"ugly":{"oxford":{"phon":"ˈʌɡli","pos":"adjective","senses":[{"en":"unpleasant to look at","cn":"丑陋的；难看的","ex":{"en":"an ugly face","cn":"丑陋的面孔"}},{"en":"unpleasant or dangerous; involving threats or violence","cn":"令人不快的；危险的；险恶的；凶险的","ex":{"en":"an ugly incident/scene","cn":"危险事件／场面"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"丑陋的；难看的","en":"If you say that someone or something is ugly, you mean that they are very unattractive and unpleasant to look at.","ex":{"en":"...an ugly little hat","cn":"难看的小帽子"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（通常因涉及暴力、挑衅行为而）令人厌恶的，邪恶的，恶性的","en":"If you refer to an event or situation as ugly, you mean that it is very unpleasant, usually because it involves violent or aggressive behaviour.","ex":{"en":"There have been some ugly scenes","cn":"出现了一些恶性事件。"}},{"pos":"","cn":"","en":"to rear its ugly head→see: ;"}]},"media":{"uk":"media/uk/ugly__gb_1.mp3","us":"media/us/ugly__us_1.mp3"},"examples":[{"en":"There were ugly scenes in the streets last night as rioting continued.","cn":"昨晚暴乱持续之际，街上险象环生。"},{"en":"an ugly face","cn":"丑陋的面孔"}]},"unyielding":{"media":{"uk":"media/uk/unyielding__gb_1.mp3","us":"media/us/unyielding__us_1.mp3"},"oxford":{"phon":"ʌnˈjiːldɪŋ","pos":"adjective","senses":[{"en":"if a person is unyielding, they are not easily influenced and they are unlikely to change their mind","cn":"坚定的；顽强不屈的；固执的"},{"en":"an unyielding substance or object does not bend or break when pressure is put on it","cn":"不弯曲的；坚固的"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"百折不回的；不屈不挠的；坚定不移的","en":"You describe someone as unyielding when they have very strong, fixed ideas about something and are unlikely to change their mind.","ex":{"en":"The authorities proved unyielding on one crucial opposition demand","cn":"面对反对党这一重大诉求，当局立场坚定。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"坚固的；坚硬的","en":"If a barrier or surface is unyielding, it is very solid or hard.","ex":{"en":"...the troopers, who had to build roads through those unyielding mountains","cn":"必须打穿这些硬石山来筑路的装甲兵"}}]},"examples":[{"en":"an unyielding resistance to change","cn":"固执己见﹐不愿改变"},{"en":"a harsh unyielding landscape","cn":"景色粗犷﹑线条硬朗的地貌"}]},"unconquerable":{"media":{"uk":"media/uk/unconquerable__gb_1.mp3","us":"media/us/unconquerable__us_1.mp3"},"oxford":{"phon":"ʌnˈkɒŋkərəbl","pos":"adjective","senses":[{"en":"too strong to be defeated or changed","cn":"不可战胜的；坚不可摧的；难以改变的"}]}},"underwear":{"media":{"uk":"media/uk/underwear__gb_1.mp3","us":"media/us/underwear__us_1.mp3"},"oxford":{"phon":"ˈʌndəweə(r)","pos":"noun","senses":[{"en":"clothes that you wear under other clothes and next to the skin","cn":"内衣；衬衣","ex":{"en":"I never wear underwear.","cn":"我从不穿内衣。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"内衣","en":"Underwear is clothing such as vests and pants which you wear next to your skin under your other clothes.","ex":{"en":"...a couple who went for a late-night swim in their underwear.","cn":"深夜穿着内衣去游泳的一对夫妇"}}]},"examples":[{"en":"She packed one change of underwear.","cn":"她打行李时带了一套换洗的内衣。"},{"en":"You just need to take a change of underwear.","cn":"你只需带一套换洗的内衣。"}]},"uproar":{"media":{"uk":"media/uk/uproar__gb_1.mp3","us":"media/us/uproar__us_1.mp3"},"oxford":{"phon":"ˈʌprɔː(r)","pos":"noun","senses":[{"en":"a situation in which people shout and make a lot of noise because they are angry or upset about something","cn":"吵闹；喧嚣；叫喊","ex":{"en":"The room was in (an) uproar.","cn":"屋子里一片嘈杂。"}},{"en":"a situation in which there is a lot of public criticism and angry argument about something that somebody has said or done","cn":"骚动；怨愤","ex":{"en":"The article caused (an) uproar.","cn":"这篇文章引起了轩然大波。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"喧闹；吵闹；鼓噪；骚动","en":"If there is uproar, there is a lot of shouting and noise because people are very angry or upset about something.","ex":{"en":"The announcement caused uproar in the crowd","cn":"公告在人群中引起了骚动。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"骚乱；骚动","en":"You can also use uproar to refer to a lot of public criticism and debate about something that has made people angry.","ex":{"en":"The town is in uproar over the dispute","cn":"整个城市因为这次争端而陷入了骚动。"}}]},"examples":[{"en":"Her comments provoked (an) uproar from the audience.","cn":"她的评论激起了听众的鼓噪。"},{"en":"The article caused (an) uproar.","cn":"这篇文章引起了轩然大波。"}]},"unwilling":{"media":{"uk":"media/uk/unwilling__gb_1.mp3","us":"media/us/unwilling__us_1.mp3"},"oxford":{"phon":"ʌnˈwɪlɪŋ","pos":"adjective","senses":[{"en":"not wanting to do something and refusing to do it","cn":"不情愿；不愿意","g":"[not usually before noun]","ex":{"en":"They are unwilling to invest any more money in the project.","cn":"他们不想在这个项目上再增加投资。"}},{"en":"not wanting to do or be something, but forced to by other people","cn":"勉强的；无奈的；迫不得已的","g":"[only before noun]","ex":{"en":"an unwilling hero","cn":"自己不愿却被抬举的英雄"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不愿意的；不情愿的；不乐意的","en":"If you are unwilling to do something, you do not want to do it and will not agree to do it.","ex":{"en":"Initially the government was unwilling to accept the defeat","cn":"最初政府不愿意承认失败。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不愿意的；勉强的","en":"You can use unwilling to describe someone who does not really want to do the thing they are doing.","ex":{"en":"A youthful teacher, he finds himself an unwilling participant in school politics","cn":"作为一名年轻教师，他发现自己并不情愿地参与到了学校的权力争斗中。"}}]},"examples":[{"en":"She was unable, or unwilling, to give me any further details.","cn":"她不能，或不愿意，向我提供进一步的细节。"},{"en":"They are unwilling to invest any more money in the project.","cn":"他们不想在这个项目上再增加投资。"}]},"unhappy":{"media":{"uk":"media/uk/unhappy__gb_1.mp3","us":"media/us/unhappy__us_1.mp3"},"oxford":{"phon":"ʌnˈhæpi","pos":"adjective","senses":[{"en":"not happy; sad","cn":"不快乐的；不幸福的；难过的；悲伤的","ex":{"en":"to feel/look/seem/sound/become unhappy","cn":"感到／看来／似乎／听起来／变得不愉快"}},{"en":"not pleased or satisfied with somebody/something","cn":"不悦的；不高兴的；不满的","ex":{"en":"unhappy customers","cn":"不满意的顾客"}},{"en":"not suitable","cn":"不适当的；不合意的","lab":"formal","ex":{"en":"an unhappy coincidence","cn":"不幸的巧合"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不幸福的；不快乐的；愁苦的","en":"If you are unhappy, you are sad and depressed.","ex":{"en":"Her marriage is in trouble and she is desperately unhappy","cn":"她的婚姻陷入困境，她为此非常郁闷。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不高兴的；不满意的","en":"If you are unhappy about something, you are not pleased about it or not satisfied with it.","ex":{"en":"He has been unhappy with his son's political leanings","cn":"他一向不满意儿子的政治倾向。"}},{"pos":"ADJ 形容词","cn":"令人不满的；不可取的","en":"An unhappy situation or choice is not satisfactory or desirable.","ex":{"en":"...this unhappy chapter in the history of relations between our two countries","cn":"我们两国关系史上不愉快的这一篇章"}}]},"examples":[{"en":"I didn't realize but he was deeply unhappy at that time.","cn":"我没有察觉到他那时非常不开心。"},{"en":"He was unhappy at being left out of the team.","cn":"他对未能入选球队感到不高兴。"}]},"unapproachable":{"media":{"uk":"media/uk/unapproachable__gb_1.mp3","us":"media/us/unapproachable__us_1.mp3"},"oxford":{"phon":"ˌʌnəˈprəʊtʃəbl","pos":"adjective","senses":[{"en":"not friendly or easy to talk to","cn":"不友好的；难接近的；不好说话的","ex":{"en":"Neighbours described the man as being difficult and unapproachable.","cn":"邻居们说这名男子不随和，难接近。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"难以接近的；不友好的","en":"If you describe someone as unapproachable, you mean that they seem to be difficult to talk to and not very friendly.","ex":{"en":"She was somewhat unapproachable but I'm sure she wanted to be friendly.","cn":"她有些不好接近，但我确信她想表现得友好一些。"}}]}},"uncovered":{"media":{"uk":"media/uk/uncovered__gb_1.mp3","us":"media/us/uncovered__us_1.mp3"},"oxford":{"phon":"ʌnˈkʌvəd","pos":"adjective","senses":[{"en":"not covered by anything","cn":"裸露的；暴露的；无覆盖的","ex":{"en":"His head was uncovered.","cn":"他光着头。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"无覆盖物的；无遮盖的；未盖盖子的","en":"Something that is left uncovered does not have anything covering it.","ex":{"en":"Minor cuts and grazes can usually be left uncovered to heal by themselves","cn":"轻微的划伤和擦伤通常不用包扎就可以自愈。"}}]},"examples":[{"en":"His head was uncovered.","cn":"他光着头。"}]},"unethical":{"media":{"uk":"media/uk/unethical__gb_1.mp3","us":"media/us/unethical__us_1.mp3"},"oxford":{"phon":"ʌnˈeθɪkl","pos":"adjective","senses":[{"en":"not morally acceptable","cn":"不道德的","ex":{"en":"The doctor was suspended amid accusations of unethical behaviour.","cn":"该医生因被指控不道德行为而被停职。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不道德的；不合乎道德标准的","en":"If you describe someone's behaviour as unethical, you think it is wrong and unacceptable according to a society's rules or people's beliefs.","ex":{"en":"It's simply unethical to promote and advertise such a dangerous product","cn":"宣传推广如此危险的产品完全是不道德的。"}}]},"examples":[{"en":"unethical behaviour","cn":"不道德行为"},{"en":"unethical medical practices","cn":"不道德的医疗行为"}]},"unite":{"media":{"uk":"media/uk/unite__gb_1.mp3","us":"media/us/unite__us_1.mp3"},"oxford":{"phon":"juˈnaɪt","pos":"verb","senses":[{"en":"to join together with other people in order to do something as a group","cn":"（为某事）联合，联手，团结","g":"[intransitive]","ex":{"en":"Nationalist parties united to oppose the government's plans.","cn":"民族主义党派联合反对政府的计划。"}},{"en":"to make people or things join together to form a unit; to join together","cn":"（与某人或集体）联结，联合；统一","g":"[transitive, intransitive]","ex":{"en":"A special bond unites our two countries.","cn":"一种特殊的纽带把我们两国联结起来。"}},{"en":"one of the largest British trade unions with members in most industries. It was formed in 2007 when Amicus joined with the TGWU.","cn":"英国最大的工会之一，成员众多。它成立于2007年，当时Amicus加入了TGWU。","pos":""}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"（使）团结；（使）联合","en":"If a group of people or things unite or if something unites them, they join together and act as a group.","ex":{"en":"The two parties have been trying to unite since the New Year","cn":"这两个党从新年开始就试图联合。"}}]},"examples":[{"en":"Local resident groups have united in opposition to the plan.","cn":"当地居民团体已联合起来反对这项计划。"},{"en":"A special bond unites our two countries.","cn":"一种特殊的纽带把我们两国联结起来。"}]},"unintentional":{"oxford":{"phon":"ˌʌnɪnˈtenʃənl","pos":"adjective","senses":[{"en":"not done deliberately, but happening by accident","cn":"无意的；非故意的；偶然的","ex":{"en":"Perhaps I misled you, but it was quite unintentional (= I did not mean to).","cn":"也许我误导了你，但那绝不是有意的。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"非故意的；无心的","en":"Something that is unintentional is not done deliberately, but happens by accident.","ex":{"en":"Perhaps he had slightly misled them, but it was quite unintentional","cn":"也许他给他们造成了小小的误导，但他不是有意的。"}}]},"media":{"uk":"media/uk/unintentional__gb_1.mp3","us":"media/us/unintentional__us_1.mp3"},"examples":[{"en":"Perhaps I misled you, but it was quite unintentional (= I did not mean to).","cn":"也许我误导了你，但那绝不是有意的。"},{"en":"They had unintentionally provided wrong information.","cn":"他们无意中提供了错误的信息。"}]},"unbelievable":{"media":{"uk":"media/uk/unbelievable__gb_1.mp3","us":"media/us/unbelievable__us_1.mp3"},"oxford":{"phon":"ˌʌnbɪˈliːvəbl","pos":"adjective","senses":[{"en":"used to emphasize how good, bad or extreme something is","cn":"非常好（或坏、极端）的；难以置信的；惊人的","lab":"informal","ex":{"en":"We had an unbelievable (= very good) time in Paris.","cn":"我们在巴黎的日子快活极了。"}},{"en":"very difficult to believe and unlikely to be true","cn":"难以相信的；不真实的","ex":{"en":"I found the whole story bizarre, not to say unbelievable.","cn":"我觉得整个事件经过荒诞不经，更不用说不可信了。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不可思议的；难以置信的；极好的；非常棒的","en":"If you say that something is unbelievable, you are emphasizing that it is very good, impressive, intense, or extreme.","ex":{"en":"His guitar solos are just unbelievable","cn":"他的吉他独奏棒极了。"}},{"pos":"ADJ 形容词","cn":"极其糟糕的；令人震惊的；令人无法相信的","en":"You can use unbelievable to emphasize that you think something is very bad or shocking.","ex":{"en":"I find it unbelievable that people can accept this sort of behaviour","cn":"人们竟能接受这样的行为，我震惊不已。"}},{"pos":"ADJ 形容词","cn":"不可信的；不像真实的","en":"If an idea or statement is unbelievable, it seems so unlikely to be true that you cannot believe it.","ex":{"en":"I still find this story both fascinating and unbelievable","cn":"我仍觉得这个故事既有趣又不太可信。"}}]},"examples":[{"en":"I found the whole story bizarre, not to say unbelievable.","cn":"我觉得整个事件经过荒诞不经，更不用说不可信了。"},{"en":"It's unbelievable that (= very shocking) they have permitted this trial to go ahead.","cn":"令人震惊的是他们竟允许进行这项审讯。"}]},"us":{"media":{"uk":"media/uk/us__gb_1.mp3","us":"media/us/us__us_1.mp3"},"oxford":{"phon":"əs","pos":"pronoun","senses":[{"en":"used when the speaker or writer and another or others are the object of a verb or preposition, or after the verb be","cn":"我们","ex":{"en":"She gave us a picture as a wedding present.","cn":"她赠给我们一幅画作结婚礼物。"}},{"en":"me","cn":"我","lab":"British English, informal，，","ex":{"en":"Give us the newspaper, will you?","cn":"把报纸给我好吗？"}},{"en":"United States (of America)","cn":"美国；美利坚合众国","ex":{"en":"She became a US citizen.","cn":"她成了美国公民。"},"pos":"abbreviation"}]},"collins":{"senses":[{"pos":"N-PROPER 专有名词","cn":"美国","en":"The US is an abbreviation for (缩略=) the United States .","ex":{"en":"The first time I saw TV was when I arrived in the US in 1956","cn":"我第一次看到电视机是我1956年到美国的时候。"}}]},"examples":[{"en":"She became a US citizen.","cn":"她成了美国公民。"},{"en":"the US dollar","cn":"美元"}]},"unconscious":{"media":{"uk":"media/uk/unconscious__gb_1.mp3","us":"media/us/unconscious__us_1.mp3"},"oxford":{"phon":"ʌnˈkɒnʃəs","pos":"adjective","senses":[{"en":"in a state like sleep because of an injury or illness, and not able to use your senses","cn":"无知觉的；昏迷的；不省人事的","ex":{"en":"They found him lying unconscious on the floor.","cn":"他们发现他晕倒在地板上。"}},{"en":"existing or happening without you realizing or being aware; not deliberate","cn":"无意识的；潜意识的；自然流露的","ex":{"en":"unconscious desires","cn":"自然流露的欲望"}},{"en":"not aware of somebody/something; not noticing something; not conscious","cn":"未察觉；未意识到；未注意","ex":{"en":"She is unconscious of the effect she has on people.","cn":"她没有察觉自己对大众的影响。"}},{"en":"the part of a person’s mind with thoughts, feelings, etc. that they are not aware of and cannot control but that can sometimes be understood by studying their behaviour or dreams","cn":"无意识（不察觉的心理活动）","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"不省人事的；失去知觉的；神志不清的","en":"Someone who is unconscious is in a state similar to sleep, usually as the result of a serious injury or a lack of oxygen.","ex":{"en":"By the time ambulancemen arrived he was unconscious","cn":"救护人员到达时他已经不省人事了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不知道的；未觉察的；没注意到的","en":"If you are unconscious of something, you are unaware of it.","ex":{"en":"He himself seemed totally unconscious of his failure","cn":"他本人似乎对自己的失败全然不知。"}},{"pos":"ADJ 形容词","cn":"潜意识的；无意识的","en":"If feelings or attitudes are unconscious, you are not aware that you have them, but they show in the way that you behave.","ex":{"en":"Unconscious envy manifests itself very often as this kind of arrogance","cn":"潜意识里的嫉妒常表现为这种傲慢自大。"}},{"pos":"N-SING 单数名词","cn":"无意识","en":"Your unconscious is the part of your mind that contains feelings and ideas that you do not know about or cannot control.","ex":{"en":"In examining the content of the unconscious, Freud called into question some deeply-held beliefs.","cn":"在审视无意识的内容时，弗洛伊德对一些根深蒂固的看法提出了质疑。"}}]},"examples":[{"en":"She is unconscious of the effect she has on people.","cn":"她没有察觉自己对大众的影响。"},{"en":"They found him lying unconscious on the floor.","cn":"他们发现他晕倒在地板上。"}]},"unfailingly":{"oxford":{"phon":"ʌnˈfeɪlɪŋli","pos":"adverb","senses":[{"en":"in a way that you can rely on to always be there and always be the same","cn":"可靠的；一贯的；永久的","ex":{"en":"unfailingly loyal/polite","cn":"忠诚不渝；一贯地彬彬有礼"}}]},"media":{"uk":"media/uk/unfailingly__gb_1.mp3","us":"media/us/unfailingly__us_1.mp3"},"examples":[{"en":"unfailingly loyal/polite","cn":"一贯地忠心耿耿/彬彬有礼"}]},"unemployable":{"media":{"uk":"media/uk/unemployable__gb_1.mp3","us":"media/us/unemployable__us_1.mp3"},"oxford":{"phon":"ˌʌnɪmˈplɔɪəbl","pos":"adjective","senses":[{"en":"not having the skills or qualities that you need to get a job","cn":"不宜雇用的（因缺乏所需技能或资质不足）","ex":{"en":"Is Britain producing a generation of unemployable young people?","cn":"英国是否正在产生一代失业的年轻人？"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（因缺乏相应的技术或能力而）不能受雇的","en":"Someone who is unemployable does not have a job and is unlikely to get a job, because they do not have the skills or abilities that an employer might want.","ex":{"en":"He freely admits he is unemployable and will probably never find a job.","cn":"他坦率地承认自己没什么技能，可能永远也找不到一份工作。"}}]}},"upsetting":{"oxford":{"phon":"ʌpˈsetɪŋ","pos":"adjective","senses":[{"en":"making you feel unhappy, anxious or annoyed","cn":"令人不快（或忧虑、苦恼）的","ex":{"en":"I could see that it had been an upsetting experience for him.","cn":"我看得出那对于他是个痛苦的经历。"}}]},"media":{"uk":"media/uk/upsetting__gb_1.mp3","us":"media/us/upsetting__us_1.mp3"},"examples":[{"en":"an upsetting experience","cn":"令人苦恼的经历"},{"en":"Don’t do anything that would upset him.","cn":""}]},"units":{"oxford":{"phon":"ˈjuːnɪt","pos":"noun","senses":[{"en":"a single thing, person or group that is complete by itself but can also form part of sth larger","cn":"单独的事物（或人、群体）；单位；单元"},{"en":"( business","cn":"商 ) a single item of the type of product that a company sells 一件（商品）；单位"}]}},"understudy":{"media":{"uk":"media/uk/understudy__gb_1.mp3","us":"media/us/understudy__us_1.mp3"},"oxford":{"phon":"ˈʌndəstʌdi","pos":"noun","senses":[{"en":"an actor who learns the part of another actor in a play so that they can play that part if necessary","cn":"候补演员；替角","ex":{"en":"She worked as an understudy to Elaine Page.","cn":"她担任了伊莲•佩姬的候补演员。"}},{"en":"to learn a part in a play as an understudy; to act as an understudy to somebody","cn":"排练当候补演员；做替角","ex":{"en":"She once understudied Marilyn Monroe.","cn":"她曾师从玛丽莲·梦露。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"预备演员；替角儿","en":"An actor's or actress's understudy is the person who has learned their part in a play and can act the part if the actor or actress is ill.","ex":{"en":"He was an understudy to Charlie Chaplin on a tour of the USA.","cn":"他是查理·卓别麟美国巡演期间的替角儿。"}}]}},"unwarranted":{"media":{"uk":"media/uk/unwarranted__gb_1.mp3","us":"media/us/unwarranted__us_1.mp3"},"oxford":{"phon":"ʌnˈwɒrəntɪd","pos":"adjective","senses":[{"en":"not reasonable or necessary; not appropriate","cn":"不合理的；不必要的；无正当理由的；不适当的","ex":{"en":"Much of the criticism was totally unwarranted.","cn":"这种批评基本上是毫无道理的。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"无端的；无正当理由的","en":"If you describe something as unwarranted, you are critical of it because there is no need or reason for it.","ex":{"en":"Any attempt to discuss the issue of human rights was rejected as an unwarranted interference in the country's internal affairs","cn":"任何讨论人权问题的尝试都会被以无端干预该国内政为由加以拒绝。"}}]},"examples":[{"en":"Much of the criticism was totally unwarranted.","cn":"这种批评基本上是毫无道理的。"},{"en":"unwarranted interference","cn":"无理干涉"}]},"usually":{"media":{"uk":"media/uk/usually__gb_1.mp3","us":"media/us/usually__us_1.mp3"},"oxford":{"phon":"ˈjuːʒuəli","pos":"adverb","senses":[{"en":"in the way that is usual or normal; most often","cn":"通常地；正常地；一般地；经常地","ex":{"en":"How long does the journey usually take?","cn":"这段旅程通常需要多长时间？"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"通常;惯常","en":"If something usually happens, it is the thing that most often happens in a particular situation.","ex":{"en":"The best information about hotels usually comes from friends and acquaintances who have been there","cn":"关于酒店的最可靠信息通常来自曾经去过那里的朋友和熟人。"}},{"pos":"PHRASE 短语","cn":"比平时更…","en":"You use more than usually to show that something shows even more of a particular quality than it normally does.","ex":{"en":"She felt more than usually hungry after her excursion","cn":"远足后，她比平时感觉更饿。"}}]},"examples":[{"en":"How long does the journey usually take?","cn":"这段旅程通常需要多长时间？"},{"en":"I'm usually home by 6 o'clock.","cn":"我一般 6 点钟回到家。"}]},"uncomfortable":{"oxford":{"phon":"ʌnˈkʌmftəbl","pos":"adjective","senses":[{"en":"not letting you feel physically comfortable; unpleasant to wear, sit on, etc.","cn":"使人不舒服的；令人不舒适的","ex":{"en":"uncomfortable shoes","cn":"不舒适的鞋子"}},{"en":"not feeling physically relaxed, warm, etc.","cn":"感到难受的；感觉不舒服（或不暖和等）的","ex":{"en":"I was sitting in an extremely uncomfortable position.","cn":"我坐着的姿势难受极了。"}},{"en":"anxious, embarrassed or afraid and unable to relax; making you feel like this","cn":"（使）焦虑的；尴尬的；害怕的；不自在的","ex":{"en":"He looked distinctly uncomfortable when the subject was mentioned.","cn":"提到这个话题，他明显表现出不安。"}},{"en":"unpleasant or difficult to deal with","cn":"棘手的；麻烦的；难处理的","ex":{"en":"an uncomfortable fact","cn":"令人头痛的事实"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不自在的；不安的；尴尬的","en":"If you are uncomfortable, you are slightly worried or embarrassed, and not relaxed and confident.","ex":{"en":"The request for money made them feel uncomfortable","cn":"索要金钱让他们有些不安。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不舒服的；不舒适的","en":"Something that is uncomfortable makes you feel slight pain or physical discomfort when you experience it or use it.","ex":{"en":"Wigs are hot and uncomfortable to wear constantly","cn":"头上老是顶着假发，又热又不舒服。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"身体不适的；不舒服的","en":"If you are uncomfortable, you are not physically content and relaxed, and feel slight pain or discomfort.","ex":{"en":"I sometimes feel uncomfortable after eating in the evening","cn":"我晚上吃完饭有时会觉得不舒服。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（处境、事实等）令人不快的，令人担忧的，令人不安的","en":"You can describe a situation or fact as uncomfortable when it is difficult to deal with and causes problems and worries.","ex":{"en":"It is uncomfortable to think of our own death, but we need to","cn":"想到人终有一死会感到不舒服，但我们不得不去面对。"}}]},"media":{"uk":"media/uk/uncomfortable__gb_1.mp3","us":"media/us/uncomfortable__us_1.mp3"},"examples":[{"en":"He looked distinctly uncomfortable when the subject was mentioned.","cn":"提到这个话题，他显然局促不安起来。"},{"en":"I had the uncomfortable feeling that it was my fault.","cn":"我内心惴惴不安，觉得那是我的过错。"}]},"upside":{"media":{"uk":"media/uk/upside__gb_1.mp3","us":"media/us/upside__us_1.mp3"},"oxford":{"phon":"ˈʌpsaɪd","pos":"noun","senses":[{"en":"the more positive aspect of a situation that is generally bad","cn":"（糟糕局面的）好的一面，光明的一面，正面"}]},"examples":[{"en":"The upside of the whole thing is that we got a free trip to Jamaica.","cn":"整个事情的好处是我们得到一次免费去牙买加旅行的机会。"}]},"undiscovered":{"media":{"uk":"media/uk/undiscovered__gb_1.mp3","us":"media/us/undiscovered__us_1.mp3"},"oxford":{"phon":"ˌʌndɪˈskʌvəd","pos":"adjective","senses":[{"en":"that has not been found or noticed; that has not been discovered","cn":"未找到（或注意到）的；未被发现的","ex":{"en":"a previously undiscovered talent","cn":"以前没被发掘的天才"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未被发现的；未知的；未被注意的","en":"Something that is undiscovered has not been discovered or noticed.","ex":{"en":"The name Vulcan was given to the undiscovered planet","cn":"一颗不为人知的行星被命名为“祝融”。"}}]},"examples":[{"en":"a previously undiscovered talent","cn":"以前没被发掘的天才"}]},"unappreciated":{"media":{"uk":"media/uk/unappreciated__gb_1.mp3","us":"media/us/unappreciated__us_1.mp3"},"oxford":{"phon":"ˌʌnəˈpriːʃieɪtɪd","pos":"adjective","senses":[{"en":"not having your work or your qualities recognized and enjoyed by other people; not appreciated","cn":"无人赏识；不被欣赏；无人感激","ex":{"en":"He was in a job where he felt unappreciated and undervalued.","cn":"他以前的工作未让他感到受赏识和重视。"}}]},"examples":[{"en":"He was in a job where he felt unappreciated and undervalued.","cn":"他以前的工作未让他感到受赏识和重视。"}]},"uncultivated":{"media":{"uk":"media/uk/uncultivated__gb_1.mp3","us":"media/us/uncultivated__us_1.mp3"},"oxford":{"phon":"ʌnˈkʌltɪveɪtɪd","pos":"adjective","senses":[{"en":"not used for growing crops","cn":"未经耕作的；未开垦的"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未开垦的；未耕种的","en":"If land is uncultivated, there are no crops growing on it.","ex":{"en":"...the flat, largely uncultivated plains.","cn":"基本上还未曾开垦的平原"}}]}},"underlying":{"media":{"uk":"media/uk/underlying__gb_1.mp3","us":"media/us/underlying__us_1.mp3"},"oxford":{"phon":"ˌʌndəˈlaɪɪŋ","pos":"adjective","senses":[{"en":"important in a situation but not always easily noticed or stated clearly","cn":"根本的；潜在的；隐含的","ex":{"en":"The underlying assumption is that the amount of money available is limited.","cn":"隐含的假定是可用的资金有限。"}},{"en":"existing under the surface of something else","cn":"表面下的；下层的","ex":{"en":"the underlying rock formation","cn":"地表下的岩石结构"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"潜在的；隐藏的；深层的；根本的","en":"The underlying features of an object, event, or situation are not obvious, and it may be difficult to discover or reveal them.","ex":{"en":"To stop a problem you have to understand its underlying causes","cn":"要想杜绝问题的发生，必须弄清它的深层原因。"}},{"pos":"ADJ 形容词","cn":"表面下的；下层的","en":"You describe something as underlying when it is below the surface of something else.","ex":{"en":"...hills with the hard underlying rock poking through the turf","cn":"坚硬的下层岩石穿过草皮凸出来的山丘"}}]},"examples":[{"en":"Unemployment may be an underlying cause of the rising crime rate.","cn":"失业可能是犯罪率攀升的潜在原因。"},{"en":"The underlying assumption is that the amount of money available is limited.","cn":"隐含的假定是可用的资金有限。"}]},"unsteady":{"oxford":{"phon":"ʌnˈstedi","pos":"adjective","senses":[{"en":"not completely in control of your movements so that you might fall","cn":"站不稳的；摇晃的","ex":{"en":"She is still a little unsteady on her feet after the operation.","cn":"手术以后她还有点站不稳。"}},{"en":"shaking or moving in a way that lacks control","cn":"颤抖的；抖动的","ex":{"en":"an unsteady hand","cn":"颤抖的手"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"脚步不稳的；身体摇晃的","en":"If you are unsteady, you have difficulty doing something, for example walking, because you cannot completely control your legs or your body.","ex":{"en":"The boy was very unsteady and had staggered around when he got up","cn":"男孩站立不稳，并且起身后四下走动时步子踉跄。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不稳定的；不可靠的；无法捉摸的；变幻无常的","en":"If you describe something as unsteady, you mean that it is not regular or stable, but unreliable or unpredictable.","ex":{"en":"His voice was unsteady and only just audible","cn":"他的声音发颤，而且小得只刚刚能听见。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不牢固的；不稳固的；不结实的","en":"Unsteady objects are not held, fixed, or balanced securely.","ex":{"en":"...a slightly unsteady item of furniture.","cn":"一件稍微有些不结实的家具"}}]},"media":{"uk":"media/uk/unsteady__gb_1.mp3","us":"media/us/unsteady__us_1.mp3"},"examples":[{"en":"She is still a little unsteady on her feet after the operation.","cn":"手术以后她还有点站不稳。"},{"en":"an unsteady hand","cn":"颤抖的手"}]},"unfortunate":{"media":{"uk":"media/uk/unfortunate__gb_1.mp3","us":"media/us/unfortunate__us_1.mp3"},"oxford":{"phon":"ʌnˈfɔːtʃənət","pos":"adjective","senses":[{"en":"having bad luck; caused by bad luck","cn":"不幸的；倒霉的","ex":{"en":"He was unfortunate to lose in the final round.","cn":"他不幸在最后一轮输了。"}},{"en":"if you say that a situation is unfortunate, you wish that it had not happened or that it had been different","cn":"令人遗憾的；可惜的","lab":"formal","ex":{"en":"She described the decision as ‘unfortunate’.","cn":"她把这项决定说成是“令人遗憾”。"}},{"en":"embarrassing and/or offensive","cn":"令人尴尬的；不适当的；得罪人的","ex":{"en":"It was an unfortunate choice of words.","cn":"那是一种不恰当的措辞。"}},{"en":"a person who does not have much luck, money, etc.","cn":"不幸的人","ex":{"en":"one of life’s unfortunates","cn":"人生中的不幸者之一"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不幸的；倒霉的","en":"If you describe someone as unfortunate, you mean that something unpleasant or unlucky has happened to them. You can also describe the unpleasant things that happen to them as unfortunate .","ex":{"en":"Some unfortunate person passing below could all too easily be seriously injured","cn":"从下面经过的倒霉蛋儿很容易受重伤。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不恰当的；尴尬的；棘手的","en":"If you describe something that has happened as unfortunate, you think that it is inappropriate, embarrassing, awkward, or undesirable.","ex":{"en":"It really is desperately unfortunate that this should have happened just now.","cn":"刚才竟发生这样的事儿，实在是太不合时宜了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"穷困潦倒的；生活艰难的","en":"You can describe someone as unfortunate when they are poor or have a difficult life.","ex":{"en":"Every year we have charity days to raise money for unfortunate people.","cn":"每年我们都有慈善日来筹款帮助贫困人群。"}}]},"examples":[{"en":"She described the decision as ‘unfortunate’.","cn":"她把这项决定说成是“令人遗憾”。"},{"en":"You're putting me in a most unfortunate position.","cn":"你正在把我推入十分可悲的处境。"}]},"uprightness":{"oxford":{"phon":"ˈʌpraɪtnəs","pos":"noun","senses":[{"en":"behaviour or attitudes that are very moral and honest","cn":"正直的行为（或态度）；诚实；公正"}]},"media":{"uk":"media/uk/uprightness__gb_1.mp3","us":"media/us/uprightness__us_1.mp3"},"examples":[{"en":"The chimpanzee stood upright and grasped the bars of its cage.","cn":""},{"en":"Katie was still awake, sitting bolt upright (= sitting with her back very straight ) staring at the television.","cn":""}]},"uncertain":{"media":{"uk":"media/uk/uncertain__gb_1.mp3","us":"media/us/uncertain__us_1.mp3"},"oxford":{"phon":"ʌnˈsɜːtn","pos":"adjective","senses":[{"en":"feeling doubt about something; not sure","cn":"无把握；犹豫；拿不准","g":"[not before noun]","lab":"British English","ex":{"en":"They're both uncertain about what to do.","cn":"他们两人都拿不定主意该怎么办。"}},{"en":"likely to change, especially in a negative or unpleasant way","cn":"多变的；难预料的","ex":{"en":"Our future looks uncertain.","cn":"我们似乎前途渺茫。"}},{"en":"not definite or decided","cn":"不确定的；未决定的","ex":{"en":"It is uncertain what his role in the company will be.","cn":"他在公司担当什么职务尚未决定。"}},{"en":"not confident","cn":"信心不足的；迟疑的","ex":{"en":"The baby took its first uncertain steps.","cn":"宝宝迈出了最初的蹒跚脚步。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不确定的；迟疑的；无把握的","en":"If you are uncertain about something, you do not know what you should do, what is going to happen, or what the truth is about something.","ex":{"en":"He was uncertain about his brother's intentions","cn":"他拿不准他哥哥的意图是什么。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"未知的；不明了的；不确定的","en":"If something is uncertain, it is not known or definite.","ex":{"en":"How far the republics can give practical help, however, is uncertain","cn":"然而，这些共和国究竟能够提供多少切实可行的帮助还未可知。"}},{"pos":"PHRASE 短语","cn":"明确地；毫不含糊地","en":"If you say that someone tells a person something in no uncertain terms, you are emphasizing that they say it strongly and clearly so that there is no doubt about what they mean.","ex":{"en":"She told him in no uncertain terms to go away.","cn":"她明白无误地叫他离她远远的。"}}]},"examples":[{"en":"I told him what I thought of him in no uncertain terms.","cn":"我直言不讳地说出了我对他的看法。"},{"en":"They're both uncertain about what to do.","cn":"他们两人都拿不定主意该怎么办。"}]},"unspoiled":{"oxford":{"phon":"ˌʌnˈspɔɪld","pos":"adjective","senses":[{"en":"beautiful because it has not been changed or built on","cn":"有自然美的；未遭破坏的","ex":{"en":"unspoiled countryside","cn":"未遭到破坏的乡村"}},{"en":"not made unpleasant, badly behaved, etc. by being praised too much","cn":"未被宠坏的；未被捧杀的","ex":{"en":"She was an affectionate child and remarkably unspoiled.","cn":"她是个充满爱心的女孩儿，丝毫没有被宠坏。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（地方）未经开发的，有自然美的","en":"If you describe a place as unspoiled, you think it is beautiful because it has not been changed or built on for a long time.","ex":{"en":"The port is quiet and unspoiled.","cn":"这个港口宁静、天然。"}}]},"media":{"uk":"media/uk/unspoiled__gb_1.mp3","us":"media/us/unspoiled__us_1.mp3"},"examples":[{"en":"She remained unspoilt by her success.","cn":"她虽然事业有成﹐却依然保持本色。"},{"en":"unspoiled countryside","cn":"未遭到破坏的乡村"}]},"ultimate":{"media":{"uk":"media/uk/ultimate__gb_1.mp3","us":"media/us/ultimate__us_1.mp3"},"oxford":{"phon":"ˈʌltɪmət","pos":"adjective","senses":[{"en":"happening at the end of a long process","cn":"最后的；最终的；终极的","ex":{"en":"our ultimate goal/aim/objective/target","cn":"我们最终的目的／目标"}},{"en":"most extreme; best, worst, greatest, most important, etc.","cn":"极端的；最好（或坏、伟大、重要等）的","ex":{"en":"This race will be the ultimate test of your skill.","cn":"这次竞赛将是对你的技能的最大考验。"}},{"en":"from which something originally comes","cn":"根本的；基本的；基础性的","ex":{"en":"the ultimate truths of philosophy and science","cn":"哲学与科学的终极原理"}},{"en":"the best, most advanced, greatest, etc. of its kind","cn":"最好（或先进、伟大等）的事物；极品；精华","ex":{"en":"the ultimate in modern design","cn":"现代设计的最高代表"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"最后的；最终的","en":"You use ultimate to describe the final result or aim of a long series of events.","ex":{"en":"He said it is still not possible to predict the ultimate outcome","cn":"他说现在还无法预料最终的结局。"}},{"pos":"ADJ 形容词","cn":"最根本的；最基础的；最原始的","en":"You use ultimate to describe the original source or cause of something.","ex":{"en":"Plants are the ultimate source of all foodstuffs","cn":"植物是所有食物的最根本来源。"}},{"pos":"ADJ 形容词","cn":"最重要的；最强大的；至高的","en":"You use ultimate to describe the most important or powerful thing of a particular kind.","ex":{"en":"...the ultimate power of the central government","cn":"中央政府的至高权力"}},{"pos":"ADJ 形容词","cn":"极端的；极度的；令人极其不快的","en":"You use ultimate to describe the most extreme and unpleasant example of a particular thing.","ex":{"en":"Being removed from his post during operations is the ultimate humiliation for a ship's captain.","cn":"在执行任务的过程中被免职，这对一位船长来说是莫大的耻辱。"}},{"pos":"ADJ 形容词","cn":"最好的；绝好的；极好的","en":"You use ultimate to describe the best possible example of a particular thing.","ex":{"en":"He is the ultimate English gentleman","cn":"他是最最典型的英国绅士。"}},{"pos":"PHRASE 短语","cn":"极致；极限；最高典范","en":"The ultimate in something is the best or most advanced example of it.","ex":{"en":"Ballet is the ultimate in human movement","cn":"芭蕾舞在人类的动作中可谓优雅至极。"}}]},"examples":[{"en":"We will accept ultimate responsibility for whatever happens.","cn":"无论出什么事情，我们愿承担全部责任。"},{"en":"This race will be the ultimate test of your skill.","cn":"这次竞赛将是对你的技能的最大考验。"}]},"unemployment":{"media":{"uk":"media/uk/unemployment__gb_1.mp3","us":"media/us/unemployment__us_1.mp3"},"oxford":{"phon":"ˌʌnɪmˈplɔɪmənt","pos":"noun","senses":[{"en":"the fact of a number of people not having a job; the number of people without a job","cn":"失业；失业人数","ex":{"en":"an area of high/low unemployment","cn":"失业率高／低的地区"}},{"en":"the state of not having a job","cn":"无业；没有工作","ex":{"en":"Thousands of young people are facing long-term unemployment.","cn":"成千上万的青年正面临长期待业状况。"}},{"en":"money paid by the government to somebody who is unemployed","cn":"失业补贴（或津贴）；失业救济金","lab":"both US English","ex":{"en":"Since losing his job, Mike has been collecting unemployment.","cn":"自从丢了工作之后，迈克一直在领取失业救济金。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"失业","en":"Unemployment is the fact that people who want jobs cannot get them.","ex":{"en":"...an area that had the highest unemployment rate in western Europe","cn":"西欧失业率最高的地区"}}]},"examples":[{"en":"Since losing his job, Mike has been collecting unemployment.","cn":"自从丢了工作之后，马克一直在领取失业救济金。"},{"en":"Thousands of young people are facing long-term unemployment.","cn":"成千上万的青年正面临长期待业状况。"}]},"uncontaminated":{"media":{"uk":"media/uk/uncontaminated__gb_1.mp3","us":"media/us/uncontaminated__us_1.mp3"},"oxford":{"phon":"ˌʌnkənˈtæmɪneɪtɪd","pos":"adjective","senses":[{"en":"not harmed by something (for example, dangerous or dirty substances)","cn":"未被损害的；未受污染的","ex":{"en":"uncontaminated water","cn":"未受污染的水"}}]},"examples":[{"en":"uncontaminated water","cn":"未被污染的水"}]},"unexpectedly":{"oxford":{"phon":"ˌʌnɪkˈspektɪdli","pos":"adverb","senses":[{"en":"in a way that surprises you because you were not expecting it","cn":"出乎意料的；始料不及的","ex":{"en":"They had arrived unexpectedly.","cn":"他们不期而至。"}}]},"media":{"uk":"media/uk/unexpectedly__gb_1.mp3","us":"media/us/unexpectedly__us_1.mp3"},"examples":[{"en":"Not unexpectedly, most local business depends on tourism.","cn":"并非出人意料的是，当地的大部分生意依靠旅游业。"},{"en":"They had arrived unexpectedly.","cn":"他们意外地到达了。"}]},"underneath":{"media":{"uk":"media/uk/underneath__gb_1.mp3","us":"media/us/underneath__us_1.mp3"},"oxford":{"phon":"ˌʌndəˈniːθ","pos":"preposition, adverb","senses":[{"en":"under or below something else, especially when it is hidden or covered by the thing on top","cn":"在…底下；隐藏（或掩盖）在下面","ex":{"en":"The coin rolled underneath the piano.","cn":"硬币滚到了钢琴底下。"}},{"en":"used to talk about somebody’s real feelings or character, as opposed to the way they seem to be","cn":"（指真实的感情或性格）在…表象之下","ex":{"en":"Underneath her cool exterior she was really very frightened.","cn":"她外表冷静，其实内心十分害怕。"}},{"en":"the lower surface or part of something","cn":"（物体的）下表面，底面，底部，下部","ex":{"en":"She pulled the drawer out and examined the underneath carefully.","cn":"她拉开抽屉仔细查看底部。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"PREP 介词","cn":"在…下面；在…底下","en":"If one thing is underneath another, it is directly under it, and may be covered or hidden by it.","ex":{"en":"The device exploded underneath a van.","cn":"该装置在一辆货车底下发生了爆炸。"}},{"pos":"ADV 副词","cn":"在下表面；在底面","en":"The part of something which is underneath is the part which normally touches the ground or faces towards the ground.","ex":{"en":"Check the actual construction of the chair by looking underneath","cn":"看看椅子的下面，检查一下它的实际构造。"}},{"pos":"ADV 副词","cn":"在内心深处；心底里","en":"You use underneath when talking about feelings and emotions that people do not show in their behaviour.","ex":{"en":"He was as violent as Nick underneath","cn":"在内心深处，他和尼克一样暴躁不安。"}}]},"examples":[{"en":"This jacket's too big, even with a sweater underneath.","cn":"即使里面穿一件毛衣，这件外套也太大了。"},{"en":"Underneath her cool exterior she was really very frightened.","cn":"她外表冷静，其实内心十分害怕。"}]},"unpredictability":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"to be unable to say or predict what will happen","cn":""},{"en":"something that is unpredictable is impossible to predict because the situation changes a lot and has no regular pattern","cn":""}]},"examples":[{"en":"the unpredictable nature of language","cn":"","src":"ld"}],"media":{"uk":"media/uk/unpredictability__gb_1.mp3","us":"media/us/unpredictability__us_1.mp3"},"oxford":{"phon":"ˌʌnprɪˌdɪktəˈbɪləti","pos":"noun","senses":[{"en":"the quality something has when it is impossible to know in advance that it will happen or what it will be like","cn":"不可预测性：当无法提前知道它将要发生或将要变成什么样时，它具有的质量","ex":{"en":"the unpredictability of the English weather","cn":"英格兰天气的变化莫测"}},{"en":"the quality somebody has when you cannot predict how they will behave in a particular situation","cn":"（人）善变的，难以捉摸的","ex":{"en":"His logical good sense complemented her unpredictability.","cn":"他的逻辑判断力与她的不可预测性相得益彰。"}}]}},"underprivileged":{"oxford":{"phon":"ˌʌndəˈprɪvəlɪdʒd","pos":"adjective","senses":[{"en":"having less money and fewer opportunities than most people in society","cn":"在社会中处于弱势的；贫苦的；机遇少的；底层的","g":"[usually before noun]","ex":{"en":"underprivileged sections of the community","cn":"社区的弱势阶层"}},{"en":"people who are underprivileged","cn":"弱势群体；贫困阶层","g":"[plural]"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"贫困的；弱势的","en":"Underprivileged people have less money and fewer possessions and opportunities than other people in their society.","ex":{"en":"...helping underprivileged children to learn to read.","cn":"帮助贫困儿童读书识字"}}]},"media":{"uk":"media/uk/underprivileged__gb_1.mp3","us":"media/us/underprivileged__us_1.mp3"},"examples":[{"en":"educationally/socially underprivileged groups","cn":"教育上/社会上处于弱势地位的群体"},{"en":"underprivileged sections of the community","cn":"社区的弱势阶层"}]},"unreasonable":{"oxford":{"phon":"ʌnˈriːznəbl","pos":"adjective","senses":[{"en":"not fair; expecting too much","cn":"不合理的；不公正的；期望过高的","ex":{"en":"The job was beginning to make unreasonable demands on his free time.","cn":"他的闲暇时间开始被工作过分地侵占了。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不公平的；不合理的","en":"If you say that someone is being unreasonable, you mean that they are behaving in a way that is not fair or sensible.","ex":{"en":"The strikers were being unreasonable in their demands, having rejected the deal two weeks ago","cn":"罢工者的要求很不合理，他们在两周前已拒绝接受这份协议。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不合理的；不讲道理的","en":"An unreasonable decision, action, price, or amount seems unfair and difficult to justify.","ex":{"en":"...unreasonable increases in the price of petrol","cn":"汽油价格的疯涨"}}]},"media":{"uk":"media/uk/unreasonable__gb_1.mp3","us":"media/us/unreasonable__us_1.mp3"},"examples":[{"en":"The job was beginning to make unreasonable demands on his free time.","cn":"他的闲暇时间开始被工作过分地侵占了。"},{"en":"It would be unreasonable to expect somebody to come at such short notice.","cn":"要求人家随传随到，太不近人情了吧。"}]},"unobserved":{"media":{"uk":"media/uk/unobserved__gb_1.mp3","us":"media/us/unobserved__us_1.mp3"},"oxford":{"phon":"ˌʌnəbˈzɜːvd","pos":"adjective","senses":[{"en":"without being seen","cn":"不被看见（或发现）的","ex":{"en":"It's not easy for somebody to get into the building unobserved.","cn":"进入这栋大楼而不被发现很不容易。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"不被注意的；未被看到的","en":"If you do something unobserved, you do it without being seen by other people.","ex":{"en":"Looking round to make sure he was unobserved, he slipped through the door","cn":"他看了看周围，确定没有被人注意，就从那扇门溜走了。"}}]},"examples":[{"en":"It's not easy for somebody to get into the building unobserved.","cn":"进入这栋大楼而不被发现很不容易。"},{"en":"Frank slipped out of the meeting unobserved.","cn":"弗兰克悄悄地溜出了会场。"}]},"unwashed":{"media":{"uk":"media/uk/unwashed__gb_1.mp3","us":"media/us/unwashed__us_2.mp3"},"oxford":{"phon":"ˌʌnˈwɒʃt","pos":"adjective","senses":[{"en":"not washed; dirty","cn":"未洗涤的；肮脏的","ex":{"en":"a pile of unwashed dishes","cn":"一堆未洗的碟子"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未洗过的；需要清洗的","en":"Unwashed people or objects are dirty and need to be washed.","ex":{"en":"They looked pale and unhealthy, with unwashed hair and sunken cheeks","cn":"他们脸色苍白，精神不振，头发脏乱，两颊深陷。"}},{"pos":"PHRASE 短语","cn":"贩夫走卒；草根阶层；穷人","en":"The unwashed or the great unwashed is a way of referring to poor or ordinary people.","ex":{"en":"A scowling man briskly led the Queen's husband away from the great unwashed.","cn":"一名面色阴沉的男子迅速地把王夫带离了那些草根下民。"}}]},"examples":[{"en":"Their clothes were dirty and their hair unwashed.","cn":"他们衣服肮脏，头发未洗。"},{"en":"a pile of unwashed dishes","cn":"一堆未洗的碟子"}]},"uninhabited":{"media":{"uk":"media/uk/uninhabited__gb_1.mp3","us":"media/us/uninhabited__us_1.mp3"},"oxford":{"phon":"ˌʌnɪnˈhæbɪtɪd","pos":"adjective","senses":[{"en":"with no people living there; not inhabited","cn":"无人居住的；无人烟的；荒凉的","ex":{"en":"an uninhabited island","cn":"荒岛"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"无人居住的；杳无人迹的","en":"An uninhabited place is one where nobody lives.","ex":{"en":"...an uninhabited island in the North Pacific","cn":"北太平洋上一个无人居住的岛"}}]},"examples":[{"en":"an uninhabited island","cn":"荒岛"}]},"usual":{"media":{"uk":"media/uk/usual__gb_1.mp3","us":"media/us/usual__us_1.mp3"},"oxford":{"phon":"ˈjuːʒuəl","pos":"adjective","senses":[{"en":"that happens or is done most of the time or in most cases","cn":"通常的；寻常的；惯常的","ex":{"en":"This is the usual way of doing it.","cn":"通常都是这么做的。"}},{"en":"what usually happens; what you usually have, especially the drink that you usually have","cn":"惯常的事物；（尤指）常喝的饮料","g":"[singular]","lab":"informal"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"通常的；寻常的；惯常的","en":"Usual is used to describe what happens or what is done most often in a particular situation.","ex":{"en":"It is a neighborhood beset by all the usual inner-city problems","cn":"这是个为各种内城常见问题所困扰的社区。"}},{"pos":"PHRASE 短语","cn":"像平常一样；照例","en":"You use as usual to indicate that you are describing something that normally happens or that is normally the case.","ex":{"en":"As usual there will be the local and regional elections on June the twelfth","cn":"照例，6月12日将会进行地方及区域选举。"}},{"pos":"PHRASE 短语","cn":"（尤指其他事情有变化时）照常","en":"If something happens as usual, it happens in the way that it normally does, especially when other things have changed.","ex":{"en":"When somebody died everything went on as usual, as if it had never happened","cn":"就算有人死了一切也都照常进行，好像什么事都没发生过。"}},{"pos":"","cn":"","en":"business as usual→see: ;"}]},"examples":[{"en":"As usual at that hour, the place was deserted.","cn":"跟平常那个时刻一样，那地方空荡荡的。"},{"en":"It is usual to start a speech by thanking everybody for coming.","cn":"讲话前先感谢大家光临，这是惯例。"}]},"unwittingly":{"media":{"uk":"media/uk/unwittingly__gb_1.mp3","us":"media/us/unwittingly__us_1.mp3"},"oxford":{"phon":"ʌnˈwɪtɪŋli","pos":"adverb","senses":[{"en":"without being aware of what you are doing or the situation that you are involved in","cn":"糊里糊涂地；茫然；无意地","ex":{"en":"She had broken the law unwittingly, but still she had broken it.","cn":"她并非故意犯法，但毕竟是犯了法。"}}]},"examples":[{"en":"She had broken the law unwittingly, but still she had broken it.","cn":"她并非故意犯法，但毕竟是犯了法。"},{"en":"Friedmann had unwittingly broken the law.","cn":"弗里德曼无意中触犯了法律。"}]},"understatement":{"media":{"uk":"media/uk/understatement__gb_1.mp3","us":"media/us/understatement__us_1.mp3"},"oxford":{"phon":"ˈʌndəsteɪtmənt","pos":"noun","senses":[{"en":"a statement that makes something seem less important, impressive, serious, etc. than it really is","cn":"保守的说法；不充分的叙述","g":"[countable]","ex":{"en":"To say we were pleased is an understatement (= we were extremely pleased).","cn":"说我们高兴，那是轻描淡写。"}},{"en":"the practice of making things seem less impressive, important, serious, etc. than they really are","cn":"淡化；低调说法","g":"[uncountable]","ex":{"en":"typical English understatement","cn":"典型的英国式低调说法"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"不充分如实的陈述；轻描淡写的说明","en":"If you say that a statement is an understatement, you mean that it does not fully express the extent to which something is true.","ex":{"en":"To say I'm disappointed is an understatement","cn":"说我失望那是说得太轻了。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"轻描淡写；重事轻说；淡化","en":"Understatement is the practice of suggesting that things have much less of a particular quality than they really have.","ex":{"en":"He informed us with massive understatement that he was feeling disappointed.","cn":"他极力轻描淡写地跟我们说他感到失望。"}}]},"examples":[{"en":"‘These figures are a bit disappointing.’ ‘That's got to be the understatement of the year. ’ “","cn":"这些数字有点令人失望。” “那一定是本年度最保守的说法了。”"},{"en":"He always goes for subtlety and understatement in his movies.","cn":"他总是在自己的电影中运用细腻刻画和淡化手法。"}]},"unfortunately":{"media":{"uk":"media/uk/unfortunately__gb_1.mp3","us":"media/us/unfortunately__us_1.mp3"},"oxford":{"phon":"ʌnˈfɔːtʃənətli","pos":"adverb","senses":[{"en":"used to say that a particular situation or fact makes you sad or disappointed, or gets you into a difficult position","cn":"不幸地；遗憾地；可惜地；可悲地","ex":{"en":"Unfortunately, I won't be able to attend the meeting.","cn":"真可惜我不能参加这次会议。"}}]},"collins":{"senses":[{"pos":"ADV-GRADED 副词","cn":"不幸的是；遗憾的是；令人失望的是","en":"You can use unfortunately to introduce or refer to a statement when you consider that it is sad or disappointing, or when you want to express regret.","ex":{"en":"Unfortunately, my time is limited","cn":"可惜的是，我的时间有限。"}}]},"examples":[{"en":"Unfortunately for him, the police had been informed and were waiting outside.","cn":"算他倒霉，警察已接到报告，就在外边等着。"},{"en":"It won't be finished for a few weeks. Unfortunately!","cn":"这工作得过几周才能完成。很遗憾！"}]},"ultrasound":{"media":{"uk":"media/uk/ultrasound__gb_1.mp3","us":"media/us/ultrasound__us_1.mp3"},"oxford":{"phon":"ˈʌltrəsaʊnd","pos":"noun","senses":[{"en":"sound that is higher than humans can hear","cn":"超声","g":"[uncountable]"},{"en":"a medical process that produces an image of what is inside your body","cn":"超声波扫描检查","g":"[uncountable, countable]","ex":{"en":"Ultrasound showed she was expecting twins.","cn":"超声波扫描显示她怀了双胞胎。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"超声波","en":"Ultrasound is sound waves which travel at such a high frequency that they cannot be heard by humans. Ultrasound is used in medicine to get pictures of the inside of people's bodies.","ex":{"en":"I had an ultrasound scan to see how the pregnancy was progressing.","cn":"我进行了超声波检查，看看妊娠情况如何。"}}]},"examples":[{"en":"Ultrasound showed she was expecting twins.","cn":"超声波扫描显示她怀了双胞胎。"},{"en":"investigation of the liver by ultrasound","cn":"对肝脏作的超声波检查"}]},"ups":{"oxford":{"phon":"ʌp","pos":"adverb","senses":[{"en":"towards or in a higher position","cn":"向（或在）较高位置；向上；在上面"},{"en":"to or at a higher level","cn":"向（或在）较高水平；加大；增高"}]},"media":{"uk":"media/uk/up__gb_1.mp3","us":"media/us/up__us_1.mp3"},"examples":[{"en":"I think I'll ship it UPS.","cn":""},{"en":"Will UPS take a box that big?","cn":""}]},"understood":{"collins":{"senses":[{"pos":"","cn":"","en":"Understood is the past tense and past participle of understand."}]},"media":{"uk":"media/uk/understood__gb_1.mp3","us":"media/us/understood__us_1.mp3"}},"understandings":{"oxford":{"phon":"ˌʌndəˈstændɪŋ","pos":"noun","senses":[{"en":"the knowledge that sb has about a particular subject or situation","cn":"理解；领悟；了解"},{"en":"an informal agreement （","cn":"非正式的）协议"}]},"media":{"uk":"media/uk/understanding__gb_1.mp3","us":"media/us/understanding__us_1.mp3"}},"ubiquitous":{"media":{"uk":"media/uk/ubiquitous__gb_1.mp3","us":"media/us/ubiquitous__us_1.mp3"},"oxford":{"phon":"juːˈbɪkwɪtəs","pos":"adjective","senses":[{"en":"seeming to be everywhere or in several places at the same time; very common","cn":"似乎无所不在的；十分普遍的","ex":{"en":"the ubiquitous bicycles of university towns","cn":"大学城里处处可见的自行车"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无所不在的；随处可见的","en":"If you describe something or someone as ubiquitous, you mean that they seem to be everywhere.","ex":{"en":"Sugar is ubiquitous in the diet","cn":"糖在这种饮食里随处可见。"}}]},"examples":[{"en":"the ubiquitous movie star, Tom Hanks","cn":"尽人皆知的影星汤姆 · 汉克斯"},{"en":"the ubiquitous bicycles of university towns","cn":"大学城里处处可见的自行车"}]},"unspoken":{"media":{"uk":"media/uk/unspoken__gb_1.mp3","us":"media/us/unspoken__us_1.mp3"},"oxford":{"phon":"ʌnˈspəʊkən","pos":"adjective","senses":[{"en":"not stated; not said in words but understood or agreed between people","cn":"未说出的；未用语言表达的；心照不宣的","ex":{"en":"an unspoken assumption","cn":"隐含的假定"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（想法、愿望、感情）没有言明的，没有说出口的","en":"If your thoughts, wishes, or feelings are unspoken, you do not speak about them.","ex":{"en":"His face was expressionless, but Alex felt the unspoken criticism","cn":"他面无表情，但亚历克斯能感觉到他未明言的批评之意。"}},{"pos":"ADJ 形容词","cn":"（协议等）不成文的，默契的，默认的","en":"When there is an unspoken agreement or understanding between people, their behaviour shows that they agree about something or understand it, even though they have never spoken about it.","ex":{"en":"There had been an unspoken agreement between them that he would not call for her at Seymour House","cn":"他们之间曾经有过默契，那便是他不会到西摩屋去找她。"}}]},"examples":[{"en":"Something unspoken hung in the air between them.","cn":"他们之间有些心照不宣的事还没有解决。"},{"en":"an unspoken assumption","cn":"隐含的假定"}]},"unable":{"media":{"uk":"media/uk/unable__gb_1.mp3","us":"media/us/unable__us_1.mp3"},"oxford":{"phon":"ʌnˈeɪbl","pos":"adjective","senses":[{"en":"not having the skill, strength, time, knowledge, etc. to do something","cn":"未能；无法","ex":{"en":"a former soldier who has been unable to find work since the war ended","cn":"战后一直未能找到工作的退伍兵"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"不能…的；无法…的","en":"If you are unable to do something, it is impossible for you to do it, for example because you do not have the necessary skill or knowledge, or because you do not have enough time or money.","ex":{"en":"The military may feel unable to hand over power to a civilian President next year","cn":"军方可能会觉得明年难以将政权移交给一位民选总统。"}}]},"examples":[{"en":"I tried to contact him but was unable to.","cn":"我试着跟他联系，却没联系上。"},{"en":"He lay there, unable to move.","cn":"他躺在那里动弹不得。"}]},"unwritten":{"media":{"uk":"media/uk/unwritten__gb_1.mp3","us":"media/us/unwritten__us_1.mp3"},"oxford":{"phon":"ˌʌnˈrɪtn","pos":"adjective","senses":[{"en":"a law, etc. that everyone knows about and accepts even though it has not been made official","cn":"非书面的，不成文的，惯常的（法律、规定、协议等）","ex":{"en":"an unwritten understanding that nobody leaves before five o’clock","cn":"五点钟之前谁都不离开的默契"}},{"en":"not yet written","cn":"未写的；未写完的","ex":{"en":"The photographs were to be included in his as yet unwritten autobiography.","cn":"这些照片准备要收入他那尚未写的自传之中。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未付印的；未写下的；未成文","en":"Something such as a book that is unwritten has not been printed or written down.","ex":{"en":"Universal have agreed to pay £2.5 million for Grisham's next, as yet unwritten, novel.","cn":"环球公司已同意为格里森姆下一部还未动笔的小说支付250万英镑。"}},{"pos":"ADJ 形容词","cn":"（规则、法律或协议）不成文的","en":"An unwritten rule, law, or agreement is one that is understood and accepted by everyone, although it may not have been formally or officially established.","ex":{"en":"They obey the one unwritten rule that binds them all—no talking.","cn":"他们都遵守着那条约束他们所有人的默认规则——要守口如瓶。"}}]},"examples":[{"en":"The photographs were to be included in his as yet unwritten autobiography.","cn":"这些照片准备要收入他那尚未写的自传之中。"},{"en":"an unwritten understanding that nobody leaves before five o'clock","cn":"五点钟之前谁都不离开的默契"}]},"unfashionable":{"oxford":{"phon":"ʌnˈfæʃnəbl","pos":"adjective","senses":[{"en":"not popular or fashionable at a particular time","cn":"不时兴的；不时髦的；过时的","ex":{"en":"an unfashionable part of London","cn":"伦敦一个老旧的角落"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不流行的；过时的","en":"If something is unfashionable, it is not approved of or done by most people.","ex":{"en":"Wearing fur has become deeply unfashionable","cn":"穿毛皮衣物已经相当过时了。"}}]},"media":{"uk":"media/uk/unfashionable__gb_1.mp3","us":"media/us/unfashionable__us_1.mp3"},"examples":[{"en":"a man with unfashionably long hair","cn":"留着过时长发的男人"},{"en":"an unfashionable part of London","cn":"伦敦一个偏僻的角落"}]},"upon":{"media":{"uk":"media/uk/upon__gb_1.mp3","us":"media/us/upon__us_1.mp3"},"oxford":{"phon":"əˈpɒn","pos":"preposition","senses":[{"en":"used to emphasize that there is a large number or amount of something","cn":"（强调数目或数量大）","ex":{"en":"mile upon mile of dusty road","cn":"绵延数英里尘土飞扬的道路"}}]},"collins":{"senses":[{"pos":"PREP 介词","cn":"在…上","en":"If one thing is upon another, it is on it.","ex":{"en":"He set the tray upon the table","cn":"他把盘子放在桌子上。"}},{"pos":"PREP 介词","cn":"一…即…；一…就…","en":"You use upon when mentioning an event that is followed immediately by another event.","ex":{"en":"The door on the left, upon entering the church, leads to the Crypt of St Issac","cn":"一进教堂左边的那扇门通往圣以撒墓。"}},{"pos":"PREP 介词","cn":"（用于名词叠用，表示数量多）","en":"You use upon between two occurrences of the same noun in order to say that there are large numbers of the thing mentioned.","ex":{"en":"Row upon row of women surged forwards","cn":"一排排的女人涌上前去。"}},{"pos":"PREP 介词","cn":"将要发生；马上来临","en":"If an event is upon you, it is just about to happen.","ex":{"en":"The long-threatened storm was upon us","cn":"酝酿多时的暴风雨就要向我们袭来。"}}]},"examples":[{"en":"The decision was based upon two considerations.","cn":"这一决定是基于两种考虑的。"},{"en":"mile upon mile of dusty road","cn":"绵延数英里尘土飞扬的道路"}]},"underused":{"media":{"uk":"media/uk/underused__gb_1.mp3","us":"media/us/underused__us_1.mp3"},"oxford":{"phon":"ˌʌndəˈjuːzd","pos":"adjective","senses":[{"en":"not used as much as it could or should be","cn":"未充分利用的；浪费的","ex":{"en":"The airport is currently grossly underused.","cn":"目前这个机场的使用率极低。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"未得到充分利用的","en":"Something useful that is underused is not used as much for people's benefit as it could be.","ex":{"en":"At present many schools' sports grounds are grossly underused.","cn":"目前许多学校的体育场都根本没有得到充分的利用。"}}]}},"up":{"media":{"uk":"media/uk/up__gb_1.mp3","us":"media/us/up__us_1.mp3"},"oxford":{"phon":"ʌp","pos":"adverb","senses":[{"en":"towards or in a higher position","cn":"向（或在）较高位置；向上；在上面","ex":{"en":"He jumped up from his chair.","cn":"他从椅子上跳起来。"}},{"en":"to or at a higher level","cn":"向（或在）较高水平；加大；增高","ex":{"en":"She turned the volume up.","cn":"她把音量调大了。"}},{"en":"to the place where somebody/something is","cn":"朝（某人或某物）的方向；向…的地方","ex":{"en":"A car drove up and he got in.","cn":"一辆汽车开过来，他就上了车。"}},{"en":"out of bed","cn":"未上床；起床","lab":"British English","ex":{"en":"I stayed up late (= did not go to bed until late) last night.","cn":"我昨晚熬夜了。"}},{"en":"to or at an important place, especially a large city","cn":"到，朝，在（重要地方，尤指大城市）","lab":"British English, formal，，","ex":{"en":"We're going up to New York for the day.","cn":"我们要上纽约一天。"}},{"en":"to a place in the north of a country; further north than somewhere else","cn":"向（北部）；向（北方）","ex":{"en":"They've moved up north.","cn":"他们已搬到北部去了。"}},{"en":"completely","cn":"完全；十足；彻底","ex":{"en":"We ate all the food up.","cn":"我们把食物吃光了。"}},{"en":"so as to be finished or closed","cn":"（以便）完结，关闭","ex":{"en":"I have some paperwork to finish up.","cn":"我有些文案工作要做完。"}},{"en":"into pieces or parts","cn":"成碎片；分开","ex":{"en":"She tore the paper up.","cn":"她把纸撕得粉碎。"}},{"en":"so as to be formed or brought together","cn":"（以便）形成，聚拢","ex":{"en":"The government agreed to set up a committee of inquiry.","cn":"政府同意成立一个调查委员会。"}},{"en":"finished; over","cn":"已结束；已过去","ex":{"en":"Time's up. Stop writing and hand in your papers.","cn":"时间到了。不要再写了，把试卷交上来。"}},{"en":"used to say that something is happening, especially something unusual or unpleasant","cn":"（尤指异常或不愉快的事情）发生，出现","lab":"informal","ex":{"en":"I could tell something was up by the looks on their faces.","cn":"从他们的脸色我就知道出事了。"}},{"en":"about to happen, be discussed, etc.","cn":"即将发生；即将进行","ex":{"en":"Next up in our top ten is a new release by Ariana Grande.","cn":"在我们的排名前十中，接下来是阿里安娜·格兰德的新歌。"}},{"en":"to or in a higher position somewhere","cn":"向，在（较高位置）","ex":{"en":"She climbed up the flight of steps.","cn":"她爬上了那段楼梯。"},"pos":"preposition"},{"en":"along or further along a road or street","cn":"沿着；顺着","ex":{"en":"We live just up the road, past the post office.","cn":"我们就住在路的前面，刚过邮局的地方。"},"pos":"preposition"},{"en":"towards the place where a river starts","cn":"向…上游；溯流而上","ex":{"en":"a cruise up the Rhine","cn":"乘船沿莱茵河溯流而上"},"pos":"preposition"},{"en":"directed or moving upwards","cn":"向上的；往上移动的","g":"[only before noun]","ex":{"en":"an up stroke","cn":"上提笔画"},"pos":"adjective"},{"en":"cheerful; happy or excited","cn":"高兴；快乐；激动","g":"[not before noun]","lab":"informal","ex":{"en":"The mood here is resolutely up.","cn":"这里的气氛十分热闹。"},"pos":"adjective"},{"en":"working","cn":"在运行","g":"[not before noun]","ex":{"en":"Our system should be up by this afternoon.","cn":"到今天下午，我们的电脑系统应该运行起来了。"},"pos":"adjective"},{"en":"to suddenly move or do something unexpected","cn":"突然移动；突然做（意想不到的事）","g":"[intransitive]","lab":"informal or humorous","ex":{"en":"He upped and left without telling anyone.","cn":"他突然起身不辞而别。"},"pos":"verb"},{"en":"to increase the price or amount of something","cn":"提高…的价格（或数量）","g":"[transitive]","ex":{"en":"The buyers upped their offer by £1 000.","cn":"买方把出价增加了 1 000 英镑。"},"pos":"verb"},{"en":"higher; upwards; towards the top of something","cn":"更高；向上；朝顶部","ex":{"en":"upland","cn":"高地"},"pos":"prefix"}]},"collins":{"senses":[{"pos":"PREP 介词","cn":"向上；朝上；往上","en":"If a person or thing goes up something such as a slope, ladder, or chimney, they move away from the ground or to a higher position.","ex":{"en":"They were climbing up a narrow mountain road","cn":"他们正沿一条狭窄的山路向上爬。"}},{"pos":"PREP 介词","cn":"近顶端；靠顶端","en":"If a person or thing is up something such as a ladder or a mountain, they are near the top of it.","ex":{"en":"He was up a ladder sawing off the tops of his apple trees","cn":"他正站在梯子顶上锯他那颗苹果树的树冠。"}},{"pos":"ADV 副词","cn":"（目光）朝上，向上","en":"You use up to indicate that you are looking or facing in a direction that is away from the ground or towards a higher level.","ex":{"en":"Paul answered, without looking up","cn":"保罗头也没抬地答了话。"}},{"pos":"ADV 副词","cn":"（站）起","en":"If someone stands up, they move so that they are standing.","ex":{"en":"He stood up and went to the window","cn":"他起身走向窗户。"}},{"pos":"PREP 介词","cn":"沿着；靠着","en":"If you go or look up something such as a road or river, you go or look along it. If you are up a road or river, you are somewhere along it.","ex":{"en":"A line of tanks came up the road from the city","cn":"一排坦克由市里沿路开来。"}},{"pos":"ADV 副词","cn":"向(或在)某地;(尤指)向(或在)北方，向(或在)地势更高处;","en":"If you are travelling to a particular place, you can say that you are going up to that place, especially if you are going towards the north or to a higher level of land. If you are already in such a place, you can say that you are up there.","ex":{"en":"I'll be up to see you tomorrow","cn":"我明天来看你。"}},{"pos":"ADV 副词","cn":"往；朝","en":"If you go up to something or someone, you move to the place where they are and stop there.","ex":{"en":"The girl ran the rest of the way across the street and up to the car","cn":"那个女孩开始跑起来，一路跑到街对面的汽车旁边。"}},{"pos":"ADV 副词","cn":"上涨；增多","en":"If an amount of something goes up, it increases. If an amount of something is up, it has increased and is at a higher level than it was.","ex":{"en":"They recently put my rent up","cn":"他们最近提高了我的租金。"}},{"pos":"ADJ 形容词","cn":"起床的","en":"If you are up, you are not in bed.","ex":{"en":"Are you sure you should be up?","cn":"你肯定你该起床了吗？"}},{"pos":"ADJ 形容词","cn":"（时间）结束的，用完的，到点的","en":"If a period of time is up, it has come to an end.","ex":{"en":"The moment the half-hour was up, Brooks rose","cn":"半个小时一到，布鲁克斯便起来了。"}},{"pos":"ADJ 形容词","cn":"（道路）正在整修的","en":"You say that a road is up when it is being repaired and cannot be used.","ex":{"en":"Half the road was up in Leadenhall Street, so their taxi was obliged to make a detour.","cn":"半条利德霍尔街都在修路，他们的出租车只好绕道走。"}},{"pos":"ADJ 形容词","cn":"（指棒球运动员）该上场击球的","en":"If a baseball player is up, it is their turn to bat."},{"pos":"ADJ 形容词","cn":"（电脑）已启动的，正常运转的","en":"If a computer or computer system is up, it is working."},{"pos":"EXCLAM 感叹语","cn":"去你的！去你妈的！","en":"People sometimes say 'Up yours!' as an insult when you have said something to annoy them or make them angry.","ex":{"en":"'Up yours,' said the reporter and stormed out into the street.","cn":"“去你的，”记者边说边怒气冲冲地冲到大街上。"}},{"pos":"PHRASE 短语","cn":"可以下床走动","en":"If someone who has been in bed for some time, for example because they have been ill, is up and about, they are now out of bed and living their normal life.","ex":{"en":"How are you Lennox? Good to see you up and about.","cn":"你怎么样，伦诺克斯？很高兴看到你能下床走动了。"}},{"pos":"PHRASE 短语","cn":"不对劲；出问题","en":"If you say that something is up, you mean that something is wrong or that something worrying is happening.","ex":{"en":"What is it then? Something's up, isn't it?","cn":"那是怎么回事呢？出问题了，是吗？"}},{"pos":"PHRASE 短语","cn":"出什么事啦？出什么问题啦？出什么毛病啦？","en":"If you say to someone 'What's up?' or if you tell them what's up, you are asking them or telling them what is wrong or what is worrying them.","ex":{"en":"'What's up?', I said to him. — 'Nothing much,' he answered","cn":"“出什么事啦？”我对他说。——“没什么事，”他答道。"}},{"pos":"PHRASE 短语","cn":"上上下下；来来回回","en":"If you move up and down somewhere, you move there repeatedly in one direction and then in the opposite direction.","ex":{"en":"He continued to jump up and down like a boy at a football match","cn":"他不停地上蹿下跳，活像个足球赛中的男孩。"}},{"pos":"PHRASE 短语","cn":"兴衰；浮沉；起落；悲欢","en":"If you have ups and downs, you experience a mixture of good things and bad things.","ex":{"en":"Every relationship has a lot of ups and downs","cn":"每一段感情都有许多起伏。"}},{"pos":"PHRASE 短语","cn":"欣欣向荣；兴旺；红火","en":"If something is on the up or on the up and up, it is becoming more successful.","ex":{"en":"They're saying that the economy is on the up","cn":"他们称经济正在企稳向好。"}},{"pos":"PHRASE 短语","cn":"安分守己；诚实可靠","en":"If someone is on the up and up, they are honest and sincere.","ex":{"en":"I'm a pretty good judge of men. If you're honest and on the up and up, I'll be able to tell it.","cn":"我看人很准的。你要是诚实正派，我能看出来的。"}},{"pos":"","cn":"","en":"up in arms→see: ;"},{"pos":"PREP-PHRASE 短语介词","cn":"胜任；有能力","en":"If you feel up to doing something, you are well enough to do it.","ex":{"en":"Those patients who were up to it could move to the adjacent pool","cn":"身体状况允许的病人可去隔壁的游泳池。"}},{"pos":"PREP-PHRASE 短语介词","cn":"搞小动作;做手脚","en":"To be up to something means to be secretly doing something that you should not be doing.","ex":{"en":"Why did you need a room unless you were up to something?","cn":"除非你要搞什么小动作，不然你为什么单要一间房？"}},{"pos":"PREP-PHRASE 短语介词","cn":"由…负责","en":"If you say that it is up to someone to do something, you mean that it is their responsibility to do it.","ex":{"en":"It was up to him to make it right, no matter how long it took","cn":"由他负责把事情摆平，不管花多长时间。"}},{"pos":"PREP-PHRASE 短语介词","cn":"直至；直到","en":"Up until or up to are used to indicate the latest time at which something can happen, or the end of the period of time that you are referring to.","ex":{"en":"Please feel free to call me any time up until half past nine at night","cn":"晚上9点半之前任何时间你都可以给我打电话。"}},{"pos":"PREP-PHRASE 短语介词","cn":"高达；多达","en":"You use up to to say how large something can be or what level it has reached.","ex":{"en":"Up to twenty thousand students paid between five and six thousand dollars","cn":"多达20,000名学生支付了5,000到6,000美元。"}},{"pos":"PHRASE 短语","cn":"马马虎虎；不怎么样","en":"If you say that something is not up to much, you mean that it is of poor quality.","ex":{"en":"My own souffles aren't up to much","cn":"我做的蛋奶酥拿不出手。"}},{"pos":"PREP-PHRASE 短语介词","cn":"在被考虑之列","en":"If someone or something is up for election, review, or discussion, they are about to be considered.","ex":{"en":"A third of the Senate and the entire House are up for re-election.","cn":"参议院三分之一的席位和众议院所有席位都面临改选。"}},{"pos":"PREP-PHRASE 短语介词","cn":"遭遇，面临（困难或问题）","en":"If you are up against something, you have a very difficult situation or problem to deal with.","ex":{"en":"The chairwoman is up against the greatest challenge to her position","cn":"女主席正面临职位上的最大挑战。"}},{"pos":"","cn":"","en":"up to your ears→see: ; up to the mark→see: ; up to par→see: ; up to scratch→see: ;"},{"pos":"VERB 动词","cn":"提高；提升；增加","en":"If you up something such as the amount of money you are offering for something, you increase it.","ex":{"en":"He upped his offer for the company","cn":"他提高了给该公司的报价。"}},{"pos":"VERB 动词","cn":"（常指突然）离开，走开","en":"If you up and leave a place, you go away from it, often suddenly or unexpectedly.","ex":{"en":"A man who for months had been dropping amorous hints about a long-term relationship upped and disappeared to America","cn":"几个月来不断暗示爱意、想发展长期恋爱关系的男人却突然远走美国。"}}]},"examples":[{"en":"It may not have been the worst week of my life but it's up there.","cn":"这可能不是我一生中最糟糕的一周，但也差不远了。"},{"en":"OK, it's not my absolute dream, but it's up there.","cn":"是的，那不是我的终极梦想，不过也差不远了。"}]},"url":{"oxford":{"phon":"ˌjuː ɑːr ˈel","pos":"abbreviation","senses":[{"en":"uniform/universal resource locator (typically, the address of a World Wide Web page)","cn":"统一资源定位地址；URL 地址"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"统一资源定位器；网页地址；网址","en":"A URL is an address that shows where a particular page can be found on the World Wide Web. URL is an abbreviation for (缩略=) 'Uniform Resource Locator'.","ex":{"en":"The URL for the Lonely Planet travel centre is http://www.lonelyplanet.com.","cn":"“孤独星球旅游中心”的网址是 http://www.lonelyplanet.com。"}}]},"media":{"uk":"media/uk/url__gb_1.mp3","us":"media/us/url__us_1.mp3"}},"unbelievably":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"making you feel surprised","cn":""},{"en":"very surprising. Astounding sounds a little more formal and a little stronger than astonishing","cn":""}]},"examples":[{"en":"The opportunities are unbelievable.","cn":"","src":"ld"},{"en":"The pain was unbelievable.","cn":"","src":"ld"}],"media":{"uk":"media/uk/unbelievably__gb_1.mp3","us":"media/us/unbelievably__us_1.mp3"},"oxford":{"phon":"ˌʌnbɪˈliːvəbli","pos":"adverb","senses":[{"en":"extremely","cn":"极其；非常","lab":"informal","ex":{"en":"unbelievably bad/good","cn":"坏得／好得令人难以置信"}},{"en":"in a way that is very difficult to believe","cn":"令人难以置信","ex":{"en":"Unbelievably it actually works.","cn":"虽然难以置信，但这确实行得通。"}}]}},"unhappiness":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not happy","cn":""},{"en":"sad, especially for a long time – used about people and periods of time","cn":""}]},"examples":[{"en":"If you’re so unhappy, why don’t you change jobs?","cn":"","src":"ld"},{"en":"Leslie had an unhappy childhood.","cn":"","src":"ld"}],"media":{"uk":"media/uk/unhappiness__gb_1.mp3","us":"media/us/unhappiness__us_1.mp3"},"oxford":{"phon":"ʌnˈhæpinəs","pos":"noun","senses":[{"en":"the feeling of being sad or not being happy","cn":"愁苦，悲惨，不幸福，不快乐","ex":{"en":"He tried to hide his unhappiness from his fans.","cn":"他试图向粉丝隐瞒自己的不满。"}},{"en":"the feeling of not being pleased or satisfied with something","cn":"不悦的；不高兴的；不满的","ex":{"en":"He expressed his office's unhappiness about the way the regulations were made.","cn":"他表达了他的办公室对法规制定方式的不满。"}}]}},"undesirable":{"media":{"uk":"media/uk/undesirable__gb_1.mp3","us":"media/us/undesirable__us_1.mp3"},"oxford":{"phon":"ˌʌndɪˈzaɪərəbl","pos":"adjective","senses":[{"en":"not wanted or approved of; likely to cause trouble or problems","cn":"不想要的；不得人心的；易惹麻烦的","ex":{"en":"undesirable consequences/effects","cn":"不良后果／影响"}},{"en":"a person who is not wanted in a particular place, especially because they are considered dangerous or criminal","cn":"不受欢迎的人；不良分子","ex":{"en":"He's been mixing with drug addicts and other undesirables.","cn":"他一直跟瘾君子和其他不良分子混在一起。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不受欢迎的；不良的；有害的","en":"If you describe something or someone as undesirable, you think they will have harmful effects.","ex":{"en":"Inflation is considered to be undesirable because of its adverse effects on income distribution","cn":"通货膨胀被认为是有害的，因为它会对收入分配产生不利影响。"}},{"pos":"N-COUNT 可数名词","cn":"不受欢迎的人；不良分子；危险人物","en":"Undesirables are people who a particular government considers to be dangerous or a threat to society, and therefore wants to get rid of.","ex":{"en":"The Home Office is usually quick to deport undesirables.","cn":"内政部通常会迅速地将不受欢迎人士驱逐出境。"}}]},"examples":[{"en":"He's been mixing with drug addicts and other undesirables.","cn":"他一直跟瘾君子和其他不良分子混在一起。"},{"en":"It would be highly undesirable to increase class sizes further.","cn":"再增加班级人数，是大家都极不愿意的。"}]},"utensils":{"oxford":{"phon":"juːˈtensl","pos":"noun","senses":[{"en":"a tool that is used in the house （","cn":"家庭）用具，器皿；家什"}]}},"unload":{"oxford":{"phon":"ˌʌnˈləʊd","pos":"verb","senses":[{"en":"to remove things from a vehicle or ship after it has taken them somewhere","cn":"（从车、船上）卸，取下","g":"[transitive, intransitive]","ex":{"en":"Everyone helped to unload the luggage from the car.","cn":"大家都帮着从汽车上卸行李。"}},{"en":"to remove the contents of something after you have finished using it","cn":"（用后）拆掉，退出，取出","g":"[transitive]","ex":{"en":"Each time a gun is laid down it must first be broken and unloaded.","cn":"每次把枪放回去时，都必须先把枪膛打开，退出子弹。"}},{"en":"to pass the responsibility for somebody/something to somebody else; to tell somebody about your problems and worries","cn":"推卸（责任）；甩掉（包袱）；倾诉（烦恼）","g":"[transitive]","lab":"informal","ex":{"en":"It's his problem, not something he should unload onto you.","cn":"那是他的事，他不该把问题甩给你。"}},{"en":"to get rid of or sell something, especially something illegal or of bad quality","cn":"脱手，卖掉（尤指非法物品或次品）","g":"[transitive]","lab":"informal","ex":{"en":"They want to unload their shares at the right price.","cn":"他们想在价格合适的时候卖掉股票。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"卸下（货物）；从…上卸货","en":"If you unload goods from a vehicle, or you unload a vehicle, you remove the goods from the vehicle, usually after they have been transported from one place to another.","ex":{"en":"Unload everything from the boat and clean it thoroughly","cn":"把所有东西从船上卸下来，然后把船彻底清理一下。"}},{"pos":"VERB 动词","cn":"使脱手；卖掉","en":"If someone unloads investments, they get rid of them or sell them.","ex":{"en":"Since March, he has unloaded 1.3 million shares.","cn":"从3月至今，他已经卖出130万股了。"}}]},"media":{"uk":"media/uk/unload__gb_1.mp3","us":"media/us/unload__us_1.mp3"},"examples":[{"en":"It's his problem, not something he should unload onto you.","cn":"那是他的事，他不该把问题甩给你。"},{"en":"They want to unload their shares at the right price.","cn":"他们想在价格合适的时候卖掉股票。"}]},"umbrellas":{"oxford":{"phon":"ʌmˈbrelə","pos":"noun","senses":[{"en":"an object with a round folding frame of long straight pieces of metal covered with material, that you use to protect yourself from the rain or from hot sun","cn":"伞；雨伞；阳伞"},{"en":"a thing that contains or includes many different parts or elements","cn":"综合体；总体；整体"}]}},"undermine":{"media":{"uk":"media/uk/undermine__gb_1.mp3","us":"media/us/undermine__us_1.mp3"},"oxford":{"phon":"ˌʌndəˈmaɪn","pos":"verb","senses":[{"en":"to make something, especially somebody’s confidence or authority, gradually weaker or less effective","cn":"逐渐削弱（信心、权威等）；使逐步减少效力","ex":{"en":"Our confidence in the team has been seriously undermined by their recent defeats.","cn":"该队最近几次失利已严重动摇了我们对他们的信心。"}},{"en":"to make something weaker at the base, for example by digging under it","cn":"从根基处破坏；挖…的墙脚"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"（常指逐渐或反复）削弱，损害（情感、体制等）","en":"If you undermine something such as a feeling or a system, you make it less strong or less secure than it was before, often by a gradual process or by repeated efforts.","ex":{"en":"Offering advice on each and every problem will undermine her feeling of being adult","cn":"对每个问题都给出建议会令她觉得自己不像个成年人。"}},{"pos":"VERB 动词","cn":"（常指间接地）削弱，损害，动摇（某人的地位或权威）","en":"If you undermine someone or undermine their position or authority, you make their authority or position less secure, often by indirect methods.","ex":{"en":"She undermined him and destroyed his confidence in his own talent","cn":"她暗中打击他，让他对自己的才华信心全无。"}},{"pos":"VERB 动词","cn":"破坏，损害（某人的努力或成功的机会）","en":"If you undermine someone's efforts or undermine their chances of achieving something, you behave in a way that makes them less likely to succeed.","ex":{"en":"The continued fighting threatens to undermine efforts to negotiate an agreement","cn":"持续的战斗会破坏希望通过谈判来达成协议的努力。"}}]},"examples":[{"en":"Our confidence in the team has been seriously undermined by their recent defeats.","cn":"他们最近的几次失败已严重动摇了我们对该队的信心。"},{"en":"This crisis has undermined his position.","cn":"这场危机已损害了他的地位。"}]},"unpleasant":{"media":{"uk":"media/uk/unpleasant__gb_1.mp3","us":"media/us/unpleasant__us_1.mp3"},"oxford":{"phon":"ʌnˈpleznt","pos":"adjective","senses":[{"en":"not pleasant or comfortable","cn":"令人不快的；不舒服的","ex":{"en":"an unpleasant experience/surprise/task","cn":"不愉快的经历；恼人的意外情况；苦差事"}},{"en":"not kind, friendly or polite","cn":"不和蔼的；不客气的；不礼貌的","ex":{"en":"He was very unpleasant to me.","cn":"他对我很凶。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"令人不快的；令人不舒服的","en":"If something is unpleasant, it gives you bad feelings, for example by making you feel upset or uncomfortable.","ex":{"en":"The symptoms can be uncomfortable, unpleasant and serious","cn":"那些症状可能令人不适，很不舒服甚至会比较严重。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不友好的；粗鲁的","en":"An unpleasant person is very unfriendly and rude.","ex":{"en":"She thought him an unpleasant man","cn":"她认为他是个粗鲁的人。"}}]},"examples":[{"en":"The minerals in the water made it unpleasant to drink.","cn":"水里的矿物质使得这水挺难喝的。"},{"en":"The drink is very sweet, but not unpleasantly so.","cn":"这饮料非常甜，但并不腻。"}]},"uk":{"media":{"uk":"media/uk/uk__gb_1.mp3","us":"media/us/uk__us_1.mp3"},"collins":{"senses":[{"pos":"N-PROPER 专有名词","cn":"联合王国（指大不列颠及北爱尔兰联合王国）；英国","en":"The UK is Great Britain and Northern Ireland. UK is an abbreviation for (缩略=) 'United Kingdom'."}]},"oxford":{"phon":"ˌjuː ˈkeɪ","pos":"abbreviation","senses":[{"en":"United Kingdom","cn":"英国；联合王国"}]}},"unmanly":{"media":{"uk":"media/uk/unmanly__gb_1.mp3","us":"media/us/unmanly__us_1.mp3"},"oxford":{"phon":"ʌnˈmænli","pos":"adjective","senses":[{"en":"not having the qualities that are admired or expected in a man","cn":"非男子汉的；无男子气概的"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无男子气概的；怯懦的","en":"If you describe a boy's or man's behaviour as unmanly, you are critical of the fact that they are behaving in a way that you think is inappropriate for a man.","ex":{"en":"Your partner can feel the loss as acutely as you, but may feel that it is unmanly to cry.","cn":"你的搭档跟你一样极度地失落，但他也许会觉得男儿有泪不轻弹。"}}]}},"unwise":{"media":{"uk":"media/uk/unwise__gb_1.mp3","us":"media/us/unwise__us_1.mp3"},"oxford":{"phon":"ˌʌnˈwaɪz","pos":"adjective","senses":[{"en":"showing a lack of good judgement","cn":"愚蠢的；不明智的；轻率的","ex":{"en":"It would be unwise to comment on the situation without knowing all the facts.","cn":"不全面了解情况就对局势妄加评论是不明智的。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不明智的；不聪明的；轻率的","en":"If you describe something as unwise, you think that it is foolish and likely to lead to a bad result.","ex":{"en":"It would be unwise to expect too much","cn":"期望过高是不明智的。"}}]},"examples":[{"en":"It would be unwise to comment on the situation without knowing all the facts.","cn":"不全面了解情况就对局势妄加评论是不明智的。"},{"en":"Perhaps unwisely, I agreed to help.","cn":"我同意帮忙，这也许太轻率了。"}]},"university":{"media":{"uk":"media/uk/university__gb_1.mp3","us":"media/us/university__us_1.mp3"},"oxford":{"phon":"ˌjuːnɪˈvɜːsəti","pos":"noun","senses":[{"en":"an institution at the highest level of education where you can study for a degree or do research","cn":"（综合性）大学；高等学府","lab":"British English","ex":{"en":"Is there a university in this town?","cn":"这座城市有没有大学？"}}]},"collins":{"senses":[{"pos":"N-VAR; N-IN-NAMES 可变名词；名称名词","cn":"（综合性）大学","en":"A university is an institution where students study for degrees and where academic research is done.","ex":{"en":"Patrick is now at London University","cn":"帕特里克现在就读于伦敦大学。"}}]},"examples":[{"en":"( BrE ) Both their children are at university.","cn":"他们的两个孩子都在上大学。"},{"en":"Is there a university in this town?","cn":"这座城市有没有大学？"}]},"uninhibited":{"media":{"uk":"media/uk/uninhibited__gb_1.mp3","us":"media/us/uninhibited__us_1.mp3"},"oxford":{"phon":"ˌʌnɪnˈhɪbɪtɪd","pos":"adjective","senses":[{"en":"behaving or expressing yourself freely without worrying about what other people think","cn":"纵情的；无拘无束的；随心所欲的","ex":{"en":"uninhibited dancing","cn":"纵情的舞蹈"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不受抑制的；无拘无束的","en":"If you describe a person or their behaviour as uninhibited, you mean that they express their opinions and feelings openly, and behave as they want to, without worrying what other people think.","ex":{"en":"...a commanding and uninhibited entertainer","cn":"气场强大、狂放不羁的艺人"}}]},"examples":[{"en":"uninhibited dancing","cn":"纵情的舞蹈"},{"en":"uninhibited laughter","cn":"开怀大笑"}]},"usage":{"media":{"uk":"media/uk/usage__gb_1.mp3","us":"media/us/usage__us_1.mp3"},"oxford":{"phon":"ˈjuːsɪdʒ","pos":"noun","senses":[{"en":"the way in which words are used in a language","cn":"（词语的）用法，惯用法","g":"[uncountable, countable]","ex":{"en":"a book on current English usage","cn":"关于当代英语用法的书"}},{"en":"the fact of something being used; how much something is used","cn":"使用；利用；利用率","g":"[uncountable]","ex":{"en":"land usage","cn":"土地的利用"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(词的)使用","en":"Usage is the way in which words are actually used in particular contexts, especially with regard to their meanings.","ex":{"en":"The word 'undertaker' had long been in common usage","cn":"undertaker一词早已广泛使用。"}},{"pos":"N-COUNT 可数名词","cn":"用法；惯用法","en":"A usage is a meaning that a word has or a way in which it can be used.","ex":{"en":"It's very definitely a usage which has come over to Britain from America.","cn":"这个用法肯定是由美国传到英国来的。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"使用；处理；对待","en":"Usage is the degree to which something is used or the way in which it is used.","ex":{"en":"Parts of the motor wore out because of constant usage","cn":"发动机的一些部件因为经常使用而磨损了。"}}]},"examples":[{"en":"Car usage is predicted to increase.","cn":"汽车的使用率预计会增长。"},{"en":"It's not a word in common usage.","cn":"这不是一个常用词。"}]},"uncertainty":{"media":{"uk":"media/uk/uncertainty__gb_1.mp3","us":"media/us/uncertainty__us_1.mp3"},"oxford":{"phon":"ʌnˈsɜːtnti","pos":"noun","senses":[{"en":"the state of being uncertain","cn":"犹豫；迟疑；无把握","g":"[uncountable]","ex":{"en":"There is considerable uncertainty about the company's future.","cn":"这家公司的前景相当渺茫。"}},{"en":"something that you cannot be sure about; a situation that makes you not be or feel certain","cn":"拿不定的事；令人无把握的局面","g":"[countable]","ex":{"en":"life’s uncertainties","cn":"人生的不可知因素"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"不确定；犹疑","en":"Uncertainty is a state of doubt about the future or about what is the right thing to do.","ex":{"en":"...a period of political uncertainty.","cn":"政治动荡的一段时期"}}]},"examples":[{"en":"There is considerable uncertainty about the company's future.","cn":"这家公司的前景相当渺茫。"},{"en":"He had an air of uncertainty about him.","cn":"他显出将信将疑的神情。"}]},"uncle":{"oxford":{"phon":"ˈʌŋkl","pos":"noun","senses":[{"en":"the brother of your mother or father; the husband of your aunt or uncle","cn":"舅父；叔父；伯父；姑父；姨父","ex":{"en":"Uncle Ian","cn":"伊恩叔叔"}},{"en":"used by children, with a first name, to address a man who is a close friend of their parents","cn":"（儿童用语，称呼父母的同辈男性朋友）叔叔，伯伯"},{"en":"used as a polite way of addressing or referring to an older man","cn":"（对老年男性的尊称）大叔，老伯","lab":"Indian English, South-East Asian English，，","ex":{"en":"The uncle who lives opposite my parents is always so warm and friendly.","cn":"住在我父母对面的叔叔总是那么热情友好。"}}]},"collins":{"senses":[{"pos":"N-FAMILY; N-TITLE 家庭成员名词；头衔名词","cn":"伯父；叔叔；舅舅；姑父；姨父","en":"Someone's uncle is the brother of their mother or father, or the husband of their aunt.","ex":{"en":"My uncle was the mayor of Memphis","cn":"我伯父是孟菲斯市市长。"}}]},"media":{"uk":"media/uk/uncle__gb_1.mp3","us":"media/us/uncle__us_1.mp3"},"examples":[{"en":"I've just become an uncle (= because your brother/sister has had a baby).","cn":"我刚当上叔叔（或舅舅）。"},{"en":"I'm going to visit my uncle.","cn":"我要去看我舅舅。"}]},"utensil":{"oxford":{"phon":"juːˈtensl","pos":"noun","senses":[{"en":"a tool that is used in the house","cn":"（家庭）用具，器皿；家什","ex":{"en":"cooking/kitchen utensils","cn":"炊具；厨房用具"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"器皿；用具","en":"Utensils are tools or objects that you use in order to help you to cook or to do other tasks in your home.","ex":{"en":"...utensils such as bowls, steamers and frying pans","cn":"碗、蒸锅、煎锅等用具"}}]},"media":{"uk":"media/uk/utensil__gb_1.mp3","us":"media/us/utensil__us_1.mp3"},"examples":[{"en":"cooking/kitchen utensils","cn":"炊具；厨房用具"},{"en":"kitchen utensils","cn":"厨房用具"}]},"unsuccessful":{"oxford":{"phon":"ˌʌnsəkˈsesfl","pos":"adjective","senses":[{"en":"not successful; not achieving what you wanted to","cn":"不成功的；失败的；落空的","ex":{"en":"His efforts to get a job proved unsuccessful.","cn":"他求职的努力都落空了。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不成功的；落空的；失败的","en":"Something that is unsuccessful does not achieve what it was intended to achieve.","ex":{"en":"His efforts were unsuccessful.","cn":"他的努力失败了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（尤指事业上）失败的，不成功的","en":"Someone who is unsuccessful does not achieve what they intended to achieve, especially in their career.","ex":{"en":"The difference between successful and unsuccessful people is that successful people put into practice the things they learn","cn":"成功者与失败者的区别在于成功者能够学以致用。"}}]},"media":{"uk":"media/uk/unsuccessful__gb_1.mp3","us":"media/us/unsuccessful__us_1.mp3"},"examples":[{"en":"His efforts to get a job proved unsuccessful.","cn":"他求职的努力都落空了。"},{"en":"They were unsuccessful in meeting their objectives for the year.","cn":"他们未能达到年度目标。"}]},"unimaginable":{"media":{"uk":"media/uk/unimaginable__gb_1.mp3","us":"media/us/unimaginable__us_1.mp3"},"oxford":{"phon":"ˌʌnɪˈmædʒɪnəbl","pos":"adjective","senses":[{"en":"impossible to think of or to believe exists; impossible to imagine","cn":"难以置信的；不可想象的","ex":{"en":"unimaginable wealth","cn":"难以想象的财富"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不可想象的；难以理解的；异乎寻常的","en":"If you describe something as unimaginable, you are emphasizing that it is difficult to imagine or understand properly, because it is not part of people's normal experience.","ex":{"en":"The scale of the fighting is almost unimaginable","cn":"战斗的规模几乎无法想象。"}}]},"examples":[{"en":"This level of success would have been unimaginable just last year.","cn":"取得这样的成就，这在仅仅一年前都是不敢想像的。"},{"en":"unimaginable wealth","cn":"难以想像的财富"}]},"unreliable":{"media":{"uk":"media/uk/unreliable__gb_1.mp3","us":"media/us/unreliable__us_1.mp3"},"oxford":{"phon":"ˌʌnrɪˈlaɪəbl","pos":"adjective","senses":[{"en":"that cannot be trusted or depended on","cn":"不可靠的；不能信赖的","ex":{"en":"The trains are notoriously unreliable.","cn":"火车不准点是出了名的。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不可靠的;不能信赖的","en":"If you describe a person, machine, or method as unreliable, you mean that you cannot trust them.","ex":{"en":"Diplomats can be a notoriously unreliable and misleading source of information","cn":"外交官可能会提供一些靠不住的误导性信息，这是众所周知的。"}}]},"examples":[{"en":"He's totally unreliable as a source of information.","cn":"他提供的消息完全不可信。"},{"en":"The trains are notoriously unreliable.","cn":"火车不准点是出了名的。"}]},"unwillingly":{"oxford":{"phon":"ʌnˈwɪlɪŋli","pos":"adverb","senses":[{"en":"without wanting to do or be something, but forced to by other people","cn":"勉强的；无奈的；迫不得已的","ex":{"en":"The country was drawn unwillingly into the war.","cn":"该国不情愿地被卷入战争。"}}]},"media":{"uk":"media/uk/unwillingly__gb_1.mp3","us":"media/us/unwillingly__us_1.mp3"},"examples":[{"en":"He was unwilling or unable to pay the fine.","cn":""}]},"unfairly":{"oxford":{"phon":"ˌʌnˈfeəli","pos":"adverb","senses":[{"en":"in a way that is not right or fair according to a set of rules or principles; in a way that does not treat people equally","cn":"不公正的；不公平的；待人不平等的","ex":{"en":"She claims to have been unfairly dismissed.","cn":"她声言遭到无理解雇。"}}]},"media":{"uk":"media/uk/unfairly__gb_1.mp3","us":"media/us/unfairly__us_1.mp3"},"examples":[{"en":"The tests discriminate unfairly against older people.","cn":"这些测验使年纪较大的人受到歧视。"},{"en":"She claims to have been unfairly dismissed.","cn":"她声言遭到无理解雇。"}]},"unequal":{"media":{"uk":"media/uk/unequal__gb_1.mp3","us":"media/us/unequal__us_1.mp3"},"oxford":{"phon":"ʌnˈiːkwəl","pos":"adjective","senses":[{"en":"in which people are treated in different ways or have different advantages in a way that seems unfair","cn":"不平等的；不均衡的；不公平的","g":"[usually before noun]","ex":{"en":"an unequal distribution of wealth","cn":"财富的分配不均"}},{"en":"different in size, amount, etc.","cn":"（大小、数量等）不相等的，不同的","ex":{"en":"The sleeves are unequal in length.","cn":"这两只衣袖不一样长。"}},{"en":"not capable of doing something","cn":"力所不及；不胜任","lab":"formal","ex":{"en":"She felt unequal to the task she had set herself.","cn":"她觉得难以完成给自己定下的任务。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不平等的；不公平的","en":"An unequal system or situation is unfair because it gives more power or privileges to one person or group of people than to others.","ex":{"en":"This country still had a deeply oppressive, unequal and divisive political system.","cn":"这个国家的政治体制依然残暴异常，缺少平等，四分五裂。"}},{"pos":"ADJ 形容词","cn":"不能胜任的；力不能及的","en":"If someone is unequal to a task they have to do, they do not have the abilities needed to do it well.","ex":{"en":"Her critics say she has proved unequal to the task","cn":"批评她的人说事实证明她并不具备完成这项工作的能力。"}},{"pos":"ADJ 形容词","cn":"（大小、力量或数量上）不均等的，不对等的","en":"Unequal means being different in size, strength, or amount.","ex":{"en":"The Egyptians probably measured their day in twenty-four hours of unequal length.","cn":"埃及人很有可能用不同长度的24小时来度量日子。"}}]},"examples":[{"en":"She felt unequal to the task she had set herself.","cn":"她觉得难以完成给自己定下的任务。"},{"en":"The sleeves are unequal in length.","cn":"这两只衣袖不一样长。"}]},"uniquely":{"oxford":{"phon":"juˈniːkli","pos":"adverb","senses":[{"en":"used to say that somebody/something is the only one in a particular situation","cn":"独特的：过去常说某人/某物在特定情况下是唯一的","ex":{"en":"The UK, uniquely, has not had to face the problem of mass unemployment.","cn":"唯独英国尚未面临大规模失业的问题。"}},{"en":"in a very special or unusual way","cn":"独特的；罕见的","ex":{"en":"Her past experience made her uniquely suited to lead the campaign.","cn":"她以往的经历使她格外适合领导这场运动。"}}]},"media":{"uk":"media/uk/uniquely__gb_1.mp3","us":"media/us/uniquely__us_1.mp3"},"examples":[{"en":"Her past experience made her uniquely suited to lead the campaign.","cn":"她以往的经历使她格外适合领导这场运动。"},{"en":"The UK, uniquely, has not had to face the problem of mass unemployment.","cn":"唯有英国无须面对大量失业的问题。"}]},"ultimately":{"media":{"uk":"media/uk/ultimately__gb_1.mp3","us":"media/us/ultimately__us_1.mp3"},"oxford":{"phon":"ˈʌltɪmətli","pos":"adverb","senses":[{"en":"in the end; finally","cn":"最终；最后；终归","ex":{"en":"A poor diet will ultimately lead to illness.","cn":"不合理的饮食终将导致疾病。"}},{"en":"at the most basic and important level","cn":"最基本地；根本上","ex":{"en":"All life depends ultimately on oxygen.","cn":"一切生命归根到底都要依赖氧气。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"最终；最后；终于","en":"Ultimately means finally, after a long and often complicated series of events.","ex":{"en":"Whatever the scientists ultimately conclude, all of their data will immediately be disputed.","cn":"不管科学家们最后得出什么样的结论，他们的全部数据将会立即引起争议。"}},{"pos":"ADV 副词","cn":"根本上；归根结底","en":"You use ultimately to indicate that what you are saying is the most important point in a discussion.","ex":{"en":"Ultimately, Bismarck's revisionism scarcely affected or damaged British interests at all.","cn":"从根本上说，俾斯麦的修正主义几乎未对英国的利益造成一丝一毫的影响或损害。"}}]},"examples":[{"en":"All life depends ultimately on oxygen.","cn":"一切生命归根到底都要依赖氧气。"},{"en":"A poor diet will ultimately lead to illness.","cn":"不均衡的饮食终将导致疾病。"}]},"upgrades":{"oxford":{"phon":"ˌʌpˈɡreɪd","pos":"verb","senses":[{"en":"to make a piece of machinery, computer system, etc. more powerful and efficient","cn":"使（机器、计算机系统等）升级；提高；改进"},{"en":"to give sb a more important job","cn":"提升；提拔"}]}},"undergraduates":{"oxford":{"phon":"ˌʌndəˈɡrædʒuət","pos":"noun","senses":[{"en":"a university or college student who is studying for their first degree","cn":"本科生"}]}},"unpacking":{"oxford":{"phon":"ˌʌnˈpæk","pos":"verb","senses":[{"en":"to take things out of a suitcase, bag, etc.","cn":"打开（箱、包等）取；从（箱、包等中）取出"},{"en":"to separate sth into parts so that it is easier to understand","cn":"分析；剖析"}]}},"unpacked":{"oxford":{"phon":"ˌʌnˈpæk","pos":"verb","senses":[{"en":"to take things out of a suitcase, bag, etc.","cn":"打开（箱、包等）取；从（箱、包等中）取出"},{"en":"to separate sth into parts so that it is easier to understand","cn":"分析；剖析"}]}},"utilities":{"oxford":{"phon":"juːˈtɪləti","pos":"noun","senses":[{"en":"( especially NAmE ) a service provided for the public, for example an electricity, water or gas supply","cn":"公用事业"},{"en":"( formal ) the quality of being useful","cn":"实用；效用；有用"}]}},"unrolled":{"oxford":{"phon":"ʌnˈrəʊl","pos":"verb","senses":[{"en":"if you unroll paper, cloth, etc. that was in a roll or if it unrolls , it opens and becomes flat （","cn":"使纸张、织物等）展开，摊开，铺开"},{"en":"to happen one after another in a series","cn":"相继出现；连续发生"}]}},"universities":{"oxford":{"phon":"ˌjuːnɪˈvɜːsəti","pos":"noun","senses":[{"en":"an institution at the highest level of education where you can study for a degree or do research （","cn":"综合性）大学；高等学府"},{"en":"( informal ) the experience of life thought of as giving sb an education, instead of the person gaining formal qualifications","cn":"人生大学（生活体验，相对于正式学历）"}]}},"uttering":{"oxford":{"phon":"ˈʌtə(r)","pos":"adjective","senses":[{"en":"used to emphasize how complete sth is","cn":"完全的；十足的；彻底的"},{"en":"( formal ) to make a sound with your voice; to say sth","cn":"出声；说；讲"}]}},"uncovers":{"oxford":{"phon":"ʌnˈkʌvə(r)","pos":"verb","senses":[{"en":"to remove sth that is covering sth","cn":"揭开盖子"},{"en":"to discover sth that was previously hidden or secret","cn":"发现；揭露；揭发"}]}},"ungenerous":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不公平的；不友善的","en":"If you describe someone's remarks, thoughts, or actions as ungenerous, you mean that they are unfair or unkind.","ex":{"en":"This was a typically ungenerous response.","cn":"这是一个典型的不友善回复。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"吝啬的；不大方的","en":"You can use ungenerous when you are describing a person or organization that is unwilling to give much money to other people.","ex":{"en":"The company had a good pension scheme for the salaried employees and an ungenerous scheme for the hourly paid.","cn":"公司给受薪员工提供了一套很好的养老金计划，但给计时工提供的计划却很吝啬。"}}]}},"urged":{"oxford":{"phon":"ɜːdʒ","pos":"verb","senses":[{"en":"to advise or try hard to persuade sb to do sth","cn":"敦促；催促；力劝"},{"en":"to recommend sth strongly","cn":"大力推荐；竭力主张"}]}},"uses":{"oxford":{"phon":"juːz","pos":"verb","senses":[{"en":"to do sth with a machine, a method, an object, etc. for a particular purpose","cn":"使用；利用；运用"},{"en":"to take a particular amount of a liquid, substance, etc. in order to achieve or make sth","cn":"消耗"}]}},"unions":{"oxford":{"phon":"ˈjuːniən","pos":"noun","senses":[{"en":"an organization of workers, usually in a particular industry, that exists to protect their interests, improve conditions of work, etc.","cn":"工会"},{"en":"an association or a club for people or organizations with the same interest","cn":"协会；联合会；会社；俱乐部"}]}},"uppers":{"oxford":{"phon":"ˈʌpə(r)","pos":"adjective","senses":[{"en":"located above sth else, especially sth of the same type or the other of a pair","cn":"上边的，上面的，上层的（尤指同类或一对中的一个）"},{"en":"at or near the top of sth","cn":"上部的；靠上部的"}]}},"using":{"oxford":{"phon":"juːz","pos":"verb","senses":[{"en":"to do sth with a machine, a method, an object, etc. for a particular purpose","cn":"使用；利用；运用"},{"en":"to take a particular amount of a liquid, substance, etc. in order to achieve or make sth","cn":"消耗"}]}},"uniforms":{"oxford":{"phon":"ˈjuːnɪfɔːm","pos":"noun","senses":[{"en":"the special set of clothes worn by all members of an organization or a group at work, or by children at school","cn":"制服；校服"},{"en":"the clothes worn by the members of a sports team when they are playing （","cn":"运动队）队服"}]}},"unfulfilled":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未履行的；未实现的；未完成的；未得到满足的","en":"If you use unfulfilled to describe something such as a promise, ambition, or need, you mean that what was promised, hoped for, or needed has not happened.","ex":{"en":"Do you have any unfulfilled ambitions?","cn":"你有什么未实现的抱负吗？"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"失望的；不满的","en":"If you describe someone as unfulfilled, you mean that they feel dissatisfied with life or with what they have done.","ex":{"en":"You must let go of the idea that to be single is to be unhappy and unfulfilled","cn":"你要摈弃单身就会不快乐、就会有失败感这一想法。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"an unfulfilled hope, desire, dream etc has not been achieved 〔","cn":"愿望﹑梦想等〕未实现的﹐未达到的"},{"en":"someone who is unfulfilled feels they could be achieving more in their job, relationship etc","cn":"壮志未酬的﹐宏图未展的"}]},"media":{"uk":"media/ldoce/hwd/bre/2/unfulfilled0205.mp3","us":"media/ldoce/hwd/ame/f/laadunfulfilled.mp3"},"examples":[{"en":"unfulfilled ambitions/hopes/promises, etc.","cn":"未实现的抱负、希望、诺言等"},{"en":"His dream of competing in the Olympics remained unfulfilled .","cn":"他登上奥运会赛场的梦想一直没有实现。"}],"oxford":{"phon":"ˌʌnfʊlˈfɪld","pos":"adjective","senses":[{"en":"that has not been satisfied or achieved","cn":"未满足的；未实现的；未兑现的","ex":{"en":"unfulfilled ambitions/hopes/promises, etc.","cn":"未实现的抱负、希望、诺言等"}},{"en":"if a person feels unfulfilled, they feel that they could achieve more in their life or work","cn":"壮志未酬的；宏图未展的","ex":{"en":"She’s feeling restless and unfulfilled in her present job.","cn":"她对目前的工作感到不安和不满足。"}}]}},"underwrite":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(机构或公司)为…保险，负担…的费用，承销","en":"If an institution or company underwrites an activity or underwrites the cost of it, they agree to provide any money that is needed to cover losses or buy special equipment, often for an agreed fee.","ex":{"en":"...58,500 dollars to underwrite a new home","cn":"58,500美元承保一个新居"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if a government or other organization subsidizes something, it pays part of the cost","cn":""},{"en":"if a company sponsors something such as sports event, a theatre, or an art show, it provides some of the money that is needed, often as a form of advertising","cn":""},{"en":"to provide all the money needed to pay for something, especially an important or expensive plan","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41underwrite.mp3","us":"media/ldoce/hwd/ame/1/underwrite.mp3"},"examples":[{"en":"The government has agreed to underwrite the project with a grant of £5 million.","cn":"政府同意拨款500万英镑资助该项目。"}],"oxford":{"phon":"ˌʌndəˈraɪt","pos":"verb","senses":[{"en":"to accept financial responsibility for an activity so that you will pay for special costs or for losses it may make","cn":"承担经济责任（包括支付特别费用或损失）","ex":{"en":"The British government ended up underwriting the entire project.","cn":"结果整个项目的费用都由英国政府承担。"}},{"en":"to accept responsibility for an insurance policy so that you will pay money in case loss or damage happens","cn":"承担保险责任；承保"},{"en":"to agree to buy shares that are not bought by the public when new shares are offered for sale","cn":"包销，承销（未获认购的新发行股份）"}]}},"ungovernable":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（国家或地区）难治理的，难控制的","en":"If you describe a country or region as ungovernable, you mean that it seems impossible to control or govern it effectively, for example because of violence or conflict among the population.","ex":{"en":"Beset by ethnic strife, the province remains ungovernable","cn":"该省因受种族冲突困扰而失控。"}},{"pos":"ADJ 形容词","cn":"（感情）难以抑制的","en":"If you describe feelings as ungovernable, you mean that they are so strong that they cannot be controlled.","ex":{"en":"He was filled with an ungovernable rage.","cn":"他怒不可遏。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a country or area that is ungovernable is one in which the people cannot be controlled by the government, the police etc 〔","cn":"国家或地区〕难统治[控制]的"},{"en":"feelings or types of behaviour that are ungovernable are impossible to control 〔","cn":"感情或行为〕难控制的"}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41ungovernable.mp3","us":"media/ldoce/hwd/ame/6/ungovernable.mp3"},"examples":[{"en":"ungovernable rage","cn":"难以抑制的暴怒"}],"oxford":{"phon":"ʌnˈɡʌvənəbl","pos":"adjective","senses":[{"en":"impossible to govern or control","cn":"无法管治的；难以控制的","ex":{"en":"Corruption and civil unrest had made the country ungovernable.","cn":"腐败和内乱使这个国家无法治理。"}},{"en":"impossible to control","cn":"抑制不住的；无法控制的","lab":"formal","ex":{"en":"ungovernable rage","cn":"难以抑制的暴怒"}}]}},"unobtainable":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"得不到的；不能获得的","en":"If something or someone is unobtainable, you cannot get them.","ex":{"en":"...an unobtainable married man","cn":"得不到的已婚男人"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"goods or products that are unobtainable are impossible to get or buy","cn":""},{"en":"if something that you really want is not to be had or not to be found you know it is not available at all because you have tried to get it everywhere","cn":""},{"en":"if something such as a seat, room, or place is taken , someone has already arranged to use it and it is not available for other people to use","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Whether it’s an unobtainable career in the NBA, an unobtainable friendship with the Queen of England, or an unobtainable new Japanese video game, the word unobtainable refers to something that you just can’t get."}]},"media":{"uk":"media/ldoce/hwd/bre/1/unobtainable0205.mp3","us":"media/ldoce/hwd/ame/c/ld41unobtainable.mp3"},"examples":[{"en":"Fresh fruit was unobtainable in the winter.","cn":"新鲜水果在冬季是买不到的。"}],"oxford":{"phon":"ˌʌnəbˈteɪnəbl","pos":"adjective","senses":[{"en":"that cannot be obtained","cn":"得不到；无法得到","ex":{"en":"Unfortunately, it is unobtainable in most shops.","cn":"不幸的是，大多数商店都买不到。"}}]}},"uninitiated":{"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"缺乏某种特定知识（或经验）的人；不熟悉某种特定情况的人","en":"You can refer to people who have no knowledge or experience of a particular subject or activity as the uninitiated .","ex":{"en":"For the uninitiated, Western Swing is a fusion of jazz, rhythm & blues, rock & roll and country music","cn":"对于外行人来说，西部摇摆是爵士乐、节奏布鲁斯、摇滚乐和乡村音乐的融合。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who is inexperienced does not know much about a job or activity, either because they have not done it at all or because they have done it for only a short time","cn":""},{"en":"to not have enough experience of doing a particular job or activity","cn":""},{"en":"if you are new to a job or activity, you do not have much experience of doing it because you have only just started it","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41uninitiated.mp3","us":"media/ldoce/hwd/ame/1/uninitiated.mp3"},"examples":[{"en":"To the uninitiated the system seems too complicated.","cn":"对外行而言，这个系统似乎过于复杂。"},{"en":"To the uninitiated, this will make little sense.","cn":"对外行来说﹐这并没有什么意义。"}],"oxford":{"phon":"ˌʌnɪˈnɪʃieɪtɪd","pos":"adjective","senses":[{"en":"having no special knowledge or experience of something","cn":"外行的;缺少经验的","ex":{"en":"The detailed notes in each chapter offer support to the uninitiated reader.","cn":"每章中的详细注释为外行读者提供支持。"}}]}},"upland":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"高地的；高原的","en":"Upland places are situated on high land.","ex":{"en":"...San Marino, the tiny upland republic","cn":"圣马力诺，面积狭小的高地共和国"}},{"pos":"N-PLURAL 复数名词","cn":"高地；高原；山地","en":"Uplands are areas of high land.","ex":{"en":"Flooding was caused by water gushing into rivers from uplands.","cn":"从山地奔流而下的水涌入河中引发了洪水。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the parts of a country that are away from the sea and are higher than other areas","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/6/brelasdeuplands.mp3","us":"media/ldoce/hwd/ame/3/laaduplands.mp3"},"examples":[{"en":"upland agriculture","cn":"山区农业"}],"oxford":{"phon":"ˈʌplənd","pos":"noun","senses":[{"en":"an area of high land that is not near the coast","cn":"（内陆）高地；山地","ex":{"en":"Conservation groups are concerned to protect wildlife in the uplands of Britain.","cn":"保护组织致力于保护英国高地的野生动物。"}},{"en":"in or connected with an area of high land that is not near the coast","cn":"（内陆）高地；山地","ex":{"en":"upland agriculture","cn":"高地农业"},"pos":"adjective"}]}},"uncorroborated":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(说法)未经证实的，无确证的","en":"An uncorroborated statement or claim is not supported by any evidence or information.","ex":{"en":"Uncorroborated confessions should no longer be accepted by courts.","cn":"没有证据证实的供词不应再被法庭采用。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"an uncorroborated claim or statement is one which is not supported by any proof","cn":"无确证的"}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41uncorroborated.mp3","us":"media/ldoce/hwd/ame/2/ld41uncorroborated.mp3"},"examples":[{"en":"He was convicted on the uncorroborated evidence of the alleged victim.","cn":"根据所谓的受害人提供的没有佐证的证词﹐他被判定有罪。"}],"oxford":{"phon":"ˌʌnkəˈrɒbəreɪtɪd","pos":"adjective","senses":[{"en":"not supported by any other evidence; not having been corroborated","cn":"无确证的；未经证实的"}]}},"unconvincing":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（论点、解释等）难以令人信服的，没有说服力的","en":"If you describe something such as an argument or explanation as unconvincing, you find it difficult to believe because it does not seem real.","ex":{"en":"Mr Patel phoned the University for an explanation, and he was given the usual unconvincing excuses","cn":"帕特尔先生致电大学要求对方作出解释，但只得到了一些无关痛痒的惯用托词。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（故事或人物）不可信的，不真实的","en":"If you describe a story or a character in a story as unconvincing, you think they do not seem likely or real.","ex":{"en":"...an unconvincing love story.","cn":"不太可信的爱情故事"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"failing to make you believe that something is true or real","cn":"不令人信服的﹔难以置信的"}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld44unconvincing.mp3","us":"media/ldoce/hwd/ame/a/ld44unconvincing.mp3"},"examples":[{"en":"I find the characters in the book very unconvincing.","cn":"我觉得书中的人物很不真实。"},{"en":"She managed a weak, unconvincing smile.","cn":"她勉强挤出一丝笑意。"}],"oxford":{"phon":"ˌʌnkənˈvɪnsɪŋ","pos":"adjective","senses":[{"en":"not seeming true or real; not making you believe that something is true","cn":"似乎不真实的；不令人信服的；难以相信的","ex":{"en":"I find the characters in the book very unconvincing.","cn":"我觉得书中的人物很不真实。"}}]}},"undersea":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"海面下的；海底的","en":"Undersea things or activities exist or happen below the surface of the sea.","ex":{"en":"...an undersea pipeline running to Europe.","cn":"通往欧洲的海底管道"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"happening or existing below the surface of the sea","cn":"海底的﹔海面下的﹔在海面下进行的"}]},"media":{"uk":"media/ldoce/hwd/bre/b/undersea0205.mp3","us":"media/ldoce/hwd/ame/3/laadundersea.mp3"},"examples":[{"en":"undersea cables/earthquakes","cn":"海底电缆/地震"},{"en":"undersea exploration","cn":"海底探险"}],"oxford":{"phon":"ˈʌndəsiː","pos":"adjective","senses":[{"en":"found, used or happening below the surface of the sea","cn":"海面下的；海底的","ex":{"en":"undersea cables/earthquakes","cn":"海底电缆／地震"}}]}},"unsubstantiated":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未经证实的；无根据的；不确凿的","en":"A claim, accusation, or story that is unsubstantiated has not been proved to be valid or true.","ex":{"en":"I do object to their claim, which I find totally unsubstantiated.","cn":"我强烈反对他们的说法，那是毫无根据的。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not proved to be true","cn":"未被证明的﹐未经证实的"}]},"media":{"uk":"media/ldoce/hwd/bre/6/brelasdeunsubstantiated.mp3","us":"media/ldoce/hwd/ame/f/laadunsubstantiated.mp3"},"examples":[{"en":"an unsubstantiated claim/rumour, etc.","cn":"未经证实的说法、传言等"},{"en":"unsubstantiated allegations of child abuse","cn":"未经证实的虐待儿童的指控"}],"oxford":{"phon":"ˌʌnsəbˈstænʃieɪtɪd","pos":"adjective","senses":[{"en":"not proved to be true by evidence","cn":"未经证实的；未被证明的","ex":{"en":"an unsubstantiated claim/rumour, etc.","cn":"未经证实的说法、传言等"}}]}},"usurp":{"collins":{"senses":[{"pos":"VERB 动词","cn":"夺取；篡夺；侵占","en":"If you say that someone usurps a job, role, title, or position, they take it from someone when they have no right to do this.","ex":{"en":"Did she usurp his place in his mother's heart?","cn":"她取代了他在他母亲心目中的地位吗？"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to take someone else’s power, position, job etc when you do not have the right to","cn":"篡夺﹐夺取〔权力﹑地位﹑工作等〕"}]},"vocab":{"pos":"v","senses":[{"en":"If you take over your neighbor's backyard and claim his in-ground swimming pool as your own, you might seize control of, or usurp his yard, but he'll probably call the cops on you."}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld44usurp.mp3","us":"media/ldoce/hwd/ame/1/usurp.mp3"},"examples":[{"en":"There were a couple of attempts to usurp the young king.","cn":"屡次有人企图篡夺那位年轻国王的王位。"}],"oxford":{"phon":"juːˈzɜːp","pos":"verb","senses":[{"en":"to take somebody’s position and/or power without having the right to do this","cn":"篡夺；侵权","ex":{"en":"Democratically elected representatives should not be usurped by pressure groups.","cn":"民主选举产生的代表不应被压力集团篡夺。"}}]}},"untruth":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"诳语；谎言；假话","en":"An untruth is a lie.","ex":{"en":"The Advertising Standards Authority accused estate agents of using blatant untruths","cn":"广告标准管理局控告房地产代理商使用无耻的谎言。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something you say or write that you know is untrue","cn":""},{"en":"a lie that you tell to avoid upsetting someone","cn":""},{"en":"a lie, especially about something that is not very important – used especially by children","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/f/untruth0205.mp3","us":"media/ldoce/hwd/ame/3/untruth.mp3"},"oxford":{"phon":"ˌʌnˈtruːθ","pos":"noun","senses":[{"en":"a lie. People often say ‘untruth’ to avoid saying ‘lie’.","cn":"（lie 的委婉说法）妄语，诳语，假话","g":"[countable]","lab":"formal","ex":{"en":"Her account of what had happened was a patent untruth.","cn":"她对所发生事情的描述显然是谎言。"}},{"en":"the state of being false","cn":"虚伪；虚假；不真实","g":"[uncountable]"}]}},"underpants":{"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"(英国英语)男用内裤;(美国英语)(男用或女用)内裤;衬裤","en":"Underpants are a piece of underwear which have two holes to put your legs through and elastic around the top to hold them up round your waist or hips. In British English, underpants refers to only men's underwear but in American English it refers to both men's and women's."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a short piece of underwear worn by men under their trousers 〔","cn":"男用〕衬裤﹐内裤"},{"en":"a short piece of underwear worn under trousers by men or women 〔","cn":"男用或女用的〕衬裤﹐内裤"}]},"collocations":{"phrases":["ADJ. men's","QUANT. pair","PREP. in your ~ He sat on the examination table in his underpants. •"]},"media":{"uk":"media/ldoce/hwd/bre/0/underpants0205.mp3","us":"media/ldoce/hwd/ame/2/underpants.mp3"},"oxford":{"phon":"ˈʌndəpænts","pos":"noun","senses":[{"en":"a piece of men’s underwear worn under their trousers","cn":"（男式）内裤，衬裤","lab":"informal","ex":{"en":"He came to the door dressed only in his underpants.","cn":"他来开门时只穿了条内裤。"}},{"en":"a piece of underwear worn by men or women under trousers, a skirt, etc.","cn":"（男式或女式）内裤","lab":"North American English"}]}},"undoing":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"失败的原因；毁灭的原因","en":"If something is someone's undoing, it is the cause of their failure.","ex":{"en":"His lack of experience may prove to be his undoing","cn":"他缺乏经验可能会最终导致他的失败。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to cause someone’s shame, failure etc","cn":"是某人蒙羞[失败]的原因[祸根]"}]},"media":{"uk":"media/ldoce/hwd/bre/a/brelasdeundoing.mp3","us":"media/ldoce/hwd/ame/3/undoing.mp3"},"examples":[{"en":"That one mistake was his undoing.","cn":"他一失足即成千古恨。"},{"en":"In the end, drink was his undoing.","cn":"最后﹐喝酒害了他。"}],"oxford":{"phon":"ʌnˈduːɪŋ","pos":"noun","senses":[{"en":"the reason why somebody fails at something or is unsuccessful in life","cn":"失败的原因","ex":{"en":"That one mistake was his undoing.","cn":"他一失足即成千古恨。"}}]}},"unwary":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无戒备的；无防备的；无警惕的","en":"If you describe someone as unwary, you mean that they are not cautious or experienced and are therefore likely to be harmed or deceived.","ex":{"en":"With its quicksands the river usually drowns a few unwary visitors every season.","cn":"因有流沙，往往每季都会有几个游客不小心在这条河里溺水身亡。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not knowing about possible problems or dangers, and therefore easily harmed or deceived","cn":"不警觉的﹐不提防的"},{"en":"people who are unwary","cn":"不警觉的人﹐不提防的人"}]},"vocab":{"pos":"adj","senses":[{"en":"Someone who's unwary isn't careful — in fact, an unwary person might be a little bit reckless. When your unwary cousin travels to China, he might end up being overcharged for a rickshaw ride."}]},"media":{"uk":"media/ldoce/hwd/bre/c/unwary0205.mp3","us":"media/ldoce/hwd/ame/4/laadunwary.mp3"},"examples":[{"en":"The stock market is full of traps for the unwary.","cn":"对无风险意识的人而言，股票市场充满了陷阱。"},{"en":"pitfalls that can trap the unwary","cn":"不警觉者易上当的圈套"}],"oxford":{"phon":"ʌnˈweəri","pos":"adjective","senses":[{"en":"not aware of the possible dangers or problems of a situation and therefore likely to be harmed in some way","cn":"不警觉的；不提防的","g":"[only before noun]","ex":{"en":"Exams are not designed to set traps for unwary students.","cn":"考试并不是为了给粗心的学生设置陷阱。"}},{"en":"people who are unwary","cn":"粗心的人；不警觉的人","g":"[plural]","ex":{"en":"The stock market is full of traps for the unwary.","cn":"对无风险意识的人而言，股票市场充满了陷阱。"}}]}},"upload":{"collins":{"senses":[{"pos":"VERB 动词","cn":"上传；上载","en":"If you upload data, you transfer it to your computer or from your computer to another computer."}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to look at information on the Internet, especially when you look quickly in order to find something that interests you","cn":""},{"en":"to copy a file from the Internet onto your own computer","cn":""},{"en":"to copy something from your computer onto the Internet","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld44upload.mp3","us":"media/ldoce/hwd/ame/a/upload.mp3"},"examples":[{"en":"It might take a while for this to upload.","cn":"上载这个可能要花些时间。"},{"en":"tips on handling file uploads","cn":"关于如何上传文件的提示"}],"oxford":{"phon":"ˌʌpˈləʊd","pos":"verb","senses":[{"en":"to send data to another computer","cn":"上传","ex":{"en":"The data was uploaded on Friday July 28 at 11:23.","cn":"该数据于 7 月 28 日星期五 11:23 上传。"}},{"en":"data that has been moved to a larger computer system from a smaller one","cn":"上载（或上传）的数据","pos":"noun"}]}},"unfasten":{"collins":{"senses":[{"pos":"VERB 动词","cn":"松开；解开","en":"If you unfasten something that is closed, tied, or held together, or if you unfasten the thing holding it, you loosen or remove the thing holding it.","ex":{"en":"When Ted was six we decided that he needed to know how to fasten and unfasten his seat belt","cn":"特德六岁的时候，我们认为他得知道如何系上和解开安全带了。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to open the two sides of a piece of clothing, bag, belt etc","cn":""},{"en":"to unfasten clothes or unfasten buttons, zips etc on clothes","cn":""},{"en":"to unfasten the knot that fastens shoes, a tie, a scarf etc","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/6/unfasten0205.mp3","us":"media/ldoce/hwd/ame/f/laadunfasten.mp3"},"examples":[{"en":"to unfasten a belt/button, etc.","cn":"解开皮带、钮扣等"},{"en":"He unfastened the top button of his shirt.","cn":"他解开衬衫最上面的那颗扣子。"}],"oxford":{"phon":"ʌnˈfɑːsn","pos":"verb","senses":[{"en":"to open something that is fastened","cn":"解开；松开；打开","ex":{"en":"to unfasten a belt/button, etc.","cn":"解开皮带、纽扣等"}}]}},"unsanitary":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"脏的；不健康的","en":"Something that is unsanitary is dirty and unhealthy, so that you may catch a disease from it.","ex":{"en":"...diseases caused by unsanitary conditions","cn":"由不卫生的环境引起的疾病"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"dirty and likely to cause disease","cn":"不卫生的﹔有碍健康的"}]},"media":{"uk":"media/ldoce/hwd/bre/b/unsanitary0205.mp3","us":"media/ldoce/hwd/ame/b/laadunsanitary.mp3"},"examples":[{"en":"unsanitary conditions","cn":"不卫生的环境"}],"oxford":{"phon":"ʌnˈsænətri","pos":"adjective","senses":[{"en":"dirty and likely to spread disease","cn":"不卫生的；不洁的","ex":{"en":"They were forced to live in overcrowded and unsanitary conditions.","cn":"他们被迫生活在拥挤且不卫生的环境中。"}}]}},"unlit":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未点着的","en":"An unlit fire or cigarette has not been made to start burning."},{"pos":"ADJ 形容词","cn":"没有灯光的；黑暗的","en":"An unlit street or building is dark because there are no lights switched on in it."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if a place is dark , there is little or no light","cn":""},{"en":"completely dark, so that nothing can be seen","cn":""},{"en":"a gloomy place or room is not at all bright or cheerful - use this especially in stories or written descriptions","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/d/brelasdeunlit.mp3","us":"media/ldoce/hwd/ame/5/laadunlit.mp3"},"examples":[{"en":"an unlit passage","cn":"无灯光的通道"},{"en":"an unlit cigarette","cn":"未点燃的香烟"}],"oxford":{"phon":"ˌʌnˈlɪt","pos":"adjective","senses":[{"en":"dark because there are no lights or the lights are not switched on","cn":"黑暗的；无灯光的","ex":{"en":"an unlit passage","cn":"无灯光的通道"}},{"en":"not yet burning","cn":"未点燃的","ex":{"en":"an unlit cigarette","cn":"未点燃的香烟"}}]}},"uncommitted":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未作承诺的；未表态的","en":"If you are uncommitted, you have not yet decided to support a particular idea, belief, group, or person, or you are unwilling to show your support.","ex":{"en":"The allegiance of uncommitted voters will be crucial","cn":"未表态的选民支持谁将是至关重要的。"}},{"pos":"ADJ 形容词","cn":"（资源等）未指定用途的，未明确用途的","en":"If resources are uncommitted, it has not yet been decided what to use them for.","ex":{"en":"...uncommitted gas reserves.","cn":"用途待定的汽油储备"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not having decided or promised to support a particular group, political belief etc","cn":"未作承诺的﹔未表态的"}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41uncommitted.mp3","us":"media/ldoce/hwd/ame/2/uncommitted.mp3"},"examples":[{"en":"The party needs to canvass the uncommitted voters.","cn":"这个党需要向未表明态度的选民游说拉票。"},{"en":"So far, they are uncommitted to his plan.","cn":"到目前为止﹐他们对他的计划还是不置可否。"}],"oxford":{"phon":"ˌʌnkəˈmɪtɪd","pos":"adjective","senses":[{"en":"not having given or promised support to a particular person, group, belief, action, etc.","cn":"未作承诺的；未表态的","ex":{"en":"The party needs to canvass the uncommitted voters.","cn":"这个党需要向未表明态度的选民游说拉票。"}}]}},"unstated":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"没有言明的；未申明的","en":"You say that something is unstated when it has not been expressed in words.","ex":{"en":"The implication was plain, if left unstated","cn":"其含意不言而喻。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not expressed in words","cn":"未陈述的﹐未阐明的"}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41unstated.mp3","us":"media/ldoce/hwd/ame/b/laadunstated.mp3"},"examples":[{"en":"Their reasoning was based on a set of unstated assumptions.","cn":"他们的推理是以一系列未说明的假定为基础的。"},{"en":"unstated assumptions","cn":"未说明的假设"}],"oxford":{"phon":"ʌnˈsteɪtɪd","pos":"adjective","senses":[{"en":"not stated; not said in words but understood or agreed between people","cn":"未说出的；未用语言表达的；心照不宣的","ex":{"en":"Their reasoning was based on a set of unstated assumptions.","cn":"他们的推理是以一系列未说明的假定为基础的。"}}]}},"undertone":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"低声；悄声","en":"If you say something in an undertone, you say it very quietly.","ex":{"en":"'What d'you think?' she asked in an undertone","cn":"“你觉得怎么样？”她小声地问道。"}},{"pos":"N-COUNT 可数名词","cn":"言下之意；寓意","en":"If something has undertones of a particular kind, it suggests ideas or attitudes of this kind without expressing them directly.","ex":{"en":"The sobbing voice had an undertone of anger.","cn":"啜泣声中隐隐透着愤怒。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"if a statement, fact, event etc suggests that something is true, it seems to mean that it is true or could be true, but this is not directly stated","cn":""},{"en":"if a statement, fact, event etc implies that something is true, it suggests very strongly that it is true","cn":""},{"en":"to say something in an indirect way - use this especially when you are saying what the real meaning of a statement is","cn":""}]},"collocations":{"phrases":["ADJ. sinister | racist, sexual The article was full of racist undertones.","VERB + UNDERTONE have","PREP. in an ~ &lsquo;I don't think she's been told yet,&rsquo; he said in an undertone. The couple at the next table were speaking in undert"]},"media":{"uk":"media/ldoce/hwd/bre/6/undertone0205.mp3","us":"media/ldoce/hwd/ame/7/undertone.mp3"},"examples":[{"en":"The play does not have the political undertones of the novel.","cn":"这部戏没有小说的那种政治寓意。"},{"en":"His soft words contained an undertone of warning.","cn":"他温和的话中蕴涵着警告之意。"}],"oxford":{"phon":"ˈʌndətəʊn","pos":"noun","senses":[{"en":"a feeling, quality or meaning that is not expressed directly but can still be understood from what somebody says or does","cn":"蕴涵的感情（或特质、意思）；寓意；弦外之音","ex":{"en":"His soft words contained an undertone of warning.","cn":"他温和的话中蕴涵着警告之意。"}}]}},"upshot":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"（通常指意外的）结果，结局","en":"The upshot of a series of events or discussions is the final result of them, usually a surprising result.","ex":{"en":"The upshot is that we have lots of good but not very happy employees","cn":"结果是我们有很多优秀然而却不太快乐的员工。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something that happens because of someone's actions or because of something else that happened before","cn":""},{"en":"when a person or situation is changed by something that happens or something that someone does","cn":""},{"en":"the consequences of an action, decision etc are the things that happen as a result of it, which are usually bad","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"The upshot of an action is the end result, whatever happens last as a consequence of the original action. The upshot of reading this sentence is that you will understand what the word upshot means."}]},"media":{"uk":"media/ldoce/hwd/bre/9/upshot0205.mp3","us":"media/ldoce/hwd/ame/f/upshot.mp3"},"examples":[{"en":"The upshot of it all was that he left college and got a job.","cn":"事情的结局是，他离开学院并投身工作了。"},{"en":"The upshot was that after much argument they all agreed to help her.","cn":"最后的结果是﹐经过长时间争论﹐他们全都同意帮助她。"}]},"unsullied":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"未受污染的;未受玷污的;清白的","en":"If something is unsullied, it has not been spoiled or made less pure by the addition of something unpleasant or unacceptable.","ex":{"en":"She had the combined talents of toughness, intellect, experience and unsullied reputation","cn":"她刚强果敢、才智超群、经验丰富，而且名声没有任何污点。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not spoiled by anything","cn":"未受污染的﹐洁净的"}]},"vocab":{"pos":"adj","senses":[{"en":"Your reputation is unsullied, or unsoiled, because you study hard, you don’t skip school, and you are generally kind to everyone. Your friend’s reputation hasn’t stayed unsullied since he got caught selling answers to tests."}]},"media":{"uk":"media/ldoce/hwd/bre/4/unsullied0205.mp3","us":"media/ldoce/hwd/ame/4/laadunsullied.mp3"},"oxford":{"phon":"ˌʌnˈsʌlid","pos":"adjective","senses":[{"en":"not made less good by anything; still pure or in the original state","cn":"未被玷污的；保持洁净的；纯洁的","ex":{"en":"the unsullied emotions of childhood","cn":"童年未受玷污的情感"}}]}},"unheeded":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（警告、危险等）未受重视的，被忽视的","en":"If you say that something such as a warning or danger goes unheeded, you mean that it has not been taken seriously or dealt with.","ex":{"en":"The advice of experts went unheeded","cn":"专家的意见未被重视。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"noticed but not listened to, accepted, or believed","cn":"视而不见的﹔被忽视的"}]},"media":{"uk":"media/ldoce/hwd/bre/a/unheeded0205.mp3","us":"media/ldoce/hwd/ame/3/laadunheeded.mp3"},"examples":[{"en":"Her warning went unheeded.","cn":"她的警告没有引起重视。"},{"en":"Her warnings went unheeded .","cn":"她的警告无人理会。"}],"oxford":{"phon":"ʌnˈhiːdɪd","pos":"adjective","senses":[{"en":"that is heard, seen or noticed but then ignored","cn":"遭视而不见的；遭听而不闻的；被忽视的","ex":{"en":"Her warning went unheeded.","cn":"她的警告没有引起重视。"}}]}},"unctuous":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(人)虚情假意的，虚与委蛇的","en":"If you describe someone as unctuous, you are critical of them because they seem to be full of praise, kindness, or interest, but are obviously insincere.","ex":{"en":"...the kind of unctuous tone that I've heard often at diplomatic parties.","cn":"我常在外交聚会上听到的那种虚与委蛇的腔调"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（食品、饮料）含乳脂的，油的，油腻的","en":"If you describe food or drink as unctuous, you mean that it is creamy or oily.","ex":{"en":"Goose fat gives the most unctuous flavour but you can use chicken fat.","cn":"鹅油最肥美，不过你也可以用鸡油。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"too friendly and praising people too much in a way that seems very insincere","cn":"甜言蜜语的﹐假殷勤的﹐谄媚的"}]},"vocab":{"pos":"adj","senses":[{"en":"You might know the idea of the adjective unctuous by other words like \"oily,\" \"smarmy,\" or overly \"flattering.\" When a person is unctuous , you can't trust their kindness, because they usually want something in return."}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41unctuous.mp3","us":"media/ldoce/hwd/ame/a/unctuous.mp3"},"oxford":{"phon":"ˈʌŋktʃuəs","pos":"adjective","senses":[{"en":"friendly or giving praise in a way that is not sincere and that is therefore unpleasant","cn":"谄媚的；油滑的；拍马奉迎的","ex":{"en":"an unctuous host","cn":"油腔滑调的主人"}}]}},"umbrage":{"collins":{"senses":[{"pos":"PHRASE 短语","cn":"愤懑；不快；生气","en":"If you say that a person takes umbrage, you mean that they are upset or offended by something that someone says or does to them, often without much reason.","ex":{"en":"He takes umbrage against anyone who criticises him.","cn":"不管谁批评他，他都心生愤懑。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to be offended by something that someone has done or said, often without good reason 〔","cn":"通常没有理由地〕（为某事）生气﹐（因某事）见怪"}]},"vocab":{"pos":"n","senses":[{"en":"When someone takes umbrage at something, they find it offensive, and it probably makes them angry."}]},"media":{"uk":"media/ldoce/hwd/bre/6/umbrage0205.mp3","us":"media/ldoce/hwd/ame/b/umbrage.mp3"}},"unification":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"合一; 联合；统一","en":"Unification is the process by which two or more countries join together and become one country.","ex":{"en":"...the process of general European unification.","cn":"欧洲一体化进程"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the act of combining two or more groups, countries etc to make a single group or country","cn":"联合﹐统一"}]},"vocab":{"pos":"n","senses":[{"en":"Unification describes the bringing together of two or more things so they become a single unit. If your marriage turns your feuding families into one big happy group, you pulled off a unification that would make Romeo and Juliet jealous."}]},"collocations":{"phrases":["ADJ. European, German, etc. | economic, monetary, political","VERB + UNIFICATION achieve, bring about"]},"media":{"uk":"media/ldoce/hwd/bre/9/unification0205.mp3","us":"media/ldoce/hwd/ame/a/unification.mp3"},"examples":[{"en":"the unification of Germany","cn":"德国的统一"}],"oxford":{"phon":"ˌjuːnɪfɪˈkeɪʃn","pos":"noun","senses":[{"en":"the act or process of joining people, things, parts of a country, etc. together so that they can form a single unit","cn":"把人、物、国家的一部分等联合起来，使之成为一个整体的行为或过程。","ex":{"en":"the unification of Germany","cn":"德国的统一"}}]}},"upsurge":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"飙升；急剧增长","en":"If there is an upsurge in something, there is a sudden, large increase in it.","ex":{"en":"...the upsurge in oil prices","cn":"油价的暴涨"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a sudden increase","cn":"急剧上升﹐猛增﹐飙升"},{"en":"a sudden strong feeling 〔","cn":"情绪的〕高涨﹐激发"}]},"vocab":{"pos":"n","senses":[{"en":"An upsurge is when there's a sudden rise of something's strength or size. Hordes of people walking around your town with cameras might be due to an upsurge in tourism, for example."}]},"collocations":{"phrases":["ADJ. great, massive | sudden","PREP. ~ in an upsurge in violent crime"]},"media":{"uk":"media/ldoce/hwd/bre/7/upsurge0205.mp3","us":"media/ldoce/hwd/ame/3/upsurge.mp3"},"examples":[{"en":"a recent upsurge of interest in his movies","cn":"最近他的电影掀起的一阵热潮"},{"en":"an upsurge in violent crime","cn":"暴力犯罪的猛增"}],"oxford":{"phon":"ˈʌpsɜːdʒ","pos":"noun","senses":[{"en":"a sudden large increase in something","cn":"急剧上升；飙升；猛增","ex":{"en":"an upsurge in violent crime","cn":"暴力犯罪的猛增"}}]}},"unabated":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未减弱的；未减少的；未衰退的","en":"If something continues unabated, it continues without any reduction in intensity or amount.","ex":{"en":"The fighting has continued unabated for over 24 hours.","cn":"激战已经持续了24小时以上。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"continuing without becoming any weaker or less violent","cn":"不减弱的[地]﹔不衰退的[地]"}]},"media":{"uk":"media/ldoce/hwd/bre/c/unabated0205.mp3","us":"media/ldoce/hwd/ame/d/unabated.mp3"},"examples":[{"en":"The rain continued unabated.","cn":"雨势一直没减弱。"},{"en":"The storm continued unabated throughout the night.","cn":"风暴持续了一夜﹐丝毫没有减弱。"}],"oxford":{"phon":"ˌʌnəˈbeɪtɪd","pos":"adjective","senses":[{"en":"without becoming any less strong","cn":"不减；未变弱","ex":{"en":"The rain continued unabated.","cn":"雨势一直没减弱。"}}]}},"upraised":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"举起的；抬起的；提高的","en":"If your hand or an object is upraised, you are holding it up in the air.","ex":{"en":"A soldier stood on the centre line of the road, his arm upraised.","cn":"一名士兵站在道路中心线上，一只胳膊高高举起。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"raised or lifted up – used especially about someone’s hand or arm 〔","cn":"尤指手或手臂〕举起的﹐扬起的"}]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41upraised.mp3","us":"media/ldoce/hwd/ame/e/laadupraised.mp3"},"examples":[{"en":"She strode towards them, her fist upraised.","cn":"她举着拳头，大步迈向他们。"}],"oxford":{"phon":"ˌʌpˈreɪzd","pos":"adjective","senses":[{"en":"lifted upwards","cn":"举起的；扬起的","ex":{"en":"She strode towards them, her fist upraised.","cn":"她举着拳头，大步迈向他们。"}}]}},"uncompromising":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不妥协的；不让步的；坚定的","en":"If you describe someone as uncompromising, you mean that they are determined not to change their opinions or aims in any way.","ex":{"en":"Mrs Thatcher was a tough and uncompromising politician.","cn":"撒切尔夫人是一位态度强硬、不轻易妥协的政治家。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不折不扣的；十足的","en":"If you describe something as uncompromising, you mean that it does not attempt to make something that is shocking or unpleasant any more acceptable to people.","ex":{"en":"...a film of uncompromising brutality.","cn":"极度血腥的影片"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who is determined works very hard to achieve what they want to achieve, and will not let problems stop them","cn":""},{"en":"someone who is single-minded works very hard in order to achieve one particular thing, and thinks that everything else is much less important","cn":""},{"en":"always very determined to do what you want to do, even if other people think it is not a good idea to do it","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/a/uncompromising0205.mp3","us":"media/ldoce/hwd/ame/9/uncompromising.mp3"},"examples":[{"en":"He has a reputation for being tough and uncompromising.","cn":"他的严厉和强硬态度是出了名的。"},{"en":"an uncompromising attitude","cn":"强硬的态度"}],"oxford":{"phon":"ʌnˈkɒmprəmaɪzɪŋ","pos":"adjective","senses":[{"en":"unwilling to change your opinions or behaviour","cn":"不让步的；不妥协的；强硬的","ex":{"en":"an uncompromising attitude","cn":"强硬的态度"}}]}},"uneasy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"焦虑的；不安的；心神不定的；不自在的","en":"If you are uneasy, you feel anxious, afraid, or embarrassed, because you think that something is wrong or that there is danger.","ex":{"en":"He said nothing but gave me a sly grin that made me feel terribly uneasy","cn":"他什么也没说，只是朝我狡黠地笑了笑，这让我感到极其不安。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不确定的；无把握的","en":"If you are uneasy about doing something, you are not sure that it is correct or wise.","ex":{"en":"Richard was uneasy about how best to approach his elderly mother","cn":"最好如何去跟年迈的母亲谈，理查德心里没有数。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（局势或关系）不稳定的，动荡的","en":"If you describe a situation or relationship as uneasy, you mean that the situation is not settled and may not last.","ex":{"en":"An uneasy calm has settled over Los Angeles","cn":"洛杉矶归于一种不稳定的平静之中。"}},{"pos":"ADJ 形容词","cn":"（书或音乐）难懂的，晦涩的","en":"If you describe a book or music as uneasy, you are critical of it because it is difficult to read or listen to.","ex":{"en":"'Rid Of Me' is harrowing, uneasy listening","cn":"《弃我而去》这首歌非常伤感，听起来很晦涩。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"worried or a little frightened about something and unable to relax","cn":""},{"en":"worried and unable to relax in a way that makes you get angry or upset easily","cn":""},{"en":"nervous because you feel that something bad might happen, so that you are unable to relax until the danger has passed","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Uneasy describes an uncomfortable feeling. You might feel socially uneasy when dining with your girlfriend's parents if they don't like you very much. Your stomach may also feel uneasy at that same dinner and gurgle in an embarrassing way."}]},"collocations":{"phrases":["VERBS appear, be, feel, look, seem, sound | become, get, grow We were starting to grow slightly uneasy. | remain | make sb","ADV. decidedly, deeply, distinctly, extremely, profoundly, very | increasingly | a bit, a little, rather, slightly, somewhat, vaguely | stra","PREP. about I felt distinctly uneasy about lending her so much money."]},"media":{"uk":"media/ldoce/hwd/bre/1/uneasy0205.mp3","us":"media/ldoce/hwd/ame/3/uneasy.mp3"},"examples":[{"en":"His socialist views sit uneasily with his huge fortune.","cn":"他拥有大量财富，这与他的社会主义观点格格不入。"},{"en":"Old farmhouses and new villas stood together in uneasy proximity.","cn":"破旧的农舍与崭新的别墅比肩而立，很不协调。"}],"oxford":{"phon":"ʌnˈiːzi","pos":"adjective","senses":[{"en":"feeling worried or unhappy about a particular situation, especially because you think that something bad or unpleasant may happen or because you are not sure that what you are doing is right","cn":"担心的；忧虑的；不安的","ex":{"en":"an uneasy laugh","cn":"不自然的大笑"}},{"en":"not certain to last; not safe or settled","cn":"不稳定的；靠不住的；不确定的","ex":{"en":"an uneasy peace","cn":"不会持久的和平"}},{"en":"that does not enable you to relax or feel comfortable","cn":"令人不安的；令人不舒服的；不安稳的","ex":{"en":"She woke from an uneasy sleep to find the house empty.","cn":"她睡得不安稳，醒来时发现屋子里空无一人。"}},{"en":"used to describe a mixture of two things, feelings, etc. that do not go well together","cn":"不和谐的；不协调的；矛盾的","ex":{"en":"an uneasy mix of humour and violence","cn":"幽默与暴力的矛盾组合"}}]}},"unproven":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未被证实的","en":"If something is unproven, it has not definitely been proved to be true.","ex":{"en":"There are a lot of unproven allegations flying around.","cn":"流言蜚语满天飞。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not proved or tested","cn":"未经证实的﹔未经检验的"}]},"media":{"uk":"media/ldoce/hwd/bre/8/unproven0205.mp3","us":"media/ldoce/hwd/ame/8/laadunproven.mp3"},"examples":[{"en":"unproven theories","cn":"未证实的理论"},{"en":"unproven allegations","cn":"未经证实的指控"}],"oxford":{"phon":"ˌʌnˈpruːvn","pos":"adjective","senses":[{"en":"not proved or tested","cn":"未验证的；未经检验的","ex":{"en":"unproven theories","cn":"未证实的理论"}}]}},"unfavourable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(条件或环境)不利的，恶劣的","en":"Unfavourable conditions or circumstances cause problems for you and reduce your chances of success.","ex":{"en":"Unfavourable economic conditions were blocking a recovery of the American insurance market","cn":"不利的经济形势阻碍着美国保险市场的复苏。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（反应）反对的，不赞同的","en":"If you have an unfavourable reaction to something, you do not like it.","ex":{"en":"A more unfavourable response was given today by the Prime Minister","cn":"首相今天的回应更是表示反对。"}},{"pos":"ADJ 形容词","cn":"（比较）使相形见绌的","en":"If you make an unfavourable comparison between two things, you say that one thing seems worse than the other.","ex":{"en":"He makes unfavourable comparisons between British and French cooking","cn":"他认为与法国菜相比，英国菜相形见绌。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not good","cn":""},{"en":"not as good as it could be or should be","cn":""},{"en":"not good – often used instead of saying directly that something was ‘bad’, especially when you were disappointed by it","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/f/brelasdeunfavourable.mp3","us":"media/ldoce/hwd/ame/d/unfavorable.mp3"},"examples":[{"en":"The documentary presents him in a very unfavourable light.","cn":"这部纪录片从十分负面的角度来描绘他。"},{"en":"In this respect, Britain compares unfavourably with other European countries.","cn":"在这方面，英国比欧洲其他各国要逊色。"}],"oxford":{"phon":"ʌnˈfeɪvərəbl","pos":"adjective","senses":[{"en":"not good and likely to cause problems or make something more difficult","cn":"不利的；有害的","ex":{"en":"The conditions were unfavourable for agriculture.","cn":"这些条件不利于农业。"}},{"en":"showing that you do not approve of or like somebody/something","cn":"不赞成的；否定的；不喜欢的","ex":{"en":"an unfavourable comment","cn":"负面的评论"}}]}},"uncork":{"collins":{"senses":[{"pos":"VERB 动词","cn":"拔去…的塞子；打开（瓶子）","en":"When you uncork a bottle, you open it by pulling the cork out of it.","ex":{"en":"Steve uncorked bottles of champagne to toast the achievement.","cn":"史蒂夫打开几瓶香槟酒庆功。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to open a bottle, box, or other container by removing or lifting its top or lid","cn":""},{"en":"to remove the top or lid of a bottle or container by turning it","cn":""},{"en":"to open a bottle of alcohol","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41uncork.mp3","us":"media/ldoce/hwd/ame/e/uncork.mp3"},"oxford":{"phon":"ˌʌnˈkɔːk","pos":"verb","senses":[{"en":"to open a bottle by removing the cork from the top","cn":"打开…的瓶塞"}]}},"unusable":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"无用的；不能用的","en":"Something that is unusable is not in a good enough state or condition to be used.","ex":{"en":"Bombing had made roads and railways unusable.","cn":"轰炸导致公路和铁路都无法通行。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"something that is unusable is in such a bad condition that you cannot use it 〔","cn":"太糟糕而〕不能使用的"}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41unusable.mp3","us":"media/ldoce/hwd/ame/3/ld41unusable.mp3"},"oxford":{"phon":"ˌʌnˈjuːzəbl","pos":"adjective","senses":[{"en":"in such a bad condition or of such low quality that it cannot be used","cn":"（破得或差得）不能使用的；破烂不堪的","ex":{"en":"The damage rendered the building unusable.","cn":"这次破坏使得这栋建筑已无法使用。"}}]}},"uncritical":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(人或行为)不加辨别的，不加批判的","en":"If you describe a person or their behaviour as uncritical, you mean that they do not judge whether someone or something is good or bad, right or wrong, before supporting or believing them.","ex":{"en":"...the conventional notion of women as uncritical purchasers of heavily advertised products.","cn":"认为女人会不加辨别地购买那些大做广告的产品的传统观点"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"unable or unwilling to see faults in something or someone – used to show disapproval","cn":"无鉴别力的，不加批评的〔含贬义〕"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41uncritical.mp3","us":"media/ldoce/hwd/ame/2/uncritical.mp3"},"examples":[{"en":"Her uncritical acceptance of everything I said began to irritate me.","cn":"我说什么她都不论对错一概接受，这倒惹我不耐烦起来。"},{"en":"John’s mother is totally uncritical of his behaviour.","cn":"约翰的母亲对他的行为完全不加批评。"}],"oxford":{"phon":"ˌʌnˈkrɪtɪkl","pos":"adjective","senses":[{"en":"not willing to criticize somebody/something or to judge whether somebody/something is right or wrong","cn":"不愿批评的；不置可否的；不得罪人的","ex":{"en":"Her uncritical acceptance of everything I said began to irritate me.","cn":"我说什么她都不论对错一概接受，这倒惹我不耐烦起来。"}}]}},"untoward":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"横生枝节的;意外的","en":"If you say that something untoward happens, you mean that something happens that is unexpected and causes difficulties.","ex":{"en":"The surveyor's report didn't highlight anything untoward","cn":"勘测员的报告没有指明有任何麻烦问题。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"unexpected, unusual, or not wanted","cn":"意外的﹔异常的﹔事与愿违的"}]},"vocab":{"pos":"adj","senses":[{"en":"The adjective untoward describes something offensive or inappropriate, like the rumors of untoward behavior that can shatter a Hollywood icon's reputation."}]},"media":{"uk":"media/ldoce/hwd/bre/c/untoward0205.mp3","us":"media/ldoce/hwd/ame/b/untoward.mp3"},"examples":[{"en":"That's the plan — unless anything untoward happens.","cn":"计划就这么定了，除非出现异常情况。"},{"en":"He had noticed nothing untoward.","cn":"他没有注意到有何特殊情况。"}],"oxford":{"phon":"ˌʌntəˈwɔːd","pos":"adjective","senses":[{"en":"unusual and unexpected, and usually unpleasant","cn":"异常的；意外的；不幸的；棘手的","ex":{"en":"That's the plan—unless anything untoward happens.","cn":"计划就这么定了，除非出现异常情况。"}}]}},"unrepentant":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"不思悔改的；不悔悟的；不知羞耻的","en":"If you are unrepentant, you are not ashamed of your beliefs or actions.","ex":{"en":"Pamela was unrepentant about her strong language and abrasive remarks.","cn":"帕梅拉对自己那些脏话和伤人的言辞一点也不感到羞愧。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who is shameless or whose behaviour is shameless does not seem to feel ashamed about something that most people would be very ashamed about","cn":""},{"en":"not feeling embarrassed or ashamed about something that most people disapprove of or consider silly","cn":""},{"en":"not feeling embarrassed or ashamed about something that people might disapprove of","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/7/brelasdeunrepentant.mp3","us":"media/ldoce/hwd/ame/2/laadunrepentant.mp3"},"examples":[{"en":"He remains unrepentant about his comments.","cn":"他对自己的这番话毫无悔意。"}],"oxford":{"phon":"ˌʌnrɪˈpentənt","pos":"adjective","senses":[{"en":"showing no shame about your actions or beliefs","cn":"不思悔改的；不悔悟的；顽固不化的","ex":{"en":"She was cheerfully unrepentant about her part in the deception.","cn":"她很高兴地对自己在欺骗中所扮演的角色毫不悔改。"}}]}},"undercurrent":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(情感的)潜流，暗流","en":"If there is an undercurrent of a feeling, you are hardly aware of the feeling, but it influences the way you think or behave.","ex":{"en":"...a deep undercurrent of racism in British society.","cn":"英国社会中强劲的种族主义暗流"}},{"pos":"N-COUNT 可数名词","cn":"(水流的)潜流；暗流","en":"An undercurrent is a strong current of water that is moving below the surface current and in a different direction to it.","ex":{"en":"Colin tried to swim after him but the strong undercurrent swept them apart.","cn":"科林想跟在他后面游，但强大的暗流把他们分开了。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a feeling, especially of anger or dissatisfaction, that people do not express openly","cn":"暗流﹐潜伏的情绪〔尤指愤怒或不满〕"},{"en":"a hidden and often dangerous current of water that flows under the surface of the sea or a river 〔","cn":"海或河中的〕暗流"}]},"media":{"uk":"media/ldoce/hwd/bre/4/undercurrent0205.mp3","us":"media/ldoce/hwd/ame/9/undercurrent.mp3"},"examples":[{"en":"I detect an undercurrent of resentment towards the new proposals.","cn":"我察觉到对新提案有一股潜在的不满情绪。"},{"en":"He sensed an undercurrent of resentment among the crowd.","cn":"他觉察出人群中有一股暗藏的不满情绪。"}],"oxford":{"phon":"ˈʌndəkʌrənt","pos":"noun","senses":[{"en":"a feeling, especially a negative one, that is hidden but whose effects are felt","cn":"潜在的情绪（尤指负面的）","ex":{"en":"I detect an undercurrent of resentment towards the new proposals.","cn":"我察觉到对新提案有一股潜在的不满情绪。"}}]}},"unprepared":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无准备的；没有预料的；措手不及的；没防备的","en":"If you are unprepared for something, you are not ready for it, and you are therefore surprised or at a disadvantage when it happens.","ex":{"en":"I was totally unprepared for the announcement on the next day","cn":"我对第二天的通告完全没有心理准备。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不乐意的；不情愿的","en":"If you are unprepared to do something, you are not willing to do it.","ex":{"en":"They are unprepared to accept the real reasons for their domestic and foreign situation","cn":"他们不愿意接受造成这种国内外形势的真实原因。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if you are not ready for something, you have not done everything that needs to be done in order to prepare for it","cn":""},{"en":"not ready to deal with something because you were not expecting it, and have not thought about it or made plans","cn":""},{"en":"not ready to deal with something","cn":"无准备的"}]},"media":{"uk":"media/ldoce/hwd/bre/6/unprepared0205.mp3","us":"media/ldoce/hwd/ame/e/laadunprepared.mp3"},"examples":[{"en":"She was unprepared to accept that her marriage was over.","cn":"她不愿相信她的婚姻已经结束。"},{"en":"She was totally unprepared for his response.","cn":"她对他的反应毫无准备。"}],"oxford":{"phon":"ˌʌnprɪˈpeəd","pos":"adjective","senses":[{"en":"not ready or not expecting something","cn":"无准备的；没有预料的；无防备的","ex":{"en":"She was totally unprepared for his response.","cn":"她对他的反应毫无准备。"}},{"en":"not willing to do something","cn":"不乐意的；不情愿的；不甘心的","lab":"formal","ex":{"en":"She was unprepared to accept that her marriage was over.","cn":"她不愿相信她的婚姻已经结束。"}}]}},"unshaken":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（信仰）坚定的，不动摇的","en":"If your beliefs are unshaken, you still have those beliefs, although they have been attacked or challenged.","ex":{"en":"His faith that men such as the Reverend John Leale tried to do their best is unshaken.","cn":"他始终深信约翰·莱亚莱神父等人已经尽了全力了。"}},{"pos":"ADJ 形容词","cn":"(情感上)不为所动的，不受影响的","en":"If you are unshaken by something, you are not emotionally affected by it.","ex":{"en":"Mona remains unshaken by her ordeal and is matter-of-fact about her courage.","cn":"莫娜不为她经历的这场磨难所动，对自己表现出的勇气也态度淡然。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not having changed your attitude or belief 〔","cn":"态度或信念〕坚定的﹐未动摇的"}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41unshaken.mp3","us":"media/ldoce/hwd/ame/b/ld41unshaken.mp3"},"examples":[{"en":"They remain unshaken in their loyalty.","cn":"他们仍然忠贞不渝。"},{"en":"He remained unshaken in his belief that she was wrong.","cn":"他依然坚持认为她错了。"}],"oxford":{"phon":"ˌʌnˈʃeɪkən","pos":"adjective","senses":[{"en":"not having changed a particular feeling or attitude","cn":"坚定的；未动摇的","ex":{"en":"They remain unshaken in their loyalty.","cn":"他们仍然忠贞不渝。"}}]}},"unattended":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"无人照料的；无人看管的","en":"When people or things are left unattended, they are not being watched or looked after.","ex":{"en":"Never leave young children unattended near any pool or water tank","cn":"千万不能放任小孩呆在水池或水槽附近不管。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"left alone without anyone in charge","cn":"无人照看的﹐无人看管的"}]},"media":{"uk":"media/ldoce/hwd/bre/c/unattended0205.mp3","us":"media/ldoce/hwd/ame/f/unattended.mp3"},"examples":[{"en":"Never leave young children unattended.","cn":"对幼儿切不可疏于看管。"},{"en":"unattended vehicles","cn":"无人看管的车辆"}],"oxford":{"phon":"ˌʌnəˈtendɪd","pos":"adjective","senses":[{"en":"without the owner present; not being watched or cared for","cn":"主人不在场的；无人看管（或照料）的","ex":{"en":"unattended vehicles","cn":"无人看管的车辆"}}]}},"unnamed":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未披露姓名的；不知姓名的","en":"Unnamed people or things are talked about but their names are not mentioned.","ex":{"en":"An unnamed man collapsed and died while he was walking near Dundonald","cn":"一个不知姓名的人在邓唐纳德附近走着走着突然倒地而亡。"}},{"pos":"ADJ 形容词","cn":"没有名字的；未被命名的","en":"Unnamed things have not been given a name.","ex":{"en":"...unnamed comets and asteroids.","cn":"未命名的彗星和小行星"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who is anonymous does something without saying what their name is, or their name is not known","cn":""},{"en":"an unnamed person is someone whose name has not been made known publicly","cn":""},{"en":"an unidentified person is someone whose name is not known because police or government officials have been unable to find out who they are, or have not said who they are","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/9/brelasdeunnamed.mp3","us":"media/ldoce/hwd/ame/b/laadunnamed.mp3"},"examples":[{"en":"Two casualties, as yet unnamed, are still in the local hospital.","cn":"两个尚不知姓名的伤者仍在当地医院。"},{"en":"information from an unnamed source","cn":"不愿透露姓名的人提供的消息"}],"oxford":{"phon":"ˌʌnˈneɪmd","pos":"adjective","senses":[{"en":"whose name is not given or not known","cn":"未披露姓名的；不知姓名的","ex":{"en":"information from an unnamed source","cn":"不愿透露姓名的人提供的消息"}}]}},"ultrasonic":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"超声波的","en":"Ultrasonic sounds have very high frequencies, which human beings cannot hear."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"ultrasonic sound waves are too high for humans to hear 〔","cn":"声波〕超声的"}]},"media":{"uk":"media/ldoce/hwd/bre/3/ultrasonic0205.mp3","us":"media/ldoce/hwd/ame/2/ultrasonic.mp3"},"examples":[{"en":"ultrasonic waves","cn":"超声波"}],"oxford":{"phon":"ˌʌltrəˈsɒnɪk","pos":"adjective","senses":[{"en":"higher than humans can hear","cn":"超声的","ex":{"en":"ultrasonic waves","cn":"超声波"}}]}},"urchin":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"肮脏而衣着破烂的儿童；小乞丐","en":"An urchin is a young child who is dirty and poorly dressed.","ex":{"en":"We were in the bazaar with all the little urchins watching us.","cn":"我们在集市里，周围一大帮衣衫褴褛的小孩盯着我们看。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a poor dirty untidy child","cn":"贫穷肮脏的小孩"}]},"vocab":{"pos":"n","senses":[{"en":"That young child, dressed in dirty hand-me-downs and running rampant through city streets, is an urchin . Street urchins , as they are commonly called, have a reputation for getting into trouble."}]},"media":{"uk":"media/ldoce/hwd/bre/9/urchin0205.mp3","us":"media/ldoce/hwd/ame/2/urchin.mp3"},"examples":[{"en":"a dirty little street urchin","cn":"肮脏的街头小乞丐"}],"oxford":{"phon":"ˈɜːtʃɪn","pos":"noun","senses":[{"en":"a young child who is poor and dirty, often one who has no home","cn":"贫穷肮脏的儿童；流浪儿","lab":"old-fashioned","ex":{"en":"a dirty little street urchin","cn":"肮脏的街头小乞丐"}},{"en":"a small sea creature with a round shell that is covered with spikes","cn":"海胆"}]}},"underdog":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（竞争、竞赛等中的）劣势方，弱者","en":"The underdog in a competition or situation is the person who seems least likely to succeed or win.","ex":{"en":"Most of the crowd were cheering for the underdog to win just this one time.","cn":"人群里的大多数人都在为劣势一方鼓劲，希望他哪怕就赢这一次。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a person, team etc that is weaker than the others, is always expected to be unsuccessful, and that is often treated badly","cn":"处于劣势的人[队]﹔弱者﹐弱方"}]},"media":{"uk":"media/ldoce/hwd/bre/6/underdog0205.mp3","us":"media/ldoce/hwd/ame/e/underdog.mp3"},"examples":[{"en":"In politics, he was a champion of the underdog (= always fought for the rights of weaker people).","cn":"在政治上，他总是为弱势群体争取权益。"},{"en":"Before the game we were definitely the underdogs.","cn":"我们在赛前绝对不被看好。"}],"oxford":{"phon":"ˈʌndədɒɡ","pos":"noun","senses":[{"en":"a person, team, country, etc. that is thought to be in a weaker position than others and therefore not likely to be successful, win a competition, etc.","cn":"处于劣势的人（或团队、国家等）；弱者；比赛前不被看好者","ex":{"en":"Before the game we were definitely the underdogs.","cn":"我们在赛前绝对不被看好。"}}]}},"urinary":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"泌尿的；泌尿器官的","en":"Urinary means belonging to or related to the parts of a person's body through which urine flows.","ex":{"en":"...urinary tract infections.","cn":"尿道感染"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"relating to urine or the parts of your body through which urine passes","cn":"尿的﹔泌尿器官的"}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41urinary.mp3","us":"media/ldoce/hwd/ame/6/urinary.mp3"},"examples":[{"en":"the urinary tract","cn":"尿道"}],"oxford":{"phon":"ˈjʊərɪnəri","pos":"adjective","senses":[{"en":"connected with urine or the parts of the body through which it passes","cn":"尿的；泌尿的；尿路的","ex":{"en":"a urinary infection","cn":"尿路感染"}}]}},"unequivocal":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"毫不含糊的；清楚明白的","en":"If you describe someone's attitude as unequivocal, you mean that it is completely clear and very firm.","ex":{"en":"...Richardson's unequivocal commitment to fair play","cn":"理查森对公平竞争的明确承诺"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"language, instructions etc that are plain are easy to understand because there is nothing difficult or unnecessary in them that might be confusing","cn":""},{"en":"having only one possible meaning and therefore clear","cn":""},{"en":"expressed very clearly and including every detail, so that no part of your meaning is hidden","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"If there is no doubt about it, it's unequivocal . An unequivocal response to a marriage proposal? \"Yes. Yes! A thousand times yes!\""}]},"media":{"uk":"media/ldoce/hwd/bre/0/unequivocal0205.mp3","us":"media/ldoce/hwd/ame/2/unequivocal.mp3"},"examples":[{"en":"The answer was an unequivocal ‘no’.","cn":"回答是个干脆利落的“不”字。"},{"en":"an unequivocal rejection","cn":"明确的拒绝"}],"oxford":{"phon":"ˌʌnɪˈkwɪvəkl","pos":"adjective","senses":[{"en":"expressing your opinion or intention very clearly and strongly","cn":"表达明确的；毫不含糊的；斩钉截铁的","ex":{"en":"an unequivocal rejection","cn":"明确的拒绝"}}]}},"upholder":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"拥护者;支持者;赞成者","en":"An upholder of a particular tradition or system is someone who believes strongly in it and will support it when it is threatened.","ex":{"en":"...upholders of the traditional family unit.","cn":"传统家庭形式的拥护者"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if a parliament or similar group passes a law or proposal, the members vote to accept it","cn":""},{"en":"to officially accept something that has been planned to happen","cn":""},{"en":"to officially agree to accept an agreement that someone else has already agreed to accept","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/f/uphold0205.mp3","us":"media/ldoce/hwd/ame/8/uphold.mp3"},"examples":[{"en":"an upholder of traditional values","cn":"支持传统价值观的人"},{"en":"a committee that aims to uphold educational standards","cn":""}],"oxford":{"phon":"ʌpˈhəʊldə(r)","pos":"noun","senses":[{"en":"a person who supports something that they think is right and makes sure that it continues to exist","cn":"支持，维护（正义等）","ex":{"en":"an upholder of traditional values","cn":"维护传统价值观的人"}}]}},"unreadable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"没有可读性的；不值得一读的","en":"If you use unreadable to describe a book or other piece of writing, you are criticizing it because it is very boring, complicated, or difficult to understand.","ex":{"en":"For some this is the greatest novel in the world. For others it is unreadable","cn":"对于一些人来说这是世界上最伟大的小说，但对于另一些人来说，它不值得一读。"}},{"pos":"ADJ 形容词","cn":"难以辨认的；模糊不清的","en":"If a piece of writing is unreadable, it is impossible to read because the letters are unclear, especially because it has been damaged in some way.","ex":{"en":"...if contracts are unreadable because of the microscopic print","cn":"如果合同因为字体太小而无法阅读的话"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（表情）难以捉摸的，难以猜测的","en":"If someone's face or expression is unreadable, it is impossible to tell what they are thinking or feeling.","ex":{"en":"He looked back at the woman for approval, but her face was unreadable.","cn":"他回头看那个女人以求得到赞许，但是她的表情让人读不懂。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"use this to say that you are unable to read someone's writing","cn":""},{"en":"use this to say that you are unable to read a particular word because it is not written clearly","cn":""},{"en":"writing that is illegible is impossible to read because it is not written clearly","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41unreadable.mp3","us":"media/ldoce/hwd/ame/f/unreadable.mp3"},"oxford":{"phon":"ʌnˈriːdəbl","pos":"adjective","senses":[{"en":"too boring or difficult to be worth reading","cn":"（因枯燥晦涩而）不值一读的，难以卒读的"},{"en":"difficult or impossible to read","cn":"难以辨认的；无法辨识的；字迹模糊的"},{"en":"if somebody’s face or expression is unreadable, you cannot tell what they are thinking or feeling","cn":"（面部表情）揣摩不透的，难以捉摸的","ex":{"en":"Ed regarded her with an unreadable expression.","cn":"艾德用一种难以理解的表情看着她。"}},{"en":"containing information that a computer is not able to read","cn":"无法读取的；打不开的","lab":"computing"}]}},"unprincipled":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"没原则的；不道德的","en":"If you describe a person or their actions as unprincipled, you are criticizing them for their lack of moral principles and because they do things which are immoral or dishonest.","ex":{"en":"It is a market where people can be very unprincipled and unpleasant.","cn":"在这个市场里，一些人可能根本不讲道德原则，非常令人厌恶。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not caring whether what you do is morally right","cn":"无原则的﹐不讲道德的﹐不择手段的"}]},"vocab":{"pos":"adj","senses":[{"en":"An unprincipled person follows no moral code, has no integrity, and should not be trusted, like the guy who offers to help an old lady across the street but steals her purse instead."}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41unprincipled.mp3","us":"media/ldoce/hwd/ame/5/unprincipled.mp3"},"oxford":{"phon":"ʌnˈprɪnsəpld","pos":"adjective","senses":[{"en":"without moral principles","cn":"不道德的","ex":{"en":"She saw him as an unprincipled opportunist.","cn":"她认为他是一个不道德的投机分子。"}}]}},"unwieldy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"沉甸甸的；粗笨的；笨重的","en":"If you describe an object as unwieldy, you mean that it is difficult to move or carry because it is so big or heavy.","ex":{"en":"They came panting up to his door with their unwieldy baggage.","cn":"他们提着笨重的行李气喘吁吁地来到他门口。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"臃肿的；庞大的","en":"If you describe a system as unwieldy, you mean that it does not work very well as a result of it being too large or badly organized.","ex":{"en":"His firm must contend with the unwieldy Russian bureaucracy.","cn":"他的公司必须与俄罗斯庞大的官僚机构周旋。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"an unwieldy object is big, heavy, and difficult to carry or use 〔","cn":"物体〕庞大而笨重的﹐不灵便的"},{"en":"an unwieldy system, argument, or organization is difficult to control or manage because it is too complicated 〔","cn":"因太复杂而〕难操纵的﹐难控制的"}]},"vocab":{"pos":"adj","senses":[{"en":"If you see an unwieldy person coming down the aisle of the bus with an unwieldy box, you may want to step aside because that's a double dose of clumsy. It's an awkward person carrying a box that is difficult to manage."}]},"media":{"uk":"media/ldoce/hwd/bre/8/unwieldy0205.mp3","us":"media/ldoce/hwd/ame/3/unwieldy.mp3"},"examples":[{"en":"unwieldy bureaucracy","cn":"尾大不掉的官僚机构"}],"oxford":{"phon":"ʌnˈwiːldi","pos":"adjective","senses":[{"en":"difficult to move or control because of its size, shape or weight","cn":"笨重的；笨拙的；不灵巧的","ex":{"en":"The first mechanical clocks were large and rather unwieldy.","cn":"第一个机械钟很大而且相当笨重。"}},{"en":"difficult to control or organize because it is very large or complicated","cn":"难控制（或操纵、管理）的；运转不灵的；尾大不掉的"}]}},"undress":{"collins":{"senses":[{"pos":"VERB 动词","cn":"脱衣服；脱去…的衣服","en":"When you undress or undress someone, you take off your clothes or someone else's clothes. →see usage note at:","ex":{"en":"She went out, leaving Rachel to undress and have her shower","cn":"她出去了，留下雷切尔一个人除衣淋浴。"}},{"pos":"PHRASE 短语","cn":"一丝不挂；赤身裸体","en":"If someone is in a state of undress, they do not have all their clothes on.","ex":{"en":"Every cover showed a woman in a state of undress.","cn":"每个封面上都有一名裸体女子。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to take off all your clothes, especially before going to bed. Get undressed is the usual phrase to use in everyday English","cn":""},{"en":"to remove a piece of clothing. Remove is more formal than take off","cn":""},{"en":"to take off all or some of your clothes – used especially when you do this quickly, when someone has ordered you to do it, or in a way that is deliberately sexually exciting","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/7/undress_v0205.mp3","us":"media/ldoce/hwd/ame/d/undress1.mp3"},"examples":[{"en":"He got undressed in a small cubicle next to the pool.","cn":"他在游泳池旁的小更衣室里脱掉了衣服。"},{"en":"He appeared at the window in a state of undress.","cn":"他光着身子出现在窗前。"}],"oxford":{"phon":"ʌnˈdres","pos":"verb","senses":[{"en":"to take off your clothes; to remove somebody else’s clothes","cn":"（给…）脱衣服","ex":{"en":"She undressed and got into bed.","cn":"她解衣上床了。"}},{"en":"the fact of somebody wearing no, or few, clothes","cn":"裸体；赤身","ex":{"en":"He appeared at the window in a state of undress.","cn":"他光着身子出现在窗前。"},"pos":"noun"}]}},"unheard-of":{"collocations":{"phrases":["VERBS be","ADV. absolutely, completely, quite, totally At that time, it was completely unheard-of for girls to go to university. | by no means | almost"]},"examples":[{"en":"He'd dyed his hair, which was almost unheard-of in the 1960s.","cn":"他染了头发，这在 20 世纪 60 年代是罕见的事。"},{"en":"It is almost unheard-of for a new band to be offered such a deal.","cn":"一支新乐队得到这样的待遇，几乎是空前的。"}],"oxford":{"phon":"ʌnˈhɜːd əv","pos":"adjective","senses":[{"en":"that has never been known or done; very unusual","cn":"前所未闻的；空前的；很反常的","ex":{"en":"He'd dyed his hair, which was almost unheard-of in the 1960s.","cn":"他染了头发，这在 20 世纪 60 年代是罕见的事。"}}]}},"ultramarine":{"collins":{"senses":[{"pos":"COLOUR 颜色词","cn":"佛青色（的）；湛蓝色（的）","en":"Ultramarine is used to describe things that are very bright blue in colour.","ex":{"en":"...an ultramarine sky.","cn":"湛蓝的天空"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a very bright blue colour","cn":"钢青色﹐铁青色"}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41ultramarine.mp3","us":"media/ldoce/hwd/ame/5/ultramarine.mp3"},"oxford":{"phon":"ˌʌltrəməˈriːn","pos":"noun","senses":[{"en":"a bright blue colour","cn":"群青色；佛青色"}]}},"undernourished":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"营养不足的；营养不良的","en":"If someone is undernourished, they are weak and unhealthy because they have not been eating enough food or the right kind of food.","ex":{"en":"People who are undernourished also lack reserves of energy when faced with physical or mental crises.","cn":"营养不良的人在体力或脑力上出现紧急情况时还缺乏足够的能量储备。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"unhealthy and weak because you have not had enough food or the right type of food","cn":"营养不足的"}]},"media":{"uk":"media/ldoce/hwd/bre/c/undernourished0205.mp3","us":"media/ldoce/hwd/ame/7/undernourished.mp3"},"examples":[{"en":"severely undernourished children","cn":"严重营养不良的儿童"}],"oxford":{"phon":"ˌʌndəˈnʌrɪʃt","pos":"adjective","senses":[{"en":"in bad health because of a lack of food or a lack of the right type of food","cn":"营养不良的；缺乏营养的","ex":{"en":"severely undernourished children","cn":"严重营养不良的儿童"}}]}},"upholsterer":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"椅套工；座套工","en":"An upholsterer is someone whose job is to make and fit the soft covering on chairs and seats."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone whose job is to cover chairs with material","cn":"座椅套垫装饰工"}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41upholsterer.mp3","us":"media/ldoce/hwd/ame/5/ld41upholsterer.mp3"},"oxford":{"phon":"ʌpˈhəʊlstərə(r)","pos":"noun","senses":[{"en":"a person whose job is to upholster furniture","cn":"家具装饰商"}]}},"usurper":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"篡夺者；篡位者；侵占者","en":"A usurper is someone who takes another person's title or position when they have no right to."}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to take someone else’s power, position, job etc when you do not have the right to","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A usurper is someone who wrongfully takes someone else's place. A usurper usually tries to take someone's place on the throne, rather than someone's seat on a bus."}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld44usurp.mp3","us":"media/ldoce/hwd/ame/1/usurp.mp3"},"examples":[{"en":"There were a couple of attempts to usurp the young king.","cn":""}],"oxford":{"phon":"juːˈzɜːpə(r)","pos":"noun","senses":[{"en":"a person who takes somebody's position and/or power without having the right to do this","cn":"篡夺；侵权","ex":{"en":"the usurper of the throne","cn":"篡位者"}}]}},"unworldly":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不练达的；不谙世故的；不老练的","en":"If you describe someone as unworldly, you mean that they have not experienced many things in their life and do not know what sort of things usually happen to other people during their lives.","ex":{"en":"She was so young, so unworldly","cn":"她太年轻，太不懂人情世故。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"淡泊的；恬淡的","en":"If you describe someone as unworldly, you mean that they are not interested in having a lot of money or possessions.","ex":{"en":"Kitty's family was unworldly, unimpressed by power, or money.","cn":"基蒂一家清心寡欲，淡泊金钱与权力。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not interested in money or possessions","cn":"对钱财不感兴趣的﹔脱俗的"},{"en":"not having a lot of experience of life","cn":"不谙世故的﹐天真的"},{"en":"unusual and having qualities that do not seem to belong to this world","cn":"非尘世的﹐非现世的﹐超凡的"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41unworldly.mp3","us":"media/ldoce/hwd/ame/9/unworldly.mp3"},"examples":[{"en":"The landscape had a stark, unworldly beauty.","cn":"那景色有一种简朴、超凡的美。"},{"en":"unworldly beauty","cn":"超凡的美"}],"oxford":{"phon":"ʌnˈwɜːldli","pos":"adjective","senses":[{"en":"not interested in money or the things that it buys","cn":"不慕金钱的；对钱财无兴趣的"},{"en":"having little experience of life","cn":"不谙世故的；天真的","ex":{"en":"She was young and hopelessly unworldly.","cn":"她很年轻，而且无可救药地不谙世事。"}},{"en":"having qualities that do not seem to belong to this world","cn":"非现世的；非尘世的；超凡的","ex":{"en":"The landscape had a stark, unworldly beauty.","cn":"那景色有一种简朴、超凡的美。"}}]}},"unerring":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"从不出错的；一贯正确的","en":"If you describe someone's judgment or ability as unerring, you mean that they are always correct and never mistaken.","ex":{"en":"These designs demonstrate her unerring eye for colour and detail","cn":"这些设计体现了她对颜色和细节的精准眼光。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"always right","cn":"一贯准确的﹐毫无偏差的"}]},"media":{"uk":"media/ldoce/hwd/bre/d/unerring0205.mp3","us":"media/ldoce/hwd/ame/d/unerring.mp3"},"examples":[{"en":"She had an unerring instinct for a good business deal.","cn":"她有天生擅长做生意的本事。"},{"en":"He passes the ball with unerring accuracy .","cn":"他的传球十分精准。"}],"oxford":{"phon":"ʌnˈɜːrɪŋ","pos":"adjective","senses":[{"en":"always right or accurate","cn":"万无一失的；一贯正确（或精确）的","ex":{"en":"She had an unerring instinct for a good business deal.","cn":"她有天生擅长做生意的本事。"}}]}},"undercut":{"collins":{"senses":[{"pos":"VERB 动词","cn":"压低(价格)；以低于…的价格销售","en":"If you undercut someone or undercut their prices, you sell a product more cheaply than they do.","ex":{"en":"The firm will be able to undercut its competitors whilst still making a profit.","cn":"该公司将得以把价格压得低于竞争对手而仍能盈利。"}},{"pos":"VERB 动词","cn":"削弱；破坏","en":"If your attempts to achieve something are undercut by something, that thing prevents your attempts from being effective.","ex":{"en":"The appeal in Miller's pictures of Indian women is undercut at times by what the artist writes about them","cn":"米勒画作中印第安妇女的魅力有时会被艺术家的文字描述削弱。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to sell goods or a service at a lower price than another company","cn":"以低于〔他人〕的价格出售"},{"en":"to make something weaker or less effective","cn":"削弱﹔使降低效率"}]},"media":{"uk":"media/ldoce/hwd/bre/2/undercut0205.mp3","us":"media/ldoce/hwd/ame/a/undercut.mp3"},"examples":[{"en":"We were able to undercut our European rivals by 5%.","cn":"我们能以低于我们的欧洲对手 5% 的价格出售。"},{"en":"Some members of the board were trying to undercut the chairman's authority.","cn":"委员会的某些成员试图削弱主席的权力。"}],"oxford":{"phon":"ˌʌndəˈkʌt","pos":"verb","senses":[{"en":"to sell goods or services at a lower price than your competitors","cn":"削价竞争；以低于（竞争对手）的价格出售","ex":{"en":"to undercut somebody’s prices","cn":"以低于对手的价格求售"}},{"en":"to make somebody/something weaker or less likely to be effective","cn":"削弱；使降低效力","ex":{"en":"Some members of the board were trying to undercut the chairman's authority.","cn":"委员会的某些成员试图削弱主席的权力。"}},{"en":"a way of cutting somebody’s hair in which the hair is left quite long on top but the hair on the lower part of the head is cut much shorter","cn":"大盖儿头发型；帽盔式发型；华盖式发型","pos":"noun"}]}},"undeniable":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"不可否认的；无可争议的；确凿无疑的","en":"If you say that something is undeniable, you mean that it is definitely true.","ex":{"en":"Her charm is undeniable.","cn":"她的魅力毋庸置疑。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"based on real facts, and not imagined or invented","cn":""},{"en":"based on facts and not containing any mistakes – used about descriptions, information, and numbers","cn":""},{"en":"definitely true, so that no one can argue or disagree about it","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Something undeniable is clearly true: it's undeniable that water is wet and the sky is blue."}]},"media":{"uk":"media/ldoce/hwd/bre/c/undeniable0205.mp3","us":"media/ldoce/hwd/ame/8/undeniable.mp3"},"examples":[{"en":"It is an undeniable fact that crime is increasing.","cn":"犯罪在增长是无可争辩的事实。"},{"en":"He had undeniable charm.","cn":"他具有不可否认的魅力。"}],"oxford":{"phon":"ˌʌndɪˈnaɪəbl","pos":"adjective","senses":[{"en":"true or certain; that cannot be denied","cn":"不可否认的；确凿的","ex":{"en":"He had undeniable charm.","cn":"他具有不可否认的魅力。"}}]}},"unrealistic":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不切实际的；不可能达成的","en":"If you say that someone is being unrealistic, you mean that they do not recognize the truth about a situation, especially about the difficulties involved in something they want to achieve.","ex":{"en":"There are many who feel that the players are being completely unrealistic in their demands","cn":"很多人都觉得这些球员的要求是完全不现实的。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"abstract paintings, pictures, designs etc contain shapes and images that represent real things and people but do not look like them","cn":""},{"en":"something that is unrealistic shows or describes things in a way that does not seem real, and is therefore not very good or cannot be believed","cn":""},{"en":"a story, situation etc that is contrived has been written or arranged in a way that seems false and not natural","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/8/brelasdeunrealistic.mp3","us":"media/ldoce/hwd/ame/3/laadunrealistic.mp3"},"examples":[{"en":"It is unrealistic to expect them to be able to solve the problem immediately.","cn":"指望他们能够立即解决问题是不现实的。"},{"en":"These prices are unrealistically high.","cn":"这些价格高得离谱。"}],"oxford":{"phon":"ˌʌnrɪəˈlɪstɪk","pos":"adjective","senses":[{"en":"not showing or accepting things as they are","cn":"不切实际的；不实事求是的","ex":{"en":"unrealistic expectations","cn":"不切实际的期望"}}]}},"unmarked":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"没有污渍的；没有污点的；没有疤痕的；没有斑点的","en":"Something that is unmarked has no marks on it.","ex":{"en":"Her shoes are still white and unmarked.","cn":"她的鞋仍然很白，没有任何污渍。"}},{"pos":"ADJ 形容词","cn":"没有标记的；没有标志的","en":"Something that is unmarked has no marking on it which identifies what it is or whose it is.","ex":{"en":"He had seen them come out and get into the unmarked police car","cn":"他看见他们走出来，上了一辆没有标志的警车。"}},{"pos":"ADJ 形容词","cn":"（球类比赛中）无人防守的，没被注意到的","en":"In a sport such as football, hockey, or basketball, if a player is unmarked, there are no players from the opposing team who are watching them in order to challenge them when they have control of the ball.","ex":{"en":"Sheringham was unmarked as he met Anderton's free kick and headed in after nine minutes.","cn":"9分钟后，谢林汉姆在无人防守的情况下接安德顿开出的任意球头球破门得分。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"something that is unmarked has no words or signs on it to show where or what it is","cn":"未做标记的﹔没有标志的"}]},"media":{"uk":"media/ldoce/hwd/bre/2/brelasdeunmarked.mp3","us":"media/ldoce/hwd/ame/a/laadunmarked.mp3"},"examples":[{"en":"He headed the ball to the unmarked Gray.","cn":"他把球顶给了无人盯防的格雷。"},{"en":"He was buried in an unmarked grave.","cn":"他埋在一处无名冢下。"}],"oxford":{"phon":"ˌʌnˈmɑːkt","pos":"adjective","senses":[{"en":"without a sign or words to show what or where something is","cn":"无标志的；无标记的；无记号的","ex":{"en":"an unmarked police car","cn":"无标识的警车"}},{"en":"with no player from the other team staying close to prevent them from getting the ball","cn":"无人盯防的","lab":"especially British English","ex":{"en":"He headed the ball to the unmarked Gray.","cn":"他把球顶给了无人盯防的格雷。"}},{"en":"not showing any particular feature or style, such as being formal or informal","cn":"无标记的","lab":"linguistics"}]}},"unarmed":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未携带武器的；未武装的；徒手的","en":"If a person or vehicle is unarmed, they are not carrying any weapons.","ex":{"en":"The soldiers concerned were unarmed at the time","cn":"涉及其中的士兵当时并未携带武器。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who is unarmed is not carrying a gun or other weapon","cn":""},{"en":"a person, place, ship etc that is defenceless has no weapons and cannot defend itself against an attack","cn":""},{"en":"not carrying any weapons","cn":"不带武器的﹐徒手的"}]},"media":{"uk":"media/ldoce/hwd/bre/c/unarmed0205.mp3","us":"media/ldoce/hwd/ame/b/unarmed.mp3"},"examples":[{"en":"The soldiers were trained in unarmed combat.","cn":"士兵接受徒手格斗训练。"},{"en":"unarmed civilians","cn":"没有武装的平民"}],"oxford":{"phon":"ˌʌnˈɑːmd","pos":"adjective","senses":[{"en":"not carrying a weapon","cn":"不带武器的；非武装的","ex":{"en":"unarmed civilians","cn":"没有武装的平民"}},{"en":"not involving the use of weapons","cn":"不使用武器的；徒手的","ex":{"en":"The soldiers were trained in unarmed combat.","cn":"士兵接受徒手格斗训练。"}}]}},"unappetizing":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"引不起食欲的；倒胃口的","en":"If you describe food as unappetizing, you think it will be unpleasant to eat because of its appearance.","ex":{"en":"...cold and unappetizing chicken.","cn":"让人没有一点食欲的冷冰冰的鸡肉"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"very bad - use this especially to talk about things that taste, smell, or look really bad","cn":""},{"en":"tasting or smelling horrible","cn":""},{"en":"a foul smell or taste is extremely bad, and is caused especially by waste or things decaying","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41unappetizing.mp3","us":"media/ldoce/hwd/ame/3/ld41unappetizing.mp3"},"examples":[{"en":"a rather unappetizing egg sandwich","cn":"倒胃口的鸡蛋三明治"}],"oxford":{"phon":"ʌnˈæpɪtaɪzɪŋ","pos":"adjective","senses":[{"en":"unpleasant to eat; looking as if it will be unpleasant to eat","cn":"难吃的；倒胃口的；看似难吃的","ex":{"en":"She brought me an unappetizing meal of cold fried eggs on toast.","cn":"她给我端来一份冷的煎蛋吐司，看上去就倒胃口。"}}]}},"unemotional":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不动感情的；无动于衷的；冷漠的；平静的","en":"If you describe someone as unemotional, you mean that they do not show any feelings.","ex":{"en":"British men are often seen as being reserved and unemotional","cn":"英国男人常被认为是矜持而冷漠的。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not showing your feelings","cn":"不流露感情的﹔不动声色的"},{"en":"not showing any feelings and especially not showing friendliness, humour, or pleasure","cn":""},{"en":"not showing the feelings that people usually show in an upsetting situation, because you have to do a job or because you really have no feelings about the situation","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/7/unemotional0205.mp3","us":"media/ldoce/hwd/ame/4/laadunemotional.mp3"},"examples":[{"en":"She seemed very cool and unemotional.","cn":"她显得十分冷静。"},{"en":"an unemotional speech","cn":"心平气和的讲话"}],"oxford":{"phon":"ˌʌnɪˈməʊʃənl","pos":"adjective","senses":[{"en":"not showing your feelings","cn":"不露感情的；不动声色的；平静的","ex":{"en":"an unemotional speech","cn":"心平气和的讲话"}}]}},"upkeep":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"维修；保养；养护","en":"The upkeep of a building or place is the work of keeping it in good condition.","ex":{"en":"The money will be used for the estate's upkeep","cn":"这笔钱将用于物业维护。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"赡养；供养；（公共事业的）维持","en":"The upkeep of a group of people or services is the process of providing them with the things that they need.","ex":{"en":"He offered to pay £100 a month towards his son's upkeep.","cn":"他愿意每月付100英镑作为儿子的抚养费。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to keep something in good condition and make sure that it does not get broken, damaged, or stolen","cn":""},{"en":"to look after something that belongs to someone else for a short time, by watching it to make sure that it does not get stolen or damaged","cn":""},{"en":"to make sure that a car, machine, place, or building is in good condition by checking it and repairing it when necessary","cn":""}]},"collocations":{"phrases":["VERB + UPKEEP contribute to, pay for Our taxes help pay for the upkeep of the city's parks. | afford","PHRASES responsible/responsibility for the upkeep of The local council is responsible for the upkeep of roads."]},"media":{"uk":"media/ldoce/hwd/bre/5/upkeep0205.mp3","us":"media/ldoce/hwd/ame/4/upkeep.mp3"},"examples":[{"en":"Tenants are responsible for the upkeep of rented property.","cn":"承租人应负责维修租用的房产。"},{"en":"He makes payments to his ex-wife for the upkeep of their children.","cn":"他向前妻支付子女的抚养费。"}],"oxford":{"phon":"ˈʌpkiːp","pos":"noun","senses":[{"en":"the cost or process of keeping something in good condition","cn":"保养（费）；维修（费）","ex":{"en":"Tenants are responsible for the upkeep of rented property.","cn":"承租人应负责维修租用的房产。"}},{"en":"the cost or process of giving a child or an animal the things that they need","cn":"抚养（费）；喂养（成本）","ex":{"en":"He makes payments to his ex-wife for the upkeep of their children.","cn":"他向前妻支付子女的抚养费。"}}]}},"unsophisticated":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"单纯的；不懂世故的；没经验的","en":"Unsophisticated people do not have a wide range of experience or knowledge and have simple tastes.","ex":{"en":"It was music of a rather crude kind which unsophisticated audiences enjoyed listening to","cn":"这是一种平民品味的听众喜欢听的简单粗糙的音乐形式。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"简单的；不精密的","en":"An unsophisticated method or device is very simple and often not very effective.","ex":{"en":"...an unsophisticated alarm system.","cn":"简单的报警系统"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"having very little experience of the world, especially because you are young so that you do not realize that some people might want to cause others harm","cn":""},{"en":"having little experience of life, so that you believe that life is simple and are too ready to trust people","cn":""},{"en":"having little knowledge or experience of clever, fashionable things, and showing this by the way you talk and behave","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/8/unsophisticate0205.mp3","us":"media/ldoce/hwd/ame/e/unsophisticated.mp3"},"examples":[{"en":"unsophisticated equipment","cn":"简单的基本设备"},{"en":"unsophisticated tastes","cn":"单纯的爱好"}],"oxford":{"phon":"ˌʌnsəˈfɪstɪkeɪtɪd","pos":"adjective","senses":[{"en":"not having or showing much experience of the world and social situations","cn":"单纯的；阅历浅的；涉世不深的；不谙世故的","ex":{"en":"unsophisticated tastes","cn":"单纯的爱好"}},{"en":"simple and basic; not complicated","cn":"基本的；简单的；不复杂的","ex":{"en":"unsophisticated equipment","cn":"简单的基本设备"}}]}},"unwanted":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不想要的；无人要的；多余的","en":"If you say that something or someone is unwanted, you mean that you do not want them, or that nobody wants them.","ex":{"en":"...the misery of unwanted pregnancies","cn":"意外怀孕的痛苦"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"something that is undesirable is not wanted because it could affect a person or situation in a bad way","cn":""},{"en":"use this about something that you are given or that happens to you that you do not want and did not ask for","cn":""},{"en":"likely to upset or cause problems for someone and therefore not wanted","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/4/brelasdeunwanted.mp3","us":"media/ldoce/hwd/ame/f/laadunwanted.mp3"},"examples":[{"en":"It is very sad when children feel unwanted (= feel that other people do not care about them).","cn":"小孩觉得没有人爱是很悲惨的。"},{"en":"unwanted advice","cn":"多余的劝告"}],"oxford":{"phon":"ˌʌnˈwɒntɪd","pos":"adjective","senses":[{"en":"that you do not want","cn":"不需要的；多余的；不受欢迎的","ex":{"en":"unwanted advice","cn":"多余的劝告"}}]}},"unsuspecting":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"不知情的；不知底细的；不明真相的","en":"You can use unsuspecting to describe someone who is not at all aware of something that is happening or going to happen.","ex":{"en":"The co-defendants are charged with selling worthless junk bonds to thousands of unsuspecting depositors.","cn":"此案的共同被告因向数千不明真相的存款人出售毫无价值的垃圾债券而被起诉。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not knowing that something bad is happening or going to happen","cn":"不怀疑的﹐无疑心的"}]},"media":{"uk":"media/ldoce/hwd/bre/7/unsuspecting0205.mp3","us":"media/ldoce/hwd/ame/6/laadunsuspecting.mp3"},"examples":[{"en":"He had crept up on his unsuspecting victim from behind.","cn":"他从背后悄悄逼近了那毫无戒备的受害者。"},{"en":"Fake designer clothes are being sold to an unsuspecting public.","cn":"有冒牌的设计师服装正在向毫不知情的大众出售。"}],"oxford":{"phon":"ˌʌnsəˈspektɪŋ","pos":"adjective","senses":[{"en":"not suspecting that anything is wrong; not aware of danger or of something bad","cn":"毫不怀疑的；无危险意识的；无戒备心的","ex":{"en":"He had crept up on his unsuspecting victim from behind.","cn":"他从背后悄悄逼近了那毫无戒备的受害者。"}}]}},"unheralded":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（艺术家、运动员等）被埋没的，怀才未遇的","en":"If you describe an artist or sports player as unheralded, you mean that people have not recognized their talent or ability.","ex":{"en":"They are inviting talented, but unheralded film-makers to submit examples of their work.","cn":"他们邀请有才气却尚未幸遇伯乐的电影制作人提交作品样本。"}},{"pos":"ADJ 形容词","cn":"出乎意料的；毫无先兆的","en":"If you describe something that happens as unheralded, you mean that you did not expect it, because nobody mentioned it beforehand.","ex":{"en":"...Sandi's unheralded arrival on her doorstep","cn":"桑迪出乎意料地出现在她门前"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if an event is unheralded, there is no warning that it is going to happen","cn":"没事先宣布的﹐未预告的"},{"en":"not known about or recognized as good","cn":"无名的﹔不被颂扬的"}]},"media":{"uk":"media/ldoce/hwd/bre/8/unheralded0205.mp3","us":"media/ldoce/hwd/ame/f/laadunheralded.mp3"},"examples":[{"en":"an unheralded visit from his aunt","cn":"他姨妈的突然到访"},{"en":"the unheralded members of the team","cn":"默默无闻的队员"}],"oxford":{"phon":"ʌnˈherəldɪd","pos":"adjective","senses":[{"en":"not previously mentioned; happening without any warning","cn":"未曾提及的；突如其来的；突然发生的","ex":{"en":"I didn’t want to make an unheralded entrance.","cn":"我不想悄无声息地进来。"}}]}},"uterine":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"子宫的","en":"Uterine means relating to the uterus of a woman or female mammal."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the organ in a woman or female mammal where babies develop","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/3/uterus0205.mp3","us":"media/ldoce/hwd/ame/f/uterus.mp3"},"oxford":{"phon":"ˈjuːtəraɪn","pos":"adjective","senses":[{"en":"connected with the uterus","cn":"子宫的"}]}},"usmc":{"collins":{"senses":[{"pos":"N-PROPER 专有名词","cn":"美国海军陆战队","en":"USMC is an abbreviation for (缩略=) United States Marine Corps ."}]},"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"( United States Marine Corps ) the full name of the marine corps","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld5_usmc.mp3","us":"media/ldoce/hwd/ame/8/p028-000012465.mp3"}},"unsound":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无根据的;似是而非的；谬误的","en":"If a conclusion or method is unsound, it is based on ideas that are wrong.","ex":{"en":"The thinking is good-hearted, but muddled and fundamentally unsound","cn":"这个想法的出发点是好的，但是条理混乱，而且本质上是错误的。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不可靠的；不安全的","en":"If something or someone is unsound, they are unreliable.","ex":{"en":"No sensible person would put his money in a bank he knew to be unsound.","cn":"凡是有头脑的人都不会把钱存到自己明知不可靠的银行里。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有危害的","en":"If you say that something is unsound in some way, you mean that it is damaging in that way or to the thing mentioned.","ex":{"en":"The project is environmentally unsound","cn":"这个项目会破坏环境。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不坚实的；不稳固的","en":"If a building or other structure is unsound, it is in poor condition and is likely to collapse.","ex":{"en":"The church was structurally unsound.","cn":"那个教堂的结构很不坚固。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not based on facts or good reasons","cn":"无根据的﹔谬误的"},{"en":"an unsound building or structure is in bad condition 〔","cn":"建筑物或结构〕不安全的﹐不稳固的"},{"en":"physically or mentally ill","cn":"身体不健康的﹔有精神病的"}]},"media":{"uk":"media/ldoce/hwd/bre/9/unsound0205.mp3","us":"media/ldoce/hwd/ame/7/unsound.mp3"},"examples":[{"en":"The use of disposable products is considered ecologically unsound.","cn":"使用一次性产品被认为是没有顾及对生态的影响。"},{"en":"The methods used were unsound.","cn":"所使用的方法不可靠。"}],"oxford":{"phon":"ˌʌnˈsaʊnd","pos":"adjective","senses":[{"en":"in poor condition; weak and likely to fall down","cn":"破旧的；摇摇欲坠的","ex":{"en":"The roof is structurally unsound.","cn":"这屋顶结构不牢固。"}},{"en":"not acceptable; not based on reliable evidence","cn":"不稳妥的；不可接受的；无可靠根据的","ex":{"en":"ideologically unsound","cn":"意识上不妥"}},{"en":"containing mistakes; that you cannot rely on","cn":"有错误的；靠不住的","ex":{"en":"The methods used were unsound.","cn":"所使用的方法不可靠。"}}]}},"unawares":{"collins":{"senses":[{"pos":"PHRASE 短语","cn":"冷不防地；出其不意地","en":"If something catches you unawares or takes you unawares, it happens when you are not expecting it.","ex":{"en":"Investors and currency dealers were caught completely unawares by the Bundesbank's action","cn":"投资者和外汇交易商被德意志联邦银行的这一举措打了个措手不及。"}}]},"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"something that is unexpected surprises you because you did not expect it","cn":""},{"en":"situations, problems, changes etc that you did not expect or prepare for, and which usually cause you difficulty","cn":""},{"en":"if something that happens is a surprise or comes as a surprise , you did not expect it to happen, and so you are surprised by it","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/8/brelasdeunawares.mp3","us":"media/ldoce/hwd/ame/0/unawares.mp3"},"examples":[{"en":"She came upon him unawares when he was searching her room.","cn":"他在翻她屋子时，冷不防被她撞见了。"},{"en":"The camera had caught her unawares.","cn":"她毫无防备地被拍摄下来。"}],"oxford":{"phon":"ˌʌnəˈweəz","pos":"adverb","senses":[{"en":"when not expected","cn":"猝然；出其不意地；冷不防","ex":{"en":"The camera had caught her unawares.","cn":"她毫无防备地被拍摄下来。"}},{"en":"without noticing or realizing","cn":"不留神地；未注意到；不知不觉地","lab":"formal","ex":{"en":"He slipped unawares into sleep.","cn":"他不知不觉地睡着了。"}}]}},"upcoming":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"即将发生(或来到)的","en":"Upcoming events will happen in the near future.","ex":{"en":"...the upcoming Asian Games in Beijing","cn":"即将在北京举行的亚运会"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if something that you are hoping for is in sight , you think it will probably happen soon","cn":""},{"en":"if something is around the corner , it might happen very soon but you cannot be completely sure","cn":""},{"en":"to be likely to happen soon, although you do not know exactly when","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/c/upcoming0205.mp3","us":"media/ldoce/hwd/ame/d/upcoming.mp3"},"examples":[{"en":"a single from the band's upcoming album","cn":"选自该乐队即将发行的专辑的一首单曲"},{"en":"the upcoming presidential election","cn":"即将举行的总统选举"}],"oxford":{"phon":"ˈʌpkʌmɪŋ","pos":"adjective","senses":[{"en":"going to happen soon","cn":"即将发生的；即将来临的","ex":{"en":"the upcoming presidential election","cn":"即将举行的总统选举"}}]}},"uncharitable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不宽厚的；刻薄的；苛刻的","en":"If you describe someone's remarks, thoughts, or behaviour as uncharitable, you think they are being unkind or unfair to someone.","ex":{"en":"Don't be uncharitable","cn":"别太苛刻。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"unkind or unfair in the way you judge people","cn":"苛刻的﹐不宽厚的，挑剔的﹔不公正的"}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41uncharitable.mp3","us":"media/ldoce/hwd/ame/c/uncharitable.mp3"},"examples":[{"en":"uncharitable thoughts","cn":"刻薄的想法"},{"en":"uncharitable remarks","cn":"刻薄的言辞"}],"oxford":{"phon":"ʌnˈtʃærɪtəbl","pos":"adjective","senses":[{"en":"unkind and unfair in the way that you judge people","cn":"刻薄的；苛刻的；冷酷的","ex":{"en":"uncharitable thoughts","cn":"刻薄的想法"}}]}},"up-and-coming":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"有作为的；有希望的；有前途的","en":"Up-and-coming people are likely to be successful in the future.","ex":{"en":"...his readiness to share the limelight with young, up-and-coming stars","cn":"他愿与冉冉升起的年轻新星分享聚光灯"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if a product, company, your job etc takes off , it suddenly starts being successful","cn":""},{"en":"to be becoming richer, more successful etc","cn":""},{"en":"an artist, player etc, especially a young one, who is getting more and more successful and who will probably soon be famous","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/2/up_and_coming0205.mp3","us":"media/ldoce/hwd/ame/1/up-and-coming.mp3"},"examples":[{"en":"up-and-coming young actors","cn":"前程似锦的年轻演员"},{"en":"up-and-coming young artists","cn":"有前途的年轻艺术家"}],"oxford":{"phon":"ˌʌp ən ˈkʌmɪŋ","pos":"adjective","senses":[{"en":"likely to be successful and popular in the future","cn":"有前途的；前程似锦的","ex":{"en":"up-and-coming young actors","cn":"前程似锦的年轻演员"}}]}},"unlucky":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不幸的；运气不好的","en":"If someone is unlucky, they have bad luck.","ex":{"en":"Owen was unlucky not to score on two occasions","cn":"欧文不幸两次都没有进球。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"令人不愉快的；令人遗憾的","en":"You can use unlucky to describe unpleasant things which happen to someone, especially when you feel that the person does not deserve them.","ex":{"en":"...Argentina's unlucky defeat by Ireland.","cn":"阿根廷队惜败于爱尔兰队"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"带来坏运气的；不吉利的","en":"Unlucky is used to describe something that is thought to cause bad luck.","ex":{"en":"Some people think it is unlucky to look at a new moon through glass.","cn":"有些人认为透过玻璃看新月是不吉利的。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"having bad luck, or causing bad luck","cn":""},{"en":"unlucky because something bad happens to you that you do not deserve. Unfortunate sounds rather formal and is used mainly in writing","cn":""},{"en":"if something is bad luck or brings bad luck, it is believed to make bad things happen","cn":""}]},"collocations":{"phrases":["VERBS be, prove, seem, sound | become | consider sb/sth, regard sb/sth as, think sb/sth The number thirteen is traditionally considered unlu","ADV. dead, desperately, extremely, very She was desperately unlucky to fall as badly as she did. | a bit, a little","PREP. for a date that is unlucky for that family | with She has been very unlucky with injuries this year."]},"media":{"uk":"media/ldoce/hwd/bre/8/unlucky0205.mp3","us":"media/ldoce/hwd/ame/c/unlucky.mp3"},"examples":[{"en":"By some unlucky chance, her name was left off the list.","cn":"倒霉的是，名单上漏掉了她的名字。"},{"en":"Some people think it's unlucky to walk under a ladder.","cn":"有些人认为从梯子下面走过不吉利。"}],"oxford":{"phon":"ʌnˈlʌki","pos":"adjective","senses":[{"en":"having bad luck or happening because of bad luck; not lucky","cn":"不幸的；倒霉的；不顺利的","ex":{"en":"He was very unlucky not to win.","cn":"他不幸输了。"}},{"en":"causing bad luck","cn":"不吉利的；晦气的","ex":{"en":"Some people think it's unlucky to walk under a ladder.","cn":"有些人认为从梯子下面走过不吉利。"}}]}},"undetected":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未被发现的；未被识破的；未被查出的","en":"If you are undetected or if you do something undetected, people do not find out where you are or what you are doing.","ex":{"en":"...the spy ring had a fifth member as yet still undetected","cn":"这个间谍团伙还有第五名成员未被查出。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if something, especially something bad, goes undetected, no one notices it 〔","cn":"尤指不好的事〕未被注意的"},{"en":"go/remain undetected Doctors can make mistakes and diseases can remain undetected.","cn":"医生有时会出错﹐查不出病症。 The thieves escaped undetected through a basement window. 那些盗贼从地下室的窗户神不知鬼不觉地逃走了。"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41undetected2.mp3","us":"media/ldoce/hwd/ame/e/laadundetected.mp3"},"examples":[{"en":"How could anyone break into the palace undetected?","cn":"怎么会有人神不知、鬼不觉地潜入皇宫呢？"},{"en":"The disease often goes/remains undetected for many years.","cn":"这种疾病经常潜伏多年而不被察觉。"}],"oxford":{"phon":"ˌʌndɪˈtektɪd","pos":"adjective","senses":[{"en":"not noticed by anyone","cn":"未被注意的","ex":{"en":"How could anyone break into the palace undetected?","cn":"怎么会有人神不知、鬼不觉地潜入皇宫呢？"}}]}},"uncomprehending":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"不理解的；困惑的；迷惑的","en":"If you describe someone as uncomprehending, you mean that they do not understand what is happening or what someone has said.","ex":{"en":"He gave the bottle a long, uncomprehending look.","cn":"他困惑地盯着那个瓶子看了好一会儿。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not understanding what is happening","cn":"不理解的，不明所以的"}]},"media":{"uk":"media/ldoce/hwd/bre/0/uncomprehendin0205.mp3","us":"media/ldoce/hwd/ame/6/laaduncomprehending.mp3"},"examples":[{"en":"She looked at him uncomprehendingly.","cn":"她一脸茫然地注视着他。"}],"oxford":{"phon":"ʌnˌkɒmprɪˈhendɪŋ","pos":"adjective","senses":[{"en":"not understanding a situation or what is happening","cn":"不理解的；茫然的；不领会的"}]}},"unscathed":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"未受伤的；未受损害的","en":"If you are unscathed after a dangerous experience, you have not been injured or harmed by it.","ex":{"en":"Tony emerged unscathed apart from a severely bruised finger","cn":"托尼除了一根手指严重淤青外没有受到其他伤害。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not harmed or damaged","cn":""},{"en":"safe and not hurt","cn":""},{"en":"not hurt","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"If you walked away from a nasty bike accident without a scratch, you walked away unscathed , meaning you came out unharmed."}]},"collocations":{"phrases":["VERBS be, be left, emerge, escape, get away, remain, survive, walk away The children escaped unscathed.","ADV. remarkably | completely, entirely, totally Amazingly, the driver walked away from the accident completely unscathed. | almost, virtuall","PREP. by The town centre was left unscathed by the riots."]},"media":{"uk":"media/ldoce/hwd/bre/6/unscathed0205.mp3","us":"media/ldoce/hwd/ame/d/unscathed.mp3"},"examples":[{"en":"The hostages emerged from their ordeal unscathed.","cn":"各人质历尽磨难后安然生还。"}],"oxford":{"phon":"ʌnˈskeɪðd","pos":"adjective","senses":[{"en":"not hurt","cn":"未受伤害；未受伤","ex":{"en":"The hostages emerged from their ordeal unscathed.","cn":"人质历尽磨难后安然生还。"}}]}},"unscripted":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"没打草稿的；不用稿子的","en":"An unscripted talk or speech is made without detailed preparation, rather than being read out.","ex":{"en":"...a witty, chatty and unscripted speech.","cn":"诙谐调侃的脱稿演讲"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"an unscripted broadcast, speech etc is not written or planned before it is made 〔","cn":"广播﹑演讲等〕不用稿子的﹔未事前准备的"}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41unscripted.mp3","us":"media/ldoce/hwd/ame/e/unscripted.mp3"},"oxford":{"phon":"ʌnˈskrɪptɪd","pos":"adjective","senses":[{"en":"not written or prepared in detail in advance","cn":"无底稿的；未详细准备的"}]}},"unwavering":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"坚定不移的；毫不动摇的；不屈不挠的","en":"If you describe a feeling or attitude as unwavering, you mean that it is strong and firm and does not weaken.","ex":{"en":"She has been encouraged by the unwavering support of her family","cn":"家人的坚决支持让她深受鼓舞。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"an unwavering attitude, belief, expression etc does not change 〔","cn":"态度﹑信仰﹑表情等〕坚定的﹐毫不动摇的﹐始终如一的"}]},"vocab":{"pos":"adj","senses":[{"en":"When something is unwavering , it is firm or unshakable. If you're a good hockey goalie, then you'll show an unwavering determination to keep the puck out of your goal."}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41unwavering.mp3","us":"media/ldoce/hwd/ame/b/laadunwavering.mp3"},"examples":[{"en":"unwavering support","cn":"坚定不移的支持"},{"en":"an unwavering stare","cn":"目不转睛的注视"}],"oxford":{"phon":"ʌnˈweɪvərɪŋ","pos":"adjective","senses":[{"en":"not changing or becoming weaker in any way","cn":"不动摇的；坚定的；始终如一的","ex":{"en":"unwavering support","cn":"坚定不移的支持"}}]}},"upstream":{"collins":{"senses":[{"pos":"ADV 副词","cn":"逆流地；往上游；在上游","en":"Something that is moving upstream is moving towards the source of a river, from a point further down the river. Something that is upstream is towards the source of a river.","ex":{"en":"The water rose high enough for them to continue upstream.","cn":"水位涨得够高了，他们可以继续向上游航行。"}}]},"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"along a river, in the opposite direction from the way the water is flowing","cn":"向上游，逆流(地)"}]},"media":{"uk":"media/ldoce/hwd/bre/0/upstream0205.mp3","us":"media/ldoce/hwd/ame/5/upstream.mp3"},"examples":[{"en":"The nearest town is about ten miles upstream.","cn":"最近的城镇大约在沿河向上十英里处。"},{"en":"upstream of/from the bridge","cn":"在桥的上游"}],"oxford":{"phon":"ˌʌpˈstriːm","pos":"adverb","senses":[{"en":"along a river, in the opposite direction to the way in which the water flows","cn":"向（或在）上游；逆流","ex":{"en":"The nearest town is about ten miles upstream.","cn":"最近的城镇大约在沿河向上十英里处。"}}]}},"uncut":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未修剪的；未割的","en":"Something that is uncut has not been cut.","ex":{"en":"...a patch of uncut grass","cn":"一小片没割的草"}},{"pos":"ADJ 形容词","cn":"（书、剧本或电影）未删节的","en":"An uncut book, play, or film has not had parts removed.","ex":{"en":"We saw the uncut version of 'Caligula' when we were in Europe.","cn":"我们在欧洲的时候看过未删节版《罗马帝国艳情史》。"}},{"pos":"ADJ 形容词","cn":"（钻石等宝石）未雕琢的，未加工的","en":"Uncut diamonds and other precious stones have not been cut into a regular shape."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a film, book etc that is uncut has not been made shorter, for example by having violent or sexual scenes removed 〔","cn":"影片﹑书籍等〕未剪辑[删节]的"},{"en":"an uncut jewel that is still in its natural form has not been cut into a particular shape 〔","cn":"宝石〕未切割的﹐未经雕琢的"}]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41uncut.mp3","us":"media/ldoce/hwd/ame/4/uncut.mp3"},"examples":[{"en":"The uncut grass came up to her waist.","cn":"未割的草齐了她的腰。"},{"en":"an uncut loaf of bread","cn":"一整条未切的面包"}],"oxford":{"phon":"ˌʌnˈkʌt","pos":"adjective","senses":[{"en":"left to grow; not cut short","cn":"未割的；未剪的","ex":{"en":"The uncut grass came up to her waist.","cn":"未割的草齐了她的腰。"}},{"en":"left in its complete form; without any parts removed; not censored","cn":"未删节的；未删剪的；未审查的","ex":{"en":"the original uncut version","cn":"未删节的原版"}},{"en":"not given a shape by cutting","cn":"未雕琢的；未加工的","ex":{"en":"uncut diamonds","cn":"未切割的钻石"}},{"en":"not cut into separate pieces","cn":"未切开的；完整的","ex":{"en":"an uncut loaf of bread","cn":"一整条未切的面包"}}]}},"uplift":{"collins":{"senses":[{"pos":"VERB 动词","cn":"使振奋；提升","en":"If something uplifts people, it helps them to have a better life, for example by making them feel happy or by improving their social conditions.","ex":{"en":"We need a little something to help sometimes, to uplift us and make us feel better","cn":"有时候，我们需要一些小东西来激励自己，使自己感觉更好。"}},{"pos":"N-COUNT 可数名词","cn":"上扬；上涨；增长","en":"In economics, an uplift in something such as the price of shares is an increase in their value.","ex":{"en":"...an uplift in the stock market","cn":"股市上涨"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an increase in something","cn":"增加﹐增长"},{"en":"a feeling of happiness and hope","cn":"鼓舞﹐振奋"},{"en":"to make someone feel happier","cn":"使〔某人〕振奋﹐鼓舞"}]},"media":{"uk":"media/ldoce/hwd/bre/8/uplift_n0205.mp3","us":"media/ldoce/hwd/ame/5/l3uplift.mp3"},"examples":[{"en":"The news gave them a much needed uplift.","cn":"这消息给他们带来了及时的鼓舞。"},{"en":"an uplift bra (= that raises the breasts)","cn":"挺高式乳罩"}],"oxford":{"phon":"ˈʌplɪft","pos":"noun","senses":[{"en":"the fact of something being raised or of something increasing","cn":"提高；抬高；增长；增加","ex":{"en":"an uplift in sales","cn":"销售的增长"}},{"en":"a feeling of hope and happiness","cn":"振奋；鼓舞","ex":{"en":"The news gave them a much needed uplift.","cn":"这消息给他们带来了及时的鼓舞。"}},{"en":"the process or result of land being moved to a higher level by movements inside the earth","cn":"（地壳的）隆起，上升；抬升","lab":"geology"},{"en":"to make somebody feel happier or give somebody more hope","cn":"鼓励；激励；使振奋","pos":"verb"}]}},"unfit":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（人因缺乏锻炼而）不健康的，不强健的","en":"If you are unfit, your body is not in good condition because you have not been taking regular exercise.","ex":{"en":"Many children are so unfit they are unable to do even basic exercises.","cn":"许多孩子非常不健康，连基本的健身锻炼都无法完成。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（人因伤病而）不适宜的","en":"If someone is unfit for something, he or she is unable to do it because of injury or illness.","ex":{"en":"He had a third examination and was declared unfit for duty","cn":"他接受了第三次检查，被告知不宜上班。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不合适的；不合格的；不胜任的","en":"If you say that someone or something is unfit for a particular purpose or job, you are criticizing them because they are not good enough for that purpose or job.","ex":{"en":"Existing houses are becoming totally unfit for human habitation","cn":"现有的房子正变得完全不适合住人。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not having the right qualities for a particular person, purpose, or situation","cn":""},{"en":"not suitable for a particular situation or purpose – used especially about someone’s behaviour or language","cn":""},{"en":"not the right thing or person for a particular job or purpose","cn":""}]},"vocab":{"pos":"adj v","senses":[{"en":"If someone is unfit , they're not qualified. You're unfit for a job as an ice cream truck driver if your only driving experience has been steering a bumper car at an amusement park."}]},"collocations":{"phrases":["VERBS be, look | become | make sb/sth, render sb/sth His conduct made him unfit to act as director of a company. | consider sb/sth, declare ","ADV. completely, quite, totally, wholly | medically, mentally, physically","PREP. for completely unfit for our purposes She was found unfit for work. 2 not in good physical health","VERBS be, feel, look, seem | become","ADV. very | completely, quite | slightly"]},"media":{"uk":"media/ldoce/hwd/bre/c/unfit0205.mp3","us":"media/ldoce/hwd/ame/a/unfit.mp3"},"examples":[{"en":"The captain is still unfit and will miss tonight's game.","cn":"队长身体状态仍不好，将不会出战今晚的比赛。"},{"en":"The company's doctor found that she was unfit to carry out her normal work.","cn":"公司的医生认为，她不宜从事正常工作。"}],"oxford":{"phon":"ʌnˈfɪt","pos":"adjective","senses":[{"en":"not of an acceptable standard; not suitable","cn":"不合格的；不适合的；不适宜的","lab":"specialist","ex":{"en":"The housing was unfit for human habitation.","cn":"这种住房不适合居住。"}},{"en":"not capable of doing something, for example because of illness","cn":"（因病等）不能做某事，不宜做事","ex":{"en":"He's still unfit for work.","cn":"他还不宜工作。"}},{"en":"not in good physical condition; not fit, because you have not taken exercise","cn":"健康状况欠佳；身体状态差","lab":"especially British English","ex":{"en":"The captain is still unfit and will miss tonight's game.","cn":"队长身体状态仍不好，将不会出战今晚的比赛。"}}]}},"unrestrained":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"无限制的；极度的","en":"If you describe someone's behaviour as unrestrained, you mean that it is extreme or intense, for example because they are expressing their feelings strongly or loudly.","ex":{"en":"There was unrestrained joy on the faces of the people","cn":"人们的脸上洋溢着无尽的欢乐。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not controlled or limited","cn":"无限制的﹔无拘束的﹔自由自在的"}]},"vocab":{"pos":"adj","senses":[{"en":"You know how your uncle Marvin is always screaming at the television when his game shows are on? That’s because he’s being unrestrained . Anyone exhibiting uncontrolled emotion is unrestrained , meaning they don’t hold back."}]},"media":{"uk":"media/ldoce/hwd/bre/7/unrestrained0205.mp3","us":"media/ldoce/hwd/ame/6/unrestrained.mp3"},"examples":[{"en":"unrestrained aggression","cn":"肆无忌惮的侵犯"},{"en":"unrestrained power","cn":"无限制的权力"}],"oxford":{"phon":"ˌʌnrɪˈstreɪnd","pos":"adjective","senses":[{"en":"not controlled; not having been restrained","cn":"无节制的；放纵的；不加制约的","ex":{"en":"unrestrained greed/joy","cn":"贪得无厌；喜不自胜"}}]}},"ukulele":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"尤克莱利琴（四弦小吉他）","en":"A ukulele is a small guitar with four strings."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a musical instrument with four strings, like a small guitar","cn":"尤克里里琴〔一种类似小吉他的四弦琴〕"}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41ukulele.mp3","us":"media/ldoce/hwd/ame/b/ld41ukulele.mp3"},"oxford":{"phon":"ˌjuːkəˈleɪli","pos":"noun","senses":[{"en":"a musical instrument with four strings, like a small guitar","cn":"尤克里里（四弦小吉他）"}]}},"unsmiling":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"不苟言笑的；不友善的","en":"An unsmiling person is not smiling, and looks serious or unfriendly.","ex":{"en":"He was unsmiling and silent.","cn":"他不苟言笑，沉默寡言。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"looking serious and unfriendly","cn":"没有笑意的﹐不苟言笑的"}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41unsmiling.mp3","us":"media/ldoce/hwd/ame/f/laadunsmiling.mp3"},"examples":[{"en":"His eyes were hard and unsmiling.","cn":"他目光严厉冷峻。"},{"en":"an unsmiling face","cn":"没有笑意的脸"}],"oxford":{"phon":"ˌʌnˈsmaɪlɪŋ","pos":"adjective","senses":[{"en":"not smiling; looking unfriendly","cn":"不苟言笑的；表情冷漠的","ex":{"en":"His eyes were hard and unsmiling.","cn":"他目光严厉冷峻。"}}]}},"underdeveloped":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（国家或地区）不发达的，欠发达的，经济落后的","en":"An underdeveloped country or region does not have modern industries and usually has a low standard of living. Some people dislike this term and prefer to use developing.","ex":{"en":"Underdeveloped countries should be assisted by allowing them access to modern technology.","cn":"应该通过提供现代技术来帮助不发达国家。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a country, area etc that is poor and where there is not much modern industry","cn":"欠发达国家/地区等"},{"en":"not having grown or developed as much as is usual or necessary","cn":"发育不全的"}]},"media":{"uk":"media/ldoce/hwd/bre/3/underdeveloped0205.mp3","us":"media/ldoce/hwd/ame/1/laadunderdeveloped.mp3"},"examples":[{"en":"a baby born with underdeveloped kidneys","cn":"肾脏先天发育不全的婴儿"}],"oxford":{"phon":"ˌʌndədɪˈveləpt","pos":"adjective","senses":[{"en":"having few industries and a low standard of living","cn":"工业不发达的；生活水平低的；低度开发的"}]}},"uhf":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"超高频","en":"UHF is a range of radio waves which allows a radio or television receiver to produce a good quality of sound. UHF is an abbreviation for (缩略=) 'ultra-high frequency'.","ex":{"en":"...Boston UHF channels.","cn":"波士顿超高频频道"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a range of radio waves that produces a very good quality of sound","cn":"特高频"}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41uhf.mp3","us":"media/ldoce/hwd/ame/b/uhf.mp3"},"oxford":{"phon":"ˌjuː eɪtʃ ˈef","pos":"abbreviation","senses":[{"en":"ultra-high frequency (a range of radio waves used for high-quality radio and television broadcasting)","cn":"特高频"}]}},"unavailing":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"徒劳的；不成功的；无成果的","en":"An unavailing attempt to do something does not succeed.","ex":{"en":"Efforts to reach the people named in the report proved unavailing","cn":"联系过报告中所提到的那些人，但都徒劳无功。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not successful or effective","cn":"徒劳的﹔无用的"}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41unavailing.mp3","us":"media/ldoce/hwd/ame/c/unavailing.mp3"},"examples":[{"en":"Their efforts were unavailing.","cn":"他们的努力都付诸东流。"},{"en":"unavailing efforts to make her happy","cn":"想使她快乐的徒劳努力"}],"oxford":{"phon":"ˌʌnəˈveɪlɪŋ","pos":"adjective","senses":[{"en":"without success","cn":"徒劳的；无成果的","ex":{"en":"Their efforts were unavailing.","cn":"他们的努力都付诸东流。"}}]}},"unbridled":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"无约束的；放肆的；放纵的","en":"If you describe behaviour or feelings as unbridled, you mean that they are not controlled or limited in any way.","ex":{"en":"...the unbridled greed of the 1980s.","cn":"20世纪80年代贪得无厌的社会风气"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not controlled and too extreme or violent","cn":"放纵的﹐不受控制的﹔极端的；激烈的"}]},"vocab":{"pos":"adj","senses":[{"en":"Unbridled means unrestrained. When you find out that you just won the lottery, feel free to jump up and down with unbridled joy. Go ahead, most people would probably let loose in the same way."}]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41unbridled.mp3","us":"media/ldoce/hwd/ame/0/unbridled.mp3"},"examples":[{"en":"unbridled passion","cn":"奔放的激情"},{"en":"unbridled greed","cn":"毫无节制的贪婪"}],"oxford":{"phon":"ʌnˈbraɪdld","pos":"adjective","senses":[{"en":"lacking control and therefore extreme","cn":"无节制的；奔放的；极端的","ex":{"en":"unbridled passion","cn":"奔放的激情"}}]}},"unpublished":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未出版的；未发表的；未公开的；从未发表过作品的","en":"An unpublished book, letter, or report has never been published. An unpublished writer has never had his or her work published."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"unpublished writing, information etc has never been publish ed","cn":"未出版的﹐未发表的"}]},"vocab":{"pos":"adj","senses":[{"en":"Unpublished means not made public. If your phone number is unpublished , it’s not listed in the telephone directory and you’re safe from late-night calls from long-lost boyfriends."}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41unpublished.mp3","us":"media/ldoce/hwd/ame/6/laadunpublished.mp3"},"examples":[{"en":"an unpublished novel","cn":"未出版的小说"}],"oxford":{"phon":"ʌnˈpʌblɪʃt","pos":"adjective","senses":[{"en":"not published","cn":"未出版的；未发表的；未公开的","ex":{"en":"an unpublished novel","cn":"未出版的小说"}}]}},"unsolved":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未解决的；未破解的","en":"An unsolved mystery or problem has never been solved.","ex":{"en":"...America's unsolved problems of poverty and racism","cn":"美国尚未解决的贫困和种族问题"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"an event or fact that is unexplained has never been explained so no one knows exactly what happened","cn":""},{"en":"a problem, mystery, or crime that is unsolved has never been solved 〔","cn":"问题﹑谜团或罪案〕未解决的"}]},"media":{"uk":"media/ldoce/hwd/bre/2/unsolved0205.mp3","us":"media/ldoce/hwd/ame/a/laadunsolved.mp3"},"examples":[{"en":"an unsolved murder/mystery/problem","cn":"未破案的谋杀事件；未解开的谜团；未解决的问题"},{"en":"The murder still remains unsolved.","cn":"谋杀案依然没有告破。"}],"oxford":{"phon":"ˌʌnˈsɒlvd","pos":"adjective","senses":[{"en":"not having been solved","cn":"未解决的；未破解的","ex":{"en":"an unsolved murder/mystery/problem","cn":"未侦破的谋杀案；未解开的谜团；未解决的问题"}}]}},"undertake":{"collins":{"senses":[{"pos":"VERB 动词","cn":"着手做;从事;承担","en":"When you undertake a task or job, you start doing it and accept responsibility for it.","ex":{"en":"She undertook the arduous task of monitoring the elections.","cn":"她承担了监督选举的艰巨任务。"}},{"pos":"VERB 动词","cn":"承诺；保证；答应","en":"If you undertake to do something, you promise that you will do it.","ex":{"en":"He undertook to edit the text himself.","cn":"他答应亲自编辑正文的内容。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to tell someone that you will definitely do something, or that something will happen","cn":""},{"en":"to make a very serious and sincere promise, for example in a law court","cn":""},{"en":"to promise sincerely that you will do something or that something is true – often used when you are trying to persuade someone that they can trust you","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"When you undertake a task or challenge, you attempt to accomplish it. If you want to undertake a verbal challenge right now, try saying “sushi chef” ten times quickly without messing up."}]},"media":{"uk":"media/ldoce/hwd/bre/f/undertake0205.mp3","us":"media/ldoce/hwd/ame/f/undertake.mp3"},"examples":[{"en":"The company has announced that it will undertake a full investigation into the accident.","cn":"公司已经宣布将对这次事故进行全面调查。"},{"en":"University professors both teach and undertake research.","cn":"大学教授既要教学又要从事研究工作。"}],"oxford":{"phon":"ˌʌndəˈteɪk","pos":"verb","senses":[{"en":"to make yourself responsible for something and start doing it","cn":"承担；从事；负责","ex":{"en":"to undertake a task/project","cn":"承担一个任务／项目"}},{"en":"to agree or promise that you will do something","cn":"承诺；允诺；答应","ex":{"en":"He undertook to finish the job by Friday.","cn":"他答应星期五之前完成这一工作。"}}]}},"unfaithful":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不忠的；通奸的","en":"If someone is unfaithful to their lover or to the person they are married to, they have a sexual relationship with someone else.","ex":{"en":"James had been unfaithful to Christine for the entire four years they'd been together.","cn":"在和克里斯蒂娜共同生活的4年中，詹姆斯一直对她不忠。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if someone is unfaithful , they have sex with someone who is not their husband, girlfriend etc","cn":""},{"en":"if someone cheats on their husband, girlfriend etc, they secretly have sex with someone else","cn":""},{"en":"a secret sexual relationship between two people when at least one of them is married to someone else","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/6/unfaithful0205.mp3","us":"media/ldoce/hwd/ame/a/unfaithful.mp3"},"examples":[{"en":"Have you ever been unfaithful to him?","cn":"你对他是否有过不忠行为？"},{"en":"Geoff had been unfaithful to her on many occasions.","cn":"杰夫多次对她不忠。"}],"oxford":{"phon":"ʌnˈfeɪθfl","pos":"adjective","senses":[{"en":"having sex with somebody who is not your husband, wife or usual partner","cn":"（对伴侣）不忠的","ex":{"en":"Have you ever been unfaithful to him?","cn":"你对他是否有过不忠行为？"}}]}},"unstructured":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（会议、会面、活动等）未组织的，未作详细安排的","en":"Something such as a meeting, interview, or activity that is unstructured is not organized in a complete or detailed way.","ex":{"en":"Our aim was that these meetings be unstructured and informal","cn":"我们的目的是，这些会议不事先进行精心组织，要随意一些。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not organized in a detailed way, and allowing people freedom to do what they want","cn":"未作仔细安排的；随意的"}]},"vocab":{"pos":"adj","senses":[{"en":"Unstructured is an adjective describing something that lacks structure or form. Some things should never be left unstructured, like a schedule for building a house or a time line for retirement."}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41unstructured.mp3","us":"media/ldoce/hwd/ame/6/laadunstructured.mp3"},"examples":[{"en":"unstructured interviews","cn":"随意的访谈"}],"oxford":{"phon":"ʌnˈstrʌktʃəd","pos":"adjective","senses":[{"en":"without structure or organization","cn":"结构凌乱的；无条理的；紊乱的","ex":{"en":"an unstructured interview","cn":"没有预先组织好的访谈。"}}]}},"unlearn":{"collins":{"senses":[{"pos":"VERB 动词","cn":"设法忘记（或忽略）；抛掉（以前的错误想法、坏习惯等）","en":"If you unlearn something that you have learned, you try to forget it or ignore it, often because it is wrong or it is having a bad influence on you.","ex":{"en":"They learn new roles and unlearn old ones","cn":"他们学习新的角色，抛却旧的角色。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to deliberately forget something you have learned, in order to change the way you do something","cn":"设法忘记﹐抛弃〔已学会的东西〕"}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41unlearn.mp3","us":"media/ldoce/hwd/ame/c/unlearn.mp3"},"examples":[{"en":"You'll have to unlearn all the bad habits you learned with your last piano teacher.","cn":"你必须丢掉你的前任钢琴老师所教的一切坏习惯。"},{"en":"It’s difficult to unlearn bad driving habits.","cn":"很难改掉不好的驾驶习惯。"}],"oxford":{"phon":"ˌʌnˈlɜːn","pos":"verb","senses":[{"en":"to deliberately forget something that you have learned, especially something bad or wrong","cn":"故意忘却（尤指错事或坏事）；抛弃","ex":{"en":"You'll have to unlearn all the bad habits you learned with your last piano teacher.","cn":"你必须丢掉你的前任钢琴老师所教的一切坏习惯。"}}]}},"untrammelled":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"无拘无束的；自由自在的；自如的","en":"Someone who is untrammelled is able to act freely in the way they want to, rather than being restricted by something.","ex":{"en":"...the only place where the royal family could really relax and lead an untrammelled domestic life","cn":"唯一一处王室成员可以真正放松、不受拘束地过家庭生活的地方"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not limited by anyone or anything","cn":"没有限制的"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41untrammelled.mp3","us":"media/ldoce/hwd/ame/4/ld41untrammelled.mp3"},"examples":[{"en":"an organization untrammelled by legal restraints","cn":"不受法律限制的机构"}],"oxford":{"phon":"ʌnˈtræmld","pos":"adjective","senses":[{"en":"not limited by something","cn":"不受限制的；无拘束的；自由自在的","ex":{"en":"untrammelled power","cn":"不受约束的权力"}}]}},"uneconomical":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不能盈利的；没有效益的；不经济的","en":"If you say that an action, a method, or a product is uneconomical, you mean that it does not make a profit.","ex":{"en":"It would be uneconomical to send a brand new tape","cn":"寄一盘新磁带过去不合算。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"using too much effort, money, or materials to make a profit","cn":"不经济的﹐浪费的"}]},"vocab":{"pos":"adj","senses":[{"en":"Leaving all your lights on all the time is an uneconomical, or wasteful. Rewriting this sentence using five hundred words would be an uneconomical, or inefficient, use of language."}]},"media":{"uk":"media/ldoce/hwd/bre/8/brelasdeuneconomical.mp3","us":"media/ldoce/hwd/ame/2/amelasdeuneconomical.mp3"},"examples":[{"en":"It soon proved uneconomical to stay open 24 hours a day.","cn":"每天 24 小时营业很快便能证明是不经济的。"},{"en":"Old vehicles are often uneconomical.","cn":"旧车往往很费钱。"}],"oxford":{"phon":"ˌʌnˌiːkəˈnɒmɪkl","pos":"adjective","senses":[{"en":"using too much time or money, or too many materials, and therefore not likely to make a profit","cn":"浪费的；不节俭的；不经济的","ex":{"en":"It soon proved uneconomical to stay open 24 hours a day.","cn":"每天 24 小时营业很快就证明是不经济的。"}}]}},"underpin":{"collins":{"senses":[{"pos":"VERB 动词","cn":"加强…的基础；巩固；支撑","en":"If one thing underpins another, it helps the other thing to continue or succeed by supporting and strengthening it.","ex":{"en":"...mystical themes that underpin all religions","cn":"支撑所有宗教的神秘主题"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to give strength or support to something and to help it succeed","cn":"巩固﹐支持"},{"en":"to put a solid piece of metal under a wall or house in order to make it stronger","cn":"加固〔墙体或房屋〕的地基"}]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41underpin.mp3","us":"media/ldoce/hwd/ame/b/underpin.mp3"},"examples":[{"en":"The report is underpinned by extensive research.","cn":"这份报告以广泛的研究为基础。"},{"en":"the theories that underpin his teaching method","cn":"支持他的教学方法的理论"}],"oxford":{"phon":"ˌʌndəˈpɪn","pos":"verb","senses":[{"en":"to support or form the basis of an argument, a claim, etc.","cn":"加强，巩固，构成（…的基础等）","lab":"formal","ex":{"en":"The report is underpinned by extensive research.","cn":"这份报告以广泛的研究为基础。"}},{"en":"to support a wall and make it stronger by putting metal, concrete (= a hard building material), etc. under it","cn":"加固（墙）基","lab":"specialist"}]}},"uneventful":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无惊人（或重大）事件的；平凡的；平静的","en":"If you describe a period of time as uneventful, you mean that nothing interesting, exciting, or important happened during it.","ex":{"en":"The return journey was uneventful, the car running perfectly","cn":"回程波澜不惊，车开得很顺。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"with nothing exciting or unusual happening","cn":"平淡的﹔平静的﹔平凡的"}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41uneventful.mp3","us":"media/ldoce/hwd/ame/5/uneventful.mp3"},"examples":[{"en":"The day passed uneventfully.","cn":"这一天平平淡淡地过去了。"},{"en":"an uneventful life","cn":"平淡的一生"}],"oxford":{"phon":"ˌʌnɪˈventfl","pos":"adjective","senses":[{"en":"in which nothing interesting, unusual or exciting happens","cn":"平淡无奇的；平凡的；缺乏刺激的","ex":{"en":"an uneventful life","cn":"平淡的一生"}}]}},"unfurnished":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"没有家具的","en":"If you rent an unfurnished house, flat, or apartment, no furniture is provided by the owner."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"an unfurnished room, house etc has no furniture in it 〔","cn":"房屋等〕无家具的"}]},"media":{"uk":"media/ldoce/hwd/bre/8/unfurnished0205.mp3","us":"media/ldoce/hwd/ame/d/laadunfurnished.mp3"},"examples":[{"en":"We rented an unfurnished apartment.","cn":"我们租了一套不带家具的公寓。"}],"oxford":{"phon":"ʌnˈfɜːnɪʃt","pos":"adjective","senses":[{"en":"without furniture","cn":"无家具的","ex":{"en":"We rented an unfurnished apartment.","cn":"我们租了一套不带家具的公寓。"}}]}},"untie":{"collins":{"senses":[{"pos":"VERB 动词","cn":"解开…上的绳索；松开","en":"If you untie something that is tied to another thing or if you untie two things that are tied together, you remove the string or rope that holds them or that has been tied round them.","ex":{"en":"Nicholas untied the boat from her mooring","cn":"尼古拉斯把泊船的绳缆解开。"}},{"pos":"VERB 动词","cn":"解开，松开（绳结等）","en":"If you untie something such as string or rope, you undo it so that there is no knot or so that it is no longer tying something.","ex":{"en":"She hurriedly untied the ropes binding her ankles","cn":"她连忙解开绑着脚踝的绳子。"}},{"pos":"VERB 动词","cn":"解开，松开（鞋带）","en":"When you untie your shoelaces or your shoes, you loosen or undo the laces of your shoes.","ex":{"en":"She untied the laces on one of her sneakers","cn":"她解开了一只鞋的鞋带。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to join together the two sides of a piece of clothing, bag, belt etc","cn":""},{"en":"to fasten something firmly to another object or surface, using screws, nails, tape, glue etc","cn":""},{"en":"to connect or fasten things together","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/d/untie0205.mp3","us":"media/ldoce/hwd/ame/b/untie.mp3"},"examples":[{"en":"I quickly untied the package and peeped inside.","cn":"我迅速拆开包裹，往里瞥了一眼。"},{"en":"He untied the rope and pushed the boat into the water.","cn":"他解开缆绳，把小船推入水中。"}],"oxford":{"phon":"ʌnˈtaɪ","pos":"verb","senses":[{"en":"to separate the pieces of string, rope, etc. that form a knot in something; to remove the string, rope, etc. from something that is tied","cn":"解开…的结；打开","ex":{"en":"to untie a knot","cn":"解开绳结"}}]}},"unwell":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不适的；不舒服的","en":"If you are unwell, you are ill.","ex":{"en":"He had been riding in Hyde Park, but felt unwell as he was being driven back to his office late this afternoon.","cn":"他一直在海德公园骑自行车，后来感到不舒服，近黄昏时被人开车送回办公室。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"suffering from a disease or not feeling well","cn":""},{"en":"ill","cn":""},{"en":"ill, but not seriously ill","cn":""}]},"collocations":{"phrases":["VERBS appear, be, feel, look, seem, sound He complained of feeling unwell. | become | remain | make sb","ADV. extremely, really, very | a little, vaguely patients who just feel vaguely unwell","PREP. with You should delay vaccination if you are unwell with a fever."]},"media":{"uk":"media/ldoce/hwd/bre/f/unwell0205.mp3","us":"media/ldoce/hwd/ame/8/unwell.mp3"},"examples":[{"en":"She said she was feeling unwell and went home.","cn":"她说她感觉不舒服回家了。"},{"en":"She had been feeling unwell.","cn":"她觉得不舒服。"}],"oxford":{"phon":"ʌnˈwel","pos":"adjective","senses":[{"en":"ill","cn":"有恙；染病；不适；不舒服","ex":{"en":"She said she was feeling unwell and went home.","cn":"她说她感觉不舒服回家了。"}}]}},"umpteenth":{"collins":{"senses":[{"pos":"ORD 序数词","cn":"第无数次（的）","en":"You use umpteenth to indicate that an occasion, thing, or person happens or comes after many others.","ex":{"en":"He checked his watch for the umpteenth time","cn":"他不停地看表。"}}]},"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"very many – used especially when you are annoyed there are so many","cn":""},{"en":"if something happens for the umpteenth time, it happens again after having happened many times before – used when you are annoyed that it has happened so often","cn":"第无数次的〔尤用于对此感到恼怒时〕"}]},"media":{"uk":"media/ldoce/hwd/bre/9/umpteen0205.mp3","us":"media/ldoce/hwd/ame/0/amelasdeumpteen.mp3"},"examples":[{"en":"‘This is crazy,’ she told herself for the umpteenth time (= she had done it many times before). “","cn":"这简直疯了！”她已无数次这般地自言自语着。"},{"en":"There seemed to be umpteen rules and regulations to learn.","cn":""}],"oxford":{"phon":"ˌʌmpˈtiːnθ","pos":"determiner","senses":[{"en":"happening or coming after many other occasions, things or people","cn":"无数次","ex":{"en":"‘This is crazy,’ she told herself for the umpteenth time.","cn":"“这简直疯了！”她已无数次这般地自言自语着。"}}]}},"ungodly":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不道德的；违背宗教教义的","en":"If you describe someone or something as ungodly, you mean that they are morally bad or are opposed to religion.","ex":{"en":"Such a view implies that our bodies and sexual nature are inherently ungodly.","cn":"这样的观点暗示我们的身体和性本能天生就是邪恶的。"}},{"pos":"ADJ 形容词","cn":"（时间）过早的","en":"If you refer to a time as an ungodly hour, you are emphasizing that it is very early in the morning.","ex":{"en":"...at the ungodly hour of 4.00am.","cn":"凌晨4点钟"}},{"pos":"ADJ 形容词","cn":"过度的；不合理的","en":"If you refer to the amount or volume of something as ungodly, you mean that it is excessive or unreasonable.","ex":{"en":"...a power struggle of ungodly proportions.","cn":"过多的权力斗争"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"unreasonable and annoying","cn":"不合情理的﹐不适当的﹔恼人的"},{"en":"showing a lack of respect for God","cn":"不敬神的﹐亵渎神灵的"}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41ungodly.mp3","us":"media/ldoce/hwd/ame/5/ungodly.mp3"},"examples":[{"en":"Why did you wake me up at such an ungodly hour?","cn":"这么一大早把我叫醒干吗？"}],"oxford":{"phon":"ʌnˈɡɒdli","pos":"adjective","senses":[{"en":"not showing respect for God; evil","cn":"亵渎神灵的；不敬神的；邪恶的"}]}},"unaided":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"无外援的；独立的","en":"If you do something unaided, you do it without help from anyone or anything else.","ex":{"en":"There have been at least thirteen previous attempts to reach the North Pole unaided","cn":"之前至少已经有过13次想独立到达北极的尝试。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"without help from anyone else","cn":""},{"en":"without any help from anyone else. Alone is more formal and less common than on your own or by yourself","cn":""},{"en":"without asking for help or advice from anyone","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"If you can still walk unaided after your bicycle accident, that’s very good news. It means you can walk without someone helping you."}]},"media":{"uk":"media/ldoce/hwd/bre/f/unaided0205.mp3","us":"media/ldoce/hwd/ame/1/unaided.mp3"},"examples":[{"en":"He can now walk unaided.","cn":"他现在能独自行走了。"},{"en":"She can no longer walk unaided.","cn":"她再也不能独力行走了。"}],"oxford":{"phon":"ʌnˈeɪdɪd","pos":"adjective, adverb","senses":[{"en":"without help from anyone or anything","cn":"无外援（的）；独力（的）","ex":{"en":"Did she produce this work unaided?","cn":"她是在没有任何帮助的情况下完成这件作品的吗？"}}]}},"uppity":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"自大的；骄横的","en":"If you say that someone is uppity, you mean that they are behaving as if they were very important and you do not think that they are important.","ex":{"en":"If you just tried to show normal dignity, you were viewed as uppity.","cn":"就算是只想表现出正常的尊严，也会被人认为是骄傲自大。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"behaving as if you are more important than you really are, or not showing someone enough respect","cn":"傲慢的﹐自大的﹐盛气凌人的"}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41uppity.mp3","us":"media/ldoce/hwd/ame/e/uppity.mp3"},"examples":[{"en":"uppity kids","cn":"目中无人的小孩"}],"oxford":{"phon":"ˈʌpəti","pos":"adjective","senses":[{"en":"behaving as if you are more important than you really are, especially when this means that you refuse to obey orders","cn":"傲慢的；自视甚高（而不服从）的"}]}},"understaffed":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"人员不足的；人手不够的","en":"If an organization is understaffed, it does not have enough employees to do its work properly.","ex":{"en":"Many institutions offering child care are understaffed and underequipped.","cn":"许多保育机构人手不够，设备也不足。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a company or organization that is understaffed does not have enough people working in it because it cannot or will not employ more people","cn":""},{"en":"to not have the number of people you need to do a job properly or on time, especially because some of the people who usually work are ill, on holiday etc","cn":""},{"en":"not having enough workers, or fewer workers than usual","cn":"人员不足的﹐人手不够的"}]},"media":{"uk":"media/ldoce/hwd/bre/9/understaffed0205.mp3","us":"media/ldoce/hwd/ame/f/understaffed.mp3"},"oxford":{"phon":"ˌʌndəˈstɑːft","pos":"adjective","senses":[{"en":"not having enough people working and therefore not able to function well","cn":"人员不足；人手太少","ex":{"en":"We’re very understaffed at the moment.","cn":"我们此刻人手太少。"}}]}},"unadorned":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"无装饰的；简朴的","en":"Something that is unadorned is plain, rather than having decoration on it.","ex":{"en":"The room is typically simple and unadorned, with white walls and a tiled floor.","cn":"墙壁是白色的，地面铺了地砖，房间布置得特别简单朴素。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"without unnecessary or special features or decorations","cn":"不加装饰的﹐简朴的"}]},"vocab":{"pos":"adj","senses":[{"en":"Something unadorned has no decorations or frills. It's plain, like a room with nothing on the walls or a person wearing purely functional clothes and no accessories."}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41unadorned.mp3","us":"media/ldoce/hwd/ame/d/laadunadorned.mp3"},"examples":[{"en":"The walls were plain and unadorned.","cn":"墙壁朴素无华。"},{"en":"They liked their churches to be unadorned.","cn":"他们希望他们的教堂朴素无华。"}],"oxford":{"phon":"ˌʌnəˈdɔːnd","pos":"adjective","senses":[{"en":"without any decoration","cn":"不加装饰的；简朴的","ex":{"en":"The walls were plain and unadorned.","cn":"墙壁朴素无华。"}}]}},"urdu":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"乌尔都语（巴基斯坦官方语言之一，亦通行于印度）","en":"Urdu is an official language of Pakistan. Urdu is also spoken in India."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the official language of Pakistan, also used in India","cn":"乌尔都语〔巴基斯坦的官方语言﹐也用于印度〕"}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41urdu.mp3","us":"media/ldoce/hwd/ame/2/urdu.mp3"},"oxford":{"phon":"ˈʊəduː","pos":"noun","senses":[{"en":"the official language of Pakistan, also widely used in India","cn":"乌尔都语（巴基斯坦的官方语言，印度也通用）"}]}},"unpaid":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"无偿的；没有薪水的","en":"If you do unpaid work or are an unpaid worker, you do a job without receiving any money for it.","ex":{"en":"Even unpaid work for charity is better than nothing","cn":"即便是给慈善机构做义工也比什么都不做要好。"}},{"pos":"ADJ 形容词","cn":"未缴纳的；未付清的；还未付款的","en":"Unpaid taxes or bills, for example, are bills or taxes which have not been paid yet.","ex":{"en":"The taxman caught up with him and demanded £7,000 in unpaid taxes","cn":"税收人员查到了他，要求他把未缴纳的7,000英镑税款交上。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"an unpaid worker does not get paid for the work that he or she does; unpaid work is work that you do but do not get paid for","cn":""},{"en":"voluntary work is done by people who want to do it, without expecting to be paid for it","cn":""},{"en":"an amount of money that is due should be paid now","cn":""}]},"collocations":{"phrases":["VERBS be | remain | leave sth customers who leave their bills unpaid till the last minute","ADV. virtually the virtually unpaid labour of large peasant families"]},"media":{"uk":"media/ldoce/hwd/bre/0/brelasdeunpaid.mp3","us":"media/ldoce/hwd/ame/5/unpaid.mp3"},"examples":[{"en":"unpaid volunteers","cn":"不领报酬的志愿者"},{"en":"unpaid leave","cn":"不带薪的休假"}],"oxford":{"phon":"ˌʌnˈpeɪd","pos":"adjective","senses":[{"en":"not yet paid","cn":"未支付的；未付清的","ex":{"en":"unpaid bills","cn":"未付的账单"}},{"en":"done or taken without payment","cn":"无偿的；不付报酬的","ex":{"en":"unpaid work","cn":"无偿劳动"}},{"en":"not receiving payment for work that they do","cn":"不领报酬的；没有工资的","ex":{"en":"These volunteers, most of them unpaid, are essential to the charity's work.","cn":"这些志愿者大部分都是无偿的，但对于慈善机构的工作至关重要。"}}]}},"unseasonably":{"collins":{"senses":[{"pos":"ADV 副词","cn":"反季节的；不合季节的","en":"Unseasonably warm, cold, or mild weather is warmer, colder, or milder than it usually is at the time of year.","ex":{"en":"...a spell of unseasonably warm weather","cn":"一段反常的暖和天气"}}]},"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"used for saying that the weather is warmer, colder etc than usual at a particular time of year 〔","cn":"天气〕反常地温暖/寒冷/炎热等"}]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41unseasonably.mp3","us":"media/ldoce/hwd/ame/1/ld41unseasonably.mp3"},"examples":[{"en":"unseasonably warm","cn":"反常地温暖"}],"oxford":{"phon":"ʌnˈsiːznəbli","pos":"adverb","senses":[{"en":"in a way that is unusual for the time of year","cn":"不合季节的；违反时令的","ex":{"en":"unseasonably warm","cn":"天气暖得不合季节"}}]}},"unfathomable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（事物）高深莫测的，深奥的","en":"If you describe something as unfathomable, you mean that it cannot be understood or explained, usually because it is very strange or complicated.","ex":{"en":"For some unfathomable reason, there are no stairs where there should be","cn":"不知什么原因，本该有楼梯的地方却没有。"}},{"pos":"ADJ 形容词","cn":"（人或表情）难以捉摸的","en":"If you use unfathomable to describe a person or the expression on their face, you mean that you cannot tell what they are thinking or what they intend to do.","ex":{"en":"...a strange, unfathomable and unpredictable individual.","cn":"一个古怪、难以捉摸、反复无常的人"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"too strange or mysterious to be understood","cn":"莫测高深的﹐难以理解的"}]},"vocab":{"pos":"adj","senses":[{"en":"Unfathomable means impossible to ever understand. For most people, the field of quantum mechanics is unfathomable ."}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41unfathomable.mp3","us":"media/ldoce/hwd/ame/e/unfathomable.mp3"},"examples":[{"en":"an unfathomable mystery","cn":"难以解释的奥秘"}],"oxford":{"phon":"ʌnˈfæðəməbl","pos":"adjective","senses":[{"en":"too strange or difficult to be understood","cn":"难以理解的；莫测高深的","ex":{"en":"an unfathomable mystery","cn":"难以解释的奥秘"}},{"en":"if somebody has an unfathomable expression, it is impossible to know what they are thinking","cn":"（表情）难以琢磨的，微妙的"}]}},"unplug":{"collins":{"senses":[{"pos":"VERB 动词","cn":"拔掉…的(电源)插头","en":"If you unplug an electrical device or telephone, you pull a wire out of a socket so that it stops working.","ex":{"en":"I had to unplug the phone.","cn":"我不得不拔掉电话线。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make something stop working, for example by pressing a button - use this about things that use electricity, for example, lights, televisions, or computers","cn":""},{"en":"to make something stop working, for example by pressing a button or turning a tap - use this about things that use electricity, gas, or water","cn":""},{"en":"to make an engine or a machine stop working","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/c/unplug0205.mp3","us":"media/ldoce/hwd/ame/7/unplug.mp3"},"examples":[{"en":"Unplug the TV before you go to bed.","cn":"睡前拔下电视机的插头。"}],"oxford":{"phon":"ˌʌnˈplʌɡ","pos":"verb","senses":[{"en":"to remove the plug of a piece of electrical equipment from the electricity supply","cn":"拔掉…的电源插头","ex":{"en":"If I’m very busy, I unplug the phone.","cn":"要是我特别忙，我就把电话线拔掉。"}}]}},"unsociable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不善交际的；不合群的","en":"Someone who is unsociable does not like talking to other people and tries to avoid meeting them.","ex":{"en":"My marriage has broken up. It has made me reclusive and unsociable","cn":"我的婚姻破裂了。这让我变得孤僻、不愿与人来往。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not wanting to be with people or to go to social events","cn":"不爱交际的﹐不合群的"}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41unsociable.mp3","us":"media/ldoce/hwd/ame/f/unsociable.mp3"},"oxford":{"phon":"ʌnˈsəʊʃəbl","pos":"adjective","senses":[{"en":"not enjoying the company of other people; not friendly","cn":"不爱交际的；不合群的","ex":{"en":"I was feeling very unsociable, so I didn’t go to the party.","cn":"我感觉自己不太想应酬，所以没去参加晚会。"}},{"en":"outside the normal times of working","cn":"非正常工作时间的；正常工作时间以外的","lab":"more frequent"}]}},"unconscionable":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"违背良心的","en":"If you describe something as unconscionable, you mean that the person responsible for it ought to be ashamed of it, especially because its effects are so great or severe.","ex":{"en":"It's unconscionable for the government to do anything for a man who admits to smuggling 135 tons of cocaine into the United States.","cn":"一个承认将135吨可卡因走私到美国的人，政府要再为他撑腰就太逆天背理了。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"much more than is reasonable or acceptable","cn":"不合理的﹔过度的﹔难以接受的"}]},"vocab":{"pos":"adj","senses":[{"en":"Something that is almost unimaginably unacceptable is unconscionable . Think of it as being something that no reasonable person would even think of doing or saying — something unbelievable, outrageous, and often horrible."}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41unconscionable.mp3","us":"media/ldoce/hwd/ame/e/unconscionable.mp3"},"examples":[{"en":"The war caused an unconscionable amount of suffering.","cn":"战争造成了太多的苦难。"}],"oxford":{"phon":"ʌnˈkɒnʃənəbl","pos":"adjective","senses":[{"en":"so bad, immoral, etc. that it should make you feel ashamed","cn":"违背良心的","ex":{"en":"It would be unconscionable for her to keep the money.","cn":"如果她保留这些钱，那就太不合情理了。"}},{"en":"too great, large, long, etc.","cn":"过分的；过于大（或多、长等）的","lab":"often humorous","ex":{"en":"You take an unconscionable amount of time getting dressed!","cn":"你穿衣服花了太多时间！"}}]}},"unafraid":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"不害怕的；不畏惧的","en":"If you are unafraid to do something, you are confident and not at all nervous about doing it.","ex":{"en":"He is a man with a reputation for being tough and unafraid of unpopular decisions","cn":"他作风强悍，作决定不怕得罪人，这是出了名的。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not frightened","cn":"不害怕的﹐不畏惧的"},{"en":"confident that you can do something or deal with something","cn":"勇于(做某事)的"}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41unafraid.mp3","us":"media/ldoce/hwd/ame/5/ld41unafraid.mp3"},"examples":[{"en":"He's unafraid to speak his mind.","cn":"他勇于说出心里话。"},{"en":"She was unafraid of conflict.","cn":"她不怕发生冲突。"}],"oxford":{"phon":"ˌʌnəˈfreɪd","pos":"adjective","senses":[{"en":"not afraid or nervous; not worried about what might happen","cn":"不害怕；不畏惧；不紧张；无顾忌","ex":{"en":"She was unafraid of conflict.","cn":"她不怕发生冲突。"}}]}},"unworkable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不可行的；行不通的；办不成的","en":"If you describe something such as a plan, law, or system as unworkable, you believe that it cannot be successful.","ex":{"en":"There is the strong possibility that such cooperation will prove unworkable","cn":"这种合作很有可能会行不通。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"an unworkable plan, system, law etc is not likely to be successful 〔","cn":"计划﹑制度﹑法律等〕不可行的﹐行不通的"}]},"media":{"uk":"media/ldoce/hwd/bre/7/unworkable0205.mp3","us":"media/ldoce/hwd/ame/4/amelasdeunworkable.mp3"},"examples":[{"en":"The law as it stands is unworkable.","cn":"照现在的情形，这条法律是难以执行的。"},{"en":"an unworkable plan","cn":"不切实际的计划"}],"oxford":{"phon":"ʌnˈwɜːkəbl","pos":"adjective","senses":[{"en":"not practical or possible to do successfully","cn":"不切实际的；难以实行的；行不通的","ex":{"en":"an unworkable plan","cn":"不切实际的计划"}}]}},"unmistakable":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"清楚明白的；不会弄错的；确定无疑的","en":"If you describe something as unmistakable, you mean that it is so obvious that it cannot be mistaken for anything else.","ex":{"en":"He didn't give his name, but the voice was unmistakable.","cn":"他没留下姓名，但是那个声音是绝不会错的。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"something that is obvious is very easy to notice or understand – used especially when you are surprised that other people cannot notice it","cn":""},{"en":"easy to notice that something is true, so that you feel sure about it and have no doubts","cn":""},{"en":"very easy to notice, especially because you can see, hear, smell, or feel something","cn":""}]},"collocations":{"phrases":["VERBS be","ADV. quite The main symptom is a scarlet rash that's quite unmistakable."]},"media":{"uk":"media/ldoce/hwd/bre/7/unmistakable0205.mp3","us":"media/ldoce/hwd/ame/9/unmistakable.mp3"},"examples":[{"en":"Her accent was unmistakable.","cn":"她的口音是很明显的。"},{"en":"His accent was unmistakably British.","cn":"他明显地操英国口音。"}],"oxford":{"phon":"ˌʌnmɪˈsteɪkəbl","pos":"adjective","senses":[{"en":"that cannot be mistaken for somebody/something else","cn":"不会弄错的；确定无疑的；清楚明白的","ex":{"en":"Her accent was unmistakable.","cn":"她的口音是很明显的。"}}]}},"upscale":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（产品或服务）高档的,质优价高的","en":"Upscale is used to describe products or services that are expensive, of good quality, and intended to appeal to people in a high social class.","ex":{"en":"Vodka has acquired an upscale image in the US.","cn":"伏特加在美国已树立起高档商品的形象。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"relating to people from a high social class who have a lot of money","cn":"高消费阶层的﹐高端市场的"}]},"vocab":{"pos":"adj","senses":[{"en":"Things that are upscale are made for rich people — they are high class, well made, or just plain pricey."}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41upscale.mp3","us":"media/ldoce/hwd/ame/3/upscale.mp3"},"examples":[{"en":"an affluent upscale audience","cn":"富裕的高消费观众"}],"oxford":{"phon":"ˌʌpˈskeɪl","pos":"adverb","senses":[{"en":"in a way that involves buying or selling goods and services that are expensive and of high quality","cn":"向高档，向高级消费市场"},{"en":"designed for or used by people who belong to a high social class or have a lot of money","cn":"高档的；高级的","pos":"adjective"},{"en":"to make something better, bigger or more powerful","cn":"改进；扩大；升级","ex":{"en":"The pilot project will begin in three areas and then be upscaled to the entire state.","cn":"该试点项目将先在三个地区推行，然后扩展至整个州。"},"pos":"verb"},{"en":"to change a product so that it will be used or bought by people who have more money or belong to a higher social class","cn":"使（产品）更高档","ex":{"en":"The complimentary snacks at the bar have been upscaled.","cn":"酒吧的免费小吃已经升级。"},"pos":"verb"}]}},"utilise":{"collins":{"senses":[{"pos":"","cn":"","en":"→see: ;"}]}},"unmoved":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无动于衷的；冷漠的；无同情心的","en":"If you are unmoved by something, you are not emotionally affected by it.","ex":{"en":"Mr Bird remained unmoved by the corruption allegations","cn":"伯德先生对贪污指控一直无动于衷。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not showing your feelings","cn":""},{"en":"not showing any feelings and especially not showing friendliness, humour, or pleasure","cn":""},{"en":"not showing the feelings that people usually show in an upsetting situation, because you have to do a job or because you really have no feelings about the situation","cn":""}]},"collocations":{"phrases":["VERBS appear, be, seem, sound | remain | leave sb Her daughter's accident had left her curiously unmoved.","ADV. completely, entirely, quite, totally | largely, relatively | apparently | curiously","PREP. by He was quite unmoved by my anger."]},"media":{"uk":"media/ldoce/hwd/bre/f/unmoved0205.mp3","us":"media/ldoce/hwd/ame/7/unmoved.mp3"},"examples":[{"en":"Alice seemed totally unmoved by the whole experience.","cn":"艾丽斯似乎对整个经过十分冷漠。"},{"en":"She pleaded with him but he remained unmoved.","cn":"她苦苦哀求，可是他仍无动于衷。"}],"oxford":{"phon":"ˌʌnˈmuːvd","pos":"adjective","senses":[{"en":"not feeling sympathy or not feeling sad, especially in a situation where it would be normal to do so","cn":"冷漠的；无同情心的；无动于衷的","ex":{"en":"Alice seemed totally unmoved by the whole experience.","cn":"爱丽斯似乎对整个经过十分冷漠。"}}]}},"unclothed":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未穿衣服的；一丝不挂的；赤身裸体的","en":"If someone is unclothed, they are not wearing any clothes.","ex":{"en":"He learned how to draw the unclothed human frame","cn":"他学过如何画裸体。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not wearing clothes","cn":"未穿衣服的﹐赤裸的"}]},"media":{"uk":"media/ldoce/hwd/bre/4/unclothed0205.mp3","us":"media/ldoce/hwd/ame/3/laadunclothed.mp3"},"oxford":{"phon":"ˌʌnˈkləʊðd","pos":"adjective","senses":[{"en":"not wearing any clothes","cn":"赤裸的；裸体的；一丝不挂的"}]}},"unforgettable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"难忘的","en":"If you describe something as unforgettable, you mean that it is, for example, extremely beautiful, enjoyable, or unusual, so that you remember it for a long time. You can also refer to extremely unpleasant things as unforgettable .","ex":{"en":"A visit to the Museum is an unforgettable experience","cn":"参观博物馆是一段令人难忘的经历。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"something that is memorable , especially an event or occasion, is so enjoyable, beautiful, unusual etc that you remember it for a long time","cn":""},{"en":"something such as an event or occasion that is unforgettable has such a powerful effect on you that you will never be able to forget it","cn":""},{"en":"an unforgettable experience, sight etc affects you so strongly that you will never forget it, especially because it is particularly good or beautiful","cn":"难以忘怀的"}]},"vocab":{"pos":"adj","senses":[{"en":"Use the adjective unforgettable to describe things that are so meaningful or important that you could never forget them, like the taste of your grandma's apple pie or your first kiss."}]},"collocations":{"phrases":["VERBS be","ADV. quite, totally, truly It was a truly unforgettable experience. | pretty"]},"media":{"uk":"media/ldoce/hwd/bre/0/unforgettable0205.mp3","us":"media/ldoce/hwd/ame/3/unforgettable.mp3"},"examples":[{"en":"A visit to Morocco is a truly unforgettable experience.","cn":"摩洛哥之行绝对是令人难忘的经历。"}],"oxford":{"phon":"ˌʌnfəˈɡetəbl","pos":"adjective","senses":[{"en":"if something is unforgettable, you cannot forget it, usually because it is so beautiful, interesting, pleasant, etc.","cn":"难以忘怀的；令人难忘的","ex":{"en":"The music is what makes the movie so unforgettable.","cn":"音乐让这部电影如此令人难忘。"}}]}},"unicorn":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（故事和传说中的）独角兽","en":"In stories and legends, a unicorn is an imaginary animal that looks like a white horse and has a horn growing from its forehead."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an imaginary animal like a white horse with a long straight horn growing on its head 〔","cn":"传说中似白马的〕独角兽"}]},"vocab":{"pos":"n","senses":[{"en":"A unicorn is a mythical horse-like creature which has one horn on its forehead. During the Middle Ages, a unicorn horn was said to have magical healing properties."}]},"media":{"uk":"media/ldoce/hwd/bre/c/unicorn0205.mp3","us":"media/ldoce/hwd/ame/f/unicorn.mp3"},"oxford":{"phon":"ˈjuːnɪkɔːn","pos":"noun","senses":[{"en":"(in stories) an animal like a white horse with a long straight horn on its head","cn":"（传说中的）独角兽"},{"en":"a new company valued at more than a billion dollars, typically in the software or technology sector","cn":"独角兽公司：市值超过十亿美元的新公司，通常在软件或技术领域","ex":{"en":"The report examines the ascent of start-ups and how unicorns are changing.","cn":"该报告探讨了初创企业的崛起以及独角兽企业的变化。"}}]}},"untypical":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"非典型的；不突出的；泛泛的","en":"If someone or something is untypical of a particular type of person or thing, they are not a good example of the way that type of person or thing normally is. People sometimes say something is not untypical when they mean that it is quite normal.","ex":{"en":"Anita Loos was in many respects untypical of the screenwriting trade","cn":"在许多方面，安妮塔·卢斯看着都不像是从事剧本创作这一行的。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"belonging to a type or group, but not having the usual qualities of that type or group","cn":""},{"en":"not typical of a situation or of someone's character, and therefore surprising","cn":""},{"en":"if you say it is not like someone or is unlike them to do something, you mean it is not typical of them to behave in that way, and it is strange or surprising","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41untypical.mp3","us":"media/ldoce/hwd/ame/0/ld41untypical.mp3"},"examples":[{"en":"Schools in this area are quite untypical of schools in the rest of the country.","cn":"这个地区的学校根本不能代表全国其他地区的学校。"},{"en":"All in all, it had been a not untypical day (= it had been very like other days).","cn":"总而言之，那一天平平常常，并没有什么特别。"}],"oxford":{"phon":"ʌnˈtɪpɪkl","pos":"adjective","senses":[{"en":"not typical","cn":"不典型的；无代表性的；无特征的","ex":{"en":"an untypical example","cn":"非典型的例子"}}]}},"uninhabitable":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"无法居住的；不适合居住的","en":"If a place is uninhabitable, it is impossible for people to live there, for example because it is dangerous or unhealthy.","ex":{"en":"About 90 percent of the city's single-family homes are uninhabitable","cn":"该市约90％的独户住宅都不适合居住。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a building or area of land that is habitable is suitable for people to live in, for example because it is clean enough, warm enough, safe enough etc","cn":""},{"en":"if a building is fit to live in , it is in a suitable condition for people to live in it","cn":""},{"en":"not suitable for living in or on","cn":""}]},"collocations":{"phrases":["VERBS be, look, remain, seem | become | make sth, render sth houses made uninhabitable by radioactive contamination | declare sth Fifty home","ADV. totally | almost, virtually | permanently"]},"media":{"uk":"media/ldoce/hwd/bre/7/uninhabitable0205.mp3","us":"media/ldoce/hwd/ame/5/uninhabitable.mp3"},"examples":[{"en":"The building was totally uninhabitable.","cn":"这栋大楼根本没法住人。"},{"en":"Much of the country is uninhabitable because it is desert.","cn":"由于地处沙漠﹐这个国家的许多地区不适宜居住。"}],"oxford":{"phon":"ˌʌnɪnˈhæbɪtəbl","pos":"adjective","senses":[{"en":"not fit to live in; impossible to live in","cn":"不宜居住的；无法居住的","ex":{"en":"The building was totally uninhabitable.","cn":"这栋大楼根本没法住人。"}}]}},"unhook":{"collins":{"senses":[{"pos":"VERB 动词","cn":"解开（衣服）的钩扣","en":"If you unhook a piece of clothing that is fastened with hooks, you undo the hooks.","ex":{"en":"She unhooked her dress.","cn":"她解开裙子的钩扣。"}},{"pos":"VERB 动词","cn":"把…从钩上取下","en":"If you unhook something that is held in place by hooks, you open it or remove it by undoing the hooks.","ex":{"en":"Chris unhooked the shutters and went out on the balcony.","cn":"克里斯拉开百叶窗，走到了阳台上。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to unfasten or remove something from a hook","cn":"从钩子上取下"}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41unhook.mp3","us":"media/ldoce/hwd/ame/3/laadunhook.mp3"},"examples":[{"en":"He unhooked his coat from the door.","cn":"他从门上取下外衣。"},{"en":"She unhooked her bra.","cn":"她解开了胸罩。"}],"oxford":{"phon":"ʌnˈhʊk","pos":"verb","senses":[{"en":"to remove something from a hook; to unfasten the hooks on clothes, etc.","cn":"从钩子上取下；解开（衣物等）的钩子","ex":{"en":"He unhooked his coat from the door.","cn":"他从门上取下外衣。"}}]}},"unpack":{"collins":{"senses":[{"pos":"VERB 动词","cn":"打开（箱、盒等）；（从箱、盒等中）取出","en":"When you unpack a suitcase, box, or similar container, or you unpack the things inside it, you take the things out of the container.","ex":{"en":"He unpacked his bag","cn":"他打开了包。"}},{"pos":"VERB 动词","cn":"分析；剖析；仔细考虑","en":"If you unpack an idea or problem, you analyse it and consider it in detail.","ex":{"en":"A lot of ground has been covered in unpacking the issues central to achieving this market-led strategic change.","cn":"在分析实现这个以市场为导向的战略转变的关键问题时，涉及了诸多领域。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to take everything out of a box, bag, suitcase etc","cn":"打开〔盒子﹑包﹑手提箱等〕取出物品"},{"en":"to make an idea or problem easier to understand by considering all the parts of it separately","cn":"分析﹐剖析"}]},"vocab":{"pos":"v","senses":[{"en":"To unpack is to take stuff out that's been packed, like the clothing in your suitcase or the fragile item that's been buried in ten thousand Styrofoam peanuts."}]},"media":{"uk":"media/ldoce/hwd/bre/8/unpack0205.mp3","us":"media/ldoce/hwd/ame/b/unpack.mp3"},"examples":[{"en":"She unpacked all the clothes she needed and left the rest in the case.","cn":"她取出所有要穿的衣服，其余的都留在箱子里。"},{"en":"I unpacked my bags as soon as I arrived.","cn":"我一到达就打开行李袋，把东西取出来。"}],"oxford":{"phon":"ˌʌnˈpæk","pos":"verb","senses":[{"en":"to take things out of a bag, case, etc.","cn":"打开（箱、包等）取；从（箱、包等中）取出","g":"[transitive, intransitive]","ex":{"en":"I unpacked my bags as soon as I arrived.","cn":"我一到达就打开行李袋，把东西取出来。"}},{"en":"to separate something into parts so that it is easier to understand","cn":"分析；剖析","g":"[transitive]","ex":{"en":"to unpack a theory","cn":"剖析一个理论"}}]}},"utopia":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"乌托邦；理想国；理想的完美社会","en":"If you refer to an imaginary situation as a utopia, you mean that it is one in which society is perfect and everyone is happy, but which you feel is not possible.","ex":{"en":"We weren't out to design a contemporary utopia.","cn":"我们并不是要设计一个现代乌托邦。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a utopian society is one in which you imagine there is a perfect social or political situation, although this is unlikely to ever really exist","cn":""},{"en":"an idealized view or description of something considers or shows it as perfect when really it is not","cn":""},{"en":"an imaginary perfect world where everyone is happy","cn":"乌托邦〔想象中的完美世界〕"}]},"vocab":{"pos":"n","senses":[{"en":"Utopia is a perfect paradise that doesn’t exist, but which we all dream of anyway. In the dead of winter, we might imagine a utopia full of palm trees, warm breezes, and sun-soaked beaches."}]},"media":{"uk":"media/ldoce/hwd/bre/a/utopia0205.mp3","us":"media/ldoce/hwd/ame/a/utopia.mp3"},"oxford":{"phon":"juːˈtəʊpiə","pos":"noun","senses":[{"en":"an imaginary place or state in which everything is perfect","cn":"乌托邦；空想的完美境界"}]}},"unimpeded":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未受阻止的；未受妨碍的","en":"If something moves or happens unimpeded, it continues without being stopped or interrupted by anything.","ex":{"en":"We drove, unimpeded by anyone, to Arras","cn":"我们一路畅行至阿拉斯。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"happening or moving without being stopped or having difficulty","cn":"无障碍的﹐无阻挡的"}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41unimpeded.mp3","us":"media/ldoce/hwd/ame/2/laadunimpeded.mp3"},"examples":[{"en":"an unimpeded view of the bay","cn":"一览无余的海湾风光"},{"en":"free and unimpeded trade","cn":"自由顺畅的贸易"}],"oxford":{"phon":"ˌʌnɪmˈpiːdɪd","pos":"adjective","senses":[{"en":"with nothing blocking or stopping somebody/something","cn":"无障碍的；无阻挡的","ex":{"en":"an unimpeded view of the bay","cn":"一览无余的海湾风光"}}]}},"underemployed":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（人）未尽其才的，大材小用的","en":"If someone is underemployed, they have not got enough work to do, or their work does not make full use of their skills or abilities.","ex":{"en":"He was underemployed and not satisfied with his work.","cn":"他的才干得不到充分施展，因此他不满意自己的工作。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"working in a job where you cannot use all your skills or where there is not enough work for you to do","cn":"大材小用的﹐未能人尽其才的﹔就业不足的"}]},"media":{"uk":"media/ldoce/hwd/bre/3/underemployed0205.mp3","us":"media/ldoce/hwd/ame/5/laadunderemployed.mp3"},"oxford":{"phon":"ˌʌndərɪmˈplɔɪd","pos":"adjective","senses":[{"en":"not having enough work to do; not having work that makes full use of your skills and abilities","cn":"未充分就业的（指就业不足、没有足够的工作可做，或所做的工作未能充分发挥技能）"}]}},"unimpressive":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"给人印象不深的；平常的；不起眼的","en":"If you describe someone or something as unimpressive, you mean they appear very ordinary, without any special or exciting qualities.","ex":{"en":"...even though Manchester United have looked unimpressive over recent weeks","cn":"尽管曼彻斯特联队在近几周表现平平"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not good enough to impress anyone","cn":""},{"en":"not as good, large etc as expected or necessary","cn":"给人印象不深的﹔不惹人注意的﹐平淡的"}]},"media":{"uk":"media/ldoce/hwd/bre/5/unimpressive0205.mp3","us":"media/ldoce/hwd/ame/8/laadunimpressive.mp3"},"examples":[{"en":"His academic record was unimpressive.","cn":"他的学业成绩平平。"},{"en":"unimpressive test results","cn":"平平的测试结果"}],"oxford":{"phon":"ˌʌnɪmˈpresɪv","pos":"adjective","senses":[{"en":"ordinary; not special in any way","cn":"普通的；寻常的；毫无特色的","ex":{"en":"His academic record was unimpressive.","cn":"他的学业成绩平平。"}}]}},"undergarment":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"内衣","en":"Undergarments are items of clothing that you wear next to your skin and under your other clothes.","ex":{"en":"...Rigby and Peller, who make undergarments for women.","cn":"制作女式内衣的里格比和佩勒"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a piece of underwear","cn":"内衣"}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41undergarment.mp3","us":"media/ldoce/hwd/ame/0/undergarment.mp3"},"oxford":{"phon":"ˈʌndəɡɑːmənt","pos":"noun","senses":[{"en":"a piece of underwear","cn":"内衣"}]}},"unjustifiable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（尤指伤害他人的行为）不能证明为正当的，无可辩解的，没有道理的","en":"If you describe an action, especially one that harms someone, as unjustifiable, you mean there is no good reason for it.","ex":{"en":"Using these missiles to down civilian aircraft is simply immoral and totally unjustifiable.","cn":"用这些导弹击落民用飞机是极不道德也是完全没道理的。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"something such as criticism or bad treatment of someone that is unjustified is unfair and cannot be shown to have a good reason","cn":""},{"en":"not fair, reasonable, or true","cn":""},{"en":"unreasonable demands, requests, orders etc are unfair and not based on any good reason","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/b/unjustifiable0205.mp3","us":"media/ldoce/hwd/ame/2/laadunjustifiable.mp3"},"examples":[{"en":"an unjustifiable delay","cn":"无理的拖延"},{"en":"Poisoning the Earth’s atmosphere is ecologically and morally unjustifiable.","cn":"污染地球的大气在生态上和道德上都是不能接受的。"}],"oxford":{"phon":"ˌʌnˌdʒʌstɪˈfaɪəbl","pos":"adjective","senses":[{"en":"impossible to excuse or accept because there is no good reason for it","cn":"不可原谅的；无法接受的；无正当理由的","ex":{"en":"an unjustifiable delay","cn":"无理的拖延"}}]}},"underline":{"collins":{"senses":[{"pos":"VERB 动词","cn":"强调；凸显","en":"If one thing, for example an action or an event, underlines another, it draws attention to it and emphasizes its importance.","ex":{"en":"The report underlined his concern that standards were at risk","cn":"报告强调了他对道德水准可能会受影响所表示的关注。"}},{"pos":"VERB 动词","cn":"在…下画线","en":"If you underline something such as a word or a sentence, you draw a line underneath it in order to make people notice it or to give it extra importance.","ex":{"en":"Underline the following that apply to you","cn":"在符合自身情况的项下画线。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to say strongly or show clearly that a fact, idea etc is especially important","cn":""},{"en":"to emphasize something when you are talking about a subject","cn":""},{"en":"to show that something is important, so that people will pay special attention to it","cn":""}]},"collocations":{"phrases":["ADV. heavily The word &lsquo;not&rsquo; was heavily underlined. 2 emphasize sth","ADV. clearly | just, merely, only, simply This disaster merely underlines the need for a consistent foreign policy. | further","VERB + UNDERLINE serve to | seem to | be intended to a move intended to underline US concern over the issue","PHRASES underline the fact that &hellip;"]},"media":{"uk":"media/ldoce/hwd/bre/0/brelasdeunderline.mp3","us":"media/ldoce/hwd/ame/c/underline.mp3"},"examples":[{"en":"The report underlined that the project enjoyed considerable support in both countries.","cn":"这份报告强调该项目得到两国的极大支持。"},{"en":"It should be underlined that these are only preliminary findings.","cn":"需要强调的是，这些只是初步的研究结果。"}],"oxford":{"phon":"ˌʌndəˈlaɪn","pos":"verb","senses":[{"en":"to draw or print a line under a word, sentence, etc.","cn":"在（词语、句子等）下画线；画（或印）底线标出","ex":{"en":"The names of the winners are underlined in red.","cn":"获奖者的名字用红色下划线标出。"}},{"en":"to emphasize or show that something is important or true","cn":"强调；突出","ex":{"en":"The report underlines the importance of pre-school education.","cn":"这份报告强调学前教育的重要性。"}}]}},"unluckily":{"collins":{"senses":[{"pos":"ADV 副词","cn":"不幸地；不走运地","en":"You use unluckily as a comment on something bad or unpleasant that happens to someone, in order to suggest sympathy for them or that it was not their fault.","ex":{"en":"Unluckily for him, the fraud officers were watching this flight too","cn":"对他而言不幸的是，那些反诈骗官员也在密切注视着这个航班。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"having bad luck, or causing bad luck","cn":""},{"en":"unlucky because something bad happens to you that you do not deserve. Unfortunate sounds rather formal and is used mainly in writing","cn":""},{"en":"if something is bad luck or brings bad luck, it is believed to make bad things happen","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/8/unlucky0205.mp3","us":"media/ldoce/hwd/ame/c/unlucky.mp3"},"examples":[{"en":"He was injured in the first game and unluckily missed the final.","cn":"他第一场比赛就受了伤，遗憾地未能参加决赛。"},{"en":"Inter Milan were unlucky to lose the match.","cn":""}],"oxford":{"phon":"ʌnˈlʌkɪli","pos":"adverb","senses":[{"en":"unfortunately; as a result of bad luck","cn":"不幸地；遗憾地；倒霉地","ex":{"en":"He was injured in the first game and unluckily missed the final.","cn":"他第一场比赛就受了伤，遗憾地未能参加决赛。"}}]}},"unacknowledged":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"被忽视的；未被注意的","en":"If you describe something or someone as unacknowledged, you mean that people ignore their existence or presence, or are not aware of it.","ex":{"en":"Unresolved or unacknowledged fears can trigger sleepwalking.","cn":"残留在心里的或不为人知的恐惧都可能引发梦游。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"未获认可的；未得到承认的","en":"If you describe something or someone as unacknowledged, you mean that their existence or importance is not recognized officially or publicly.","ex":{"en":"This tradition goes totally unacknowledged in official guidebooks","cn":"这种传统在正式的指导手册中根本未得到承认。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"ignored or not noticed","cn":"未受到注意[重视]的"},{"en":"not receiving the public thanks, praise, or reward that something deserves","cn":"没有得到〔应有的〕感谢[赞扬﹐奖励]的"},{"en":"someone who is a leader etc but who has not publicly or officially been given that position","cn":"没有得到正式承认的领导/权威等"}]},"media":{"uk":"media/ldoce/hwd/bre/1/unacknowledged0205.mp3","us":"media/ldoce/hwd/ame/0/laadunacknowledged.mp3"},"examples":[{"en":"Her contribution to the research went largely unacknowledged.","cn":"她对这项研究的贡献大都被忽略了。"},{"en":"the unacknowledged leader of the group","cn":"这个团体非正式任命的首领"}],"oxford":{"phon":"ˌʌnəkˈnɒlɪdʒd","pos":"adjective","senses":[{"en":"not receiving the thanks or praise that is deserved","cn":"未得到应有的感激（或赞赏）的","ex":{"en":"Her contribution to the research went largely unacknowledged.","cn":"她对这项研究的贡献大都被忽略了。"}},{"en":"that people do not admit as existing or true; that people are not aware of","cn":"不被承认存在（或真实）的；未被意识到的","ex":{"en":"unacknowledged feelings","cn":"下意识的感情"}},{"en":"not publicly or officially recognized","cn":"未得到公开（或正式）承认的；非正式的","ex":{"en":"the unacknowledged leader of the group","cn":"这个团体非正式任命的首领"}}]}},"unshaven":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"没刮胡子的；未刮过脸的","en":"If a man is unshaven, he has not shaved recently and there are short hairs on his face or chin.","ex":{"en":"His hair was disheveled, and his face was unshaven and gray.","cn":"他头发凌乱，没刮胡子，脸色苍白。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a man who is unshaven has very short hairs growing on his face because he has not shave d 〔","cn":"男子〕未剃须的﹐未修面的"}]},"media":{"uk":"media/ldoce/hwd/bre/d/unshaven0205.mp3","us":"media/ldoce/hwd/ame/a/unshaven.mp3"},"examples":[{"en":"He looked pale and unshaven.","cn":"他面色苍白，胡子也没刮。"},{"en":"his unshaven face","cn":"他那张没刮的脸"}],"oxford":{"phon":"ˌʌnˈʃeɪvn","pos":"adjective","senses":[{"en":"not having shaved or been shaved recently","cn":"未刮脸的；未剃须的","ex":{"en":"He looked pale and unshaven.","cn":"他面色苍白，胡子也没刮。"}}]}},"unquestioned":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"不容置疑的；无可争议的","en":"You use unquestioned to emphasize that something is so obvious, real, or great that nobody can doubt it or disagree with it.","ex":{"en":"His commitment has been unquestioned","cn":"他的忠诚是不容置疑的。"}},{"pos":"ADJ 形容词","cn":"公认的；没有异议的","en":"If something or someone is unquestioned, they are accepted by everyone, without anyone doubting or disagreeing.","ex":{"en":"He is the best player on an excellent team and their unquestioned leader.","cn":"他是一支优秀球队中最好的球员，也是大家公认的领袖。"}},{"pos":"ADJ 形容词","cn":"毫无异议的;毫无疑问的","en":"If you describe someone's belief or attitude as unquestioned, you are emphasizing that they accept something without any doubt or disagreement.","ex":{"en":"Royalty is regarded with unquestioned reverence.","cn":"王室成员毫无争议地受到尊重。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"something that is unquestioned is accepted or believed by everyone","cn":"无争议的﹔公认的"}]},"media":{"uk":"media/ldoce/hwd/bre/a/unquestioned0205.mp3","us":"media/ldoce/hwd/ame/9/laadunquestioned.mp3"},"examples":[{"en":"His courage remains unquestioned.","cn":"他的勇敢仍然不容置疑。"},{"en":"an unquestioned assumption","cn":"盲目接受的假设"}],"oxford":{"phon":"ʌnˈkwestʃənd","pos":"adjective","senses":[{"en":"so obvious that it cannot be doubted","cn":"显而易见的；无可争议的；毋庸置疑的；公认的","ex":{"en":"His courage remains unquestioned.","cn":"他的勇敢仍然不容置疑。"}},{"en":"accepted as right or true without really being considered","cn":"不假思索而认可的；盲目接受的","ex":{"en":"an unquestioned assumption","cn":"盲目接受的假设"}}]}},"unholy":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"极不合理的；极令人厌恶的","en":"You use unholy to emphasize how unreasonable or unpleasant you think something is.","ex":{"en":"She protested that it wasn't traditional jazz at all, but an unholy row","cn":"她抗议说那根本不是传统爵士乐，而是令人憎恶的噪音。"}},{"pos":"ADJ 形容词","cn":"（由通常敌对的两方或多方组成的联盟）不同寻常的，诡异的","en":"If you refer to two or more people or groups working together as an unholy alliance, you mean that this arrangement is unusual because the people usually oppose each other.","ex":{"en":"If the government does fall it will be because of this unholy alliance between the far right and the left","cn":"如果政府真的倒台了，那一定是因为极右翼势力和左翼势力的诡异联盟。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"邪恶的；罪恶的；亵渎的","en":"If you describe something as unholy, you mean that it is wicked or bad.","ex":{"en":"'This ought to be fun,' he told Alex, eyes gleaming with an almost unholy relish","cn":"“这一定会很有趣,”他对亚历克斯说，眼神里几乎透出一丝邪恶的光芒。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"an agreement between two people or organizations who would not normally work together, usually for a bad purpose","cn":"邪恶的同盟"},{"en":"bad and extreme","cn":"可怕的﹔极端的﹔令人无法容忍的"},{"en":"not holy, or not respecting what is holy","cn":"不神圣的﹔不虔敬的﹔亵渎神灵的"}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41unholy.mp3","us":"media/ldoce/hwd/ame/0/unholy.mp3"},"examples":[{"en":"She wondered how she had got into this unholy mess.","cn":"她不知道自己如何弄得如此狼狈不堪。"},{"en":"an unholy alliance between the medical profession and the pharmaceutical industry","cn":"医疗界与医药业的不当联盟"}],"oxford":{"phon":"ʌnˈhəʊli","pos":"adjective","senses":[{"en":"dangerous; likely to be harmful","cn":"危险的；有害的","ex":{"en":"an unholy alliance between the medical profession and the pharmaceutical industry","cn":"医疗界与医药业的不当联盟"}},{"en":"not respecting the laws of a religion","cn":"不守教规的；亵渎神明的；罪恶的"},{"en":"used to emphasize how bad something is","cn":"（强调糟糕的程度）极端的，极坏的","g":"[only before noun]","lab":"informal","ex":{"en":"She wondered how she had got into this unholy mess.","cn":"她不知道自己如何弄得如此狼狈不堪。"}}]}},"unrecognizable":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"无法辨别的；难以辨认的","en":"If someone or something is unrecognizable, they have become impossible to recognize or identify, for example because they have been greatly changed or damaged.","ex":{"en":"The corpses of the prisoners were nearly unrecognizable from the number of bullet wounds they'd received","cn":"囚犯的尸体上中枪太多，几乎无法辨认。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a strange person, voice, smell etc one that is not recognizable because it is different from other, similar things that you know already","cn":""},{"en":"difficult or impossible to recognize","cn":""},{"en":"something that is unfamiliar is not recognizable because you have never seen it, heard it, done it etc before","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/e/brelasdeunrecognizable.mp3","us":"media/ldoce/hwd/ame/0/laadunrecognizable.mp3"},"examples":[{"en":"He was unrecognizable without his beard.","cn":"他刮掉胡子，无人认得出他了。"},{"en":"I hadn’t been to the city for 20 years and it was almost unrecognizable.","cn":"我已经20年没有到过这座城市﹐几乎认不出来了。"}],"oxford":{"phon":"ˌʌnrekəɡˈnaɪzəbl","pos":"adjective","senses":[{"en":"so changed or damaged that you do not recognize them or it","cn":"变得（或损坏得）难以辨认的；无法识别的","ex":{"en":"He was unrecognizable without his beard.","cn":"他刮掉胡子，无人认得出他了。"}}]}},"unjustified":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未被证明为正当的；无法解释的；无法开脱的","en":"If you describe a belief or action as unjustified, you think that there is no good reason for having it or doing it.","ex":{"en":"Your report last week was unfair. It was based upon wholly unfounded and totally unjustified allegations","cn":"你上周的报告是不公平的。它是基于毫无根据且完全无端的指控。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"something such as criticism or bad treatment of someone that is unjustified is unfair and cannot be shown to have a good reason","cn":""},{"en":"not fair, reasonable, or true","cn":""},{"en":"unreasonable demands, requests, orders etc are unfair and not based on any good reason","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Whether it’s unjustified violence, an unjustified complaint, or an unjustified belief, you can use the word unjustified when something just isn’t right or seems to have no reason behind it."}]},"media":{"uk":"media/ldoce/hwd/bre/f/unjustified0205.mp3","us":"media/ldoce/hwd/ame/c/laadunjustified.mp3"},"examples":[{"en":"The criticism was wholly unjustified.","cn":"这样的批评完全是不公平的。"},{"en":"unjustified price increases","cn":"无端的涨价"}],"oxford":{"phon":"ˌʌnˈdʒʌstɪfaɪd","pos":"adjective","senses":[{"en":"not fair or necessary","cn":"不公正的；不正当的；不必要的","ex":{"en":"The criticism was wholly unjustified.","cn":"这样的批评完全是不公平的。"}}]}},"unmask":{"collins":{"senses":[{"pos":"VERB 动词","cn":"揭露；揭发","en":"If you unmask someone or something bad, you show or make known their true nature or character, when they had previously been thought to be good.","ex":{"en":"Mr Burkett has unmasked several hundred impostors.","cn":"伯克特先生已经揭穿了数百个冒名顶替者。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make known the hidden truth about someone","cn":"揭露﹐揭穿〔真相〕"}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41unmask.mp3","us":"media/ldoce/hwd/ame/8/unmask.mp3"},"examples":[{"en":"to unmask a spy","cn":"揭发间谍"},{"en":"He was one of the most high-ranking spies ever unmasked by the CIA.","cn":"他是中央情报局所揭露的最高级别的间谍之一。"}],"oxford":{"phon":"ˌʌnˈmɑːsk","pos":"verb","senses":[{"en":"to show the true character of somebody, or a hidden truth about something","cn":"使露出真相；揭露；暴露","ex":{"en":"to unmask a spy","cn":"揭发间谍"}}]}},"unmarried":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未婚的","en":"Someone who is unmarried is not married.","ex":{"en":"They refused to rent an apartment to an unmarried couple.","cn":"他们拒绝把公寓租给未婚情侣。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who is single is not married or is not in a permanent romantic relationship with anyone","cn":""},{"en":"an unmarried person is someone who has never been married","cn":""},{"en":"a man who has never been married","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/3/unmarried0205.mp3","us":"media/ldoce/hwd/ame/1/unmarried.mp3"},"examples":[{"en":"an unmarried mother","cn":"未婚母亲"},{"en":"unmarried mothers","cn":"未婚母亲"}],"oxford":{"phon":"ˌʌnˈmærid","pos":"adjective","senses":[{"en":"not married","cn":"未婚的；单身的","ex":{"en":"an unmarried mother","cn":"未婚母亲"}}]}},"ulcer":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"溃疡","en":"An ulcer is a sore area on the outside or inside of your body which is very painful and may bleed or produce an unpleasant poisonous substance.","ex":{"en":"...stomach ulcers.","cn":"胃溃疡"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a sore area on your skin or inside your body that may bleed or produce poisonous substances","cn":"溃疡"}]},"vocab":{"pos":"n","senses":[{"en":"A canker sore is a common form of ulcer or open sore. An ulcer can be on an external surface like the mouth or an internal surface, like the stomach. They are caused by a break in skin or mucus membrane that won't heal."}]},"media":{"uk":"media/ldoce/hwd/bre/b/ulcer0205.mp3","us":"media/ldoce/hwd/ame/9/ld44ulcer.mp3"},"examples":[{"en":"a stomach ulcer","cn":"胃溃疡"},{"en":"stomach ulcers","cn":"胃溃疡"}],"oxford":{"phon":"ˈʌlsə(r)","pos":"noun","senses":[{"en":"an open sore on the outside of the body or on the surface of an organ inside the body, where there is a break in the skin or membrane covering the organ that fails to heal (= get better) without treatment","cn":"溃疡","ex":{"en":"a stomach ulcer","cn":"胃溃疡"}}]}},"unending":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"不断的；不停的；无休止的","en":"If you describe something as unending, you mean that it continues without stopping for a very long time.","ex":{"en":"I do not recall any formal training, just endless work and an unending stream of people!","cn":"现在想起来，没有任何正式的培训，有的只是没完没了的工作和无休无止的人流！"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"use this about something annoying or unpleasant that continues for a long time without stopping","cn":""},{"en":"use this about an unpleasant or frightening situation that continues for a long time without stopping","cn":""},{"en":"use this about an unpleasant or upsetting situation that is always there and does not change","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41unending.mp3","us":"media/ldoce/hwd/ame/b/unending.mp3"},"examples":[{"en":"a seemingly unending supply of money","cn":"似乎源源不断的资金供应"},{"en":"an unending stream of people","cn":"源源不断的人流"}],"oxford":{"phon":"ʌnˈendɪŋ","pos":"adjective","senses":[{"en":"seeming to last forever","cn":"无尽的；源源不断的；不竭的","ex":{"en":"a seemingly unending supply of money","cn":"似乎源源不断的资金供应"}}]}},"unstoppable":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"不可抗拒的；不可阻挡的","en":"Something that is unstoppable cannot be prevented from continuing or developing.","ex":{"en":"The progress of science is unstoppable.","cn":"科学的前进步伐不可阻挡。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a process or action that is unstoppable cannot be stopped","cn":""},{"en":"a process that is remorseless continues in an unpleasant and threatening way and it seems to be impossible to stop","cn":""},{"en":"use this about a gradual process that cannot be stopped, especially one which leads to something very bad happening","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/3/unstoppable0205.mp3","us":"media/ldoce/hwd/ame/a/laadunstoppable.mp3"},"examples":[{"en":"On form, the team was simply unstoppable.","cn":"若状态良好，这个队伍简直势不可当。"},{"en":"an unstoppable rise in prices","cn":"无法遏止的价格上涨"}],"oxford":{"phon":"ʌnˈstɒpəbl","pos":"adjective","senses":[{"en":"that cannot be stopped or prevented","cn":"无法遏止的；不能防止的","ex":{"en":"an unstoppable rise in prices","cn":"无法遏止的价格上涨"}}]}},"unsightly":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"难看的；不悦目的；不雅观的","en":"If you describe something as unsightly, you mean that it is unattractive to look at.","ex":{"en":"My mother has had unsightly varicose veins for years","cn":"我母亲多年来一直患有难看的静脉曲张。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"very unpleasant to look at","cn":""},{"en":"something that is unsightly is unpleasant to look at, and spoils the appearance of the things around it","cn":""},{"en":"not at all pleasant to look at","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Unsightly is a gentler way of saying ugly . Often something that is described as unsightly sticks out like a sore thumb in an otherwise attractive environment."}]},"media":{"uk":"media/ldoce/hwd/bre/d/unsightly0205.mp3","us":"media/ldoce/hwd/ame/9/unsightly.mp3"},"examples":[{"en":"unsightly buildings","cn":"难看的楼房"},{"en":"unsightly marks","cn":"难看的污渍"}],"oxford":{"phon":"ʌnˈsaɪtli","pos":"adjective","senses":[{"en":"not pleasant to look at","cn":"难看的；不雅观的；不悦目的","ex":{"en":"an unsightly scar","cn":"难看的疤痕"}}]}},"undertow":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"潜在的情绪","en":"If there is an undertow of a feeling, that feeling exists in such a weak form that you are hardly aware of it, but it influences the way you think or behave.","ex":{"en":"The existence of an emotional undertow is an aspect of all politics.","cn":"具有情绪感召力是所有政治的一个方面。"}},{"pos":"N-COUNT 可数名词","cn":"潜流;下层逆流","en":"An undertow is a strong current of water that is moving below the surface current and in a different direction to it.","ex":{"en":"Dangerous undertows make swimming unsafe along most of the coastline.","cn":"由于存在着危险的下层逆流，在大部分海岸线附近游泳都不安全。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the water current under the surface of the sea, that pulls away from the land when a wave comes onto the shore","cn":"回流﹐水下逆流"},{"en":"a tendency or feeling that seems weak, but in fact has a strong effect","cn":"潜在的倾向[感觉]"}]},"vocab":{"pos":"n","senses":[{"en":"If you're nervous about swimming in the ocean, it may be because you were warned as a child about the undertow , or strong current, that might pull you beneath the surface."}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41undertow.mp3","us":"media/ldoce/hwd/ame/a/undertow.mp3"},"examples":[{"en":"The children were carried out to sea by the strong undertow.","cn":"强大的回流把孩子们卷到海里去了。"},{"en":"The dangerous undertow means that swimming is not allowed.","cn":"因存在危险的逆流，所以禁止游泳。"}],"oxford":{"phon":"ˈʌndətəʊ","pos":"noun","senses":[{"en":"a current in the sea or ocean that moves in the opposite direction to the water near the surface","cn":"回流；底流","ex":{"en":"The children were carried out to sea by the strong undertow.","cn":"强大的回流把孩子们卷到海里去了。"}},{"en":"a feeling or quality that influences people in a particular situation even though they may not really be aware of it","cn":"潜在的倾向（或特质）；感染力"}]}},"ulcerated":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"溃疡的；溃烂的","en":"If a part of someone's body is ulcerated, ulcers have developed on it.","ex":{"en":"...ulcerated mouths","cn":"溃疡的嘴巴"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to form an ulcer, or become covered with ulcers","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41ulcerate.mp3","us":"media/ldoce/hwd/ame/6/ulcerate.mp3"}},"unconstitutional":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"违反宪法的","en":"If something is unconstitutional, it breaks the rules of a political system.","ex":{"en":"The Moldavian parliament has declared the elections unconstitutional","cn":"摩尔达维亚议会已宣布选举违宪。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"forbidden by law","cn":""},{"en":"to be illegal. This phrase is very commonly used in everyday English, instead of saying that something is illegal","cn":""},{"en":"illegal – a rather formal word, which is used especially when this particular action is considered to be illegal, although there are some situations where such actions can be legal","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"When someone protests an action on the part of the government by saying, \"That's vile! That's wrong! That's downright unconstitutional !,\" they're saying that the action violates the tenets of the U.S. Constitution."}]},"media":{"uk":"media/ldoce/hwd/bre/4/unconstitution0205.mp3","us":"media/ldoce/hwd/ame/3/unconstitutional.mp3"},"examples":[{"en":"claims that the president’s action was unconstitutional","cn":"认为总统行为违宪的说法"}],"oxford":{"phon":"ˌʌnˌkɒnstɪˈtjuːʃənl","pos":"adjective","senses":[{"en":"not allowed by the constitution of a country, a political system or an organization","cn":"违背宪法的；违反宪章（或章程）的","ex":{"en":"The judges declared the decision unconstitutional.","cn":"法官宣布该决议违宪。"}}]}},"unchecked":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未被遏制的；未受到抑制的","en":"If something harmful or undesirable is left unchecked, nobody controls it or prevents it from growing or developing.","ex":{"en":"If left unchecked, weeds will flourish.","cn":"如果不加以遏制，杂草就会疯长。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"to let someone do something, or let something happen, especially something bad that you should try to stop. Allow is more formal than let","cn":""},{"en":"to let someone do something that they have chosen to do, although you could stop them, especially because they want to do it very much","cn":""},{"en":"if something bad or unpleasant happens unchecked , it is allowed to continue to happen because no one is controlling it when they should be","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/1/unchecked0205.mp3","us":"media/ldoce/hwd/ame/8/unchecked.mp3"},"examples":[{"en":"The plant will soon choke ponds and waterways if left unchecked.","cn":"如不控制这种植物的生长，池塘和水道很快就要被阻塞。"},{"en":"The rise in violent crime must not go unchecked.","cn":"暴力犯罪的增长必须加以制止。"}],"oxford":{"phon":"ˌʌnˈtʃekt","pos":"adjective","senses":[{"en":"if something harmful is unchecked, it is not stopped from getting worse","cn":"不加约束的；不受限制的；放任的","ex":{"en":"The fire was allowed to burn unchecked.","cn":"大火肆虐，不受控制。"}}]}},"untried":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未尝试过的;未经试验的","en":"If someone or something is untried, they have not yet experienced certain situations or have not yet been tried out, so you do not know what they will be like.","ex":{"en":"He was young and untried, with no reputation of his own.","cn":"他年纪轻，经验浅，没名气。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not having any experience of doing a particular job","cn":"无经验的﹐不熟练的"},{"en":"something that is untried has not been tested to see whether it is successful","cn":"未经试验的"}]},"media":{"uk":"media/ldoce/hwd/bre/a/brelasdeuntried.mp3","us":"media/ldoce/hwd/ame/e/laaduntried.mp3"},"examples":[{"en":"She chose two untried actors for the leading roles.","cn":"她选了两个没有经验的演员饰演主角。"},{"en":"This is a new and relatively untried procedure.","cn":"这是个未经多少试验的新程序。"}],"oxford":{"phon":"ˌʌnˈtraɪd","pos":"adjective","senses":[{"en":"without experience of doing a particular job","cn":"没有经验的","ex":{"en":"She chose two untried actors for the leading roles.","cn":"她选了两个没有经验的演员饰演主角。"}},{"en":"not yet tried or tested to discover if it works or is successful","cn":"未检验的；未经考验（或试验）的","ex":{"en":"This is a new and relatively untried procedure.","cn":"这是个未经多少试验的新程序。"}}]}},"unprovoked":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（攻击）非因触犯而发生的，无缘无故的","en":"If someone makes an unprovoked attack, they attack someone who has not tried to harm them in any way."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"something such as criticism or bad treatment of someone that is unjustified is unfair and cannot be shown to have a good reason","cn":""},{"en":"not fair, reasonable, or true","cn":""},{"en":"unreasonable demands, requests, orders etc are unfair and not based on any good reason","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Something that's unprovoked is done for no good reason, with no real cause. A slap across your face is unprovoked if you did nothing to make the slapper mad at you."}]},"collocations":{"phrases":["VERBS be","ADV. completely, totally a totally unprovoked attack"]},"media":{"uk":"media/ldoce/hwd/bre/d/unprovoked0205.mp3","us":"media/ldoce/hwd/ame/9/unprovoked.mp3"},"examples":[{"en":"Her angry outburst was totally unprovoked.","cn":"她暴跳如雷完全是无理取闹。"},{"en":"an act of unprovoked aggression","cn":"无端的侵犯行为"}],"oxford":{"phon":"ˌʌnprəˈvəʊkt","pos":"adjective","senses":[{"en":"not caused by anything the person being attacked has said or done","cn":"未受挑衅的；无端的","ex":{"en":"a vicious and unprovoked attack","cn":"恶毒的无端攻击"}}]}},"uppercut":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（拳击中的）上钩拳","en":"An uppercut is a type of punch used in boxing. It is a hard upward blow to the chin.","ex":{"en":"He was knocked down by an uppercut from Eubank.","cn":"他被尤班克一记上钩拳击倒在地。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a way of hitting someone in which you swing your hand up into their chin","cn":"上钩拳"}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41uppercut.mp3","us":"media/ldoce/hwd/ame/0/uppercut.mp3"},"oxford":{"phon":"ˈʌpəkʌt","pos":"noun","senses":[{"en":"a way of hitting somebody on the chin (= part of the face below the mouth), in which you bend your arm and move your hand upwards","cn":"上勾拳"}]}},"unbiased":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无偏见的；不偏不倚的；公正的","en":"If you describe someone or something as unbiased, you mean they are fair and not likely to support one particular person or group involved in something.","ex":{"en":"There is no clear and unbiased information available for consumers","cn":"消费者没有清晰明确、不偏不倚的信息可以参考。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not influenced by personal opinions or emotions, especially when you have to make a decision about something","cn":""},{"en":"able to make fair judgements or decisions about a situation because you do not support anyone who is involved in it","cn":""},{"en":"not supporting any side in a disagreement, argument, war etc","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"To be unbiased , you have to be 100% fair — you can't have a favorite, or opinions that would color your judgment. For example, to make things as unbiased as possible, judges of an art contest didn't see the artists' names or the names of their schools and hometowns."}]},"media":{"uk":"media/ldoce/hwd/bre/a/unbiased0205.mp3","us":"media/ldoce/hwd/ame/c/laadunbiased.mp3"},"examples":[{"en":"unbiased advice","cn":"客观的忠告"},{"en":"an unbiased judge","cn":"公正的法官"}],"oxford":{"phon":"ʌnˈbaɪəst","pos":"adjective","senses":[{"en":"fair and not influenced by your own or somebody else’s opinions, desires, etc.","cn":"公正的；不偏不倚的；无偏见的","ex":{"en":"unbiased advice","cn":"客观的忠告"}}]}},"unfunny":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不逗乐的；不好笑的","en":"If you describe something or someone as unfunny, you mean that they do not make you laugh, although this was their intention or purpose.","ex":{"en":"We became increasingly fed up with his increasingly unfunny and unintelligent comments.","cn":"我们越来越反感他益发无趣又缺乏见地的言论。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"an unfunny joke or action is not amusing, although it is intended to be – used to show disapproval 〔","cn":"玩笑、行为〕不滑稽的﹐不逗人发笑的﹐不幽默的〔含贬义〕"}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41unfunny.mp3","us":"media/ldoce/hwd/ame/4/laadunfunny.mp3"},"examples":[{"en":"The show was deeply unfunny.","cn":"这场演出毫无趣味。"}],"oxford":{"phon":"ʌnˈfʌni","pos":"adjective","senses":[{"en":"not funny, especially when something is supposed to be funny","cn":"索然无味的；没意思的；无趣的","ex":{"en":"The show was deeply unfunny.","cn":"这场演出毫无趣味。"}}]}},"unconditional":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"无条件的；无限制的","en":"If you describe something as unconditional, you mean that the person doing or giving it does not require anything to be done by other people in exchange.","ex":{"en":"Children need unconditional love","cn":"孩子们需要无条件的爱。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"an agreement or offer that is unconditional is made without any conditions","cn":""},{"en":"if you offer something or ask for something with no strings attached , you offer it or ask for it without stating any conditions and without trying to get an advantage for yourself","cn":""},{"en":"not limited by or depending on any conditions","cn":"不加限制的﹔无条件的"}]},"vocab":{"pos":"adj","senses":[{"en":"Whether it’s love, support, or surrender, if something’s unconditional it’s absolute and not subject to any special terms or conditions: it’ll happen no matter what else happens."}]},"media":{"uk":"media/ldoce/hwd/bre/a/unconditional0205.mp3","us":"media/ldoce/hwd/ame/8/unconditional.mp3"},"examples":[{"en":"She gave her children unconditional love.","cn":"她将爱毫无保留地给了她的孩子。"},{"en":"the unconditional surrender of military forces","cn":"军队的无条件投降"}],"oxford":{"phon":"ˌʌnkənˈdɪʃənl","pos":"adjective","senses":[{"en":"without any conditions or limits","cn":"无条件的；无限制的；绝对的","ex":{"en":"the unconditional surrender of military forces","cn":"军队的无条件投降"}}]}},"untangle":{"collins":{"senses":[{"pos":"VERB 动词","cn":"解开，解松（绳结）","en":"If you untangle something that is knotted or has become twisted around something, you undo the knots in it or free it.","ex":{"en":"He was found desperately trying to untangle several reels of film.","cn":"他被撞见拼命想要解开几盘缠在一起的胶卷。"}},{"pos":"VERB 动词","cn":"排解，解决，处理（混乱或复杂的局面）","en":"f you untangle a confused or complicated situation, you make the different things involved clear, or put the situation right.","ex":{"en":"Lawyers and accountants began trying to untangle the complex affairs of the bank","cn":"律师和会计师开始着手梳理这家银行复杂的事务。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to separate pieces of string, wire etc that are twisted together","cn":"解开〔绳﹑线等〕的结"},{"en":"to make something less complicated","cn":"理顺﹐整理〔某物〕"}]},"media":{"uk":"media/ldoce/hwd/bre/3/untangle0205.mp3","us":"media/ldoce/hwd/ame/c/untangle.mp3"},"examples":[{"en":"The research attempts to untangle some of these issues.","cn":"这项研究试图理清其中的一些问题。"}],"oxford":{"phon":"ˌʌnˈtæŋɡl","pos":"verb","senses":[{"en":"to separate pieces of string, hair, wire, etc. that have become twisted or have knots in them","cn":"解开，松开（结子等）","ex":{"en":"Can you untangle all those cables on the floor?","cn":"你能解开地板上所有缠结的电缆吗？"}},{"en":"to make something that is complicated or confusing easier to deal with or understand","cn":"整理；厘清","ex":{"en":"It will not be easy to untangle his financial affairs.","cn":"解决他的财务问题并不容易。"}}]}},"underestimate":{"collins":{"senses":[{"pos":"VERB 动词","cn":"低估；对…估计不足","en":"If you underestimate something, you do not realize how large or great it is or will be.","ex":{"en":"None of us should ever underestimate the degree of difficulty women face in career advancement","cn":"我们谁都不应该低估女性在事业发展过程中所面临的困难程度。"}},{"pos":"VERB 动词","cn":"低估;轻视;小看","en":"If you underestimate someone, you do not realize what they are capable of doing.","ex":{"en":"I think a lot of people still underestimate him","cn":"我觉得很多人仍然低估了他。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to count something wrongly","cn":""},{"en":"to forget how many things or people you have already counted, when you are counting a lot of things over a long period","cn":""},{"en":"to wrongly guess an amount, price or number by making the total too high","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"To underestimate is to guess that something is worth less or is smaller than it really is. You might underestimate the size of a one-pound hamburger until you realize it's too big to fit in your stomach."}]},"collocations":{"phrases":["ADJ. gross, serious The official figures are a gross underestimate of the true number.","PREP. ~ of"]},"media":{"uk":"media/ldoce/hwd/bre/5/underestimate_10205.mp3","us":"media/ldoce/hwd/ame/8/l3underestimate.mp3"},"examples":[{"en":"My guess of 400 proved to be a serious underestimate.","cn":"我猜 400，结果证明是严重的低估。"},{"en":"We underestimated the time it would take to get there.","cn":"我们低估了抵达那里所需的时间。"}],"oxford":{"phon":"ˌʌndərˈestɪmeɪt","pos":"verb","senses":[{"en":"to think or guess that the amount, cost or size of something is smaller than it really is","cn":"低估；对…估计不足","ex":{"en":"to underestimate the cost of the project","cn":"低估项目的成本"}},{"en":"to not realize how good, strong, determined, difficult, etc. somebody/something really is","cn":"对…认识不足（或重视不够）；低估；轻视","ex":{"en":"Never underestimate your opponent.","cn":"绝不可低估你的对手。"}},{"en":"an estimate about the size, cost, etc. of something that is too low","cn":"低估；轻视","ex":{"en":"My guess of 400 proved to be a serious underestimate.","cn":"我猜 400，结果证明是严重的低估。"},"pos":"noun"}]}},"unstressed":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"无重音的；非重读的","en":"If a word or syllable is unstressed, it is pronounced without emphasis.","ex":{"en":"...the unstressed syllable of words like 'above', 'surround' or 'arrive'.","cn":"above, surround, arrive 等单词的非重读音节"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"an unstressed word or part of a word is pronounced with less force than other ones 〔","cn":"单词或音节〕非重读的﹐轻读的"}]},"vocab":{"pos":"adj","senses":[{"en":"An unstressed syllable is the part of the word that you don't emphasize or accent, like the to - in today, or the - day in Sunday. An unstressed person is someone for whom every day feels like Sunday."}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41unstressed.mp3","us":"media/ldoce/hwd/ame/7/laadunstressed.mp3"},"oxford":{"phon":"ˌʌnˈstrest","pos":"adjective","senses":[{"en":"pronounced without emphasis","cn":"非重读的；轻读的"}]}},"undernourishment":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"营养不足；营养不良","en":"If someone is suffering from undernourishment, they have poor health because they are not eating enough food or are eating the wrong kind of food.","ex":{"en":"Forty per cent of children under five in developing countries are short for their age because of undernourishment.","cn":"在发展中国家，5岁以下的孩子中有40%因为营养不良而身高偏低。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"unhealthy and weak because you have not had enough food or the right type of food","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/c/undernourished0205.mp3","us":"media/ldoce/hwd/ame/7/undernourished.mp3"},"oxford":{"phon":"ˌʌndəˈnʌrɪʃmənt","pos":"noun","senses":[{"en":"the condition of being in bad health because of a lack of food or a lack of the right type of food","cn":"营养不良的；缺乏营养的"}]}},"usaf":{"collins":{"senses":[{"pos":"N-PROPER 专有名词","cn":"美国空军","en":"The USAF is an abbreviation for (缩略=) the United States Air Force ."}]},"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"the abbreviation of the United States Air Force","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/f/p028-000012456.mp3","us":"media/ldoce/hwd/ame/7/laadusaf.mp3"},"oxford":{"phon":"ˌjuː es eɪ ˈef","pos":"abbreviation","senses":[{"en":"United States Air Force","cn":"美国空军"}]}},"unattainable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无法实现的；难以得到的","en":"If you say that something is unattainable, you mean that it cannot be achieved or is not available.","ex":{"en":"There are those who argue that true independent advice is unattainable.","cn":"有一些人认为真正独立的意见是不存在的。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"something that is impossible cannot happen or be done","cn":""},{"en":"something that is impractical is too expensive, takes too much time, is too difficult etc and therefore it is not sensible to try to do it","cn":""},{"en":"used when saying that something is completely impossible, especially because it is not allowed","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Something unattainable is out of reach — you can't attain it or achieve it."}]},"media":{"uk":"media/ldoce/hwd/bre/d/unattainable0205.mp3","us":"media/ldoce/hwd/ame/9/laadunattainable.mp3"},"examples":[{"en":"an unattainable goal","cn":"难以达到的目标"},{"en":"A military victory is unattainable.","cn":"不可能取得军事胜利。"}],"oxford":{"phon":"ˌʌnəˈteɪnəbl","pos":"adjective","senses":[{"en":"impossible to achieve or reach","cn":"无法得到的；难以达到的","ex":{"en":"an unattainable goal","cn":"难以达到的目标"}}]}},"unidentified":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未被认出的；未被识别的","en":"If you describe someone or something as unidentified, you mean that nobody knows who or what they are.","ex":{"en":"He was shot this morning by unidentified intruders at his house.","cn":"他今天早上在家中被身份不明的闯入者射杀。"}},{"pos":"ADJ 形容词","cn":"不愿透露姓名（或名称）的","en":"If you use unidentified to describe people, groups, and organizations, you do not want to give their names.","ex":{"en":"...his claims, which were based on the comments of anonymous and unidentified sources.","cn":"他的说法是基于不知姓名且身份不明的消息人士的话"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a place or an experience that people have not been in before and that they are therefore often nervous about","cn":""},{"en":"relating to places that have not been put on a map yet, or to situations that have not yet been experienced","cn":""},{"en":"if something is unidentified , people do not know what it is, what its name is, or who it belongs to - used especially in newspapers or in official reports","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/a/unidentified0205.mp3","us":"media/ldoce/hwd/ame/f/unidentified.mp3"},"examples":[{"en":"The painting was sold to an unidentified American dealer (= his or her name was not given).","cn":"这幅画卖给了一名未披露姓名的美国商人。"},{"en":"an unidentified virus","cn":"尚未确定的病毒"}],"oxford":{"phon":"ˌʌnaɪˈdentɪfaɪd","pos":"adjective","senses":[{"en":"not recognized or known; not identified","cn":"未知的；不明的；未确认的","ex":{"en":"an unidentified virus","cn":"尚未确定的病毒"}}]}},"unhygienic":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不清洁的；不卫生的","en":"If you describe something as unhygienic, you mean that it is dirty and likely to cause infection or disease.","ex":{"en":"Parts of the shop were very dirty, unhygienic, and an ideal breeding ground for bacteria.","cn":"店里的一些地方十分肮脏不洁，简直就是滋生细菌的理想温床。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not clean","cn":""},{"en":"very dirty","cn":""},{"en":"covered with mud","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld44unhygienic.mp3","us":"media/ldoce/hwd/ame/2/ld44unhygienic.mp3"},"examples":[{"en":"unhygienic conditions","cn":"不卫生的环境"}],"oxford":{"phon":"ˌʌnhaɪˈdʒiːnɪk","pos":"adjective","senses":[{"en":"not clean and therefore likely to cause disease or infection","cn":"不清洁的；不卫生的；易致病（或感染）的","ex":{"en":"The animals were kept in cramped and unhygienic conditions.","cn":"那些动物的饲养环境狭小且不卫生。"}}]}},"underachieve":{"collins":{"senses":[{"pos":"VERB 动词","cn":"未展现实力；未发挥水平","en":"If someone underachieves in something such as school work or a job, they do not perform as well as they could.","ex":{"en":"Some people might think I've underachieved in my job.","cn":"有些人可能会认为我的才华在目前的工作中没能充分施展出来。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who does not do as well at school or at work as they could do if they worked harder","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/d/underachiever0205.mp3","us":"media/ldoce/hwd/ame/e/laadunderachiever.mp3"},"oxford":{"phon":"ˌʌndərəˈtʃiːv","pos":"verb","senses":[{"en":"to do less well than you could do, especially in school work","cn":"（尤指学习上）未发挥水平，未展现实力","ex":{"en":"Too many boys are underachieving at school.","cn":"太多男孩在学校成绩不佳。"}}]}},"ugandan":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"乌干达的；乌干达人的；乌干达文化的","en":"Ugandan means belonging or relating to Uganda or to its people or culture.","ex":{"en":"...the Ugandan capital, Kampala.","cn":"乌干达首都坎帕拉"}},{"pos":"N-COUNT 可数名词","cn":"乌干达人","en":"A Ugandan is a Ugandan citizen, or a person of Ugandan origin."}]},"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"a country in east central Africa, between the Democratic Republic of the Congo and Kenya. Population: 34,758,809 (2014). Capital: Kampala. After Uganda became independent from the UK in 1962, the country experienced many economic and political problems, especi","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/d/p028-000012365.mp3","us":"media/ldoce/hwd/ame/d/p028-000012365.mp3"},"oxford":{"phon":"juˈɡændən","pos":"noun, adjective","senses":[{"en":"(a person) from Uganda","cn":"乌干达人；乌干达的；乌干达人的"}]}},"undignified":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有失尊严的；不像话的；令人尴尬的","en":"If you describe someone's actions as undignified, you mean they are foolish or embarrassing.","ex":{"en":"It is sad to see a county confine its activities to undignified public bickering","cn":"看到整个县都不顾颜面地公开争吵，真让人感到难过。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"behaving in a way that is embarrassing or makes you look silly","cn":"不庄重的﹔有损尊严的﹔不像样子的"}]},"collocations":{"phrases":["VERBS be, feel, look, seem | become","ADV. most, very | thoroughly | rather, somewhat"]},"media":{"uk":"media/ldoce/hwd/bre/5/undignified0205.mp3","us":"media/ldoce/hwd/ame/8/ld41undignified.mp3"},"examples":[{"en":"There was an undignified scramble for the best seats.","cn":"大家争抢最好的位子，真是有失体统。"},{"en":"There was an undignified scramble for the free drinks.","cn":"出现了争抢免费饮料的丢人场面。"}],"oxford":{"phon":"ʌnˈdɪɡnɪfaɪd","pos":"adjective","senses":[{"en":"causing you to look silly and to lose the respect of other people","cn":"不像样的；不成体统的；不体面的；不庄重的","ex":{"en":"There was an undignified scramble for the best seats.","cn":"大家争抢最好的位子，真是有失体统。"}}]}},"urn":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"骨灰瓮；骨灰罐","en":"An urn is a container in which a dead person's ashes are kept."},{"pos":"N-COUNT 可数名词","cn":"（金属制）大茶壶，咖啡壶","en":"An urn is a metal container used for making a large quantity of tea or coffee and keeping it hot."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a decorated container, especially one that is used for holding the ash es of a dead body","cn":"瓮﹔〔尤指〕骨灰瓮"},{"en":"a metal container that holds a large amount of tea or coffee 〔","cn":"金属的〕大茶壶，大咖啡壶"}]},"vocab":{"pos":"n","senses":[{"en":"An urn is a large, hollow vase that's usually made of metal or clay. Some urns are used for making coffee or tea, others are made to put someone’s ashes in. Go figure."}]},"media":{"uk":"media/ldoce/hwd/bre/d/earn0205.mp3","us":"media/ldoce/hwd/ame/6/earn.mp3"},"examples":[{"en":"a tea urn","cn":"茶水桶"}],"oxford":{"phon":"ɜːn","pos":"noun","senses":[{"en":"a tall decorated container, especially one used for holding the ashes of a dead person","cn":"瓮；（尤指）骨灰缸"},{"en":"a large metal container with a tap, used for making and/or serving tea or coffee","cn":"（带龙头的）茶水桶，咖啡桶","ex":{"en":"a tea urn","cn":"茶水桶"}},{"en":"uniform resource name (a standard way of identifying a book, film, journal, computer file, etc.)","cn":"统一资源名称（全写为 uniform resource name，一种资源定位方式）","pos":"abbreviation"}]}},"untold":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（强调糟糕或令人不快的程度）无以名状的，难以估量的","en":"You can use untold to emphasize how bad or unpleasant something is.","ex":{"en":"The demise of the industry has caused untold misery to thousands of hard-working tradesmen","cn":"该行业的没落给数以千计辛苦经营的商贩带来了难言的苦楚。"}},{"pos":"ADJ 形容词","cn":"数不胜数的;不计其数的","en":"You can use untold to emphasize that an amount or quantity is very large, especially when you are not sure how large it is.","ex":{"en":"...the nation's untold millions of anglers.","cn":"该国数不清的钓鱼爱好者"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"used to emphasize how bad something is","cn":"坏透的﹔彻头彻尾的﹐极端的〔用于强调某事的恶劣程度〕"},{"en":"used to emphasize that an amount or quantity is very large","cn":"数量巨大的"}]},"media":{"uk":"media/ldoce/hwd/bre/1/brelasdeuntold.mp3","us":"media/ldoce/hwd/ame/b/untold.mp3"},"examples":[{"en":"These gases cause untold damage to the environment.","cn":"这些气体对环境造成难以估计的破坏。"},{"en":"untold misery/wealth","cn":"极度的痛苦；巨额财富"}],"oxford":{"phon":"ˌʌnˈtəʊld","pos":"adjective","senses":[{"en":"used to emphasize how large, great, unpleasant, etc. something is","cn":"难以形容的（大、恶劣等）","g":"[only before noun]","ex":{"en":"untold misery/wealth","cn":"极度的痛苦；巨额财富"}},{"en":"not told to anyone","cn":"未讲过的；未叙述的"}]}},"unpronounceable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"难发音的；难读出的","en":"An unpronounceable word or name is too difficult to say."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"an unpronounceable word or name is very difficult to say 〔","cn":"单词或名字〕难发音的"}]},"media":{"uk":"media/ldoce/hwd/bre/2/unpronounceabl0205.mp3","us":"media/ldoce/hwd/ame/b/laadunpronounceable.mp3"},"oxford":{"phon":"ˌʌnprəˈnaʊnsəbl","pos":"adjective","senses":[{"en":"too difficult to pronounce","cn":"难发音的；拗口的"}]}},"unbutton":{"collins":{"senses":[{"pos":"VERB 动词","cn":"解开…的纽扣","en":"If you unbutton an item of clothing, you undo the buttons fastening it.","ex":{"en":"She had begun to unbutton her blouse.","cn":"她开始解衬衣扣子。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to join together the two sides of a piece of clothing, bag, belt etc","cn":""},{"en":"to fasten something firmly to another object or surface, using screws, nails, tape, glue etc","cn":""},{"en":"to connect or fasten things together","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/4/unbutton0205.mp3","us":"media/ldoce/hwd/ame/c/unbutton.mp3"},"examples":[{"en":"He unbuttoned his shirt.","cn":"他解开衬衣扣子。"},{"en":"He took off his sweater and unbuttoned his shirt.","cn":"他脱去毛衣﹐解开衬衫的扣子。"}],"oxford":{"phon":"ˌʌnˈbʌtn","pos":"verb","senses":[{"en":"to open the buttons on a piece of clothing","cn":"解开…的纽扣","ex":{"en":"He unbuttoned his shirt.","cn":"他解开衬衣扣子。"}}]}},"unrequited":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（爱情）单相思的","en":"If you have unrequited love for someone, they do not love you.","ex":{"en":"...his unrequited love for a married woman.","cn":"他对一个已婚女子的暗恋"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"unrequited love or other strong feeling is love etc that you feel for someone but that they do not feel for you 〔","cn":"爱等强烈的情感〕无回报的﹐单方面的﹔单恋的﹐单相思的"}]},"vocab":{"pos":"adj","senses":[{"en":"Unrequited is used almost exclusively in the context of romantic love. If you love someone and they don't love you back––that, my friend, is a case of unrequited love."}]},"media":{"uk":"media/ldoce/hwd/bre/9/brelasdeunrequited.mp3","us":"media/ldoce/hwd/ame/c/unrequited.mp3"},"oxford":{"phon":"ˌʌnrɪˈkwaɪtɪd","pos":"adjective","senses":[{"en":"not returned by the person that you love","cn":"没有回报的；单方面的；单相思的"}]}},"undiluted":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"强烈的；没有掺杂的","en":"If you describe someone's feelings or characteristics as undiluted, you are emphasizing that they are very strong and not mixed with any other feeling or quality.","ex":{"en":"I will look back at this one with undiluted pleasure","cn":"回顾此事，我会无比地开心。"}},{"pos":"ADJ 形容词","cn":"（液体）未稀释的","en":"A liquid that is undiluted has not been made weak by mixing it with water."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"an undiluted feeling is very strong and not mixed with any other feelings 〔","cn":"感情〕未淡化的﹔浓烈的﹔纯粹的"},{"en":"an undiluted liquid has not been made weaker by adding water 〔","cn":"液体〕未经稀释的"}]},"media":{"uk":"media/ldoce/hwd/bre/7/undiluted0205.mp3","us":"media/ldoce/hwd/ame/1/laadundiluted.mp3"},"examples":[{"en":"undiluted joy","cn":"浓浓的喜悦"},{"en":"undiluted fruit juice","cn":"纯果汁"}],"oxford":{"phon":"ˌʌndaɪˈluːtɪd","pos":"adjective","senses":[{"en":"not made weaker by having water added to it; not having been diluted","cn":"未掺水的；未稀释的"},{"en":"not mixed or combined with anything and therefore very strong","cn":"真挚的；纯洁的；浓烈的；醇厚的","ex":{"en":"I looked back on that time with undiluted pleasure.","cn":"我怀着纯粹的喜悦回顾那段时光。"}}]}},"unflinching":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"不退缩的；坚定的","en":"You can use unflinching in expressions such as unflinching honesty and unflinching support to indicate that a good quality which someone has is strong and steady, and never weakens.","ex":{"en":"...the armed forces, all of whom had pledged their unflinching support and loyalty to the government.","cn":"武装力量一致保证坚决支持并效忠政府"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not changing or becoming weaker, even in a very difficult or dangerous situation","cn":"坚定的﹐不畏缩的"}]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41unflinching.mp3","us":"media/ldoce/hwd/ame/7/unflinching.mp3"},"examples":[{"en":"unflinching loyalty","cn":"坚贞不渝的忠诚"},{"en":"an unflinching stare","cn":"毫不畏惧的注视"}],"oxford":{"phon":"ʌnˈflɪntʃɪŋ","pos":"adjective","senses":[{"en":"remaining strong and determined, even in a difficult or dangerous situation","cn":"不屈不挠的；果敢的；坚定的；不畏缩的","ex":{"en":"unflinching loyalty","cn":"坚贞不渝的忠诚"}}]}},"utopian":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（计划、想法）空想的，不切实际的","en":"If you describe a plan or idea as utopian, you are criticizing it because it is unrealistic and shows a belief that things can be improved much more than is possible.","ex":{"en":"He was pursuing a utopian dream of world prosperity","cn":"他怀揣着一个实现世界繁荣的乌托邦之梦。"}},{"pos":"ADJ 形容词","cn":"（政治或宗教思想）空想的，乌托邦式的","en":"Utopian is used to describe political or religious philosophies which claim that it is possible to build a new and perfect society in which everyone is happy.","ex":{"en":"His was a utopian vision of nature in its purest form.","cn":"他对大自然怀有一种极为纯粹的乌托邦式看法。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a utopian society is one in which you imagine there is a perfect social or political situation, although this is unlikely to ever really exist","cn":""},{"en":"an idealized view or description of something considers or shows it as perfect when really it is not","cn":""},{"en":"an imaginary perfect world where everyone is happy","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"If you're looking to relocate to a utopia, good luck! A utopia is an ideal society, and a scheme or vision for producing such a society can be called utopian ."}]},"media":{"uk":"media/ldoce/hwd/bre/a/utopia0205.mp3","us":"media/ldoce/hwd/ame/a/utopia.mp3"},"examples":[{"en":"utopian ideals","cn":"不切实际的理想"},{"en":"a utopian society","cn":"乌托邦式社会"}],"oxford":{"phon":"juːˈtəʊpiən","pos":"adjective","senses":[{"en":"having a strong belief that everything can be perfect, often in a way that does not seem to be realistic or practical","cn":"乌托邦的；空想完美主义的","ex":{"en":"utopian ideals","cn":"不切实际的理想"}}]}},"uneducated":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"未受过良好教育的；没有多少文化的","en":"Someone who is uneducated has not received much education.","ex":{"en":"Though an uneducated man, Chavez was not a stupid one.","cn":"查维斯虽然没有受过多少教育，但并不笨。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not educated to the usual level, or showing that someone is not well educated","cn":"没受过教育的﹔未受过良好教育的﹔没有教养的"}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41uneducated.mp3","us":"media/ldoce/hwd/ame/8/uneducated.mp3"},"examples":[{"en":"an uneducated workforce","cn":"缺乏教育的劳动力"},{"en":"an uneducated point of view","cn":"无知的观点"}],"oxford":{"phon":"ʌnˈedʒukeɪtɪd","pos":"adjective","senses":[{"en":"having had little or no formal education at a school; showing a lack of education","cn":"未受教育的；未教化的；缺乏教养的","ex":{"en":"an uneducated workforce","cn":"缺乏教育的劳动力"}}]}},"unimaginative":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"缺乏想象力的；刻板的","en":"If you describe someone as unimaginative, you are criticizing them because they do not think of new methods or things to do.","ex":{"en":"Her second husband was a steady, unimaginative, corporate lawyer.","cn":"她的第二任丈夫是一位稳重、刻板的公司法律师。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"乏味的；无吸引力的","en":"If you describe something as unimaginative, you mean that it is boring or unattractive because very little imagination or effort has been used on it.","ex":{"en":"...unimaginative food","cn":"毫无吸引力的饭菜"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"lacking the ability to think of new or unusual ideas","cn":"缺乏想象力的"},{"en":"ordinary and boring, and not using any new ideas","cn":"平淡的﹐无趣的﹐无新意的﹐无创见的"}]},"media":{"uk":"media/ldoce/hwd/bre/c/unimaginative0205.mp3","us":"media/ldoce/hwd/ame/e/laadunimaginative.mp3"},"examples":[{"en":"an unimaginative solution to a problem","cn":"毫无创意的解决方法"},{"en":"a boring unimaginative man","cn":"一个乏味、没有想像力的男人"}],"oxford":{"phon":"ˌʌnɪˈmædʒɪnətɪv","pos":"adjective","senses":[{"en":"not having any original or new ideas","cn":"无创意的；缺乏想象力的","ex":{"en":"an unimaginative solution to a problem","cn":"毫无创意的解决方法"}}]}},"unbeliever":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"无宗教信仰者","en":"People who do not believe in a particular religion are sometimes referred to as unbelievers ."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who does not believe in God or a particular religion","cn":"不信教者"}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41unbeliever.mp3","us":"media/ldoce/hwd/ame/6/unbeliever.mp3"},"oxford":{"phon":"ˌʌnbɪˈliːvə(r)","pos":"noun","senses":[{"en":"a person who does not believe, especially in God, a religion, etc.","cn":"无（宗教）信仰的人；（尤指）不信上帝的人"}]}},"unaware":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"不知道的；不晓得的；未注意到的","en":"If you are unaware of something, you do not know about it.","ex":{"en":"Many people are unaware of just how much food and drink they consume","cn":"许多人并不知道他们究竟消耗掉了多少食品和饮料。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"to not know about a situation or about something that is happening, especially when you should know about it","cn":""},{"en":"to know nothing about a subject or situation because you have not experienced it, read about it, or heard about it","cn":""},{"en":"use this about something that was happening without you knowing about it at the time","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Unaware is simply the opposite of \"aware.\" If you are unaware , you have no idea what's going on."}]},"collocations":{"phrases":["VERBS appear, be, seem | remain","ADV. completely, entirely, quite, totally, utterly, wholly | almost, virtually | generally, largely | comparatively | apparently, seemingly ","PREP. of"]},"media":{"uk":"media/ldoce/hwd/bre/1/unaware0205.mp3","us":"media/ldoce/hwd/ame/0/unaware.mp3"},"examples":[{"en":"He was completely unaware of the whole affair.","cn":"他对整件事情一无所知。"},{"en":"She was unaware that I could see her.","cn":"她没想到我能看见她。"}],"oxford":{"phon":"ˌʌnəˈweə(r)","pos":"adjective","senses":[{"en":"not knowing or realizing that something is happening or that something exists","cn":"不知道；没意识到；未察觉","ex":{"en":"He was completely unaware of the whole affair.","cn":"他对整件事情一无所知。"}}]}},"unionism":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"联合主义；统一主义","en":"Unionism is any set of political principles based on the idea that two or more political or national units should be joined or remain together, for example that Northern Ireland should remain part of the United Kingdom."},{"pos":"N-UNCOUNT 不可数名词","cn":"同 trade unionism","en":"Unionism is the same as trade unionism ."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"belief in the principles of trade union s","cn":"工会主义﹐工联主义"}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41unionism.mp3","us":"media/ldoce/hwd/ame/6/unionism.mp3"},"oxford":{"phon":"ˈjuːniənɪzəm","pos":"noun","senses":[{"en":"the principles and practices of trade unions (= organizations of workers that exist to protect their interests)","cn":"工会主义；工联主义"},{"en":"the belief that Northern Ireland should stay part of the United Kingdom","cn":"统一主义者，统一派（主张北爱尔兰继续为英国的一部分）"},{"en":"support of the Union during the Civil War in the US","cn":"（美国内战时期的）合众国拥护者，合众派成员"}]}},"unconsciousness":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not able to see, hear, feel etc, usually for a short time, for example because you have taken a drug or been hit on the head","cn":""},{"en":"to be unconscious for a long time, because of a serious accident or illness","cn":""},{"en":"to be unconscious","cn":""}]},"collocations":{"phrases":["ADJ. deep","VERB + UNCONSCIOUSNESS fall/lapse/sink/slip into"]},"media":{"uk":"media/ldoce/hwd/bre/1/unconscious_n0205.mp3","us":"media/ldoce/hwd/ame/b/unconscious1.mp3"},"examples":[{"en":"He had lapsed into unconsciousness.","cn":"他陷入了昏迷状态。"},{"en":"She was found alive but unconscious.","cn":""}],"oxford":{"phon":"ʌnˈkɒnʃəsnəs","pos":"noun","senses":[{"en":"a state like sleep caused by injury or illness, when you are unable to use your senses","cn":"昏迷；无知觉状态","ex":{"en":"He had lapsed into unconsciousness.","cn":"他陷入了昏迷状态。"}}]}},"uppermost":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"最高的；最上面的","en":"The uppermost part of something is the part that is higher than the rest of it. The uppermost thing is the highest one of a group of things.","ex":{"en":"John was on the uppermost floor of the three-storey gatehouse","cn":"约翰在三层门房的最高层。"}},{"pos":"ADJ 形容词","cn":"最重要的；最主要的","en":"If something is uppermost in a particular situation, it is the most important thing in that situation.","ex":{"en":"The economy appears to be uppermost in people's minds","cn":"大家心里最关心的似乎是经济。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"at the top above the lower part of something","cn":""},{"en":"the topmost or uppermost part of something is the highest of all its parts, right at the top","cn":""},{"en":"if something is uppermost in your mind, you think about it a lot because it is very important to you","cn":"是心目中最主要的"}]},"media":{"uk":"media/ldoce/hwd/bre/f/uppermost0205.mp3","us":"media/ldoce/hwd/ame/7/uppermost.mp3"},"examples":[{"en":"Place the material on a flat surface, shiny side uppermost.","cn":"把材料放在平面上，有光的一面朝上。"},{"en":"These thoughts were uppermost in my mind.","cn":"我心里想得最多的就是这些事。"}],"oxford":{"phon":"ˈʌpəməʊst","pos":"adjective","senses":[{"en":"higher or nearer the top than other things","cn":"最高的；最上端的；最上面的","g":"[usually before noun]","lab":"formal","ex":{"en":"the uppermost branches of the tree","cn":"树顶端的枝丫"}},{"en":"more important than other things in a particular situation","cn":"最重要；最关键","g":"[not usually before noun]","ex":{"en":"These thoughts were uppermost in my mind.","cn":"我心里想的最多的就是这些事。"}},{"en":"in the highest position; facing upwards","cn":"处于最高位置；面向上地","ex":{"en":"Place the material on a flat surface, shiny side uppermost.","cn":"把材料放在平面上，有光的一面朝上。"},"pos":"adverb"}]}},"undercarriage":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（飞机的）起落架","en":"The undercarriage of an aeroplane is the part, including the wheels, which supports the aeroplane when it is on the ground and when it is landing or taking off."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the wheels of an aircraft, train etc and the structure that holds them 〔","cn":"飞机的〕起落架﹔〔火车等的〕底盘"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41undercarriage.mp3","us":"media/ldoce/hwd/ame/c/undercarriage.mp3"},"oxford":{"phon":"ˈʌndəkærɪdʒ","pos":"noun","senses":[{"en":"the part of an aircraft, including the wheels, that supports it when it is on the ground","cn":"（飞行器的）起落装置"}]}},"unpalatable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（意见等）令人不快的，难以接受的","en":"If you describe an idea as unpalatable, you mean that you find it unpleasant and difficult to accept.","ex":{"en":"It is an unpalatable fact that rape makes a good news story","cn":"强奸事件成了新闻报道的好素材，真是令人难以接受。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"难吃的；不可口的","en":"If you describe food as unpalatable, you mean that it is so unpleasant that you can hardly eat it.","ex":{"en":"...a lump of dry, unpalatable cheese.","cn":"一块干巴巴、难以入口的奶酪"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"an unpalatable fact or idea is very unpleasant and difficult to accept 〔","cn":"事实或想法〕使人不快的﹔令人讨厌的﹔难以接受的"},{"en":"unpalatable food tastes unpleasant","cn":"难吃的﹐不可口的"}]},"vocab":{"pos":"adj","senses":[{"en":"Use the adjective unpalatable to describe something that tastes really bad, like a glass of unsweetened lemonade."}]},"media":{"uk":"media/ldoce/hwd/bre/3/unpalatable0205.mp3","us":"media/ldoce/hwd/ame/7/unpalatable.mp3"},"examples":[{"en":"Only then did I learn the unpalatable truth.","cn":"直到那时我才得知令人难以接受的真相。"},{"en":"unpalatable food","cn":"难吃的食物"}],"oxford":{"phon":"ʌnˈpælətəbl","pos":"adjective","senses":[{"en":"unpleasant and not easy to accept","cn":"令人不快的；难以接受的","ex":{"en":"Only then did I learn the unpalatable truth.","cn":"直到那时我才得知令人难以接受的真相。"}},{"en":"not pleasant to taste","cn":"难吃的；不可口的","ex":{"en":"unpalatable food","cn":"难吃的食物"}}]}},"unsolicited":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未经请求的；自发的","en":"Something that is unsolicited has been given without being asked for and may not have been wanted.","ex":{"en":"'If I were you,' she adds by way of some unsolicited advice, 'I'd watch out for that girl of yours.'","cn":"“如果我是你，”她主动建议说，“我会密切注意自己的女儿。”"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not asked for and often not wanted","cn":"未经要求的﹐自发的"}]},"vocab":{"pos":"adj","senses":[{"en":"Something unsolicited was not asked for and possibly not wanted. Unsolicited calls and advice come whether we want them or not."}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld44unsolicited.mp3","us":"media/ldoce/hwd/ame/6/ld44unsolicited.mp3"},"examples":[{"en":"unsolicited advice","cn":"主动提出的忠告"},{"en":"unsolicited calls","cn":"未获邀请的造访"}],"oxford":{"phon":"ˌʌnsəˈlɪsɪtɪd","pos":"adjective","senses":[{"en":"not asked for and sometimes not wanted","cn":"未经要求的；自发的；自我推荐的","ex":{"en":"unsolicited advice","cn":"主动提出的忠告"}}]}},"unnatural":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不自然的；诡异的；反常的","en":"If you describe something as unnatural, you mean that it is strange and often frightening, because it is different from what you normally expect.","ex":{"en":"The aircraft rose with unnatural speed on take-off","cn":"那架飞机以反常的速度起飞升空。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不自然的；做作的","en":"Behaviour that is unnatural seems artificial and not normal or genuine.","ex":{"en":"She gave him a bright, determined smile which seemed unnatural.","cn":"她对他开朗、坚定地一笑，但笑得有点不自然。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"very different from what is normal, in a way that is strange, worrying, or dangerous","cn":""},{"en":"different from normal human behaviour in a way that seems morally wrong 〔","cn":"行为〕违反常理的﹐违背人道的"},{"en":"deviant behaviour or actions are considered to be very strange and morally unacceptable -- often used about sexual or criminal behaviour","cn":""}]},"collocations":{"phrases":["VERBS be, feel, look, seem, sound | consider sth, regard sth as","ADV. highly, terribly, very food produced under highly unnatural conditions | quite | almost | a bit, rather"]},"media":{"uk":"media/ldoce/hwd/bre/d/unnatural0205.mp3","us":"media/ldoce/hwd/ame/2/unnatural.mp3"},"examples":[{"en":"It seems unnatural for a child to spend so much time alone.","cn":"一个孩子独自一人待那么长时间似乎有点反常。"},{"en":"There was an unnatural silence and then a scream.","cn":"一阵反常的寂静，接着便是一声尖叫。"}],"oxford":{"phon":"ʌnˈnætʃrəl","pos":"adjective","senses":[{"en":"different from what is normal or expected, or from what is generally accepted as being right","cn":"不自然的；勉强的；反常的","ex":{"en":"It seems unnatural for a child to spend so much time alone.","cn":"一个孩子独自一人待那么长时间似乎有点反常。"}},{"en":"different from anything in nature","cn":"不正常的；怪异的","ex":{"en":"Her leg was bent at an unnatural angle.","cn":"她的腿弯曲的角度反常。"}}]}},"unappealing":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不诱人的；无吸引力的","en":"If you describe someone or something as unappealing, you find them unpleasant and unattractive.","ex":{"en":"He's wearing a deeply unappealing baseball hat","cn":"他戴着一顶很不起眼的棒球帽。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not pleasant or attractive","cn":"令人不快的﹔无吸引力的"}]},"media":{"uk":"media/ldoce/hwd/bre/9/unappealing0205.mp3","us":"media/ldoce/hwd/ame/e/laadunappealing.mp3"},"examples":[{"en":"The prospect of studying for another five years was distinctly unappealing.","cn":"未来还需要再学五年真是让人厌烦。"},{"en":"The room was painted in an unappealing shade of brown.","cn":"这屋子漆成了难看的棕色。"}],"oxford":{"phon":"ˌʌnəˈpiːlɪŋ","pos":"adjective","senses":[{"en":"not attractive or pleasant","cn":"无吸引力的；不诱人的；令人不快的","ex":{"en":"The room was painted in an unappealing shade of brown.","cn":"这屋子漆成了难看的棕色。"}}]}},"unabashed":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"不害臊的；不难为情的","en":"If you describe someone as unabashed, you mean that they are not ashamed, embarrassed, or shy about something, especially when you think most people would be.","ex":{"en":"He seems unabashed by his recent defeat","cn":"他似乎对最近的失利并不在乎。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who is shameless or whose behaviour is shameless does not seem to feel ashamed about something that most people would be very ashamed about","cn":""},{"en":"not feeling embarrassed or ashamed about something that most people disapprove of or consider silly","cn":""},{"en":"not feeling embarrassed or ashamed about something that people might disapprove of","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"To be unabashed is to be unembarrassed. When you're unabashed , you're confident and proud. You're letting it all hang out."}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41unabashed.mp3","us":"media/ldoce/hwd/ame/2/unabashed.mp3"},"examples":[{"en":"She stared at him with unabashed curiosity.","cn":"她好奇地盯着他看﹐一点也不难为情。"}],"oxford":{"phon":"ˌʌnəˈbæʃt","pos":"adjective","senses":[{"en":"not ashamed, embarrassed or affected by people’s negative opinions, when other people would be","cn":"不在乎的；不害羞的；不难为情的","ex":{"en":"He was unabashed by the reaction he had caused.","cn":"他没有为他所引起的反应感到害羞。"}}]}},"unfurl":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"打开（伞等）；展开（帆、旗帜等）","en":"If you unfurl something rolled or folded such as an umbrella, sail, or flag, you open it, so that it is spread out. You can also say that it unfurls .","ex":{"en":"Once outside the inner breakwater, we began to unfurl all the sails.","cn":"一驶出内防波堤，我们就扬起了所有的船帆。"}},{"pos":"VERB 动词","cn":"（事件、故事或场面）展开，显露","en":"If you say that events, stories, or scenes unfurl before you, you mean that you are aware of them or can see them as they happen or develop.","ex":{"en":"...as the dramatic changes in Europe continue to unfurl.","cn":"随着欧洲剧变不断展现在人们眼前"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if a flag, sail etc unfurls, or if someone unfurls it, it unrolls and opens (","cn":"使)〔旗﹑帆等〕打开﹐展开"}]},"vocab":{"pos":"v","senses":[{"en":"When you unfurl something, you unroll it or spread it out. Your yoga teacher will unfurl her long purple mat at the beginning of class."}]},"media":{"uk":"media/ldoce/hwd/bre/7/unfurl0205.mp3","us":"media/ldoce/hwd/ame/e/unfurl.mp3"},"examples":[{"en":"The leaves slowly unfurled.","cn":"叶子慢慢地展开了。"},{"en":"to unfurl a flag","cn":"展开旗子"}],"oxford":{"phon":"ˌʌnˈfɜːl","pos":"verb","senses":[{"en":"when something that is curled or rolled tightly unfurls, or you unfurl it, it opens","cn":"（使卷紧的东西）打开，展开","ex":{"en":"The leaves slowly unfurled.","cn":"叶子慢慢地展开了。"}}]}},"unbuckle":{"collins":{"senses":[{"pos":"VERB 动词","cn":"解开（皮带、鞋子等）的搭扣","en":"If you unbuckle something such as a belt or a shoe, you undo the buckle fastening it.","ex":{"en":"He unbuckled his seat belt","cn":"他解开了坐椅安全带。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to unfasten the buckle on a belt, a shoe etc","cn":"解开…的搭扣"}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41unbuckle.mp3","us":"media/ldoce/hwd/ame/7/unbuckle.mp3"},"oxford":{"phon":"ˌʌnˈbʌkl","pos":"verb","senses":[{"en":"to open the buckle of a belt, shoe, etc.","cn":"解开（皮带、鞋子等）的扣"}]}},"unprintable":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（因粗鲁或惊世骇俗）难以启齿的","en":"If you describe something that someone has said or done as unprintable, you mean that it is so rude or shocking that you do not want to say exactly what it was.","ex":{"en":"Her reply was unprintable.","cn":"她的回答实在难以启齿。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"language that most people think is offensive","cn":""},{"en":"language that most people think is offensive - used especially to warn people that there may be offensive words used in a film or television programme","cn":""},{"en":"language that uses a lot of swear words - use this in humorous contexts","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41unprintable.mp3","us":"media/ldoce/hwd/ame/9/unprintable.mp3"},"oxford":{"phon":"ʌnˈprɪntəbl","pos":"adjective","senses":[{"en":"too offensive or shocking to be printed and read by people","cn":"（因冒犯或令人震惊）不宜刊印的，不宜发表的"}]}},"unchallenged":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未引起质疑的；没有异议的","en":"When something goes unchallenged or is unchallenged, people accept it without asking questions about whether it is right or wrong.","ex":{"en":"These views have not gone unchallenged","cn":"这些观点并非没有受到质疑。"}},{"pos":"ADJ 形容词","cn":"未受到挑战的；稳固的","en":"If you say that someone's position of authority is unchallenged, you mean that it is strong and no one tries to replace them.","ex":{"en":"He is the unchallenged leader of the strongest republic.","cn":"他是这个最强大的共和国的绝对领袖。"}},{"pos":"ADJ 形容词","cn":"未被盘问的；未受到质疑的","en":"If you do something unchallenged, nobody stops you and asks you questions, for example about who you are or why you are doing it.","ex":{"en":"I managed to walk around unchallenged for 10 minutes before an alert nurse spotted me.","cn":"我四处走动了10分钟，没有受到查问，之后一位警觉的护士发现了我。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"accepted and believed by everyone and not doubted","cn":"未引起争论的，无异议的﹐未引起质疑的"},{"en":"someone who goes somewhere unchallenged is not stopped and asked who they are or what they are doing 〔","cn":"人〕未受阻拦的，未受到盘查的"}]},"media":{"uk":"media/ldoce/hwd/bre/5/unchallenged0205.mp3","us":"media/ldoce/hwd/ame/2/laadunchallenged.mp3"},"examples":[{"en":"She could not allow such a claim to go unchallenged.","cn":"她不能对这样的要求听任不管。"},{"en":"I walked into the building unchallenged.","cn":"我畅行无阻地走进大楼。"}],"oxford":{"phon":"ʌnˈtʃælɪndʒd","pos":"adjective","senses":[{"en":"not doubted; accepted without question; not challenged","cn":"不被怀疑的；完全接受的；没有异议的","ex":{"en":"She could not allow such a claim to go unchallenged.","cn":"她不能对这样的要求听之任之。"}},{"en":"not opposed by anyone","cn":"无人反对的；稳固的","ex":{"en":"He is in a position of unchallenged authority.","cn":"他拥有绝对的权威。"}},{"en":"without being stopped and asked to explain who you are, what you are doing, etc.","cn":"无阻挡的；未受盘查的","ex":{"en":"I walked into the building unchallenged.","cn":"我畅行无阻地走进大楼。"}}]}},"uncoil":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"（卷绕之物）展开，伸展；展开，将…伸展开","en":"If something uncoils or if you uncoil it, it becomes straight after it has been wound or curled up. If someone who is curled up uncoils, they move so that their body becomes straight.","ex":{"en":"He uncoiled the hose and gave them a thorough drenching","cn":"他把软管铺展开来，把它们彻底冲洗了一下。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if you uncoil something, or if it uncoils, it stretches out straight after being wound around in a circle","cn":"解开〔卷着的东西〕﹔(使)展开"}]},"media":{"uk":"media/ldoce/hwd/bre/5/uncoil0205.mp3","us":"media/ldoce/hwd/ame/7/laaduncoil.mp3"},"examples":[{"en":"The snake slowly uncoiled.","cn":"蛇慢慢地展开了盘着的身体。"},{"en":"to uncoil a rope","cn":"打开盘卷的绳索"}],"oxford":{"phon":"ˌʌnˈkɔɪl","pos":"verb","senses":[{"en":"to become or make something straight after it has been wound or twisted round in a circle","cn":"（使盘卷的东西）展开，打开；拉直","ex":{"en":"The snake slowly uncoiled.","cn":"蛇慢慢地展开了盘着的身体。"}}]}},"unsecured":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（贷款或债务）无担保的","en":"Unsecured is used to describe loans or debts that are not guaranteed by a particular asset such as a person's home.","ex":{"en":"We can arrange unsecured loans for any amount from £500 to £7,500.","cn":"我们能提供数额从500英镑到7,500英镑的无担保贷款。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"an unsecured debt or loan is one that does not make you promise to give the bank something you own if you cannot pay it back 〔","cn":"债务或贷款〕无担保的﹐无抵押的"}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41unsecured.mp3","us":"media/ldoce/hwd/ame/0/laadunsecured.mp3"},"oxford":{"phon":"ˌʌnsɪˈkjʊəd","pos":"adjective","senses":[{"en":"if a debt or loan is unsecured, a person has arranged it without legally agreeing to give somebody valuable property if they cannot pay the money back","cn":"（债务或贷款）无抵押的，无担保的","ex":{"en":"an unsecured personal loan of £15 000","cn":"一笔 15 000 英镑的无抵押私人贷款"}},{"en":"having given somebody a loan without security (= an agreement that they will give you valuable property if they cannot pay the money back)","cn":"给予无抵押贷款的","ex":{"en":"unsecured creditors","cn":"无抵押债权人"}},{"en":"not locked, guarded or protected","cn":"未上锁的；无保护的；不安全的","ex":{"en":"unsecured windows","cn":"未关严的窗户"}}]}},"unrepresentative":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不具代表性的；不典型的","en":"If you describe a group of people as unrepresentative, you mean that their views are not typical of the community or society to which they belong.","ex":{"en":"The President denounced the demonstrators as unrepresentative of the Romanian people.","cn":"总统谴责示威者，说他们并不能代表罗马尼亚人民。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not typical of a particular group of things or people","cn":"不典型的﹐不具代表性的"}]},"media":{"uk":"media/ldoce/hwd/bre/d/unrepresentati0205.mp3","us":"media/ldoce/hwd/ame/a/laadunrepresentative.mp3"},"examples":[{"en":"an unrepresentative sample","cn":"缺乏代表性的样品"},{"en":"opinions that are unrepresentative of the population","cn":"不代表全部人的观点"}],"oxford":{"phon":"ˌʌnˌreprɪˈzentətɪv","pos":"adjective","senses":[{"en":"not typical of a group of people or things and therefore not useful as a source of information about that group","cn":"不典型的；无代表性的","ex":{"en":"an unrepresentative sample","cn":"缺乏代表性的样品"}}]}},"ungainly":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（人、兽、车船）笨拙的，难看的","en":"If you describe a person, animal, or vehicle as ungainly, you mean that they look awkward or clumsy, often because they are big.","ex":{"en":"The dog, an ungainly mongrel pup, was loping about the road","cn":"那只丑陋的杂种幼犬在马路上到处乱跑。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"moving or doing things in a careless way, especially so that you drop things, knock into things etc","cn":""},{"en":"moving in a way that does not seem relaxed or comfortable","cn":""},{"en":"moving in a way that is not graceful – used especially about people or things that are big","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Ungainly is the opposite of graceful, convenient or easy. A clumsy dancer boogies in an ungainly or awkward fashion."}]},"media":{"uk":"media/ldoce/hwd/bre/e/ungainly0205.mp3","us":"media/ldoce/hwd/ame/a/ungainly.mp3"},"examples":[{"en":"He was a tall, ungainly boy of 18.","cn":"他是个个子高而笨拙的 18 岁小伙子。"},{"en":"a tall ungainly teenager","cn":"一个动作笨拙的高个子少年"}],"oxford":{"phon":"ʌnˈɡeɪnli","pos":"adjective","senses":[{"en":"moving in a way that is not smooth or attractive","cn":"笨手笨脚的；（举止）不雅观的，难看的","ex":{"en":"He was a tall, ungainly boy of 18.","cn":"他是个个子高而笨拙的 18 岁小伙子。"}}]}},"unbeaten":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（体育中）保持不败的，未被打败过的","en":"In sport, if a person or their performance is unbeaten, nobody else has performed well enough to beat them.","ex":{"en":"He's unbeaten in 20 fights","cn":"他20战全胜。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a team, player etc that is unbeaten has not been defeated","cn":"未曾被击败的﹔未尝败绩的"}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41unbeaten.mp3","us":"media/ldoce/hwd/ame/0/unbeaten.mp3"},"examples":[{"en":"The team are unbeaten in their last four games.","cn":"这个队在最近的四场比赛中从未失败过。"},{"en":"They will be putting their unbeaten record to the test next Saturday.","cn":"下周六他们的不败纪录将要受到考验。"}],"oxford":{"phon":"ʌnˈbiːtn","pos":"adjective","senses":[{"en":"not having been defeated","cn":"未尝败绩的；未败过的","ex":{"en":"The team are unbeaten in their last four games.","cn":"这个队在最近的四场比赛中从未输过。"}}]}},"utilitarian":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"功利主义的；实利主义的","en":"Utilitarian means based on the idea that the morally correct course of action is the one that produces benefit for the greatest number of people.","ex":{"en":"It was James Mill who was the best publicist for utilitarian ideas on government.","cn":"詹姆斯·米尔是政府功利主义思想的最具代表性的人物。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（物品、建筑等）实用的","en":"Utilitarian objects and buildings are designed to be useful rather than attractive.","ex":{"en":"Bruce's office is a corner one, utilitarian and unglamorous.","cn":"布鲁斯的办公室在角落里，实用而普通。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"intended to be useful and practical rather than attractive or comfortable","cn":"有用的﹔实用的"},{"en":"based on a belief in utilitarianism","cn":"功利主义的"}]},"vocab":{"pos":"adj n","senses":[{"en":"The adjective utilitarian describes something that is useful or functional. If you are attracted to a car for its storage space and gas mileage — as opposed to its sparkly tire rims — then chances are you value a car's utilitarian features."}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41utilitarian.mp3","us":"media/ldoce/hwd/ame/e/utilitarian.mp3"},"examples":[{"en":"ugly utilitarian buildings","cn":"丑陋但实用的建筑物"}],"oxford":{"phon":"ˌjuːtɪlɪˈteəriən","pos":"adjective","senses":[{"en":"designed to be useful and practical rather than attractive","cn":"实用的；功利的；实惠的","lab":"formal","ex":{"en":"Her clothes were utilitarian, unlike the elaborate dresses the other girls were wearing.","cn":"她的衣服很实用，不像其他女孩穿的精致的衣服。"}},{"en":"based on or supporting the ideas of utilitarianism","cn":"功利主义的","lab":"philosophy"}]}},"urbane":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有礼貌的；温文尔雅的","en":"Someone who is urbane is polite and appears comfortable in social situations.","ex":{"en":"She describes him as urbane and charming","cn":"她说他文雅而迷人。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"behaving in a relaxed and confident way in social situations","cn":"温文尔雅的﹐从容不迫的"}]},"vocab":{"pos":"adj","senses":[{"en":"Urbane people are sophisticated, polished, cultured, refined. Spend enough time in an urban setting–-going to concerts, museums, spending time in crowds––and you'll be urbane too."}]},"media":{"uk":"media/ldoce/hwd/bre/a/urbane0205.mp3","us":"media/ldoce/hwd/ame/e/urbane.mp3"},"examples":[{"en":"Neil was urbane, witty, direct, and honest.","cn":"尼尔文雅机智﹐坦率诚实。"}],"oxford":{"phon":"ɜːˈbeɪn","pos":"adjective","senses":[{"en":"good at knowing what to say and how to behave in social situations; appearing relaxed and confident","cn":"温文儒雅的；练达的；从容不迫的","ex":{"en":"He was charming and urbane, full of witty conversation.","cn":"他魅力十足且温文儒雅，谈吐诙谐。"}}]}},"unreasoning":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"缺乏理性的；盲目冲动的；未加思量的","en":"Unreasoning feelings or actions are not logical, sensible, or controlled.","ex":{"en":"At this moment of success I found only an unreasoning sense of futility","cn":"在这一成功的时刻我只感到一阵莫名的枉然。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"an unreasoning feeling is not based on facts or good reasons 〔","cn":"感觉〕无端的﹐没有根据的﹔缺乏理智的"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41unreasoning.mp3","us":"media/ldoce/hwd/ame/a/unreasoning.mp3"},"examples":[{"en":"unreasoning fear","cn":"无端的恐惧"}],"oxford":{"phon":"ʌnˈriːzənɪŋ","pos":"adjective","senses":[{"en":"not based on facts or reason","cn":"没根据的；缺乏理性的；无缘无故的","ex":{"en":"unreasoning fear","cn":"无端的恐惧"}}]}},"unattractive":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不漂亮的；难看的；不吸引人的","en":"Unattractive people and things are unpleasant in appearance.","ex":{"en":"I'm 27, have a nice flat, a good job and I'm not unattractive.","cn":"本人27岁，有一所不错的公寓，一份像样的工作，长得也不难看。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无吸引力的；不受欢迎的","en":"If you describe something as unattractive, you mean that people do not like it and do not want to be involved with it.","ex":{"en":"The market is still unattractive to many insurers","cn":"市场对许多保险公司依然没有吸引力。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"very unpleasant to look at","cn":""},{"en":"something that is unsightly is unpleasant to look at, and spoils the appearance of the things around it","cn":""},{"en":"not at all pleasant to look at","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/b/unattractive0205.mp3","us":"media/ldoce/hwd/ame/f/laadunattractive.mp3"},"examples":[{"en":"one of the unattractive aspects of the free market economy","cn":"自由市场经济糟糕的一个方面"},{"en":"an unattractive brown colour","cn":"难看的棕色"}],"oxford":{"phon":"ˌʌnəˈtræktɪv","pos":"adjective","senses":[{"en":"not attractive or pleasant to look at","cn":"不悦目的；不漂亮的；难看的","ex":{"en":"an unattractive brown colour","cn":"难看的棕色"}},{"en":"not good, interesting or pleasant","cn":"不好的；无趣的；令人反感的","ex":{"en":"one of the unattractive aspects of the free market economy","cn":"自由市场经济糟糕的一个方面"}}]}},"unilateral":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"一方的；单边的；单方面的","en":"A unilateral decision or action is taken by only one of the groups, organizations, or countries that are involved in a particular situation, without the agreement of the others.","ex":{"en":"...unilateral nuclear disarmament.","cn":"单方面核裁军"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a unilateral action or decision is done by only one of the groups involved in a situation 〔","cn":"行动或决定〕一方的﹐单边的﹐单方面的"},{"en":"→ bilateral , multilateral : a unilateral declaration of independence","cn":"单方面宣布独立 unilateral disarmament (= when one country gets rid of its own nuclear weapons without waiting for other countri"}]},"vocab":{"pos":"adj","senses":[{"en":"Unilateral means \"one-sided.\" If parents make a unilateral decision to eliminate summer vacation, it means that the students’ opinions or opposing views weren’t considered."}]},"media":{"uk":"media/ldoce/hwd/bre/a/unilateral0205.mp3","us":"media/ldoce/hwd/ame/6/unilateral.mp3"},"examples":[{"en":"They had campaigned vigorously for unilateral nuclear disarmament (= when one country gets rid of its nuclear weapons without waiting for other countries to do the same).","cn":"他们曾致力于单方面裁减核武器运动。"},{"en":"They were forced to take unilateral action.","cn":"他们被迫采取单方面行动。"}],"oxford":{"phon":"ˌjuːnɪˈlætrəl","pos":"adjective","senses":[{"en":"done by or affecting only one person, group or country involved in a situation without the agreement of the others","cn":"单方面的；单边的","ex":{"en":"a unilateral decision","cn":"单方面的决定"}}]}},"untenable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（论点、理论或立场）经不起反驳的，不堪一击的，站不住脚的","en":"An argument, theory, or position that is untenable cannot be defended successfully against criticism or attack.","ex":{"en":"This argument is untenable from an intellectual, moral and practical standpoint","cn":"从智识、道德和现实的角度来看，这一论点是站不住脚的。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"an untenable situation has become so difficult that it is impossible to continue 〔","cn":"局面〕难以维持的"},{"en":"an untenable argument, suggestion etc is impossible to defend 〔","cn":"论点等〕站不住脚的﹐不堪一击的"}]},"vocab":{"pos":"adj","senses":[{"en":"If something is untenable , you can't defend it or justify it. If your disagreement with your teacher puts you in an untenable position, you better just admit you made a mistake and get on with it."}]},"media":{"uk":"media/ldoce/hwd/bre/0/untenable0205.mp3","us":"media/ldoce/hwd/ame/c/untenable.mp3"},"examples":[{"en":"His position had become untenable and he was forced to resign.","cn":"他的地位已难以维持，因此他被迫辞职。"},{"en":"The scandal put the president in an untenable position .","cn":"这桩丑闻使总统处境艰难。"}],"oxford":{"phon":"ʌnˈtenəbl","pos":"adjective","senses":[{"en":"that cannot be defended against attack or criticism","cn":"难以捍卫的；站不住脚的；不堪一击的","ex":{"en":"His position had become untenable and he was forced to resign.","cn":"他的地位已难以维持，因此他被迫辞职。"}}]}},"upholstery":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"座套；椅套","en":"Upholstery is the soft covering on chairs and seats that makes them more comfortable to sit on.","ex":{"en":"...white leather upholstery","cn":"白色皮座套"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"material used to cover chairs 〔","cn":"椅子的〕被覆材料﹐垫衬料"},{"en":"the process of covering chairs with material 〔","cn":"座椅的〕加套装饰"}]},"vocab":{"pos":"n","senses":[{"en":"Upholstery refers to the covering on furniture. Without upholstery , your couch wouldn't be very comfortable."}]},"media":{"uk":"media/ldoce/hwd/bre/6/upholstery0205.mp3","us":"media/ldoce/hwd/ame/3/upholstery.mp3"},"oxford":{"phon":"ʌpˈhəʊlstəri","pos":"noun","senses":[{"en":"soft material that covers furniture such as armchairs and sofas","cn":"家具装饰品（或衬垫等）"},{"en":"the process or trade of upholstering","cn":"家具装饰；家具装饰业"}]}},"underclothing":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"同 underclothes","en":"Underclothing is the same as underclothes .","ex":{"en":"...a common brand of men's underclothing.","cn":"一个普通的男士内衣品牌"}}]}},"undisputed":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"无可争议的；毫无疑问的；确实的","en":"If you describe a fact or opinion as undisputed, you are trying to persuade someone that it is generally accepted as true or correct.","ex":{"en":"...the undisputed fact that he had broken the law.","cn":"他违反了法律这一毫无疑问的事实"}},{"pos":"ADJ 形容词","cn":"公认的；当之无愧的","en":"If you describe someone as the undisputed leader or champion, you mean that everyone accepts their position as leader or champion.","ex":{"en":"Seles won 10 tournaments, and was the undisputed world champion","cn":"塞莱斯拿到了10个锦标赛冠军，是当之无愧的世界冠军。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"known to be definitely true","cn":"无可争辩的﹐毫无疑问的"},{"en":"accepted by everyone","cn":"公认的"}]},"media":{"uk":"media/ldoce/hwd/bre/5/brelasdeundisputed.mp3","us":"media/ldoce/hwd/ame/1/laadundisputed.mp3"},"examples":[{"en":"the undisputed champion of the world","cn":"公认的世界冠军"},{"en":"undisputed facts","cn":"不容置疑的事实"}],"oxford":{"phon":"ˌʌndɪˈspjuːtɪd","pos":"adjective","senses":[{"en":"that cannot be questioned or proved to be false; that cannot be disputed","cn":"不容置疑的；毫无疑问的；不可争辩的","ex":{"en":"undisputed facts","cn":"不容置疑的事实"}},{"en":"that everyone accepts or recognizes","cn":"广为接受的；公认的","ex":{"en":"the undisputed champion of the world","cn":"公认的世界冠军"}}]}},"underway":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"happening now","cn":"在进行中的"},{"en":"something such as a boat or train that is underway is moving 〔","cn":"船﹑火车等〕在行进中的"}]},"media":{"uk":"media/ldoce/hwd/bre/a/brelasdeunderway.mp3","us":"media/ldoce/hwd/ame/5/laadunderway.mp3"},"examples":[{"en":"The project is already well underway .","cn":"项目已经顺利启动。"},{"en":"Your peace will be shattered when the tourist season gets underway (= starts ) .","cn":"一到旅游旺季﹐你的宁静生活就被打乱了。"}],"oxford":{"phon":"ˌʌndəˈweɪ","pos":"adjective","senses":[{"en":"having started","cn":"已经开始；在进行中","ex":{"en":"Preparations are well underway for a week of special events in May.","cn":"五月份特别活动周的准备工作已经顺利开展。"}}]}},"unthinkable":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"匪夷所思的；不可思议的；难以想象的","en":"If you say that something is unthinkable, you are emphasizing that it cannot possibly be accepted or imagined as a possibility.","ex":{"en":"Her strong Catholic beliefs made abortion unthinkable.","cn":"笃信天主教让她完全无法接受堕胎。"}},{"pos":"ADJ 形容词","cn":"匪夷所思的；难以想象的；不堪设想的","en":"You can use unthinkable to describe a situation, event, or action which is extremely unpleasant to imagine or remember.","ex":{"en":"This place is going to be unthinkable without you.","cn":"没有了你，真不知道这地方会变成什么样子。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"something that is impossible cannot happen or be done","cn":""},{"en":"something that is impractical is too expensive, takes too much time, is too difficult etc and therefore it is not sensible to try to do it","cn":""},{"en":"used when saying that something is completely impossible, especially because it is not allowed","cn":""}]},"collocations":{"phrases":["VERBS be, seem | make sth | consider sth This would have been considered unthinkable only a decade ago.","ADV. absolutely, completely, quite | almost, practically, virtually | hitherto, previously A hitherto unthinkable question was asked. | poli","PREP. to This course of action would have been unthinkable to the Russian generals."]},"media":{"uk":"media/ldoce/hwd/bre/e/unthinkable0205.mp3","us":"media/ldoce/hwd/ame/b/unthinkable.mp3"},"examples":[{"en":"Suddenly the unthinkable happened and he drew out a gun.","cn":"突然，难以相信的事情发生了，他拔出了手枪。"},{"en":"The time has come to think the unthinkable (= consider possibilities that used to be unacceptable).","cn":"现在该开始考虑以前不予考虑的事情了。"}],"oxford":{"phon":"ʌnˈθɪŋkəbl","pos":"adjective","senses":[{"en":"impossible to imagine or accept","cn":"难以想象的；不可思议的；难以置信的","ex":{"en":"This would have been considered unthinkable only a decade ago.","cn":"就在 10 年前这会被认为是不可思议的事。"}}]}},"unpick":{"collins":{"senses":[{"pos":"VERB 动词","cn":"拆（线）；拆开, 拆散","en":"If you unpick a piece of sewing, you remove the stitches from it.","ex":{"en":"You can always unpick the hems on the dungarees if you don't like them.","cn":"如果你不喜欢，你可以把工作服的褶边拆掉。"}},{"pos":"VERB 动词","cn":"找…的毛病;给…挑刺","en":"If someone unpicks a plan or policy, they disagree with it and examine it thoroughly in order to find any mistakes that they can use to defeat it.","ex":{"en":"A statesman who ought to know better wants to unpick last year's reform of Europe's common agricultural policy.","cn":"一个不甚了解情况的政客想对去年欧洲普遍的农业政策改革指手画脚。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to take out stitches from a piece of cloth or knitting","cn":"拆去〔衣料或编织物上〕的针脚[缝线]"},{"en":"to examine the different parts of a subject, deal etc, especially in order to find faults","cn":"挑…的刺﹐找…的毛病"}]},"media":{"uk":"media/ldoce/hwd/bre/4/unpick0205.mp3","us":"media/ldoce/hwd/ame/3/amelasdeunpick.mp3"},"examples":[{"en":"I didn’t want to unpick the past.","cn":"我不想翻旧账。"},{"en":"There are fears that the president might unpick the treaty.","cn":"有人担心总统会挑那个协议的毛病。"}],"oxford":{"phon":"ˌʌnˈpɪk","pos":"verb","senses":[{"en":"to take out stitches from a piece of sewing or knitting","cn":"拆去…的缝线；拆（编织物）的针脚","ex":{"en":"I unpicked the sleeve and started again.","cn":"我解开袖子，重新开始。"}}]}},"underdone":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(食品)未煮熟的，半生不熟的，不太熟的","en":"Underdone food has been cooked for less time than necessary, and so is not pleasant to eat.","ex":{"en":"The second batch of bread came out underdone.","cn":"第二炉面包烤得不太熟。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"raw food has not been cooked","cn":""},{"en":"uncooked food has not yet been cooked, but should be cooked before it is eaten","cn":""},{"en":"not cooked for long enough","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41underdone.mp3","us":"media/ldoce/hwd/ame/a/underdone.mp3"},"oxford":{"phon":"ˌʌndəˈdʌn","pos":"adjective","senses":[{"en":"not cooked enough","cn":"未煮熟的；欠火候的"}]}},"uranium":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"铀","en":"Uranium is a naturally occurring radioactive metal that is used to produce nuclear energy and weapons."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a heavy white metal that is radioactive and is used to produce nuclear power and nuclear weapons. It is a chemical element : symbol U","cn":"铀〔一种放射性化学元素﹐符号为U〕"}]},"collocations":{"phrases":["ADJ. natural | enriched a tonne of highly enriched uranium | depleted | weapons-grade","VERB + URANIUM mine | recover","URANIUM + NOUN ore, reserves | fuel | mine, miner, mining | enrichment"]},"media":{"uk":"media/ldoce/hwd/bre/d/uranium0205.mp3","us":"media/ldoce/hwd/ame/6/uranium.mp3"},"oxford":{"phon":"juˈreɪniəm","pos":"noun","senses":[{"en":"a chemical element. Uranium is a heavy, silver-white, radioactive metal, used mainly in producing nuclear energy.","cn":"铀（放射性化学元素）","ex":{"en":"a tonne of highly enriched uranium","cn":"一吨高纯度浓缩铀"}}]}},"upstart":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（初到某地或初出茅庐却）自命不凡的家伙","en":"You can refer to someone as an upstart when they behave as if they are important, but you think that they are too new in a place or job to be treated as important.","ex":{"en":"Many prefer a familiar authority figure to a young upstart.","cn":"很多人都更愿意跟自己熟悉的权威人物打交道，而不是一个年纪轻轻却自命不凡的家伙。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who behaves as if they were more important than they really are and who shows a lack of respect towards people who are more experienced or older","cn":"目中无人的新人[年轻人]﹔自命不凡的家伙"}]},"vocab":{"pos":"1 n adj 2 n","senses":[{"en":"An upstart is someone who's cocky and arrogant, and who doesn't show much respect for other people."}]},"media":{"uk":"media/ldoce/hwd/bre/2/upstart0205.mp3","us":"media/ldoce/hwd/ame/f/upstart.mp3"},"examples":[{"en":"a cheeky young upstart","cn":"傲慢无礼的后生小子"}],"oxford":{"phon":"ˈʌpstɑːt","pos":"noun","senses":[{"en":"a person who has just started in a new position or job but who behaves as if they are more important than other people, in a way that is annoying","cn":"自命不凡的新上任者；狂妄自大的新手"}]}},"unbeknown":{"collins":{"senses":[{"pos":"PREP-PHRASE 短语介词","cn":"在…不知情的情况下；瞒着…","en":"If something happens unbeknown to you or unbeknownst to you, you do not know about it.","ex":{"en":"I am appalled that children can mount up debts unbeknown to their parents","cn":"让我深感震惊的是，孩子们竟会背着父母欠债累累。"}}]},"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"to not know about a situation or about something that is happening, especially when you should know about it","cn":""},{"en":"to know nothing about a subject or situation because you have not experienced it, read about it, or heard about it","cn":""},{"en":"use this about something that was happening without you knowing about it at the time","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41unbeknown.mp3","us":"media/ldoce/hwd/ame/3/ld41unbeknown.mp3"},"examples":[{"en":"Unbeknown to her they had organized a surprise party.","cn":"他们瞒着她为她筹备了一个意外惊喜的聚会。"},{"en":"Unbeknown to him, his wife had been trying to phone him all morning.","cn":"他哪里知道﹐妻子一上午都在给他打电话。"}],"oxford":{"phon":"ˌʌnbɪˈnəʊn","pos":"adjective","senses":[{"en":"without the person mentioned knowing","cn":"瞒着；背着","ex":{"en":"Unbeknown to her they had organized a surprise party.","cn":"他们瞒着她筹备了一个惊喜聚会。"}}]}},"undismayed":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不害怕的；不气馁的；不沮丧的","en":"If you say that someone is undismayed by something unpleasant or unexpected, you mean that they do not feel any fear, worry, or sadness about it.","ex":{"en":"He was undismayed by the prospect of failure.","cn":"想到可能会失败，他并不气馁。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not worried or frightened by something unpleasant or unexpected","cn":"不沮丧的﹐镇定的"}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41undismayed.mp3","us":"media/ldoce/hwd/ame/5/ld41undismayed.mp3"},"oxford":{"phon":"ˌʌndɪsˈmeɪd","pos":"adjective","senses":[{"en":"not worried or frightened by something unpleasant or unexpected","cn":"处变不惊；不惊恐；镇定","ex":{"en":"He was undismayed by the havoc he encountered on his return.","cn":"他对回国时遇到的破坏并不感到沮丧。"}}]}},"unabridged":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未删节的；未节略的；足本的；完整的","en":"An unabridged piece of writing, for example a book or article, is complete and not shortened in any way.","ex":{"en":"...the unabridged version of 'War and Peace'.","cn":"《战争与和平》的全本"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a piece of writing, speech etc that is unabridged is in its full form and has not been made shorter 〔","cn":"文章﹑演讲等〕未删节的﹐全文的"}]},"vocab":{"pos":"adj n","senses":[{"en":"When a book is unabridged it's the whole thing, with nothing cut out. If you're seeking a definition for a very unusual word, you may need to look in an unabridged dictionary."}]},"media":{"uk":"media/ldoce/hwd/bre/d/unabridged0205.mp3","us":"media/ldoce/hwd/ame/6/unabridged.mp3"},"examples":[{"en":"the complete and unabridged works of Dickens","cn":"未删节版狄更斯全集"}],"oxford":{"phon":"ˌʌnəˈbrɪdʒd","pos":"adjective","senses":[{"en":"complete, without being made shorter in any way","cn":"（版本）完整的；未删节的"}]}},"undaunted":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无畏的；勇敢的；不气馁的","en":"If you are undaunted, you are not at all afraid or worried about dealing with something, especially something that would frighten or worry most people.","ex":{"en":"Undaunted by the scale of the job, Lesley set about planning how each room should look.","cn":"莱斯利并没有被这项浩大的工程所吓倒，开始着手规划每个房间的格局。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"to continue trying to do something in a very patient and determined way, in spite of difficulties","cn":""},{"en":"to continue working or studying in a very determined way in order to achieve something","cn":""},{"en":"to force yourself to continue working, practising etc in order to achieve something, even though it needs a lot of effort","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"If you're undaunted , you're not afraid or intimidated. As a great surfer, you remain undaunted as you seek out dangerous waters to ride the biggest waves."}]},"media":{"uk":"media/ldoce/hwd/bre/c/undaunted0205.mp3","us":"media/ldoce/hwd/ame/a/undaunted.mp3"},"examples":[{"en":"He seemed undaunted by all the opposition to his idea.","cn":"尽管他的思想屡遭非难，他似乎仍然百折不挠。"},{"en":"Undaunted by the enormity of the task, they began rebuilding the village.","cn":"他们不畏任务艰巨﹐开始重建村庄。"}],"oxford":{"phon":"ˌʌnˈdɔːntɪd","pos":"adjective","senses":[{"en":"still enthusiastic and determined, despite difficulties, danger, etc.","cn":"顽强；百折不挠；坚强不屈","ex":{"en":"He seemed undaunted by all the opposition to his idea.","cn":"尽管他的思想屡遭非难，他似乎仍然百折不挠。"}}]}},"unfettered":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"自由的；不受拘束的","en":"If you describe something as unfettered, you mean that it is not controlled or limited by anyone or anything.","ex":{"en":"...unfettered free trade","cn":"不受限制的自由贸易"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not restricted by laws or rules","cn":"不受法规约束的﹐自由的"}]},"vocab":{"pos":"adj","senses":[{"en":"The adjective unfettered describes something or someone uninhibited and unrestrained. If you write mysteries novels for a living you probably turn your unfettered imagination to murder and mayhem."}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41unfettered.mp3","us":"media/ldoce/hwd/ame/0/unfettered.mp3"},"examples":[{"en":"an unfettered free market","cn":"不受约束的自由市场"},{"en":"unfettered economic activity","cn":"自由的经济活动"}],"oxford":{"phon":"ʌnˈfetəd","pos":"adjective","senses":[{"en":"not limited in any way","cn":"无限制的；不受约束的；自由的","ex":{"en":"an unfettered free market","cn":"不受约束的自由市场"}}]}},"unburden":{"collins":{"senses":[{"pos":"VERB 动词","cn":"卸去…的负担；倾吐（心事）","en":"If you unburden yourself or your problems to someone, you tell them about something which you have been secretly worrying about.","ex":{"en":"The Centre became a place where many came to unburden themselves, to talk about their hopes and fears","cn":"该中心已经成了许多人前来倾诉心事、谈论心中希望与忧惧的地方。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to tell someone your problems, secrets etc so that you feel better (","cn":"对某人)诉苦，吐露心事"}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41unburden.mp3","us":"media/ldoce/hwd/ame/2/unburden.mp3"},"examples":[{"en":"She needed to unburden herself to somebody.","cn":"她需要找个人诉诉心里的苦衷。"}],"oxford":{"phon":"ˌʌnˈbɜːdn","pos":"verb","senses":[{"en":"to talk to somebody about your problems or something you have been worrying about, so that you feel less anxious","cn":"倾诉；诉说；诉苦","ex":{"en":"She needed to unburden herself to somebody.","cn":"她需要找个人诉诉心里的苦衷。"}},{"en":"to take something that causes a lot of work or worry away from somebody/something","cn":"给…解除（负担）；分忧"}]}},"uncomplaining":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"任劳任怨的；不发牢骚的；不抱怨的","en":"If you describe someone as uncomplaining, you approve of them because they do difficult or unpleasant things and do not complain about them.","ex":{"en":"He was a cheerful and uncomplaining travel companion.","cn":"他是一个乐观开朗从不抱怨的旅伴。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"willing to accept a difficult or unpleasant situation without complaining","cn":"顺从的﹔没有怨言的﹐不诉苦的"}]},"media":{"uk":"media/ldoce/hwd/bre/9/uncomplaining0205.mp3","us":"media/ldoce/hwd/ame/b/laaduncomplaining.mp3"},"oxford":{"phon":"ˌʌnkəmˈpleɪnɪŋ","pos":"adjective","senses":[{"en":"not saying that you are unhappy about a difficult or unpleasant situation; not saying that you are in pain","cn":"任劳任怨的；不抱怨的"}]}},"uncivilized":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"粗野的；无礼的；无教养的；不文明的","en":"If you describe someone's behaviour as uncivilized, you find it unacceptable, for example because it is very cruel or very rude.","ex":{"en":"The campaign has abounded in mutual accusations of uncivilised behaviour","cn":"整个活动中双方频频指责对方粗野。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"behaviour that is uncivilized is rude or socially unacceptable 〔","cn":"行为〕野蛮的﹐不文明的"},{"en":"societies that are uncivilized have a very simple way of life, and have not developed social, legal, economic etc systems 〔","cn":"社会〕未开化的﹐远离文明的"}]},"media":{"uk":"media/ldoce/hwd/bre/c/uncivilized0205.mp3","us":"media/ldoce/hwd/ame/6/ld41uncivilized.mp3"},"examples":[{"en":"I have worked in the wildest and most uncivilized parts of the world.","cn":"我曾在世界上最荒凉、最原始的地区工作过。"}],"oxford":{"phon":"ʌnˈsɪvəlaɪzd","pos":"adjective","senses":[{"en":"not behaving in a way that is acceptable according to social or moral standards","cn":"不合社会（或道德）规范的；无教养的"},{"en":"not having developed a modern culture and way of life","cn":"未开化的；远离文明的","ex":{"en":"I have worked in the wildest and most uncivilized parts of the world.","cn":"我曾在世界上最荒凉、最原始的地区工作过。"}}]}},"unambiguous":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不含糊的；清晰的；明确的","en":"If you describe a message or comment as unambiguous, you mean that it is clear and cannot be understood wrongly.","ex":{"en":"...an election result that sent the party an unambiguous message","cn":"向该党传递明确信息的选举结果"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"language, instructions etc that are plain are easy to understand because there is nothing difficult or unnecessary in them that might be confusing","cn":""},{"en":"having only one possible meaning and therefore clear","cn":""},{"en":"expressed very clearly and including every detail, so that no part of your meaning is hidden","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"If something is unambiguous , there are no two ways to interpret it. If your girlfriend burns all your letters, texts you that she hates you, and moves a thousand miles away, the unambiguous message is that she’s finished with you."}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41unambiguous.mp3","us":"media/ldoce/hwd/ame/2/unambiguous.mp3"},"examples":[{"en":"The message was clear and unambiguous — ‘Get out!’","cn":"这其中的含义明确无疑 — “滚开！”"},{"en":"an unambiguous statement","cn":"明确的陈述"}],"oxford":{"phon":"ˌʌnæmˈbɪɡjuəs","pos":"adjective","senses":[{"en":"clear in meaning; that can only be understood in one way","cn":"意思清楚的；明确的；毫不含糊的；无歧义的","ex":{"en":"an unambiguous statement","cn":"明确的陈述"}}]}},"unassailable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"坚不可摧的；无懈可击的","en":"If you describe something or someone as unassailable, you mean that nothing can alter, destroy, or challenge them.","ex":{"en":"That was enough to give Mansell an unassailable lead","cn":"那足以让曼塞尔获得别人无法撼动的领先地位。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not able to be criticized, made weaker, or beaten","cn":"不容置疑的﹔攻不破的"}]},"vocab":{"pos":"adj","senses":[{"en":"The adjective unassailable means without flaws or indefensible. If you are going to get home late (again!), you'd better have an unassailable alibi for your parents, or else you should plan on not seeing the outside of your room for a while."}]},"media":{"uk":"media/ldoce/hwd/bre/b/unassailable0205.mp3","us":"media/ldoce/hwd/ame/3/laadunassailable.mp3"},"examples":[{"en":"Their ten-point lead puts the team in an almost unassailable position.","cn":"他们以十分领先的优势使整个球队处于难以撼动的地位。"},{"en":"The party now has an unassailable lead.","cn":"这个党的领先地位现在坚不可摧。"}],"oxford":{"phon":"ˌʌnəˈseɪləbl","pos":"adjective","senses":[{"en":"that cannot be destroyed, defeated or questioned","cn":"无法摧毁的；不可战胜的；不容置疑的","ex":{"en":"The party now has an unassailable lead.","cn":"这个党的领先地位现在坚不可摧。"}}]}},"unhurried":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不慌不忙的；从容不迫的；悠闲的","en":"If you describe something as unhurried, you approve of it because it is relaxed and slow, and is not rushed or anxious.","ex":{"en":"...an unhurried pace of life.","cn":"悠闲的生活节奏"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not moving quickly or not doing something quickly","cn":""},{"en":"happening, developing, or changing slowly over a long period of time","cn":""},{"en":"moving or doing something slowly, especially because you are enjoying what you are doing and do not have to hurry","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/3/unhurried0205.mp3","us":"media/ldoce/hwd/ame/1/laadunhurried.mp3"},"examples":[{"en":"Lynn walked unhurriedly into the kitchen.","cn":"林恩不慌不忙地走进了厨房。"},{"en":"the unhurried pace of a small town","cn":"小镇悠闲的生活节奏"}],"oxford":{"phon":"ʌnˈhʌrid","pos":"adjective","senses":[{"en":"relaxed and calm; not done too quickly","cn":"从容的；不慌不忙的","ex":{"en":"It’s a quiet resort where life is taken at an easy, unhurried pace.","cn":"那是个宁静的度假胜地，那里的生活安逸、从容。"}}]}},"usn":{"collins":{"senses":[{"pos":"N-PROPER 专有名词","cn":"美国海军","en":"USN is an abbreviation for (缩略=) United States Navy ."}]},"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"the abbreviation of the United States Navy","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/e/p028-000012466.mp3","us":"media/ldoce/hwd/ame/6/laadusn.mp3"},"oxford":{"phon":"ˌjuː es ˈen","pos":"abbreviation","senses":[{"en":"United States Navy","cn":"美国海军"}]}},"undecided":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无法决定的；未作出决定的；犹豫不决的","en":"If someone is undecided, they cannot decide about something or have not yet decided about it.","ex":{"en":"After university she was still undecided as to what career she wanted to pursue","cn":"大学毕业后她仍决定不下来要从事什么职业。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who is undecided has not yet decided about something, especially something important","cn":""},{"en":"to deliberately avoid or delay making an important decision so that you are free to decide later","cn":""},{"en":"not having made a decision about something important","cn":"未决定的"}]},"collocations":{"phrases":["VERBS be, feel, seem, sound | remain | leave sth The question cannot be left undecided.","ADV. very | quite | still | as yet She is as yet undecided in which direction she wants to make her future career.","PREP. about He is still undecided about what to do. | as to They are undecided as to whether to buy a new car. | on The government remains u"]},"media":{"uk":"media/ldoce/hwd/bre/8/undecided0205.mp3","us":"media/ldoce/hwd/ame/7/undecided.mp3"},"examples":[{"en":"He was undecided as to what to do next.","cn":"他对下一步要做什么犹豫不决。"},{"en":"The venue for the World Cup remains undecided.","cn":"世界杯的举办地点尚未确定。"}],"oxford":{"phon":"ˌʌndɪˈsaɪdɪd","pos":"adjective","senses":[{"en":"not having made a decision about somebody/something","cn":"未拿定主意；犹豫不决","ex":{"en":"I’m still undecided (about) who to vote for.","cn":"我还拿不定主意投谁的票。"}},{"en":"not having been decided","cn":"尚未被确定；悬而未决","ex":{"en":"The venue for the World Cup remains undecided.","cn":"世界杯的举办地点尚未确定。"}}]}},"upmarket":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（产品或服务）高端的，高档的","en":"Upmarket products or services are expensive, of good quality, and intended to appeal to people in a high social class.","ex":{"en":"Anne chose an upmarket agency aimed at professional people.","cn":"安妮选择了一家以专业人士为服务对象的高端代理商。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"an expensive hotel, restaurant, area etc is very fashionable and it is expensive to stay, eat, or live there","cn":""},{"en":"an exclusive area, school, shop, club etc is very expensive, and only a few very rich people have enough money to live there or use it","cn":""},{"en":"a luxurious building or room is large, very comfortable, and has expensive decorations and furniture","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/b/brelasdeupmarket.mp3","us":"media/ldoce/hwd/ame/a/laadupmarket.mp3"},"examples":[{"en":"The company has been forced to move more upmarket.","cn":"这家公司被迫进一步转向高端市场。"},{"en":"an upmarket restaurant","cn":"高级餐厅"}],"oxford":{"phon":"ˌʌpˈmɑːkɪt","pos":"adverb","senses":[{"en":"in a way that involves buying or selling goods and services that are expensive and of high quality","cn":"向高档，向高级消费市场","ex":{"en":"The company has been forced to move more upmarket.","cn":"公司被迫进一步转向高端市场。"}},{"en":"designed for or used by people who belong to a high social class or have a lot of money","cn":"高档的；高级的","ex":{"en":"an upmarket restaurant","cn":"高级餐厅"},"pos":"adjective"}]}},"undercoat":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"底漆；内涂层","en":"An undercoat is a covering of paint or varnish put onto a surface as a base for a final covering of paint or varnish."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a layer of paint that you put onto a surface before you put the final layer on","cn":"内[底]涂层"}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41undercoat.mp3","us":"media/ldoce/hwd/ame/f/undercoat.mp3"},"oxford":{"phon":"ˈʌndəkəʊt","pos":"noun","senses":[{"en":"a layer of paint under the final layer; the paint used for this","cn":"底涂层；内涂层；底层涂料","ex":{"en":"Apply the undercoat first.","cn":"先涂底漆。"}}]}},"uninspired":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"缺乏创造力的；单调乏味的","en":"If you describe something or someone as uninspired, you are criticizing them because they do not seem to have any original or exciting qualities.","ex":{"en":"The script was singularly uninspired","cn":"这个剧本极其没有创意。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not showing any imagination","cn":"缺乏创见的﹐没有想象力的﹔平凡的"}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41uninspired.mp3","us":"media/ldoce/hwd/ame/f/uninspired.mp3"},"examples":[{"en":"an uninspired performance","cn":"乏味的演出"}],"oxford":{"phon":"ˌʌnɪnˈspaɪəd","pos":"adjective","senses":[{"en":"not original or exciting","cn":"无创意的；不激励人心的；乏味的","ex":{"en":"It's an album of perfectly competent, if uninspired songs.","cn":"这是一张完全有能力但缺乏灵感的歌曲的专辑。"}}]}},"unopposed":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"不反对的；无对手的","en":"In something such as an election or a war, if someone is unopposed, there are no opponents competing or fighting against them.","ex":{"en":"The council re-elected him unopposed as party leader","cn":"委员会一致通过再次选举他为党的领袖。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"without any opponent or opposition, especially in an election 〔","cn":"尤指选举中〕没有对手的﹔无人反对的"}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41unopposed.mp3","us":"media/ldoce/hwd/ame/7/laadunopposed.mp3"},"examples":[{"en":"The party leader was re-elected unopposed.","cn":"这个党派的领袖再次顺利当选。"},{"en":"Roberts was elected unopposed as president.","cn":"罗伯茨没有受到任何阻挠﹐顺利当选总裁。"}],"oxford":{"phon":"ˌʌnəˈpəʊzd","pos":"adjective","senses":[{"en":"not opposed or stopped by anyone","cn":"无人反对；无阻挠","ex":{"en":"The party leader was re-elected unopposed.","cn":"这个党派的领袖再次顺利当选。"}}]}},"underweight":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"体重偏轻的；过瘦的","en":"If someone is underweight, they are too thin, and therefore not healthy.","ex":{"en":"Nearly a third of the children were severely underweight.","cn":"近1/3的孩子体重严重偏轻。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"having little fat on your body","cn":""},{"en":"thin in an attractive way","cn":""},{"en":"thin in an attractive and graceful way – used especially about parts of the body, and used especially about women","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/b/underweight0205.mp3","us":"media/ldoce/hwd/ame/7/underweight.mp3"},"examples":[{"en":"She is a few pounds underweight for (= in relation to) her height.","cn":"就其身高而言，她的体重还差几磅。"},{"en":"Women who smoke risk giving birth to underweight babies.","cn":"抽烟的女性有可能会生下体重不足的婴儿。"}],"oxford":{"phon":"ˌʌndəˈweɪt","pos":"adjective","senses":[{"en":"weighing less than the normal or expected weight","cn":"体重不足的；未达到正常体重的","lab":"British English","ex":{"en":"The baby was dangerously underweight at birth.","cn":"婴儿出生时体重严重不足。"}}]}},"unstinting":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"慷慨的；大方的","en":"Unstinting help, care, or praise is great in amount or degree and is given generously.","ex":{"en":"The task of producing the text was made easier by the unstinting help and generosity extended to me.","cn":"在人们的慷慨帮助下，我写这篇文章的工作变得轻松了许多。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"unstinting support, help, praise etc is complete and given willingly 〔","cn":"支持﹑帮助﹑赞扬等〕慷慨的﹐大方的"}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41unstinting.mp3","us":"media/ldoce/hwd/ame/6/unstinting.mp3"},"examples":[{"en":"They were unstinting in their praise.","cn":"他们赞不绝口。"},{"en":"unstinting support","cn":"全力的支持"}],"oxford":{"phon":"ʌnˈstɪntɪŋ","pos":"adjective","senses":[{"en":"given or giving generously","cn":"慷慨的；大方的；无限的","ex":{"en":"unstinting support","cn":"全力的支持"}}]}},"unmatched":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"无与伦比的；无可匹敌的","en":"If you describe something as unmatched, you are emphasizing that it is better or greater than all other things of the same kind.","ex":{"en":"...a landscape of unmatched beauty","cn":"无与伦比的美景"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"better than any other","cn":"无可匹敌的﹐无双的"}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41unmatched.mp3","us":"media/ldoce/hwd/ame/5/unmatched.mp3"},"examples":[{"en":"He had a talent unmatched by any other politician of this century.","cn":"他的才华是本世纪其他政坛人物所望尘莫及的。"},{"en":"a woman of unmatched beauty","cn":"美貌绝伦的女子"}],"oxford":{"phon":"ˌʌnˈmætʃt","pos":"adjective","senses":[{"en":"better than all others","cn":"无比的；无双的；出类拔萃的","ex":{"en":"He had a talent unmatched by any other politician of this century.","cn":"他的才华是本世纪其他政坛人物望尘莫及的。"}}]}},"uganda":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"a country in east central Africa, between the Democratic Republic of the Congo and Kenya. Population: 34,758,809 (2014). Capital: Kampala. After Uganda became independent from the UK in 1962, the country experienced many economic and political problems, especi","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/d/p028-000012365.mp3","us":"media/ldoce/hwd/ame/d/p028-000012365.mp3"},"oxford":{"phon":"juˈɡændə","pos":"","senses":[{"en":"a country in East Africa. Its capital city is Kampala and its official language is English. The economy is based mainly on farming, and its main exports are cotton and coffee. From 1894 to 1962 Uganda was a British protectorate (= a country controlled and protected by Britain), and it then became an independent member of the Commonwealth. In the 1970s the country suffered under the violent rule of Idi Amin. One of his acts was to force Ugandan Asians to leave the country, and many of them settled in Britain.","cn":"乌干达（东非国家）"}]}},"unswerving":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"坚定不移的；立场坚定的；毫不动摇的","en":"If you describe someone's attitude, feeling, or way of behaving as unswerving, you mean that it is strong and firm and does not weaken or change.","ex":{"en":"In his diary of 1944 he proclaims unswerving loyalty to the monarchy.","cn":"他在1944年的日记里声称对君主忠贞不贰。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"an unswerving belief or attitude is one that is very strong and never changes 〔","cn":"信念﹑态度〕坚定不移的"},{"en":"unswerving loyalty/commitment/support etc a politician with unswerving loyalty to the president","cn":"一名对总统忠心耿耿的政治家"}]},"vocab":{"pos":"adj","senses":[{"en":"Something that's unswerving is strong and trustworthy. You might promise to have unswerving faith in your favorite baseball team, even when they don't make it to the playoffs."}]},"media":{"uk":"media/ldoce/hwd/bre/c/unswerving0205.mp3","us":"media/ldoce/hwd/ame/c/unswerving.mp3"},"examples":[{"en":"unswerving loyalty/support, etc.","cn":"始终如一的忠诚、支持等"}],"oxford":{"phon":"ʌnˈswɜːvɪŋ","pos":"adjective","senses":[{"en":"strong and not changing or becoming weaker","cn":"坚定的；不懈的；始终如一的","ex":{"en":"unswerving loyalty/support, etc.","cn":"始终如一的忠诚、支持等"}}]}},"uplifted":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（脸或手臂）扬起的，抬起的","en":"If people's faces or arms are uplifted, they are pointing them upwards or are holding them up.","ex":{"en":"The men support the ballerinas, who pose with their uplifted arms.","cn":"男演员托举着女芭蕾舞演员，她们在上面抬臂摆出造型。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"昂扬的；振奋的；鼓舞的；兴奋的","en":"If something makes you feel uplifted, it makes you feel very cheerful and happy.","ex":{"en":"...people whose presence left you feeling uplifted, happy and full of energy.","cn":"那些一出现就让你感到兴奋、开心和活力十足的人"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"feeling happier and more hopeful","cn":"振奋的，受鼓舞的"},{"en":"raised upwards","cn":"被提[抬，举]起的"}]},"media":{"uk":"media/ldoce/hwd/bre/3/uplifted0205.mp3","us":"media/ldoce/hwd/ame/9/laaduplifted.mp3"},"examples":[{"en":"a sea of uplifted faces","cn":"一张张扬起的脸"},{"en":"He felt uplifted by her presence.","cn":"她的出现让他觉得精神振奋。"}],"oxford":{"phon":"ˌʌpˈlɪftɪd","pos":"adjective","senses":[{"en":"feeling happy and full of hope","cn":"兴冲冲；意气昂扬","g":"[not before noun]","ex":{"en":"Everyone left the meeting feeling uplifted.","cn":"会议结束时，每个人都心情振奋。"}},{"en":"lifted upwards","cn":"抬起的；昂起的；举起的","lab":"literary","ex":{"en":"a sea of uplifted faces","cn":"一张张扬起的脸"}}]}},"unequalled":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"无与伦比的；无敌的","en":"If you describe something as unequalled, you mean that it is greater, better, or more extreme than anything else of the same kind.","ex":{"en":"This record figure was unequalled for 13 years","cn":"这项纪录保持了13年，无人能破。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"better than any other","cn":"无可匹敌的﹐无双的"}]},"media":{"uk":"media/ldoce/hwd/bre/e/unequalled0205.mp3","us":"media/ldoce/hwd/ame/1/unequaled.mp3"},"examples":[{"en":"an unequalled record of success","cn":"空前的成功纪录"},{"en":"The hotel has a range of facilities unequalled in the city.","cn":"这家酒店拥有本市最好的各种设施。"}],"oxford":{"phon":"ʌnˈiːkwəld","pos":"adjective","senses":[{"en":"better than all others","cn":"无比的；无双的；出类拔萃的","ex":{"en":"an unequalled record of success","cn":"空前的成功纪录"}}]}},"unskilled":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"无（特殊）技能的;未经专门训练的","en":"People who are unskilled do not have any special training for a job.","ex":{"en":"He went to Paris in search of work as an unskilled labourer","cn":"他没有任何劳动技能就到巴黎找起了工作。"}},{"pos":"ADJ 形容词","cn":"无需(特殊)技能的；不需专门训练的","en":"Unskilled work does not require any special training.","ex":{"en":"In the US, minorities and immigrants have generally gone into low-paid, unskilled jobs.","cn":"在美国，少数族裔和移民一般都会从事低薪水、无需特殊技能的工作。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"an unskilled worker has not been trained for a particular type of job 〔","cn":"工人〕无特殊技能的﹐未受专门训练的"},{"en":"unskilled work, jobs etc do not need people with special skills 〔","cn":"工作等〕无需特殊技能的"}]},"media":{"uk":"media/ldoce/hwd/bre/1/unskilled0205.mp3","us":"media/ldoce/hwd/ame/8/unskilled.mp3"},"examples":[{"en":"unskilled work","cn":"无需特别技能的工作"},{"en":"unskilled manual workers","cn":"非熟练体力劳动者"}],"oxford":{"phon":"ˌʌnˈskɪld","pos":"adjective","senses":[{"en":"not having or needing special skills or training","cn":"无特长的；无（需）特别技能的；无（需）专门训练的","ex":{"en":"unskilled manual workers","cn":"非熟练体力劳动者"}}]}},"unceremoniously":{"collins":{"senses":[{"pos":"ADV 副词","cn":"随便地；突然地；唐突地","en":"If someone or something is removed, left, or put somewhere unceremoniously, this is done in a sudden or rude way that shows they are not thought to be important.","ex":{"en":"She was unceremoniously dumped to be replaced by a leader who could win the election","cn":"她被人踢掉了，取而代之的是一个能够赢得选举的领导人物。"}}]},"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"in a rough or sudden way, without showing any respect or politeness","cn":"无礼地﹐粗鲁地﹔随便地"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41unceremoniousl.mp3","us":"media/ldoce/hwd/ame/0/laadunceremoniously.mp3"},"examples":[{"en":"They dumped his belongings unceremoniously on the floor.","cn":"他们粗暴地把他的物品摔到地板上。"},{"en":"He grabbed her arms and hauled her unceremoniously to her feet.","cn":"他抓住她的手臂﹐粗暴地把她拉起来。"}],"oxford":{"phon":"ˌʌnˌserəˈməʊniəsli","pos":"adverb","senses":[{"en":"in a rough or rude way, without caring about a person’s feelings","cn":"粗野地；粗暴无礼地","ex":{"en":"They dumped his belongings unceremoniously on the floor.","cn":"他们粗暴地把他的物品摔到地板上。"}}]}},"underfed":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"吃不饱的；食不果腹的","en":"People who are underfed do not get enough food to eat.","ex":{"en":"Kate still looks pale and underfed.","cn":"凯特看上去仍旧面色苍白、营养不良。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who is starving has not had enough food for a long time and will die soon if they do not eat","cn":""},{"en":"to have so little food to eat that you become ill or die","cn":""},{"en":"if people are hungry , they need food but do not have enough food to eat over a long period of time","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/5/underfed0205.mp3","us":"media/ldoce/hwd/ame/d/laadunderfed.mp3"},"oxford":{"phon":"ˌʌndəˈfed","pos":"adjective","senses":[{"en":"having had too little food to eat","cn":"食物不足的；没吃饱的"}]}},"unused":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未用过的；未使用的","en":"Something that is unused has not been used or is not being used at the moment.","ex":{"en":"...unused containers of food and drink","cn":"未用过的食物和饮料盛器"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不习惯的；不熟悉的","en":"If you are unused to something, you have not often done it or experienced it before, so it feels unusual and unfamiliar to you.","ex":{"en":"Mother was entirely unused to such hard work.","cn":"妈妈对这么艰苦的工作完全不习惯。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not being used, or never used","cn":"不在使用的﹔从未用过的"},{"en":"not experienced in dealing with something","cn":"不习惯于(做)某事的"}]},"collocations":{"phrases":["VERBS appear, be, lie, look, remain, sit, stand, stay The church has lain empty and unused since 1994. | leave sth The meeting rooms are lef","ADV. virtually"]},"media":{"uk":"media/ldoce/hwd/bre/0/ld44unused.mp3","us":"media/ldoce/hwd/ame/6/l3unused.mp3"},"examples":[{"en":"This is an easy routine, designed for anyone who is unused to exercise.","cn":"这是一套简单的固定动作，是为不常锻炼的人设计的。"},{"en":"She was unused to talking about herself.","cn":"她不习惯谈论自己。"}],"oxford":{"phon":"ˌʌnˈjuːzd","pos":"adjective","senses":[{"en":"not being used at the moment; never having been used","cn":"没用着的；闲着的；未用过的","ex":{"en":"The house was left unused for most of the year.","cn":"这所房子一年中大部分时间都处于闲置状态。"}},{"en":"not having much experience of something and therefore not knowing how to deal with it; not used to something","cn":"经验少；不习惯；不熟悉；不惯于","ex":{"en":"This is an easy routine, designed for anyone who is unused to exercise.","cn":"这是一套简单的固定动作，是为不常锻炼的人设计的。"}}]}},"unoccupied":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"空置的；没人居住的","en":"If a building is unoccupied, there is nobody in it.","ex":{"en":"The house was unoccupied at the time of the explosion","cn":"爆炸发生的时候房子里没有人。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"used about a place that has no one in it or no one using it","cn":""},{"en":"used about a seat, space, or room that is available to use because no one else is using it","cn":""},{"en":"used about a room or building that is available for people to pay to use","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/a/unoccupied0205.mp3","us":"media/ldoce/hwd/ame/2/laadunoccupied.mp3"},"examples":[{"en":"I sat down at the nearest unoccupied table.","cn":"我在最近的一张空桌旁坐了下来。"},{"en":"unoccupied territory","cn":"未沦陷的领土"}],"oxford":{"phon":"ˌʌnˈɒkjupaɪd","pos":"adjective","senses":[{"en":"empty, with nobody living there or using it","cn":"空着的；闲置的；无人占用的","ex":{"en":"an unoccupied house","cn":"闲置的房屋"}},{"en":"not controlled by foreign soldiers","cn":"未沦陷的；未被敌人占领的","ex":{"en":"unoccupied territory","cn":"未沦陷的领土"}}]}},"unscrupulous":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不诚实的；不道德的；无道德原则的","en":"If you describe a person as unscrupulous, you are critical of the fact that they are prepared to act in a dishonest or immoral way in order to get what they want.","ex":{"en":"These kids are being exploited by very unscrupulous people.","cn":"这些孩子正在被无良之人利用。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"behaving in a way that is intended to deceive people, for example by lying, cheating, or stealing","cn":""},{"en":"using your power in a dishonest way for your own advantage – used about people in official positions","cn":""},{"en":"good at secretly thinking of clever plans to trick people in order to get what you want","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Use the adjective unscrupulous to describe someone who behaves in a dishonest or unethical way."}]},"collocations":{"phrases":["VERBS be, seem | become","ADV. completely, quite, thoroughly In his desire for power, he has become thoroughly unscrupulous. | pretty"]},"media":{"uk":"media/ldoce/hwd/bre/8/unscrupulous0205.mp3","us":"media/ldoce/hwd/ame/4/unscrupulous.mp3"},"examples":[{"en":"unscrupulous methods","cn":"不公正的方法"},{"en":"unscrupulous employers","cn":"无耻的雇主"}],"oxford":{"phon":"ʌnˈskruːpjələs","pos":"adjective","senses":[{"en":"without moral principles; not honest or fair","cn":"不道德的；无道德原则的；不诚实的；不公正的","ex":{"en":"unscrupulous methods","cn":"不公正的方法"}}]}},"underwriter":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"保险商；承销商","en":"An underwriter is someone whose job involves agreeing to provide money for a particular activity or to pay for any losses that are made.","ex":{"en":"If the market will not buy the shares, the underwriter buys them","cn":"如果市场上没有人买这些股票，承销商就会买下来。"}},{"pos":"N-COUNT 可数名词","cn":"核保师（对投保项目进行风险评估并决定保险费率）","en":"An underwriter is someone whose job is to judge the risks involved in certain activities and decide how much to charge for insurance."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who makes insurance contracts","cn":"保险商﹔保险业务受理人"}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41underwriter.mp3","us":"media/ldoce/hwd/ame/1/underwriter.mp3"},"oxford":{"phon":"ˈʌndəraɪtə(r)","pos":"noun","senses":[{"en":"a person or organization that underwrites insurance policies, especially for ships","cn":"（尤指船只的）承保人，保险商"},{"en":"a person whose job is to estimate the risks involved in a particular activity and decide how much somebody must pay for insurance","cn":"核保人（对投保项目进行风险评估并决定保险费率）"}]}},"ungracious":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不礼貌的；不友好的","en":"If you describe a person or their behaviour as ungracious, you mean that they are not polite or friendly in their speech or behaviour.","ex":{"en":"...his ungracious behaviour during the Queen's recent visit","cn":"女王最近到访期间他的不得体行为"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not polite or friendly","cn":"无礼的﹔不友好的"}]},"media":{"uk":"media/ldoce/hwd/bre/3/ungracious0205.mp3","us":"media/ldoce/hwd/ame/2/laadungracious.mp3"},"examples":[{"en":"After Anna’s kindness to me, I don’t want to seem ungracious.","cn":"既然安娜已经向我示好﹐我也不想显得无礼。"}],"oxford":{"phon":"ʌnˈɡreɪʃəs","pos":"adjective","senses":[{"en":"not polite or friendly, especially towards somebody who is being kind to you","cn":"（尤指对别人的善意）不客气的，失礼的"}]}},"unquestioning":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"毫不怀疑的；毫不犹豫的","en":"If you describe a person or their beliefs as unquestioning, you are emphasizing that they accept something without any doubt or disagreement.","ex":{"en":"Isabella had been taught unquestioning obedience","cn":"伊莎贝拉被要求无条件服从。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"an unquestioning faith, attitude etc is very certain and without doubts 〔","cn":"信念﹑态度等〕无疑问[异议]的"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41unquestioning.mp3","us":"media/ldoce/hwd/ame/1/unquestioning.mp3"},"examples":[{"en":"unquestioning obedience","cn":"绝对的服从"},{"en":"an unquestioning belief in God","cn":"对上帝的笃信不移"}],"oxford":{"phon":"ʌnˈkwestʃənɪŋ","pos":"adjective","senses":[{"en":"done or given without asking questions, expressing doubt, etc.","cn":"不加质询的；不表示怀疑（等）的","ex":{"en":"unquestioning obedience","cn":"绝对的服从"}}]}},"unhinge":{"collins":{"senses":[{"pos":"VERB 动词","cn":"使精神错乱（或失常）","en":"If you say that an experience has unhinged someone, you mean that it has affected them so deeply that they have become mentally ill.","ex":{"en":"The stress of war temporarily unhinged him.","cn":"战争的压力让他一时丧失了神志。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make someone become very upset or mentally ill","cn":"使精神失常﹔使心烦意乱"}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41unhinge.mp3","us":"media/ldoce/hwd/ame/e/unhinge.mp3"},"examples":[{"en":"The terrible experience seemed to have unhinged him slightly.","cn":"这一可怕的经历似乎使他有点精神失常了。"}],"oxford":{"phon":"ʌnˈhɪndʒ","pos":"verb","senses":[{"en":"to make somebody seriously mentally ill","cn":"使精神失常（或错乱）","ex":{"en":"Her mind was unhinged by the death of her child and she never recovered.","cn":"孩子的死让她精神错乱，再也没有恢复过来。"}}]}},"unbending":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"固执的；顽固的；倔强的","en":"If you describe a person or their behaviour as unbending, you mean that they have very strict beliefs and attitudes, which they are unwilling to change.","ex":{"en":"He was rigid and unbending.","cn":"他很固执，态度很坚决。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"unwilling to change your opinions, decisions etc","cn":"不妥协的，固执的"}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41unbending.mp3","us":"media/ldoce/hwd/ame/5/unbending.mp3"},"oxford":{"phon":"ˌʌnˈbendɪŋ","pos":"adjective","senses":[{"en":"unwilling to change your opinions, decisions, etc.","cn":"顽固的；固执的；倔强的","ex":{"en":"Her father was a stern unbending man.","cn":"她的父亲是一个严厉不屈的人。"}}]}},"usable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"可用的；能用的","en":"If something is usable, it is in a good enough state or condition to be used.","ex":{"en":"Charity shops and jumble sales welcome usable clothes","cn":"慈善商店和义卖活动欢迎大家捐助能穿的衣服。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"something that is available can be used, for example because no one else is using it or it is not being used for anything else","cn":""},{"en":"use this about a chair, room, table etc that you can use because no-one else is using it","cn":""},{"en":"something that is usable can be used, because it works well or because it has been made ready for use","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Something that's usable can be successfully used right away for its intended purpose. If your car is usable , it's running just fine."}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld44usable.mp3","us":"media/ldoce/hwd/ame/8/laadusable.mp3"},"examples":[{"en":"How can we display this data in a usable form?","cn":"我们如何把这些数据以实用形式展示出来呢？"},{"en":"The bike is rusty but usable.","cn":"自行车生锈了，但还能骑。"}],"oxford":{"phon":"ˈjuːzəbl","pos":"adjective","senses":[{"en":"that can be used; in good enough condition to be used","cn":"能用的；可用的；适用的","ex":{"en":"How can we display this data in a usable form?","cn":"我们如何把这些数据以实用形式展示出来呢？"}}]}},"underlay":{"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"地毯衬垫","en":"Underlay is a layer of thick material that you place between a carpet and the floor to protect the carpet and make it feel warmer and softer."},{"pos":"","cn":"","en":"Underlay is the past tense of underlie."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"thick material that is put between a carpet and the floor 〔","cn":"地毯和地板之间的〕厚垫料﹐垫层"}]},"vocab":{"pos":"v n","senses":[{"en":"To underlay a thing is to give it a foundation or support by putting something sturdy under it. Underlay also means to be underneath."}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41underlay.mp3","us":"media/ldoce/hwd/ame/e/ld41underlay.mp3"},"oxford":{"phon":"ˈʌndəleɪ","pos":"noun","senses":[{"en":"a layer of thick material placed under a carpet to protect it","cn":"地毯衬垫"}]}},"unguarded":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"没有防备的；无人看管的","en":"If something is unguarded, nobody is protecting it or looking after it.","ex":{"en":"I should not leave my briefcase and camera bag unguarded.","cn":"我不该把我的公文包和相机包留在那儿无人看管。"}},{"pos":"ADJ 形容词","cn":"轻率的；不留神的","en":"If you do or say something in an unguarded moment, you do or say it carelessly and without thinking, especially when it is something that you did not want anyone to see or know.","ex":{"en":"The photographers managed to capture Jane in an unguarded moment","cn":"摄影师抓拍到了简不经意的瞬间。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a time when you are not paying attention to what you are doing or saying","cn":"一不留神﹔一不小心"},{"en":"an unguarded remark, statement etc is one that you make carelessly without thinking of the possible effects 〔","cn":"话语﹑声明等〕粗心大意的﹐不慎重的﹐轻率的"},{"en":"not guarded or protected by anyone","cn":"没有防卫[保护]的"}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41unguarded.mp3","us":"media/ldoce/hwd/ame/4/unguarded.mp3"},"examples":[{"en":"It was something I'd let out in an unguarded moment.","cn":"那是我一不留神说漏了嘴的话。"},{"en":"The museum was unguarded at night.","cn":"这个博物馆夜里无人看守。"}],"oxford":{"phon":"ʌnˈɡɑːdɪd","pos":"adjective","senses":[{"en":"not protected or watched","cn":"无防备的；无警戒的；无保护的","ex":{"en":"The museum was unguarded at night.","cn":"这个博物馆夜里无人看守。"}},{"en":"said or done carelessly, at a time when you are not thinking about the effects of your words or are not paying attention","cn":"不小心的；不谨慎的；不留神的","ex":{"en":"an unguarded remark","cn":"轻率的言论"}}]}},"unscheduled":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"计划外的；出乎意料的","en":"An unscheduled event was not planned to happen, but happens unexpectedly or because someone changes their plans at a late stage.","ex":{"en":"...an unscheduled meeting with Robin Cook","cn":"和罗宾·库克的不期而遇"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not planned or expected","cn":"偶然的﹐意外的"}]},"vocab":{"pos":"adj","senses":[{"en":"Something unscheduled is not planned for or anticipated. If your mother shows up at your door unscheduled , hope that you've been keeping the place nice and clean since you won't have time to tidy up before her arrival."}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41unscheduled.mp3","us":"media/ldoce/hwd/ame/f/laadunscheduled.mp3"},"examples":[{"en":"an unscheduled stop","cn":"计划外的停顿"},{"en":"The plane made an unscheduled stop in New York.","cn":"飞机在纽约临时停留。"}],"oxford":{"phon":"ʌnˈʃedjuːld","pos":"adjective","senses":[{"en":"that was not planned in advance","cn":"未事先计划的；非计划中的","ex":{"en":"an unscheduled stop","cn":"计划外的停顿"}}]}},"unease":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"焦虑；不安","en":"If you have a feeling of unease, you feel rather anxious or afraid, because you think that something is wrong.","ex":{"en":"Sensing my unease about the afternoon ahead, he told me,'These men are pretty easy to talk to.'","cn":"他感觉到了我对即将到来的下午忐忑不安，便对我说：“这些人说话都比较随和。”"}},{"pos":"N-UNCOUNT 不可数名词","cn":"不满；愤怒；紧张","en":"If you say that there is unease in a situation, you mean that people are dissatisfied or angry, but have not yet started to take any action.","ex":{"en":"He faces growing unease among the Democrats about the likelihood of war.","cn":"他面临民主党内对可能出现的战事不断滋长的不满情绪。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a feeling of worry or slight fear about something","cn":"不自在﹔忧虑﹐不安"},{"en":"sense/feeling of unease As she neared the door, Amy felt a growing sense of unease.","cn":"埃米越靠近门口，越感到不安。 public unease about defence policy 民众对国防政策的忧虑"}]},"collocations":{"phrases":["ADJ. deep, great, growing | certain, some, vague She felt a vague unease. | general, public","VERB + UNEASE feel | express, show They expressed their deep unease about the lack of security arrangements. | hide I smiled to hide my unea","UNEASE + VERB grow, rise","PREP. ~ about/at/over Many felt unease about the methods used.","PHRASES a feeling/sense of unease, a source of unease He looked in vain for the source of his unease."]},"media":{"uk":"media/ldoce/hwd/bre/e/unease0205.mp3","us":"media/ldoce/hwd/ame/6/unease.mp3"},"examples":[{"en":"There was a growing unease about their involvement in the war.","cn":"对他们卷入战争感到日益不安。"},{"en":"He was unable to hide his unease at the way the situation was developing.","cn":"他无法掩饰对局势演变的忧虑。"}],"oxford":{"phon":"ʌnˈiːz","pos":"noun","senses":[{"en":"the feeling of being worried or unhappy about something","cn":"不安；忧虑","ex":{"en":"a deep feeling/sense of unease","cn":"深刻的忧虑感／忧患意识"}}]}},"unsavoury":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"令人讨厌的;不道德的","en":"If you describe a person, place, or thing as unsavoury, you mean that you find them unpleasant or morally unacceptable.","ex":{"en":"The sport has long been associated with illegal wagers and unsavoury characters.","cn":"这项运动长期以来都与非法赌博及黑道人物联系在一起。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"unpleasant or morally unacceptable","cn":"令人不快的﹔名声不好的"}]},"media":{"uk":"media/ldoce/hwd/bre/c/unsavoury0205.mp3","us":"media/ldoce/hwd/ame/f/unsavory.mp3"},"examples":[{"en":"Her friends are all pretty unsavoury characters.","cn":"她的朋友尽是些不三不四的人。"},{"en":"an unsavoury incident","cn":"令人厌恶的事件"}],"oxford":{"phon":"ʌnˈseɪvəri","pos":"adjective","senses":[{"en":"unpleasant or offensive; not considered morally acceptable","cn":"讨厌的；无礼的；声名狼藉的；不道德的","ex":{"en":"an unsavoury incident","cn":"令人厌恶的事件"}}]}},"untouchable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不可触动的；不受影响的；碰不得的","en":"If you say that someone is untouchable, you mean that they cannot be affected or punished in any way.","ex":{"en":"I want to make it clear, however, that no one is untouchable in this investigation.","cn":"但我想说明白一点，这次调查谁都逃不了。"}},{"pos":"ADJ 形容词","cn":"高人一等的；无与伦比的；无可匹敌的","en":"If you describe someone, especially a sports player or entertainer, as untouchable, you are emphasizing that they are better than anyone else in what they do.","ex":{"en":"A lot of the players began to feel they were untouchable.","cn":"许多球手开始觉得自己天下无敌。"}},{"pos":"N-COUNT 可数名词","cn":"不可接触者，贱民（指印度社会最低阶层的人）","en":"Some people refer to Hindus of the lowest social rank as untouchables .","ex":{"en":"He was born an untouchable in a very poor village in south India.","cn":"他出身贱民，生于印度南部一个非常贫困的村子。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who is untouchable is in such a strong position that they cannot be defeated, affected, or punished 〔","cn":"人因地位稳固而〕碰不得的﹐不受影响的﹐不能被击败的"},{"en":"belonging to the lowest social group, especially in the Hindu caste system","cn":"社会最底层的；〔尤指印度种姓制度中〕贱民的"}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41untouchable.mp3","us":"media/ldoce/hwd/ame/f/untouchable.mp3"},"examples":[{"en":"Given his political connections, he thought he was untouchable.","cn":"他有一些政界关系，所以自认为谁也管不了他。"},{"en":"The department's budget is untouchable.","cn":"这个部门的预算是不容变动的。"}],"oxford":{"phon":"ʌnˈtʌtʃəbl","pos":"adjective","senses":[{"en":"a person who is untouchable is in a position where they are unlikely to be punished or criticized","cn":"不可处罚（或批评）的；管不了的","ex":{"en":"Given his political connections, he thought he was untouchable.","cn":"他有一些政界关系，所以自认为谁也管不了他。"}},{"en":"that cannot be touched or changed by other people","cn":"不可触及（或改变）的","ex":{"en":"The department's budget is untouchable.","cn":"这个部门的预算是不容变动的。"}},{"en":"(in India in the past) belonging to or connected with the Hindu social class (or caste) that was considered by other classes to be the lowest","cn":"（旧时印度）贱民的，不可接触者的"},{"en":"(in India in the past) a member of a Hindu social class (or caste) that was considered by other classes to be the lowest","cn":"（旧时印度）贱民，不可接触者","pos":"noun"}]}},"unattached":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未婚的；没有女朋友（或男朋友）的","en":"Someone who is unattached is not married or does not have a girlfriend or boyfriend.","ex":{"en":"I knew only two or three unattached men.","cn":"我只认识两三个未婚的男士。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not married or involved in a romantic relationship","cn":"未婚的﹐单身的﹔未恋爱的"},{"en":"not connected or fastened to anything","cn":"无关系的﹔非附属的﹔独立的"}]},"vocab":{"pos":"adj","senses":[{"en":"Unattached things are not connected or fastened. People can also be unattached, which usually means they don't have a long-term sweetheart."}]},"media":{"uk":"media/ldoce/hwd/bre/1/unattached0205.mp3","us":"media/ldoce/hwd/ame/1/unattached.mp3"},"examples":[{"en":"He was still unattached at the age of 34.","cn":"他 34 岁时还是单身。"},{"en":"According to Jo, Mark was still unattached.","cn":"据乔说﹐马克仍然单身。"}],"oxford":{"phon":"ˌʌnəˈtætʃt","pos":"adjective","senses":[{"en":"not married or involved in a romantic relationship","cn":"未婚的；单身的；未恋爱的","ex":{"en":"He was still unattached at the age of 34.","cn":"他 34 岁时还是单身。"}},{"en":"not connected with or belonging to a particular group or organization","cn":"不属于团体或组织的；无所属的；无党派的；独立的"}]}},"unruffled":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"沉着的；处乱不惊的","en":"If you describe someone as unruffled, you mean that they are calm and do not seem to be affected by surprising or frightening events.","ex":{"en":"Anne had remained unruffled, very cool and controlled.","cn":"安妮处乱不惊，十分冷静沉着。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"calm and not upset by a difficult situation – use this to show approval","cn":"平静的﹔沉着的〔含褒义〕"}]},"media":{"uk":"media/ldoce/hwd/bre/d/unruffled0205.mp3","us":"media/ldoce/hwd/ame/0/unruffled.mp3"},"examples":[{"en":"He remained unruffled by their accusations.","cn":"对于他们的指控他处之泰然。"},{"en":"Emily remained completely unruffled by the chaos.","cn":"埃米莉面对这混乱的局面毫不慌张。"}],"oxford":{"phon":"ʌnˈrʌfld","pos":"adjective","senses":[{"en":"calm","cn":"平静的；镇定的；沉着的","ex":{"en":"He remained unruffled by their accusations.","cn":"对于他们的指控他处之泰然。"}}]}},"upheaval":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"激变；剧变；动乱","en":"An upheaval is a big change which causes a lot of trouble, confusion, and worry.","ex":{"en":"Wherever there is political upheaval, invariably there are refugees","cn":"哪里有政治动乱，哪里就一定有难民。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a change in something, especially one that has happened gradually or naturally","cn":""},{"en":"a complete change from a bad economic situation to a good one, or a change from failing to succeeding","cn":""},{"en":"a big change in your life or in the way things are organized, especially when this causes problems and anxiety","cn":""}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"Upheaval means a violent or sudden change. You might talk about an upheaval in government following an election where many incumbents are replaced."}]},"collocations":{"phrases":["ADJ. big, enormous, great, major, massive, violent | domestic, economic, emotional, political, social The loss of his high-paying job caused","VERB + UPHEAVAL cause, provoke | go through, undergo The company underwent a massive upheaval after the takeover.","PREP. during/in the ~ He rose to power during the political upheavals of the 1990s.","PHRASES a period of upheaval"]},"media":{"uk":"media/ldoce/hwd/bre/8/upheaval0205.mp3","us":"media/ldoce/hwd/ame/1/upheaval.mp3"},"examples":[{"en":"I can't face the upheaval of moving house again.","cn":"我无法忍受再次搬家的折腾。"},{"en":"the latest upheavals in the education system","cn":"最近教育制度上的种种变更"}],"oxford":{"phon":"ʌpˈhiːvl","pos":"noun","senses":[{"en":"a big change that causes a lot of worry and problems","cn":"剧变；激变；动乱；动荡","ex":{"en":"Teachers are still getting used to the latest upheavals in the education system.","cn":"教师们仍在适应教育系统最新的剧变。"}}]}},"upbeat":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"达观的；乐观的；充满希望的","en":"If people or their opinions are upbeat, they are cheerful and hopeful about a situation.","ex":{"en":"The Defense Secretary gave an upbeat assessment of the war so far","cn":"国防部长对目前的战事给予了乐观的评价。"}},{"pos":"N-COUNT 可数名词","cn":"弱拍；上拍","en":"In music, the upbeat is the beat before the first beat of the bar."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"believing that good things will happen","cn":""},{"en":"believing that what you hope for will happen","cn":""},{"en":"thinking about what is good in a situation, rather than what is bad","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/f/upbeat0205.mp3","us":"media/ldoce/hwd/ame/6/upbeat.mp3"},"examples":[{"en":"The tone of the speech was upbeat.","cn":"这次讲话的语气颇为乐观。"},{"en":"The meeting ended on an upbeat note.","cn":"会议在乐观的气氛中结束。"}],"oxford":{"phon":"ˈʌpbiːt","pos":"adjective","senses":[{"en":"positive and enthusiastic; making you feel that the future will be good","cn":"乐观的；快乐的；积极向上的","ex":{"en":"The tone of the speech was upbeat.","cn":"这次讲话的语气颇为乐观。"}}]}},"unannounced":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未事先通知的；未提前说明的；未打招呼的","en":"If someone arrives or does something unannounced, they do it unexpectedly and without anyone having being told about it beforehand.","ex":{"en":"He had just arrived unannounced from South America","cn":"他刚刚从南美来到这里，事先没有打招呼。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"something that is unexpected surprises you because you did not expect it","cn":""},{"en":"situations, problems, changes etc that you did not expect or prepare for, and which usually cause you difficulty","cn":""},{"en":"if something that happens is a surprise or comes as a surprise , you did not expect it to happen, and so you are surprised by it","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/4/unannounced0205.mp3","us":"media/ldoce/hwd/ame/a/unannounced.mp3"},"examples":[{"en":"She just turned up unannounced on my doorstep.","cn":"她未打招呼就来到我家门口了。"},{"en":"an unannounced increase in bus fares","cn":"公共汽车票价未经公告的上涨"}],"oxford":{"phon":"ˌʌnəˈnaʊnst","pos":"adjective","senses":[{"en":"happening without anyone being told or warned in advance","cn":"未通知的；未预告的；未打招呼的","ex":{"en":"She just turned up unannounced on my doorstep.","cn":"她未打招呼就来到我家门口了。"}}]}},"unbalanced":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"情绪不稳的；精神失常的","en":"If you describe someone as unbalanced, you mean that they appear disturbed and upset or they seem to be slightly mad.","ex":{"en":"I knew how unbalanced Paula had been since my uncle Peter died","cn":"我知道葆拉自从我叔叔彼得去世后情绪一直很不稳定。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不公正的；偏颇的；片面的","en":"If you describe something such as a report or argument as unbalanced, you think that it is unfair or inaccurate because it emphasizes some things and ignores others.","ex":{"en":"UN officials argued that the report was unbalanced.","cn":"联合国官员指出那份报告有失公允。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who is unbalanced is slightly crazy 〔","cn":"人〕精神错乱[失常]的"},{"en":"a report, argument etc that is unbalanced is unfair because it emphasizes one opinion too much 〔","cn":"报告﹑论点等〕有失公允的﹐片面的"},{"en":"a relationship that is unbalanced is not equal because one person has more influence, power etc 〔","cn":"关系〕不平衡的﹐失衡的﹐不平等的"}]},"collocations":{"phrases":["VERBS be, seem | become","ADV. a little, slightly | mentally She became mentally unbalanced after the accident. 2 not fair to all ideas or sides of sth","VERBS be, seem | become","ADV. extremely, seriously, very | completely, wholly The report is completely unbalanced. | slightly, somewhat a somewhat unbalanced account"]},"media":{"uk":"media/ldoce/hwd/bre/e/brelasdeunbalanced.mp3","us":"media/ldoce/hwd/ame/0/laadunbalanced.mp3"},"examples":[{"en":"an unbalanced article","cn":"持论偏颇的文章"},{"en":"an unbalanced diet","cn":"不均衡的饮食"}],"oxford":{"phon":"ˌʌnˈbælənst","pos":"adjective","senses":[{"en":"giving too much or too little importance to one part or aspect of something","cn":"不持平的；偏颇的；失衡的","g":"[usually before noun]","ex":{"en":"an unbalanced article","cn":"持论偏颇的文章"}},{"en":"not thinking or behaving as they normally do; mentally ill","cn":"心理不平衡的；精神失常的","g":"[not usually before noun]","ex":{"en":"The report described him as unbalanced and erratic.","cn":"报告称他精神不平衡且反复无常。"}}]}},"undertaker":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"承办丧葬者；殡仪员","en":"An undertaker is a person whose job is to deal with the bodies of people who have died and to arrange funerals."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone whose job is to arrange funerals","cn":"殡葬人员﹐殡仪员"}]},"vocab":{"pos":"n","senses":[{"en":"An undertaker is someone who prepares a body for burial or cremation. When a loved one dies, you'll have to visit an undertaker ."}]},"media":{"uk":"media/ldoce/hwd/bre/4/undertaker0205.mp3","us":"media/ldoce/hwd/ame/a/undertaker.mp3"},"oxford":{"phon":"ˈʌndəteɪkə(r)","pos":"noun","senses":[{"en":"a person whose job is to prepare the bodies of dead people to be buried or cremated, and to arrange funerals","cn":"殡葬承办人；殡仪服务员"}]}},"ute":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"","en":"A ute is a vehicle that is designed to travel over rough ground. Ute is an abbreviation for (缩略=) 'utility vehicle'."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a Native American tribe living mainly in Colorado and Utah","cn":""},{"en":"a member of this tribe","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/7/lpd_ute.mp3","us":"media/ldoce/hwd/ame/5/ute.mp3"},"oxford":{"phon":"juːt","pos":"noun","senses":[{"en":"a vehicle with low sides and no roof at the back used, for example, by farmers","cn":"（农用）小卡车，轻型货车"},{"en":"a member of a native North American people many of whom live in the US states of Colorado and Utah","cn":"犹他人（美洲土著，很多居于美国科罗拉多州和犹他州）"}]}},"undulate":{"collins":{"senses":[{"pos":"VERB 动词","cn":"波动；起伏；摇曳","en":"Something that undulates has gentle curves or slopes, or moves gently and slowly up and down or from side to side in an attractive manner.","ex":{"en":"As we travel south, the countryside begins to undulate as the rolling hills sweep down to the riverbanks","cn":"我们一路南行，乡间开始变得起伏不平，绵延的山峦一直延伸到河岸。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to move or be shaped like waves that are rising and falling","cn":"起伏﹐波动"}]},"vocab":{"pos":"v adj","senses":[{"en":"Undulate describes a wave-like pattern. If a sound increases and decreases in pitch or volume like waves, you can say the sound is undulating . When searching for the lost boy, the rescuers' cries undulated through the forest."}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41undulate.mp3","us":"media/ldoce/hwd/ame/c/ld41undulate.mp3"},"examples":[{"en":"The countryside undulates pleasantly.","cn":"原野起伏，景色宜人。"},{"en":"undulating hills","cn":"绵延起伏的山峦"}],"oxford":{"phon":"ˈʌndʒəleɪt","pos":"verb","senses":[{"en":"to go or move gently up and down like waves","cn":"起伏；波动；荡漾","ex":{"en":"The countryside undulates pleasantly.","cn":"原野起伏，景色宜人。"}}]}},"unravel":{"collins":{"senses":[{"pos":"VERB 动词","cn":"崩溃；失败","en":"If something such as a plan or system unravels, it breaks up or begins to fail.","ex":{"en":"His government began to unravel because of a banking scandal","cn":"他的政府由于一起金融丑闻而开始瓦解。"}},{"pos":"V-ERG 及物/不及物动词","cn":"解开；拆散；（使）松开","en":"If you unravel something that is knotted, woven, or knitted, or if it unravels, it becomes one straight piece again or separates into its different threads.","ex":{"en":"He was good with his hands and could unravel a knot or untangle yarn that others wouldn't even attempt","cn":"他的手很灵巧，其他人甚至都不敢尝试的一些难解的绳结或缠在一起的纱线，他都能解开。"}},{"pos":"V-ERG 及物/不及物动词","cn":"揭开；揭示","en":"If you unravel a mystery or puzzle, or if it unravels, it gradually becomes clearer and you can work out the answer to it.","ex":{"en":"A young mother has flown to Iceland to unravel the mystery of her husband's disappearance","cn":"一位年轻的母亲飞抵冰岛，要揭开她丈夫失踪之谜。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to find the explanation to something that is difficult to understand, for example a crime or a mystery","cn":""},{"en":"to find the explanation for something that is difficult to understand, by thinking carefully about it and using the information available to you","cn":""},{"en":"to find a way of explaining something, especially after trying for a fairly long time","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"However tempting, don't pull that straggly thread hanging from your sleeve. You'll just unravel or totally undo that hand knitted sweater."}]},"media":{"uk":"media/ldoce/hwd/bre/7/unravel0205.mp3","us":"media/ldoce/hwd/ame/9/unravel.mp3"},"examples":[{"en":"The discovery will help scientists unravel the mystery of the Ice Age.","cn":"这一发现将有助于科学家揭开冰川时代的奥秘。"},{"en":"I unravelled the string and wound it into a ball.","cn":"我把绳子解开并绕成一个球。"}],"oxford":{"phon":"ʌnˈrævl","pos":"verb","senses":[{"en":"if you unravel threads that are twisted, woven or knitted, or if they unravel, they become separated","cn":"（把缠或织在一起的线）解开，拆散，松开","g":"[transitive, intransitive]","ex":{"en":"I unravelled the string and wound it into a ball.","cn":"我把绳子解开并绕成一个球。"}},{"en":"to start to fail or no longer stay together as a whole","cn":"解体；崩溃；瓦解","g":"[intransitive]"},{"en":"to explain something that is difficult to understand or is mysterious; to become clearer or easier to understand","cn":"阐释；说明；澄清；变得清楚易懂","g":"[transitive, intransitive]","ex":{"en":"The discovery will help scientists unravel the mystery of the Ice Age.","cn":"这一发现将有助于科学家揭开冰期的奥秘。"}}]}},"unify":{"collins":{"senses":[{"pos":"V-RECIP-ERG","cn":"（使）成一体；（使）联合；（使）统一","en":"If someone unifies different things or parts, or if the things or parts unify, they are brought together to form one thing.","ex":{"en":"A flexible retirement age is being considered by Ministers to unify men's and women's pension rights","cn":"大臣们正在考虑一个灵活的退休年龄机制，这样可以把男性和女性的养老金权益统一起来。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if you unify two or more parts or things, or if they unify, they are combined to make a single unit (","cn":"使)统一﹐(使)成一体"}]},"vocab":{"pos":"v","senses":[{"en":"When you bring together unlike elements, you unify them. Political movements can unify people by inspiring them towards a shared goal, just as a shared love of a team or music group can unify people who otherwise don't have much in common."}]},"media":{"uk":"media/ldoce/hwd/bre/b/unify0205.mp3","us":"media/ldoce/hwd/ame/f/unify.mp3"},"examples":[{"en":"The new leader hopes to unify the country.","cn":"新领袖希望把国家统一起来。"},{"en":"the task of unifying Europe","cn":"统一欧洲的大业"}],"oxford":{"phon":"ˈjuːnɪfaɪ","pos":"verb","senses":[{"en":"to join people, things, parts of a country, etc. together so that they form a single unit","cn":"统一；使成一体；使一元化","ex":{"en":"The new leader hopes to unify the country.","cn":"新领袖希望把国家统一起来。"}}]}},"undated":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"无日期的；未注明日期的","en":"Something that is undated does not have a date written on it.","ex":{"en":"In each packet there are batches of letters, most of which are undated.","cn":"每个包裹里都有一摞摞的信件，其中大部分都没有日期。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a letter, article, painting etc that is undated does not have a date written on it","cn":"未标明日期的"}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41undated.mp3","us":"media/ldoce/hwd/ame/7/laadundated.mp3"},"examples":[{"en":"undated archaeological remains","cn":"时间未确定的考古遗迹"},{"en":"an undated letter","cn":"一封没写日期的信"}],"oxford":{"phon":"ˌʌnˈdeɪtɪd","pos":"adjective","senses":[{"en":"without a date written or printed on it","cn":"未注日期的","ex":{"en":"an undated letter","cn":"一封没写日期的信"}},{"en":"of which the date is not known","cn":"日期不明的；时间不详的","ex":{"en":"undated archaeological remains","cn":"时间未确定的考古遗迹"}}]}},"untreated":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未经治疗的","en":"If an injury or illness is left untreated, it is not given medical treatment.","ex":{"en":"If left untreated the condition may become chronic.","cn":"这种病如果不治疗可能会发展成慢性病。"}},{"pos":"ADJ 形容词","cn":"（有害物质）未经处理的","en":"Untreated materials, water, or chemicals are harmful and have not been made safe.","ex":{"en":"...the dumping of nuclear waste and untreated sewage.","cn":"倾倒核废料和未经处理的污水"}},{"pos":"ADJ 形容词","cn":"（天然或原始物质）未经处理的，未加工过的","en":"Untreated materials are in their natural or original state, often before being prepared for use in a particular process.","ex":{"en":"All the bedding is made of simple, untreated cotton","cn":"所有床上用品全部用未经处理的天然棉花制成。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"an untreated illness or injury has not had medical treatment 〔","cn":"疾病或伤〕未予治疗的"},{"en":"harmful substances that are untreated have not been made safe 〔","cn":"有害物质〕未经处理的"},{"en":"untreated wood has not had any substances put on it to preserve it 〔","cn":"木材〕未经防护处理的"}]},"media":{"uk":"media/ldoce/hwd/bre/f/untreated0205.mp3","us":"media/ldoce/hwd/ame/0/laaduntreated.mp3"},"examples":[{"en":"If untreated, the illness can become severe.","cn":"若不加以治疗，病情就可能会变得很严重。"},{"en":"untreated sewage","cn":"未处理的污水"}],"oxford":{"phon":"ˌʌnˈtriːtɪd","pos":"adjective","senses":[{"en":"not receiving medical treatment","cn":"没有接受治疗的","ex":{"en":"If untreated, the illness can become severe.","cn":"若不加以治疗，病情就可能会变得很严重。"}},{"en":"not made safe by chemical or other treatment","cn":"未处理的","ex":{"en":"untreated sewage","cn":"未处理的污水"}},{"en":"not treated with substances to preserve it","cn":"未经防护处理的"}]}},"unimpeachable":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"无可怀疑的；完全可靠的","en":"If you describe someone as unimpeachable, you mean that they are completely honest and reliable.","ex":{"en":"He said all five were men of unimpeachable character.","cn":"他说这五个都是品格完美无缺的人。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"so good or definite that criticism or doubt is impossible","cn":"无可指摘的﹐无懈可击的﹔不容置疑的﹔可靠的"}]},"vocab":{"pos":"adj","senses":[{"en":"Unimpeachable describes someone or something that is totally, completely, without any doubt, innocent and good, like an unimpeachable role model who avoids bad influences and sketchy situations."}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41unimpeachable.mp3","us":"media/ldoce/hwd/ame/2/unimpeachable.mp3"},"examples":[{"en":"evidence from an unimpeachable source","cn":"来源可靠的证据"},{"en":"unimpeachable morals","cn":"无可指摘的品行"}],"oxford":{"phon":"ˌʌnɪmˈpiːtʃəbl","pos":"adjective","senses":[{"en":"that you cannot doubt or question","cn":"不容置疑的；无可指摘的；无可怀疑的","ex":{"en":"evidence from an unimpeachable source","cn":"来源可靠的证据"}}]}},"untested":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未经考验的；未测试的","en":"If something or someone is untested, they have not yet been tried out or have not yet experienced a particular situation, so you do not know what they will be like.","ex":{"en":"The Egyptian Army remained an untested force","cn":"埃及军队依然有待考验。"}},{"pos":"ADJ 形容词","cn":"未经检验的；未经测试的","en":"If you describe something such as a drug or chemical as untested, you mean that it has not been subject to scientific tests to find out if it is safe to use.","ex":{"en":"...the dangers of giving untested drugs to people.","cn":"把未经检验的药物给人吃的危险"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"untested ideas, methods, or people have not been used in a particular situation so you do not know what they are like 〔","cn":"观点或方法〕未经验证的﹔[人]未经考验的"},{"en":"an untested drug, medical treatment etc has not been given any scientific tests to discover if it is safe to use 〔","cn":"药物﹑治疗方法等〕未经试验的"}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41untested.mp3","us":"media/ldoce/hwd/ame/f/laaduntested.mp3"},"examples":[{"en":"an argument based on untested assumptions","cn":"建立在未经验证的假设上的论点"}],"oxford":{"phon":"ˌʌnˈtestɪd","pos":"adjective","senses":[{"en":"not tested; of unknown quality or value","cn":"未经试验（或考验）的","ex":{"en":"an untested assumption","cn":"未经检验的假设"}}]}},"unsettled":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"多变的；不安定的；不平稳的；动荡不安的","en":"In an unsettled situation, there is a lot of uncertainty about what will happen.","ex":{"en":"Britain's unsettled political scene also worries some investors","cn":"英国动荡不安的政治局面也让一些投资者担心不已。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不能集中精力的","en":"If you are unsettled, you cannot concentrate on anything because you are worried.","ex":{"en":"A lot of people wake up every day with a sense of being unsettled and disturbed","cn":"很多人每天起床的时候都感到无法集中精力、心烦意乱。"}},{"pos":"ADJ 形容词","cn":"（争论等）未解决的，悬而未决的","en":"An unsettled argument or dispute has not yet been resolved.","ex":{"en":"They were in the process of resolving all the unsettled issues","cn":"他们正在着手解决所有悬而未决的问题。"}},{"pos":"ADJ 形容词","cn":"渺无人烟的；荒芜的","en":"Unsettled places are places where no people have yet lived.","ex":{"en":"Until very recently Texas was an unsettled frontier.","cn":"就在没多久之前，得克萨斯州还是一个荒无人烟的边远地区。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不可预测的；易变的","en":"Unsettled weather is unpredictable and changes a lot.","ex":{"en":"Despite the unsettled weather, we had a marvellous weekend.","cn":"尽管天气一会儿好一会儿差，我们仍然度过了一个美好的周末。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"feelings or conditions that are changeable change frequently so that it is difficult to know what they will be like in a short time","cn":""},{"en":"behaviour, processes, or services that are erratic change suddenly in an unexpected and surprising way, when it would be better if they remained the same","cn":""},{"en":"a volatile situation or character is likely to change suddenly and unexpectedly","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/e/unsettled0205.mp3","us":"media/ldoce/hwd/ame/4/unsettled.mp3"},"examples":[{"en":"These were difficult and unsettled times.","cn":"那是个艰难而动荡的时期。"},{"en":"They all felt restless and unsettled.","cn":"他们都感到焦躁不安。"}],"oxford":{"phon":"ʌnˈsetld","pos":"adjective","senses":[{"en":"that may change; making people uncertain about what might happen","cn":"多变的；不安定的；不平稳的；动荡不安的","ex":{"en":"These were difficult and unsettled times.","cn":"那是个艰难而动荡的时期。"}},{"en":"not calm or relaxed","cn":"不镇静的；心绪不宁的；不安的","ex":{"en":"They all felt restless and unsettled.","cn":"他们都感到焦躁不安。"}},{"en":"that continues without any agreement being reached","cn":"无休止的；未解决的"},{"en":"not yet paid","cn":"未支付的；未付清的"}]}},"uniformed":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"穿（着）制服的","en":"If you use uniformed to describe someone who does a particular job, you mean that they are wearing a uniform.","ex":{"en":"...uniformed policemen.","cn":"身穿制服的警察"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"wearing a uniform","cn":"穿制服的"}]},"media":{"uk":"media/ldoce/hwd/bre/f/uniformed0205.mp3","us":"media/ldoce/hwd/ame/a/uniformed.mp3"},"examples":[{"en":"a uniformed chauffeur","cn":"穿制服的司机"},{"en":"uniformed police officers","cn":"穿制服的警察"}],"oxford":{"phon":"ˈjuːnɪfɔːmd","pos":"adjective","senses":[{"en":"wearing a uniform","cn":"穿制服的","ex":{"en":"a uniformed chauffeur","cn":"穿制服的司机"}}]}},"untapped":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未开采过的；未用过的","en":"An untapped supply or source of something has not yet been used.","ex":{"en":"Mongolia, although poor, has considerable untapped resources of oil and minerals","cn":"蒙古虽然穷，但有大量尚未开采的石油和矿产资源。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"something that is unused , has not been used, especially because it has not been needed","cn":""},{"en":"not used at all - use this when it is unusual or surprising that something has not been used","cn":""},{"en":"untapped supplies of something, especially a natural product, have not been used","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/a/untapped0205.mp3","us":"media/ldoce/hwd/ame/a/untapped.mp3"},"examples":[{"en":"untapped reserves of oil","cn":"未开采的石油贮量"},{"en":"Older people are an untapped resource in the employment market.","cn":"年龄较大的人是就业市场中有待利用的资源。"}],"oxford":{"phon":"ˌʌnˈtæpt","pos":"adjective","senses":[{"en":"available but not yet used","cn":"未利用的；未开发的；蕴藏的","ex":{"en":"untapped reserves of oil","cn":"未开采的石油储量"}}]}},"upend":{"collins":{"senses":[{"pos":"VERB 动词","cn":"使倒立；倒放；颠倒","en":"If you upend something, you turn it upside down.","ex":{"en":"He upended the beer, and swallowed.","cn":"他举起啤酒，一饮而尽。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to turn something over so that it is upside down","cn":"倒放﹐使颠倒"}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41upend.mp3","us":"media/ldoce/hwd/ame/7/upend.mp3"},"examples":[{"en":"The bicycle lay upended in a ditch.","cn":"自行车翻倒在一条小水沟里。"}],"oxford":{"phon":"ʌpˈend","pos":"verb","senses":[{"en":"to turn somebody/something the wrong way up or onto one end","cn":"翻倒；倒放；使颠倒","lab":"figurative","ex":{"en":"The bicycle lay upended in a ditch.","cn":"自行车翻倒在一条小水沟里。"}}]}},"unclean":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不洁的；肮脏的","en":"Something that is unclean is dirty and likely to cause disease.","ex":{"en":"...the Western attitude to insects as being dirty and unclean","cn":"西方人认为昆虫肮脏不洁的看法"}},{"pos":"ADJ 形容词","cn":"邪恶的；龌龊的","en":"If you describe someone or something as unclean, you consider them to be spiritually or morally bad.","ex":{"en":"They felt as though they had done something discreditable and unclean.","cn":"他们觉得自己仿佛做了什么龌龊丢脸之事。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"morally or spiritually bad","cn":"不道德的﹔肮脏的﹔邪恶的"},{"en":"unclean food, animals etc are those that a particular religion says must not be eaten, touched etc 〔","cn":"宗教上指食物﹑动物等〕不洁的"},{"en":"dirty","cn":"脏的"}]},"media":{"uk":"media/ldoce/hwd/bre/a/unclean0205.mp3","us":"media/ldoce/hwd/ame/5/unclean.mp3"},"examples":[{"en":"unclean water","cn":"不清洁的水"},{"en":"unclean food","cn":"不洁的食物"}],"oxford":{"phon":"ˌʌnˈkliːn","pos":"adjective","senses":[{"en":"dirty and therefore likely to cause disease","cn":"肮脏的，不洁净的（因而容易致病）","lab":"formal","ex":{"en":"unclean water","cn":"不清洁的水"}},{"en":"considered to be bad, immoral or not pure in a religious way, and therefore not to be touched, eaten, etc.","cn":"邪恶的；不洁的；（宗教上所指）不洁净的","ex":{"en":"unclean thoughts","cn":"邪念"}}]}},"unanimous":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（所有人）一致同意的，全体一致的，无异议的","en":"When a group of people are unanimous, they all agree about something or all vote for the same thing.","ex":{"en":"Editors were unanimous in their condemnation of the proposals","cn":"编辑人员一致谴责这些提议。"}},{"pos":"ADJ 形容词","cn":"（投票、决定、协议等）全体同意的，无异议的，一致通过的","en":"A unanimous vote, decision, or agreement is one in which all the people involved agree.","ex":{"en":"...the unanimous vote for Hungarian membership","cn":"投票一致同意匈牙利成为会员国"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a situation in which two or more people, groups etc have the same opinion about something","cn":""},{"en":"general agreement among most of the people in a group, especially an official group that makes important decisions","cn":""},{"en":"if a group of people is unanimous , they all have the same opinion about something, especially about what should be done or who should be chosen or elected","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"When a group or a decision is unanimous , it means that everyone is in total agreement. Just imagine if you let third graders vote on what to serve at lunch: Pizza and candy would be the unanimous choice!"}]},"collocations":{"phrases":["VERBS be","ADV. almost, nearly, virtually","PREP. about Doctors are unanimous about the dangers of this drug. | in They were unanimous in this decision. | on The experts are not unanim"]},"media":{"uk":"media/ldoce/hwd/bre/9/unanimous0205.mp3","us":"media/ldoce/hwd/ame/c/unanimous.mp3"},"examples":[{"en":"Local people are unanimous in their opposition to the proposed new road.","cn":"当地居民一致反对拟建的新公路。"},{"en":"The decision was not unanimous.","cn":"这项决定没有得到一致通过。"}],"oxford":{"phon":"juˈnænɪməs","pos":"adjective","senses":[{"en":"if a decision or an opinion is unanimous, it is agreed or shared by everyone in a group","cn":"（决定或意见）一致的，一致同意的","ex":{"en":"a unanimous vote","cn":"全体一致的表决"}},{"en":"if a group of people are unanimous, they all agree about something","cn":"（团体）意见一致的，一致同意某事的","ex":{"en":"Local people are unanimous in their opposition to the proposed new road.","cn":"当地居民一致反对拟建的新公路。"}}]}},"unpopularity":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if someone or something is unpopular , a lot of people do not like them","cn":""},{"en":"if a person, idea, or other thing is out of favour , people no longer approve of them or use them, although they used to be popular","cn":""},{"en":"if there is no demand for a product or service people do not want to buy it","cn":""}]},"collocations":{"phrases":["ADJ. great, growing","VERB + UNPOPULARITY increase","PREP. ~ among Her close relationship with the teacher increased her unpopularity among her schoolmates. | ~ with the great unpopularity of t"]},"media":{"uk":"media/ldoce/hwd/bre/2/unpopular0205.mp3","us":"media/ldoce/hwd/ame/1/laadunpopular.mp3"},"examples":[{"en":"the growing unpopularity of the military regime","cn":"军政府日益不得人心"},{"en":"a decision that was deeply unpopular with students","cn":""}],"oxford":{"phon":"ˌʌnˌpɒpjuˈlærəti","pos":"noun","senses":[{"en":"the state of not being liked or enjoyed by a person, a group or people in general","cn":"没人缘儿的；不受欢迎的；不得人心的","ex":{"en":"the growing unpopularity of the military regime","cn":"军政府日益不得人心"}}]}},"unresponsive":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"没有回应的；漠不关心的","en":"An unresponsive person does not react or pay enough attention to something, for example to an urgent situation or to people's needs.","ex":{"en":"He was totally unresponsive to the pressing social and economic needs of the majority of the population.","cn":"他对大多数人迫切的社会和经济需求漠不关心。"}},{"pos":"ADJ 形容词","cn":"一动不动的；没反应的","en":"If a person or their body is unresponsive, they do not react physically in a normal way, or do not make any movements.","ex":{"en":"I found her in a coma, totally unresponsive.","cn":"我发现她昏倒了，完全失去了知觉。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not reacting to something or not affected by it","cn":"无反应的﹔不受影响的"}]},"vocab":{"pos":"adj","senses":[{"en":"If someone can't or won't respond, we call them unresponsive . Depending on the context, a person's unresponsiveness can be just a bummer or a life-threatening condition."}]},"media":{"uk":"media/ldoce/hwd/bre/d/brelasdeunresponsive.mp3","us":"media/ldoce/hwd/ame/a/laadunresponsive.mp3"},"examples":[{"en":"a politician who is unresponsive to the mood of the country","cn":"对国民情绪毫无反应的政客"},{"en":"The disease is totally unresponsive to conventional treatment.","cn":"常规疗法对这种病根本不起作用。"}],"oxford":{"phon":"ˌʌnrɪˈspɒnsɪv","pos":"adjective","senses":[{"en":"not reacting to somebody/something; not giving the response that you would expect or hope for","cn":"无反应的；未答复的；反应迟钝的","ex":{"en":"If the person is unconscious or unresponsive, dial 999.","cn":"如果这个人失去知觉或者没有反应，就拨打 999。"}}]}},"untruthful":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不真实的；虚伪的；虚假的","en":"If someone is untruthful or if they say untruthful things, they are dishonest and say things that they know are not true.","ex":{"en":"He must not be untruthful, or a coward","cn":"他绝不能是虚伪或胆怯之徒。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"dishonest or not true","cn":"不诚实的﹔不真实的"}]},"media":{"uk":"media/ldoce/hwd/bre/1/untruthful0205.mp3","us":"media/ldoce/hwd/ame/d/laaduntruthful.mp3"},"oxford":{"phon":"ʌnˈtruːθfl","pos":"adjective","senses":[{"en":"saying things that you know are not true","cn":"说谎的；不说实话的","ex":{"en":"The allegations make her out to be untruthful.","cn":"这些指控表明她不诚实。"}}]}},"unconfirmed":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未经证实的；未确证的","en":"If a report or a rumour is unconfirmed, there is no definite proof as to whether it is true or not.","ex":{"en":"There are unconfirmed reports of several small villages buried by mudslides.","cn":"据未经证实的报道说，几个小村庄被泥石流吞没了。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a report etc that has not been proved or supported by official information","cn":"未经证实的报道/说法/传闻等"}]},"media":{"uk":"media/ldoce/hwd/bre/7/brelasdeunconfirmed.mp3","us":"media/ldoce/hwd/ame/3/unconfirmed.mp3"},"examples":[{"en":"Unconfirmed reports said that at least six people had been killed.","cn":"未经证实的报道称至少有六人丧生。"},{"en":"unconfirmed rumours","cn":"未证实的传言"}],"oxford":{"phon":"ˌʌnkənˈfɜːmd","pos":"adjective","senses":[{"en":"that has not yet been proved to be true or confirmed","cn":"未经证实的；未被认可的；未确认的","ex":{"en":"unconfirmed rumours","cn":"未证实的传言"}}]}},"underbrush":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（森林里林木下的）下层灌丛，灌木丛","en":"Underbrush consists of bushes and plants growing close together under trees in a forest.","ex":{"en":"...the cool underbrush of the rain forest","cn":"雨林里使人感到凉爽的下层灌丛"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"bushes, small trees etc growing under and around larger trees in a forest 〔","cn":"森林中的〕下层灌木﹐林下灌木"}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41underbrush.mp3","us":"media/ldoce/hwd/ame/c/underbrush.mp3"},"oxford":{"phon":"ˈʌndəbrʌʃ","pos":"noun","senses":[{"en":"a mass of bushes and plants that grow close together under trees in woods and forests","cn":"下木层","ex":{"en":"In some places, the dense underbrush becomes so thick that it's nearly impassable.","cn":"有些地方灌木丛长得很密实，几乎无法穿行。"}}]}},"unnaturally":{"collins":{"senses":[{"pos":"PHRASE 短语","cn":"理所当然地；很自然地","en":"You can use not unnaturally to indicate that the situation you are describing is exactly as you would expect in the circumstances.","ex":{"en":"It was a question that Roy not unnaturally found impossible to answer","cn":"那是个罗伊显然无法回答的问题。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"very different from what is normal, in a way that is strange, worrying, or dangerous","cn":""},{"en":"different from normal human behaviour in a way that seems morally wrong","cn":""},{"en":"deviant behaviour or actions are considered to be very strange and morally unacceptable -- often used about sexual or criminal behaviour","cn":""}]},"vocab":{"pos":"adv","senses":[{"en":"The adverb unnaturally describes something that happens in an unusual or strange way. If you feel unnaturally hot in a cool room, you may have a fever."}]},"media":{"uk":"media/ldoce/hwd/bre/d/unnatural0205.mp3","us":"media/ldoce/hwd/ame/2/unnatural.mp3"},"examples":[{"en":"She was, not unnaturally, very surprised at the news.","cn":"这消息自然让她大吃一惊。"},{"en":"His eyes were unnaturally bright.","cn":"他的眼睛异常明亮。"}],"oxford":{"phon":"ʌnˈnætʃrəli","pos":"adverb","senses":[{"en":"in a way that is different from what is normal or expected","cn":"不自然地：以不同于正常或预期的方式","ex":{"en":"She was, not unnaturally, very surprised at the news.","cn":"听到这个消息，她自然大吃一惊。"}},{"en":"in a way that is different from anything in nature","cn":"不正常的；怪异的","ex":{"en":"His eyes were unnaturally bright.","cn":"他的眼睛异常明亮。"}}]}},"unbreakable":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"打不碎的;牢不可破的","en":"Unbreakable objects cannot be broken, usually because they are made of a very strong material.","ex":{"en":"Tableware for outdoor use should ideally be unbreakable.","cn":"室外用的餐具最好是打不破的。"}},{"pos":"ADJ 形容词","cn":"（规则、限制等）不能违反的，必须服从的","en":"An unbreakable rule or limit must be obeyed.","ex":{"en":"One unbreakable rule in our school is that no child can be tested without written parental permission.","cn":"我们学校有一条金科玉律：未经父母书面同意，不得对学生进行测试。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not easily broken or damaged","cn":""},{"en":"strong – used especially about something that can be used a lot without damaging it or making it weaker","cn":""},{"en":"extremely strong – used about materials, tools, machines etc that are made especially to be used a lot without being easily damaged","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41unbreakable.mp3","us":"media/ldoce/hwd/ame/2/laadunbreakable.mp3"},"examples":[{"en":"This new material is virtually unbreakable.","cn":"这种新材料实际上是不碎的。"},{"en":"unbreakable glass","cn":"打不碎的玻璃"}],"oxford":{"phon":"ʌnˈbreɪkəbl","pos":"adjective","senses":[{"en":"impossible to break","cn":"无法打破的；牢不可破的","ex":{"en":"This new material is virtually unbreakable.","cn":"这种新材料实际上是不碎的。"}}]}},"unruly":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（尤指孩子）没教养的，难控制的，难管束的","en":"If you describe people, especially children, as unruly, you mean that they behave badly and are difficult to control.","ex":{"en":"It's not good enough just to blame the unruly children.","cn":"对难管教的孩子只是责备是不够的。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（头发）凌乱的，不整洁的","en":"Unruly hair is difficult to keep tidy.","ex":{"en":"The man had a huge head of remarkably black, unruly hair.","cn":"那个人有一头乱蓬蓬的黑发。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"violent or difficult to control","cn":"粗暴的﹔难驾驭的﹐难管教的"},{"en":"unruly hair is difficult to keep tidy 〔","cn":"头发〕难梳理的﹐乱蓬蓬的"}]},"vocab":{"pos":"adj","senses":[{"en":"Unruly means lacking in restraint or not submitting to authority. Spitballs, shouting kids, a shouting teacher––these are all signs of an unruly classroom. Often, one unruly student is all it takes."}]},"media":{"uk":"media/ldoce/hwd/bre/8/unruly0205.mp3","us":"media/ldoce/hwd/ame/c/unruly.mp3"},"examples":[{"en":"unruly hair (= difficult to keep looking neat)","cn":"难梳理的头发"},{"en":"unruly behaviour","cn":"无法无天的行为"}],"oxford":{"phon":"ʌnˈruːli","pos":"adjective","senses":[{"en":"difficult to control or manage","cn":"难以控制（或管理）的；难以驾驭的","ex":{"en":"an unruly class","cn":"难管教的班级"}}]}},"unbridgeable":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"难以逾越的；无法弥合的","en":"An unbridgeable gap or divide between two sides in an argument is so great that the two sides seem unlikely ever to agree.","ex":{"en":"...the apparently unbridgeable gulf between the SIS and the Security Service","cn":"秘密情报局和国家安全局之间显然难以逾越的鸿沟"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"unbridgeable differences between two people, groups, or ideas are so big that no one will ever agree about them or be satisfied with them 〔","cn":"两个人﹑团体或两种观念之间的分歧〕无法弥合的﹐无法逾越的"},{"en":"unbridgeable gulf/gap/chasm etc (between somebody/something and somebody/something) the unbridgeable gulf between the rich and the poor","cn":"富人和穷人之间无法逾越的鸿沟"}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41unbridgeable.mp3","us":"media/ldoce/hwd/ame/e/laadunbridgeable.mp3"},"oxford":{"phon":"ʌnˈbrɪdʒəbl","pos":"adjective","senses":[{"en":"an unbridgeable gap or difference between two people or groups or their opinions is one that cannot be closed or made less wide","cn":"（分歧、意见等）无法弥合的；无法沟通的","ex":{"en":"Owing to seemingly unbridgeable political differences, there has been little dialogue between the two sides.","cn":"由于看似无法弥合的政治分歧，双方之间几乎没有对话。"}}]}},"uneconomic":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"获利不多的；效益不好的","en":"If you describe something such as an industry or business as uneconomic, you mean that it does not produce enough profit.","ex":{"en":"...the closure of uneconomic factories","cn":"关闭效益差的工厂"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不合算的；不经济的","en":"If you say that an action or plan is uneconomic, you think it will cost a lot of money and not be successful or not be worth the expense.","ex":{"en":"It would be uneconomic to try and repair it","cn":"花钱修理不合算。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"an unprofitable business or activity does not make a profit and is likely to have debts","cn":""},{"en":"not making enough profits to be successful or to successfully compete with other companies, industries etc - use this especially when this is a reason for closing the company, industry etc","cn":""},{"en":"not making enough money or profit","cn":"赚钱不多的﹐利润不大的"}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41uneconomic.mp3","us":"media/ldoce/hwd/ame/b/ld41uneconomic.mp3"},"examples":[{"en":"uneconomic industries","cn":"不赚钱的行业"},{"en":"the closure of uneconomic industries","cn":"效益不好的企业的关闭"}],"oxford":{"phon":"ˌʌnˌiːkəˈnɒmɪk","pos":"adjective","senses":[{"en":"not making a profit","cn":"不赢利的；不赚钱的","ex":{"en":"uneconomic industries","cn":"不赚钱的行业"}},{"en":"using too much time or money, or too many materials, and therefore not likely to make a profit","cn":"浪费的；不节俭的；不经济的"}]}},"unlock":{"collins":{"senses":[{"pos":"VERB 动词","cn":"（用钥匙）打开，开启(门、房间、箱匣等的锁)","en":"If you unlock something such as a door, a room, or a container that has a lock, you open it using a key.","ex":{"en":"He unlocked the car and threw the coat on to the back seat","cn":"他用钥匙打开车门，把外套扔到了后座上。"}},{"pos":"VERB 动词","cn":"释放（潜能）；揭开（秘密）","en":"If you unlock the potential or the secrets of something or someone, you release them.","ex":{"en":"Education and training is the key that will unlock our nation's potential.","cn":"教育和培训是发掘我们国家潜力的关键。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"used about a door, window, container, package, letter, your eyes, or your mouth","cn":""},{"en":"to open a door, drawer, box etc with a key","cn":""},{"en":"to open a lid on a bottle, container etc by turning it","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/0/unlock0205.mp3","us":"media/ldoce/hwd/ame/b/unlock.mp3"},"examples":[{"en":"The divers hoped to unlock some of the secrets of the seabed.","cn":"潜水员希望揭开海底的一些秘密。"},{"en":"to unlock the door","cn":"打开门锁"}],"oxford":{"phon":"ˌʌnˈlɒk","pos":"verb","senses":[{"en":"to open the lock of a door, window, etc., usually using a key","cn":"（用钥匙）开…的锁","ex":{"en":"to unlock the door","cn":"打开门锁"}},{"en":"to discover something and let it be known","cn":"发现；揭示；揭开","ex":{"en":"The divers hoped to unlock some of the secrets of the seabed.","cn":"潜水员希望揭开海底的一些秘密。"}},{"en":"to enable a mobile phone to use any network rather than only one particular one","cn":"解除（手机）的网络锁定","ex":{"en":"Have an old phone lying around? Unlock it and keep it as a spare.","cn":"有闲置的旧手机？把它解除网络锁定留作备用吧。"}},{"en":"to use a code or password to get access to more data or features on a computer or phone, or in a computer game","cn":"（用密码）解锁（计算机、手机内容或电脑游戏）","ex":{"en":"Players complete goals, unlock new levels and progress through the game.","cn":"玩家完成目标，解锁新级别，在游戏中成长。"}}]}},"unflagging":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（支持、努力、热情等）不懈的，持续的","en":"If you describe something such as support, effort, or enthusiasm as unflagging, you mean that it does not stop or get less as time passes.","ex":{"en":"He was sustained by the unflagging support of his family","cn":"他得到了家人不断的支持。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"continuing strongly and never becoming tired or weak","cn":"持久的﹔不倦的﹔(经久)不衰的"}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41unflagging.mp3","us":"media/ldoce/hwd/ame/8/unflagging.mp3"},"examples":[{"en":"unflagging energy","cn":"无穷的精力"},{"en":"his unflagging energy","cn":"他旺盛不衰的精力"}],"oxford":{"phon":"ˌʌnˈflæɡɪŋ","pos":"adjective","senses":[{"en":"remaining strong; not becoming weak or tired","cn":"蓬勃的；不松懈的；不减弱的；不倦的","ex":{"en":"unflagging energy","cn":"无穷的精力"}}]}},"untitled":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"无标题的","en":"If something such as a book, film, or song is untitled, it does not have a title.","ex":{"en":"The full-length feature, as yet untitled, will include interviews plus footage of their live gigs.","cn":"这部尚未定名的正规长度影片将包括对他们的采访和他们现场表演的片段。"}},{"pos":"ADJ 形容词","cn":"无头衔的；无爵位的","en":"Someone who is untitled does not have a title such as 'Sir' or 'Lord'."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"an untitled song, painting etc has not been given a title 〔","cn":"歌曲﹑绘画作品等〕无题的﹐没起名字的"}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41untitled.mp3","us":"media/ldoce/hwd/ame/8/laaduntitled.mp3"},"oxford":{"phon":"ʌnˈtaɪtld","pos":"adjective","senses":[{"en":"without a title","cn":"无题的（表示不标明题目或没有名称）"}]}},"unendurable":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"不能忍受的；难以容忍的","en":"If you describe a bad situation as unendurable, you mean that it is so extremely unpleasant that you have to end it.","ex":{"en":"Isaac had found the work unendurable and walked out of the job","cn":"艾萨克觉得这份工作实在令人难以忍受，就辞职走人了。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"too unpleasant, painful etc to bear","cn":"不可容忍的﹐难以忍受的"}]},"vocab":{"pos":"adj","senses":[{"en":"When you can't tolerate something, it's unendurable . The vintage camper your parents bought might smell so terrible that it's unendurable ."}]},"media":{"uk":"media/ldoce/hwd/bre/8/unendurable0205.mp3","us":"media/ldoce/hwd/ame/c/ld41unendurable.mp3"},"examples":[{"en":"unendurable pain","cn":"难以忍受的痛苦"},{"en":"The pain was unendurable.","cn":"疼痛无法忍受。"}],"oxford":{"phon":"ˌʌnɪnˈdjʊərəbl","pos":"adjective","senses":[{"en":"too bad, unpleasant, etc. to bear","cn":"无法容忍的；难以忍受的","ex":{"en":"unendurable pain","cn":"难以忍受的痛苦"}}]}},"unrewarded":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"没收获的；未得到回报的","en":"You can say that someone goes unrewarded, or that their activities go unrewarded, when they do not achieve what they are trying to achieve.","ex":{"en":"The jockey rushed back from America to ride at Nottingham on Monday but went unrewarded.","cn":"那位职业赛马骑师周一从美国赶回诺丁汉参加比赛，但是一无所获。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not achieving what you want to achieve","cn":"未果的﹐未获成功的"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41unrewarded.mp3","us":"media/ldoce/hwd/ame/4/ld41unrewarded.mp3"},"examples":[{"en":"Real talent often goes unrewarded.","cn":"真正的人才常被埋没。"},{"en":"His efforts have not gone unrewarded .","cn":"他的努力没有白费。"}],"oxford":{"phon":"ˌʌnrɪˈwɔːdɪd","pos":"adjective","senses":[{"en":"not receiving the success that you are trying to achieve","cn":"无回报的；未果的；未获成功的","ex":{"en":"Real talent often goes unrewarded.","cn":"真正的人才常被埋没。"}}]}},"underfoot":{"collins":{"senses":[{"pos":"ADV 副词","cn":"在脚下；在地上","en":"You describe something as being underfoot when you are standing or walking on it.","ex":{"en":"...a room, high and square with carpet underfoot and tapestries on the walls","cn":"一个高高的四方房间，地上铺有地毯，墙上挂着挂毯"}},{"pos":"ADV 副词","cn":"踩在脚下；践踏","en":"If you trample or crush something underfoot, you spoil or destroy it by stepping on it.","ex":{"en":"Morgan dropped his cigarette and crushed it underfoot.","cn":"摩根把香烟丢到地上，用脚踩灭。"}}]},"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"under your feet where you are walking","cn":"在脚下"},{"en":"to crush someone or something on the ground by stepping heavily on them","cn":"把某人/某物踩在脚下"},{"en":"to completely destroy someone or something","cn":"彻底毁灭某人/某物"}]},"media":{"uk":"media/ldoce/hwd/bre/1/underfoot0205.mp3","us":"media/ldoce/hwd/ame/f/underfoot.mp3"},"examples":[{"en":"I was nearly trampled underfoot by the crowd of people rushing for the door.","cn":"冲向大门的人群险些把我踩在脚下。"},{"en":"The ground was dry and firm underfoot.","cn":"脚下踩的土地又干又硬。"}],"oxford":{"phon":"ˌʌndəˈfʊt","pos":"adverb","senses":[{"en":"under your feet; on the ground where you are walking","cn":"在脚下；在（脚下的）地面上","ex":{"en":"The ground was dry and firm underfoot.","cn":"脚下踩的土地又干又硬。"}}]}},"unprepossessing":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不吸引人的；其貌不扬的","en":"If you describe someone or something as unprepossessing, you mean that they look rather plain or ordinary, although they may have good or special qualities that are hidden.","ex":{"en":"We found the tastiest and most imaginative paella and tapas in the most unprepossessing bars and cafés.","cn":"我们在最不起眼的酒吧和咖啡馆找到了最可口、最具创意的肉菜饭和餐前小吃。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not very attractive or noticeable","cn":"不吸引人的﹐不引人注意的"}]},"vocab":{"pos":"adj","senses":[{"en":"If you find someone to be unprepossessing , you find them unattractive. Not that they're ugly, mind you! Just unprepossessing ."}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41unprepossessin.mp3","us":"media/ldoce/hwd/ame/e/unprepossessing.mp3"},"examples":[{"en":"Despite his unprepossessing appearance, he was very popular with women.","cn":"他虽然其貌不扬﹐但很有女人缘。"}],"oxford":{"phon":"ˌʌnˌpriːpəˈzesɪŋ","pos":"adjective","senses":[{"en":"not attractive; not making a good or strong impression","cn":"不讨人喜欢的；不吸引人的；让人无良好（或深刻）印象的"}]}},"unnerve":{"collins":{"senses":[{"pos":"VERB 动词","cn":"使担忧；使烦恼","en":"If you say that something unnerves you, you mean that it worries or troubles you.","ex":{"en":"The news about Dermot had unnerved me","cn":"关于德莫特的消息让我很担心。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if something unsettles you, it makes you feel slightly nervous and unable to relax or concentrate completely","cn":""},{"en":"to make someone very nervous, especially by shocking or surprising them","cn":""},{"en":"to try to make someone, especially someone you are competing against in a game, lose their confidence and their ability to remain calm","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/9/unnerve0205.mp3","us":"media/ldoce/hwd/ame/9/unnerve.mp3"},"examples":[{"en":"She appeared strained and a little unnerved.","cn":"她看起来神色不安，有点心慌。"},{"en":"His silence unnerved us.","cn":"他的沉默令我们心里发慌。"}],"oxford":{"phon":"ˌʌnˈnɜːv","pos":"verb","senses":[{"en":"to make somebody feel nervous or frightened or lose confidence","cn":"使紧张；使恐惧；使丧失信心","ex":{"en":"His silence unnerved us.","cn":"他的沉默令我们心里发慌。"}}]}},"up-to-date":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"something that is modern uses the most recent designs or methods","cn":""},{"en":"the newest that is available","cn":""},{"en":"using the most modern technology, ideas, information etc","cn":""}]},"collocations":{"phrases":["VERBS be | bring sth We'll have to bring our equipment up-to-date. | keep sth","ADV. really, very | bang, completely Today's holiday parks are bang up-to-date. 2 having the most recent information about sth","VERBS be, seem | keep It is difficult to keep up-to-date with all the developments. | bring sb | keep sb","ADV. completely, fully","PREP. on Bring me up-to-date on their progress. | with We can keep you fully up-to-date with your financial position."]},"media":{"uk":"media/ldoce/hwd/bre/1/up_to_date0205.mp3","us":"media/ldoce/hwd/ame/9/up-to-date.mp3"},"examples":[{"en":"They have access to up-to-date information through a computer database.","cn":"他们可以通过计算机数据库获得最新信息。"},{"en":"Our magazine will keep you up to date with fashion.","cn":"我们的杂志可以让你即时掌握最新的时尚资讯。"}],"oxford":{"phon":"ˌʌp tə ˈdeɪt","pos":"adjective","senses":[{"en":"modern; fashionable","cn":"现代化的；时髦的；流行的","ex":{"en":"This technology is bang up to date (= completely modern).","cn":"这项技术是最新的。"}},{"en":"having or including the most recent information","cn":"最新的；时新的；即时的","ex":{"en":"We are keeping up to date with the latest developments.","cn":"我们时刻留意最新的发展情况。"}}]}},"unbroken":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"连续不断的；未被打断的；完整的；未破损的","en":"If something is unbroken, it is continuous or complete and has not been interrupted or broken.","ex":{"en":"...an unbroken run of 38 match wins","cn":"38场连胜"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"continuing without being interrupted or broken","cn":"未中断的﹔未破损的﹐完整的"}]},"collocations":{"phrases":["VERBS be | remain","ADV. almost, largely, virtually a tradition of government involvement which remained virtually unbroken until the 1990s"]},"media":{"uk":"media/ldoce/hwd/bre/8/unbroken0205.mp3","us":"media/ldoce/hwd/ame/d/laadunbroken.mp3"},"examples":[{"en":"my first night of unbroken sleep since the baby was born","cn":"自孩子出世以来我睡的头一个囫囵觉"},{"en":"30 years of virtually unbroken peace","cn":"持续将近 30 年的和平"}],"oxford":{"phon":"ʌnˈbrəʊkən","pos":"adjective","senses":[{"en":"not interrupted in any way","cn":"连续的；不间断的","ex":{"en":"a single unbroken line","cn":"一条连续的线"}},{"en":"that has not been improved on","cn":"未改写的；未被打破的；未被超过的","ex":{"en":"His long jump record remained unbroken for 25 years.","cn":"他的跳远纪录 25 年没被打破。"}}]}},"unforeseeable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（问题或坏事）不可预见的，难以预测的","en":"An unforeseeable problem or unpleasant event is one which you did not expect and could not have predicted.","ex":{"en":"...severe unforeseeable weather conditions","cn":"不可预测的恶劣天气"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"to be unable to say or predict what will happen","cn":""},{"en":"something that is unpredictable is impossible to predict because the situation changes a lot and has no regular pattern","cn":""},{"en":"a situation or event, especially a bad one, that is unforeseeable could not have been predicted because it is the result of unusually bad luck","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/4/unforeseeable0205.mp3","us":"media/ldoce/hwd/ame/3/ld41unforeseeable.mp3"},"examples":[{"en":"Building a dam here could have unforeseeable consequences for the environment.","cn":"在这里修建水坝可能会对环境造成无法预料的后果。"},{"en":"unforeseeable danger","cn":"预料不到的危险"}],"oxford":{"phon":"ˌʌnfɔːˈsiːəbl","pos":"adjective","senses":[{"en":"that you cannot predict or foresee","cn":"无法预见的；难以预测的","ex":{"en":"Building a dam here could have unforeseeable consequences for the environment.","cn":"在这里修建水坝可能会对环境造成无法预料的后果。"}}]}},"unsettle":{"collins":{"senses":[{"pos":"VERB 动词","cn":"使不安；使担心","en":"If something unsettles you, it makes you feel rather worried or uncertain.","ex":{"en":"The presence of the two policemen unsettled her.","cn":"两名警察的出现让她感到不安。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if something unsettles you, it makes you feel slightly nervous and unable to relax or concentrate completely","cn":""},{"en":"to make someone very nervous, especially by shocking or surprising them","cn":""},{"en":"to try to make someone, especially someone you are competing against in a game, lose their confidence and their ability to remain calm","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41unsettle.mp3","us":"media/ldoce/hwd/ame/b/unsettle.mp3"},"examples":[{"en":"Changing schools might unsettle the kids.","cn":"转学可能会让孩子心情不能安稳。"},{"en":"The sudden changes unsettled Judy.","cn":"突如其来的变化弄得朱迪心神不宁。"}],"oxford":{"phon":"ʌnˈsetl","pos":"verb","senses":[{"en":"to make somebody feel upset or worried, especially because a situation has changed","cn":"使心神不宁；扰乱；使担忧","ex":{"en":"Changing schools might unsettle the kids.","cn":"转学可能会让孩子感到不安。"}}]}},"uncanny":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"奇怪的；离奇的；费解的","en":"If you describe something as uncanny, you mean that it is strange and difficult to explain.","ex":{"en":"The hero, Danny, bears an uncanny resemblance to Kirk Douglas","cn":"主人公丹尼与柯克·道格拉斯出奇地相像。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"very strange or very different from what you are used to","cn":""},{"en":"extremely strange and different from what is usually considered normal","cn":""},{"en":"extremely strange and unconnected with real life or normal experiences, like something out of a dream","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"If something is uncanny , it is so mysterious, strange, or unfamiliar that it seems supernatural. If you hear strange music echoing through your attic, you might refer to it as positively uncanny ."}]},"media":{"uk":"media/ldoce/hwd/bre/5/uncanny0205.mp3","us":"media/ldoce/hwd/ame/3/uncanny.mp3"},"examples":[{"en":"It was uncanny really, almost as if she knew what I was thinking.","cn":"真是不可思议，她好像知道我在想什么似的。"},{"en":"I had an uncanny feeling I was being watched.","cn":"我有种被人监视的奇怪感觉。"}],"oxford":{"phon":"ʌnˈkæni","pos":"adjective","senses":[{"en":"strange and difficult to explain","cn":"异常的；难以解释的","ex":{"en":"I had an uncanny feeling I was being watched.","cn":"我有种被人监视的奇怪感觉。"}}]}},"unitary":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"统一的；集中的；中央集权制的","en":"A unitary country or organization is one in which two or more areas or groups have joined together, have the same aims, and are controlled by a single government.","ex":{"en":"...a call for the creation of a single unitary state.","cn":"建立单一中央集权制国家的呼声"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"relating to or existing as a single unit","cn":"单一的﹐个体的"}]},"vocab":{"pos":"1 adj 2 adj","senses":[{"en":"Use the adjective unitary to describe something that has or desires unity, or oneness."}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41unitary.mp3","us":"media/ldoce/hwd/ame/4/laadunitary.mp3"},"examples":[{"en":"( BrE ) a unitary authority (= a type of local council, introduced in some areas from 1995 to replace existing local governments which consisted of county and district councils)","cn":"单一管理区（1995 年起在某些地区实行，由此成立的地方委员会取代原有的郡、区政府）"},{"en":"a unitary authority (= a type of local council, introduced in some areas from 1995 to replace existing local governments which consisted of county and district councils)","cn":""}],"oxford":{"phon":"ˈjuːnətri","pos":"adjective","senses":[{"en":"consisting of a number of areas or groups that are joined together and are controlled by one government or group","cn":"集中的；统一的；中央集权制的","lab":"specialist","ex":{"en":"a single unitary state","cn":"单一中央集权制国家"}},{"en":"single; forming one unit","cn":"单一的；形成单一个体的","lab":"formal"}]}},"unrelenting":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"不顾一切的;不留情面的","en":"If you describe someone's behaviour as unrelenting, you mean that they are continuing to do something in a very determined way, often without caring whether they hurt or embarrass other people.","ex":{"en":"She established her authority with unrelenting thoroughness","cn":"她坚定地树立起自己绝对的权威。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"没完没了的；无休止的","en":"If you describe something unpleasant as unrelenting, you mean that it continues without stopping.","ex":{"en":"...an unrelenting downpour of rain.","cn":"下个不停的瓢泼大雨"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"use this about something annoying or unpleasant that continues for a long time without stopping","cn":""},{"en":"use this about an unpleasant or frightening situation that continues for a long time without stopping","cn":""},{"en":"use this about an unpleasant or upsetting situation that is always there and does not change","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Unrelenting is an adjective that describes someone or something that is not willing to give up, like a person who tries fifty different types of ice cream in pursuit of the perfect flavor."}]},"media":{"uk":"media/ldoce/hwd/bre/b/unrelenting0205.mp3","us":"media/ldoce/hwd/ame/3/unrelenting.mp3"},"examples":[{"en":"He was unrelenting in his search for the truth about his father.","cn":"他不顾一切地搜集有关他父亲的事实真相。"},{"en":"The heat was unrelenting.","cn":"炎热没有减弱的迹象。"}],"oxford":{"phon":"ˌʌnrɪˈlentɪŋ","pos":"adjective","senses":[{"en":"not stopping or becoming less severe","cn":"持续的；不缓和的；势头不减的","ex":{"en":"unrelenting pressure","cn":"持续不断的压力"}},{"en":"if a person is unrelenting, they continue with something without considering the feelings of other people","cn":"不留情的","ex":{"en":"She is one of the president's most unrelenting critics.","cn":"她是对总统最苛刻的批评者之一。"}}]}},"unstuck":{"collins":{"senses":[{"pos":"PHRASE 短语","cn":"脱离；松脱；松开","en":"If something comes unstuck, it becomes separated from the thing that it was attached to.","ex":{"en":"The brown vinyl covering all the horizontal surfaces is coming unstuck in several places.","cn":"水平面上覆盖的棕色塑料布有几处地方松脱。"}},{"pos":"PHRASE 短语","cn":"失败；栽跟头；砸锅","en":"To come unstuck means to fail.","ex":{"en":"Where economics comes unstuck is when it doesn't take account of the anticipated actions of human beings","cn":"经济学若无视人的预期行动的话，注定是行不通的。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if a person, plan, or system comes unstuck, they fail at what they were trying to achieve 〔","cn":"人﹑计划﹑系统〕失败"},{"en":"if something comes unstuck, it becomes separated from the thing that it was stuck to","cn":"脱落﹔松开"}]},"media":{"uk":"media/ldoce/hwd/bre/9/unstuck0205.mp3","us":"media/ldoce/hwd/ame/1/unstuck.mp3"},"examples":[{"en":"The flap of the envelope had come unstuck.","cn":"信封的封口没粘牢，张开了。"},{"en":"a dangerous area of rock where many climbers come unstuck","cn":"许多攀登者在此止步的危险岩石地带"}]},"unconcern":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"漠不关心；冷淡；冷漠","en":"A person's unconcern is their lack of interest in or anxiety about something, often something that most people would be concerned about.","ex":{"en":"She'd mentioned it casually once, surprising him by her unconcern","cn":"她曾随口提到过，当时她的冷漠很让他吃惊。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when you do not care about something that other people worry about","cn":"漠不关心﹐冷漠"}]},"media":{"uk":"media/ldoce/hwd/bre/f/unconcern0205.mp3","us":"media/ldoce/hwd/ame/f/laadunconcern.mp3"},"examples":[{"en":"She received the news with apparent unconcern.","cn":"她接到这消息时显然无动于衷。"},{"en":"the government’s apparent unconcern about high inflation","cn":"政府对高通货膨胀率明显的漠不关心"}],"oxford":{"phon":"ˌʌnkənˈsɜːn","pos":"noun","senses":[{"en":"a lack of care, interest or worry about something that other people would care about","cn":"冷漠；不关心；无兴趣","ex":{"en":"She received the news with apparent unconcern.","cn":"她接到这消息时显然无动于衷。"}}]}},"underbelly":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"软肋；最薄弱的环节；最易受攻击的部分","en":"The underbelly of something is the part of it that can be most easily attacked or criticized.","ex":{"en":"The ANC are attacking rugby because it is the soft underbelly of South African sport","cn":"橄榄球运动在“非国大”受到抨击，因为它是南非体育的软肋。"}},{"pos":"N-COUNT 可数名词","cn":"（动物的）下腹部；（交通工具的）底部，下部","en":"The underbelly of an animal or a vehicle is the underneath part of it.","ex":{"en":"...the underbelly of a fish","cn":"鱼肚"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the unpleasant parts of a place or society that are normally hidden 〔","cn":"地方或社会的〕阴暗面"},{"en":"the weakest part of an organization or a person’s character, that is most easily attacked or criticized 〔","cn":"机构或某人性格中的〕脆弱点﹐最薄弱部分"},{"en":"the lower part of an animal’s body, including the stomach 〔","cn":"动物的〕下腹部"}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41underbelly.mp3","us":"media/ldoce/hwd/ame/5/underbelly.mp3"},"examples":[{"en":"The trade deficit remains the soft underbelly of the US economy.","cn":"贸易赤字仍是美国经济的软肋。"},{"en":"( figurative ) He became familiar with the dark underbelly of life in the city (= the parts that are usually hidden).","cn":"他逐渐熟悉都市生活的阴暗面。"}],"oxford":{"phon":"ˈʌndəbeli","pos":"noun","senses":[{"en":"the soft part of an animal on the underside of its body","cn":"（动物的）下腹部，腩"},{"en":"the weakest part of something that is most easily attacked","cn":"脆弱点；薄弱环节","ex":{"en":"The trade deficit remains the soft underbelly of the US economy.","cn":"贸易赤字仍是美国经济的软肋。"}},{"en":"an unpleasant or criminal part of society that is usually hidden","cn":"（社会的）阴暗面，底层","ex":{"en":"He became familiar with the dark underbelly of life in the city.","cn":"他逐渐熟悉了城市生活的阴暗面。"}}]}},"unsatisfactory":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不够好的；不能令人满意的；不能接受的","en":"If you describe something as unsatisfactory, you mean that it is not as good as it should be, and cannot be considered acceptable.","ex":{"en":"The inspectors said just under a third of lessons were unsatisfactory","cn":"督察员说只有不到1/3的课程不够好。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not good enough and likely to cause problems or make people unhappy","cn":""},{"en":"not good enough for a particular purpose or for what someone needs","cn":""},{"en":"if someone's performance, work, or products are not up to scratch , they are not of the standard that is necessary or expected","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/a/brelasdeunsatisfactory.mp3","us":"media/ldoce/hwd/ame/e/laadunsatisfactory.mp3"},"examples":[{"en":"an unsatisfactory situation","cn":"让人不满意的状况"}],"oxford":{"phon":"ˌʌnˌsætɪsˈfæktəri","pos":"adjective","senses":[{"en":"not good enough","cn":"不够好的；不能令人满意的","ex":{"en":"The results were considered to be thoroughly unsatisfactory.","cn":"这些结果让人非常不满意。"}}]}},"underpass":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"高架桥下通道；地下通道；下穿交叉道","en":"An underpass is a road or path that goes underneath a railway or another road.","ex":{"en":"The Hanger Lane underpass was closed through flooding.","cn":"发洪水期间，汉格巷地下通道被关闭。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a road or path that goes under another road or a railway","cn":"地下通道﹔下穿交叉道﹔下层通道"}]},"media":{"uk":"media/ldoce/hwd/bre/8/underpass0205.mp3","us":"media/ldoce/hwd/ame/3/underpass.mp3"},"oxford":{"phon":"ˈʌndəpɑːs","pos":"noun","senses":[{"en":"a road or path that goes under another road or railway track","cn":"下穿式立交桥；地下通道"}]}},"unclear":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不清楚的；不确定的","en":"If something is unclear, it is not known or not certain.","ex":{"en":"It is unclear how much popular support they have among the island's population","cn":"目前还不清楚他们在岛上的民众中间有多高的支持率。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不明白的；不清楚的；不确定的","en":"If you are unclear about something, you do not understand it properly or are not sure about it.","ex":{"en":"He is still unclear about his own future","cn":"他仍然不清楚自己的将来会怎样。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a picture, shape, image etc that is faint is unclear because it is a long way away, there is not enough light, or it was very lightly drawn","cn":""},{"en":"unclear so that only the general shape can be seen, and not small details","cn":""},{"en":"a photograph, television picture etc that is fuzzy is not clear, and it is difficult to see separate edges and objects, often because there is something wrong with your equipment or with the way the pictures were taken","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/0/unclear0205.mp3","us":"media/ldoce/hwd/ame/6/unclear.mp3"},"examples":[{"en":"I'm unclear about what you want me to do.","cn":"我不太明白你要我做什么。"},{"en":"It is unclear whether there is any damage.","cn":"有无损坏尚不清楚。"}],"oxford":{"phon":"ˌʌnˈklɪə(r)","pos":"adjective","senses":[{"en":"not clear or definite; difficult to understand or be sure about","cn":"不清楚的；不确定的；难以掌握的","ex":{"en":"His motives are unclear.","cn":"他的用意不明。"}},{"en":"not fully understanding something","cn":"不完全明白；不理解","ex":{"en":"I'm unclear about what you want me to do.","cn":"我不太明白你要我做什么。"}}]}},"underworld":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"黑帮；黑社会","en":"The underworld in a city is the organized crime there and the people who are involved in it.","ex":{"en":"...a Spanish Harlem underworld of gangs, drugs and violence","cn":"充斥着犯罪团伙、毒品和暴力的西班牙哈莱姆区黑社会"}},{"pos":"N-SING 单数名词","cn":"地狱；阴间；冥府","en":"In many ancient religions and legends, the underworld is a place under the earth's surface where people go after they die.","ex":{"en":"...Persephone, goddess of the underworld.","cn":"冥后珀耳塞福涅"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a group of criminals who work together","cn":""},{"en":"a group of people who work together and organize an illegal trade, especially in something such as drugs or weapons","cn":""},{"en":"a large and powerful organization that controls illegal businesses and criminal activities","cn":""}]},"collocations":{"phrases":["ADJ. dark, sinister the dark underworld of smuggling | criminal","UNDERWORLD + NOUN figure","PREP. in the &hellip; ~ She was a shady figure in the Dublin underworld."]},"media":{"uk":"media/ldoce/hwd/bre/6/underworld0205.mp3","us":"media/ldoce/hwd/ame/3/underworld.mp3"},"examples":[{"en":"the Glasgow underworld","cn":"格拉斯哥的黑社会"},{"en":"the criminal underworld","cn":"罪恶的黑社会"}],"oxford":{"phon":"ˈʌndəwɜːld","pos":"noun","senses":[{"en":"the people and activities involved in crime in a particular place","cn":"黑社会；黑道；犯罪集团","ex":{"en":"the criminal underworld","cn":"罪恶的黑社会"}},{"en":"the place under the earth where people are believed to go when they die","cn":"阴间；冥府；阴曹地府","ex":{"en":"The three-headed dog Cerberus guarded the entrance to the underworld.","cn":"三头犬刻耳柏洛斯守卫着冥界的入口。"}}]}},"undisguised":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"不加掩饰的；公开的；坦率的","en":"If you describe someone's feelings as undisguised, you mean that they show them openly and do not make any attempt to hide them.","ex":{"en":"...undisguised glee","cn":"不加掩饰的高兴"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"an undisguised feeling is clearly shown and not hidden 〔","cn":"感觉〕公开的，坦率的，不加掩饰的"}]},"media":{"uk":"media/ldoce/hwd/bre/3/brelasdeundisguised.mp3","us":"media/ldoce/hwd/ame/8/laadundisguised.mp3"},"examples":[{"en":"a look of undisguised admiration","cn":"不加掩饰的仰慕神情"},{"en":"There was undisguised contempt in his voice.","cn":"他的语气中带着不加掩饰的轻蔑。"}],"oxford":{"phon":"ˌʌndɪsˈɡaɪzd","pos":"adjective","senses":[{"en":"that you do not try to hide from other people; not disguised","cn":"坦诚的；率直的；不加掩饰的","ex":{"en":"a look of undisguised admiration","cn":"不加掩饰的仰慕神情"}}]}},"unreal":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不真实的；怪异的；难以相信的","en":"If you say that a situation is unreal, you mean that it is so strange that you find it difficult to believe it is happening.","ex":{"en":"It was unreal. Like some crazy childhood nightmare","cn":"这不是真的，就像儿时的某个荒唐的噩梦一样。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不可能的；虚构的","en":"If you use unreal to describe something, you are critical of it because you think that it is not like, or not related to, things you expect to find in the real world.","ex":{"en":"...unreal financial targets","cn":"不切实际的理财目标"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"极好的","en":"Some people use unreal to indicate that they like something very much.","ex":{"en":"Oh, I can't explain it. It's just unreal. Everybody is so happy.","cn":"啊，我都没法形容。就是太棒了，每个人都很高兴。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"an experience, situation etc that is unreal seems so strange that you think you must be imagining it","cn":"不真实的﹐虚幻的"},{"en":"not related to real things that happen","cn":"脱离现实的﹐不切实际的"},{"en":"very exciting","cn":"令人激动的"}]},"collocations":{"phrases":["VERBS be, feel, look, seem | become","ADV. very | quite, totally, wholly | almost | a little, rather, slightly | somehow He seemed somehow unreal, a creature from another world. "]},"media":{"uk":"media/ldoce/hwd/bre/4/unreal0205.mp3","us":"media/ldoce/hwd/ame/2/unreal.mp3"},"examples":[{"en":"The party began to take on an unreal, almost nightmarish quality.","cn":"聚会开始呈现出虚幻、近乎梦魇般的气氛。"},{"en":"Many people have unreal expectations of what marriage will be like.","cn":"许多人对婚姻生活抱有不切实际的憧憬。"}],"oxford":{"phon":"ˌʌnˈrɪəl","pos":"adjective","senses":[{"en":"so strange that it is more like a dream than reality","cn":"奇异的；虚幻的；梦幻般的","ex":{"en":"The party began to take on an unreal, almost nightmarish quality.","cn":"聚会开始呈现出虚幻、近乎梦魇般的气氛。"}},{"en":"not related to reality","cn":"不真实的；脱离现实的","ex":{"en":"Many people have unreal expectations of what marriage will be like.","cn":"许多人对婚姻生活抱有不切实际的憧憬。"}},{"en":"used to say that you like something very much or that something surprises you","cn":"（表示十分喜爱或惊讶）","lab":"informal","ex":{"en":"‘That's unreal!’ she laughed.","cn":"“这怎么可能！”她笑了起来。"}}]}},"untrained":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未经培训的；未经训练的；无经验的","en":"Someone who is untrained has not been taught the skills that they need for a particular job, activity, or situation.","ex":{"en":"It is a nonsense to say we have untrained staff dealing with emergencies","cn":"说我们派未受过培训的员工来处理紧急事故简直是胡说八道。"}},{"pos":"ADJ 形容词","cn":"(嗓子)未受专门训练的；(心智)未受正规教育的","en":"If you describe a voice or a mind, for example, as untrained, you mean that it has not been developed through formal education or training.","ex":{"en":"It was often said that he had the best untrained mind in politics.","cn":"人们常说，他虽未受过专门训练却极有政治头脑。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who is inexperienced does not know much about a job or activity, either because they have not done it at all or because they have done it for only a short time","cn":""},{"en":"to not have enough experience of doing a particular job or activity","cn":""},{"en":"if you are new to a job or activity, you do not have much experience of doing it because you have only just started it","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/1/brelasdeuntrained.mp3","us":"media/ldoce/hwd/ame/8/laaduntrained.mp3"},"examples":[{"en":"To the untrained eye, the products look remarkably similar.","cn":"这些产品在没有受过专门训练的人看来几乎一模一样。"},{"en":"untrained in keyboard skills","cn":"未经键盘操作技能训练的"}],"oxford":{"phon":"ˌʌnˈtreɪnd","pos":"adjective","senses":[{"en":"not trained to perform a particular job or skill; without formal training in something","cn":"没有训练的；未经正规培训的","ex":{"en":"untrained in keyboard skills","cn":"未经键盘操作技能训练的"}}]}},"up-to-the-minute":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"最近的；最新的","en":"Up-to-the-minute information is the latest information that you can get about something.","ex":{"en":"...24 hours a day up-to-the-minute instant news","cn":"一天24小时最新消息即时播报"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"the latest news, information etc is the most recent news, information etc","cn":""},{"en":"up-to-date information is the most recent and correct information","cn":""},{"en":"up-to-the-minute news or information is the most recent news or information about something that is likely to change very quickly all the time","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/5/brelasdeup-to-the-minute.mp3","us":"media/ldoce/hwd/ame/b/up-to-the-minute.mp3"},"examples":[{"en":"up-to-the-minute designs","cn":"最时髦的设计"},{"en":"up-to-the-minute news","cn":"最新消息"}],"oxford":{"phon":"ˌʌp tə ðə ˈmɪnɪt","pos":"adjective","senses":[{"en":"having or including the most recent information","cn":"最新的；时新的；即时的","ex":{"en":"up-to-the-minute news","cn":"最新消息"}},{"en":"modern; fashionable","cn":"现代化的；时髦的；流行的","ex":{"en":"up-to-the-minute designs","cn":"最时髦的设计"}}]}},"underling":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"跟班儿；手下；羽翼；喽啰；走卒","en":"You refer to someone as an underling when they are inferior in rank or status to someone else and take orders from them. You use this word to show that you do not respect someone.","ex":{"en":"Every underling feared him.","cn":"所有的手下都怕他。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an insulting word for someone who has a low rank – often used humorously","cn":"下属﹐喽啰，走卒〔侮辱性用词﹔常为幽默用法〕"}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41underling.mp3","us":"media/ldoce/hwd/ame/2/underling.mp3"},"oxford":{"phon":"ˈʌndəlɪŋ","pos":"noun","senses":[{"en":"a person with a lower rank or status","cn":"走卒；喽啰；手下；下属","ex":{"en":"He dishes out orders to his underlings.","cn":"他向手下人随意发号施令。"}}]}},"unanswerable":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"无法回答的；没有答案的","en":"If you describe a question as unanswerable, you mean that it has no possible answer or that a particular person cannot possibly answer it.","ex":{"en":"They would ask their mother unanswerable questions.","cn":"他们会问母亲一些无法回答的问题。"}},{"pos":"ADJ 形容词","cn":"明摆着的；无可辩驳的","en":"If you describe a case or argument as unanswerable, you think that it is obviously true or correct and that nobody could disagree with it.","ex":{"en":"He actually became convinced that the nurses had an unanswerable case","cn":"他实际上已经相信了护士们的情况确实如此。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"an unanswerable question is one that cannot be answered 〔","cn":"问题〕无法回答的﹐没有答案的"},{"en":"definitely true and therefore impossible to argue against","cn":"无可辩驳的"}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41unanswerable.mp3","us":"media/ldoce/hwd/ame/a/unanswerable.mp3"},"examples":[{"en":"They presented an unanswerable case for more investment.","cn":"他们提出了一个无可争辩的理由，要求增加投资。"},{"en":"The case (= reasons for doing something ) for better public transport is unanswerable .","cn":"要求改善公共交通的理由是无可争辩的。"}],"oxford":{"phon":"ʌnˈɑːnsərəbl","pos":"adjective","senses":[{"en":"an unanswerable argument, etc. is one that nobody can question or disagree with","cn":"无可争辩的；不容反对的","ex":{"en":"They presented an unanswerable case for more investment.","cn":"他们提出了一个无可争辩的理由，要求增加投资。"}},{"en":"an unanswerable question is one that has no answer or that you cannot answer","cn":"无答案的；无法回答的"}]}},"unpromising":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"没前途的；没有希望的","en":"If you describe something as unpromising, you think that it is unlikely to be successful or produce anything good in the future.","ex":{"en":"In fact, his business career had distinctly unpromising beginnings","cn":"事实上，他的经商生涯从初期就明显前景暗淡。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not likely to be good or successful","cn":"不乐观的﹔不大会成功的"}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41unpromising.mp3","us":"media/ldoce/hwd/ame/9/laadunpromising.mp3"},"examples":[{"en":"Sales improved after an unpromising start .","cn":"销量在经历了一个不容乐观的开端之后开始上升。"},{"en":"an unpromising place for a picnic","cn":"不太理想的野餐地点"}],"oxford":{"phon":"ʌnˈprɒmɪsɪŋ","pos":"adjective","senses":[{"en":"not likely to be successful or show good results","cn":"不乐观的；难有好结果的"}]}},"unsweetened":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未加糖的；不含甜料的","en":"Unsweetened food or drink does not have any sugar or other sweet substance added to it."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"unsweetened food or drink has not had sugar added to it 〔","cn":"食品或饮料〕未加糖的"}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41unsweetened.mp3","us":"media/ldoce/hwd/ame/1/laadunsweetened.mp3"},"oxford":{"phon":"ˌʌnˈswiːtnd","pos":"adjective","senses":[{"en":"without sugar or a similar substance having been added","cn":"未加糖的；未加甜味素的"}]}},"unexciting":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不令人兴奋的；单调乏味的","en":"If you describe someone or something as unexciting, you think they are rather boring, and not likely to shock or surprise you in any way.","ex":{"en":"He is regarded as very capable but unexciting","cn":"他被认为非常有能力，但为人乏味。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"ordinary and slightly boring","cn":"平淡的﹔单调的﹔没劲的"}]},"media":{"uk":"media/ldoce/hwd/bre/a/unexciting0205.mp3","us":"media/ldoce/hwd/ame/b/laadunexciting.mp3"},"examples":[{"en":"After Tokyo, Okinawa seemed unexciting at first.","cn":"去过东京后，初到冲绳时让人觉得有些乏味无聊。"}],"oxford":{"phon":"ˌʌnɪkˈsaɪtɪŋ","pos":"adjective","senses":[{"en":"not interesting; boring","cn":"枯燥的；乏味的；无聊的","ex":{"en":"Some people might find the life we live here unexciting.","cn":"有些人可能会觉得我们在这里的生活平淡无奇。"}}]}},"unsuitable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不适宜的；不合适的","en":"Someone or something that is unsuitable for a particular purpose or situation does not have the right qualities for it.","ex":{"en":"Amy's shoes were unsuitable for walking any distance.","cn":"埃米的鞋子根本不适合走路。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not having the right qualities for a particular person, purpose, or situation","cn":"不合适的﹔不适宜的"},{"en":"not suitable for a particular situation or purpose – used especially about someone’s behaviour or language","cn":""},{"en":"not the right thing or person for a particular job or purpose","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Something that's unsuitable doesn't work well or is out of place. A kitchen knife is unsuitable for sawing firewood."}]},"collocations":{"phrases":["VERBS be, prove | make sth The huge proportions of the main rooms made the house unsuitable for conversion into flats. | consider sth, deem ","ADV. highly, most, very | completely, entirely, quite, totally, wholly | manifestly, obviously"]},"media":{"uk":"media/ldoce/hwd/bre/8/unsuitable0205.mp3","us":"media/ldoce/hwd/ame/0/laadunsuitable.mp3"},"examples":[{"en":"He was wearing shoes that were totally unsuitable for climbing.","cn":"他穿了一双完全不适合登山的鞋子。"},{"en":"They were unsuitably dressed for the occasion.","cn":"他们的穿着在那种场合很不得体。"}],"oxford":{"phon":"ʌnˈsuːtəbl","pos":"adjective","senses":[{"en":"not right or appropriate for a particular person, purpose or occasion","cn":"不适当的；不适宜的；不合适的","ex":{"en":"He was wearing shoes that were totally unsuitable for climbing.","cn":"他穿了一双完全不适合登山的鞋子。"}}]}},"urinal":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（固定在墙上的）男用小便池","en":"A urinal is a bowl fixed to the wall of a men's public toilet for men to urinate in."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a room with a toilet in it, in someone’s house or in a public place","cn":""},{"en":"a room with a toilet in it, in someone’s house. In British English, bathroom is used especially when you want to be polite. In American English, it is the usual word to use","cn":""},{"en":"a room in a public place that has one or more toilets in it","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/1/urinal0205.mp3","us":"media/ldoce/hwd/ame/7/urinal.mp3"},"oxford":{"phon":"jʊəˈraɪnl","pos":"noun","senses":[{"en":"a type of toilet for men that is attached to the wall; a room or building containing urinals","cn":"（男用）小便池，小便器；男厕所","ex":{"en":"Modern waterless urinals can help to save the environment.","cn":"现代无水小便器有助环保。"}}]}},"unison":{"collins":{"senses":[{"pos":"PHRASE 短语","cn":"同时；一起","en":"If two or more people do something in unison, they do it together at the same time.","ex":{"en":"The students gave him a rapturous welcome, chanting in unison: 'We want the king!'","cn":"学生们给予了他热烈的欢迎，他们齐声高喊：“我们要国王！”"}},{"pos":"PHRASE 短语","cn":"和谐地;一致地","en":"If people or organizations act in unison, they act the same way because they agree with each other or because they want to achieve the same aims.","ex":{"en":"For churches not normally noted for their ability to act in unison, today's unprecedented move was all the more remarkable","cn":"对于通常无法统一行动的各个教会来说，今天这一前所未有的举动无疑更加非同寻常。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"if people speak or do something in unison, they say the same words at the same time or do the same thing at the same time 〔","cn":"说话﹑做事〕一起﹐一齐"},{"en":"if two groups, governments etc do something in unison, they do it together because they agree with each other","cn":"共同﹐一致〔做某事〕"}]},"vocab":{"pos":"n","senses":[{"en":"The noun unison describes something that is synchronized or simultaneous, like when someone asks a question and you and your friend respond with the exact same answer at the same moment. When something is said in unison , two or more voices sound like one."}]},"media":{"uk":"media/ldoce/hwd/bre/f/unison0205.mp3","us":"media/ldoce/hwd/ame/1/unison.mp3"},"examples":[{"en":"‘Good morning!’ the kids replied in unison. “","cn":"早上好！”孩子们齐声应答。"},{"en":"Management and workers must act in unison to compete with foreign business.","cn":"管理层和员工必须联合起来与外国企业竞争。"}],"oxford":{"phon":"ˈjuːnɪsn","pos":"","senses":[{"en":"one of the largest British trade unions, formed in 1993 by combining three existing unions (NALGO, NUPE and COHSE). Its members work mainly in local government, the health service and other industries serving the public.","cn":"统一：英国最大的工会之一，成立于1993年，由三个现有工会（NALGO，NUPE和COHSE）合并而成。其成员主要在地方政府，卫生服务和其他服务于公众的行业中工作。"}]}},"upchuck":{"collins":{"senses":[{"pos":"VERB 动词","cn":"呕出；吐出","en":"If you upchuck, food and drink comes back up from your stomach and out through your mouth."}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to bring food or drink up from your stomach and out through your mouth because you are ill or drunk","cn":"呕吐"}]},"media":{"uk":"media/ldoce/hwd/bre/1/upchuck0205.mp3","us":"media/ldoce/hwd/ame/2/upchuck.mp3"},"oxford":{"phon":"ˈʌptʃʌk","pos":"verb","senses":[{"en":"to vomit","cn":"呕吐"}]}},"unobtrusive":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不显著的；不容易被注意到的；不引人注目的","en":"If you describe something or someone as unobtrusive, you mean that they are not easily noticed or do not draw attention to themselves.","ex":{"en":"The coffee-table is glass, to be as unobtrusive as possible","cn":"那张咖啡桌是玻璃的，为的是尽量不惹眼。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a subtle change or difference is difficult to notice unless you look closely or think about it carefully","cn":""},{"en":"something, especially an object, that is unobtrusive is not very noticeable, especially because it is small or ordinary compared to other things","cn":""},{"en":"things or people that are inconspicuous are not noticeable because they look the same as the people or things around them","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Use the adjective unobtrusive to describe something that doesn’t attract much attention, like an unobtrusive waiter who doesn't interrupt diners to rattle off the nightly specials, or an unobtrusive stain on the floor that your parents haven't noticed."}]},"media":{"uk":"media/ldoce/hwd/bre/7/unobtrusive0205.mp3","us":"media/ldoce/hwd/ame/7/unobtrusive.mp3"},"examples":[{"en":"The service at the hotel is efficient and unobtrusive.","cn":"那旅馆的服务既有效率，又沉稳低调。"},{"en":"Dora slipped unobtrusively in through the back door.","cn":"多拉悄悄地从后门溜了进去。"}],"oxford":{"phon":"ˌʌnəbˈtruːsɪv","pos":"adjective","senses":[{"en":"not attracting unnecessary attention","cn":"不张扬的；不招摇的","ex":{"en":"The service at the hotel is efficient and unobtrusive.","cn":"那旅馆的服务既有效率，又沉稳低调。"}}]}},"unpredictable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无法预言的；不可预测的；难以预料的","en":"If you describe someone or something as unpredictable, you mean that you cannot tell what they are going to do or how they are going to behave.","ex":{"en":"He is utterly unpredictable.","cn":"他是个高深莫测的人。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"to be unable to say or predict what will happen","cn":""},{"en":"something that is unpredictable is impossible to predict because the situation changes a lot and has no regular pattern","cn":""},{"en":"a situation or event, especially a bad one, that is unforeseeable could not have been predicted because it is the result of unusually bad luck","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"When something's unpredictable , it doesn't happen at expected times or it can't be predicted. If trains were unpredictable , they wouldn't follow a set schedule and you'd never know when one would arrive."}]},"media":{"uk":"media/ldoce/hwd/bre/b/unpredictable0205.mp3","us":"media/ldoce/hwd/ame/e/unpredictable.mp3"},"examples":[{"en":"The result is entirely unpredictable.","cn":"结果是完全无法预料的。"},{"en":"the unpredictability of the English weather","cn":"英国天气的变幻莫测"}],"oxford":{"phon":"ˌʌnprɪˈdɪktəbl","pos":"adjective","senses":[{"en":"that cannot be predicted because it changes a lot or depends on too many different things","cn":"无法预言的；不可预测的；难以预料的","ex":{"en":"The unpredictable weather in the mountains can make climbing extremely hazardous.","cn":"山里那变幻莫测的天气可以使登山变得异常危险。"}},{"en":"if a person is unpredictable, you cannot predict how they will behave in a particular situation","cn":"（人）善变的，难以捉摸的","ex":{"en":"Her behaviour became so unpredictable when she had been drinking.","cn":"她一酗酒行为就变得不可捉摸。"}}]}},"unleavened":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未经发酵的；不含酵母的","en":"Unleavened bread or dough is made without any yeast."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"unleavened bread is flat because it is not made with yeast 〔","cn":"面包〕未经发酵的"}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41unleavened.mp3","us":"media/ldoce/hwd/ame/a/unleavened.mp3"},"oxford":{"phon":"ˌʌnˈlevnd","pos":"adjective","senses":[{"en":"made without any yeast, or other substance that would cause the bread to rise, and therefore flat","cn":"未发酵的；不加酵母的；死面的"}]}},"unfeeling":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（人）没同情心的，无情的","en":"If you describe someone as unfeeling, you are criticizing them for their lack of kindness or sympathy for other people.","ex":{"en":"He was branded an unfeeling bully","cn":"他被说成冷酷的恶棍。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not sympathetic towards other people’s feelings","cn":"无情的﹐冷酷的﹐冷漠的"}]},"media":{"uk":"media/ldoce/hwd/bre/8/unfeeling0205.mp3","us":"media/ldoce/hwd/ame/b/unfeeling.mp3"},"examples":[{"en":"Dave had been quite wrong to call Michelle cold and unfeeling .","cn":"一直以来﹐戴夫说米歇尔冷漠无情是大错特错了。"}],"oxford":{"phon":"ʌnˈfiːlɪŋ","pos":"adjective","senses":[{"en":"not showing care or sympathy for other people","cn":"漠不关心的；无情的；无怜悯心的","ex":{"en":"an unfeeling attitude","cn":"无情的态度"}}]}},"unrecognized":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"不被人注意的；未被认出的","en":"If someone does something unrecognized, nobody knows or recognizes them while they do it.","ex":{"en":"He is believed to have worked unrecognised as a doorman at East End clubs","cn":"据信他在伦敦东区的夜总会当过看门人而没被认出来。"}},{"pos":"ADJ 形容词","cn":"未意识到的","en":"If something is unrecognized, people are not aware of it.","ex":{"en":"There is the possibility that hypothermia can go unrecognized","cn":"人们有可能察觉不到体温的过低。"}},{"pos":"ADJ 形容词","cn":"不被承认的；不被认可的","en":"If you or your achievements or qualities are unrecognized, you have not been properly appreciated or acknowledged by other people for what you have done.","ex":{"en":"Hard work and talent so often go unrecognised and unrewarded","cn":"努力和天赋经常不被认可，也得不到回报。"}},{"pos":"ADJ 形容词","cn":"非正式的；非官方的","en":"An unrecognized meeting, agreement, or political party is not formally acknowledged as legal or valid by the authorities.","ex":{"en":"...the unrecognised Islamic Fundamentalist Movement","cn":"未被官方承认的伊斯兰原教旨主义运动"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not having received praise or respect for something good you have achieved","cn":"未得到承认的"},{"en":"not noticed or not thought to be important","cn":"不被注意的﹔被忽略的﹐不受重视的"},{"en":"an unrecognized group, meeting, agreement etc is not considered to be legal or acceptable by someone in authority 〔","cn":"组织﹑会议﹑协议等〕非法的﹐得不到承认的"}]},"media":{"uk":"media/ldoce/hwd/bre/a/unrecognized0205.mp3","us":"media/ldoce/hwd/ame/7/laadunrecognized.mp3"},"examples":[{"en":"The problem of ageism in the workplace often goes unrecognized.","cn":"工作场所的年龄歧视问题常被忽视。"},{"en":"one of the great unrecognized jazzmen of the 1930s 20","cn":"世纪30年代没有得到承认的杰出爵士乐演奏者之一"}],"oxford":{"phon":"ʌnˈrekəɡnaɪzd","pos":"adjective","senses":[{"en":"that people are not aware of or do not realize is important","cn":"未被意识到的；被忽略的；不受重视的","ex":{"en":"The problem of ageism in the workplace often goes unrecognized.","cn":"工作场所的年龄歧视问题常被忽视。"}},{"en":"not having received the praise and notice they deserve for something that they have done or achieved","cn":"被埋没的；未得到赏识的","ex":{"en":"He remained largely unrecognized by the scientific establishment.","cn":"他在很大程度上仍未得到科学界的认可。"}}]}},"upcountry":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"内陆的；北方边远地区的","en":"Upcountry places are towards the middle or north of a large country, usually in the countryside.","ex":{"en":"...a collection of upcountry hamlets.","cn":"内地村落"}}]}},"unwind":{"collins":{"senses":[{"pos":"VERB 动词","cn":"放松；减压","en":"When you unwind, you relax after you have done something that makes you tense or tired.","ex":{"en":"It helps them to unwind after a busy day at work","cn":"这有助于他们忙碌一天后放松自己。"}},{"pos":"V-ERG 及物/不及物动词","cn":"解开；展开","en":"If you unwind a length of something that is wrapped round something else or round itself, you loosen it and make it straight. You can also say that it unwinds .","ex":{"en":"One of them unwound a length of rope from around his waist","cn":"其中一人把绑在腰间的一条绳子解下来。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to rest or do something that is enjoyable after you have been working","cn":""},{"en":"to stop working or stop being active, and sit down or lie down so that you become less tired","cn":""},{"en":"to gradually relax after you have been working hard or feeling anxious","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"The literal meaning of the verb unwind is exactly what it sounds like — the opposite of \"wind,\" or twist. But when someone says they need to unwind , they mean that they need to relax."}]},"media":{"uk":"media/ldoce/hwd/bre/2/unwind0205.mp3","us":"media/ldoce/hwd/ame/3/unwind.mp3"},"examples":[{"en":"Music helps me unwind after a busy day.","cn":"音乐使我在忙碌一天后得以放松。"},{"en":"He unwound his scarf from his neck.","cn":"他从脖子上解下围巾。"}],"oxford":{"phon":"ˌʌnˈwaɪnd","pos":"verb","senses":[{"en":"if something that has been wrapped into a ball or around something unwinds or you unwind it, it becomes, or you make it, straight, flat or loose again","cn":"（使卷绕之物）解开，打开，松开","g":"[transitive, intransitive]","ex":{"en":"to unwind a ball of string","cn":"解开一团绳"}},{"en":"to stop worrying or thinking about problems and start to relax","cn":"放松；轻松","g":"[intransitive]","ex":{"en":"Music helps me unwind after a busy day.","cn":"音乐使我在忙碌一天后得以放松。"}}]}},"unsafe":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不安全的；危险的","en":"If a building, machine, activity, or area is unsafe, it is dangerous.","ex":{"en":"Critics claim the trucks are unsafe","cn":"批评家声称这些卡车很危险。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"身处险境的","en":"If you are unsafe, you are in danger of being harmed.","ex":{"en":"In the larger neighbourhood, I felt very unsafe.","cn":"在大一点的小区里，我感到很不安全。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"证据不足的;证据不可靠的","en":"If a criminal conviction is unsafe, it is not based on enough evidence or is based on false evidence.","ex":{"en":"An appeal court decided their convictions were unsafe.","cn":"上诉法庭裁定对他们的判罪证据不足。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"likely to cause death or serious harm, or cause something bad to happen","cn":""},{"en":"if something is risky, something bad could easily happen or you could easily make a mistake","cn":""},{"en":"dangerous – used especially about substances, jobs, and journeys","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/0/unsafe0205.mp3","us":"media/ldoce/hwd/ame/9/laadunsafe.mp3"},"examples":[{"en":"Their convictions were declared unsafe.","cn":"先前给他们的定罪已经宣布证据不足。"},{"en":"It was considered unsafe to release the prisoners.","cn":"释放这些囚犯被认为是危险的。"}],"oxford":{"phon":"ʌnˈseɪf","pos":"adjective","senses":[{"en":"not safe; dangerous","cn":"不安全的；危险的","ex":{"en":"The roof was declared unsafe.","cn":"已宣布屋顶有安全隐患。"}},{"en":"in danger of being harmed","cn":"身处险境的","ex":{"en":"He felt unsafe and alone.","cn":"他感到既危险又孤单。"}},{"en":"based on evidence that may be false or is not good enough","cn":"证据不可靠（或不足）的","lab":"British English, law，，","ex":{"en":"Their convictions were declared unsafe.","cn":"先前给他们的定罪已经宣布证据不足。"}}]}},"uncoordinated":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（人）动作不协调的，笨拙的","en":"If you describe someone as uncoordinated you mean that their movements are not smooth or controlled.","ex":{"en":"They were unsteady on their feet and rather uncoordinated.","cn":"他们站立不稳，协调性较差。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（行动、计划）组织不力的，未协调好的","en":"If you describe actions or plans as uncoordinated, you mean they are not well-organized.","ex":{"en":"Government action has been half-hearted and uncoordinated.","cn":"政府行动半心半意，组织不力。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"moving or doing things in a careless way, especially so that you drop things, knock into things etc","cn":""},{"en":"moving in a way that does not seem relaxed or comfortable","cn":""},{"en":"moving in a way that is not graceful – used especially about people or things that are big","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/8/uncoordinated0205.mp3","us":"media/ldoce/hwd/ame/2/uncoordinated.mp3"},"oxford":{"phon":"ˌʌnkəʊˈɔːdɪneɪtɪd","pos":"adjective","senses":[{"en":"if a person is uncoordinated, they are not able to control their movements well, and are therefore not very good at some sports and physical activities","cn":"动作不协调的；不灵便的；手脚笨拙的"},{"en":"having no control; not moving smoothly or together","cn":"不协调的；不灵活的"},{"en":"not well organized; with no thought for how the different parts work together","cn":"不缜密的；无通盘安排的；缺乏全面考虑的","ex":{"en":"The budget process had been uncoordinated and inefficient.","cn":"预算过程不协调且效率低下。"}}]}},"unsporting":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"没有体育道德的","en":"If you describe someone playing a game as unsporting, you are critical of them because they have done something that is unfair to their opponent.","ex":{"en":"Players are warned, fined and can even be disqualified for unsporting actions in the heat of contest.","cn":"在激烈的竞赛中，缺乏体育道德的选手会被警告、罚款乃至撤销比赛资格。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"behaving in an unfair way, especially towards an opponent in a game or competition","cn":"不公平的﹐不光明正大的﹔〔尤指〕没有体育精神的"}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41unsporting.mp3","us":"media/ldoce/hwd/ame/a/ld41unsporting.mp3"},"oxford":{"phon":"ˌʌnˈspɔːtɪŋ","pos":"adjective","senses":[{"en":"not fair or generous in your behaviour or treatment of others, especially of an opponent in a game","cn":"不公平的；不光明正大的；（尤指）缺乏体育道德的"}]}},"uncover":{"collins":{"senses":[{"pos":"VERB 动词","cn":"揭露，发现（隐秘之事）","en":"If you uncover something, especially something that has been kept secret, you discover or find out about it.","ex":{"en":"Auditors said they had uncovered evidence of fraud","cn":"审计人员说他们已经发现了欺诈的证据。"}},{"pos":"VERB 动词","cn":"发现，发掘（地下埋藏之物）","en":"When people who are digging somewhere uncover something, they find a thing or a place that has been under the ground for a long time.","ex":{"en":"Archaeologists have uncovered an 11,700-year-old hunting camp in Alaska.","cn":"考古学家在阿拉斯加发现了一个距今11,700年的狩猎营地。"}},{"pos":"VERB 动词","cn":"揭开…的盖子；除去…上的覆盖物","en":"To uncover something means to remove something that is covering it.","ex":{"en":"When the seedlings sprout, uncover the tray.","cn":"秧苗发芽后，就把盘子上的盖子拿掉。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to find out information that has been deliberately kept secret, especially while you are studying or examining a particular subject","cn":""},{"en":"to find out information by searching carefully for it, especially information about someone's past that they have deliberately tried to keep secret","cn":""},{"en":"to find something out, especially the truth about a situation, or facts that someone has tried to hide","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/f/uncover0205.mp3","us":"media/ldoce/hwd/ame/6/uncover.mp3"},"examples":[{"en":"Police have uncovered a plot to kidnap the President's son.","cn":"警方发现了一起绑架总统之子的阴谋。"},{"en":"Uncover the pan and let the soup simmer.","cn":"揭开锅盖，让汤再慢火煨一下。"}],"oxford":{"phon":"ʌnˈkʌvə(r)","pos":"verb","senses":[{"en":"to remove something that is covering something","cn":"揭开盖子","ex":{"en":"Uncover the pan and let the soup simmer.","cn":"揭开锅盖，让汤再慢火煨一下。"}},{"en":"to discover something that was previously hidden or secret","cn":"发现；揭露；揭发","ex":{"en":"Police have uncovered a plot to kidnap the President's son.","cn":"警方发现了一个绑架总统之子的阴谋。"}}]}},"ubiquity":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"无所不在；随处可见","en":"If you talk about the ubiquity of something, you mean that it seems to be everywhere."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if something is common, there are a lot of them","cn":""},{"en":"happening in a lot of places or done by a lot of people","cn":""},{"en":"common in a particular place or time – used especially when saying that this seems surprising or unusual","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Ubiquity is the state of being everywhere all the time. Some ubiquity is real (the ubiquity of sadness at a funeral), and some only seems real (the ubiquity of cowboy boots in Texas)."}]},"media":{"uk":"media/ldoce/hwd/bre/2/ubiquitous0205.mp3","us":"media/ldoce/hwd/ame/c/ubiquitous.mp3"},"examples":[{"en":"the ubiquity of the mass media","cn":"大众传媒的无所不在"},{"en":"Coffee shops are ubiquitous these days.","cn":""}],"oxford":{"phon":"juːˈbɪkwəti","pos":"noun","senses":[{"en":"the fact that something seems to be everywhere or in several places at the same time; the fact that something is very common","cn":"似乎无所不在的；十分普遍的","ex":{"en":"the ubiquity of the mass media","cn":"大众媒体的无处不在"}}]}},"umpire":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（体育比赛或竞赛中的）裁判，裁判员","en":"An umpire is a person whose job is to make sure that a sports match or contest is played fairly and that the rules are not broken.","ex":{"en":"The umpire's decision is final.","cn":"裁判的裁定是不可更改的。"}},{"pos":"VERB 动词","cn":"在…中担任裁判","en":"To umpire means to be the umpire in a sports match or contest.","ex":{"en":"He umpired baseball games","cn":"他担任棒球比赛的裁判。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who makes sure that the rules of a sport are obeyed in soccer, American football, rugby, ice hockey, basketball, boxing, or wrestling","cn":""},{"en":"someone who makes sure that the rules are obeyed in baseball, cricket, tennis, or hockey","cn":""},{"en":"someone who decides the result of a competition or sporting contest","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/7/umpire_v0205.mp3","us":"media/ldoce/hwd/ame/e/umpire1.mp3"},"examples":[{"en":"We need someone to umpire.","cn":"我们得找个人当裁判。"},{"en":"to umpire a game of baseball","cn":"做棒球赛裁判"}],"oxford":{"phon":"ˈʌmpaɪə(r)","pos":"noun","senses":[{"en":"a person whose job is to watch a game and make sure that rules are not broken","cn":"裁判员","ex":{"en":"The umpire’s decision is final.","cn":"裁判的裁定是不可更改的。"}},{"en":"to act as an umpire","cn":"（为…）做裁判员，当裁判","ex":{"en":"We need someone to umpire.","cn":"我们得找个人当裁判。"},"pos":"verb"}]}},"unaffected":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"未受影响的；未被改变的","en":"If someone or something is unaffected by an event or occurrence, they are not changed by it in any way.","ex":{"en":"She seemed totally unaffected by what she'd drunk","cn":"她所喝的似乎对她没有丝毫影响。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不矫揉造作的；自然的；率真的","en":"If you describe someone as unaffected, you mean that they are natural and genuine in their behaviour, and do not act as though they are more important than other people.","ex":{"en":"...this unaffected, charming couple.","cn":"这对率真迷人的夫妇"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if someone or something hasn't changed , they are the same as they were before, even though you have not seen them for a long time","cn":""},{"en":"still the same, especially after a long period of time when there would usually have been a lot of changes","cn":""},{"en":"the same as before, and not changed or affected by something that has happened","cn":""}]},"vocab":{"pos":"1 adj 2 adj","senses":[{"en":"When bad weather or a mean aunt or some other force takes over and you still don't change, you're unaffected. If your party was unaffected by the rain and Aunt Emma's no-fun attitude, then everyone probably had a good time."}]},"collocations":{"phrases":["VERBS appear, be, seem | remain","ADV. altogether, completely, entirely, quite, totally, wholly | almost, virtually | largely | comparatively, relatively | apparently, seemin","PREP. by He appeared totally unaffected by this experience."]},"media":{"uk":"media/ldoce/hwd/bre/a/unaffected0205.mp3","us":"media/ldoce/hwd/ame/1/unaffected.mp3"},"examples":[{"en":"Some members of the family may remain unaffected by the disease.","cn":"这家族有些人可能不会受到这种疾病的影响。"},{"en":"People's rights are unaffected by the new law.","cn":"新法规没有影响人民的权利。"}],"oxford":{"phon":"ˌʌnəˈfektɪd","pos":"adjective","senses":[{"en":"not changed or influenced by something; not affected by something","cn":"未被改变的；未受影响的；无动于衷的","ex":{"en":"People's rights are unaffected by the new law.","cn":"新法规没有影响人民的权利。"}},{"en":"natural and sincere","cn":"真诚自然的；真挚的；不做作的","lab":"approving","ex":{"en":"She had a warm smile and an unaffected manner.","cn":"她笑容温暖，举止不做作。"}}]}},"unearthly":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"怪异的；非自然的","en":"You use unearthly to describe something that seems very strange and unnatural.","ex":{"en":"For a few seconds we watched the unearthly lights on the water","cn":"有那么几秒钟，我们注视着水面上那些奇异的光。"}},{"pos":"ADJ 形容词","cn":"过早的","en":"If you refer to a time as an unearthly hour, you are emphasizing that it is very early in the morning.","ex":{"en":"They arranged to meet in Riverside Park at the unearthly hour of seven in the morning.","cn":"他们约定一大清早7点在河滨公园见面。"}},{"pos":"ADJ 形容词","cn":"（声音）可怕的，恐怖的，怪异的","en":"An unearthly noise is unpleasant because it sounds frightening and unnatural.","ex":{"en":"She heard the sirens scream their unearthly wail.","cn":"她听到警报器发出可怕的尖叫声。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"very strange and unnatural, and probably frightening","cn":"奇异的﹐怪异的﹔可怕的"},{"en":"very early or very late and therefore extremely inconvenient","cn":"早[晚]得不合理的时间等"}]},"vocab":{"pos":"adj","senses":[{"en":"Unearthly describes something supernatural — a person or object that seems to come from another world. Unearthly beings are usually mysterious and can sometimes be scary, like the aliens you might see in a science fiction movie."}]},"media":{"uk":"media/ldoce/hwd/bre/6/unearthly0205.mp3","us":"media/ldoce/hwd/ame/c/unearthly.mp3"},"examples":[{"en":"The job involved getting up at some unearthly hour to catch the first train.","cn":"这工作需要起大早赶头班火车。"},{"en":"an unearthly cry","cn":"令人毛骨悚然的喊声"}],"oxford":{"phon":"ʌnˈɜːθli","pos":"adjective","senses":[{"en":"very strange; not natural and therefore frightening","cn":"怪异的；异常的；非自然的；恐怖的","ex":{"en":"an unearthly cry","cn":"令人毛骨悚然的喊声"}}]}},"understandable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（行为、情绪等）可以理解的，正常的，合情理的","en":"If you describe someone's behaviour or feelings as understandable, you think that they have reacted to a situation in a natural way or in the way you would expect.","ex":{"en":"His unhappiness was understandable.","cn":"他不高兴是可以理解的。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（论述、理论等）容易理解的","en":"If you say that something such as a statement or theory is understandable, you mean that people can easily understand it.","ex":{"en":"Roger Neuberg writes in a simple and understandable way.","cn":"罗杰·纽伯格的文章简明易懂。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"to understand how someone feels, and feel sympathy for them, especially when they are upset or have problems","cn":""},{"en":"to understand how someone feels and why they feel that way, especially because the reasons are very clear","cn":""},{"en":"to understand clearly how someone feels or what problems they have","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Something understandable can be understood or grasped. It makes sense."}]},"collocations":{"phrases":["VERBS be, seem | become","ADV. very | completely, entirely, perfectly, quite, wholly | fairly 2 easy to understand","VERBS be, seem","ADV. easily, readily Warning notices must be readily understandable.","PREP. to The instructions must be understandable to the average user."]},"media":{"uk":"media/ldoce/hwd/bre/3/understandable0205.mp3","us":"media/ldoce/hwd/ame/d/understandable.mp3"},"examples":[{"en":"Their attitude is perfectly understandable.","cn":"他们的态度是完全可以理解的。"},{"en":"It was an understandable mistake to make.","cn":"那是一个情有可原的失误。"}],"oxford":{"phon":"ˌʌndəˈstændəbl","pos":"adjective","senses":[{"en":"seeming normal and reasonable in a particular situation","cn":"合情理的；正常的；可以理解的","ex":{"en":"Their attitude is perfectly understandable.","cn":"他们的态度是完全可以理解的。"}},{"en":"easy to understand","cn":"容易理解的；易懂的","ex":{"en":"Warning notices must be readily understandable.","cn":"警示性公告必须明白易懂。"}}]}},"uninformed":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"未被告知（或通知）的；知识（或信息）贫乏的","en":"If you describe someone as uninformed, you mean that they have very little knowledge or information about a particular situation or subject.","ex":{"en":"He could not complain that he was uninformed about the true nature of the regime","cn":"他不能抱怨说没人告诉他该政权的实质。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who is ignorant does not know facts or information that they should know","cn":""},{"en":"when someone does not know facts or information that they should know","cn":""},{"en":"people or opinions that are uninformed show a lack of knowledge and information about the subject that they are discussing","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41uninformed.mp3","us":"media/ldoce/hwd/ame/8/uninformed.mp3"},"examples":[{"en":"The public is generally uninformed about these diseases.","cn":"大众对这些疾病普遍知之甚少。"},{"en":"an uninformed comment/criticism","cn":"无知的话语/批评"}],"oxford":{"phon":"ˌʌnɪnˈfɔːmd","pos":"adjective","senses":[{"en":"having or showing a lack of knowledge or information about something","cn":"知识（或信息）贫乏的；蒙昧的；无知的","ex":{"en":"an uninformed comment/criticism","cn":"无知的话语／批评"}}]}},"untrustworthy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不可信的；不可靠的","en":"If you say that someone is untrustworthy, you think they are unreliable and cannot be trusted.","ex":{"en":"I think he is shallow, vain and untrustworthy","cn":"我觉得他为人浅薄，好虚荣，靠不住。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who is untrustworthy cannot be trusted","cn":"不能信赖的﹐不值得信任的"}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41untrustworthy.mp3","us":"media/ldoce/hwd/ame/8/laaduntrustworthy.mp3"},"oxford":{"phon":"ʌnˈtrʌstwɜːði","pos":"adjective","senses":[{"en":"that cannot be trusted","cn":"不可靠的；不能信赖（或信任）的"}]}},"unblemished":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"没有污点的；无瑕疵的；清白的","en":"If you describe something such as someone's record, reputation, or character as unblemished, you mean it has not been harmed or spoiled.","ex":{"en":"Ghana does not have an unblemished record on human rights.","cn":"加纳在人权方面并非毫无瑕疵。"}},{"pos":"ADJ 形容词","cn":"无斑痕的；无瑕疵的；完好无损的","en":"If you describe something as unblemished, you mean that it has no marks or holes on its surface.","ex":{"en":"Be sure to select firm, unblemished fruit.","cn":"一定要选坚实、无疤痕的果子。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone or something that is perfect is good in every way and could not be any better","cn":""},{"en":"completely perfect, with no mistakes or faults at all","cn":""},{"en":"someone who has all the qualities that a husband, wife, student etc should have","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41unblemished.mp3","us":"media/ldoce/hwd/ame/e/unblemished.mp3"},"examples":[{"en":"He had an unblemished reputation.","cn":"他的名声白璧无瑕。"},{"en":"her pale unblemished skin","cn":"她那白皙光洁的皮肤"}],"oxford":{"phon":"ʌnˈblemɪʃt","pos":"adjective","senses":[{"en":"not spoiled, damaged or marked in any way","cn":"完好的；无损的；无污点的","ex":{"en":"He had an unblemished reputation.","cn":"他的名声白璧无瑕。"}}]}},"unforgivable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不可原谅的；十恶不赦的","en":"If you say that something is unforgivable, you mean that it is very bad, cruel, or socially unacceptable.","ex":{"en":"These people are animals and what they did was unforgivable","cn":"这些人是禽兽，他们所做的一切都是不可原谅的。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"behaviour that is unforgivable is so bad that you cannot forgive it","cn":""},{"en":"an action or situation that is inexcusable cannot be excused and someone must be blamed for it, because there is no good reason for it","cn":""},{"en":"an unforgivable action is so bad or cruel that you cannot forgive the person who did it 〔","cn":"行为〕不可原谅的﹐不可饶恕的"}]},"media":{"uk":"media/ldoce/hwd/bre/0/unforgivable0205.mp3","us":"media/ldoce/hwd/ame/4/laadunforgivable.mp3"},"examples":[{"en":"Patrick had deceived her, and that was unforgivable.","cn":"帕特里克欺骗了她﹐那是不可原谅的。"},{"en":"the unforgivable sin of informing on your friends","cn":"出卖朋友这种不可饶恕的恶行"}],"oxford":{"phon":"ˌʌnfəˈɡɪvəbl","pos":"adjective","senses":[{"en":"if somebody’s behaviour is unforgivable, it is so bad or unacceptable that you cannot forgive the person","cn":"不可原谅的；难以饶恕的","ex":{"en":"It was an unforgivable thing to say.","cn":"那么说真是不可原谅。"}}]}},"unpretentious":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"简洁的；朴素的","en":"If you describe a place, person, or thing as unpretentious, you approve of them because they are simple in appearance or character, rather than sophisticated or luxurious.","ex":{"en":"The Tides Inn is both comfortable and unpretentious.","cn":"泰得斯小酒店舒适而又简洁。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not wanting to talk about your abilities or achievements and to say that you are good at something, even when you are – used to show approval","cn":""},{"en":"not wanting to talk about yourself or to attract attention","cn":""},{"en":"not wanting to be noticed and not expecting to be treated in a special way","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"The adjective unpretentious is perfect for describing someone you know who's modest and natural and never tries to impress other people."}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41unpretentious.mp3","us":"media/ldoce/hwd/ame/d/unpretentious.mp3"},"examples":[{"en":"an unpretentious hotel","cn":"简朴的酒店"},{"en":"an unpretentious woman","cn":"行事低调的女子"}],"oxford":{"phon":"ˌʌnprɪˈtenʃəs","pos":"adjective","senses":[{"en":"not trying to appear more special, intelligent, important, etc. than you really are/it really is","cn":"谦虚谨慎的；不事张扬的；不爱炫耀的","ex":{"en":"He was a friendly and unpretentious man.","cn":"他是一个友善而朴实的人。"}}]}},"unrelieved":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未减轻的；未得缓解的","en":"If you describe something unpleasant as unrelieved, you mean that it is very severe and is not replaced by anything better, even for a short time.","ex":{"en":"...unrelieved misery","cn":"难以释怀的悲痛"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"an unpleasant situation that is unrelieved continues for a long time because nothing happens to change it 〔","cn":"讨厌的情况〕未减轻的﹐未解除的﹐无变化的"}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41unrelieved.mp3","us":"media/ldoce/hwd/ame/7/unrelieved.mp3"},"examples":[{"en":"unrelieved pain","cn":"毫无缓解的疼痛"}],"oxford":{"phon":"ˌʌnrɪˈliːvd","pos":"adjective","senses":[{"en":"continuing without changing","cn":"持续不变的；未缓和的"}]}},"uprising":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"起义;暴动","en":"When there is an uprising, a group of people start fighting against the people who are in power in their country, because they want to bring about a political change.","ex":{"en":"...a popular uprising against the authoritarian government","cn":"反对独裁政府的群众暴动"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an attempt by a large group of people at revolution","cn":""},{"en":"an occasion when a group of people, especially soldiers, suddenly take control of a country","cn":""},{"en":"an organized attempt to change the government or other authority, often by using violence","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"An organized rebellion, especially against an authority or government — is an uprising . If your entire math class joined together in rebellion against your teacher's unfair grading practices, you could call it an uprising ."}]},"collocations":{"phrases":["ADJ. successful | failed the failed uprising of 1830 | armed | revolutionary | mass, national, popular | military | peasant | spontaneous","VERB + UPRISING provoke, spark (off) | stage | crush, put down, quell, suppress","PREP. during/in the ~ He was killed in the Warsaw uprising. | ~ against the 1951 uprising against colonial rule"]},"media":{"uk":"media/ldoce/hwd/bre/4/uprising0205.mp3","us":"media/ldoce/hwd/ame/b/uprising.mp3"},"examples":[{"en":"an armed uprising against the government","cn":"反政府的武装起义"},{"en":"a popular uprising (= by the ordinary people of the country)","cn":"平民暴动"}],"oxford":{"phon":"ˈʌpraɪzɪŋ","pos":"noun","senses":[{"en":"a situation in which a group of people join together in order to fight against the people who are in power","cn":"起义；暴动；造反","ex":{"en":"He led an armed uprising against the government.","cn":"他领导了一场反对政府的武装起义。"}}]}},"unfinished":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（作品等）未完成的","en":"If you describe something such as a work of art or a piece of work as unfinished, you mean that it is not complete, for example because it was abandoned or there was no time to complete it.","ex":{"en":"...Jane Austen's unfinished novel","cn":"简·奥斯汀未完成的小说"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not finished, because not all of the work has been done on something, or because it does not have all the parts that it should have","cn":""},{"en":"if something is not over yet , especially something difficult or unpleasant, it is not finished and still needs to be done or dealt with","cn":""},{"en":"not completed","cn":"未竟的﹐未完成的"}]},"media":{"uk":"media/ldoce/hwd/bre/c/unfinished0205.mp3","us":"media/ldoce/hwd/ame/a/laadunfinished.mp3"},"examples":[{"en":"We have some unfinished business to settle.","cn":"我们还有些没做完的事要处理。"},{"en":"Rachael left her meal unfinished.","cn":"雷切尔的饭剩下了。"}],"oxford":{"phon":"ʌnˈfɪnɪʃt","pos":"adjective","senses":[{"en":"not complete; not finished","cn":"未做完的；未完成的","ex":{"en":"We have some unfinished business to settle.","cn":"我们还有些没做完的事要处理。"}}]}},"unseeded":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（选手）非种子的，没进前16强的","en":"In tennis and badminton competitions, an unseeded player is someone who has not been ranked among the top 16 players by the competition's organizers.","ex":{"en":"He was understandably dejected after losing in the first round to an unseeded American.","cn":"第一轮就输给了一位美国的非种子选手，他的沮丧是可以理解的。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not chosen as a seed (= someone with a numbered rank in a competition ) , especially in a tennis competition 〔","cn":"尤指网球比赛中〕非种子的，未被列为种子选手的"}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41unseeded.mp3","us":"media/ldoce/hwd/ame/8/unseeded.mp3"},"examples":[{"en":"unseeded players","cn":"非种子选手"}],"oxford":{"phon":"ʌnˈsiːdɪd","pos":"adjective","senses":[{"en":"not chosen as a seed (= one of the players expected to do well) in a sports competition, especially in tennis","cn":"未被列为种子选手的；（尤指网球运动员）非种子的","ex":{"en":"unseeded players","cn":"非种子选手"}}]}},"unimpaired":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"完好无损的；未削弱的","en":"If something is unimpaired after something bad or unpleasant has happened to it, it is not damaged or made worse.","ex":{"en":"His health and vigour were unimpaired by a stroke","cn":"他的健康和精力在经历了一次中风后没有受到影响。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not damaged or made weak","cn":"未受损的﹔未削弱的"}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41unimpaired.mp3","us":"media/ldoce/hwd/ame/6/laadunimpaired.mp3"},"examples":[{"en":"Although he's ninety, his mental faculties remain unimpaired.","cn":"他虽年届九旬，但头脑仍然清晰。"}],"oxford":{"phon":"ˌʌnɪmˈpeəd","pos":"adjective","senses":[{"en":"not damaged or made less good","cn":"未被损坏的；未毁坏的","ex":{"en":"Although he's ninety, his mental faculties remain unimpaired.","cn":"他虽年届九旬，但头脑仍然清晰。"}}]}},"u-turn":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"U型转弯；180度转弯；掉头","en":"If you make a U-turn when you are driving or cycling, you turn in a half circle in one movement, so that you are then going in the opposite direction.","ex":{"en":"Making a sharp U-turn, she headed back","cn":"她猛地掉转车头，往回开。"}},{"pos":"N-COUNT 可数名词","cn":"（政治家在政策、计划、行动方面的）180度大转弯，彻底转变","en":"If you describe a change in a politician's policy, plans, or actions as a U-turn, you mean that it is a complete change and that they made the change because they were weak or were wrong.","ex":{"en":"...a humiliating U-turn by the Prime Minister.","cn":"首相极不光彩的180度大转变"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a change in which something or someone becomes completely different","cn":""},{"en":"a complete change in ways of thinking or working","cn":""},{"en":"a situation in which a lot of changes are very quickly made in a system or organization in order to make it more effective","cn":""}]},"collocations":{"phrases":["ADJ. complete | dramatic, spectacular | embarrassing, humiliating | government, policy VERB + U-TURN do, execute, make, perform The governme","PREP. ~ on a U-turn on education policy | ~ over a government U-turn over plans to cut social security payments"]},"media":{"uk":"media/ldoce/hwd/bre/5/u_turn0205.mp3","us":"media/ldoce/hwd/ame/d/u-turn.mp3"},"examples":[{"en":"to do/make a U-turn","cn":"作 180 度转弯"},{"en":"He made a quick U-turn and sped away.","cn":"他迅速掉了个头﹐飞快地开走了。"}],"oxford":{"phon":"ˈjuː tɜːn","pos":"noun","senses":[{"en":"a turn of 180° that a vehicle makes so that it can move forwards in the opposite direction","cn":"（汽车等的）U 形转弯，180 度转弯","ex":{"en":"to do/make a U-turn","cn":"掉头"}},{"en":"a complete change in policy or behaviour, usually one that is embarrassing","cn":"（政策、行为上令人尴尬的）彻底转变，180 度大转变","lab":"informal","ex":{"en":"The government has made a spectacular U-turn on taxes.","cn":"政府在税收方面作出重大调整。"}}]}},"unbearable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不堪忍受的；无法容忍的；难以承受的","en":"If you describe something as unbearable, you mean that it is so unpleasant, painful, or upsetting that you feel unable to accept it or deal with it.","ex":{"en":"War has made life almost unbearable for the civilians remaining in the capital","cn":"对留在首都的平民来说，战争已使生活变得几乎不堪忍受。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"to be unable to accept an unpleasant situation","cn":""},{"en":"to be unable to accept an unpleasant situation without becoming angry or upset, especially when someone's behaviour is not fair or reasonable","cn":""},{"en":"to be unable to stand something because thinking about it makes you feel sick or angry","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"When something's unbearable , you just can't take it. Your neighbor's loud music was always annoying, but when the walls shook until your favorite vase fell and broke you knew it had become unbearable ."}]},"collocations":{"phrases":["VERBS be, feel, seem | become, get | make sb/sth His arrogance made him absolutely unbearable! | find sb/sth They found the heat unbearable.","ADV. absolutely, quite | almost"]},"media":{"uk":"media/ldoce/hwd/bre/b/unbearable0205.mp3","us":"media/ldoce/hwd/ame/f/unbearable.mp3"},"examples":[{"en":"He's been unbearable since he won that prize.","cn":"他得奖以后变得很难相与。"},{"en":"The heat was becoming unbearable.","cn":"炎热开始变得难以忍受。"}],"oxford":{"phon":"ʌnˈbeərəbl","pos":"adjective","senses":[{"en":"too painful, annoying or unpleasant to deal with or accept","cn":"难耐的；无法接受的；难以处理的","ex":{"en":"The heat was becoming unbearable.","cn":"炎热开始变得难以忍受。"}}]}},"uncharacteristic":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不典型的；不代表…的特征的；反常的","en":"If you describe something as uncharacteristic of someone, you mean that it is not typical of them.","ex":{"en":"It was uncharacteristic of her father to disappear like this.","cn":"就这样消失不像她父亲的一贯作风。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"belonging to a type or group, but not having the usual qualities of that type or group","cn":""},{"en":"not typical of a situation or of someone's character, and therefore surprising","cn":""},{"en":"if you say it is not like someone or is unlike them to do something, you mean it is not typical of them to behave in that way, and it is strange or surprising","cn":""}]},"collocations":{"phrases":["VERBS be, seem","ADV. very | quite, totally | rather","PREP. of The houses were totally uncharacteristic of the area."]},"media":{"uk":"media/ldoce/hwd/bre/0/brelasdeuncharacteristic.mp3","us":"media/ldoce/hwd/ame/6/laaduncharacteristic.mp3"},"examples":[{"en":"The children had been uncharacteristically quiet.","cn":"孩子们显得异样的安静。"},{"en":"The remark was quite uncharacteristic of her.","cn":"这话很不像是她说的。"}],"oxford":{"phon":"ˌʌnˌkærəktəˈrɪstɪk","pos":"adjective","senses":[{"en":"not typical of somebody; not the way somebody usually behaves","cn":"（指人的行为）非典型的；非通常的；表现奇怪的","ex":{"en":"The remark was quite uncharacteristic of her.","cn":"这话很不像是她说的。"}}]}},"undone":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未做的；未完成的","en":"Work that is undone has not yet been done.","ex":{"en":"He left nothing undone that needed attention.","cn":"所有需要注意的事他都注意到了。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not fastened","cn":"未系好的﹐未扣上的"},{"en":"not finished","cn":"未完成的"},{"en":"destroyed and without hope","cn":"毁掉的﹔完蛋了的"}]},"collocations":{"phrases":["VERBS be | come My button's come undone again. | get sth I can't get this knot undone. 2 not done","VERBS be | remain | leave sth We left the washing-up undone and went out for the day."]},"media":{"uk":"media/ldoce/hwd/bre/3/undone0205.mp3","us":"media/ldoce/hwd/ame/d/undone.mp3"},"examples":[{"en":"Most of the work had been left undone.","cn":"大部分工作还没有做完。"},{"en":"Her blouse had come undone.","cn":"她的衬衫扣松开了。"}],"oxford":{"phon":"ʌnˈdʌn","pos":"adjective","senses":[{"en":"not fastened or tied","cn":"未扣；未系；松开","ex":{"en":"Her blouse had come undone.","cn":"她的衬衫扣松开了。"}},{"en":"not finished","cn":"未完成；未竟","ex":{"en":"Most of the work had been left undone.","cn":"大部分工作还没有做完。"}},{"en":"defeated and without any hope for the future","cn":"完蛋；一蹶不振；无出头之日","lab":"old use"}]}},"unbecoming":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不好看的；不吸引人的","en":"If you describe things such as clothes as unbecoming, you mean that they look unattractive.","ex":{"en":"...the unbecoming dress hurriedly stitched from cheap cloth.","cn":"用廉价布料匆匆缝制的难看的连衣裙"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不得体的；不合宜的；不恰当的","en":"If you describe a person's behaviour or remarks as unbecoming, you mean that they are shocking and unsuitable for that person.","ex":{"en":"His conduct was totally unbecoming to an officer in the British armed services","cn":"作为一名英军军官，他的行为极不得体。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"clothes that are unbecoming make you look unattractive 〔","cn":"衣服〕不相配的，不合身的，难看的"},{"en":"behaviour that is unbecoming is shocking or unsuitable 〔","cn":"行为〕过分的，不合适的﹐不得体的"}]},"vocab":{"pos":"adj","senses":[{"en":"Use the adjective unbecoming when a person does something that's awkward or inappropriate, like using foul language at your grandmother's tea party."}]},"media":{"uk":"media/ldoce/hwd/bre/0/unbecoming0205.mp3","us":"media/ldoce/hwd/ame/7/laadunbecoming.mp3"},"examples":[{"en":"She was wearing an unbecoming shade of purple.","cn":"她穿着一身不相配的紫色衣服。"},{"en":"He was accused of conduct unbecoming to an officer.","cn":"他被谴责行为有失官员身分。"}],"oxford":{"phon":"ˌʌnbɪˈkʌmɪŋ","pos":"adjective","senses":[{"en":"not suiting a particular person","cn":"不合适的；不相称的","ex":{"en":"She was wearing an unbecoming shade of purple.","cn":"她穿着一身深浅不相配的紫色衣服。"}},{"en":"not appropriate or acceptable","cn":"不恰当；不得体；不可接受","ex":{"en":"He was accused of conduct unbecoming to an officer.","cn":"他被谴责行为有失官员身份。"}}]}},"ulterior":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（动机等）隐蔽的，隐秘的，隐藏的","en":"If you say that someone has an ulterior motive for doing something, you believe that they have a hidden reason for doing it.","ex":{"en":"Sheila had an ulterior motive for trying to help Stan","cn":"希拉想帮助斯坦是另有所图的。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"to have a reason for doing something - used especially when you do not want to say what that reason is","cn":""},{"en":"to be the reasons why someone does something, especially when you know they have a reason but do not know what it is","cn":""},{"en":"to do something for a secret reason when everyone thinks you are doing it for a different reason","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"An ulterior interest, argument, or revelation is one you try to keep hidden, like your ulterior motive for weeding your grandmother's garden is to have a conversation with your crush — and Grandma's neighbor — who happens to be outside, too."}]},"media":{"uk":"media/ldoce/hwd/bre/6/ulterior0205.mp3","us":"media/ldoce/hwd/ame/a/ulterior.mp3"},"examples":[{"en":"She must have some ulterior motive for being nice to me — what does she really want?","cn":"她对我这么好，一定别有用心。她到底想干什么呢？"},{"en":"He’s just being nice. I don’t think he has any ulterior motives .","cn":"他只是出于好心﹐我不认为他别有目的。"}],"oxford":{"phon":"ʌlˈtɪəriə(r)","pos":"adjective","senses":[{"en":"that somebody keeps hidden and does not admit","cn":"隐秘的；不可告人的；秘密的；矢口否认的","ex":{"en":"She must have some ulterior motive for being nice to me—what does she really want?","cn":"她对我这么好，一定别有用心。她到底想干什么呢？"}}]}},"untouched":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"不受影响的","en":"Something that is untouched by something else is not affected by it.","ex":{"en":"Asian airlines remain untouched by the deregulation that has swept America","cn":"亚洲航空公司并未受到席卷美国的撤销管制浪潮的影响。"}},{"pos":"ADJ 形容词","cn":"完好无缺的；未受损害的","en":"If something is untouched, it is not damaged in any way, although it has been in a situation where it could easily have been damaged.","ex":{"en":"Michael pointed out to me that amongst the rubble, there was one building that remained untouched","cn":"迈克尔指给我看说，瓦砾中有一栋建筑完好无损。"}},{"pos":"ADJ 形容词","cn":"世外桃源般的；不染尘嚣的；天然质朴的","en":"An untouched area or place is thought to be beautiful because it is still in its original state and has not been changed or damaged in any way.","ex":{"en":"Ducie is one of the world's last untouched islands, nearly 5,000km from Australia.","cn":"迪西岛是当今世上仅存的几个不染尘嚣的岛屿之一，距澳大利亚近5,000公里。"}},{"pos":"ADJ 形容词","cn":"未吃过（或喝过）的；未动过的","en":"If food or drink is untouched, none of it has been eaten or drunk.","ex":{"en":"The coffee was untouched, the toast had cooled","cn":"咖啡没有动过，吐司已经凉了。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"existing in nature and not caused, made, or controlled by people","cn":""},{"en":"used about flowers, plants, and animals that are not controlled by people. Also used about areas of land where there are no humans","cn":""},{"en":"used about food, drink, or materials that have not had anything added to them","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/1/brelasdeuntouched.mp3","us":"media/ldoce/hwd/ame/4/laaduntouched.mp3"},"examples":[{"en":"The area has remained relatively untouched by commercial development.","cn":"相对而言，这个地区至今没有受到商业开发的影响。"},{"en":"The final clause in the contract will be left untouched.","cn":"合同的最后一项条款将不作改动。"}],"oxford":{"phon":"ʌnˈtʌtʃt","pos":"adjective","senses":[{"en":"not affected by something, especially something bad or unpleasant; not damaged","cn":"未受影响；未被损害；原封未动","ex":{"en":"The area has remained relatively untouched by commercial development.","cn":"相对而言，这个地区至今没怎么受到商业开发的影响。"}},{"en":"not eaten or drunk","cn":"未食用（或饮用）；未动","ex":{"en":"She left her meal untouched.","cn":"她的饭连动都没动。"}},{"en":"not changed in any way","cn":"未改变；未修改","ex":{"en":"The final clause in the contract will be left untouched.","cn":"合同的最后一项条款将不作改动。"}}]}},"unalterable":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not possible to change","cn":"不可变更[改变]的"}]},"vocab":{"pos":"adj","senses":[{"en":"You take your dress to the tailor to be altered. He tells you he can't alter it. The dress is unalterable . Something unalterable cannot be changed."}]},"media":{"uk":"media/ldoce/hwd/bre/6/unalterable0205.mp3","us":"media/ldoce/hwd/ame/6/laadunalterable.mp3"},"examples":[{"en":"the unalterable laws of the universe","cn":"不可改变的宇宙法则"},{"en":"an unalterable fact","cn":"不可改变的事实"}],"oxford":{"phon":"ʌnˈɔːltərəbl","pos":"adjective","senses":[{"en":"that cannot be changed","cn":"无法改变的；不可更改的","ex":{"en":"the unalterable laws of the universe","cn":"不可改变的宇宙法则"}}]}},"unavoidable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不可避免的；无法阻止的","en":"If something is unavoidable, it cannot be avoided or prevented.","ex":{"en":"Managers said the job losses were unavoidable","cn":"经理们说裁员是不可避免的。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"impossible to prevent","cn":"不可避免的"}]},"vocab":{"pos":"adj","senses":[{"en":"Use the adjective unavoidable to describe something that you can't escape or avoid. Going to your family reunion is unavoidable if there's no way for you to get out of it."}]},"collocations":{"phrases":["VERBS be, prove, seem | become | make sth This latest incident makes his dismissal unavoidable.","ADV. absolutely, quite, totally, utterly | almost"]},"media":{"uk":"media/ldoce/hwd/bre/4/unavoidable0205.mp3","us":"media/ldoce/hwd/ame/e/unavoidable.mp3"},"examples":[{"en":"I was unavoidably delayed.","cn":"我无奈被耽搁了。"},{"en":"unavoidable delays","cn":"不可避免的延误"}],"oxford":{"phon":"ˌʌnəˈvɔɪdəbl","pos":"adjective","senses":[{"en":"impossible to avoid or prevent","cn":"无法避免的；难以预防的","ex":{"en":"unavoidable delays","cn":"不可避免的延误"}}]}},"unarguable":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"不容争论的；不容置疑的","en":"If you describe a statement or opinion as unarguable, you think that it is obviously true or correct and that nobody could disagree with it.","ex":{"en":"He is making the unarguable point that our desires and preferences have a social component.","cn":"他要表述一个无可争议的观点：我们的欲望和喜好都掺杂着社会因素。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"something that is unarguable is definitely true or correct","cn":"不容置疑的，无可争辩的"}]},"media":{"uk":"media/ldoce/hwd/bre/b/unarguable0205.mp3","us":"media/ldoce/hwd/ame/a/ld41unarguable.mp3"},"examples":[{"en":"She is unarguably one of the country's finest athletes.","cn":"她无疑是全国最优秀的运动员之一。"},{"en":"unarguable proof","cn":"不容置疑的证据"}],"oxford":{"phon":"ʌnˈɑːɡjuəbl","pos":"adjective","senses":[{"en":"that nobody can disagree with","cn":"无可争辩的；不容置疑的","ex":{"en":"unarguable proof","cn":"不容置疑的证据"}}]}},"unseemly":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不合适的；不得体的","en":"If you say that some-one's behaviour is unseemly, you disapprove of it because it is not polite or not suitable for a particular situation or occasion.","ex":{"en":"It would be unseemly for judges to receive pay increases when others are having to tighten their belts.","cn":"在其他人正不得不勒紧裤腰带的时候，给法官提高薪水是不合适的。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"unseemly behaviour is not polite or not suitable for a particular occasion 〔","cn":"行为〕不体面的﹐不合礼节的﹐不得体的"}]},"vocab":{"pos":"adj","senses":[{"en":"Something that is inappropriate or unacceptable behavior is unseemly . It's a gentler, somewhat nicer word for \"inappropriate\" than its synonyms, the \"in\" words: \"indecent, indecorous, indelicate, inelegant, inept\" — well, you get the idea."}]},"media":{"uk":"media/ldoce/hwd/bre/b/unseemly0205.mp3","us":"media/ldoce/hwd/ame/d/unseemly.mp3"},"examples":[{"en":"Ann thought it unseemly to kiss her husband in public.","cn":"安认为当众亲吻丈夫不太得体。"}],"oxford":{"phon":"ʌnˈsiːmli","pos":"adjective","senses":[{"en":"not polite or suitable for a particular situation","cn":"不礼貌的；不得体的；不相宜的","ex":{"en":"There followed an unseemly rush for the exits.","cn":"接着大家一窝蜂地冲向出口。"}}]}},"unseen":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未被看到的；被忽略的","en":"If you describe something as unseen, you mean that it has not been seen for a long time.","ex":{"en":"...a spectacular ballroom, unseen by the public for over 30 years","cn":"公众30多年来未曾见过的豪华舞厅"}},{"pos":"ADJ 形容词","cn":"看不见的；无形的","en":"You can use unseen to describe things which people cannot see.","ex":{"en":"For me, a performance is in front of a microphone, over the radio, to an unseen audience","cn":"对我来说，表演就是在麦克风前通过无线电波面对看不见的听众进行的。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"to not notice something because it is difficult to see","cn":""},{"en":"to not notice something because you have not been careful enough","cn":""},{"en":"to not notice something, especially when this could have a serious result","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/1/unseen_adj0205.mp3","us":"media/ldoce/hwd/ame/8/laadunseen.mp3"},"examples":[{"en":"He was killed by a single shot from an unseen soldier.","cn":"一个埋伏的士兵一枪就把他打死了。"},{"en":"The exam consists of an essay and an unseen translation.","cn":"考试包括一篇作文和一篇即席翻译。"}],"oxford":{"phon":"ˌʌnˈsiːn","pos":"adjective","senses":[{"en":"that cannot be seen; that is not seen","cn":"看不见的；隐形的","ex":{"en":"unseen forces","cn":"无形的力量"}},{"en":"not previously seen","cn":"前所未见的；未被发现的","ex":{"en":"unseen dangers","cn":"未预见的危险"}}]}},"unconcerned":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"漠不关心的；淡漠的；不在意的","en":"If a person is unconcerned about something, usually something that most people would care about, they are not interested in it or worried about it.","ex":{"en":"Paul was unconcerned about what he had done","cn":"保罗对自己的所作所为毫不在意。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not worried or not caring about something, especially when you would normally expect someone to care","cn":""},{"en":"not seeming to care about what is happening, especially about other people's problems or feelings","cn":""},{"en":"not interested in anything or not caring about anything, and not making any effort to change or improve things","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"If you're unconcerned , you don't care — you're just not that interested. It's not ideal for the principal of a high school to be unconcerned about bullying."}]},"collocations":{"phrases":["VERBS act, appear, be, look, seem, sound I tried to act unconcerned.","ADV. very | completely, quite, totally | relatively | apparently, seemingly","PREP. about They appeared completely unconcerned about what they had done. | by He was apparently unconcerned by his failure to gain a unive"]},"media":{"uk":"media/ldoce/hwd/bre/1/brelasdeunconcerned.mp3","us":"media/ldoce/hwd/ame/c/unconcerned.mp3"},"examples":[{"en":"He drove on, apparently unconcerned about the noise the engine was making.","cn":"他继续驾车前进，对发动机发出的噪声显然毫不在意。"},{"en":"Young people are often unconcerned with political issues.","cn":"青年人对政治问题往往漠不关心。"}],"oxford":{"phon":"ˌʌnkənˈsɜːnd","pos":"adjective","senses":[{"en":"not worried or anxious about something because you feel it does not affect you or is not important","cn":"冷淡的；漠视的；漫不经心的","ex":{"en":"He drove on, apparently unconcerned about the noise the engine was making.","cn":"他继续驾车前进，对发动机发出的噪声显然毫不在意。"}},{"en":"not interested in something","cn":"不关心的；无兴趣的","ex":{"en":"Young people are often unconcerned with political issues.","cn":"青年人对政治问题往往漠不关心。"}}]}},"underclothes":{"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"内衣","en":"Your underclothes are the items of clothing that you wear next to your skin and under your other clothes.","ex":{"en":"...from multi-patterned sweaters to attractive underclothes.","cn":"从各式各样的毛线衫到性感迷人的内衣"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"clothes that you wear next to your body under your other clothes","cn":"内衣"}]},"media":{"uk":"media/ldoce/hwd/bre/a/underclothes0205.mp3","us":"media/ldoce/hwd/ame/d/underclothes.mp3"},"oxford":{"phon":"ˈʌndəkləʊðz","pos":"noun","senses":[{"en":"underwear (= clothes that you wear under other clothes and next to the skin)","cn":"内衣；衬衣"}]}},"universally":{"collins":{"senses":[{"pos":"ADV 副词","cn":"普遍地;全体地;人人","en":"If something is universally believed or accepted, it is believed or accepted by everyone with no disagreement.","ex":{"en":"...a universally accepted point of view","cn":"普遍接受的观点"}},{"pos":"ADV 副词","cn":"到处；在所有情况下；无一例外地","en":"If something is universally true, it is true everywhere in the world or in all situations.","ex":{"en":"The disadvantage is that it is not universally available","cn":"缺点在于它并不是随处都可获得。"}}]},"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"by everyone in the world or everyone in a particular group","cn":"全世界地，全体地"},{"en":"in every situation","cn":"广泛，普遍"}]},"vocab":{"pos":"adv","senses":[{"en":"Use the adverb universally to emphasize that something is done — or felt, or believed — in every single case."}]},"media":{"uk":"media/ldoce/hwd/bre/f/ldoce6universally.mp3","us":"media/ldoce/hwd/ame/9/universally_adv.mp3"},"examples":[{"en":"The theory does not apply universally.","cn":"这个理论并非放之四海而皆准。"},{"en":"This treatment is not universally available.","cn":"这种疗法不是到处都有的。"}],"oxford":{"phon":"ˌjuːnɪˈvɜːsəli","pos":"adverb","senses":[{"en":"by everyone","cn":"全体地；一致地；共同地","ex":{"en":"to be universally accepted","cn":"得到普遍接受"}},{"en":"everywhere or in every situation","cn":"到处；随时随地；在各种情况下","ex":{"en":"This treatment is not universally available.","cn":"这种疗法不是到处都有的。"}}]}},"untiring":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"孜孜不倦的；不懈的","en":"If you describe a person or their efforts as untiring, you approve of them because they continue what they are doing without slowing down or stopping.","ex":{"en":"...an untiring fighter for justice, democracy and tolerance.","cn":"为公正、民主和宽容奋斗不息的斗士"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"working very hard for a long period of time in order to do something – used to show approval","cn":"不倦的﹔坚持不懈的〔含褒义〕"}]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41untiring.mp3","us":"media/ldoce/hwd/ame/a/untiring.mp3"},"examples":[{"en":"untiring efforts to help the homeless","cn":"帮助无家可归者的不懈努力"}],"oxford":{"phon":"ʌnˈtaɪərɪŋ","pos":"adjective","senses":[{"en":"continuing to do something for a long period of time with a lot of effort and/or enthusiasm","cn":"不知疲劳的；孜孜不倦的；坚持不懈的","ex":{"en":"an untiring campaigner for human rights","cn":"孜孜不倦的人权活动家"}}]}},"underside":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"底面；下面；下侧","en":"The underside of something is the part of it which normally faces towards the ground.","ex":{"en":"...the underside of the car.","cn":"车的底部"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the bottom surface on the outside of something large","cn":""},{"en":"the bottom side or surface of something (","cn":"某物的)下侧﹐下表面﹐底部"}]},"media":{"uk":"media/ldoce/hwd/bre/4/underside0205.mp3","us":"media/ldoce/hwd/ame/0/underside.mp3"},"examples":[{"en":"The leaves are green on top and silvery on the underside.","cn":"那些叶子正面是绿色的﹐反面是银色的。"}],"oxford":{"phon":"ˈʌndəsaɪd","pos":"noun","senses":[{"en":"the bottom or lower side or surface of something","cn":"下侧；底面；底部；下表面"}]}},"unionization":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（工人或行业的）加入工会，成立工会","en":"The unionization of workers or industries is the process of workers becoming members of trade unions.","ex":{"en":"Increasing unionization led to demands for higher wages and shorter hours.","cn":"随着工会越来越壮大，有了提高工资、缩短工作时间的要求。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if workers unionize or are unionized, they become members of a trade union","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41unionize.mp3","us":"media/ldoce/hwd/ame/d/laadunionize.mp3"},"oxford":{"phon":"ˌjuːniənaɪˈzeɪʃn","pos":"noun","senses":[{"en":"the act or process of organizing people to become members of trade union or of becoming a member of a trade union","cn":"组织（或成立）工会；加入工会","ex":{"en":"a high level of unionization","cn":"高水平的工会化"}}]}},"unearth":{"collins":{"senses":[{"pos":"VERB 动词","cn":"发现；揭露","en":"If someone unearths facts or evidence about something bad, they discover them with difficulty, usually because they were being kept secret or were being lied about.","ex":{"en":"Researchers have unearthed documents indicating her responsibility for the forced adoption of children","cn":"调查人员已经发现了证明她对强制收养儿童事件负有责任的文件。"}},{"pos":"VERB 动词","cn":"发掘，挖掘（埋藏物）","en":"If someone unearths something that is buried, they find it by digging in the ground.","ex":{"en":"Fossil hunters have unearthed the bones of an elephant believed to be 500,000 years old.","cn":"化石搜集者们发掘出了一具大象骨骼，据信距今已有50万年。"}},{"pos":"VERB 动词","cn":"找到，发现（隐藏或丢失之物）","en":"If you say that someone has unearthed something, you mean that they have found it after it had been hidden or lost for some time.","ex":{"en":"From somewhere, he had unearthed a black silk suit","cn":"他不知从哪里找来了一套黑色的丝绸衣服。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to get or see something that you have been searching for","cn":""},{"en":"to find something that was hidden or that people did not know about before","cn":""},{"en":"to find the exact position of something","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"To unearth something is to dig it up. You could unearth a coffin, or even a tee shirt buried in the bottom of a drawer."}]},"media":{"uk":"media/ldoce/hwd/bre/9/unearth0205.mp3","us":"media/ldoce/hwd/ame/a/unearth.mp3"},"examples":[{"en":"I unearthed my old diaries when we moved house.","cn":"我们搬家时我偶然发现了自己以前的日记。"},{"en":"The newspaper has unearthed some disturbing facts.","cn":"报纸揭发了一些令人不安的真相。"}],"oxford":{"phon":"ʌnˈɜːθ","pos":"verb","senses":[{"en":"to find something in the ground by digging","cn":"挖掘；发掘；使出土","ex":{"en":"to unearth buried treasures","cn":"挖掘地下埋藏的珍宝"}},{"en":"to find or discover something by chance or after searching for it","cn":"（偶然或经搜寻）发现，找到","ex":{"en":"I unearthed my old diaries when we moved house.","cn":"我们搬家时，我偶然发现了自己以前的日记。"}}]}},"uplifting":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"振奋人心的；鼓舞人心的；令人兴奋不已的","en":"You describe something as uplifting when it makes you feel very cheerful and happy.","ex":{"en":"...a charming and uplifting love story","cn":"引人入胜的、令人振奋的爱情故事"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"making you feel happier and more hopeful","cn":"令人振奋的，使受鼓舞的"}]},"vocab":{"pos":"1 n 2 adj","senses":[{"en":"When you stand on a beach and admire the uplifting of a kite into the blue sky, you're watching it move up. Watching that kite rise might be an uplifting , or moving, experience."}]},"collocations":{"phrases":["VERBS be, feel | find sth","ADV. really, very | suitably a suitably uplifting ending for the film | morally, spiritually"]},"media":{"uk":"media/ldoce/hwd/bre/c/brelasdeuplifting.mp3","us":"media/ldoce/hwd/ame/3/laaduplifting.mp3"},"examples":[{"en":"an uplifting experience/speech","cn":"令人振奋的经历/演说"},{"en":"an uplifting experience","cn":"令人振奋的经历"}],"oxford":{"phon":"ˌʌpˈlɪftɪŋ","pos":"adjective","senses":[{"en":"making you feel happier or giving you more hope","cn":"令人振奋的；鼓舞人心的；催人奋进的","ex":{"en":"an uplifting experience/speech","cn":"令人振奋的经历／演说"}}]}},"unasked":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未被提出的；未被问及的","en":"An unasked question is one that has not been asked, although people are wondering what the answer is.","ex":{"en":"She was undernourished, an observation that prompted yet another unasked question","cn":"她看上去营养不良，这一发现又引出了一个未被问及的问题。"}},{"pos":"ADJ 形容词","cn":"未被要求的；未受邀请的；主动的","en":"If someone says or does something unasked, they say or do it without being asked to do it.","ex":{"en":"His advice, offered to her unasked, was to stay home and make the best of things.","cn":"他主动给她提出的建议是呆在家里尽量做些事。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if a question remains unasked, no one asks it, often because they are embarrassed 〔","cn":"问题常因不便过问而〕未被问及的"},{"en":"if you do something unasked, you do it without anyone asking or inviting you to","cn":"未被要求的﹔未受邀请的"}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41unasked.mp3","us":"media/ldoce/hwd/ame/9/unasked.mp3"},"examples":[{"en":"He came to the party unasked.","cn":"他未经邀请就来参加聚会了。"},{"en":"She brought him, unasked, the relevant file.","cn":"她主动把有关案卷带给了他。"}],"oxford":{"phon":"ˌʌnˈɑːskt","pos":"adjective","senses":[{"en":"an unasked question is one that you have not asked even though you would like to know the answer","cn":"没发问的；未出口的"},{"en":"without being invited or asked","cn":"未获邀请的；未经要求的","ex":{"en":"He came to the party unasked.","cn":"他未经邀请就来参加聚会了。"}}]}},"uninterrupted":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"不间断的；连续不断的","en":"If something is uninterrupted, it is continuous and has no breaks or interruptions in it.","ex":{"en":"This enables the healing process to continue uninterrupted","cn":"这样能使恢复过程不间断地进行下去。"}},{"pos":"ADJ 形容词","cn":"（景色）不受阻挡的","en":"An uninterrupted view of something is a clear view of it, without any obstacles in the way.","ex":{"en":"Diners can enjoy an uninterrupted view of the garden.","cn":"用餐者对花园的景色一览无余。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"continuing for a long time without stopping, or happening many times in a way that is annoying or causes problems","cn":""},{"en":"continuing without stopping","cn":""},{"en":"used when saying that something does not stop or always stays the same, or that something keeps happening. Constant is often used about things that are worrying, frightening, or difficult","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/3/uninterrupted0205.mp3","us":"media/ldoce/hwd/ame/a/uninterrupted.mp3"},"examples":[{"en":"We managed to eat our meal uninterrupted by phone calls.","cn":"我们总算吃了一顿没有电话打搅的安生饭。"},{"en":"We had an uninterrupted view of the stage.","cn":"我们能清楚地看见舞台。"}],"oxford":{"phon":"ˌʌnˌɪntəˈrʌptɪd","pos":"adjective","senses":[{"en":"not stopped or blocked by anything; continuous and not interrupted","cn":"不受阻挡的；不间断的；持续不断的","ex":{"en":"We had an uninterrupted view of the stage.","cn":"我们能清楚地看见舞台。"}}]}},"unborn":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未降生的；未出世的","en":"An unborn child has not yet been born and is still inside its mother's womb.","ex":{"en":"...her unborn baby","cn":"她未出世的婴儿"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a baby that is developing in its mother's body - used especially by doctors","cn":""},{"en":"a baby that is in the very early stage of development inside its mother's body","cn":""},{"en":"not yet born","cn":"尚未出生的"}]},"media":{"uk":"media/ldoce/hwd/bre/e/unborn0205.mp3","us":"media/ldoce/hwd/ame/c/unborn.mp3"},"examples":[{"en":"her unborn baby","cn":"她未出世的宝宝"},{"en":"an unborn child","cn":"未出世的孩子"}],"oxford":{"phon":"ˌʌnˈbɔːn","pos":"adjective","senses":[{"en":"not yet born","cn":"尚未出生的","ex":{"en":"her unborn baby","cn":"她未出世的宝宝"}}]}},"uproarious":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"喧嚣的；热闹的；充满喧闹哄笑声的","en":"When events or people are uproarious, they make people laugh in a very noisy way.","ex":{"en":"He had spent several uproarious evenings at the Embassy Club","cn":"他在使馆俱乐部度过了几个狂欢夜。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"very noisy, because a lot of people are laughing or shouting","cn":"喧闹的﹐人声鼎沸的"}]},"vocab":{"pos":"adj","senses":[{"en":"Uproarious situations are very loud, a little out of control, and often hilarious. You might encounter an uproarious crowd at a soccer match, or even in your school cafeteria."}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41uproarious.mp3","us":"media/ldoce/hwd/ame/8/uproarious.mp3"},"examples":[{"en":"The audience laughed uproariously.","cn":"观众哄然大笑。"},{"en":"an uproarious story","cn":"令人捧腹的故事"}],"oxford":{"phon":"ʌpˈrɔːriəs","pos":"adjective","senses":[{"en":"in which there is a lot of noise and people laugh or shout a lot","cn":"喧闹的；热烈的；吵吵嚷嚷的","ex":{"en":"an uproarious party","cn":"热闹的聚会"}},{"en":"extremely funny","cn":"滑稽的；极可笑的；令人捧腹的","ex":{"en":"an uproarious story","cn":"令人捧腹的故事"}}]}},"undisclosed":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未公开的；未公布的；未披露的","en":"Undisclosed information is not revealed to the public.","ex":{"en":"The company has been sold for an undisclosed amount","cn":"那家公司已被卖掉，具体售价未公开。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"used to describe information which is not given to the public 〔","cn":"信息〕未公开的﹐保密的﹐未披露的"}]},"media":{"uk":"media/ldoce/hwd/bre/e/brelasdeundisclosed.mp3","us":"media/ldoce/hwd/ame/e/laadundisclosed.mp3"},"examples":[{"en":"He was paid an undisclosed sum.","cn":"他得到了一笔数目不详的款项。"},{"en":"Developers have agreed to buy the site for an undisclosed sum.","cn":"开发商同意购买那块地﹐具体金额不详。"}],"oxford":{"phon":"ˌʌndɪsˈkləʊzd","pos":"adjective","senses":[{"en":"not made known or told to anyone; not having been disclosed","cn":"未披露的；未公开的；保密的","ex":{"en":"He was paid an undisclosed sum.","cn":"他得到了一笔数目不详的钱。"}}]}},"user-friendly":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（机器、系统等）易操作的，便于使用的","en":"If you describe something such as a machine or system as user-friendly, you mean that it is well designed and easy to use.","ex":{"en":"This is an entirely computer operated system which is very user friendly.","cn":"这个系统完全由电脑操控，非常好用。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not difficult to do, and not needing much effort","cn":""},{"en":"easy and not complicated – used about things such as instructions and explanations, or about machines and systems","cn":""},{"en":"easy to understand or do, and unlikely to cause you any problems","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"A gadget that is user-friendly is easy to use. User-friendly devices can be used quickly, even if you haven't used anything like it before."}]},"media":{"uk":"media/ldoce/hwd/bre/4/user_friendly0205.mp3","us":"media/ldoce/hwd/ame/4/user-friendly.mp3"},"examples":[{"en":"a user-friendly guide to computing","cn":"易懂的计算机应用指南"}],"oxford":{"phon":"ˌjuːzə ˈfrendli","pos":"adjective","senses":[{"en":"easy for people who are not experts to use or understand","cn":"方便非专业用户的；便于使用的；易于掌握的","ex":{"en":"What can we do to make the museum more user-friendly?","cn":"我们可以做些什么来让博物馆更加人性化？"}}]}},"uncooked":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未烹饪过的；生的","en":"Uncooked food has not yet been cooked.","ex":{"en":"Don't use pickled beetroot, but buy it uncooked and cook it yourself.","cn":"不要买腌制的甜菜根，买生的来自己煮。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"raw food has not been cooked","cn":""},{"en":"uncooked food has not yet been cooked, but should be cooked before it is eaten","cn":""},{"en":"not cooked for long enough","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41uncooked.mp3","us":"media/ldoce/hwd/ame/b/ld41uncooked.mp3"},"examples":[{"en":"Eat plenty of uncooked fruit and vegetables.","cn":"要多吃新鲜水果和生蔬菜。"},{"en":"Always wash your hands after handling uncooked meat.","cn":"碰过生肉后一定要洗手。"}],"oxford":{"phon":"ˌʌnˈkʊkt","pos":"adjective","senses":[{"en":"not cooked","cn":"未烹煮的；生的","ex":{"en":"Eat plenty of uncooked fruit and vegetables.","cn":"要多吃生的水果和蔬菜。"}}]}},"upriver":{"collins":{"senses":[{"pos":"ADV 副词","cn":"往上游；向上游；在上游","en":"Something that is moving up-river is moving towards the source of a river, from a point down the river. Something that is up-river is towards the source of a river.","ex":{"en":"Heavy goods could be brought up-river in barges","cn":"较重的货物可用驳船运到上游。"}}]},"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"away from the sea towards the place where a river begins","cn":"向上游﹐往上游"}]},"media":{"uk":"media/ldoce/hwd/bre/6/upriver0205.mp3","us":"media/ldoce/hwd/ame/0/laadupriver.mp3"},"oxford":{"phon":"ˌʌpˈrɪvə(r)","pos":"adverb","senses":[{"en":"along a river, in the opposite direction to the way in which the water flows","cn":"向（或在）上游；逆流"}]}},"ungrateful":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不感激的；不领情的；忘恩负义的","en":"If you describe someone as ungrateful, you are criticizing them for not showing thanks or for being unkind to someone who has helped them or done them a favour.","ex":{"en":"I thought it was rather ungrateful","cn":"我觉得这样做有些忘恩负义。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who is ungrateful does not thank you when you do something for them, and this makes you annoyed or upset","cn":""},{"en":"a lack of any feeling of being grateful when someone has given you something or does something for you","cn":""},{"en":"to expect someone to help you or do things for you because they always have done, and never thank them or show them that you are grateful","cn":""}]},"vocab":{"pos":"1 adj 2 adj","senses":[{"en":"Someone who's ungrateful isn't thankful or appreciative. Your grandmother might think you're ungrateful if you don't send her a handwritten thank you note for the birthday gift she gave you."}]},"media":{"uk":"media/ldoce/hwd/bre/c/ungrateful0205.mp3","us":"media/ldoce/hwd/ame/8/ungrateful.mp3"},"examples":[{"en":"Don’t be so ungrateful!","cn":"不要如此忘恩负义！"}],"oxford":{"phon":"ʌnˈɡreɪtfl","pos":"adjective","senses":[{"en":"not showing or expressing thanks for something that somebody has done for you or given to you","cn":"不领情的；忘恩负义的"}]}},"untamed":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"原始的；天然淳朴的；未开发的","en":"An untamed area or place is in its original or natural state and has not been changed or affected by people.","ex":{"en":"...the wild, untamed undergrowth","cn":"野生的、原始的灌木丛"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not made, caused, or changed by humans","cn":""},{"en":"wild flowers, plants, and animals are in their natural state and have not been changed or controlled by humans","cn":""},{"en":"if animals live in the wild , they live in their natural state, not in a place such as a farm","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41untamed.mp3","us":"media/ldoce/hwd/ame/3/laaduntamed.mp3"},"oxford":{"phon":"ˌʌnˈteɪmd","pos":"adjective","senses":[{"en":"allowed to remain in a wild state; not changed, controlled or influenced by anyone; not tamed","cn":"野性的；未驯服的；未受抑制的；未调教的","ex":{"en":"a wild and untamed landscape","cn":"尚未开发的自然景色"}}]}},"unseat":{"collins":{"senses":[{"pos":"VERB 动词","cn":"把…革职；罢免","en":"When people try to unseat a person who is in an important job or position, they try to remove him or her from that job or position.","ex":{"en":"It is still not clear who was behind Sunday's attempt to unseat the President","cn":"目前还不清楚星期天发动的企图推翻总统的行动的幕后指使人是谁。"}},{"pos":"VERB 动词","cn":"使从马上摔下","en":"If a horse unseats its rider, it causes him or her to fall off.","ex":{"en":"Crystal Spirit unseated his rider in the Berkshire Hurdle at Newbury","cn":"在纽伯里举行的伯克郡障碍赛中“水玉精灵”把骑师掀了下来。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to remove someone from a powerful job or position","cn":"罢免﹐拉…下马"},{"en":"if a horse unseats someone, it throws them off its back 〔","cn":"马〕把〔骑手〕摔下来"}]},"media":{"uk":"media/ldoce/hwd/bre/6/unseat0205.mp3","us":"media/ldoce/hwd/ame/e/unseat.mp3"},"examples":[{"en":"The horse unseated its rider at the first fence.","cn":"马在过第一道篱障时把骑手掀了下来。"},{"en":"an attempt to unseat the party leader","cn":"罢免政党领导的企图"}],"oxford":{"phon":"ˌʌnˈsiːt","pos":"verb","senses":[{"en":"to remove somebody from a position of power","cn":"罢免；解除职务；赶下台","ex":{"en":"She is bidding to unseat the local Tory MP at the next election.","cn":"她正在争取在下次选举中推翻当地保守党议员。"}},{"en":"to make somebody fall off a horse or bicycle","cn":"使摔下马（或自行车）","ex":{"en":"The horse unseated its rider at the first fence.","cn":"马在过第一道篱障时把骑手掀了下来。"}}]}},"undeserved":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"不应得的；不该有的","en":"If you describe something such as a reaction, treatment, or result as undeserved, you mean that the person who experiences it has not earned it and should not really have it.","ex":{"en":"Douglas has an undeserved reputation for being dull and dry","cn":"道格拉斯呆板无趣的名声并不副实。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not treating everyone equally, or not treating people in a way that most people think is right","cn":""},{"en":"not fair or not sensible","cn":""},{"en":"a punishment or criticism that is undeserved is unfair because you do not deserve it","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/f/undeserved0205.mp3","us":"media/ldoce/hwd/ame/d/undeserved.mp3"},"examples":[{"en":"The criticism was totally undeserved.","cn":"这批评纯属冤枉人。"},{"en":"an undeserved victory","cn":"不该得到的胜利"}],"oxford":{"phon":"ˌʌndɪˈzɜːvd","pos":"adjective","senses":[{"en":"that somebody does not deserve and therefore unfair","cn":"不应得的；冤枉的；不公正的","ex":{"en":"The criticism was totally undeserved.","cn":"这批评纯属冤枉人。"}}]}},"unscrew":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"拧开；旋开","en":"If you unscrew something such as a lid, or if it unscrews, you keep turning it until you can remove it.","ex":{"en":"She unscrewed the cap of her water bottle and gave him a drink","cn":"她拧开水壶的盖子给他喝水。"}},{"pos":"VERB 动词","cn":"(旋出螺丝以)拆卸，取下","en":"If you unscrew something such as a sign or mirror which is fastened to something by screws, you remove it by taking out the screws.","ex":{"en":"He unscrewed the back of the telephone and started connecting it to the cable.","cn":"他旋出螺丝打开电话机后盖，开始动手把话机跟电话线接上。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"used about a door, window, container, package, letter, your eyes, or your mouth","cn":""},{"en":"to open a door, drawer, box etc with a key","cn":""},{"en":"to open a lid on a bottle, container etc by turning it","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/b/unscrew0205.mp3","us":"media/ldoce/hwd/ame/6/unscrew.mp3"},"examples":[{"en":"You'll have to unscrew the handles to paint the door.","cn":"要漆这扇门，你得把门把手上的螺丝拧开拿下来。"},{"en":"I can't unscrew the lid of this jar.","cn":"这个瓶盖儿我拧不开。"}],"oxford":{"phon":"ˌʌnˈskruː","pos":"verb","senses":[{"en":"to remove something by twisting or turning it; to be removed in this way","cn":"（被）旋松，拧开","g":"[transitive, intransitive]","ex":{"en":"I can't unscrew the lid of this jar.","cn":"这个瓶盖儿我拧不开。"}},{"en":"to take the screws out of something","cn":"拧下…的螺丝","g":"[transitive]","ex":{"en":"You'll have to unscrew the handles to paint the door.","cn":"要漆这扇门，你得把螺丝拧开，卸下门把手。"}}]}},"upturn":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"好转；上升；改善","en":"If there is an upturn in the economy or in a company or industry, it improves or becomes more successful.","ex":{"en":"They do not expect an upturn in the economy until the end of the year","cn":"他们预测要到年底经济才能有所好转。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an increase in amount, quantity, population etc","cn":""},{"en":"an increase in numbers, level, population, or temperature","cn":""},{"en":"a gradual increase in something harmful or bad","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Use the noun upturn to describe an improvement, especially in finances or business."}]},"collocations":{"phrases":["ADJ. dramatic, sharp | slight | economic","VERB + UPTURN be on, take Sales are on the upturn. Their fortunes have taken an upturn in recent months.","UPTURN + VERB come We expect an increase in demand when the economic upturn eventually comes.","PREP. ~ in a sharp upturn in oil prices"]},"media":{"uk":"media/ldoce/hwd/bre/6/upturn0205.mp3","us":"media/ldoce/hwd/ame/9/upturn.mp3"},"examples":[{"en":"The restaurant trade is on the upturn.","cn":"餐厅业正在复苏。"},{"en":"an upturn in the economy","cn":"经济的好转"}],"oxford":{"phon":"ˈʌptɜːn","pos":"noun","senses":[{"en":"a situation in which something improves or increases over a period of time","cn":"改善；改进；回升；进步","ex":{"en":"an upturn in the economy","cn":"经济的好转"}}]}},"unplayable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（选手）无法战胜的；（球）无法击出的","en":"In some sports, if you describe a player as unplayable, you mean that they are playing extremely well and are difficult to beat. If you describe a ball as unplayable, you mean that it is difficult to hit."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"in sport, a ball that is unplayable is difficult to hit because of its position or speed 〔","cn":"球〕无法击打的"},{"en":"a sports field that is unplayable is in too bad a condition to play on 〔","cn":"运动场〕不适宜比赛的"}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41unplayable.mp3","us":"media/ldoce/hwd/ame/f/ld41unplayable.mp3"},"examples":[{"en":"The ball was unplayable (= it was hit so well that it was impossible to hit it back).","cn":"那个球没法接。"}],"oxford":{"phon":"ˌʌnˈpleɪəbl","pos":"adjective","senses":[{"en":"not able to be played; impossible to play on or with","cn":"（乐曲）无法演奏的；（球）接不住的；（运动场）不能用于比赛的","ex":{"en":"The two coaches decided the pitch was unplayable so the match was cancelled.","cn":"两位教练认为场地没法使用，所以比赛取消了。"}},{"en":"(of a sportsperson or team) playing so well that it is impossible to beat them","cn":"（运动员或运动队）发挥出色而难以击败的","ex":{"en":"When they're good, they're unplayable.","cn":"他们打得好时是战无不胜的。"}}]}},"unassuming":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"低调的；谦逊的；不招摇的","en":"If you describe a person or their behaviour as unassuming, you approve of them because they are quiet and do not try to appear important.","ex":{"en":"He's a man of few words, very polite and unassuming","cn":"他话不多，很有礼貌，为人谦和。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not wanting to talk about your abilities or achievements and to say that you are good at something, even when you are – used to show approval","cn":""},{"en":"not wanting to talk about yourself or to attract attention","cn":""},{"en":"not wanting to be noticed and not expecting to be treated in a special way","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"The word unassuming means modest, lacking in arrogance, pleasant, or polite. You'll find that some of the most unassuming people are actually the most interesting and powerful of all. They're just decent enough not to display it all the time."}]},"media":{"uk":"media/ldoce/hwd/bre/7/unassuming0205.mp3","us":"media/ldoce/hwd/ame/5/unassuming.mp3"},"oxford":{"phon":"ˌʌnəˈsjuːmɪŋ","pos":"adjective","senses":[{"en":"not wanting to draw attention to yourself or to your abilities or status","cn":"不爱出风头的；不爱炫耀的；谦逊的","ex":{"en":"He did some wonderful work in a quiet and unassuming way.","cn":"他一声不响、不事张扬地干了一些漂亮活儿。"}}]}},"unwelcome":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不受欢迎的；不想要的；讨人嫌的","en":"An unwelcome experience is one that you do not like and did not want.","ex":{"en":"The media has brought more unwelcome attention to the Royal Family","cn":"媒体对王室的过度关注令人反感。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（访客）不受欢迎的","en":"If you say that a visitor is unwelcome, you mean that you did not want them to come.","ex":{"en":"...an unwelcome guest","cn":"不受欢迎的客人"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"something that is undesirable is not wanted because it could affect a person or situation in a bad way","cn":""},{"en":"use this about something that you are given or that happens to you that you do not want and did not ask for","cn":""},{"en":"likely to upset or cause problems for someone and therefore not wanted","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Things that are unwelcome are unpleasant or objectionable in some way. An unwelcome guest is one you didn't invite and you're not particularly happy to see."}]},"media":{"uk":"media/ldoce/hwd/bre/0/unwelcome0205.mp3","us":"media/ldoce/hwd/ame/d/laadunwelcome.mp3"},"examples":[{"en":"To avoid attracting unwelcome attention he kept his voice down.","cn":"为避免引起不必要的注意，他把声音压低了。"},{"en":"an unwelcome visitor","cn":"不受欢迎的访客"}],"oxford":{"phon":"ʌnˈwelkəm","pos":"adjective","senses":[{"en":"not wanted","cn":"不需要的；不受欢迎的；多余的","ex":{"en":"Security cameras around the building keep out unwelcome visitors.","cn":"建筑物周围的监视摄像机能防止不受欢迎的访客进入。"}}]}},"utilize":{"collins":{"senses":[{"pos":"VERB 动词","cn":"利用；使用","en":"If you utilize something, you use it.","ex":{"en":"Sound engineers utilize a range of techniques to enhance the quality of the recordings","cn":"音响师运用一系列技术来提高录音质量。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to use something for a particular purpose","cn":"利用﹐使用"},{"en":"to use something that is available to you","cn":""},{"en":"to use a particular method or skill in order to achieve something","cn":""}]},"vocab":{"pos":"1 v 2 v","senses":[{"en":"To utilize is to use what you have or what's available, and it's a three-syllable word meaning the same thing as the one-syllable \"use.\""}]},"collocations":{"phrases":["ADV. heavily | extensively | fully, to the full The new computer system is not being fully utilized yet. | effectively, successfully","PREP. as Concrete had long been utilized as a bonding and covering material."]},"media":{"uk":"media/ldoce/hwd/bre/f/utilize0205.mp3","us":"media/ldoce/hwd/ame/9/laadutilize.mp3"},"examples":[{"en":"The resources at our disposal could have been better utilized.","cn":"我们所掌握的资源本来可以利用得更好，获得更高的效益。"},{"en":"The Romans were the first to utilize concrete as a building material.","cn":"罗马人首先使用混凝土作建筑材料。"}],"oxford":{"phon":"ˈjuːtəlaɪz","pos":"verb","senses":[{"en":"to use something, especially for a practical purpose","cn":"使用；利用；运用；应用","ex":{"en":"The Romans were the first to utilize concrete as a building material.","cn":"罗马人首先使用混凝土作建筑材料。"}}]}},"unworthy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不值得的；配不上的","en":"If a person or thing is unworthy of something good, they do not deserve it.","ex":{"en":"You may feel unworthy of the attention and help people offer you","cn":"你可能会觉得自己不值得别人关心和帮助。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不相称的；与（某人）身份不相符的","en":"If you say that an action is unworthy of someone, you mean that it is not a nice thing to do and someone with their reputation or position should not do it.","ex":{"en":"Miss Melville could not resist asking, although she knew it was unworthy of her","cn":"梅尔维尔小姐忍不住问起来，虽然她知道自己不该问。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not deserving respect, attention etc","cn":"不值得〔尊敬﹑注意等〕的"},{"en":"unworthy behaviour, attitudes etc are not acceptable from someone who is respected or who has an important job 〔","cn":"行为﹑态度等〕有失身份的"}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41unworthy.mp3","us":"media/ldoce/hwd/ame/6/laadunworthy.mp3"},"examples":[{"en":"He considered himself unworthy of the honour they had bestowed on him.","cn":"他认为自己不配得到大家赋予他的荣誉。"},{"en":"Such opinions are unworthy of educated people.","cn":"知识分子发表这样的言论有失身分。"}],"oxford":{"phon":"ʌnˈwɜːði","pos":"adjective","senses":[{"en":"not having the necessary qualities to deserve something, especially respect","cn":"不值得（尊重）的；不配的","ex":{"en":"He considered himself unworthy of the honour they had bestowed on him.","cn":"他认为自己不配得到大家赋予他的荣誉。"}},{"en":"not acceptable from somebody, especially somebody who has an important job or high social position","cn":"格格不入的；不能接受的；（与…的身份）不相称的","ex":{"en":"Such opinions are unworthy of educated people.","cn":"知识分子发表这样的言论有失身份。"}}]}},"understate":{"collins":{"senses":[{"pos":"VERB 动词","cn":"不充分如实地陈述；对…轻描淡写；打折扣地说","en":"If you understate something, you describe it in a way that suggests that it is less important or serious than it really is.","ex":{"en":"The government chooses deliberately to understate the increase in prices","cn":"政府故意对物价上涨轻描淡写。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to write or talk about something in a way that makes it seem less serious or important than it really is","cn":""},{"en":"to pretend that a problem, illness etc is less important or serious than it really is","cn":""},{"en":"to say or do something that makes someone's efforts or achievements seem unimportant or useless","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"One way to think about the verb understate is as the opposite of \"exaggerate.\" If you want to make something seem smaller or less important than it really is, you're likely to understate it."}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41understate.mp3","us":"media/ldoce/hwd/ame/c/understate.mp3"},"examples":[{"en":"It would be a mistake to understate the seriousness of the problem.","cn":"对问题的严重性轻描淡写是错误的。"},{"en":"The press have tended to understate the extent of the problem.","cn":"媒体想淡化问题的严重程度。"}],"oxford":{"phon":"ˌʌndəˈsteɪt","pos":"verb","senses":[{"en":"to state that something is smaller, less important or less serious than it really is","cn":"轻描淡写；避重就轻地说","ex":{"en":"It would be a mistake to understate the seriousness of the problem.","cn":"淡化问题的严重性是错误的。"}}]}},"unseeing":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"视而不见的；不留心的","en":"If you describe a person or their eyes as unseeing, you mean that they are not looking at anything, or not noticing something, although their eyes are open.","ex":{"en":"In the hallway Greenfield was staring at the wood panelling with unseeing eyes","cn":"在门厅里，格林菲尔德茫然地看着木质面板。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not noticing anything even though your eyes are open","cn":"视而不见的"}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41unseeing.mp3","us":"media/ldoce/hwd/ame/f/unseeing.mp3"},"examples":[{"en":"They stared unseeingly at the wreckage.","cn":"他们看着残骸发愣。"},{"en":"Jack gazed unseeing out of the window.","cn":"杰克茫然地望着窗外。"}],"oxford":{"phon":"ˌʌnˈsiːɪŋ","pos":"adjective","senses":[{"en":"not noticing or really looking at anything although your eyes are open","cn":"心不在焉地看着的","ex":{"en":"He gazed out to the horizon with unseeing eyes.","cn":"他用一双看不见的眼睛凝视着远方的地平线。"}}]}},"unsaid":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未讲出来的；不说的","en":"If something is left unsaid or goes unsaid in a particular situation, it is not said, although you might have expected it to be said.","ex":{"en":"Some things, Donald, are better left unsaid","cn":"唐纳德，有些事还是不说为好。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if something is left unsaid, you do not say it although you might be thinking it 〔","cn":"话〕未说出口"}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld44unsaid.mp3","us":"media/ldoce/hwd/ame/d/ld44unsaid.mp3"},"examples":[{"en":"Some things are better left unsaid.","cn":"有些事情还是不说出来好。"},{"en":"Some things are better left unsaid (= it is better not to mention them ) .","cn":"有些事不说出来更好。"}],"oxford":{"phon":"ʌnˈsed","pos":"adjective","senses":[{"en":"thought but not spoken","cn":"（想到却）未说出","ex":{"en":"Some things are better left unsaid.","cn":"有些事情还是不说出来好。"}}]}},"uncooperative":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不合作的；不配合的","en":"If you describe someone as uncooperative, you mean that they make no effort at all to help other people or to make other people's lives easier.","ex":{"en":"She became uncooperative: unwilling to do her homework or help with any household chores.","cn":"她变得很不合作：不愿做作业，也不愿帮着做家务。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if something or someone is no help they do not help you do something or get something","cn":""},{"en":"not wanting to help someone who wants you to help them, especially by deliberately opposing them or stopping them doing something easily","cn":""},{"en":"not giving any help - use this when you are annoyed with someone or something because they should help you but they do not","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/0/uncooperative0205.mp3","us":"media/ldoce/hwd/ame/2/laaduncooperative.mp3"},"oxford":{"phon":"ˌʌnkəʊˈɒpərətɪv","pos":"adjective","senses":[{"en":"not willing to be helpful to other people or do what they ask","cn":"不愿合作的；不愿配合的","ex":{"en":"The witness was extremely uncooperative.","cn":"目击者一点都不配合。"}}]}},"unknowing":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未意识到的；没察觉的；不知的","en":"If you describe a person as unknowing, you mean that they are not aware of what is happening or of what they are doing.","ex":{"en":"Some governments have been victims and perhaps unknowing accomplices in the bank's activities.","cn":"一些政府成为了银行活动的受害者，而且可能在不知不觉中做了其帮凶。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not realizing what you are doing or what is happening","cn":"不知道的﹔未察觉的"}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41unknowing.mp3","us":"media/ldoce/hwd/ame/c/unknowing.mp3"},"examples":[{"en":"He was the unknowing cause of all the misunderstanding.","cn":"他无意中引起了这一切误会。"},{"en":"She had unknowingly broken the rules.","cn":"她无意中犯了规。"}],"oxford":{"phon":"ʌnˈnəʊɪŋ","pos":"adjective","senses":[{"en":"not aware of what you are doing or what is happening","cn":"没意识到的；未察觉的；无知的","ex":{"en":"He was the unknowing cause of all the misunderstanding.","cn":"他无意中引起了这一切误会。"}}]}},"ultimatum":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"最后通牒","en":"An ultimatum is a warning to someone that unless they act in a particular way, action will be taken against them.","ex":{"en":"They issued an ultimatum to the police to rid an area of racist attackers, or they will take the law into their own hands.","cn":"他们向警方发出了最后通牒，要求肃清整个地区的种族主义暴徒，否则他们将自行采取行动。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when you tell someone that you will hurt them or cause serious problems for them if they do not do what you want","cn":""},{"en":"a final, often official, warning that unless someone does something you will punish or attack them","cn":""},{"en":"a threat saying that if someone does not do what you want by a particular time, you will do something to punish them","cn":"最后通牒﹐哀的美敦书"}]},"vocab":{"pos":"n","senses":[{"en":"An ultimatum is a final demand attached to a threat, like \"If you don't do it, I'll never speak to you again.\" Ultimatums are serious business."}]},"collocations":{"phrases":["VERB + ULTIMATUM deliver, give sb, issue, present (sb with), send The government denied that it had presented the union with an ultimatum. |","ULTIMATUM + VERB demand sth"]},"media":{"uk":"media/ldoce/hwd/bre/5/ultimatum0205.mp3","us":"media/ldoce/hwd/ame/8/ultimatum.mp3"},"examples":[{"en":"to issue an ultimatum","cn":"发出最后通牒"},{"en":"The club gave him an ultimatum - either he apologized, or he would be expelled from the team.","cn":"俱乐部给他下了最后通牒——要么道歉﹐要么等着被开除出队。"}],"oxford":{"phon":"ˌʌltɪˈmeɪtəm","pos":"noun","senses":[{"en":"a final warning to a person or country that if they do not do what you ask, you will use force or take action against them","cn":"最后通牒","ex":{"en":"to issue an ultimatum","cn":"发出最后通牒"}}]}},"uproot":{"collins":{"senses":[{"pos":"VERB 动词","cn":"使离开久住之处；使迁移他处居住","en":"If you uproot yourself or if you are uprooted, you leave, or are made to leave, a place where you have lived for a long time.","ex":{"en":"...the trauma of uprooting themselves from their homes","cn":"背井离乡给他们造成的心灵创伤"}},{"pos":"VERB 动词","cn":"把…连根拔起；根除","en":"If someone uproots a tree or plant, or if the wind uproots it, it is pulled out of the ground.","ex":{"en":"They had been forced to uproot their vines and plant wheat.","cn":"他们已被迫将葡萄藤连根拔除，改种小麦。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to pull a plant and its roots out of the ground","cn":"把〔植物〕连根拔起"},{"en":"to make someone leave their home for a new place, especially when this is difficult or upsetting （","cn":"使）〔某人〕背井离乡"}]},"vocab":{"pos":"v","senses":[{"en":"When you uproot people, you move them from one place to a completely new one. Your parents may need to uproot you if your mom gets a new job all the way across the country."}]},"media":{"uk":"media/ldoce/hwd/bre/c/uproot0205.mp3","us":"media/ldoce/hwd/ame/f/uproot.mp3"},"examples":[{"en":"If I accept the job, it will mean uprooting my family and moving to Italy.","cn":"如果我接受了这份工作，那将意味着我得举家搬迁到意大利去。"},{"en":"We decided to uproot and head for Scotland.","cn":"我们决定迁往苏格兰。"}],"oxford":{"phon":"ˌʌpˈruːt","pos":"verb","senses":[{"en":"to pull a tree, plant, etc. out of the ground","cn":"将…连根拔起","g":"[transitive]","ex":{"en":"The storms uprooted a number of large trees.","cn":"暴风雨将许多大树连根拔起。"}},{"en":"to leave a place where you have lived for a long time; to make somebody do this","cn":"（使）离开家园（或熟悉的地方等）","g":"[intransitive, transitive]","ex":{"en":"We decided to uproot and head for Scotland.","cn":"我们决定迁往苏格兰。"}}]}},"unanimity":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"一致同意；全体一致","en":"When there is unanimity among a group of people, they all agree about something or all vote for the same thing.","ex":{"en":"All decisions would require unanimity.","cn":"所有决定都需要全体一致同意。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a state or situation of complete agreement among a group of people","cn":"一致同意"}]},"vocab":{"pos":"n","senses":[{"en":"When there is unanimity , everyone agrees. When it comes to opinion, unanimity is the opposite of disagreement."}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41unanimity.mp3","us":"media/ldoce/hwd/ame/e/unanimity.mp3"},"oxford":{"phon":"ˌjuːnəˈnɪməti","pos":"noun","senses":[{"en":"complete agreement about something among a group of people","cn":"一致同意；全体赞同","ex":{"en":"There is no unanimity of opinion among the medical profession on this subject.","cn":"医学界对此问题尚未达成一致意见。"}}]}},"unalloyed":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（感情）纯粹的，不掺杂的","en":"If you describe a feeling such as happiness or relief as unalloyed, you are emphasizing that it is a strong feeling and no other feeling is involved.","ex":{"en":"...an occasion of unalloyed joy.","cn":"纵情欢乐的时刻"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"complete, pure, or total","cn":"十足的，纯粹的，完全的"}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41unalloyed.mp3","us":"media/ldoce/hwd/ame/2/unalloyed.mp3"},"examples":[{"en":"unalloyed joy","cn":"纯粹的快乐"}],"oxford":{"phon":"ˌʌnəˈlɔɪd","pos":"adjective","senses":[{"en":"not mixed with anything else, such as negative feelings","cn":"纯真的；纯粹的","ex":{"en":"unalloyed joy","cn":"纯粹的快乐"}}]}},"unrivalled":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"无与伦比的；无可匹敌的；无双的","en":"If you describe something as unrivalled, you are emphasizing that it is better than anything else of the same kind.","ex":{"en":"He had an unrivalled knowledge of south Arabian society, religion, law and customs","cn":"他对南阿拉伯社会、宗教、法律和风俗的了解无人可比。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"better than any other","cn":"无可匹敌的﹐无双的"}]},"media":{"uk":"media/ldoce/hwd/bre/a/unrivalled0205.mp3","us":"media/ldoce/hwd/ame/c/unrivaled.mp3"},"examples":[{"en":"an unrivalled collection of Chinese art","cn":"一批无与伦比的中国艺术收藏品"}],"oxford":{"phon":"ʌnˈraɪvld","pos":"adjective","senses":[{"en":"better or greater than any other","cn":"无可匹敌的；无与伦比的；没有对手的","ex":{"en":"The hotel enjoys an unrivalled position overlooking the lake.","cn":"酒店享有无与伦比的位置，俯瞰着湖泊。"}}]}},"underhand":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"秘密的；狡诈的；欺诈的","en":"If an action is underhand or if it is done in an underhand way, it is done secretly and dishonestly.","ex":{"en":"...underhand financial deals.","cn":"秘密的金融交易"}},{"pos":"ADJ 形容词","cn":"（投球等）低手的，手不过肩的","en":"You use underhand or underhanded to describe actions, such as throwing a ball, in which you do not raise your arm above your shoulder.","ex":{"en":"...an underhanded pitch.","cn":"低手投球"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"behaving in a way that is intended to deceive people, for example by lying, cheating, or stealing","cn":""},{"en":"using your power in a dishonest way for your own advantage – used about people in official positions","cn":""},{"en":"good at secretly thinking of clever plans to trick people in order to get what you want","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/2/underhand_adv0205.mp3","us":"media/ldoce/hwd/ame/5/underhand1.mp3"},"examples":[{"en":"I would never have expected her to behave in such an underhand way.","cn":"我从未想到她的行为竟如此阴险。"},{"en":"They did it all in such an underhand way.","cn":"这一切他们都进行得如此隐秘。"}],"oxford":{"phon":"ˌʌndəˈhænd","pos":"adjective","senses":[{"en":"secret and dishonest","cn":"秘密的；阴险的；狡诈的；卑鄙的","ex":{"en":"I would never have expected her to behave in such an underhand way.","cn":"我从未想到她的行为竟如此阴险。"}}]}},"unresolved":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未解决的","en":"If a problem or difficulty is unresolved, no satisfactory solution has been found to it.","ex":{"en":"The murder remains unresolved.","cn":"那个谋杀案还没有侦破。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"an unresolved problem still exists because it has not been dealt with successfully","cn":""},{"en":"an insoluble problem is very difficult or impossible to solve","cn":""},{"en":"an intractable problem is one that is so difficult and complicated that it is impossible to solve it however hard you try","cn":""}]},"vocab":{"pos":"1 adj 2 adj","senses":[{"en":"The word unresolved may describe an argument that has not been solved, a question that remains unanswered, or a decision that not been made — like the title of \"Checkers Champion\" after a tie game."}]},"media":{"uk":"media/ldoce/hwd/bre/f/brelasdeunresolved.mp3","us":"media/ldoce/hwd/ame/3/laadunresolved.mp3"},"examples":[{"en":"the unresolved issue of who will pay for the project","cn":"项目由谁出资这个悬而未决的问题"},{"en":"an unresolved conflict","cn":"没有解决的冲突"}],"oxford":{"phon":"ˌʌnrɪˈzɒlvd","pos":"adjective","senses":[{"en":"not yet solved or answered; not having been resolved","cn":"未克服的；未解答的；未解决的","ex":{"en":"These unresolved issues must be addressed.","cn":"这些悬而未决的问题必须设法解决。"}}]}},"usefulness":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"how useful and effective something is","cn":""},{"en":"the state of being useful or the degree to which something is useful","cn":"有用﹔实用性"}]},"collocations":{"phrases":["ADJ. limited, some | general | practical | potential","VERB + USEFULNESS have | increase | diminish, limit, reduce Badly written questions limit the usefulness of questionnaires. | assess, evalua","PREP. of &hellip; ~ The theory is of limited usefulness. | ~ for the exam's usefulness for ranking students | ~ in the drug's usefulness in "]},"media":{"uk":"media/ldoce/hwd/bre/2/usefulness0205.mp3","us":"media/ldoce/hwd/ame/3/laadusefulness.mp3"},"examples":[{"en":"There are doubts about the usefulness of these tests.","cn":"这些试验是否有用，人们有所保留。"},{"en":"The building has outlived its usefulness.","cn":"这座楼房已超过使用年限了。"}],"oxford":{"phon":"ˈjuːsflnəs","pos":"noun","senses":[{"en":"the fact of being useful or possible to use","cn":"有用；实用；可用性","ex":{"en":"There are doubts about the usefulness of these tests.","cn":"这些试验是否有用，人们有所保留。"}}]}},"unfocused":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（目光）茫然的，呆滞的","en":"If someone's eyes are unfocused, they are open, but not looking at anything.","ex":{"en":"Her eyes were unfocused, as if she were staring inside at her memories of the day.","cn":"她目光呆滞，仿佛沉浸在那天的记忆当中。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（情绪、计划等）漫无目的的，不着边际的","en":"If you describe someone's feelings or plans as unfocused, you are criticizing them because they do not seem to be clearly formed or have any clear purpose.","ex":{"en":"But for now, she is in the grip of a blind, unfocused anger","cn":"而现在，她陷入了一种无名的愤怒之中。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not dealing with or paying attention to the most important ideas, causes etc","cn":"无焦点的﹔漫无边际的"},{"en":"eyes that are unfocused are open, but are not looking at anything specific","cn":"目光分散的﹔目光茫然的"}]},"media":{"uk":"media/ldoce/hwd/bre/6/unfocused0205.mp3","us":"media/ldoce/hwd/ame/d/unfocused.mp3"},"examples":[{"en":"The research is too unfocused to have any significant impact.","cn":"这一次的研究太零散，难以发挥重大的作用。"},{"en":"unfocused questions","cn":"漫无边际的问题"}],"oxford":{"phon":"ʌnˈfəʊkəst","pos":"adjective","senses":[{"en":"not looking at a particular thing or person; not having been focused","cn":"目光分散的；漫不经心的","ex":{"en":"an unfocused look","cn":"茫然的眼神"}},{"en":"not having a clear aim or purpose; not well organized or clear","cn":"目的不明确的；组织不严密的；松散的","ex":{"en":"The research is too unfocused to have any significant impact.","cn":"这项研究太零散，难以发挥重大的作用。"}}]}},"up-country":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"from a place without many people or towns, especially in the middle of a country","cn":"来自内地的〔尤指地处国家中部﹑人口或城镇不多的地区〕"}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41up-country.mp3","us":"media/ldoce/hwd/ame/a/ld41up-country.mp3"},"oxford":{"phon":"ˌʌp ˈkʌntri","pos":"adjective","senses":[{"en":"relating to an area of a country that is not near large towns","cn":"内地的；偏远的；偏僻的"},{"en":"in or towards an area of a country that is not near large towns","cn":"内地的；偏远的；偏僻的","pos":"adverb"}]}},"unpardonable":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"不可原谅的；不可宽恕的","en":"If you say that someone's behaviour is unpardonable, you mean that it is very wrong or offensive, and completely unacceptable.","ex":{"en":"...an unpardonable lack of discipline","cn":"无组织无纪律，简直不可容忍"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"unpardonable behaviour is completely unacceptable","cn":"不可宽恕的﹐不可原谅的"}]},"media":{"uk":"media/ldoce/hwd/bre/4/unpardonable0205.mp3","us":"media/ldoce/hwd/ame/0/laadunpardonable.mp3"},"examples":[{"en":"an unpardonable offence","cn":"不可饶恕的罪行"}],"oxford":{"phon":"ʌnˈpɑːdnəbl","pos":"adjective","senses":[{"en":"that cannot be forgiven or excused","cn":"不可饶恕的；不可原谅的"}]}},"unspecified":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未说明的；不明确的","en":"You say that something is unspecified when you are not told exactly what it is.","ex":{"en":"The government said an unspecified number of bandits were killed","cn":"政府称已歼灭若干路匪。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not known or not stated","cn":"未具体说明的﹔未详述的"}]},"vocab":{"pos":"adj","senses":[{"en":"If something's unspecified , you don't know the specifics, at least not yet. If your housemate offers to trade this week's dishes for next week's dusting and an unspecified chore to be named later, you should consider this offer carefully."}]},"media":{"uk":"media/ldoce/hwd/bre/2/brelasdeunspecified.mp3","us":"media/ldoce/hwd/ame/6/laadunspecified.mp3"},"examples":[{"en":"The story takes place at an unspecified date.","cn":"故事发生的日期不明。"},{"en":"The meeting will take place at an unspecified date in the future.","cn":"会议将于日后召开﹐具体日期不确定。"}],"oxford":{"phon":"ʌnˈspesɪfaɪd","pos":"adjective","senses":[{"en":"not stated clearly or definitely; not having been specified","cn":"未说明的；不明确的","ex":{"en":"The story takes place at an unspecified date.","cn":"故事发生的日期不明。"}}]}},"underarm":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"腋下的；腋窝的","en":"Underarm means in or for the areas under your arms, where they are joined to your body.","ex":{"en":"...underarm deodorants.","cn":"腋下除臭剂"}},{"pos":"ADJ 形容词","cn":"（投球等）低手的，手不过肩的","en":"You use underarm to describe actions, such as throwing a ball, in which you do not raise your arm above your shoulder.","ex":{"en":"...an underarm throw.","cn":"低手投球"}}]},"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"if you throw a ball underarm, you throw it without moving your arm above your shoulder 〔","cn":"体育运动中投球〕下手，手臂不过肩"},{"en":"relating to or used on your armpit s","cn":"腋窝的﹐腋下的"},{"en":"an underarm throw is one where you throw a ball without moving your arm above your shoulder 〔","cn":"体育运动中投球〕下手的，手臂不过肩的"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41underarm2.mp3","us":"media/ldoce/hwd/ame/1/ld41underarm.mp3"},"examples":[{"en":"underarm hair/deodorant/sweating","cn":"腋毛；腋下除臭剂；腋下出汗"},{"en":"underarm hair","cn":"腋毛"}],"oxford":{"phon":"ˈʌndərɑːm","pos":"adjective","senses":[{"en":"connected with a person’s armpit","cn":"腋窝的；腋下的","g":"[only before noun]","ex":{"en":"underarm hair/deodorant/sweating","cn":"腋毛；腋下除臭剂；腋下出汗"}},{"en":"an underarm throw of a ball is done with your hand kept below the level of your shoulder","cn":"下手（或低手）投球的"},{"en":"if you throw, etc. underarm, you throw keeping your hand below the level of your shoulder","cn":"下手地，低手地（投球等）","pos":"adverb"}]}},"unprofessional":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"未达专业水准的；不专业的；外行的","en":"If you use unprofessional to describe someone's behaviour at work, you are criticizing them for not behaving according to the standards that are expected of a person in their profession.","ex":{"en":"What she did was very unprofessional. She left abruptly about 90 minutes into the show","cn":"她的表现很不专业，在节目进行到90分钟的时候就突然离开了。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"behaving in a way that is not acceptable in a particular profession","cn":"违反行业准则的"}]},"media":{"uk":"media/ldoce/hwd/bre/1/unprofessional0205.mp3","us":"media/ldoce/hwd/ame/a/unprofessional.mp3"},"examples":[{"en":"She was found guilty of unprofessional conduct.","cn":"她因违反职业道德而被判罪。"},{"en":"Johnson was fired for unprofessional conduct.","cn":"约翰逊因为有违反职业道德的行为而被开除了。"}],"oxford":{"phon":"ˌʌnprəˈfeʃənl","pos":"adjective","senses":[{"en":"not reaching the standard expected in a particular profession","cn":"未达专业水平的；违反职业道德的","ex":{"en":"She was found guilty of unprofessional conduct.","cn":"她因违反职业道德而被判罪。"}}]}},"umber":{"collins":{"senses":[{"pos":"COLOUR 颜色词","cn":"红棕色；赭色","en":"Umber is used to describe things that are yellowish or reddish brown in colour.","ex":{"en":"...umber paint.","cn":"赭色油漆"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a brown colour like earth","cn":"棕土色，赭色"}]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41umber.mp3","us":"media/ldoce/hwd/ame/5/umber.mp3"},"oxford":{"phon":"ˈʌmbə(r)","pos":"noun","senses":[{"en":"a dark brown or yellow-brown colour used in paints","cn":"（颜料中用的）棕土色，赭土色"}]}},"unsocial":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"加班(工时)的；在非正常工作时间的","en":"If someone works unsocial hours, they work late at night, early in the morning, at weekends, or on public holidays. In Britain, people are often paid extra for working unsocial hours."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"to work during the night or early in the morning when most people do not have to work","cn":"在非正常时间上班〔即夜班﹑早班等〕"}]},"media":{"uk":"media/ldoce/hwd/bre/6/brelasdeunsocial.mp3","us":"media/ldoce/hwd/ame/0/amelasdeunsocial.mp3"},"examples":[{"en":"I work long and unsocial hours.","cn":"我工作时间长，且在非正常时间上班。"}],"oxford":{"phon":"ˌʌnˈsəʊʃl","pos":"adjective","senses":[{"en":"outside the normal times of working","cn":"非正常工作时间的；正常工作时间以外的","ex":{"en":"I work long and unsocial hours.","cn":"我工作时间长，且在非正常时间上班。"}}]}},"unformed":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未成形的；不成熟的","en":"If you describe someone or something as unformed, you mean that they are in an early stage of development and not fully formed or matured.","ex":{"en":"The market for which they are competing is still unformed.","cn":"他们角逐的市场尚未成形。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not yet developed","cn":"未成形的﹔未充分发展的"}]},"media":{"uk":"media/ldoce/hwd/bre/1/unformed0205.mp3","us":"media/ldoce/hwd/ame/0/laadunformed.mp3"},"examples":[{"en":"unformed ideas","cn":"不成熟的意见"},{"en":"the unformed mind of a child","cn":"儿童未发育完善的大脑"}],"oxford":{"phon":"ˌʌnˈfɔːmd","pos":"adjective","senses":[{"en":"not fully developed","cn":"发展不充分的；未成形的；不成熟的","ex":{"en":"unformed ideas","cn":"不成熟的意见"}}]}},"uniformity":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"统一（性);一致（性）；规则（性）","en":"If there is uniformity in something such as a system, organization, or group of countries, the same rules, ideas, or methods are applied in all parts of it.","ex":{"en":"Spanish liberals sought to create linguistic as well as administrative uniformity.","cn":"西班牙自由主义者寻求语言及行政上的统一。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the quality of being or looking the same as all other members of a group","cn":"相同(性)﹔统一(性)﹔一致(性)"}]},"vocab":{"pos":"n","senses":[{"en":"Have you ever noticed that even though you and your friend have different history teachers, you are both learning the same thing? That is because of the uniformity , or consistency, of the curriculum."}]},"collocations":{"phrases":["ADJ. broad | great | bland, drab, dull","VERB + UNIFORMITY achieve, ensure, impose","PREP. ~ in Government inspections ensure a high degree of uniformity in the standard of service."]},"media":{"uk":"media/ldoce/hwd/bre/f/uniformity0205.mp3","us":"media/ldoce/hwd/ame/5/laaduniformity.mp3"},"examples":[{"en":"They tried to ensure uniformity across the different departments.","cn":"他们努力保证各部门之间的统一。"},{"en":"the drab uniformity of the houses","cn":"这些房屋的千篇一律"}],"oxford":{"phon":"ˌjuːnɪˈfɔːməti","pos":"noun","senses":[{"en":"the fact of not varying and of being the same in all parts and at all times","cn":"一致的；统一的；一律的","ex":{"en":"They tried to ensure uniformity across the different departments.","cn":"他们努力确保各部门之间协调一致。"}}]}},"ululate":{"collins":{"senses":[{"pos":"VERB 动词","cn":"号叫；大呼小叫","en":"If someone ululates, they make quickly repeated loud sounds, often to express sorrow or happiness.","ex":{"en":"They ululated like Red Indians","cn":"他们像印第安人一样大呼小叫。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to cry out with a long high sound, especially because you are very sad or in pain","cn":"嚎叫﹐长啸﹔哀号"}]},"vocab":{"pos":"v","senses":[{"en":"To ululate is to loudly howl or wail. Animals ululate , and so do people in pain."}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld45ululate.mp3","us":"media/ldoce/hwd/ame/4/laadululate.mp3"},"oxford":{"phon":"ˈʌljuleɪt","pos":"verb","senses":[{"en":"to give a long, loud call","cn":"嚎叫；大叫；长啸"}]}},"unenviable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不值得羡慕的；令人不快的；尴尬的","en":"If you describe a situation or task as unenviable, you mean that nobody would enjoy dealing with it because it is very difficult, dangerous, or unpleasant.","ex":{"en":"She had the unenviable task of making the first few phone calls","cn":"她接受了这个令人为难的差事，负责打头几个电话。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"difficult and unpleasant","cn":"艰难的﹔令人不快的﹔讨厌的"},{"en":"unenviable task/job etc (of doing something) the unenviable task of informing the victim’s relations","cn":"通知受害人亲属的为难差事 Edward III was in a delicate and unenviable position . 爱德华三世处境微妙而尴尬。"}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41unenviable.mp3","us":"media/ldoce/hwd/ame/5/unenviable.mp3"},"examples":[{"en":"She was given the unenviable task of informing the losers.","cn":"让她去通知失败的人，真不是什么好差事。"}],"oxford":{"phon":"ʌnˈenviəbl","pos":"adjective","senses":[{"en":"difficult or unpleasant; that you would not want to have","cn":"艰难的；讨厌的；不值得羡慕的","ex":{"en":"She was given the unenviable task of informing the losers.","cn":"让她去通知失败的人，真不是什么好差事。"}}]}},"upstate":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"州的最边远地区的；州的最北部地区的","en":"Upstate means belonging or relating to the parts of a state that are furthest to the north or furthest from the main city.","ex":{"en":"...an idyllic village in upstate New York.","cn":"纽约州最北部的一个恬静村庄"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"in the northern part of a particular state 〔","cn":"州的〕北部地区的"}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41upstate.mp3","us":"media/ldoce/hwd/ame/d/upstate.mp3"},"examples":[{"en":"They retired and went to live upstate.","cn":"他们退休后移居到州的乡野地区去了。"},{"en":"upstate New York","cn":"纽约的北部"}],"oxford":{"phon":"ˌʌpˈsteɪt","pos":"adverb","senses":[{"en":"in or to a part of a state that is far from its main cities, especially a northern part","cn":"在（或向）州的乡野地区（尤指北部）","ex":{"en":"They retired and went to live upstate.","cn":"他们退休后移居到州的乡野地区去了。"}},{"en":"in a part of a state that is far from its main cities, especially a northern part","cn":"在（或向）州的乡野地区（尤指北部）","ex":{"en":"upstate New York","cn":"纽约州北部城郊区"},"pos":"adjective"}]}},"unrestricted":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"不受拘束的；没有限制的","en":"If an activity is unrestricted, you are free to do it in the way that you want, without being limited by any rules.","ex":{"en":"Freedom to pursue extracurricular activities is totally unrestricted","cn":"参加课外活动的自由完全不受限制。"}},{"pos":"ADJ 形容词","cn":"完整的；清晰的","en":"If you have an unrestricted view of something, you can see it fully and clearly, because there is nothing in the way.","ex":{"en":"Nearly all seats have an unrestricted view.","cn":"几乎在所有的座位上都可以看到完整清晰的画面。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not restricted by any rules or orders","cn":""},{"en":"if an activity or event is open , anyone can take part in it","cn":""},{"en":"not restricted by time, length, subject etc","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"When something is unrestricted , it means there are no restrictions placed on it. A restriction is a rule about a way that something can be used."}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41unrestricted.mp3","us":"media/ldoce/hwd/ame/5/laadunrestricted.mp3"},"examples":[{"en":"We have unrestricted access to all the facilities.","cn":"我们可随意使用一切设施。"},{"en":"unrestricted access to information","cn":"随意获取信息"}],"oxford":{"phon":"ˌʌnrɪˈstrɪktɪd","pos":"adjective","senses":[{"en":"not limited or controlled in any way","cn":"没有限制的","ex":{"en":"We have unrestricted access to all the facilities.","cn":"我们可随意使用一切设施。"}}]}},"unlawful":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"不合法的；非法的；违法的","en":"If something is unlawful, the law does not allow you to do it.","ex":{"en":"...employees who believe their dismissal was unlawful","cn":"认为将他们解雇是违法行为的雇员"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"forbidden by law","cn":""},{"en":"to be illegal. This phrase is very commonly used in everyday English, instead of saying that something is illegal","cn":""},{"en":"illegal – a rather formal word, which is used especially when this particular action is considered to be illegal, although there are some situations where such actions can be legal","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/7/unlawful0205.mp3","us":"media/ldoce/hwd/ame/f/unlawful.mp3"},"examples":[{"en":"The jury returned a verdict of unlawful killing.","cn":"陪审团作出了非法杀害的裁决。"}],"oxford":{"phon":"ʌnˈlɔːfl","pos":"adjective","senses":[{"en":"not allowed by the law","cn":"不合法的；非法的；违法的","ex":{"en":"He was convicted of unlawful possession of a firearm.","cn":"他被判非法持有枪支罪。"}}]}},"unduly":{"collins":{"senses":[{"pos":"ADV 副词","cn":"过分地；过度地；不适当地；不必要地","en":"If you say that something does not happen or is not done unduly, you mean that it does not happen or is not done to an excessive or unnecessary extent.","ex":{"en":"'But you're not unduly worried about doing this report?' — 'No.'","cn":"“但是你没有过于担心如何写这个报告？”——“没有。”"}}]},"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"more than is normal or reasonable","cn":"过度地﹐过分地"},{"en":"unduly worried/concerned/anxious etc She doesn’t seem unduly concerned about her exams.","cn":"她似乎对考试并未过分担忧。 It didn’t trouble me unduly. 这事并没有让我太烦恼。"}]},"vocab":{"pos":"adv","senses":[{"en":"If something is done unduly , it's done out of proportion with what's reasonable or right. If you're unduly treated, you're not treated in the way you deserve to be."}]},"media":{"uk":"media/ldoce/hwd/bre/e/unduly0205.mp3","us":"media/ldoce/hwd/ame/1/unduly.mp3"},"examples":[{"en":"He did not sound unduly worried at the prospect.","cn":"他的口气听上去对前景并不十分担忧。"},{"en":"The thought did not disturb her unduly.","cn":"这个想法并没有让她过分烦恼。"}],"oxford":{"phon":"ˌʌnˈdjuːli","pos":"adverb","senses":[{"en":"more than you think is reasonable or necessary","cn":"过分；过度；不适当地","ex":{"en":"He did not sound unduly worried at the prospect.","cn":"他的口气听上去对前景并不十分担忧。"}}]}},"uptown":{"collins":{"senses":[{"pos":"ADV 副词","cn":"往(或在)城外;往(或在)城镇的非商业区","en":"If you go uptown, or go to a place uptown, you go away from the centre of a town or city towards the edge. Uptown sometimes refers to a part of the city other than the main business district.","ex":{"en":"He rode uptown and made his way to Bob's apartment","cn":"他乘车前往城外鲍勃的公寓。"}}]},"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"in or towards an area of a city that is away from the centre, especially one where the streets have larger numbers in their names and where people have more money","cn":"在[向]城郊﹔在[向]富人区"}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41uptown.mp3","us":"media/ldoce/hwd/ame/a/uptown.mp3"},"examples":[{"en":"We walked uptown a couple of blocks until we found a cab.","cn":"我们向市郊走了好几条街才找到一辆出租车。"},{"en":"They live in an apartment uptown.","cn":"他们住在市郊的一套公寓。"}],"oxford":{"phon":"ˌʌpˈtaʊn","pos":"adverb","senses":[{"en":"in or to the parts of a town or city that are away from the centre, where people live","cn":"离开市中心；在（或向）市郊","ex":{"en":"They live in an apartment uptown.","cn":"他们住在市郊的一套公寓。"}},{"en":"in, to or typical of the parts of a town or city that are away from the centre, where people live","cn":"在（或向）市郊住宅区的；市郊住宅区的","g":"[only before noun]","ex":{"en":"an uptown train","cn":"开往市郊住宅区的火车"},"pos":"adjective"},{"en":"typical of an area of a town or city where people have a lot of money","cn":"富人区的","ex":{"en":"uptown prices","cn":"富人区的价格"},"pos":"adjective"}]}},"unconnected":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无关联的；不相关的","en":"If one thing is unconnected with another or the two things are unconnected, the things are not related to each other in any way.","ex":{"en":"She was known to have had personal problems unconnected with her marriage","cn":"据悉，她有过一些与婚姻不相干的个人问题。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not connected in any way","cn":""},{"en":"to not be connected with something in any way","cn":""},{"en":"to not be connected with something or someone in any way","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/6/unconnected0205.mp3","us":"media/ldoce/hwd/ame/3/laadunconnected.mp3"},"examples":[{"en":"My resignation was totally unconnected with recent events.","cn":"我的辞职与最近的事件毫不相干。"},{"en":"The two crimes are apparently unconnected.","cn":"这两起犯罪显然没有关联。"}],"oxford":{"phon":"ˌʌnkəˈnektɪd","pos":"adjective","senses":[{"en":"not related or connected in any way","cn":"不相关的；无联系的","ex":{"en":"The two crimes are apparently unconnected.","cn":"这两起犯罪显然没有关联。"}}]}},"unthinking":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"莽撞的；不顾后果的；没头脑的","en":"If you say that someone is unthinking, you are critical of them because you consider that they do not think carefully about the effects of their behaviour.","ex":{"en":"He doesn't say those silly things that unthinking people say","cn":"他并没有像没头脑的人那样说蠢话。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not thinking about the effects of something you say or do","cn":"不考虑后果的"}]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41unthinking.mp3","us":"media/ldoce/hwd/ame/3/unthinking.mp3"},"oxford":{"phon":"ʌnˈθɪŋkɪŋ","pos":"adjective","senses":[{"en":"not thinking about the effects of what you do or say","cn":"不计后果的；考虑不周的；不动脑筋的","ex":{"en":"Unthinking, he started to cross the road.","cn":"他想也不想就开始横穿马路。"}}]}},"underage":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"too young to legally buy alcohol, drive a car, vote etc","cn":"未成年的﹐未及法定年龄的"}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41underage.mp3","us":"media/ldoce/hwd/ame/c/underage.mp3"},"examples":[{"en":"underage drinking","cn":"未成年饮酒"}],"oxford":{"phon":"ˈʌndəreɪdʒ","pos":"adjective","senses":[{"en":"done by people who are too young by law","cn":"未达到法定年龄的人所做的；未成年人的","ex":{"en":"underage drinking","cn":"未成年饮酒"}}]}},"unisex":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"不分男女的；男女通用的","en":"Unisex is used to describe things, usually clothes or places, which are designed for use by both men and women rather than by only one sex.","ex":{"en":"...the classic unisex hair salon","cn":"男女皆可光顾的传统理发店"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a mixed school, class, group etc is for people of both sexes","cn":""},{"en":"a school, camp etc that is coed is for students or other people of both sexes","cn":""},{"en":"use this for describing places that are for both men and women, especially when these places are usually for either men or women","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/4/unisex0205.mp3","us":"media/ldoce/hwd/ame/c/unisex.mp3"},"examples":[{"en":"unisex jeans","cn":"男女都能穿的牛仔裤"},{"en":"a unisex hair salon","cn":"男女美发店"}],"oxford":{"phon":"ˈjuːnɪseks","pos":"adjective","senses":[{"en":"intended for or used by both men and women","cn":"男女皆宜的；不分性别的","ex":{"en":"a unisex hair salon","cn":"男女美发店"}}]}},"undies":{"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"女式内衣","en":"You can refer to a woman or girl's underwear as their undies ."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"underwear","cn":"内衣裤"}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41undies.mp3","us":"media/ldoce/hwd/ame/3/undies.mp3"},"oxford":{"phon":"ˈʌndiz","pos":"noun","senses":[{"en":"underwear","cn":"内衣；衬衣"}]}},"unhurt":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"没有受伤的；安然无恙的","en":"If someone who has been attacked, or involved in an accident, is unhurt, they are not injured.","ex":{"en":"The lorry driver escaped unhurt, but a pedestrian was injured","cn":"卡车司机安然脱险，但有一位行人受了伤。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"to not be hurt, even though you have been in a dangerous situation such as an accident","cn":""},{"en":"to not be hurt or harmed, even though you have been in a dangerous situation","cn":""},{"en":"if you have a dangerous experience and escape from it without a scratch , you do not have any injury at all, because you have been very lucky","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/5/brelasdeunhurt.mp3","us":"media/ldoce/hwd/ame/0/laadunhurt.mp3"},"examples":[{"en":"He escaped from the crash unhurt.","cn":"他平安逃过了这场车祸。"},{"en":"The driver escaped unhurt from the accident.","cn":"司机安然无恙地逃过了这场车祸。"}],"oxford":{"phon":"ʌnˈhɜːt","pos":"adjective","senses":[{"en":"not injured or harmed","cn":"未受伤；未受伤害；平安；安然无恙","ex":{"en":"He escaped from the crash unhurt.","cn":"他平安逃过了这场车祸。"}}]}},"unzip":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"拉开（拉链）","en":"When you unzip something which is fastened by a zip or when it unzips, you open it by pulling open the zip.","ex":{"en":"James unzipped his bag","cn":"詹姆斯把自己包上的拉链拉开。"}},{"pos":"VERB 动词","cn":"解压缩","en":"To unzip a computer file means to open a file that has been compressed.","ex":{"en":"Unzip the icons into a sub-directory.","cn":"把图标解压到一个子目录里。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to join together the two sides of a piece of clothing, bag, belt etc","cn":""},{"en":"to fasten something firmly to another object or surface, using screws, nails, tape, glue etc","cn":""},{"en":"to connect or fasten things together","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/0/unzip0205.mp3","us":"media/ldoce/hwd/ame/c/unzip.mp3"},"oxford":{"phon":"ˌʌnˈzɪp","pos":"verb","senses":[{"en":"if you unzip a piece of clothing, a bag, etc., or if it unzips, you open the zip that fastens it","cn":"拉开…的拉锁；…的拉锁被拉开","g":"[transitive, intransitive]","ex":{"en":"She unzipped his jacket, as if he were a child.","cn":"她拉开他的上衣拉链，仿佛他是一个孩子。"}},{"en":"to return a file to its original size after it has been compressed (= made smaller)","cn":"解压缩（文件）","g":"[transitive]","lab":"computing"}]}},"unscramble":{"collins":{"senses":[{"pos":"VERB 动词","cn":"整理；使有条理","en":"To unscramble things that are in a state of confusion or disorder means to arrange them so that they can be understood or seen clearly.","ex":{"en":"All you have to do to win is unscramble the words here to find four names of birds.","cn":"只要你能从这些单词中找到四种鸟的名称你就赢了。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to change a television signal or a message that has been sent in code (= a deliberately confusing way ) so that it can be seen or read","cn":"解读〔电视信号〕﹔译出〔密码〕"},{"en":"to make a confusing situation or confusing feelings easier to understand","cn":"整理﹐理清﹐理顺〔混乱的情形或情绪〕"}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41unscramble.mp3","us":"media/ldoce/hwd/ame/6/unscramble.mp3"},"oxford":{"phon":"ˌʌnˈskræmbl","pos":"verb","senses":[{"en":"to change a word, message, television signal, etc. that has been sent in a code so that it can be read or understood","cn":"使（信息、信号等）还原；译出（密码）；解码"},{"en":"to arrange something that is confused or in the wrong order in a clear, correct way","cn":"整理；清理；使条理化"}]}},"unforeseen":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"出乎意料的；未预见到的","en":"If something that has happened was unforeseen, it was not expected to happen or known about beforehand.","ex":{"en":"Radiation may damage cells in a way that was previously unforeseen","cn":"辐射可能以一种我们过去未能预见到的方式破坏细胞。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"something that is unexpected surprises you because you did not expect it","cn":""},{"en":"situations, problems, changes etc that you did not expect or prepare for, and which usually cause you difficulty","cn":""},{"en":"if something that happens is a surprise or comes as a surprise , you did not expect it to happen, and so you are surprised by it","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Something unforeseen is something that could not be predicted and was not expected. It's a surprise."}]},"media":{"uk":"media/ldoce/hwd/bre/4/brelasdeunforeseen.mp3","us":"media/ldoce/hwd/ame/5/unforeseen.mp3"},"examples":[{"en":"The project was running late owing to unforeseen circumstances.","cn":"这个项目因意外情况而拖延了。"},{"en":"unforeseen delays/problems","cn":"意外的延误/问题"}],"oxford":{"phon":"ˌʌnfɔːˈsiːn","pos":"adjective","senses":[{"en":"that you did not expect to happen","cn":"未想到的；始料不及的","ex":{"en":"unforeseen delays/problems","cn":"意外的延误／问题"}}]}},"umpteen":{"collins":{"senses":[{"pos":"DET 限定词","cn":"无数的；大量的；许许多多的","en":"Umpteen can be used to refer to an extremely large number of things or people.","ex":{"en":"He was interrupted by applause umpteen times","cn":"他无数次被掌声打断。"}}]},"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"very many – used especially when you are annoyed there are so many","cn":"无数的﹐许许多多的〔尤用于感到恼怒时〕"}]},"media":{"uk":"media/ldoce/hwd/bre/9/umpteen0205.mp3","us":"media/ldoce/hwd/ame/0/amelasdeumpteen.mp3"},"examples":[{"en":"‘This is crazy,’ she told herself for the umpteenth time (= she had done it many times before). “","cn":"这简直疯了！”她已无数次这般地自言自语着。"},{"en":"I've told this story umpteen times.","cn":"这个故事我已讲了无数次了。"}],"oxford":{"phon":"ˌʌmpˈtiːn","pos":"determiner","senses":[{"en":"very many","cn":"大量；很多","ex":{"en":"I've told this story umpteen times.","cn":"这个故事我已讲了无数次了。"}},{"en":"very many","cn":"大量；很多","ex":{"en":"Umpteen of them all arrived at once.","cn":"他们大批人同时到达了。"},"pos":"pronoun"}]}},"unbeatable":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"无与伦比的；无可匹敌的","en":"If you describe something as unbeatable, you mean that it is the best thing of its kind.","ex":{"en":"These resorts, like Magaluf and Arenal, remain unbeatable in terms of price.","cn":"像马加拉夫和阿雷纳尔这样的度假胜地，在价格方面仍具有绝对的优势。"}},{"pos":"ADJ 形容词","cn":"无法战胜的；无敌的","en":"In a game or competition, if you describe a person or team as unbeatable, you mean that they win so often, or perform so well that they are unlikely to be beaten by anyone.","ex":{"en":"The opposition was unbeatable","cn":"对手实力超群。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"something that is unbeatable is the best of its kind","cn":"无与伦比的，〔同类中〕最好的"},{"en":"a team, player etc that is unbeatable cannot be defeated","cn":"打不垮的﹐无法击败的"}]},"collocations":{"phrases":["VERBS be, look, seem The French team looks unbeatable. | become | remain United remain unbeatable at the top of the League.","ADV. almost, virtually He now has an almost unbeatable lead over his rivals."]},"media":{"uk":"media/ldoce/hwd/bre/c/unbeatable0205.mp3","us":"media/ldoce/hwd/ame/e/unbeatable.mp3"},"examples":[{"en":"unbeatable offers","cn":"最优惠的报价"},{"en":"carpets at unbeatable prices","cn":"价格最优惠的地毯"}],"oxford":{"phon":"ʌnˈbiːtəbl","pos":"adjective","senses":[{"en":"impossible to defeat","cn":"难以击败的；打不垮的","ex":{"en":"This year the team has shown itself to be almost unbeatable.","cn":"今年，这支球队已经证明了自己几乎是不可战胜的。"}},{"en":"impossible to improve","cn":"已达极限的；难以竞争的","ex":{"en":"unbeatable offers","cn":"最优惠的报价"}}]}},"unquestionable":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"显然的；不容置疑的","en":"If you describe something as unquestionable, you are emphasizing that it is so obviously true or real that nobody can doubt it.","ex":{"en":"He inspires affection and respect as a man of unquestionable integrity","cn":"他无可争议的忠诚正直赢得了人们的爱戴和尊敬。"}}]},"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"use this to emphasize that something is definitely true. Definitely is more common in spoken English than certainly","cn":""},{"en":"use this to say that, in your opinion, something is definitely true about someone or something","cn":""},{"en":"use this to say that, in your opinion, something definitely is true about someone or something","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/1/brelasdeunquestionably.mp3","us":"media/ldoce/hwd/ame/e/amelasdeunquestionably.mp3"},"examples":[{"en":"It was unquestionably a step in the right direction.","cn":"这无疑是朝正确方向迈出的一步。"},{"en":"a man of unquestionable honesty","cn":"绝对诚实的人"}],"oxford":{"phon":"ʌnˈkwestʃənəbl","pos":"adjective","senses":[{"en":"that cannot be doubted","cn":"无疑的；无可非议的；确实的","ex":{"en":"a man of unquestionable honesty","cn":"绝对诚实的人"}}]}},"unconvinced":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"不信服的；不确定的","en":"If you are unconvinced that something is true or right, you are not at all certain that it is true or right.","ex":{"en":"Most consumers seem unconvinced that the recession is over","cn":"大多数消费者似乎都不相信经济衰退已经过去。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not persuaded that something is true or good","cn":"未被说服的﹔不信服的"}]},"vocab":{"pos":"adj","senses":[{"en":"If you're just not buying it, you're unconvinced . When it comes to music, people will often try to sway you to their way of thinking — that a band is THE band — especially if you remain unconvinced ."}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld5_unconvinced.mp3","us":"media/ldoce/hwd/ame/e/ld5_unconvinced.mp3"},"examples":[{"en":"She seemed unconvinced by their promises.","cn":"她似乎不相信他们的许诺。"},{"en":"The jury were unconvinced that he was innocent.","cn":"陪审团不相信他是无辜的。"}],"oxford":{"phon":"ˌʌnkənˈvɪnst","pos":"adjective","senses":[{"en":"not believing or not certain about something despite what you have been told","cn":"不信服的；未被说服的","ex":{"en":"I remain unconvinced of the need for change.","cn":"我仍怀疑改革的必要性。"}}]}},"unremarkable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"一般的；普通的","en":"If you describe someone or something as unremarkable, you mean that they are very ordinary, without many exciting, original, or attractive qualities.","ex":{"en":"...a tall, lean man, with an unremarkable face.","cn":"又高又瘦、长相一般的男人"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a person or object that is nondescript is not at all interesting to look at because they have no special or unusual features","cn":""},{"en":"very ordinary and not containing anything interesting, shocking etc, often in order to avoid offending or upsetting anyone","cn":""},{"en":"someone or something that is unremarkable is very ordinary and not especially different from most other people or things","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/4/unremarkable0205.mp3","us":"media/ldoce/hwd/ame/d/laadunremarkable.mp3"},"examples":[{"en":"an unremarkable life","cn":"平淡的生活"},{"en":"He led a busy but otherwise unremarkable life.","cn":"他过着忙忙碌碌却又平平淡淡的生活。"}],"oxford":{"phon":"ˌʌnrɪˈmɑːkəbl","pos":"adjective","senses":[{"en":"ordinary; not special in any way","cn":"普通的；寻常的；毫无特色的","ex":{"en":"an unremarkable life","cn":"平淡的生活"}}]}},"unscientific":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不科学的；无科学知识的","en":"Research or treatment that is unscientific is not likely to be good because it is not based on facts or is not done in the proper way.","ex":{"en":"No member of the team was medically qualified and its methods were considered totally unscientific.","cn":"这支队伍中的成员没有一个具有行医资格，而且他们使用的方法也被认为根本不科学。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not based on facts or the usual scientific methods of doing something","cn":"不科学的﹐没有科学道理的"}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41unscientific.mp3","us":"media/ldoce/hwd/ame/a/laadunscientific.mp3"},"examples":[{"en":"an unscientific approach to a problem","cn":"非科学的解决问题方式"},{"en":"unscientific ideas","cn":"不科学的想法"}],"oxford":{"phon":"ˌʌnˌsaɪənˈtɪfɪk","pos":"adjective","senses":[{"en":"not scientific; not done in a careful, logical way","cn":"不科学的；非科学的；违背科学方法的","ex":{"en":"an unscientific approach to a problem","cn":"非科学的解决问题方式"}}]}},"unaccompanied":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"无人陪伴的；独自的","en":"If someone is unaccompanied, they are alone.","ex":{"en":"It is estimated that every year 50 unaccompanied children arrive in Britain","cn":"据估计,每年有50名儿童独自来到英国。"}},{"pos":"ADJ 形容词","cn":"（行李、货物等）单独运送的，不随主人同行的","en":"Unaccompanied luggage or goods are being sent or transported separately from their owner.","ex":{"en":"Unaccompanied bags are either searched or removed.","cn":"单独运送的包裹或是遭到搜查，或是被搬走。"}},{"pos":"ADJ 形容词","cn":"无伴奏的；清唱的；独奏的","en":"An unaccompanied voice or instrument sings or plays alone, with no other instruments playing at the same time.","ex":{"en":"...an unaccompanied flute","cn":"独奏的长笛"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if you are alone, on your own, or by yourself, you are in a place and no-one else is there with you","cn":""},{"en":"if you go somewhere unaccompanied, you go there alone, especially when it is more usual to be with someone else","cn":""},{"en":"when you are alone, especially when you want to be alone because this gives you time to think, work etc","cn":""}]},"vocab":{"pos":"adj adv","senses":[{"en":"When you show up on your own at a social function, you are unaccompanied , meaning you’ve got no date."}]},"media":{"uk":"media/ldoce/hwd/bre/0/brelasdeunaccompanied.mp3","us":"media/ldoce/hwd/ame/d/unaccompanied.mp3"},"examples":[{"en":"Mere words, unaccompanied by any violence, cannot amount to an assault.","cn":"只有言语而未伴随暴力不能算侵犯人身。"},{"en":"No unaccompanied children allowed.","cn":"无大人带领的儿童不许进入。"}],"oxford":{"phon":"ˌʌnəˈkʌmpənid","pos":"adjective","senses":[{"en":"without a person going together with somebody/something","cn":"无人陪伴（或同行）的","lab":"formal","ex":{"en":"No unaccompanied children allowed.","cn":"儿童无大人陪伴不许进入。"}},{"en":"performed without anyone else playing or singing at the same time","cn":"无伴奏的；无伴唱的","lab":"music","ex":{"en":"a sonata for unaccompanied violin","cn":"无伴奏小提琴奏鸣曲"}},{"en":"not together with a particular thing","cn":"没有；不伴有","lab":"formal","ex":{"en":"Mere words, unaccompanied by any violence, cannot amount to an assault.","cn":"只有言语而未伴随暴力不能算攻击。"}}]}},"untrue":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"不真实的；虚假的","en":"If a statement or idea is untrue, it is false and not based on facts.","ex":{"en":"The allegations were completely untrue","cn":"这些指控纯属捏造。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not true, because the person does not know the facts, or because they are lying","cn":""},{"en":"not true and not based on the facts, or not the real one","cn":""},{"en":"if what someone says or believes is happening is not the case, it is not happening and what they say or believe is not true","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/a/untrue0205.mp3","us":"media/ldoce/hwd/ame/a/untrue.mp3"},"examples":[{"en":"If he agreed to their demands, he would have to be untrue to his own principles.","cn":"假使答应他们的要求，他就得背叛自己的原则。"},{"en":"It is untrue to say that something like this could never happen again.","cn":"说这类事情再也不会发生是毫无事实根据的。"}],"oxford":{"phon":"ʌnˈtruː","pos":"adjective","senses":[{"en":"not true; not based on facts","cn":"不真实的；假的；无事实根据的","ex":{"en":"These accusations are totally untrue.","cn":"这些指控纯属捏造。"}},{"en":"not loyal to somebody/something; doing something that hurts or damages somebody/something","cn":"不忠实的；不忠诚的；背叛的","lab":"formal","ex":{"en":"If he agreed to their demands, he would have to be untrue to his own principles.","cn":"假使答应他们的要求，他就得背叛自己的原则。"}}]}},"unsigned":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"没签名的","en":"An unsigned document does not have anyone's signature on it.","ex":{"en":"The envelope contained a typed, unsigned letter demanding £75,000 in cash.","cn":"信封里装着一封打印的、没签名的信，索要75,000英镑。"}},{"pos":"ADJ 形容词","cn":"没签约的","en":"An unsigned band has not signed a contract with a company to produce CDs.","ex":{"en":"Fugazi are America's biggest unsigned alternative band.","cn":"弗格齐是美国最大的未签约的另类乐队。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"an unsigned letter or document has not been signed with someone’s name 〔","cn":"信件或文件〕没有署名[签名]的"},{"en":"an unsigned sports player or musician has not yet signed a contract to play for a sports team or record music for a company 〔","cn":"运动员或音乐人〕没有签约的"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41unsigned.mp3","us":"media/ldoce/hwd/ame/6/laadunsigned.mp3"},"oxford":{"phon":"ˌʌnˈsaɪnd","pos":"adjective","senses":[{"en":"not having been signed by somebody; without a signature","cn":"没签名的；无署名的","ex":{"en":"an unsigned letter to the editor","cn":"写给编辑的未署名的信"}},{"en":"not having a contract with a company or team","cn":"未（与公司或运动队）签约的","ex":{"en":"an unsigned band/player","cn":"未签约的乐队／运动员"}}]}},"unionized":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"已加入工会的；已组织工会的；工会化的","en":"Unionized workers belong to trade unions. If a company or place is unionized, most of the workers there belong to trade unions.","ex":{"en":"The contract would give unionized workers a 12 percent pay raise over three years","cn":"合同将给加入工会的工人今后3年12%的加薪。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if workers unionize or are unionized, they become members of a trade union","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41unionize.mp3","us":"media/ldoce/hwd/ame/d/laadunionize.mp3"}},"underscore":{"collins":{"senses":[{"pos":"VERB 动词","cn":"强调；突出；强化","en":"If something such as an action or an event underscores another, it draws attention to the other thing and emphasizes its importance.","ex":{"en":"The Labor Department figures underscore the shaky state of the economic recovery","cn":"劳工部的数据进一步印证了经济复苏状况的不稳定。"}},{"pos":"VERB 动词","cn":"在（字词、句子等）下画线","en":"If you underscore something such as a word or a sentence, you draw a line underneath it in order to make people notice it or give it extra importance.","ex":{"en":"He heavily underscored his note to Shelley.","cn":"他在给谢利的便条内容下面重重地画了线。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to say strongly or show clearly that a fact, idea etc is especially important","cn":""},{"en":"to emphasize something when you are talking about a subject","cn":""},{"en":"to show that something is important, so that people will pay special attention to it","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"To underscore is to draw special attention to a fact, idea, or situation. When you're involved in a debate, it’s wise to underscore the points that best support your argument."}]},"media":{"uk":"media/ldoce/hwd/bre/6/brelasdeunderscore.mp3","us":"media/ldoce/hwd/ame/7/underscore.mp3"},"oxford":{"phon":"ˌʌndəˈskɔː(r)","pos":"verb","senses":[{"en":"to draw a line under a word, sentence, etc.","cn":"在（词语等下）画线；画底线标出","ex":{"en":"The word ‘not’ was heavily underscored.","cn":"“不”这个词被重重地强调了。"}},{"en":"to emphasize or show that something is important or true","cn":"强调；突出","ex":{"en":"His speech underscored the need for a clear policy.","cn":"他的演讲强调了明确政策的必要性。"}},{"en":"the symbol (_ ) that is used to draw a line between letters or words, especially in computer commands and internet addresses","cn":"下划线（用于字母或单词之间，尤见于计算机命令和网址）","pos":"noun"}]}},"undersized":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"小于一般尺寸的；偏小的","en":"Undersized people or things are smaller than usual, or smaller than they should be.","ex":{"en":"...undersized and underweight babies","cn":"偏小偏轻的婴儿"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"too small","cn":"太小的"}]},"vocab":{"pos":"adj","senses":[{"en":"The adjective undersized describes something that is smaller than usual. Your Great Dane is undersized if he fits comfortably on your lap."}]},"media":{"uk":"media/ldoce/hwd/bre/0/undersized0205.mp3","us":"media/ldoce/hwd/ame/f/undersized.mp3"},"oxford":{"phon":"ˌʌndəˈsaɪzd","pos":"adjective","senses":[{"en":"not as big as is expected or needed","cn":"小于正常（或一般）的","ex":{"en":"She held an undersized baby in her arms.","cn":"她怀里抱着一个身材矮小的婴儿。"}}]}},"utilitarianism":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"功利主义;实利主义","en":"Utilitarianism is the idea that the morally correct course of action is the one that produces benefit for the greatest number of people."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the political belief that an action is good if it helps the largest number of people","cn":"功利主义"}]},"vocab":{"pos":"n","senses":[{"en":"If you believe in utilitarianism , you believe that the most valuable things are the most useful — and useful to the greatest number of people possible."}]},"media":{"uk":"media/ldoce/hwd/bre/b/utilitarianism0205.mp3","us":"media/ldoce/hwd/ame/7/utilitarianism.mp3"},"oxford":{"phon":"ˌjuːtɪlɪˈteəriənɪzəm","pos":"noun","senses":[{"en":"the belief that the right course of action is the one that will produce the greatest happiness of the greatest number of people","cn":"功利主义"}]}},"utmost":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"极度的；最大的","en":"You can use utmost to emphasize the importance or seriousness of something or to emphasize the way that it is done.","ex":{"en":"It is a matter of the utmost urgency to find out what has happened to these people","cn":"当务之急是要弄清楚这些人出了什么事。"}},{"pos":"N-SING 单数名词","cn":"极度；极限；最大可能","en":"If you say that you are doing your utmost to do something, you are emphasizing that you are trying as hard as you can to do it.","ex":{"en":"He would have done his utmost to help her, of that she was certain","cn":"他肯定会尽最大努力帮她，这一点她非常肯定。"}},{"pos":"PHRASE 短语","cn":"尽力；极度","en":"If you say that something is done to the utmost, you are emphasizing that it is done to the greatest extent, amount, or degree possible.","ex":{"en":"My limited diplomatic skills were tested to the utmost","cn":"我有限的外交手腕儿受到了极其严峻的考验。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"the greatest possible importance etc","cn":"极为重要/尊敬/关心等"},{"en":"to try as hard as you can, even when the situation is difficult and you are not sure if you will succeed","cn":""},{"en":"to try as hard as you can to do something, even though it is difficult or you do not have enough time, money etc to do it really well","cn":""}]},"vocab":{"pos":"adj n","senses":[{"en":"Utmost means \"the greatest extent or amount.\" When you work as part as you possibly can, you do your utmost to accomplish your goal."}]},"media":{"uk":"media/ldoce/hwd/bre/e/utmost_n0205.mp3","us":"media/ldoce/hwd/ame/7/utmost1.mp3"},"examples":[{"en":"You should study this document with the utmost care.","cn":"你对这份文件的研究应该慎之又慎。"},{"en":"He did his utmost (= tried as hard as possible) to persuade me not to go.","cn":"他使尽浑身解数劝我别去。"}],"oxford":{"phon":"ˈʌtməʊst","pos":"adjective","senses":[{"en":"greatest; most extreme","cn":"最大的；极度的","ex":{"en":"This is a matter of the utmost importance.","cn":"这是个极其重要的问题。"}},{"en":"the greatest amount possible","cn":"最大量；最大限度；极限；最大可能","ex":{"en":"Our resources are strained to the utmost.","cn":"我们的资源极端紧缺。"},"pos":"noun"}]}},"uptight":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"紧张不安的；忧虑的;易怒的","en":"Someone who is uptight is tense, nervous, or annoyed about something and so is difficult to be with.","ex":{"en":"Penny never got uptight about exams","cn":"彭妮从来不会因为考试而紧张。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"angry and unfriendly, and often complaining about things","cn":""},{"en":"someone who is disagreeable is bad-tempered and very unfriendly and behaves in an unpleasant way towards people","cn":""},{"en":"often becoming annoyed or unhappy, especially when there seems to be no good reason to","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"To be uptight is to be tense. When you're uptight , you're stressed out and anxious."}]},"collocations":{"phrases":["VERBS be, feel, look, seem, sound | get Try to laugh at it instead of getting uptight. | make sb","ADV. really, very | all (informal) He gets all uptight if anyone criticizes him! | a bit, quite","PREP. about He's feeling a bit uptight about his exam tomorrow."]},"media":{"uk":"media/ldoce/hwd/bre/a/uptight0205.mp3","us":"media/ldoce/hwd/ame/9/uptight.mp3"},"examples":[{"en":"Relax! You're getting too uptight about it.","cn":"轻松点儿！你对这事太紧张了。"},{"en":"an uptight teenager","cn":"腼腆的少年"}],"oxford":{"phon":"ˌʌpˈtaɪt","pos":"adjective","senses":[{"en":"anxious and/or angry about something","cn":"紧张不安的；愤怒的","ex":{"en":"Relax! You're getting too uptight about it.","cn":"放松点儿！你对这事太紧张了。"}},{"en":"nervous about showing your feelings","cn":"局促的；拘谨的；紧张的","lab":"especially North American English","ex":{"en":"an uptight teenager","cn":"腼腆的少年"}}]}},"unmentionable":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"不愿提及的；羞于提起的","en":"If you describe something as unmentionable, you mean that it is too embarrassing or unpleasant to talk about.","ex":{"en":"Has he got some unmentionable disease?","cn":"他是不是得了什么难以启齿的病？"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"too shocking or embarrassing to talk about 〔","cn":"因太震惊或尴尬而〕说不出口的"}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41unmentionable.mp3","us":"media/ldoce/hwd/ame/e/unmentionable.mp3"},"examples":[{"en":"an unmentionable disease","cn":"羞于启齿的疾病"},{"en":"unmentionable scandals","cn":"难以启齿的丑闻"}],"oxford":{"phon":"ʌnˈmenʃənəbl","pos":"adjective","senses":[{"en":"too shocking or embarrassing to be mentioned or spoken about","cn":"不可提及的；不宜述说的；难以启齿的","ex":{"en":"an unmentionable disease","cn":"羞于启齿的疾病"}}]}},"unripe":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（果蔬）生的，未成熟的","en":"Unripe fruit or vegetables are not yet ready to eat.","ex":{"en":"I was only ill once and that came of eating an unripe pear.","cn":"我唯一一次生病是因为吃了未熟的梨。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if something is not ready , you cannot use it or eat it immediately","cn":""},{"en":"fruit that is unripe is not soft, sweet, or ready to eat","cn":""},{"en":"unripe fruit, grain etc is not fully developed or ready to be eaten","cn":"未成熟的﹐生的"}]},"media":{"uk":"media/ldoce/hwd/bre/c/unripe0205.mp3","us":"media/ldoce/hwd/ame/7/laadunripe.mp3"},"examples":[{"en":"unripe fruit","cn":"未熟的水果"}],"oxford":{"phon":"ˌʌnˈraɪp","pos":"adjective","senses":[{"en":"not yet ready to eat","cn":"（食物）未成熟的","ex":{"en":"unripe fruit","cn":"未熟的水果"}}]}},"undercover":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"秘密的;密探的;卧底的","en":"Undercover work involves secretly obtaining information for the government or the police.","ex":{"en":"...an undercover operation designed to catch drug smugglers.","cn":"抓捕毒贩的秘密行动"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"known about by only a few people, who have agreed not to tell anyone else","cn":""},{"en":"used about information, especially in business or government, that is secret and not intended to be shown or told to other people","cn":""},{"en":"used about information that the government has ordered to be kept secret from most people","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/2/undercover0205.mp3","us":"media/ldoce/hwd/ame/2/undercover.mp3"},"examples":[{"en":"The illegal payments were discovered by a journalist working undercover.","cn":"这些非法付款是一位暗中查访的新闻记者发现的。"},{"en":"an undercover operation/investigation","cn":"秘密行动/调查"}],"oxford":{"phon":"ˌʌndəˈkʌvə(r)","pos":"adjective","senses":[{"en":"working or done secretly in order to find out information for the police, a government, etc.","cn":"秘密工作的；暗中做的；私下进行的","ex":{"en":"an undercover agent","cn":"密探"}},{"en":"secretly, in order to find out information for the police, a government, etc.","cn":"秘密工作的；暗中做的；私下进行的","ex":{"en":"The illegal payments were discovered by a journalist working undercover.","cn":"违法付款是被一名卧底记者发现的。"},"pos":"adverb"}]}},"unreconstructed":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not changing your ideas even though many people think they are old-fashioned","cn":"思想僵化的﹐顽固守旧的﹐坚持过时观点的"}]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41unreconstructe.mp3","us":"media/ldoce/hwd/ame/b/unreconstructed.mp3"},"oxford":{"phon":"ˌʌnriːkənˈstrʌktɪd","pos":"adjective","senses":[{"en":"not having changed, although general opinion on these matters has changed","cn":"僵化的；顽固守旧的；不顺应形势的","ex":{"en":"an unreconstructed Marxist","cn":"一个未改造的马克思主义者"}}]}},"unilateralism":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"单方面(核)裁军主义","en":"Unilateralism is the belief that one country should get rid of all its own nuclear weapons, without waiting for other countries to do the same."},{"pos":"N-UNCOUNT 不可数名词","cn":"单边主义","en":"Unilateralism is used to refer to a policy in which one country or group involved in a situation takes a decision or action on its own, without the agreement of the other countries or groups involved.","ex":{"en":"...the recent history of American aggressive unilateralism on trade.","cn":"美国在贸易上奉行咄咄逼人的单边主义的近一段历史"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a unilateral action or decision is done by only one of the groups involved in a situation","cn":""},{"en":"→ bilateral , multilateral : a unilateral declaration of independence unilateral disarmament (= when one country gets rid of its own nuclear weapons without waiting for other countries to do the same )","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Governments that believe in unilateralism think that they should wage war and enact foreign policy without consulting any other countries."}]},"media":{"uk":"media/ldoce/hwd/bre/a/unilateral0205.mp3","us":"media/ldoce/hwd/ame/6/unilateral.mp3"},"examples":[{"en":"the defeat of the unilateralists on nuclear disarmament","cn":"核武器裁军单边主义者的失败"},{"en":"unilateralist defence policy","cn":"单边主义防御政策"}],"oxford":{"phon":"ˌjuːnɪˈlætrəlɪzəm","pos":"noun","senses":[{"en":"belief in or support of unilateral action, especially the policy of getting rid of nuclear weapons without waiting for other countries to do the same","cn":"单边主义（信仰和支持单方面行动，尤指单方面销毁核武器的政策）"}]}},"upstanding":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"品行端正的；正直的","en":"Upstanding people behave in a morally acceptable way.","ex":{"en":"...a fine, upstanding and decent Irish citizen","cn":"一位杰出而又品行端正、作风正派的爱尔兰公民"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"honest and responsible","cn":"诚实的；有担当的"},{"en":"standing upright or pointing upwards","cn":"直立的﹔向上的"},{"en":"used in a formal situation such as a law court to tell people to stand up as a sign of respect for an important person","cn":"起立〔用于法庭等正式场合﹐要求人们站起来以示对某重要人物的尊重〕"}]},"vocab":{"pos":"adj","senses":[{"en":"The adjective upstanding is good for describing someone who is a good and honorable person, like your trusted best friend."}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41upstanding.mp3","us":"media/ldoce/hwd/ame/0/upstanding.mp3"},"examples":[{"en":"Ladies and gentlemen, please be upstanding and join me in a toast to the bride and groom.","cn":"各位来宾，请大家起立，我们一起为新娘新郎干一杯。"},{"en":"an upstanding member of the community","cn":"群体中正直的一分子"}],"oxford":{"phon":"ˌʌpˈstændɪŋ","pos":"adjective","senses":[{"en":"behaving in a moral and honest way","cn":"正直的；正派的；诚实的","ex":{"en":"an upstanding member of the community","cn":"群体中正直的一分子"}}]}},"unlovely":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不可爱的；讨人嫌的","en":"If you describe something as unlovely, you mean that it is unattractive or unpleasant in some way.","ex":{"en":"She found a small, inexpensive motel on the outskirts of the town; it was barren and unlovely.","cn":"她在城郊找了一家便宜的小汽车旅馆，那旅馆既简陋又难看。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"ugly","cn":"不好看的﹐丑陋的"}]},"media":{"uk":"media/ldoce/hwd/bre/a/unlovely0205.mp3","us":"media/ldoce/hwd/ame/0/ld41unlovely.mp3"},"examples":[{"en":"an unlovely building","cn":"不美观的建筑物"}],"oxford":{"phon":"ˌʌnˈlʌvli","pos":"adjective","senses":[{"en":"not attractive","cn":"不好看的；不动人的；不美观的","ex":{"en":"an unlovely building","cn":"不美观的建筑物"}}]}},"undermanned":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"人员不足的；缺少人手的","en":"If an organization is undermanned, it does not have enough employees to function properly.","ex":{"en":"In some stores we were undermanned and customer service was suffering.","cn":"有些店我们人手不足，对顾客照顾不周。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a ship, office etc that is undermanned does not have enough workers to operate effectively","cn":"人员不足的﹐人手不够的"}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41undermanned.mp3","us":"media/ldoce/hwd/ame/0/undermanned.mp3"},"oxford":{"phon":"ˌʌndəˈmænd","pos":"adjective","senses":[{"en":"not having enough people working in order to be able to function well","cn":"人手不足的；编制不足的；缺编的"}]}},"unprotected":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（人或地方）未受保护的，未设防的","en":"An unprotected person or place is not looked after or defended, and so they may be harmed or attacked.","ex":{"en":"The landing beaches would be unprotected.","cn":"登陆的海滩可能没有设防。"}},{"pos":"ADJ 形容词","cn":"暴露在外的；易受损的","en":"If something is unprotected, it is not covered or treated with anything, and so it may easily be damaged.","ex":{"en":"Exposure of unprotected skin to the sun carries the risk of developing skin cancer","cn":"皮肤没有采取任何防晒措施就在太阳下曝晒的话有得皮肤癌的危险。"}},{"pos":"ADJ 形容词","cn":"未用避孕套的；无防护的","en":"If two people have unprotected sex, they do not use a condom when they have sex."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not protected against possible harm or damage","cn":"未受保护的﹐未设防的"},{"en":"unprotected machines are not covered and could injure someone 〔","cn":"机器〕没有防护罩的"},{"en":"sex without using a condom","cn":"无保护性交"}]},"media":{"uk":"media/ldoce/hwd/bre/7/unprotected0205.mp3","us":"media/ldoce/hwd/ame/0/laadunprotected.mp3"},"examples":[{"en":"Machinery was often unprotected and accidents were frequent.","cn":"机器常裸露着，因此事故频仍。"},{"en":"Thieves often target unprotected vehicles.","cn":"窃贼常常瞄准未采取防护措施的车辆。"}],"oxford":{"phon":"ˌʌnprəˈtektɪd","pos":"adjective","senses":[{"en":"not protected against being hurt or damaged","cn":"未受保护的；未设防的","ex":{"en":"They hunt in packs, attacking the old, sick and unprotected young animals.","cn":"它们成群结队地狩猎，攻击年老、患病和未受保护的幼小动物。"}},{"en":"not covered to prevent it from causing damage or injury","cn":"无防护罩的；无掩护的","ex":{"en":"Machinery was often unprotected and accidents were frequent.","cn":"机器常裸露着，因此事故频仍。"}},{"en":"done without using a condom","cn":"未用避孕套的；无防护的"}]}},"uphold":{"collins":{"senses":[{"pos":"VERB 动词","cn":"拥护；支持；维护","en":"If you uphold something such as a law, a principle, or a decision, you support and maintain it.","ex":{"en":"Our policy has been to uphold the law","cn":"拥护法律是我们一贯的方针。"}},{"pos":"VERB 动词","cn":"维持，坚持（原判）","en":"If a court of law upholds a legal decision that has already been made, it decides that it was the correct decision.","ex":{"en":"The crown court, however, upheld the magistrate's decision.","cn":"然而，最高法院维持了地方法院的判决。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if a parliament or similar group passes a law or proposal, the members vote to accept it","cn":""},{"en":"to officially accept something that has been planned to happen","cn":""},{"en":"to officially agree to accept an agreement that someone else has already agreed to accept","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"When you uphold something, you stick up for or support it. Police officers are paid to uphold the law, and crazy Elvis fans uphold their belief that he's still alive out there somewhere."}]},"collocations":{"phrases":["ADV. firmly, resolutely, vigorously | unanimously Three judges unanimously upheld the sentence.","VERB + UPHOLD have a duty to | be determined to We are determined to uphold the law. | seek to | promise to | vote to The IWC voted to uphol"]},"media":{"uk":"media/ldoce/hwd/bre/f/uphold0205.mp3","us":"media/ldoce/hwd/ame/8/uphold.mp3"},"examples":[{"en":"to uphold a conviction/an appeal/a complaint","cn":"维持原判；受理上诉/申诉"},{"en":"We have a duty to uphold the law.","cn":"维护法律是我们的责任。"}],"oxford":{"phon":"ʌpˈhəʊld","pos":"verb","senses":[{"en":"to support something that you think is right and make sure that it continues to exist","cn":"支持，维护（正义等）","ex":{"en":"We have a duty to uphold the law.","cn":"维护法律是我们的责任。"}},{"en":"to agree that a previous decision was correct or that a request is reasonable","cn":"维持（原判）；受理（申诉）","ex":{"en":"to uphold a conviction/an appeal/a complaint","cn":"维持原判；受理上诉／申诉"}}]}},"unbounded":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"无限的；无穷尽的","en":"If you describe something as unbounded, you mean that it has, or seems to have, no limits.","ex":{"en":"...an unbounded capacity to imitate and adopt the new","cn":"仿效和接受新事物的无限能力"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"extreme or without any limit","cn":"极度的﹐无限的"}]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41unbounded.mp3","us":"media/ldoce/hwd/ame/8/unbounded.mp3"},"examples":[{"en":"her unbounded energy","cn":"她的无限精力"},{"en":"the child’s unbounded energy","cn":"这孩子无穷的精力"}],"oxford":{"phon":"ʌnˈbaʊndɪd","pos":"adjective","senses":[{"en":"having, or seeming to have, no limits","cn":"（似）无限的；无尽的；无穷的","ex":{"en":"her unbounded energy","cn":"她的无限精力"}}]}},"unselfish":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无私的；为他人考虑的","en":"If you describe someone as unselfish, you approve of the fact that they regard other people's wishes and interests as more important than their own.","ex":{"en":"She started to get a reputation as an unselfish girl with a heart of gold","cn":"她开始被人们赞誉为有一颗金子般的心的无私女孩。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"caring only about other people's needs, not your own, and never behaving selfishly","cn":""},{"en":"sincerely concerned about other people and willing to help them or give money to them if they need it, without trying to get any advantage for yourself","cn":""},{"en":"caring about other people and thinking about their needs and wishes before your own","cn":"不自私的﹐无私的﹐为他人着想的"}]},"media":{"uk":"media/ldoce/hwd/bre/5/unselfish0205.mp3","us":"media/ldoce/hwd/ame/4/laadunselfish.mp3"},"examples":[{"en":"unselfish motives","cn":"无私的动机"}],"oxford":{"phon":"ʌnˈselfɪʃ","pos":"adjective","senses":[{"en":"giving more time or importance to other people’s needs, wishes, etc. than to your own","cn":"无私的；忘我的；不谋私利的","ex":{"en":"unselfish motives","cn":"无私的动机"}}]}},"urinate":{"collins":{"senses":[{"pos":"VERB 动词","cn":"排尿；小便；撒尿","en":"When someone urinates, they get rid of urine from their body."}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to get rid of urine from your body","cn":"排尿"}]},"media":{"uk":"media/ldoce/hwd/bre/2/urinate0205.mp3","us":"media/ldoce/hwd/ame/1/urinate.mp3"},"oxford":{"phon":"ˈjʊərɪneɪt","pos":"verb","senses":[{"en":"to get rid of urine from the body","cn":"排尿；小便"}]}},"unrefined":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未提炼过的；未精制过的","en":"An unrefined food or other substance is in its natural state and has not been processed.","ex":{"en":"Unrefined carbohydrates include brown rice and other grains.","cn":"糙米和其他谷物属非精制的碳水化合物。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"an unrefined substance is in its natural form","cn":"未精制的﹔未提炼的"},{"en":"not polite or educated","cn":"不礼貌的﹐粗俗的﹔无教养的"}]},"media":{"uk":"media/ldoce/hwd/bre/f/unrefined0205.mp3","us":"media/ldoce/hwd/ame/c/laadunrefined.mp3"},"examples":[{"en":"unrefined sugar","cn":"原糖"}],"oxford":{"phon":"ˌʌnrɪˈfaɪnd","pos":"adjective","senses":[{"en":"not separated from the other substances that it is combined with in its natural form","cn":"未精制的；未提炼的","ex":{"en":"unrefined sugar","cn":"原糖"}},{"en":"not polite or educated","cn":"粗俗的；不文雅的；缺乏教养的"}]}},"utter":{"collins":{"senses":[{"pos":"VERB 动词","cn":"发出（声音）；说；讲","en":"If someone utters sounds or words, they say them.","ex":{"en":"He uttered a snorting laugh","cn":"他嗤笑了一声。"}},{"pos":"ADJ 形容词","cn":"完全的；彻底的；十足的","en":"You use utter to emphasize that something is great in extent, degree, or amount.","ex":{"en":"This, of course, is utter nonsense.","cn":"这当然是一派胡言。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"say this when you strongly agree with something or approve of something, or to emphasize strong adjectives","cn":""},{"en":"use this especially to say that you have completely understood something or have everything that you need","cn":""},{"en":"use this especially to show that you completely disagree with something or that you are very annoyed about it","cn":""}]},"vocab":{"pos":"1 adj 2 v 3 v","senses":[{"en":"The adjective utter is often used as an intensifier to mean \"total\" — often with negative connotations (like \" utter failure\"). As a verb, the word has a totally unrelated meaning: to speak or to articulate a sound."}]},"media":{"uk":"media/ldoce/hwd/bre/f/utter_v0205.mp3","us":"media/ldoce/hwd/ame/5/utter1.mp3"},"examples":[{"en":"To my utter amazement she agreed.","cn":"令我大感意外的是，她同意了。"},{"en":"We're so utterly different from each other.","cn":"我们之间有着天壤之别。"}],"oxford":{"phon":"ˈʌtə(r)","pos":"adjective","senses":[{"en":"used to emphasize how complete something is","cn":"完全的；十足的；彻底的","ex":{"en":"That's complete and utter nonsense!","cn":"那纯属一派胡言！"}},{"en":"to make a sound with your voice; to say something","cn":"出声；说；讲","ex":{"en":"He uttered a great cry of anger.","cn":"他发出一声愤怒的大叫。"},"pos":"verb"}]}},"unknowingly":{"collins":{"senses":[{"pos":"ADV 副词","cn":"未意识到地；不知不觉地；无意中","en":"If someone does something unknowingly, they do it without being aware of it.","ex":{"en":"...if people unknowingly move into more contaminated areas of the river.","cn":"如果人们在不知情的情况下搬到了河流污染更严重的地区"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not realizing what you are doing or what is happening","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41unknowing.mp3","us":"media/ldoce/hwd/ame/c/unknowing.mp3"},"examples":[{"en":"She had unknowingly broken the rules.","cn":"她无意中犯了规。"}],"oxford":{"phon":"ʌnˈnəʊɪŋli","pos":"adverb","senses":[{"en":"without being aware of what you are doing or what is happening","cn":"没意识到的；未察觉的；无知的","ex":{"en":"She had unknowingly broken the rules.","cn":"她无意中犯了规。"}}]}},"unleaded":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(燃料)无铅的","en":"Unleaded fuel contains a smaller amount of lead than most fuels so that it produces fewer harmful substances when it is burned.","ex":{"en":"The new Metro is designed to run on unleaded fuel.","cn":"新的地铁系统设计为使用无铅燃料。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"unleaded petrol does not contain any lead 〔","cn":"汽油〕不含铅的﹐无铅的"}]},"media":{"uk":"media/ldoce/hwd/bre/f/unleaded0205.mp3","us":"media/ldoce/hwd/ame/f/unleaded.mp3"},"examples":[{"en":"Unleaded is cheaper than diesel.","cn":"无铅汽油比柴油便宜。"}],"oxford":{"phon":"ˌʌnˈledɪd","pos":"noun","senses":[{"en":"petrol that does not contain lead and is therefore less harmful to the environment","cn":"无铅的；不含铅的","ex":{"en":"Unleaded is cheaper than diesel.","cn":"无铅汽油比柴油便宜。"}},{"en":"not containing lead and therefore less harmful to the environment","cn":"无铅的；不含铅的","pos":"adjective"}]}},"unsuited":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不适宜的；不相称的","en":"If someone or something is unsuited to a particular job, situation, or place, they do not have the right qualities or characteristics for it.","ex":{"en":"He's totally unsuited to the job","cn":"他完全不适合做这份工作。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（男女）不般配的，彼此不合适的","en":"If two people, especially a man and a woman, are unsuited to each other, they have different personalities or interests, and so are unlikely to have a successful relationship.","ex":{"en":"By the end of that first year, I knew how totally unsuited we were to each other.","cn":"到了第一年年底，我明白了我们俩根本不般配。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not suitable for a situation or purpose - use this especially about something that has been done or chosen without enough care or thought","cn":""},{"en":"not having the qualities or characteristics that are needed for a particular purpose or situation","cn":""},{"en":"not the right one for a particular job or purpose","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41unsuited.mp3","us":"media/ldoce/hwd/ame/a/ld41unsuited.mp3"},"examples":[{"en":"She was totally unsuited for the job.","cn":"她根本不能胜任这项工作。"},{"en":"He is unsuited to academic work.","cn":"他不适合做学术工作。"}],"oxford":{"phon":"ʌnˈsuːtɪd","pos":"adjective","senses":[{"en":"not having the right or necessary qualities for something","cn":"不合格的；不胜任的；不适宜的","ex":{"en":"He is unsuited to academic work.","cn":"他不适合做学术工作。"}},{"en":"if two people are unsuited to each other, they do not have the same interests, etc. and are therefore not likely to make a good couple","cn":"（人）志趣不相投的，不相配的，不般配的"}]}},"unutterable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（尤指不好的事情）无以名状的，难以形容的，莫名的","en":"You can use unutterable to emphasize that something, especially a bad quality, is great in degree or intensity.","ex":{"en":"I am at the beginning of a new and unutterable loneliness.","cn":"我再次陷入莫名的孤独寂寞中。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"an unutterable feeling is too extreme to be expressed in words 〔","cn":"感受过于强烈〕无法言表的﹐难以言喻的"}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41unutterable.mp3","us":"media/ldoce/hwd/ame/7/unutterable.mp3"},"examples":[{"en":"unutterable sadness","cn":"无法形容的悲伤"}],"oxford":{"phon":"ʌnˈʌtərəbl","pos":"adjective","senses":[{"en":"used to emphasize how great a particular emotion or quality is","cn":"难以言表的；说不出的","ex":{"en":"unutterable sadness","cn":"无法形容的悲伤"}}]}},"undertaking":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（尤指艰巨的）任务，工作，事业","en":"An undertaking is a task or job, especially a large or difficult one.","ex":{"en":"Organizing the show has been a massive undertaking.","cn":"组织那场演出是一项浩大的工程。"}},{"pos":"N-COUNT 可数名词","cn":"承诺；保证","en":"If you give an undertaking to do something, you formally promise to do it.","ex":{"en":"The MOD gave an undertaking to Saville that it had provided him with all relevant material.","cn":"国防部向萨维尔保证已向他提供了所有相关的资料。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a statement that you will definitely do or provide something, which may not be reliable","cn":""},{"en":"a public or official promise to do a particular thing in the future","cn":""},{"en":"a very serious promise to do something or not to do something that you choose to make","cn":""}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"Painting a house is a serious undertaking ––it looks simple but involves a lot of preparation and hard work. An undertaking is a job or a task you commit to. The word also can mean the profession of funeral management."}]},"collocations":{"phrases":["ADJ. considerable, large, major, serious | worthwhile | hazardous, risky | joint the first joint undertaking of the two societies | commerci","ADJ. solemn | express | irrevocable | voluntary | verbal, written | contractual | government | public","VERB + UNDERTAKING give (sb) He gave an undertaking not to leave the country before the trial. | seek | obtain | carry out, honour, renege o"]},"media":{"uk":"media/ldoce/hwd/bre/5/brelasdeundertaking.mp3","us":"media/ldoce/hwd/ame/9/undertaking1.mp3"},"examples":[{"en":"In those days, the trip across country was a dangerous undertaking.","cn":"那个时期，越野旅行是一件危险的事情。"},{"en":"He is interested in buying the club as a commercial undertaking.","cn":"他有意购买那个俱乐部作为投资。"}],"oxford":{"phon":"ˌʌndəˈteɪkɪŋ","pos":"noun","senses":[{"en":"a task or project, especially one that is important and/or difficult","cn":"（重大或艰巨的）任务，项目，事业；企业","g":"[countable]","ex":{"en":"He is interested in buying the club as a commercial undertaking.","cn":"他有意购买那个俱乐部作为投资。"}},{"en":"an agreement or a promise to do something","cn":"承诺；保证；许诺；答应","g":"[countable]","lab":"formal","ex":{"en":"a government undertaking to spend more on education","cn":"政府增加教育经费的承诺"}},{"en":"the business of an undertaker","cn":"殡仪业；丧葬业","g":"[uncountable]"}]}},"udder":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（母牛的）乳房","en":"A cow's udder is the organ that hangs below its body and produces milk."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the part of a cow, female goat etc that hangs down between its back legs and that produces milk 〔","cn":"奶牛﹑母山羊等的〕乳房"}]},"media":{"uk":"media/ldoce/hwd/bre/b/udder0205.mp3","us":"media/ldoce/hwd/ame/6/udder.mp3"},"oxford":{"phon":"ˈʌdə(r)","pos":"noun","senses":[{"en":"an organ like a bag in shape that produces milk and hangs under the body of a cow, goat, etc.","cn":"（母牛、母羊等的）乳房"}]}},"unrecorded":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未被正式记录的","en":"You use unrecorded to describe something that has not been written down or recorded officially, especially when it should have been.","ex":{"en":"The statistics don't reveal of course unrecorded crime","cn":"这项统计数据显然没有披露未登记的罪案。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not written down or recorded","cn":"未写下来的﹔未记录的﹔未登记的"}]},"media":{"uk":"media/ldoce/hwd/bre/e/unrecorded0205.mp3","us":"media/ldoce/hwd/ame/7/laadunrecorded.mp3"},"examples":[{"en":"Many crimes go unrecorded.","cn":"许多罪行都未记录在案。"},{"en":"Many of the complaints have gone unrecorded .","cn":"许多投诉都未作记录。"}],"oxford":{"phon":"ˌʌnrɪˈkɔːdɪd","pos":"adjective","senses":[{"en":"not written down or recorded","cn":"未写下的；未记录的；未录音的","ex":{"en":"Many crimes go unrecorded.","cn":"许多罪行都未记录在案。"}}]}},"unofficial":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"非官方的；未经正式批准的；非正式的","en":"An unofficial action or statement is not organized or approved by a person or group in authority.","ex":{"en":"Staff voted to continue an unofficial strike in support of seven colleagues who were dismissed last week","cn":"职工投票决定继续进行非正式罢工，以支持上周被解雇的7名同事。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not done according to official rules or processes, or not officially approved by a government or other organization","cn":""},{"en":"informal discussions, agreements, offers etc are not official and have not been officially approved","cn":""},{"en":"if someone tells you something off the record , they are not giving you the official opinion of their organization and do not want what they say to be made public","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/b/unofficial0205.mp3","us":"media/ldoce/hwd/ame/5/unofficial.mp3"},"examples":[{"en":"Unofficial estimates put the figure at over two million.","cn":"非官方的估计数字为 200 万以上。"},{"en":"The former president paid an unofficial visit to China.","cn":"前总统到中国进行了私人访问。"}],"oxford":{"phon":"ˌʌnəˈfɪʃl","pos":"adjective","senses":[{"en":"that does not have permission or approval from somebody in authority","cn":"未经正式批准的；非官方的；非正式的","ex":{"en":"an unofficial agreement/strike","cn":"未经批准的协议／罢工"}},{"en":"that is not part of somebody’s official business","cn":"非公事的；私事的；私人的","ex":{"en":"The former president paid an unofficial visit to China.","cn":"前总统到中国进行了私人访问。"}}]}},"uncharted":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"陌生的；不熟悉的","en":"If you describe a situation, experience, or activity as uncharted territory or waters, you mean that it is new or unfamiliar.","ex":{"en":"Carter's fourth album definitely moves into uncharted territory.","cn":"卡特的第四张专辑无疑涉足了全新的领域。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a place or an experience that people have not been in before and that they are therefore often nervous about","cn":""},{"en":"relating to places that have not been put on a map yet, or to situations that have not yet been experienced","cn":""},{"en":"if something is unidentified , people do not know what it is, what its name is, or who it belongs to - used especially in newspapers or in official reports","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"If a place is uncharted , it means it isn't found on any map, like the uncharted wilderness settlers found when heading west, or an uncharted island inhabited by stranded castaways, or, more figuratively, the uncharted territory of a new strategy."}]},"media":{"uk":"media/ldoce/hwd/bre/1/uncharted0205.mp3","us":"media/ldoce/hwd/ame/a/uncharted.mp3"},"examples":[{"en":"They set off into the country's uncharted interior.","cn":"他们出发前往这个国家人迹罕至的内陆。"},{"en":"( figurative ) I was moving into uncharted territory (= a completely new experience) with this relationship.","cn":"这个关系让我开始体验到全新的事物。"}],"oxford":{"phon":"ˌʌnˈtʃɑːtɪd","pos":"adjective","senses":[{"en":"not marked on a map; that has not been visited or investigated before","cn":"地图上未标示的；人迹罕至的；无人涉足的","lab":"figurative","ex":{"en":"The ship hit an uncharted rock.","cn":"船撞在海图上未标示的岩石上。"}}]}},"unproductive":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"没有好结果的；徒然的","en":"Something that is unproductive does not produce any good results.","ex":{"en":"Research workers are well aware that much of their time and effort is unproductive.","cn":"研究人员很清楚，他们的很多时间和精力全都是白费。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if a plan or attempt fails , it does not achieve what you want it to achieve","cn":""},{"en":"when a plan or attempt fails","cn":""},{"en":"to fail","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/f/unproductive0205.mp3","us":"media/ldoce/hwd/ame/0/laadunproductive.mp3"},"examples":[{"en":"I've had a very unproductive day.","cn":"我这一天什么事都没干成。"},{"en":"an unproductive meeting","cn":"事倍功半的会议"}],"oxford":{"phon":"ˌʌnprəˈdʌktɪv","pos":"adjective","senses":[{"en":"not producing very much; not producing good results","cn":"产量少的；效果不佳的；无益的","ex":{"en":"unproductive land","cn":"贫瘠的土地"}}]}},"uninvited":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未经邀请的；不请自到的；未经要求的","en":"If someone does something or goes somewhere uninvited, they do it or go there without being asked, often when their action or presence is not wanted.","ex":{"en":"He came uninvited to one of Stein's parties.","cn":"在斯坦举办的一个聚会上他不请自到。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who goes to a party but was not invited, especially someone who causes trouble","cn":""},{"en":"not invited and expected","cn":"未被邀请的"}]},"media":{"uk":"media/ldoce/hwd/bre/5/uninvited0205.mp3","us":"media/ldoce/hwd/ame/3/laaduninvited.mp3"},"examples":[{"en":"He turned up uninvited.","cn":"他不请自到了。"},{"en":"uninvited guests at a party","cn":"聚会上的不速之客"}],"oxford":{"phon":"ˌʌnɪnˈvaɪtɪd","pos":"adjective","senses":[{"en":"doing something or going somewhere when you have not been asked or invited to, especially when somebody does not want you to","cn":"未经要求的；未获邀请的；不速而至的","ex":{"en":"uninvited guests at a party","cn":"聚会上的不速之客"}}]}},"unprofitable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不盈利的；无利可图的","en":"An industry, company, or product that is unprofitable does not make any profit or does not make enough profit.","ex":{"en":"...unprofitable state-owned industries","cn":"不盈利的国有行业"}},{"pos":"ADJ 形容词","cn":"无益的；没好处的","en":"Unprofitable activities or efforts do not produce any useful or helpful results.","ex":{"en":"...an endless, unprofitable argument","cn":"没完没了的无用争论"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"an unprofitable business or activity does not make a profit and is likely to have debts","cn":""},{"en":"not making enough profits to be successful or to successfully compete with other companies, industries etc - use this especially when this is a reason for closing the company, industry etc","cn":""},{"en":"making no profit","cn":"无利润的"}]},"media":{"uk":"media/ldoce/hwd/bre/d/unprofitable0205.mp3","us":"media/ldoce/hwd/ame/3/laadunprofitable.mp3"},"examples":[{"en":"unprofitable companies","cn":"不赚钱的公司"},{"en":"It would be unprofitable to pursue this argument any further.","cn":"这个争论再继续下去也是徒劳。"}],"oxford":{"phon":"ʌnˈprɒfɪtəbl","pos":"adjective","senses":[{"en":"not making any financial profit","cn":"不赢利的；无利润的","ex":{"en":"unprofitable companies","cn":"不赚钱的公司"}},{"en":"not bringing any advantage","cn":"无益的；没好处的","lab":"formal"}]}},"unspeakable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"恶劣得说不出口的；坏透了的","en":"If you describe something as unspeakable, you are emphasizing that it is extremely unpleasant.","ex":{"en":"...the unspeakable horrors of chemical weapons","cn":"化学武器难以名状的可怖"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"used for emphasizing how bad someone or something is","cn":"坏得无法形容的﹐坏透了的"},{"en":"unspeakable feelings are so extreme that it is impossible to describe them 〔","cn":"感觉〕难以形容的﹐难以言表的"}]},"media":{"uk":"media/ldoce/hwd/bre/3/unspeakable0205.mp3","us":"media/ldoce/hwd/ame/e/unspeakable.mp3"},"examples":[{"en":"an unspeakable tragedy","cn":"无法形容的悲剧"},{"en":"unspeakable joy","cn":"难以形容的快乐"}],"oxford":{"phon":"ʌnˈspiːkəbl","pos":"adjective","senses":[{"en":"that cannot be described in words, usually because it is so bad","cn":"难以说出口的；不堪入耳的","ex":{"en":"unspeakable suffering","cn":"难以言喻的痛苦"}}]}},"unexplained":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"莫名其妙的；原因不明的","en":"If you describe something as unexplained, you mean that the reason for it or cause of it is unclear or is not known.","ex":{"en":"The demonstrations were provoked by the unexplained death of an opposition leader","cn":"一位反对派领袖莫名身亡，引发了示威游行。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"an event or fact that is unexplained has never been explained so no one knows exactly what happened","cn":""},{"en":"something that is unexplained is something you cannot understand because you do not know the reason for it","cn":"无法解释的﹔莫名其妙的﹔原因不明的"}]},"media":{"uk":"media/ldoce/hwd/bre/5/unexplained0205.mp3","us":"media/ldoce/hwd/ame/7/laadunexplained.mp3"},"examples":[{"en":"He died in unexplained circumstances.","cn":"他死因不明。"},{"en":"an unexplained mystery","cn":"解释不清的奥妙"}],"oxford":{"phon":"ˌʌnɪkˈspleɪnd","pos":"adjective","senses":[{"en":"for which the reason or cause is not known; that has not been explained","cn":"原因不详的；未解释的；未说明的","ex":{"en":"an unexplained mystery","cn":"解释不清的奥妙"}}]}},"unmitigated":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（坏事情）完全的，十足的，彻底的","en":"You use unmitigated to emphasize that a bad situation or quality is totally bad.","ex":{"en":"Last year's cotton crop was an unmitigated disaster","cn":"去年棉花作物所遭遇的是彻头彻尾的灾难。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"something that is completely bad or good","cn":"十足的灾难/失败/快乐等"}]},"vocab":{"pos":"adj","senses":[{"en":"The adjective unmitigated describes something that is undiminished, unqualified, or absolute. If your new recipe for chocolate cupcakes is met by enthusiastic cheers, you can assume you have an unmitigated success on your hands."}]},"media":{"uk":"media/ldoce/hwd/bre/7/unmitigated0205.mp3","us":"media/ldoce/hwd/ame/e/unmitigated.mp3"},"examples":[{"en":"The evening was an unmitigated disaster.","cn":"这一晚完全是一场灾难。"}],"oxford":{"phon":"ʌnˈmɪtɪɡeɪtɪd","pos":"adjective","senses":[{"en":"used to mean ‘complete’, usually when describing something bad","cn":"完全的，十足的，彻底的（通常指坏事）","ex":{"en":"The evening was an unmitigated disaster.","cn":"这一晚完全是一场灾难。"}}]}},"usher":{"collins":{"senses":[{"pos":"VERB 动词","cn":"引;领;陪同","en":"If you usher someone somewhere, you show them where they should go, often by going with them.","ex":{"en":"I ushered him into the office","cn":"我领他去办公室。"}},{"pos":"N-COUNT 可数名词","cn":"（婚礼、音乐会等的）引座员，招待员，迎宾员","en":"An usher is a person who shows people where to sit, for example at a wedding or at a concert.","ex":{"en":"He did part-time work as an usher in a theatre.","cn":"他在一家戏院兼职当引座员。"}},{"pos":"N-COUNT 可数名词","cn":"（英国）法庭庭警","en":"An usher is a person who organizes people who are attending a law court in Britain."},{"pos":"","cn":"","en":"相关词组：usher in"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to take a person or animal somewhere by going in front of them while they follow, or by pulling them gently","cn":""},{"en":"to take someone somewhere with you when you have the transport, know the way, are paying etc","cn":""},{"en":"to take someone through or to a place you know, showing them the way","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"That guy who guided you to your seat? He's called an usher . You most often see ushers at movie theaters and weddings."}]},"media":{"uk":"media/ldoce/hwd/bre/1/usher_v0205.mp3","us":"media/ldoce/hwd/ame/0/usher1.mp3"},"examples":[{"en":"The change of management ushered in fresh ideas and policies.","cn":"更换领导班子带来了新思想和新政策。"},{"en":"The secretary ushered me into his office.","cn":"秘书把我领进他的办公室。"}],"oxford":{"phon":"ˈʌʃə(r)","pos":"noun","senses":[{"en":"a person who shows people where to sit in a church, public hall, etc.","cn":"引座员"},{"en":"an official who has special responsibilities in court, for example allowing people in and out of the court","cn":"（法院的）传达员，门卫，门房"},{"en":"a friend of the couple at a wedding who helps show people to their seats","cn":"（婚礼）迎宾员，接待员"},{"en":"to take or show somebody where they should go","cn":"把…引往；引导；引领","ex":{"en":"The secretary ushered me into his office.","cn":"秘书把我领进他的办公室。"},"pos":"verb"}]}},"uterus":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"子宫","en":"The uterus of a woman or female mammal is her womb.","ex":{"en":"...an ultrasound scan of the uterus.","cn":"子宫超声波扫描"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the organ in a woman or female mammal where babies develop","cn":"子宫"}]},"media":{"uk":"media/ldoce/hwd/bre/3/uterus0205.mp3","us":"media/ldoce/hwd/ame/f/uterus.mp3"},"oxford":{"phon":"ˈjuːtərəs","pos":"noun","senses":[{"en":"the organ in women and female animals in which babies or young animals develop before they are born","cn":"子宫","ex":{"en":"A scan determines the position of the baby in the uterus.","cn":"扫描可确定胎儿在子宫里的位置。"}}]}},"urbanized":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"城市化的","en":"An urbanized country or area has many buildings and a lot of industry and business.","ex":{"en":"Zambia is black Africa's most urbanised country","cn":"赞比亚是撒哈拉沙漠以南的非洲地区城市化程度最高的国家。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"都市的；城市的","en":"An urbanized population consists of people who live and work in a town.","ex":{"en":"...a large urbanized industrial population.","cn":"规模庞大的城镇工业人口"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"an urbanized country or area has a lot of houses, factories, shops, offices etc 〔","cn":"国家或地区〕城市化的﹐都市化的"},{"en":"in an urbanized society, there are a lot of people who live and work in towns and cities 〔","cn":"社会〕城市化的﹐都市化的"}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41urbanized.mp3","us":"media/ldoce/hwd/ame/0/ld41urbanized.mp3"},"examples":[{"en":"an increasingly urbanized society","cn":"城镇居民日益增加的社会"},{"en":"During the 19th century, Britain became the world’s first modern urbanized society.","cn":"在19世纪﹐英国成为世界上第一个现代的城市化社会。"}],"oxford":{"phon":"ˈɜːbənaɪzd","pos":"adjective","senses":[{"en":"having a lot of towns, streets, factories, etc. rather than countryside","cn":"城市化的"},{"en":"living and working in towns and cities rather than in the country","cn":"生活于城市的；在都市工作的","ex":{"en":"an increasingly urbanized society","cn":"城镇居民日益增加的社会"}}]}},"unblinking":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"不眨眼的;目不转睛的","en":"If you describe someone's eyes or expression as unblinking, you mean that they are looking steadily at something without blinking.","ex":{"en":"He stared into Leo's unblinking eyes.","cn":"他凝视着利奥一眨不眨的双眼。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if you look at something or someone with unblinking eyes, you look continuously at them without blink ing (= quickly closing and opening your eyes )","cn":"不眨眼的﹔目不转睛的"}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41unblinking.mp3","us":"media/ldoce/hwd/ame/f/unblinking.mp3"},"examples":[{"en":"His father’s unblinking gaze was fixed on the fire.","cn":"他父亲目不转睛地凝视着炉火。"}],"oxford":{"phon":"ʌnˈblɪŋkɪŋ","pos":"adjective","senses":[{"en":"if somebody has an unblinking stare or looks with unblinking eyes, they look very steadily at something and do not blink","cn":"不眨眼的；目不转睛的"}]}},"unbalance":{"collins":{"senses":[{"pos":"VERB 动词","cn":"使失衡；使紊乱；使失常","en":"If something unbalances a relationship, system, or group, it disturbs or upsets it so that it is no longer successful or functioning properly.","ex":{"en":"The interplay between the new politics and the modern media will unbalance the political process and inhibit its workings.","cn":"新政治和现代媒体之间的相互作用将会扰乱政治进程，妨碍其正常运作。"}},{"pos":"VERB 动词","cn":"使失去平衡;使不稳;使倾侧","en":"To unbalance something means to make it unsteady and likely to tip over.","ex":{"en":"Her whole body began to buckle, unbalancing the ladder","cn":"她整个身体开始弯曲，搞得梯子倾侧起来。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make a situation, relationship, or work of art not as good as it used to be or could be, especially by adding too much of one thing","cn":"打破〔状况﹑关系或艺术作品〕的平衡"},{"en":"to make someone or something unsteady, so that they are likely to fall down","cn":"使失去重心[平衡]"},{"en":"to make someone slightly crazy","cn":"使精神错乱，使精神失常"}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41unbalance.mp3","us":"media/ldoce/hwd/ame/a/ld41unbalance.mp3"},"examples":[{"en":"Having children can often unbalance even the closest of relationships.","cn":"有了孩子﹐即使最亲密的关系也常常会失衡。"},{"en":"He banged against the cupboard, unbalancing a pile a books.","cn":""}],"oxford":{"phon":"ˌʌnˈbæləns","pos":"verb","senses":[{"en":"to make something no longer balanced, for example by giving too much importance to one part of it","cn":"使不平衡；使失去均衡"},{"en":"to make somebody/something unsteady so that they are likely to fall down","cn":"使失去重心（或平衡）；使倾覆"},{"en":"to make somebody so upset that they are unable to continue thinking or behaving as they normally do","cn":"使心理不平衡；使精神失常"}]}},"upwind":{"collins":{"senses":[{"pos":"ADV 副词","cn":"逆风地；顶风地；在上风","en":"If something moves upwind, it moves in the opposite direction to the wind. If something is upwind, the wind is blowing away from it.","ex":{"en":"...riding a bike upwind","cn":"逆风骑车"}}]},"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"in the opposite direction to the way the wind is blowing","cn":"逆风地﹐顶风地"}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41upwind2.mp3","us":"media/ldoce/hwd/ame/8/ld41upwind2.mp3"},"examples":[{"en":"The house was upwind of the factory and its smells (= the wind did not blow the smells towards the house).","cn":"这房子坐落在工厂的上风处，闻不到工厂的气味。"},{"en":"to sail upwind","cn":"逆风行船"}],"oxford":{"phon":"ˌʌpˈwɪnd","pos":"adverb, adjective","senses":[{"en":"in the opposite direction to the way in which the wind is blowing","cn":"逆风（的）；顶风（的）","ex":{"en":"to sail upwind","cn":"逆风行船"}}]}},"uninspiring":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不振奋精神的；引不起兴趣的","en":"If you describe something or someone as uninspiring, you are criticizing them because they have no special or exciting qualities, and make you feel bored.","ex":{"en":"The series of speeches on the economy was uninspiring and a rehash of old subjects","cn":"这一系列关于经济的演讲平常无奇，都是一些陈词滥调。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"something that is boring is not interesting in any way and makes you feel tired and annoyed","cn":""},{"en":"very ordinary and not really interesting or enjoyable","cn":""},{"en":"boring because nothing different, interesting, or exciting happens","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41uninspiring.mp3","us":"media/ldoce/hwd/ame/e/uninspiring.mp3"},"examples":[{"en":"The view from the window was uninspiring.","cn":"窗外的景色平凡无奇。"},{"en":"No one deserved to win this uninspiring game.","cn":"谁也不该赢下这场乏味的比赛。"}],"oxford":{"phon":"ˌʌnɪnˈspaɪərɪŋ","pos":"adjective","senses":[{"en":"not making people interested or excited","cn":"不吸引人的；不令人鼓舞的","ex":{"en":"The view from the window was uninspiring.","cn":"窗外的景色平淡无奇。"}}]}},"umlaut":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（德语等语言中加于元音之上的）变音符，曲音符号","en":"An umlaut is a symbol that is written over vowels in German and some other languages to indicate the way in which they should be pronounced. For example, the word 'für' has an umlaut over the 'u'."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a sign (¨) written over a German vowel to show how it is pronounced 〔","cn":"德语中标在元音上方的〕变音符(¨)"}]},"vocab":{"pos":"n","senses":[{"en":"If you've ever studied German, you've seen an umlaut . It's a mark that looks like two dots over a letter, and it signifies a shift in pronunciation."}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41umlaut.mp3","us":"media/ldoce/hwd/ame/4/umlaut.mp3"},"oxford":{"phon":"ˈʊmlaʊt","pos":"noun","senses":[{"en":"the mark placed over a vowel in some languages to show how it should be pronounced, as over the u in the German word für","cn":"（元音的）变音符"}]}},"understated":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"朴素的；低调的；不夸张的；不惹眼的","en":"If you describe a style, colour, or effect as understated, you mean that it is not obvious.","ex":{"en":"I have always liked understated clothes — simple shapes which take a lot of hard work to get right.","cn":"我一直喜欢不太惹眼的衣服——简单的款式需要下大工夫才能弄得恰到好处。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"an understated style is one that is attractive because it is simple and does not have too many decorations 〔","cn":"风格〕简洁的﹐淡雅的"}]},"media":{"uk":"media/ldoce/hwd/bre/4/brelasdeunderstated.mp3","us":"media/ldoce/hwd/ame/6/laadunderstated.mp3"},"examples":[{"en":"the understated elegance of the Hotel Traiano","cn":"特拉亚诺酒店低调的优雅"}],"oxford":{"phon":"ˌʌndəˈsteɪtɪd","pos":"adjective","senses":[{"en":"if a style, colour, etc. is understated, it is attractive in a way that is not too obvious","cn":"淡雅的；素雅的；柔和的；不过分的"}]}},"unsure":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"心虚的；缺乏信心的","en":"If you are unsure of yourself, you lack confidence.","ex":{"en":"He made her feel hot, and awkward, and unsure of herself","cn":"他令她内心躁动，手足无措，对自己没有信心。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不确定的；不清楚的；拿不准的","en":"If you are unsure about something, you feel uncertain about it.","ex":{"en":"Fifty-two per cent were unsure about the idea","cn":"五成二的人对这个想法存有疑虑。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"to not be confident about your abilities or appearance","cn":""},{"en":"to stop feeling confident, especially after making a mistake","cn":""},{"en":"to not be confident, especially because you are young or you do not have much experience","cn":""}]},"collocations":{"phrases":["VERBS be, feel, look, seem, sound I felt a bit unsure about him. | remain | leave sb, make sb His sudden change of heart left Brenda unsure ","ADV. terribly, very | completely | a bit, a little, rather | obviously, plainly | still","PREP. about If you're still unsure about what you are supposed to do, speak up! | as to We were unsure as to what to do next. | of She was r"]},"media":{"uk":"media/ldoce/hwd/bre/b/unsure0205.mp3","us":"media/ldoce/hwd/ame/4/laadunsure.mp3"},"examples":[{"en":"Like many women, deep down she was unsure of herself.","cn":"和许多女性一样，她心底里缺乏自信。"},{"en":"I was unsure how to reply to this question.","cn":"我拿不准该如何回答这个问题。"}],"oxford":{"phon":"ˌʌnˈʃʊə(r)","pos":"adjective","senses":[{"en":"not certain of something; having doubts","cn":"无把握；不确知；犹豫","ex":{"en":"There were a lot of things I was unsure about.","cn":"有许多事情我没把握。"}},{"en":"not having enough confidence in yourself","cn":"缺乏自信","ex":{"en":"Like many women, deep down she was unsure of herself.","cn":"和许多女性一样，她内心深处缺乏自信。"}}]}},"uncouth":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（人）粗野的，粗鄙的，粗鲁的","en":"If you describe a person as uncouth, you mean that their behaviour is rude, noisy, and unpleasant.","ex":{"en":"...that oafish, uncouth person.","cn":"那个蠢笨粗野的家伙"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"behaving and speaking in a way that is rude or socially unacceptable 〔","cn":"言语和行为〕粗鲁的﹐不文明的"}]},"vocab":{"pos":"adj","senses":[{"en":"When you're at a fancy dinner party, if you burp after you eat, use your fingers to spread butter on your bread, and hang spoons from your nose, people will probably say you are uncouth , meaning vulgar and ill-mannered."}]},"media":{"uk":"media/ldoce/hwd/bre/e/uncouth0205.mp3","us":"media/ldoce/hwd/ame/c/uncouth.mp3"},"examples":[{"en":"an uncouth young man","cn":"一个无教养的年轻人"},{"en":"uncouth laughter","cn":"粗野的笑声"}],"oxford":{"phon":"ʌnˈkuːθ","pos":"adjective","senses":[{"en":"rude or socially unacceptable","cn":"粗鲁的；无礼的；无教养的","ex":{"en":"uncouth laughter","cn":"粗野的笑声"}}]}},"unveil":{"collins":{"senses":[{"pos":"VERB 动词","cn":"为…揭幕","en":"If someone formally unveils something such as a new statue or painting, they draw back the curtain which is covering it.","ex":{"en":"...a ceremony to unveil a monument to the victims.","cn":"死难者纪念碑揭幕仪式"}},{"pos":"VERB 动词","cn":"公布；推出；出台","en":"If you unveil a plan, new product, or some other thing that has been kept secret, you introduce it to the public.","ex":{"en":"Mr Werner unveiled his new strategy this week","cn":"沃纳先生本周公布了其新策略。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to show something such as paintings or interesting objects, especially a collection of them, by putting them in a public place so that a lot of people can see them","cn":""},{"en":"if a shop, museum etc displays things, it arranges them in a way that makes it possible for people to see them clearly","cn":""},{"en":"to show a special collection of paintings, photographs etc in a public place where people can look at them","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"Unveil is a dramatic verb we use when we uncover or reveal something for the first time, often in front of a large gathering or as part of a publicity campaign."}]},"collocations":{"phrases":["ADV. formally, officially The government has officially unveiled its plans for tax reform."]},"media":{"uk":"media/ldoce/hwd/bre/1/unveil0205.mp3","us":"media/ldoce/hwd/ame/f/unveil.mp3"},"examples":[{"en":"They will be unveiling their new models at the Motor Show.","cn":"他们将在汽车大展上首次推出自己的新型汽车。"},{"en":"The Queen unveiled a plaque to mark the official opening of the hospital.","cn":"女王主持揭幕式，标志着医院正式启用。"}],"oxford":{"phon":"ˌʌnˈveɪl","pos":"verb","senses":[{"en":"to remove a cover or curtain from a painting, statue, etc. so that it can be seen in public for the first time","cn":"为…揭幕；揭开…上的覆盖物；拉开…的帷幔","ex":{"en":"The Queen unveiled a plaque to mark the official opening of the hospital.","cn":"女王主持揭幕式，标志着医院正式启用。"}},{"en":"to show or introduce a new plan, product, etc. to the public for the first time","cn":"（首次）展示，介绍，推出；将…公之于众","ex":{"en":"They will be unveiling their new models at the Motor Show.","cn":"他们将在汽车展上首次推出自己的新型汽车。"}}]}},"unremitting":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未停止的；未减弱的；不懈的","en":"Something that is unremitting continues without stopping or becoming less intense.","ex":{"en":"I was sent to boarding school, where I spent six years of unremitting misery","cn":"我被送到寄宿学校呆了6年，其间我的生活一直很悲惨。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"continuing for a long time and not likely to stop","cn":"不间断的﹐无休止的"}]},"vocab":{"pos":"adj","senses":[{"en":"During a heat wave, it's not always the temperature itself that's a problem. It's that the heat is unremitting ––you don't get a break from it. It's sweltering hot day after day after day."}]},"media":{"uk":"media/ldoce/hwd/bre/0/brelasdeunremitting.mp3","us":"media/ldoce/hwd/ame/4/unremitting.mp3"},"examples":[{"en":"unremitting hostility","cn":"从未化解的敌视"},{"en":"unremittingly gloomy weather","cn":"持续的阴沉天气"}],"oxford":{"phon":"ˌʌnrɪˈmɪtɪŋ","pos":"adjective","senses":[{"en":"never stopping","cn":"不停的；不懈的；持续不断的","ex":{"en":"unremitting hostility","cn":"从未化解的敌视"}}]}},"unopened":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未被打开的","en":"If something is unopened, it has not been opened yet.","ex":{"en":"...unopened bottles of olive oil","cn":"一瓶瓶封着的橄榄油"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"an unopened package, letter etc has not been opened yet 〔","cn":"包裹、信件等〕未打开的"}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41unopened.mp3","us":"media/ldoce/hwd/ame/0/laadunopened.mp3"},"examples":[{"en":"The letter was returned unopened.","cn":"信被原封不动地退回了。"},{"en":"The letter was returned to us unopened.","cn":"那封信原封不动地退给了我们。"}],"oxford":{"phon":"ʌnˈəʊpənd","pos":"adjective","senses":[{"en":"not opened yet","cn":"未开启的；未打开的","ex":{"en":"The letter was returned unopened.","cn":"信被原封不动地退回了。"}}]}},"underplay":{"collins":{"senses":[{"pos":"VERB 动词","cn":"贬低；对…轻描淡写","en":"If you underplay something, you make it seem less important than it really is.","ex":{"en":"We often underplay the skills we have","cn":"我们常常贬低自身的技能。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make something seem less important or less serious than it really is","cn":"淡化…的重要性[严重性]"}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41underplay.mp3","us":"media/ldoce/hwd/ame/8/underplay.mp3"},"examples":[{"en":"She underplays her achievements.","cn":"她对自己的成就表现得很低调。"}],"oxford":{"phon":"ˌʌndəˈpleɪ","pos":"verb","senses":[{"en":"to make something seem less important than it really is","cn":"低调处理；降低…的重要性","ex":{"en":"I think she's underplaying the significance of the report.","cn":"我觉得她在淡化报告的重要性。"}}]}},"unwrap":{"collins":{"senses":[{"pos":"VERB 动词","cn":"打开…的包裹物;拆开…的包装","en":"When you unwrap something, you take off the paper, plastic, or other covering that is around it.","ex":{"en":"I untied the bow and unwrapped the small box","cn":"我解开蝴蝶结，拆开小盒子的包装。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"used about a door, window, container, package, letter, your eyes, or your mouth","cn":""},{"en":"to open a door, drawer, box etc with a key","cn":""},{"en":"to open a lid on a bottle, container etc by turning it","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/1/brelasdeunwrap.mp3","us":"media/ldoce/hwd/ame/f/laadunwrap.mp3"},"examples":[{"en":"Don't unwrap your present until your birthday.","cn":"生日礼物要等到你生日那天才可打开。"},{"en":"Brigitte was unwrapping her birthday presents.","cn":"布丽吉特正在拆她的生日礼物。"}],"oxford":{"phon":"ʌnˈræp","pos":"verb","senses":[{"en":"to take off the paper, etc. that covers or protects something","cn":"打开（或解开、拆开）…的包装","ex":{"en":"Don't unwrap your present until your birthday.","cn":"生日礼物要等到你生日那天再打开。"}}]}},"upturned":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"朝上的；朝上翘的；向上翻的","en":"Something that is upturned points upwards.","ex":{"en":"...the rain splashing down on her upturned face.","cn":"溅落到她仰起的脸上的雨水"}},{"pos":"ADJ 形容词","cn":"翻转的；倒置的","en":"Something that is upturned is upside down.","ex":{"en":"...upturned buckets","cn":"倒扣的水桶"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"pointing or turning upwards","cn":"向上翘的﹔朝上翻的"},{"en":"turned upside down","cn":"翻转的﹐倒置的"}]},"media":{"uk":"media/ldoce/hwd/bre/b/brelasdeupturned.mp3","us":"media/ldoce/hwd/ame/a/upturned.mp3"},"examples":[{"en":"She looked down at the sea of upturned faces.","cn":"她俯视着一大片仰起的脸孔。"},{"en":"She sat on an upturned box.","cn":"她坐在一个倒放的箱子上。"}],"oxford":{"phon":"ˌʌpˈtɜːnd","pos":"adjective","senses":[{"en":"pointing or facing upwards","cn":"向上翘的；面朝上的","ex":{"en":"an upturned nose (= that curves upwards at the end)","cn":"翘鼻子"}},{"en":"turned into a position in which the top part is where the bottom part normally is","cn":"颠倒的；翻转的；倒着的","ex":{"en":"She sat on an upturned box.","cn":"她坐在一个倒放的箱子上。"}}]}},"ufo":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"不明飞行物","en":"A UFO is an object seen in the sky or landing on earth which cannot be identified and which is often believed to be from another planet. UFO is an abbreviation for (缩略=) 'unidentified flying object'.","ex":{"en":"There has been a surge of UFO sightings in America.","cn":"美国不明飞行物目击事件激增。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a strange object in the sky, that some people believe is a spaceship from another world","cn":"不明飞行物"}]},"media":{"uk":"media/ldoce/hwd/bre/7/brelasdeufo.mp3","us":"media/ldoce/hwd/ame/8/ufo.mp3"},"oxford":{"phon":"ˌjuː ef ˈəʊ","pos":"noun","senses":[{"en":"a strange object that some people claim to have seen in the sky and believe is a spacecraft from another planet (the abbreviation for ‘unidentified flying object’)","cn":"不明飞行物（全写为 unidentified flying object）"}]}},"undue":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"过分的；过多的；过度的","en":"If you describe something bad as undue, you mean that it is greater or more extreme than you think is reasonable or appropriate.","ex":{"en":"This would help the families to survive the drought without undue suffering","cn":"这会帮助那些家庭度过干旱期，不至于遭受太多的苦。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"more than is reasonable, suitable, or necessary","cn":"不适当的﹔过度的﹐过分的"}]},"vocab":{"pos":"1 adj 2 adj","senses":[{"en":"When something isn't appropriate or justified, you can describe it as undue . For example, an undue delay in a hospital waiting room can be dangerous for someone with a bad injury."}]},"media":{"uk":"media/ldoce/hwd/bre/c/undo0205.mp3","us":"media/ldoce/hwd/ame/1/undo.mp3"},"examples":[{"en":"We did not want to put any undue pressure on them.","cn":"我们并不想给他们施加过多的压力。"},{"en":"The work should be carried out without undue delay.","cn":"进行这项工作不得有不当的延误。"}],"oxford":{"phon":"ˌʌnˈdjuː","pos":"adjective","senses":[{"en":"more than you think is reasonable or necessary","cn":"不适当的；过分的；过度的","ex":{"en":"They are taking undue advantage of the situation.","cn":"他们过分利用了这种情势。"}}]}},"upper-class":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"belonging to the class of people who originally had most of the money and power, especially families that own a lot of land","cn":""},{"en":"the people who belong to families that own a lot of land, and used to have a lot of power, and have special titles before their names, like 'Lord' or 'Lady' - used especially when you are talking about the past","cn":""},{"en":"having a high position in society that has special, and usually unfair, advantages such as power, money and the best education","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/5/brelasdeupper_class.mp3","us":"media/ldoce/hwd/ame/d/upper_class.mp3"},"oxford":{"phon":"ði ˌʌpə ˈklɑːs","pos":"adjective","senses":[{"en":"belonging to or typical of groups of people that are considered to have the highest social status and that have more money and/or power than other people in society","cn":"上流社会的；上层阶级的","ex":{"en":"Her family is very upper class.","cn":"她家世显赫。"}}]}},"unintelligible":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"难以理解的；晦涩难懂的","en":"Unintelligible language is impossible to understand, for example because it is not written or pronounced clearly, or because its meaning is confused or complicated.","ex":{"en":"He muttered something unintelligible","cn":"他嘴里不知咕哝了几句什么。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"having more than one possible meaning and therefore confusing and unclear","cn":""},{"en":"words or statements that are imprecise are unclear because they do not describe or explain something in an exact way when this is necessary","cn":""},{"en":"unclear, especially because not enough details are given","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Something unintelligible is difficult to understand, either because the room is too noisy or because the unintelligible thing is too quiet or confusing."}]},"collocations":{"phrases":["VERBS be, sound | become","ADV. quite, totally | almost, practically, virtually | largely | mutually mutually unintelligible languages","PREP. to Dolphin sounds are unintelligible to humans."]},"media":{"uk":"media/ldoce/hwd/bre/4/brelasdeunintelligible.mp3","us":"media/ldoce/hwd/ame/e/laadunintelligible.mp3"},"examples":[{"en":"A lot of the jargon they use is unintelligible to outsiders.","cn":"他们所用的大量行话是外人听不懂的。"},{"en":"She turned away and muttered something unintelligible.","cn":"她转向一旁，嘴里不知咕哝些什么。"}],"oxford":{"phon":"ˌʌnɪnˈtelɪdʒəbl","pos":"adjective","senses":[{"en":"impossible to understand","cn":"无法理解的；难懂的","ex":{"en":"She turned away and muttered something unintelligible.","cn":"她转向一旁，嘴里不知咕哝些什么。"}}]}},"ultraviolet":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"紫外的；紫外线的","en":"Ultraviolet light or radiation is what causes your skin to become darker in colour after you have been in sunlight. In large amounts ultraviolet light is harmful.","ex":{"en":"The sun's ultraviolet rays are responsible for both tanning and burning.","cn":"阳光中的紫外线是皮肤晒黑和灼伤的根源。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"ultraviolet light cannot be seen by people, but is responsible for making your skin darker when you are in the sun","cn":"紫外线的"},{"en":"ultraviolet radiation/rays ultraviolet radiation from the sun","cn":"太阳发出的紫外线辐射"}]},"vocab":{"pos":"adj n","senses":[{"en":"Use the adjective ultraviolet to describe light with a wavelength that's less than visible light, but longer than x-rays. You can't see ultraviolet light."}]},"media":{"uk":"media/ldoce/hwd/bre/6/ultraviolet0205.mp3","us":"media/ldoce/hwd/ame/b/ultraviolet.mp3"},"examples":[{"en":"ultraviolet rays (= that cause the skin to go darker)","cn":"紫外线"},{"en":"an ultraviolet lamp","cn":"紫外线灯"}],"oxford":{"phon":"ˌʌltrəˈvaɪələt","pos":"adjective","senses":[{"en":"of or using electromagnetic waves that are just shorter than those of violet light in the spectrum and that cannot be seen","cn":"紫外线的；利用紫外线的","ex":{"en":"ultraviolet rays (= that cause the skin to go darker)","cn":"紫外线"}}]}},"unleash":{"collins":{"senses":[{"pos":"VERB 动词","cn":"释放；放纵…而出","en":"If you say that someone or something unleashes a powerful force, feeling, activity, or group, you mean that they suddenly start it or send it somewhere.","ex":{"en":"Then he unleashed his own, unstoppable, attack","cn":"接着他开始了自己不可阻挡的攻击。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to suddenly let a strong force, feeling etc have its full effect","cn":"突然释放﹐发泄〔力量﹑感情等〕"},{"en":"to let a dog run free after it has been held on a leash","cn":"解皮带放开〔狗〕"}]},"media":{"uk":"media/ldoce/hwd/bre/e/unleash0205.mp3","us":"media/ldoce/hwd/ame/e/unleash.mp3"},"examples":[{"en":"The government's proposals unleashed a storm of protest in the press.","cn":"政府的提案引发了新闻界的抗议浪潮。"},{"en":"Lefèvre’s comments unleashed a wave of protest.","cn":"勒菲弗的评论引发了一波抗议的浪潮。"}],"oxford":{"phon":"ʌnˈliːʃ","pos":"verb","senses":[{"en":"to suddenly let a strong force, emotion, etc. be felt or have an effect","cn":"发泄；突然释放；使爆发","ex":{"en":"The government's proposals unleashed a storm of protest in the press.","cn":"政府的提案引发了新闻界的抗议浪潮。"}}]}},"undying":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"永恒的；不朽的","en":"If you refer to someone's undying feelings, you mean that the feelings are very strong and are unlikely to change.","ex":{"en":"Dianne declared her undying love for Sam","cn":"黛安娜表示她对萨姆的爱永远不会变。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"continuing for ever","cn":"永恒的﹐恒久的"},{"en":"undying love/devotion/support etc They declared their undying love for each other.","cn":"他们宣称永远相爱。"}]},"media":{"uk":"media/ldoce/hwd/bre/5/undying0205.mp3","us":"media/ldoce/hwd/ame/b/undying.mp3"},"examples":[{"en":"undying love","cn":"永恒的爱"}],"oxford":{"phon":"ʌnˈdaɪɪŋ","pos":"adjective","senses":[{"en":"lasting forever","cn":"永恒的；永久的；不朽的","ex":{"en":"undying love","cn":"永恒的爱"}}]}},"unhinged":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"失控的；发狂的","en":"If you describe someone's behaviour or performance as unhinged, you are critical of it because it seems wild and uncontrollable.","ex":{"en":"The phrase 'yeah yeah yeah' can rarely have been delivered with so much unhinged passion.","cn":"“好耶！好耶！好耶！”的呼叫声极少带有如此狂放的激情。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make someone become very upset or mentally ill","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41unhinge.mp3","us":"media/ldoce/hwd/ame/e/unhinge.mp3"},"examples":[{"en":"The terrible experience seemed to have unhinged him slightly.","cn":""}],"oxford":{"phon":"ʌnˈhɪndʒd","pos":"adjective","senses":[{"en":"having a mental illness that makes somebody unable to think or behave normally","cn":"精神失常的；精神错乱的","ex":{"en":"the delusions of an unhinged mind","cn":"精神病患者的妄想"}}]}},"unlisted":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未编入册的；不公开列出的","en":"If a person or their telephone number is unlisted, the number is not listed in the telephone book, and the telephone company will refuse to give it to people who ask for it."},{"pos":"ADJ 形容词","cn":"（公司）未上市的；（股票）场外交易的","en":"An unlisted company or unlisted stock is not listed officially on a stock exchange.","ex":{"en":"Its shares are traded on the Unlisted Securities Market.","cn":"那家公司的股票在场外证券市场交易。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not shown on an official stock exchange list 〔","cn":"证券〕未[非]上市的"},{"en":"not in the list of numbers in the telephone directory 〔","cn":"电话号码〕未登入电话簿的"}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41unlisted.mp3","us":"media/ldoce/hwd/ame/b/unlisted.mp3"},"examples":[{"en":"an unlisted company","cn":"非上市公司"}],"oxford":{"phon":"ˌʌnˈlɪstɪd","pos":"adjective","senses":[{"en":"not on a published list, especially of stock exchange prices","cn":"未列表公布的；（尤指证券）未挂牌的，未上市的","ex":{"en":"an unlisted company","cn":"非上市公司"}},{"en":"not listed in the public phone book or online directory, at the request of the owner of the phone. The phone company will not give unlisted numbers to people who ask for them.","cn":"未列入电话簿的"}]}},"upstage":{"collins":{"senses":[{"pos":"ADV 副词","cn":"在舞台后部；朝舞台后面","en":"When an actor is upstage or moves upstage, he or she is or moves towards the back part of the stage.","ex":{"en":"Upstage and right of centre, Robert Morris stands with his back to the audience","cn":"舞台后方偏右处，罗伯特·莫里斯背对观众站着。"}},{"pos":"VERB 动词","cn":"使相形见绌；抢…的风头","en":"If someone upstages you, they draw attention away from you by being more attractive or interesting.","ex":{"en":"He had a younger brother who always publicly upstaged him","cn":"他有一个弟弟，总是公然抢他的风头。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to do something that takes people’s attention away from someone else who is more important","cn":"抢…的风头﹐抢…的镜头"},{"en":"towards the back of the stage in a theatre","cn":"朝着舞台后方"}]},"vocab":{"pos":"adv v n adj","senses":[{"en":"To upstage is to steal the show. If you try to upstage your \"Grease\" costar, you'll attempt to pull the audience's attention away from him and onto you at the back of the stage doing cartwheels."}]},"media":{"uk":"media/ldoce/hwd/bre/a/upstage_adv0205.mp3","us":"media/ldoce/hwd/ame/b/upstage1.mp3"},"examples":[{"en":"She was furious at being upstaged by her younger sister.","cn":"她被妹妹抢去风头，感到气愤不已。"},{"en":"All the big-name stars were upstaged by 12-year-old Katy Rochford.","cn":"所有的大明星都被12岁的凯蒂·罗奇福德抢去了风头。"}],"oxford":{"phon":"ˌʌpˈsteɪdʒ","pos":"adverb, adjective","senses":[{"en":"at or towards the back of the stage in a theatre","cn":"在（或向）舞台后部（的）"},{"en":"to say or do something that makes people notice you more than the person that they should be interested in","cn":"抢…的镜头；把对…的注意吸引过来","ex":{"en":"She was furious at being upstaged by her younger sister.","cn":"她被妹妹抢去风头，感到气愤不已。"},"pos":"verb"}]}},"untutored":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"非科班出身的；未经正式训练的","en":"If someone is untutored, they have not been formally trained to do something, although they may be quite skilled at it.","ex":{"en":"This untutored mathematician had an obsession with numbers","cn":"这位非科班出身的数学家对数字特别痴迷。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not having been taught to do something","cn":"未受过训练的﹐未经正规教育的"},{"en":"SYN untrained to the untutored eye/ear/mind To the untutored ear, this music sounds as if it might have been written by Beethoven.","cn":"在外行人听来﹐这曲子似乎是贝多芬写的。"}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41untutored.mp3","us":"media/ldoce/hwd/ame/0/ld41untutored.mp3"},"oxford":{"phon":"ˌʌnˈtjuːtəd","pos":"adjective","senses":[{"en":"not having been formally taught about something","cn":"未接受正规教育的；未受过正式训练的","ex":{"en":"To the untutored eye, all these butterflies look the same.","cn":"对于未经训练的人来说，所有这些蝴蝶看起来都一样。"}}]}},"unflattering":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"贬低的；有损形象的","en":"If you describe something as unflattering, you mean that it makes a person or thing seem less attractive than they really are.","ex":{"en":"He depicted the town's respectable families in an unflattering light","cn":"他在描述镇上体面人家时满是贬抑之词。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"making someone look or seem bad or unattractive","cn":"使人显得难看的﹐有损形象的"}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41unflattering.mp3","us":"media/ldoce/hwd/ame/a/laadunflattering.mp3"},"examples":[{"en":"an unflattering dress","cn":"难看的连衣裙"},{"en":"unflattering comments","cn":"贬抑的评论"}],"oxford":{"phon":"ʌnˈflætərɪŋ","pos":"adjective","senses":[{"en":"making somebody/something seem worse or less attractive than they really are","cn":"贬损的；有损形象的；不恭维的","ex":{"en":"an unflattering dress","cn":"难看的连衣裙"}}]}},"unloved":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"未被爱的；缺少爱的","en":"If someone feels unloved, they feel that nobody loves them.","ex":{"en":"I think she feels desperately wounded and unloved at the moment.","cn":"我想她此刻定会觉得受到了极大的伤害，无人关爱。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not loved by someone or anyone","cn":""},{"en":"not loved by anyone","cn":"无人喜爱的﹐没有人爱的"}]},"media":{"uk":"media/ldoce/hwd/bre/f/unloved0205.mp3","us":"media/ldoce/hwd/ame/e/laadunloved.mp3"},"examples":[{"en":"unloved children","cn":"无人疼爱的孩子"}],"oxford":{"phon":"ˌʌnˈlʌvd","pos":"adjective","senses":[{"en":"not loved by anyone","cn":"无人喜欢（或疼爱）的","ex":{"en":"unloved children","cn":"无人疼爱的孩子"}}]}},"undivided":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"专注的；专一的；完全的","en":"If you give someone or something your undivided attention, you concentrate on them fully and do not think about anything else.","ex":{"en":"Eldest children are the only ones to have experienced the undivided attention of their parents","cn":"只有老大得到过父母一心一意的照顾。"}},{"pos":"ADJ 形容词","cn":"（情感）专一的，专心的","en":"Undivided feelings are ones that are very strong and not mixed with other feelings.","ex":{"en":"The paintings she produced in those months won undivided admiration","cn":"她那几个月里创作的画作备受推崇。"}},{"pos":"ADJ 形容词","cn":"（国家或组织）统一的，未分裂的","en":"An undivided country or organization is one that is not separated into smaller parts or groups.","ex":{"en":"Mandela said, 'We want a united, undivided South Africa'.","cn":"曼德拉说道：“我们想要一个团结统一的南非。”"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"to spend your time considering a particular subject, group etc, especially because you think it is more important than others","cn":""},{"en":"to begin to pay attention to someone or something different or new - used especially in written and formal contexts","cn":""},{"en":"to give all your attention to something or someone and not do anything else at the same time","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/7/undivided0205.mp3","us":"media/ldoce/hwd/ame/0/undivided.mp3"},"examples":[{"en":"You must be prepared to give the job your undivided attention.","cn":"你必须准备好全心全意地投入工作。"},{"en":"an undivided Church","cn":"未分立支派的教会"}],"oxford":{"phon":"ˌʌndɪˈvaɪdɪd","pos":"adjective","senses":[{"en":"not split into smaller parts; not divided","cn":"未划分的；未分开的；完整的","ex":{"en":"an undivided Church","cn":"未分立支派的教会"}},{"en":"total; complete; not divided","cn":"完全的；全部的；专注的","g":"[usually before noun]","ex":{"en":"undivided loyalty","cn":"赤胆忠心"}}]}},"undervalue":{"collins":{"senses":[{"pos":"VERB 动词","cn":"低估；轻视；小看","en":"If you undervalue something or someone, you fail to recognize how valuable or important they are.","ex":{"en":"We must never undervalue freedom","cn":"我们决不能低估自由的价值。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to think that someone or something is less important or valuable than they really are","cn":"小看﹐轻视﹔低估"}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41undervalue.mp3","us":"media/ldoce/hwd/ame/f/undervalue.mp3"},"examples":[{"en":"Education is currently undervalued in this country.","cn":"现在这个国家对教育重视不够。"},{"en":"He believes his house has been undervalued.","cn":"他认为自己的房子估值太低。"}],"oxford":{"phon":"ˌʌndəˈvæljuː","pos":"verb","senses":[{"en":"to not recognize how good, valuable or important somebody/something really is","cn":"低估；对…认识不足；轻视","ex":{"en":"Education is currently undervalued in this country.","cn":"现在这个国家对教育重视不够。"}},{"en":"to state that the financial value of something is lower than it really is","cn":"对…估价过低；低估…的价值","ex":{"en":"He believes his house has been undervalued.","cn":"他认为自己的房子估值太低。"}}]}},"unmanned":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"无人驾驶的；无人操纵的","en":"Unmanned vehicles such as spacecraft do not have any people in them and operate automatically or are controlled from a distance.","ex":{"en":"...a special unmanned spacecraft.","cn":"一架特别的无人驾驶飞行器"}},{"pos":"ADJ 形容词","cn":"无人(工作)的","en":"If a place is unmanned, there is nobody working there.","ex":{"en":"The fare from the last unmanned station is probably less than a pound","cn":"从上一个无人站过来的费用可能还不到1镑。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"an unmanned spacecraft does not have a person inside it 〔","cn":"宇宙飞船〕无人驾驶[操纵]的"},{"en":"if a place is unmanned, nobody is working there 〔","cn":"地方〕无人看管的"}]},"media":{"uk":"media/ldoce/hwd/bre/0/unmanned0205.mp3","us":"media/ldoce/hwd/ame/2/unmanned.mp3"},"examples":[{"en":"an unmanned spacecraft","cn":"无人驾驶宇宙飞船"},{"en":"an unmanned Mars mission","cn":"无人火星探测计划"}],"oxford":{"phon":"ˌʌnˈmænd","pos":"adjective","senses":[{"en":"if a machine, a vehicle, a place or an activity is unmanned, it does not have or need a person to control or operate it","cn":"无（需）人操作的；无（需）人控制的；自控的","ex":{"en":"an unmanned spacecraft","cn":"无人驾驶宇宙飞船"}}]}},"unflappable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"冷静的；镇定的","en":"Someone who is unflappable is always calm and never panics or gets upset or angry."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"having the ability to stay calm and not become upset, even in difficult situations","cn":"临危不乱的﹐镇定自若的"}]},"vocab":{"pos":"adj","senses":[{"en":"To be unflappable is to be calm and relaxed, even in a stressful situation. A confident person is usually unflappable ."}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41unflappable.mp3","us":"media/ldoce/hwd/ame/5/unflappable.mp3"},"oxford":{"phon":"ˌʌnˈflæpəbl","pos":"adjective","senses":[{"en":"able to stay calm in a difficult situation","cn":"处变不惊的；镇定的；冷静的"}]}},"unfounded":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"无事实根据的；没有理由的","en":"If you describe a rumour, belief, or feeling as unfounded, you mean that it is wrong and is not based on facts or evidence.","ex":{"en":"There were unfounded rumours of alcohol abuse","cn":"一些毫无根据的酗酒谣言在流传。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"use this to say that there is no reason for someone to think or behave in a particular way","cn":""},{"en":"use this to say that there is no acceptable reason for someone to think or behave in a bad or unfair way. Be no justification is more formal than be no excuse","cn":""},{"en":"groundless fears, suspicions etc that are unnecessary because there are no facts to base them on","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Has someone ever told a complete lie about you? Then what they said was unfounded . There is nothing behind an unfounded statement."}]},"collocations":{"phrases":["VERBS be, prove","ADV. completely, entirely, quite, totally, wholly | not altogether These claims were not altogether unfounded. | largely | manifestly"]},"media":{"uk":"media/ldoce/hwd/bre/a/unfounded0205.mp3","us":"media/ldoce/hwd/ame/d/unfounded.mp3"},"examples":[{"en":"unfounded allegations/rumours, etc.","cn":"缺乏依据的指称、无中生有的谣言等"},{"en":"Speculation about a divorce proved totally unfounded.","cn":"有关离婚的猜测证实纯属无稽之谈。"}],"oxford":{"phon":"ʌnˈfaʊndɪd","pos":"adjective","senses":[{"en":"not based on reason or fact","cn":"莫须有的；无端的；没理由的；不依据事实的","ex":{"en":"unfounded allegations/rumours, etc.","cn":"缺乏依据的指控、无中生有的谣言等"}}]}},"unreserved":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"坦白的；没有隐瞒的","en":"An unreserved opinion or statement is one that expresses a feeling or opinion completely and without any doubts.","ex":{"en":"Charles displays unreserved admiration for his grandfather","cn":"查尔斯从不掩饰他对祖父的景仰。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"completed and without any doubts","cn":"毫无保留的﹐完全的"},{"en":"not booked","cn":"未被预订的"}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld5_unreserved.mp3","us":"media/ldoce/hwd/ame/6/ld5_unreserved.mp3"},"examples":[{"en":"He offered us his unreserved apologies.","cn":"他诚恳地向我们道了歉。"},{"en":"unreserved support for the prime minister","cn":"对首相的全力支持"}],"oxford":{"phon":"ˌʌnrɪˈzɜːvd","pos":"adjective","senses":[{"en":"not paid for in advance; not kept for the use of a particular person","cn":"未被预订的；非保留的","ex":{"en":"Unreserved seats are available one hour before the performance.","cn":"未预订座位在演出前一小时开放。"}},{"en":"complete and without any doubts","cn":"完全的；彻底的；无保留的","lab":"formal","ex":{"en":"He offered us his unreserved apologies.","cn":"他诚恳地向我们道了歉。"}}]}},"unashamed":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"不害羞的；不难为情的；无羞耻心的","en":"If you describe someone's behaviour or attitude as unashamed, you mean that they are open and honest about things that other people might find embarrassing or shocking.","ex":{"en":"I grinned at him in unashamed delight.","cn":"我高兴地朝他笑了笑，一点也不觉得难为情。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who is shameless or whose behaviour is shameless does not seem to feel ashamed about something that most people would be very ashamed about","cn":""},{"en":"not feeling embarrassed or ashamed about something that most people disapprove of or consider silly","cn":""},{"en":"not feeling embarrassed or ashamed about something that people might disapprove of","cn":"不难为情的﹐不知羞耻的"}]},"media":{"uk":"media/ldoce/hwd/bre/d/unashamed0205.mp3","us":"media/ldoce/hwd/ame/2/laadunashamed.mp3"},"examples":[{"en":"She wept unashamedly.","cn":"她不顾羞耻地哭了起来。"},{"en":"an unashamedly sentimental song","cn":"一首夸张的伤感歌曲"}],"oxford":{"phon":"ˌʌnəˈʃeɪmd","pos":"adjective","senses":[{"en":"not feeling ashamed or embarrassed about something, especially when people might expect you to","cn":"不害臊的；不感觉难为情的；恬不知耻的","ex":{"en":"She talked openly about her unashamed love of money.","cn":"她公开谈论了她对金钱的无耻热爱。"}}]}},"unbend":{"collins":{"senses":[{"pos":"VERB 动词","cn":"（人）态度变缓和，变随和","en":"If someone unbends, their attitude becomes less strict than it was.","ex":{"en":"In her dying days the old Queen unbent a little.","cn":"在临死的那些日子里，年迈的女王态度稍缓和了一些。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to relax and start behaving in a less formal way","cn":"放松﹔变得随意"}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41unbend.mp3","us":"media/ldoce/hwd/ame/a/unbend.mp3"},"oxford":{"phon":"ˌʌnˈbend","pos":"verb","senses":[{"en":"to relax and become less strict or formal in your behaviour or attitude","cn":"（在行为或态度上）放松；变得无拘束；随和","g":"[intransitive]","ex":{"en":"He could be fun if he’d unbend a little.","cn":"如果他能稍微放松一点，他会很有趣。"}},{"en":"to make something that was bent become straight; to become straight","cn":"拉直；抻直；变直","g":"[transitive, intransitive]"}]}},"unpunished":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if a criminal gets off , they get little or no official punishment for their crime","cn":""},{"en":"to do something wrong and not be caught or not be punished for it","cn":""},{"en":"to avoid being punished after breaking the law, especially because you cannot be proved guilty","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41unpunished.mp3","us":"media/ldoce/hwd/ame/6/unpunished.mp3"},"examples":[{"en":"He promised that the murder would not go unpunished.","cn":"他保证不会让凶手逍遥法外。"},{"en":"An attack like that cannot go unpunished.","cn":"像那样的袭击行为不能让它逃脱惩罚。"}],"oxford":{"phon":"ʌnˈpʌnɪʃt","pos":"adjective","senses":[{"en":"not punished","cn":"未受惩罚的","ex":{"en":"He promised that the murder would not go unpunished.","cn":"他保证不会让凶手逍遥法外。"}}]}},"unharmed":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"无恙的；完好无损的","en":"If someone or something is unharmed after an accident or violent incident, they are not hurt or damaged in any way.","ex":{"en":"The car was a write-off, but everyone escaped unharmed","cn":"汽车报废了，但是大家都安然脱险。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not harmed or damaged","cn":""},{"en":"safe and not hurt","cn":""},{"en":"not hurt","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/e/brelasdeunharmed.mp3","us":"media/ldoce/hwd/ame/a/laadunharmed.mp3"},"examples":[{"en":"The hostages were released unharmed .","cn":"人质平安获释。"},{"en":"The girl managed to escape unharmed .","cn":"这个女孩得以平安脱险。"}],"oxford":{"phon":"ʌnˈhɑːmd","pos":"adjective","senses":[{"en":"not injured or damaged; not harmed","cn":"未受伤的；未受损害的","ex":{"en":"All eight climbers were rescued unharmed.","cn":"八名登山者全部获救，安然无恙。"}}]}},"usury":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"高利贷；高利盘剥","en":"Usury is the practice of lending money at a high rate of interest."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the practice of lending money to people and making them pay interest 1 (4)","cn":"放高利贷"}]},"vocab":{"pos":"n","senses":[{"en":"Usury means lending money at exorbitant interest rates. Credit-card companies charging annual interest rates of 29% are guilty of usury , as far as I'm concerned."}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41usury.mp3","us":"media/ldoce/hwd/ame/9/usury.mp3"},"examples":[{"en":"In medieval times, it was illegal for Christians to practise usury.","cn":"在中世纪﹐基督徒放高利贷是犯法的。"}],"oxford":{"phon":"ˈjuːʒəri","pos":"noun","senses":[{"en":"the practice of lending money to people at unfairly high rates of interest","cn":"放高利贷；高利盘剥"}]}},"unadulterated":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"未掺杂的;纯的","en":"Something that is unadulterated is completely pure and has had nothing added to it.","ex":{"en":"Organic food is unadulterated food produced without artificial chemicals or pesticides.","cn":"有机食品是未使用人工化学制剂和杀虫剂的纯净食品。"}},{"pos":"ADJ 形容词","cn":"（常用于强调不好的品质）十足的，纯粹的，地道的","en":"You can also use unadulterated to emphasize a particular quality, often a bad quality.","ex":{"en":"It was pure, unadulterated hell.","cn":"那里简直就是个不折不扣的地狱。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not mixed with anything else","cn":""},{"en":"made of gold, silver, wood etc that has not been mixed with any other metal or wood","cn":""},{"en":"if something is 100% beef, 100% cotton etc, it is made only from beef or cotton, and has no other food or material added to it","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Something that's pure, not mixed with other ingredients, is unadulterated . If you stand in your yard every time it rains singing \"Singin' in the Rain\" with unadulterated enthusiasm, your neighbors will eventually call the police."}]},"media":{"uk":"media/ldoce/hwd/bre/2/unadulterated0205.mp3","us":"media/ldoce/hwd/ame/0/unadulterated.mp3"},"examples":[{"en":"For me, the holiday was sheer unadulterated pleasure.","cn":"对我来说，这个假期是百分之百的赏心乐事。"},{"en":"unadulterated foods","cn":"未掺杂其他物质的食物"}],"oxford":{"phon":"ˌʌnəˈdʌltəreɪtɪd","pos":"adjective","senses":[{"en":"you use unadulterated to emphasize that something is complete or total","cn":"完全的；十足的；不折不扣的","g":"[usually before noun]","ex":{"en":"For me, the holiday was sheer unadulterated pleasure.","cn":"对我来说，这个假期是百分之百的赏心乐事。"}},{"en":"not mixed with other substances; not adulterated","cn":"纯的；不掺杂质的","ex":{"en":"unadulterated foods","cn":"未掺杂其他物质的食物"}}]}},"unwitting":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"不知情的；不知不觉的；无意的","en":"If you describe a person or their actions as unwitting, you mean that the person does something or is involved in something without realizing it.","ex":{"en":"We're unwitting victims of the system","cn":"我们都是该系统的不知情的受害者。"}}]},"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"in a way that shows you do not know or realize something","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Use the adjective unwitting to describe someone who doesn't know certain important information, such as unwitting computer users who don't know that an online shopping site is tracking all their activity."}]},"media":{"uk":"media/ldoce/hwd/bre/d/brelasdeunwittingly.mp3","us":"media/ldoce/hwd/ame/9/laadunwittingly.mp3"},"examples":[{"en":"He became an unwitting accomplice in the crime.","cn":"他糊里糊涂地成了犯罪的帮凶。"},{"en":"She was the unwitting cause of the argument.","cn":"她无意中引起了这场争执。"}],"oxford":{"phon":"ʌnˈwɪtɪŋ","pos":"adjective","senses":[{"en":"not aware of what you are doing or of the situation you are involved in","cn":"不知情的；糊里糊涂的；无意的","ex":{"en":"He became an unwitting accomplice in the crime.","cn":"他糊里糊涂地成了犯罪的帮凶。"}}]}},"upbraid":{"collins":{"senses":[{"pos":"VERB 动词","cn":"责难；非难；责骂","en":"If you upbraid someone, you tell them that they have done something wrong and criticize them for doing it.","ex":{"en":"His mother summoned him, upbraided him, wept and prayed","cn":"他母亲把他叫到跟前训斥了一番，又哭哭啼啼地向上帝祷告。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to tell someone angrily that they have done something wrong","cn":"责骂﹐申斥﹐训斥"}]},"vocab":{"pos":"v","senses":[{"en":"No, upbraid isn’t what girls get done at a salon before prom. When you upbraid people, you scold them, tell them off and criticize them. (You could, however, upbraid your stylist after a bad haircut.)"}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld44upbraid.mp3","us":"media/ldoce/hwd/ame/2/ld44upbraid.mp3"},"oxford":{"phon":"ʌpˈbreɪd","pos":"verb","senses":[{"en":"to criticize somebody or speak angrily to them because you do not approve of something that they have said or done","cn":"申斥；训斥；责骂"}]}},"unsung":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"被埋没的；未受颂扬的","en":"Unsung is used to describe people, things, or places that are not appreciated or praised, although you think they deserve to be.","ex":{"en":"They are among the unsung heroes of our time","cn":"他们是我们这个时代的无名英雄。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not praised or famous for something you have done, although you deserve to be 〔","cn":"应该但〕未受到赞颂的"}]},"media":{"uk":"media/ldoce/hwd/bre/9/brelasdeunsung.mp3","us":"media/ldoce/hwd/ame/1/unsung.mp3"},"examples":[{"en":"the unsung heroes of the war","cn":"战争中的无名英雄"},{"en":"one of the unsung heroes of French politics","cn":"法国政坛的一位无名英雄"}],"oxford":{"phon":"ˌʌnˈsʌŋ","pos":"adjective","senses":[{"en":"not praised or famous but deserving to be","cn":"被埋没的；未被颂扬的","ex":{"en":"the unsung heroes of the war","cn":"战争中的无名英雄"}}]}},"unorthodox":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"非正统的；非传统的；不同寻常的","en":"If you describe someone's behaviour, beliefs, or customs as unorthodox, you mean that they are different from what is generally accepted.","ex":{"en":"She spent an unorthodox girlhood travelling with her father throughout Europe","cn":"她童年的经历不同寻常，其间她和父亲游遍了欧洲。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"非法的；非惯常的","en":"If you describe ways of doing things as unorthodox, you are criticizing them because they are unusual or illegal.","ex":{"en":"The charity says the journalists appear to have obtained confidential documents in an unorthodox manner.","cn":"慈善机构称那些记者似乎以非正常手段取得了秘密文件。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"behaving in a way that seems rather strange but not frightening","cn":""},{"en":"very different from the way people usually behave, think, dress etc, often in a way that seems interesting","cn":""},{"en":"unorthodox ideas or methods are different from the usual ones, and therefore seem surprising to many people","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Unorthodox describes something that goes against the usual ways of doing things. Instead of describing yourself as a terrible speller, you might instead proudly refer to your spelling as unorthodox ."}]},"collocations":{"phrases":["VERBS be, seem, sound | become","ADV. highly, very a highly unorthodox teaching style | a little, quite, rather, slightly, somewhat"]},"media":{"uk":"media/ldoce/hwd/bre/2/unorthodox0205.mp3","us":"media/ldoce/hwd/ame/2/unorthodox.mp3"},"examples":[{"en":"unorthodox methods","cn":"非正统的方法"}],"oxford":{"phon":"ʌnˈɔːθədɒks","pos":"adjective","senses":[{"en":"different from what is usual or accepted","cn":"非正统的；非传统的；不正规的","ex":{"en":"unorthodox methods","cn":"非正统的方法"}}]}},"undefined":{"vocab":{"pos":"adj","senses":[{"en":"If something is undefined it's not clear, such as your undefined vacation plans. You know you want to go somewhere during the third week of August, but you just don't know where."}]},"examples":[{"en":"The money was lent for an undefined period of time.","cn":"这笔钱无限期借出。"}],"oxford":{"phon":"ˌʌndɪˈfaɪnd","pos":"adjective","senses":[{"en":"not made clear or definite","cn":"未阐明的；未限定的","ex":{"en":"The money was lent for an undefined period of time.","cn":"这笔钱无限期借出。"}}]}}});
